/// E-process anomaly detection defaults. These control the statistical test
/// that monitors transaction and query behavior for anomalies:
/// - `p0` (0.1): base rate hypothesis for the e-process betting strategy
/// - `lambda` (3.0): exponential mixture weight — higher = more aggressive
/// - `alpha` (0.05): false positive rate target (5%)
/// - `max_evalue` (1e12): numerical clamp to prevent f64 overflow
///
/// A future `PRAGMA fsqlite.eprocess_*` family could expose these to users
/// with workload-specific anomaly profiles.
const EPROCESS_DEFAULT_CONFIG: EProcessConfig = EProcessConfig {
    p0: 0.1,
    lambda: 3.0,
    alpha: 0.05,
    max_evalue: 1e12,
};
const EPROCESS_PRIORITY_THRESHOLD: u8 = 1;

// Keep BEGIN/open retry cooperative under cross-process contention. A tiny
// spin preserves the same-process handoff fast path; the bounded sleep keeps
// busy_timeout from monopolizing the CPU and starving the lock holder.
const BEGIN_BUSY_HANDOFF_BASE_SPINS: u32 = 64;
const BEGIN_BUSY_HANDOFF_MAX_SPINS: u32 = 2_048;
const BEGIN_BUSY_HANDOFF_BASE_SLEEP_US: u64 = 1_000;
const BEGIN_BUSY_HANDOFF_MAX_SLEEP_US: u64 = 50_000;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct BeginBusyRetryWait {
    attempt: u32,
    spin_loops: u32,
    sleep_for: Duration,
}

#[derive(Debug, Clone, Copy, Default)]
struct BeginBusyRetryHandoff {
    next_attempt: u32,
}

impl BeginBusyRetryHandoff {
    fn next_wait(&mut self, started: Instant, deadline: Duration) -> Option<BeginBusyRetryWait> {
        if deadline.is_zero() || started.elapsed() >= deadline {
            return None;
        }

        let attempt = self.next_attempt.saturating_add(1);
        self.next_attempt = attempt;
        let remaining = deadline
            .checked_sub(started.elapsed())
            .unwrap_or(Duration::ZERO);
        let sleep_for = begin_busy_retry_sleep(attempt).min(remaining);
        Some(BeginBusyRetryWait {
            attempt,
            spin_loops: begin_busy_retry_spin_loops(attempt),
            sleep_for,
        })
    }
}

const fn begin_busy_retry_spin_loops(attempt: u32) -> u32 {
    let growth = attempt.saturating_sub(1);
    let shift = if growth > 5 { 5 } else { growth };
    let spins = BEGIN_BUSY_HANDOFF_BASE_SPINS << shift;
    if spins > BEGIN_BUSY_HANDOFF_MAX_SPINS {
        BEGIN_BUSY_HANDOFF_MAX_SPINS
    } else {
        spins
    }
}

fn page_size_from_pragma_state(page_size_bytes: u32) -> Result<PageSize> {
    PageSize::new(page_size_bytes).ok_or_else(|| {
        FrankenError::Internal(format!(
            "pragma state contains invalid page size: {page_size_bytes}"
        ))
    })
}

fn default_statement_cache_capacity() -> NonZeroUsize {
    match NonZeroUsize::new(256) {
        Some(capacity) => capacity,
        None => NonZeroUsize::MIN,
    }
}

#[cfg(not(test))]
fn thread_parse_cache_capacity() -> NonZeroUsize {
    match NonZeroUsize::new(512) {
        Some(capacity) => capacity,
        None => NonZeroUsize::MIN,
    }
}

const fn begin_busy_retry_sleep_micros(attempt: u32) -> u64 {
    let growth = attempt.saturating_sub(1);
    let shift = if growth > 6 { 6 } else { growth };
    let micros = BEGIN_BUSY_HANDOFF_BASE_SLEEP_US << shift;
    if micros > BEGIN_BUSY_HANDOFF_MAX_SLEEP_US {
        BEGIN_BUSY_HANDOFF_MAX_SLEEP_US
    } else {
        micros
    }
}

fn begin_busy_retry_sleep(attempt: u32) -> Duration {
    Duration::from_micros(begin_busy_retry_sleep_micros(attempt))
}

fn perform_begin_busy_retry_handoff(wait: BeginBusyRetryWait) {
    for _ in 0..wait.spin_loops {
        std::hint::spin_loop();
    }

    #[cfg(not(target_arch = "wasm32"))]
    if !wait.sleep_for.is_zero() {
        std::thread::sleep(wait.sleep_for);
    }
}

fn retry_busy_connection_bootstrap<T>(mut operation: impl FnMut() -> Result<T>) -> Result<T> {
    let mut err = match operation() {
        Ok(value) => return Ok(value),
        Err(err @ (FrankenError::Busy | FrankenError::BusyRecovery)) => err,
        Err(err) => return Err(err),
    };

    let busy_timeout_ms = fsqlite_vdbe::pragma::ConnectionPragmaState::default()
        .busy_timeout_ms
        .max(0) as u64;
    let deadline = Duration::from_millis(busy_timeout_ms);
    let started = Instant::now();
    let mut handoff = BeginBusyRetryHandoff::default();

    while let Some(wait) = handoff.next_wait(started, deadline) {
        perform_begin_busy_retry_handoff(wait);
        match operation() {
            Ok(value) => return Ok(value),
            Err(next_err @ (FrankenError::Busy | FrankenError::BusyRecovery)) => {
                err = next_err;
            }
            Err(next_err) => return Err(next_err),
        }
    }

    Err(err)
}

/// Maximum trigger recursion depth (F-PGM.11).
///
/// SQLite defines `SQLITE_MAX_TRIGGER_DEPTH = 1000`, but each Rust recursion
/// level consumes significantly more stack space than C (~20-40 KiB per level
/// including VDBE dispatch + expression evaluation). Keep at least a 2x margin
/// below the observed 2 MiB test-thread stack boundary: compiler changes can
/// grow these frames, and the limit must fire before the process aborts. The
/// regression test exercises this boundary on an explicit 1 MiB stack.
const MAX_TRIGGER_DEPTH: usize = 8;

/// Maximum depth for FK CASCADE propagation.
///
/// Multi-level cascades (e.g., grandparent -> parent -> child) require
/// recursive FK enforcement.  This limit prevents infinite recursion from
/// self-referencing or circular FK chains.  SQLite uses
/// `SQLITE_MAX_TRIGGER_DEPTH` for the same purpose; we use a separate
/// bound because FK cascades run through `execute_statement`, not the
/// trigger machinery.
const MAX_FK_CASCADE_DEPTH: usize = 50;

static FSQLITE_HOT_PATH_PROFILE_ENABLED: AtomicBool = AtomicBool::new(false);
#[cfg(test)]
thread_local! {
    // Thread-local override for hot-path profiling. When `Some(true)`, profiling
    // is enabled only on the current thread; when `Some(false)`, disabled only on
    // the current thread; when `None`, the global flag is used. This prevents a
    // test-only profile guard from accidentally enabling profiling for concurrent
    // threads in the same process.
    static FSQLITE_HOT_PATH_PROFILE_THREAD_OVERRIDE: std::cell::Cell<Option<bool>> =
        const { std::cell::Cell::new(None) };

}

thread_local! {
    // bd-5310l benchmark knob: force the defensive schema deep-clone in `compile_table_select`
    // even when the borrow fast path would apply, so an A/B harness can measure the clone cost
    // (clone arm vs borrow arm) within a single build. Off by default; zero cost when off.
    static FSQLITE_FORCE_SCHEMA_CLONE_BENCH: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };

    // bd-5310l: set while `compile_with_cache` is fronting a compile (i.e. the compiled-PROGRAM
    // cache is already keying this SQL). On this path the separate planner-directive cache is
    // redundant, so `compile_table_select` bypasses it and computes the directive directly (saving
    // the `to_string` cache-key derivation + lookup + insert). Direct callers of
    // `compile_table_select` (join/subquery/view paths, unit tests) do NOT set this, so they keep the
    // planner cache. Save/restore semantics handle the reentrant sqlite_stat1 self.query().
    static FSQLITE_PROGRAM_CACHE_FRONTED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };

    // bd-5310l benchmark knob: force the planner-directive cache path even when fronted, so the A/B
    // harness can measure bypass vs cache within one build. Off by default; zero cost when off.
    static FSQLITE_FORCE_PLANNER_CACHE_BENCH: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Force the per-compile schema deep-clone path on the current thread (bd-5310l bench A/B only).
///
/// When `true`, `compile_table_select` always clones the schema instead of taking the borrow fast
/// path, so the clone cost can be measured against the fast path in one process.
pub fn set_force_schema_clone_bench(enabled: bool) {
    FSQLITE_FORCE_SCHEMA_CLONE_BENCH.with(|c| c.set(enabled));
}

/// Force the planner-directive cache path even when fronted (bd-5310l bench A/B only).
///
/// When `true`, `compile_table_select` uses the planner-directive cache instead of the direct
/// bypass, so the bypass win can be measured against the cache path in one process.
pub fn set_force_planner_cache_bench(enabled: bool) {
    FSQLITE_FORCE_PLANNER_CACHE_BENCH.with(|c| c.set(enabled));
}

/// RAII guard that marks the current thread as inside a `compile_with_cache` (program-cache-fronted)
/// compile, restoring the previous value on drop so reentrant compiles (e.g. the `sqlite_stat1`
/// query) nest correctly.
struct ProgramCacheFrontedGuard(bool);
impl ProgramCacheFrontedGuard {
    fn enter() -> Self {
        let prev = FSQLITE_PROGRAM_CACHE_FRONTED.with(|c| c.replace(true));
        Self(prev)
    }
}
impl Drop for ProgramCacheFrontedGuard {
    fn drop(&mut self) {
        FSQLITE_PROGRAM_CACHE_FRONTED.with(|c| c.set(self.0));
    }
}

/// Test-only hook fired inside `execute_commit_with_cx` for a concurrent commit,
/// at the precise point AFTER the physical pager write has landed but BEFORE the
/// commit is published into the shared `CommitIndex`. This is the exact
/// validate→write→publish window that issue #115 identifies as the
/// double-allocation TOCTOU. A deterministic test installs a callback here to
/// force a second connection to validate inside this window; production builds
/// never compile this hook so it has zero runtime cost off the test path.
#[cfg(test)]
static FSQLITE_CONCURRENT_COMMIT_WINDOW_HOOK: Mutex<Option<Arc<dyn Fn() + Send + Sync + 'static>>> =
    Mutex::new(None);

#[cfg(test)]
fn set_concurrent_commit_window_hook(hook: Option<Arc<dyn Fn() + Send + Sync + 'static>>) {
    *FSQLITE_CONCURRENT_COMMIT_WINDOW_HOOK
        .lock()
        .expect("commit-window hook mutex poisoned") = hook;
}

#[cfg(test)]
#[inline]
fn fire_concurrent_commit_window_hook() {
    let hook = {
        FSQLITE_CONCURRENT_COMMIT_WINDOW_HOOK
            .lock()
            .expect("commit-window hook mutex poisoned")
            .clone()
    };
    if let Some(hook) = hook {
        hook();
    }
}

