fn statement_reuse_log_context_from_env() -> (String, String) {
    let run_id = std::env::var("RUN_ID").unwrap_or_else(|_| "(none)".to_owned());
    let scenario_id = std::env::var("SCENARIO_ID").unwrap_or_else(|_| "(none)".to_owned());
    (run_id, scenario_id)
}

const STATEMENT_REUSE_TRACE_CAPACITY: usize = 1_024;

#[derive(Debug, Clone, PartialEq, Eq)]
struct StatementReuseLaneContext {
    worker_id: String,
    node_id: String,
}

impl StatementReuseLaneContext {
    fn from_runtime() -> Self {
        let worker_id = std::env::var("WORKER_ID")
            .or_else(|_| std::env::var("FSQLITE_WORKER_ID"))
            .unwrap_or_else(|_| {
                let thread = std::thread::current();
                thread
                    .name()
                    .map_or_else(|| format!("{:?}", thread.id()), |name| name.to_owned())
            });
        let node_id = std::env::var("NODE_ID")
            .or_else(|_| std::env::var("FSQLITE_NODE_ID"))
            .or_else(|_| std::env::var("HOSTNAME"))
            .unwrap_or_else(|_| "(local)".to_owned());
        Self { worker_id, node_id }
    }
}

#[cfg(test)]
thread_local! {
    static FSQLITE_STATEMENT_REUSE_LANE_CONTEXT_OVERRIDE:
        std::cell::RefCell<Option<StatementReuseLaneContext>> =
            const { std::cell::RefCell::new(None) };
}

fn statement_reuse_lane_context() -> StatementReuseLaneContext {
    #[cfg(test)]
    {
        if let Some(override_ctx) =
            FSQLITE_STATEMENT_REUSE_LANE_CONTEXT_OVERRIDE.with(|slot| slot.borrow().clone())
        {
            return override_ctx;
        }
    }

    StatementReuseLaneContext::from_runtime()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StatementReuseLaneLocality {
    FirstObservation,
    SameLane,
    CrossLane,
    CrossNode,
}

impl StatementReuseLaneLocality {
    const fn as_str(self) -> &'static str {
        match self {
            Self::FirstObservation => "first_observation",
            Self::SameLane => "same_lane",
            Self::CrossLane => "cross_lane",
            Self::CrossNode => "cross_node",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct StatementReuseTraceKey {
    cache_kind: &'static str,
    statement_fingerprint: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StatementReuseLastSeen {
    cache_sequence: u64,
    worker_id: String,
    node_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StatementReuseTraceEntry {
    cache_kind: &'static str,
    statement_fingerprint: String,
    cache_sequence: u64,
    cache_hit: bool,
    reuse_distance: Option<u64>,
    lane_locality: StatementReuseLaneLocality,
    worker_id: String,
    node_id: String,
    previous_worker_id: Option<String>,
    previous_node_id: Option<String>,
}

#[derive(Debug, Default)]
struct StatementReuseTraceState {
    next_sequence_by_cache_kind: HashMap<&'static str, u64>,
    last_seen: HashMap<StatementReuseTraceKey, StatementReuseLastSeen>,
    recent: VecDeque<StatementReuseTraceEntry>,
}

impl StatementReuseTraceState {
    #[cfg(test)]
    fn clear(&mut self) {
        self.next_sequence_by_cache_kind.clear();
        self.last_seen.clear();
        self.recent.clear();
    }

    fn record(
        &mut self,
        cache_kind: &'static str,
        statement_fingerprint: &str,
        cache_hit: bool,
        lane: StatementReuseLaneContext,
    ) -> StatementReuseTraceEntry {
        let cache_sequence_entry = self
            .next_sequence_by_cache_kind
            .entry(cache_kind)
            .or_default();
        *cache_sequence_entry = (*cache_sequence_entry).saturating_add(1);
        let cache_sequence = *cache_sequence_entry;
        let trace_key = StatementReuseTraceKey {
            cache_kind,
            statement_fingerprint: statement_fingerprint.to_owned(),
        };
        let previous = self.last_seen.insert(
            trace_key,
            StatementReuseLastSeen {
                cache_sequence,
                worker_id: lane.worker_id.clone(),
                node_id: lane.node_id.clone(),
            },
        );

        let (reuse_distance, lane_locality, previous_worker_id, previous_node_id) =
            if let Some(previous) = previous {
                let lane_locality = if previous.node_id != lane.node_id {
                    StatementReuseLaneLocality::CrossNode
                } else if previous.worker_id != lane.worker_id {
                    StatementReuseLaneLocality::CrossLane
                } else {
                    StatementReuseLaneLocality::SameLane
                };
                (
                    Some(
                        cache_sequence
                            .saturating_sub(previous.cache_sequence)
                            .saturating_sub(1),
                    ),
                    lane_locality,
                    Some(previous.worker_id),
                    Some(previous.node_id),
                )
            } else {
                (
                    None,
                    StatementReuseLaneLocality::FirstObservation,
                    None,
                    None,
                )
            };

        let entry = StatementReuseTraceEntry {
            cache_kind,
            statement_fingerprint: statement_fingerprint.to_owned(),
            cache_sequence,
            cache_hit,
            reuse_distance,
            lane_locality,
            worker_id: lane.worker_id,
            node_id: lane.node_id,
            previous_worker_id,
            previous_node_id,
        };

        if self.recent.len() == STATEMENT_REUSE_TRACE_CAPACITY {
            self.recent.pop_front();
        }
        self.recent.push_back(entry.clone());

        // bd-db300.6.1.1: Update hot-path profile counters for compile-governance decisions.
        if hot_path_profile_enabled() {
            FSQLITE_STATEMENT_GLOBAL_SEQ.fetch_add(1, AtomicOrdering::Relaxed);
            if let Some(distance) = reuse_distance {
                FSQLITE_STATEMENT_REUSE_COUNT.fetch_add(1, AtomicOrdering::Relaxed);
                FSQLITE_STATEMENT_REUSE_DISTANCE_SUM.fetch_add(distance, AtomicOrdering::Relaxed);
                // Update max reuse distance using CAS loop.
                let mut current_max =
                    FSQLITE_STATEMENT_MAX_REUSE_DISTANCE.load(AtomicOrdering::Relaxed);
                while distance > current_max {
                    match FSQLITE_STATEMENT_MAX_REUSE_DISTANCE.compare_exchange_weak(
                        current_max,
                        distance,
                        AtomicOrdering::Relaxed,
                        AtomicOrdering::Relaxed,
                    ) {
                        Ok(_) => break,
                        Err(v) => current_max = v,
                    }
                }
                match lane_locality {
                    StatementReuseLaneLocality::SameLane => {
                        FSQLITE_STATEMENT_LANE_LOCAL_REUSES.fetch_add(1, AtomicOrdering::Relaxed);
                    }
                    StatementReuseLaneLocality::CrossLane
                    | StatementReuseLaneLocality::CrossNode => {
                        FSQLITE_STATEMENT_CROSS_LANE_REUSES.fetch_add(1, AtomicOrdering::Relaxed);
                    }
                    StatementReuseLaneLocality::FirstObservation => {
                        // Not a reuse - first time seeing this statement.
                    }
                }
            }
        }

        entry
    }
}

fn format_schema_identity(cookie: u32, generation: u64) -> String {
    format!("cookie={cookie};generation={generation}")
}

fn is_hidden_rowid_alias_name(name: &str) -> bool {
    name.eq_ignore_ascii_case("rowid")
        || name.eq_ignore_ascii_case("_rowid_")
        || name.eq_ignore_ascii_case("oid")
}

/// I/O polling strategy for the shared runtime context.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IoPollStrategy {
    /// Let FrankenSQLite choose the platform default.
    Auto,
    /// Use a conservative blocking strategy.
    Blocking,
}

/// Selects the commit-path safety regime.
///
/// `Safe` (the default) always runs the full Cahill/Fekete SSI
/// validation for every `BEGIN CONCURRENT` commit. `LabUnsafe`
/// activates research-grade optimisations — currently the
/// [`SsiEProcessGate`] skip-path — that trade a bounded-probability
/// increase in potentially-missed SSI conflicts for commit-path
/// throughput. `LabUnsafe` is configured via
/// `PRAGMA fsqlite.write_merge = LAB_UNSAFE` and emits a startup
/// warning the first time it is activated on a connection.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum WriteMergeMode {
    /// Full SSI every commit. This is the only production-safe mode.
    #[default]
    Safe,
    /// Research-grade skip path gated by an anytime-valid e-process.
    /// See `SsiEProcessGate` in `fsqlite-mvcc` for the mathematical
    /// form and safety argument.
    LabUnsafe,
}

impl WriteMergeMode {
    fn as_label(self) -> &'static str {
        match self {
            Self::Safe => "SAFE",
            Self::LabUnsafe => "LAB_UNSAFE",
        }
    }
}

/// Configuration for the process-global runtime context.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeConfig {
    /// Preferred worker-thread count for background services.
    pub worker_threads: usize,
    /// I/O polling strategy to prefer for background services.
    pub io_poll_strategy: IoPollStrategy,
}

impl Default for RuntimeConfig {
    fn default() -> Self {
        Self {
            worker_threads: crate::available_parallelism_or_one(),
            io_poll_strategy: IoPollStrategy::Auto,
        }
    }
}

/// Process-global runtime handle shared by all database regions.
pub struct RuntimeContext {
    runtime_id: u64,
    config: RuntimeConfig,
    root_cx: Cx,
    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    native_runtime_handle: Option<asupersync::runtime::RuntimeHandle>,
}

impl std::fmt::Debug for RuntimeContext {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut debug = f.debug_struct("RuntimeContext");
        debug
            .field("runtime_id", &self.runtime_id)
            .field("config", &self.config)
            .field("root_cx", &self.root_cx);
        #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
        debug.field(
            "has_native_runtime_handle",
            &self.native_runtime_handle.is_some(),
        );
        debug.finish()
    }
}

impl RuntimeContext {
    fn detached_root_cx() -> Cx {
        Cx::new().with_trace_context(next_trace_id(), 0, 0)
    }

    fn derived_root_cx(parent: &Cx) -> Cx {
        parent
            .create_child()
            .with_trace_context(next_trace_id(), 0, 0)
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    fn current_native_runtime_handle() -> Option<asupersync::runtime::RuntimeHandle> {
        asupersync::runtime::Runtime::current_handle()
    }

    /// Create a runtime context with the provided configuration.
    ///
    /// This constructor always creates a cancellation-detached FrankenSQLite
    /// root `Cx`, even when invoked from within an active asupersync task.
    /// Call [`Self::new_with_root_cx`] when the caller already owns the
    /// canonical parent `Cx` and wants explicit capability lineage.
    #[must_use]
    pub fn new(config: RuntimeConfig) -> Self {
        Self {
            runtime_id: NEXT_RUNTIME_ID.fetch_add(1, AtomicOrdering::Relaxed),
            config,
            root_cx: Self::detached_root_cx(),
            #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
            native_runtime_handle: Self::current_native_runtime_handle(),
        }
    }

    /// Create a fully process-global-safe runtime context.
    ///
    /// Like [`Self::new`] this mints a cancellation-detached root `Cx`, but it
    /// also refuses to capture any ambient asupersync runtime handle. The
    /// process-global runtime (installed via [`init_global_runtime`] or
    /// lazily by [`Self::global`]) outlives any short-lived `block_on`/request
    /// scope it happens to be created inside, so binding it to that scope's
    /// runtime handle would (a) let it spawn the write-coordinator service on a
    /// runtime that is about to be dropped and (b) leak that ambient capture
    /// into every later `Connection::open` that resolves the global runtime —
    /// pollution that is observable as spurious active write-coordinator tasks.
    /// Both effects are forbidden for the canonical detached process root.
    #[must_use]
    fn new_process_global(config: RuntimeConfig) -> Self {
        Self {
            runtime_id: NEXT_RUNTIME_ID.fetch_add(1, AtomicOrdering::Relaxed),
            config,
            root_cx: Self::detached_root_cx(),
            #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
            native_runtime_handle: None,
        }
    }

    /// Create a runtime context rooted in a caller-supplied parent `Cx`.
    ///
    /// This keeps capability lineage attached to the caller's budget,
    /// cancellation state, and native asupersync context instead of minting
    /// a disconnected root inside FrankenSQLite.
    #[must_use]
    pub fn new_with_root_cx(config: RuntimeConfig, root_cx: &Cx) -> Self {
        Self {
            runtime_id: NEXT_RUNTIME_ID.fetch_add(1, AtomicOrdering::Relaxed),
            config,
            root_cx: Self::derived_root_cx(root_cx),
            #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
            native_runtime_handle: Self::current_native_runtime_handle(),
        }
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    fn native_runtime_handle(&self) -> Option<asupersync::runtime::RuntimeHandle> {
        self.native_runtime_handle.clone()
    }

    /// Return the stable runtime identity used to isolate per-database state.
    #[must_use]
    pub const fn runtime_id(&self) -> u64 {
        self.runtime_id
    }

    /// Access the runtime configuration.
    #[must_use]
    pub const fn config(&self) -> &RuntimeConfig {
        &self.config
    }

    /// Return the active process-global runtime context.
    #[must_use]
    pub fn global() -> Arc<Self> {
        global_runtime_context()
    }
}

impl Default for RuntimeContext {
    fn default() -> Self {
        Self::new(RuntimeConfig::default())
    }
}

static GLOBAL_RUNTIME_CONTEXT: OnceLock<Mutex<Option<Arc<RuntimeContext>>>> = OnceLock::new();
static NEXT_RUNTIME_ID: AtomicU64 = AtomicU64::new(1);

fn global_runtime_context() -> Arc<RuntimeContext> {
    let slot = GLOBAL_RUNTIME_CONTEXT.get_or_init(|| Mutex::new(None));
    let mut guard = lock_unpoisoned(slot);
    Arc::clone(guard.get_or_insert_with(|| {
        Arc::new(RuntimeContext::new_process_global(RuntimeConfig::default()))
    }))
}

/// Install or replace the process-global runtime context used by `Connection::open`.
#[must_use]
pub fn init_global_runtime(config: RuntimeConfig) -> Arc<RuntimeContext> {
    let runtime = Arc::new(RuntimeContext::new_process_global(config));
    let slot = GLOBAL_RUNTIME_CONTEXT.get_or_init(|| Mutex::new(None));
    *lock_unpoisoned(slot) = Some(Arc::clone(&runtime));
    runtime
}

/// Connection-scoped environment for selecting the runtime context and
/// tuning resource limits.
///
/// # Page buffer pool sizing
///
/// By default the page-buffer pool is sized via the `FSQLITE_PAGE_BUFFER_MAX`
/// environment variable (if set), otherwise
/// [`DEFAULT_PAGE_BUFFER_MAX`](fsqlite_pager::DEFAULT_PAGE_BUFFER_MAX)
/// (262 144 buffers ≈ 1 GiB at 4 KiB pages).
///
/// To override programmatically, call
/// [`set_page_buffer_max`](Self::set_page_buffer_max) before opening a
/// connection:
///
/// ```ignore
/// let mut env = ConnectionEnv::default();
/// env.set_page_buffer_max(524_288); // 2 GiB at 4 KiB pages
/// let conn = Connection::open_with_env("big.db", env)?;
/// ```
#[derive(Debug, Clone)]
pub struct ConnectionEnv {
    runtime: Arc<RuntimeContext>,
    /// Explicit page-buffer-pool ceiling override. `None` defers to the
    /// `FSQLITE_PAGE_BUFFER_MAX` env var / [`DEFAULT_PAGE_BUFFER_MAX`].
    page_buffer_max: Option<usize>,
    /// Explicit MemoryVfs growth policy for `:memory:` / imported in-memory databases.
    memory_vfs_config: Option<MemoryVfsConfig>,
    /// Strict multi-process mode. When enabled, the connection refuses
    /// to silently proceed past ambiguous concurrency states (open-time
    /// freelist drift, F_SETLK timeout, WAL checkpoint contention).
    /// Default off — preserves the existing best-effort behavior for
    /// single-process callers. See frankensqlite#81. Opting in
    /// converts otherwise-silent corruption symptoms into actionable
    /// `FrankenError::MultiProcessContractViolation` errors.
    strict_multi_process: bool,
}

impl ConnectionEnv {
    /// Create a connection environment from an explicit runtime context.
    #[must_use]
    pub fn new(runtime: Arc<RuntimeContext>) -> Self {
        Self {
            runtime,
            page_buffer_max: None,
            memory_vfs_config: None,
            strict_multi_process: false,
        }
    }

    /// Enable strict multi-process mode for this connection env. With
    /// strict mode on, the connection refuses to silently proceed past
    /// concurrency contract violations (F_SETLK timeout, freelist
    /// trunk page past db_size, WAL checkpoint contention at open) and
    /// returns `FrankenError::MultiProcessContractViolation` instead.
    /// See frankensqlite#81.
    pub fn set_strict_multi_process(&mut self, strict: bool) {
        self.strict_multi_process = strict;
    }

    /// Returns whether strict multi-process refusal is enabled. See
    /// frankensqlite#81.
    #[must_use]
    pub fn strict_multi_process(&self) -> bool {
        self.strict_multi_process
    }

    /// Access the runtime context that will back newly opened connections.
    #[must_use]
    pub fn runtime(&self) -> &Arc<RuntimeContext> {
        &self.runtime
    }

    /// Override the maximum number of page buffers the pager's buffer pool
    /// will allocate.
    ///
    /// At the standard 4 KiB page size, each buffer consumes ~4 KiB, so
    /// `262_144` ≈ 1 GiB and `524_288` ≈ 2 GiB.
    ///
    /// Pass `None` to revert to the default resolution (env var, then
    /// compile-time default).
    pub fn set_page_buffer_max(&mut self, max_buffers: impl Into<Option<usize>>) {
        self.page_buffer_max = max_buffers.into();
    }

    /// Returns the explicit page-buffer-pool ceiling, if one has been set.
    #[must_use]
    pub fn page_buffer_max(&self) -> Option<usize> {
        self.page_buffer_max
    }

    /// Override the MemoryVfs growth policy used for `:memory:` databases and
    /// imported SQLite images.
    ///
    /// File-backed connections ignore this setting.
    pub fn set_memory_vfs_config(&mut self, config: impl Into<Option<MemoryVfsConfig>>) {
        self.memory_vfs_config = config.into();
    }

    /// Returns the explicit MemoryVfs configuration, if one has been set.
    #[must_use]
    pub fn memory_vfs_config(&self) -> Option<MemoryVfsConfig> {
        self.memory_vfs_config
    }
}

impl Default for ConnectionEnv {
    fn default() -> Self {
        Self {
            runtime: RuntimeContext::global(),
            page_buffer_max: None,
            memory_vfs_config: None,
            strict_multi_process: false,
        }
    }
}

/// Point-in-time memory diagnostics for a live connection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ConnectionMemoryStats {
    /// Database page size used by the active pager backend.
    pub page_size_bytes: usize,
    /// Current page-cache metrics snapshot.
    pub page_cache: PageCacheMetricsSnapshot,
    /// MemoryVfs usage snapshot for `:memory:` databases, when available.
    pub memory_vfs: Option<MemoryVfsUsageSnapshot>,
}

impl ConnectionMemoryStats {
    /// Resident page-cache bytes (`cached_pages * page_size_bytes`).
    #[must_use]
    pub const fn page_cache_used_bytes(self) -> usize {
        self.page_cache
            .cached_pages
            .saturating_mul(self.page_size_bytes)
    }

    /// Page-cache capacity bytes (`pool_capacity * page_size_bytes`).
    #[must_use]
    pub const fn page_cache_capacity_bytes(self) -> usize {
        self.page_cache
            .pool_capacity
            .saturating_mul(self.page_size_bytes)
    }

    /// Estimated currently allocated bytes tracked by FrankenSQLite.
    ///
    /// This combines MemoryVfs reserved bytes (actual heap capacity) with the
    /// resident page-cache footprint.
    #[must_use]
    pub fn estimated_used_bytes(self) -> usize {
        self.memory_vfs
            .map_or(0, MemoryVfsUsageSnapshot::reserved_bytes)
            .saturating_add(self.page_cache_used_bytes())
    }
}

