    /// Open a pager for the given path.
    ///
    /// Uses [`MemoryVfs`] for `:memory:`.
    ///
    /// File-backed paths use [`IoUringVfs`] on Linux and [`UnixVfs`] on
    /// other unix platforms.
    ///
    /// `page_buffer_max` overrides the page-buffer-pool ceiling. `None`
    /// defers to the `FSQLITE_PAGE_BUFFER_MAX` env var, then to
    /// [`DEFAULT_PAGE_BUFFER_MAX`](fsqlite_pager::DEFAULT_PAGE_BUFFER_MAX).
    fn open_with_page_buffer_max(
        path: &str,
        cx: &Cx,
        page_buffer_max: Option<usize>,
        memory_vfs_config: Option<MemoryVfsConfig>,
    ) -> Result<Self> {
        Self::open_with_requested_page_size_and_page_buffer_max(
            path,
            cx,
            PageSize::DEFAULT,
            None,
            page_buffer_max,
            memory_vfs_config,
        )
    }

    /// Initialize an existing caller-reserved empty file after binding its
    /// open handle to `expected_identity`.
    fn open_reserved_with_page_buffer_max(
        path: &str,
        cx: &Cx,
        expected_identity: FileIdentity,
        page_buffer_max: Option<usize>,
        memory_vfs_config: Option<MemoryVfsConfig>,
    ) -> Result<Self> {
        Self::open_with_requested_page_size_and_page_buffer_max(
            path,
            cx,
            PageSize::DEFAULT,
            Some(expected_identity),
            page_buffer_max,
            memory_vfs_config,
        )
    }

    fn open_with_requested_page_size_and_page_buffer_max(
        path: &str,
        cx: &Cx,
        requested_page_size: PageSize,
        expected_identity: Option<FileIdentity>,
        page_buffer_max: Option<usize>,
        memory_vfs_config: Option<MemoryVfsConfig>,
    ) -> Result<Self> {
        if path == ":memory:" {
            let vfs = memory_vfs_config.map_or_else(MemoryVfs::new, MemoryVfs::new_with_config);
            let db_path = PathBuf::from("/:memory:");
            let mut pager = if let Some(expected_identity) = expected_identity {
                SimplePager::open_reserved_with_cx_and_page_buffer_max(
                    cx,
                    vfs,
                    &db_path,
                    requested_page_size,
                    expected_identity,
                    page_buffer_max,
                )?
            } else {
                SimplePager::open_with_cx_and_page_buffer_max(
                    cx,
                    vfs,
                    &db_path,
                    requested_page_size,
                    page_buffer_max,
                )?
            };
            let _ = pager.enable_single_connection_cache_fast_path();
            Ok(Self::Memory(Arc::new(pager)))
        } else {
            #[cfg(all(feature = "native", target_os = "linux"))]
            {
                let vfs = IoUringVfs::new();
                let db_path = PathBuf::from(path);
                let mode = if let Some(expected_identity) = expected_identity {
                    ConnectionPagerOpenMode::ReservedEmpty(expected_identity)
                } else {
                    ConnectionPagerOpenMode::CreateIfMissing
                };
                let pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                    cx,
                    vfs,
                    &db_path,
                    requested_page_size,
                    page_buffer_max,
                    mode,
                )?;
                Ok(Self::IoUring(Arc::new(pager)))
            }
            #[cfg(all(feature = "native", unix, not(target_os = "linux")))]
            {
                let vfs = UnixVfs::new();
                let db_path = PathBuf::from(path);
                let mode = if let Some(expected_identity) = expected_identity {
                    ConnectionPagerOpenMode::ReservedEmpty(expected_identity)
                } else {
                    ConnectionPagerOpenMode::CreateIfMissing
                };
                let pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                    cx,
                    vfs,
                    &db_path,
                    requested_page_size,
                    page_buffer_max,
                    mode,
                )?;
                Ok(Self::Unix(Arc::new(pager)))
            }
            #[cfg(all(feature = "native", target_os = "windows"))]
            {
                let vfs = fsqlite_vfs::WindowsVfs::new();
                let db_path = PathBuf::from(path);
                let mode = if let Some(expected_identity) = expected_identity {
                    ConnectionPagerOpenMode::ReservedEmpty(expected_identity)
                } else {
                    ConnectionPagerOpenMode::CreateIfMissing
                };
                let pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                    cx,
                    vfs,
                    &db_path,
                    requested_page_size,
                    page_buffer_max,
                    mode,
                )?;
                Ok(Self::Windows(Arc::new(pager)))
            }
            #[cfg(any(not(feature = "native"), not(any(unix, target_os = "windows"))))]
            {
                Err(FrankenError::NotImplemented(
                    "file-backed pager not available on this platform".to_owned(),
                ))
            }
        }
    }

    /// Open an existing file-backed database for reading and writing without
    /// creating or initializing the main database file.
    fn open_existing_with_page_buffer_max(
        path: &str,
        cx: &Cx,
        expected_identity: Option<FileIdentity>,
        page_buffer_max: Option<usize>,
    ) -> Result<Self> {
        #[cfg(all(feature = "native", target_os = "linux"))]
        {
            let vfs = IoUringVfs::new();
            let db_path = PathBuf::from(path);
            let pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                cx,
                vfs,
                &db_path,
                PageSize::DEFAULT,
                page_buffer_max,
                ConnectionPagerOpenMode::ExistingOnly(expected_identity),
            )?;
            Ok(Self::IoUring(Arc::new(pager)))
        }
        #[cfg(all(feature = "native", unix, not(target_os = "linux")))]
        {
            let vfs = UnixVfs::new();
            let db_path = PathBuf::from(path);
            let pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                cx,
                vfs,
                &db_path,
                PageSize::DEFAULT,
                page_buffer_max,
                ConnectionPagerOpenMode::ExistingOnly(expected_identity),
            )?;
            Ok(Self::Unix(Arc::new(pager)))
        }
        #[cfg(all(feature = "native", target_os = "windows"))]
        {
            let vfs = fsqlite_vfs::WindowsVfs::new();
            let db_path = PathBuf::from(path);
            let pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                cx,
                vfs,
                &db_path,
                PageSize::DEFAULT,
                page_buffer_max,
                ConnectionPagerOpenMode::ExistingOnly(expected_identity),
            )?;
            Ok(Self::Windows(Arc::new(pager)))
        }
        #[cfg(any(not(feature = "native"), not(any(unix, target_os = "windows"))))]
        {
            let _ = (path, cx, expected_identity, page_buffer_max);
            Err(FrankenError::NotImplemented(
                "file-backed pager not available on this platform".to_owned(),
            ))
        }
    }

    /// Open a database pager in true read-only mode (fast path).
    ///
    /// Skips journal recovery and freelist traversal for instant open on
    /// large databases.
    ///
    /// `page_buffer_max` overrides the page-buffer-pool ceiling. `None`
    /// defers to the `FSQLITE_PAGE_BUFFER_MAX` env var, then to
    /// [`DEFAULT_PAGE_BUFFER_MAX`](fsqlite_pager::DEFAULT_PAGE_BUFFER_MAX).
    fn open_readonly_with_page_buffer_max(
        path: &str,
        cx: &Cx,
        expected_identity: Option<FileIdentity>,
        page_buffer_max: Option<usize>,
        memory_vfs_config: Option<MemoryVfsConfig>,
    ) -> Result<Self> {
        if path == ":memory:" {
            if expected_identity.is_some() {
                return Err(FrankenError::CannotOpen {
                    path: PathBuf::from(path),
                });
            }
            return Self::open_with_page_buffer_max(path, cx, page_buffer_max, memory_vfs_config);
        }
        #[cfg(all(feature = "native", target_os = "linux"))]
        {
            let vfs = IoUringVfs::new();
            let db_path = PathBuf::from(path);
            let mut pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                cx,
                vfs,
                &db_path,
                PageSize::DEFAULT,
                page_buffer_max,
                ConnectionPagerOpenMode::ReadOnly(expected_identity),
            )?;
            let _ = pager.enable_single_connection_cache_fast_path();
            Ok(Self::IoUring(Arc::new(pager)))
        }
        #[cfg(all(feature = "native", unix, not(target_os = "linux")))]
        {
            let vfs = UnixVfs::new();
            let db_path = PathBuf::from(path);
            let mut pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                cx,
                vfs,
                &db_path,
                PageSize::DEFAULT,
                page_buffer_max,
                ConnectionPagerOpenMode::ReadOnly(expected_identity),
            )?;
            let _ = pager.enable_single_connection_cache_fast_path();
            Ok(Self::Unix(Arc::new(pager)))
        }
        #[cfg(all(feature = "native", target_os = "windows"))]
        {
            let vfs = fsqlite_vfs::WindowsVfs::new();
            let db_path = PathBuf::from(path);
            let mut pager = SimplePager::open_for_connection_with_cx_and_page_buffer_max(
                cx,
                vfs,
                &db_path,
                PageSize::DEFAULT,
                page_buffer_max,
                ConnectionPagerOpenMode::ReadOnly(expected_identity),
            )?;
            let _ = pager.enable_single_connection_cache_fast_path();
            Ok(Self::Windows(Arc::new(pager)))
        }
        #[cfg(any(not(feature = "native"), not(any(unix, target_os = "windows"))))]
        {
            let _ = expected_identity;
            Err(FrankenError::NotImplemented(
                "file-backed pager not available on this platform".to_owned(),
            ))
        }
    }

    /// Begin a new transaction.
    fn begin(&self, cx: &Cx, mode: TransactionMode) -> Result<TransactionKind> {
        match self {
            Self::Memory(p) => Ok(p.begin(cx, mode)?.into()),
            #[cfg(all(feature = "native", target_os = "linux"))]
            Self::IoUring(p) => Ok(p.begin(cx, mode)?.into()),
            #[cfg(all(feature = "native", unix))]
            Self::Unix(p) => Ok(p.begin(cx, mode)?.into()),
            #[cfg(all(feature = "native", target_os = "windows"))]
            Self::Windows(p) => Ok(p.begin(cx, mode)?.into()),
        }
    }

