fn wal_path_for_db_path(path: &str) -> PathBuf {
    let mut db_path = if path == ":memory:" {
        PathBuf::from("/:memory:")
    } else {
        PathBuf::from(path)
    }
    .into_os_string();
    db_path.push("-wal");
    PathBuf::from(db_path)
}

fn install_opened_wal_backend<V>(
    pager: &Arc<SimplePager<V>>,
    cx: &Cx,
    vfs: V,
    wal_path: &Path,
    wal: WalFile<V::File>,
    create_missing: bool,
) -> Result<()>
where
    V: Vfs + Send + Sync + 'static,
    V::File: Send + Sync + 'static,
{
    let expected_page_size = pager.page_size().get();
    if u32::try_from(wal.page_size()).ok() != Some(expected_page_size) {
        let actual_page_size = wal.page_size();
        let _ = wal.close(cx);
        return Err(FrankenError::WalCorrupt {
            detail: format!(
                "WAL page size {actual_page_size} does not match database page size {expected_page_size}"
            ),
        });
    }
    let adapter = PathRefreshingWalBackend::new(
        vfs,
        pager.db_path(),
        wal_path,
        expected_page_size,
        wal,
        create_missing,
        #[cfg(all(feature = "native", any(unix, windows)))]
        pager.namespace_binding(),
    );
    match pager.set_wal_backend_owned(adapter) {
        Ok(()) => Ok(()),
        Err((err, adapter)) => {
            let adapter = adapter.into_inner();
            let wal = adapter.into_inner();
            let _ = wal.close(cx);
            Err(err)
        }
    }
}

fn install_opened_wal_backend_bare<V>(
    pager: &Arc<SimplePager<V>>,
    cx: &Cx,
    wal: WalFile<V::File>,
) -> Result<()>
where
    V: Vfs + Send + Sync + 'static,
    V::File: Send + Sync + 'static,
{
    let expected_page_size = pager.page_size().get();
    if u32::try_from(wal.page_size()).ok() != Some(expected_page_size) {
        let actual_page_size = wal.page_size();
        let _ = wal.close(cx);
        return Err(FrankenError::WalCorrupt {
            detail: format!(
                "WAL page size {actual_page_size} does not match database page size {expected_page_size}"
            ),
        });
    }
    let adapter = WalBackendAdapter::new(wal);
    match pager.set_wal_backend_owned(adapter) {
        Ok(()) => Ok(()),
        Err((err, adapter)) => {
            let wal = adapter.into_inner();
            let _ = wal.close(cx);
            Err(err)
        }
    }
}

fn install_wal_backend_with_vfs<V>(
    pager: &Arc<SimplePager<V>>,
    vfs: V,
    cx: &Cx,
    wal_path: &Path,
) -> Result<()>
where
    V: Vfs + Send + Sync + 'static,
    V::File: Send + Sync + 'static,
{
    if vfs.access(cx, wal_path, AccessFlags::EXISTS)? {
        let open_flags = VfsOpenFlags::READWRITE | VfsOpenFlags::WAL;
        let (mut file, _) = vfs.open(cx, Some(wal_path), open_flags)?;
        if file.file_size(cx)? >= u64::try_from(fsqlite_wal::WAL_HEADER_SIZE).unwrap_or(32) {
            match WalFile::open(cx, file) {
                Ok(wal) => return install_opened_wal_backend(pager, cx, vfs, wal_path, wal, true),
                Err(err) => return Err(err),
            }
        }
        let _ = file.close(cx);
    }

    let create_flags = VfsOpenFlags::READWRITE | VfsOpenFlags::CREATE | VfsOpenFlags::WAL;
    let (file, _) = vfs.open(cx, Some(wal_path), create_flags)?;
    // Random salts (GH #201): a fresh WAL generation must not validate
    // frames from any stale or copied WAL of a previous generation.
    let wal = WalFile::create(cx, file, pager.page_size().get(), 0, WalSalts::generate())?;
    install_opened_wal_backend(pager, cx, vfs, wal_path, wal, true)
}

fn install_existing_wal_backend_with_vfs<V>(
    pager: &Arc<SimplePager<V>>,
    vfs: V,
    cx: &Cx,
    wal_path: &Path,
    allow_readonly: bool,
) -> Result<bool>
where
    V: Vfs + Send + Sync + 'static,
    V::File: Send + Sync + 'static,
{
    if !vfs.access(cx, wal_path, AccessFlags::EXISTS)? {
        return Ok(false);
    }

    // bd-zna34 fix: Always open the WAL file READWRITE. Opening READONLY
    // first would install a read-only canonical fd in the global InodeInfo
    // table (unix.rs). All subsequent connections that clone this fd via the
    // fast path inherit the read-only fd and fail with EBADF on WAL writes
    // (pwrite on a read-only fd returns EBADF on Linux).
    let (mut file, _) = match vfs.open(
        cx,
        Some(wal_path),
        VfsOpenFlags::READWRITE | VfsOpenFlags::WAL,
    ) {
        Ok(opened) => opened,
        Err(err) if allow_readonly => vfs
            .open(
                cx,
                Some(wal_path),
                VfsOpenFlags::READONLY | VfsOpenFlags::WAL,
            )
            .map_err(|_| err)?,
        Err(err) => return Err(err),
    };
    if file.file_size(cx)? < u64::try_from(fsqlite_wal::WAL_HEADER_SIZE).unwrap_or(32) {
        let _ = file.close(cx);
        return Ok(false);
    }

    let wal = WalFile::open(cx, file)?;
    if allow_readonly {
        install_opened_wal_backend_bare(pager, cx, wal)?;
    } else {
        install_opened_wal_backend(pager, cx, vfs, wal_path, wal, false)?;
    }
    Ok(true)
}

fn wal_file_present_with_vfs<V>(vfs: &V, cx: &Cx, wal_path: &Path) -> bool
where
    V: Vfs + Send + Sync + 'static,
{
    if !vfs
        .access(cx, wal_path, AccessFlags::EXISTS)
        .unwrap_or(false)
    {
        return false;
    }

    // bd-zna34 fix: Open READWRITE instead of READONLY for the WAL probe.
    // A READONLY open would install a read-only canonical fd in the global
    // InodeInfo table. If another thread clones that fd before the probe
    // closes, all WAL writes through that fd will fail with EBADF (pwrite
    // on a read-only fd returns EBADF on Linux).
    let open_flags = VfsOpenFlags::READWRITE | VfsOpenFlags::WAL;
    let Ok((mut file, _)) = vfs.open(cx, Some(wal_path), open_flags) else {
        // Fall back to READONLY if READWRITE fails (e.g., read-only filesystem).
        let ro_flags = VfsOpenFlags::READONLY | VfsOpenFlags::WAL;
        let Ok((mut file, _)) = vfs.open(cx, Some(wal_path), ro_flags) else {
            return false;
        };
        let size = file.file_size(cx).ok();
        let _ = file.close(cx);
        return size.is_some_and(|len| len >= 32);
    };
    let size = file.file_size(cx).ok();
    let _ = file.close(cx);
    size.is_some_and(|len| len >= 32)
}

/// Build a [`FunctionRegistry`] populated with all built-in scalar,
/// aggregate, datetime, and math functions.
fn shared_builtin_function_registry() -> &'static Arc<FunctionRegistry> {
    static REGISTRY: OnceLock<Arc<FunctionRegistry>> = OnceLock::new();
    REGISTRY.get_or_init(|| {
        let mut registry = FunctionRegistry::new();
        fsqlite_func::register_builtins(&mut registry);
        fsqlite_func::register_datetime_builtins(&mut registry);
        fsqlite_func::register_math_builtins(&mut registry);
        fsqlite_func::register_aggregate_builtins(&mut registry);
        fsqlite_func::register_window_builtins(&mut registry);
        #[cfg(feature = "ext-json")]
        fsqlite_ext_json::register_json_scalars(&mut registry);
        #[cfg(feature = "ext-fts5")]
        fsqlite_ext_fts5::register_fts5_scalars(&mut registry);
        #[cfg(feature = "ext-icu")]
        fsqlite_ext_icu::register_icu_scalars(&mut registry);
        #[cfg(feature = "ext-misc")]
        fsqlite_ext_misc::register_misc_scalars(&mut registry);
        #[cfg(feature = "ext-rtree")]
        fsqlite_ext_rtree::register_geopoly_scalars(&mut registry);
        Arc::new(registry)
    })
}

#[cfg(feature = "ext-icu")]
fn default_function_registry(
    collation_registry: &Arc<Mutex<CollationRegistry>>,
) -> Arc<FunctionRegistry> {
    let mut registry = FunctionRegistry::clone_from_arc(shared_builtin_function_registry());
    // This entry captures the connection-local collation registry, so it
    // cannot live in the process-global immutable base registry.
    fsqlite_ext_icu::register_icu_load_collation(&mut registry, Arc::clone(collation_registry));
    Arc::new(registry)
}

#[cfg(not(feature = "ext-icu"))]
fn default_function_registry(
    _collation_registry: &Arc<Mutex<CollationRegistry>>,
) -> Arc<FunctionRegistry> {
    Arc::new(FunctionRegistry::clone_from_arc(
        shared_builtin_function_registry(),
    ))
}

fn shared_default_vtab_module_registry() -> &'static HashMap<String, Arc<dyn VtabModuleFactory>> {
    static MODULES: OnceLock<HashMap<String, Arc<dyn VtabModuleFactory>>> = OnceLock::new();
    MODULES.get_or_init(|| {
        let mut modules: HashMap<String, Arc<dyn VtabModuleFactory>> = HashMap::new();
        #[cfg(feature = "ext-fts5")]
        modules.insert(
            "FTS5".to_owned(),
            Arc::new(module_factory_from::<Fts5Table>()),
        );
        #[cfg(feature = "ext-json")]
        modules.insert(
            "JSON_EACH".to_owned(),
            Arc::new(module_factory_from::<JsonEachVtab>()),
        );
        #[cfg(feature = "ext-json")]
        modules.insert(
            "JSON_TREE".to_owned(),
            Arc::new(module_factory_from::<JsonTreeVtab>()),
        );
        #[cfg(feature = "ext-misc")]
        modules.insert(
            "GENERATE_SERIES".to_owned(),
            Arc::new(module_factory_from::<GenerateSeriesTable>()),
        );
        modules.insert(
            "FSQLITE_HTM_METRICS".to_owned(),
            Arc::new(module_factory_from::<HtmMetricsVtab>()),
        );
        #[cfg(feature = "ext-rtree")]
        modules.insert(
            "RTREE".to_owned(),
            Arc::new(fsqlite_ext_rtree::rtree_module_factory()),
        );
        #[cfg(feature = "ext-rtree")]
        modules.insert(
            "RTREE_I32".to_owned(),
            Arc::new(fsqlite_ext_rtree::rtree_i32_module_factory()),
        );
        modules
    })
}

fn default_vtab_module_registry() -> HashMap<String, Arc<dyn VtabModuleFactory>> {
    shared_default_vtab_module_registry().clone()
}

