#[derive(Debug, Clone, Copy)]
struct TopCategorySumAccumulator {
    int_sum: i64,
    float_sum: f64,
    float_compensation: f64,
    all_integer: bool,
    has_values: bool,
    int_overflowed: bool,
}

impl Default for TopCategorySumAccumulator {
    fn default() -> Self {
        Self {
            int_sum: 0,
            float_sum: 0.0,
            float_compensation: 0.0,
            all_integer: true,
            has_values: false,
            int_overflowed: false,
        }
    }
}

impl TopCategorySumAccumulator {
    #[allow(clippy::cast_precision_loss)]
    fn add(&mut self, value: &SqliteValue) {
        let value = value.to_sum_numeric_value();
        if value.is_null() {
            return;
        }
        self.has_values = true;
        match value {
            SqliteValue::Integer(integer) => {
                if self.all_integer && !self.int_overflowed {
                    match self.int_sum.checked_add(integer) {
                        Some(sum) => self.int_sum = sum,
                        None => self.int_overflowed = true,
                    }
                }
                self.add_float(integer as f64);
            }
            SqliteValue::Float(f) => {
                self.all_integer = false;
                self.add_float(f);
            }
            SqliteValue::Null | SqliteValue::Text(_) | SqliteValue::Blob(_) => {}
        }
    }

    fn finish(self) -> Result<SqliteValue> {
        if !self.has_values {
            Ok(SqliteValue::Null)
        } else if self.all_integer && self.int_overflowed {
            Err(FrankenError::IntegerOverflow)
        } else if self.all_integer {
            Ok(SqliteValue::Integer(self.int_sum))
        } else {
            Ok(SqliteValue::Float(self.float_sum + self.float_compensation))
        }
    }

    fn add_float(&mut self, value: f64) {
        let sum = self.float_sum;
        let next = sum + value;
        if sum.abs() > value.abs() {
            self.float_compensation += (sum - next) + value;
        } else {
            self.float_compensation += (value - next) + sum;
        }
        self.float_sum = next;
    }
}

