#[derive(Debug, Clone)]
struct PreparedPrecompiledDml {
    kind: PreparedDmlKind,
    table_name: String,
    post_write_action: PreparedInsertPostWriteAction,
    rollback_on_constraint_violation: bool,
    preserve_prior_changes_on_constraint_violation: bool,
    skip_statement_savepoint_in_explicit_txn: bool,
    runtime_requirements: TableExecutionRuntimeRequirements,
    static_runtime_inputs: Option<TableExecutionRuntimeInputs>,
    direct_simple_insert: Option<PreparedDirectSimpleInsert>,
    /// Issue #110: `true` when this is an `INSERT OR REPLACE` or an upsert
    /// (`ON CONFLICT`), i.e. an INSERT that can delete or mutate an existing
    /// row (potentially a parent of a previously cached child FK). Only
    /// meaningful for `kind == Insert`. Plain INSERTs (the hot path) leave this
    /// `false`, so the transaction-scoped FK parent-validation cache survives.
    insert_may_invalidate_fk_parent_cache: bool,
}

#[derive(Debug, Clone)]
#[allow(clippy::large_enum_variant)]
enum PreparedDmlDispatch {
    /// Fall back to the full statement pipeline. This can still reuse a cached
    /// compiled program when `db` is populated, but it keeps the AST around for
    /// trigger/FK/materialization paths that still need statement structure.
    Deferred(Arc<Statement>),
    /// Execute through a dedicated prepared-DML helper that reuses the cached
    /// program without keeping the full AST alive.
    Precompiled(Rc<PreparedPrecompiledDml>),
}

#[derive(Clone)]
struct PreparedStatementTemplate {
    canonical_sql: Rc<str>,
    program: Arc<VdbeProgram>,
    expression_postprocess: Option<ExpressionPostprocess>,
    distinct: bool,
    distinct_collations: Vec<Option<String>>,
    table_backed: bool,
    post_distinct_limit: Option<LimitClause>,
    schema_cookie: u32,
    schema_generation: u64,
    function_registry_generation: u64,
    /// Finalized commit epoch (global, monotonic) at the time this template
    /// was inserted into the prepared cache (bd-#70 wedge). Together with
    /// schema identity, this guards cached plans against stale row visibility
    /// after a cross-connection write commit. Templates that opt-in via
    /// [`can_survive_write_commit`] bypass the epoch check so direct-DML
    /// dispatch keeps surviving ordinary commits.
    commit_epoch: u64,
    dml_dispatch: Option<PreparedDmlDispatch>,
    prepared_update_delete_fast_path: Option<PreparedUpdateDeleteFastPath>,
    deferred_query_statement: Option<Arc<Statement>>,
    deferred_query_column_count: Option<usize>,
    column_names: Vec<String>,
    prepared_query_fast_path: Option<PreparedQueryFastPath>,
    may_observe_change_tracking: bool,
}

impl PreparedStatementTemplate {
    fn from_statement(stmt: &PreparedStatement<'_>, commit_epoch: u64) -> Self {
        Self {
            canonical_sql: Rc::clone(&stmt.sql),
            program: Arc::clone(&stmt.program),
            expression_postprocess: stmt.expression_postprocess.clone(),
            distinct: stmt.distinct,
            distinct_collations: stmt.distinct_collations.clone(),
            table_backed: stmt.db.is_some(),
            post_distinct_limit: stmt.post_distinct_limit.clone(),
            schema_cookie: stmt.schema_cookie,
            schema_generation: stmt.schema_generation,
            function_registry_generation: stmt.function_registry_generation,
            commit_epoch,
            dml_dispatch: stmt.dml_dispatch.clone(),
            prepared_update_delete_fast_path: stmt.prepared_update_delete_fast_path.clone(),
            deferred_query_statement: stmt.deferred_query_statement.clone(),
            deferred_query_column_count: stmt.deferred_query_column_count,
            column_names: stmt.column_names.clone(),
            prepared_query_fast_path: stmt.prepared_query_fast_path.clone(),
            may_observe_change_tracking: stmt.may_observe_change_tracking,
        }
    }

    fn matches_cache_identity(
        &self,
        schema_cookie: u32,
        schema_generation: u64,
        function_registry_generation: u64,
        current_commit_epoch: u64,
    ) -> bool {
        // bd-#70 plan-cache epoch wedge: a prepared template is only reusable
        // when both its schema identity AND the finalized global commit epoch
        // are unchanged since insertion. Without the commit-epoch check, a
        // SELECT prepared on connection A could reuse cached row-visibility
        // bindings after a write committed on connection B — the root cause
        // of `beads_rust#252` (stale row reads across connections) and #70.
        //
        // Direct-DML templates (`can_survive_write_commit() == true`) opt out
        // of the epoch check: their dispatch metadata depends only on schema
        // identity (root page, column layout, bind slots), never on row-data
        // visibility, so re-using them across ordinary write commits is safe
        // and preserves the ~2pp Lexer + write_ident hot-path savings called
        // out in the 2026-04-23 MT capture.
        //
        // Conservative wedge: any commit invalidates non-direct-DML plans.
        // Future optimization: narrow by `pages_read_set ∩ pages_written_set`
        // so a commit that only touches unrelated pages leaves the plan live.
        if self.schema_cookie != schema_cookie
            || self.schema_generation != schema_generation
            || self.function_registry_generation != function_registry_generation
        {
            return false;
        }
        if self.can_survive_write_commit() {
            return true;
        }
        self.commit_epoch == current_commit_epoch
    }

    fn can_survive_write_commit(&self) -> bool {
        let direct_insert = self.dml_dispatch.as_ref().is_some_and(|dispatch| {
            let PreparedDmlDispatch::Precompiled(dml) = dispatch else {
                return false;
            };
            matches!(dml.kind, PreparedDmlKind::Insert)
                && dml
                    .direct_simple_insert
                    .as_ref()
                    .is_some_and(|direct| !direct.prefers_reusable_table_program())
        });
        let direct_update_delete = self
            .prepared_update_delete_fast_path
            .as_ref()
            .is_some_and(PreparedUpdateDeleteFastPath::has_direct_simple_dispatch);

        direct_insert || direct_update_delete
    }

    fn instantiate<'conn>(&self, conn: &'conn Connection) -> PreparedStatement<'conn> {
        PreparedStatement {
            sql: Rc::clone(&self.canonical_sql),
            program: Arc::clone(&self.program),
            func_registry: Some(Arc::clone(&*conn.func_registry.borrow())),
            expression_postprocess: self.expression_postprocess.clone(),
            distinct: self.distinct,
            distinct_collations: self.distinct_collations.clone(),
            db: self.table_backed.then(|| Rc::clone(&conn.db)),
            post_distinct_limit: self.post_distinct_limit.clone(),
            schema_cookie: self.schema_cookie,
            schema_generation: self.schema_generation,
            function_registry_generation: self.function_registry_generation,
            dml_dispatch: self.dml_dispatch.clone(),
            prepared_update_delete_fast_path: self.prepared_update_delete_fast_path.clone(),
            deferred_query_statement: self.deferred_query_statement.clone(),
            deferred_query_column_count: self.deferred_query_column_count,
            column_names: self.column_names.clone(),
            prepared_query_fast_path: self.prepared_query_fast_path.clone(),
            may_observe_change_tracking: self.may_observe_change_tracking,
            conn,
        }
    }
}

#[derive(Clone)]
struct PreparedCacheEntry {
    sql: String,
    template: PreparedStatementTemplate,
}

pub struct PreparedStatement<'conn> {
    sql: Rc<str>,
    program: Arc<VdbeProgram>,
    func_registry: Option<Arc<FunctionRegistry>>,
    expression_postprocess: Option<ExpressionPostprocess>,
    distinct: bool,
    distinct_collations: Vec<Option<String>>,
    /// For table-backed SELECT, the statement must execute against the same
    /// MemDatabase as the Connection that prepared it.
    db: Option<Rc<RefCell<MemDatabase>>>,
    /// For table-backed `SELECT DISTINCT ... LIMIT/OFFSET`, we compile an
    /// unbounded program and apply the LIMIT/OFFSET after de-duplication.
    ///
    /// This mirrors `Connection::execute_statement`'s distinct+limit handling
    /// to avoid returning too few rows when LIMIT is applied before DISTINCT.
    post_distinct_limit: Option<LimitClause>,
    /// Schema cookie captured at prepare time (bd-3mmj). Used by the
    /// engine's `ReadCookie` opcode and prepared-statement invalidation.
    schema_cookie: u32,
    /// Local schema-generation marker captured at prepare time so prepared
    /// statements invalidate on same-connection DDL before any memdb reload.
    schema_generation: u64,
    /// Function-registry generation captured at prepare time so cached plans
    /// and prepared handles fail fast after any UDF redefinition.
    function_registry_generation: u64,
    /// DML execution path metadata for prepared statements. Some statements
    /// still need the parsed AST at execution time, while others can run from
    /// the cached bytecode plus a small amount of dispatch metadata.
    dml_dispatch: Option<PreparedDmlDispatch>,
    /// Prepare-time fast-path metadata for UPDATE/DELETE statements that keep
    /// the AST as a generic fallback but can skip repeated eligibility scans.
    prepared_update_delete_fast_path: Option<PreparedUpdateDeleteFastPath>,
    /// For SELECT statements that cannot be safely precompiled because they
    /// depend on connection-level fallback routing or parameter-sensitive
    /// subquery rewriting, store the AST and re-dispatch at execution time.
    deferred_query_statement: Option<Arc<Statement>>,
    /// Cached column count for deferred SELECT statements whose placeholder
    /// program does not contain a `ResultRow` opcode.
    deferred_query_column_count: Option<usize>,
    /// Best-effort result column labels inferred at prepare time for SELECT
    /// statements so higher layers can expose stable metadata.
    column_names: Vec<String>,
    /// Prepare-time fast-path metadata for SELECT statements that can bypass
    /// generic VDBE row production on repeated exact-row calls.
    prepared_query_fast_path: Option<PreparedQueryFastPath>,
    /// True when the prepared statement tree may read connection-scoped SQL
    /// change-tracking state like `changes()` or `last_insert_rowid()`.
    may_observe_change_tracking: bool,
    /// Reference to the parent Connection that prepared this statement.
    /// Used by `execute_with_params` to delegate DML execution through
    /// the Connection's full execution pipeline (triggers, constraints,
    /// autocommit).
    conn: &'conn Connection,
}

#[derive(Debug, Clone, Default)]
struct ExpressionPostprocess {
    order_by: Vec<OrderingTerm>,
    limit: Option<LimitClause>,
    output_aliases: HashMap<String, usize>,
    output_width: usize,
}

#[derive(Debug, Clone, Copy)]
struct ResolvedOrderTerm {
    column_index: usize,
    descending: bool,
    nulls_order: NullsOrder,
}

/// Compatibility mask for sqlite3_trace_v2-style callbacks.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TraceMask(u32);

impl TraceMask {
    pub const STMT: Self = Self(0x01);
    pub const PROFILE: Self = Self(0x02);
    pub const ROW: Self = Self(0x04);
    pub const CLOSE: Self = Self(0x08);
    pub const ALL: Self = Self(Self::STMT.0 | Self::PROFILE.0 | Self::ROW.0 | Self::CLOSE.0);

    #[must_use]
    pub const fn contains(self, other: Self) -> bool {
        (self.0 & other.0) != 0
    }
}

const QUERY_ROW_RESULT_ROW_CAP: usize = 2;

enum QueryRowCollectionOutcome {
    Row(Row),
    NoRows,
    MultipleRows,
}

fn record_direct_result_row_metrics(row: &Row) {
    fsqlite_vdbe::engine::record_external_result_row_metrics(row.values());
}

fn direct_query_row_result(row: Row) -> Row {
    record_direct_result_row_metrics(&row);
    row
}

fn direct_query_row_outcome_result(row_outcome: QueryRowCollectionOutcome) -> Result<Row> {
    match row_outcome {
        QueryRowCollectionOutcome::Row(row) => Ok(direct_query_row_result(row)),
        QueryRowCollectionOutcome::NoRows => Err(FrankenError::QueryReturnedNoRows),
        QueryRowCollectionOutcome::MultipleRows => Err(FrankenError::QueryReturnedMultipleRows),
    }
}

impl std::ops::BitOr for TraceMask {
    type Output = Self;

    fn bitor(self, rhs: Self) -> Self::Output {
        Self(self.0 | rhs.0)
    }
}

/// sqlite3_trace_v2-style callback event payload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TraceEvent {
    /// Statement text about to execute.
    Statement { sql: String },
    /// Statement execution profile (nanoseconds).
    Profile { sql: String, elapsed_ns: u64 },
    /// Row delivered to the client.
    Row { values: Vec<SqliteValue> },
    /// Connection close lifecycle event.
    Close,
}

impl TraceEvent {
    #[must_use]
    fn callback_type(&self) -> &'static str {
        match self {
            Self::Statement { .. } => "stmt",
            Self::Profile { .. } => "profile",
            Self::Row { .. } => "row",
            Self::Close => "close",
        }
    }

    #[must_use]
    fn required_mask(&self) -> TraceMask {
        match self {
            Self::Statement { .. } => TraceMask::STMT,
            Self::Profile { .. } => TraceMask::PROFILE,
            Self::Row { .. } => TraceMask::ROW,
            Self::Close => TraceMask::CLOSE,
        }
    }
}

/// Callback signature for sqlite3_trace_v2 compatibility.
pub type TraceCallback = Arc<dyn Fn(TraceEvent) + Send + Sync + 'static>;

#[derive(Clone)]
struct TraceRegistration {
    mask: TraceMask,
    callback: TraceCallback,
}

fn emit_compat_trace_event(trace: Option<&TraceRegistration>, event: TraceEvent) {
    let Some(trace) = trace else {
        return;
    };
    if !trace.mask.contains(event.required_mask()) {
        return;
    }

    let callback_type = event.callback_type();
    record_compat_trace_callback();
    if tracing::enabled!(target: "fsqlite.compat_trace", tracing::Level::DEBUG) {
        let span = tracing::span!(
            target: "fsqlite.compat_trace",
            tracing::Level::DEBUG,
            "compat_trace",
            callback_type
        );
        record_trace_span_created();
        let _guard = span.enter();
        (trace.callback)(event);
        tracing::debug!(callback_type, "sqlite3_trace_v2 callback emitted");
    } else {
        (trace.callback)(event);
    }
}

impl std::fmt::Debug for PreparedStatement<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PreparedStatement")
            .field("sql", &self.sql)
            .field("program", &self.program)
            .finish_non_exhaustive()
    }
}

impl PreparedStatement<'_> {
    fn clean_memory_prepared_memdb_fast_path_ready_without_refresh(&self) -> bool {
        if !self
            .conn
            .clean_memory_prepared_memdb_direct_fast_path_candidate(self)
            || !self
                .conn
                .prepared_memdb_query_fast_path_ready_with_mode(self, false)
            || !self.conn.memdb_storage_count_shortcuts_safe.get()
            || self.conn.memdb_requires_active_txn_reload.get()
        {
            return false;
        }

        let visible_commit_seq = *self.conn.memdb_visible_commit_seq.borrow();
        let cached_write_txn = self.conn.cached_write_txn.borrow();
        let Some(bound_visible_commit_seq) = cached_write_txn
            .as_ref()
            .and_then(|txn| txn.published_visible_commit_seq_hint())
        else {
            return true;
        };

        bound_visible_commit_seq < visible_commit_seq
            || (bound_visible_commit_seq == visible_commit_seq
                && self.conn.cached_write_txn_memdb_row_mirror_exact.get())
    }

    fn clean_memory_prepared_memdb_row_image_fast_path_ready_without_refresh(&self) -> bool {
        if !self
            .conn
            .clean_memory_prepared_memdb_direct_fast_path_candidate(self)
            || !self
                .conn
                .prepared_memdb_query_fast_path_ready_with_mode(self, false)
            || self.conn.memdb_requires_active_txn_reload.get()
        {
            return false;
        }

        let visible_commit_seq = *self.conn.memdb_visible_commit_seq.borrow();
        let cached_write_txn = self.conn.cached_write_txn.borrow();
        let Some(bound_visible_commit_seq) = cached_write_txn
            .as_ref()
            .and_then(|txn| txn.published_visible_commit_seq_hint())
        else {
            return true;
        };

        bound_visible_commit_seq < visible_commit_seq
            || (bound_visible_commit_seq == visible_commit_seq
                && self.conn.cached_write_txn_memdb_row_mirror_exact.get())
    }

    fn try_query_clean_memory_indexed_equality_fast(
        &self,
        params: &[SqliteValue],
    ) -> Result<Option<Vec<Row>>> {
        let Some(PreparedQueryFastPath::SimpleIndexedEqualityLookup {
            root_page,
            index_root_page,
            column_index,
            parameter_index,
            rowid_alias_column_index,
            projections,
        }) = self.prepared_query_fast_path.as_ref()
        else {
            return Ok(None);
        };
        if self.dml_dispatch.is_some()
            || self.may_observe_change_tracking
            || record_profile_enabled()
            || tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG)
            || tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO)
        {
            return Ok(None);
        }
        if !self.clean_memory_prepared_memdb_row_image_fast_path_ready_without_refresh() {
            return Ok(None);
        }
        let Some(probe_value) = params.get(*parameter_index) else {
            return Ok(None);
        };
        if matches!(probe_value, SqliteValue::Null) {
            self.ensure_schema_identity_unchanged_after_local_refresh()?;
            FSQLITE_DIRECT_INDEXED_EQUALITY_QUERY_HITS.fetch_add(1, AtomicOrdering::Relaxed);
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = "direct_indexed_equality_query",
                    read_boundary = "skipped_clean_memory_memdb_direct",
                );
            }
            self.conn.note_connection_statement_execution_count(1);
            return Ok(Some(Vec::new()));
        }
        let SqliteValue::Text(_) = probe_value else {
            return Ok(None);
        };

        self.ensure_schema_identity_unchanged_after_local_refresh()?;
        let cache_key = self.conn.prepared_indexed_equality_cache_key(
            *root_page,
            *index_root_page,
            *column_index,
        );
        let rows = if let Some(rows) = self.conn.last_prepared_indexed_equality_rows(
            cache_key,
            *rowid_alias_column_index,
            projections.as_ref(),
            probe_value,
        ) {
            rows
        } else {
            let Some(result) = self.conn.with_prepared_indexed_equality_rowids_for_key(
                cache_key,
                probe_value,
                |rowids| {
                    let db = self.conn.db.borrow();
                    let table = db.get_table(*root_page)?;
                    let mut rows = Vec::with_capacity(rowids.len());
                    for rowid in rowids.iter().copied() {
                        let values = table.row_values_by_rowid(rowid)?;
                        rows.push(match projections.as_deref() {
                            Some(projections) => row_from_memdb_value_sources(
                                rowid,
                                values,
                                projections,
                                *rowid_alias_column_index,
                            ),
                            None => {
                                row_from_memdb_row_values(rowid, values, *rowid_alias_column_index)
                            }
                        });
                    }
                    Some(rows)
                },
            ) else {
                return Ok(None);
            };
            let Some(rows) = result else {
                return Ok(None);
            };
            self.conn.store_prepared_indexed_equality_last_result(
                cache_key,
                *rowid_alias_column_index,
                projections.as_ref(),
                probe_value,
                &rows,
            );
            rows
        };

        FSQLITE_DIRECT_INDEXED_EQUALITY_QUERY_HITS.fetch_add(1, AtomicOrdering::Relaxed);
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast",
                reason = "direct_indexed_equality_query",
                read_boundary = "skipped_clean_memory_memdb_direct",
            );
        }
        self.conn.note_connection_statement_execution_count(1);
        Ok(Some(rows))
    }

    fn try_query_row_clean_memory_count_star_fast(&self) -> Result<Option<Row>> {
        let Some(PreparedQueryFastPath::SimpleCountStar { root_page }) =
            self.prepared_query_fast_path.as_ref()
        else {
            return Ok(None);
        };
        if self.dml_dispatch.is_some()
            || self.may_observe_change_tracking
            || record_profile_enabled()
            || tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG)
            || tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO)
        {
            return Ok(None);
        }
        self.ensure_schema_identity_unchanged_after_local_refresh()?;
        let (count, read_boundary) =
            if self.clean_memory_prepared_memdb_fast_path_ready_without_refresh() {
                let db = self.conn.db.borrow();
                let Some(table) = db.get_table(*root_page) else {
                    return Ok(None);
                };
                let count = i64::try_from(table.row_count()).map_err(|_| {
                    FrankenError::Internal(format!(
                        "table row count exceeds i64 for root page {root_page}"
                    ))
                })?;
                (count, "skipped_clean_memory_memdb_direct")
            } else if let Some(count) = self
                .conn
                .try_clean_memory_storage_count_cached_count(*root_page)?
            {
                (count, "skipped_clean_memory_storage_count_cache")
            } else {
                return Ok(None);
            };

        FSQLITE_DIRECT_COUNT_STAR_QUERY_ROW_HITS.fetch_add(1, AtomicOrdering::Relaxed);
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast",
                reason = "direct_count_star_query_row",
                read_boundary,
            );
        }
        self.conn.note_connection_statement_execution_count(1);
        Ok(Some(Row {
            values: vec![SqliteValue::Integer(count)],
        }))
    }

    fn try_query_row_clean_memory_count_indexed_rowid_probe_fast(&self) -> Result<Option<Row>> {
        let Some(PreparedQueryFastPath::SimpleCountIndexedRowidProbe {
            root_page,
            index_root_page,
            column_index,
            probe_root_page,
            probe_rowid_upper_exclusive,
        }) = self.prepared_query_fast_path.as_ref()
        else {
            return Ok(None);
        };
        if self.dml_dispatch.is_some()
            || self.may_observe_change_tracking
            || record_profile_enabled()
            || tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG)
            || tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO)
        {
            return Ok(None);
        }
        self.ensure_schema_identity_unchanged_after_local_refresh()?;
        if !self
            .conn
            .clean_memory_prepared_memdb_fast_path_candidate(self)
            || self.conn.memdb_requires_active_txn_reload.get()
        {
            return Ok(None);
        }
        let Some(row) = self.conn.prepared_count_indexed_rowid_probe_row(
            *root_page,
            *index_root_page,
            *column_index,
            *probe_root_page,
            *probe_rowid_upper_exclusive,
        )?
        else {
            return Ok(None);
        };

        FSQLITE_DIRECT_COUNT_INDEXED_ROWID_PROBE_QUERY_ROW_HITS
            .fetch_add(1, AtomicOrdering::Relaxed);
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast",
                reason = "direct_count_indexed_rowid_probe_query_row",
                read_boundary = "skipped_clean_memory_memdb_direct",
            );
        }
        self.conn.note_connection_statement_execution_count(1);
        Ok(Some(row))
    }

    fn try_query_row_clean_memory_rowid_lookup_fast(
        &self,
        params: &[SqliteValue],
    ) -> Result<Option<QueryRowCollectionOutcome>> {
        let Some(fast_path) = self.prepared_query_fast_path.as_ref() else {
            return Ok(None);
        };
        let (root_page, parameter_index, rowid_alias_column_index, projections) = match fast_path {
            PreparedQueryFastPath::SimpleRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
            } => (
                *root_page,
                *parameter_index,
                *rowid_alias_column_index,
                None,
            ),
            PreparedQueryFastPath::SimpleProjectedRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
                projections,
            } => (
                *root_page,
                *parameter_index,
                *rowid_alias_column_index,
                Some(projections.as_ref()),
            ),
            _ => return Ok(None),
        };
        if self.dml_dispatch.is_some()
            || self.may_observe_change_tracking
            || record_profile_enabled()
            || tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG)
            || tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO)
            || !self.clean_memory_prepared_memdb_row_image_fast_path_ready_without_refresh()
        {
            return Ok(None);
        }
        let Some(SqliteValue::Integer(rowid)) = params.get(parameter_index) else {
            return Ok(None);
        };

        let schema_identity_carried = self.conn.stmt_microbatch_try_carry(
            Arc::as_ptr(&self.program) as usize,
            params.len(),
            false,
            None,
        );
        if !schema_identity_carried {
            self.ensure_schema_identity_unchanged_after_local_refresh()?;
        }
        let outcome = {
            let db = self.conn.db.borrow();
            let Some(table) = db.get_table(root_page) else {
                return Ok(None);
            };
            match table.row_values_by_rowid(*rowid) {
                Some(values) => {
                    let row = match projections {
                        Some(projections) => row_from_memdb_value_sources(
                            *rowid,
                            values,
                            projections,
                            rowid_alias_column_index,
                        ),
                        None => row_from_memdb_row_values(*rowid, values, rowid_alias_column_index),
                    };
                    QueryRowCollectionOutcome::Row(row)
                }
                None => QueryRowCollectionOutcome::NoRows,
            }
        };

        FSQLITE_DIRECT_ROWID_LOOKUP_QUERY_ROW_HITS.fetch_add(1, AtomicOrdering::Relaxed);
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast",
                reason = fast_path.query_row_trace_reason(),
                read_boundary = "skipped_clean_memory_memdb_direct",
            );
        }
        self.conn.note_connection_statement_execution_count(1);
        Ok(Some(outcome))
    }

    fn requires_schema_validation(&self) -> bool {
        self.db.is_some() || self.dml_dispatch.is_some() || self.deferred_query_statement.is_some()
    }

    fn requires_external_schema_refresh(&self) -> bool {
        self.requires_schema_validation()
            && !self.conn.pager.is_memory()
            && self.conn.active_txn.borrow().is_none()
    }

    fn can_use_lightweight_external_schema_refresh(&self) -> bool {
        self.db.is_some()
            && self.deferred_query_statement.is_none()
            && self.deferred_dml_statement().is_none()
    }

    fn dispatch_precompiled_program(&self) -> Option<&VdbeProgram> {
        if self.deferred_dml_statement().is_some() && self.db.is_some() {
            Some(self.program.as_ref())
        } else {
            None
        }
    }

    fn deferred_dml_statement(&self) -> Option<&Statement> {
        match self.dml_dispatch.as_ref() {
            Some(PreparedDmlDispatch::Deferred(statement)) => Some(statement.as_ref()),
            Some(PreparedDmlDispatch::Precompiled(_)) | None => None,
        }
    }

    fn precompiled_dml(&self) -> Option<&PreparedPrecompiledDml> {
        match self.dml_dispatch.as_ref() {
            Some(PreparedDmlDispatch::Precompiled(dispatch)) => Some(dispatch.as_ref()),
            Some(PreparedDmlDispatch::Deferred(_)) | None => None,
        }
    }

    fn prepared_update_delete_fast_path(&self) -> Option<&PreparedUpdateDeleteFastPath> {
        self.prepared_update_delete_fast_path.as_ref()
    }

    fn prepared_query_fast_path_metadata(
        &self,
        missing_context: &'static str,
    ) -> Result<PreparedQueryFastPath> {
        self.prepared_query_fast_path.clone().ok_or_else(|| {
            FrankenError::internal(format!(
                "{missing_context} requires prepared_query_fast_path metadata"
            ))
        })
    }

    fn clone_with_program(&self, program: Arc<VdbeProgram>) -> Self {
        Self {
            sql: Rc::clone(&self.sql),
            program,
            func_registry: self.func_registry.clone(),
            expression_postprocess: self.expression_postprocess.clone(),
            distinct: self.distinct,
            distinct_collations: self.distinct_collations.clone(),
            db: self.db.as_ref().map(Rc::clone),
            post_distinct_limit: self.post_distinct_limit.clone(),
            schema_cookie: self.schema_cookie,
            schema_generation: self.schema_generation,
            function_registry_generation: self.function_registry_generation,
            dml_dispatch: self.dml_dispatch.clone(),
            prepared_update_delete_fast_path: self.prepared_update_delete_fast_path.clone(),
            deferred_query_statement: self.deferred_query_statement.clone(),
            deferred_query_column_count: self.deferred_query_column_count,
            column_names: self.column_names.clone(),
            prepared_query_fast_path: self.prepared_query_fast_path.clone(),
            may_observe_change_tracking: self.may_observe_change_tracking,
            conn: self.conn,
        }
    }

    fn prepared_table_program_runtime_inputs(
        &self,
    ) -> (
        TableExecutionRuntimeRequirements,
        Option<TableExecutionRuntimeInputs>,
    ) {
        if let Some(dispatch) = self.precompiled_dml() {
            return (
                dispatch.runtime_requirements,
                dispatch.static_runtime_inputs.clone(),
            );
        }
        if let Some(fast_path) = self.prepared_update_delete_fast_path() {
            return (
                fast_path.runtime_requirements,
                fast_path.static_runtime_inputs.clone(),
            );
        }
        (TableExecutionRuntimeRequirements::read_path(), None)
    }

    fn ensure_schema_unchanged(&self, cx: &Cx) -> Result<()> {
        let _ = self.ensure_schema_unchanged_with_prebound_publication(cx)?;
        Ok(())
    }

    fn ensure_schema_identity_unchanged_after_local_refresh(&self) -> Result<()> {
        if self.conn.function_registry_generation() != self.function_registry_generation {
            let failure_diag = format!(
                "prepared_function_registry_generation={} current_function_registry_generation={}",
                self.function_registry_generation,
                self.conn.function_registry_generation()
            );
            self.conn.log_statement_reuse_event(
                "prepared_schema_validation",
                &self.sql,
                false,
                "function_registry_changed",
                0,
                0,
                failure_diag.as_str(),
            );
            return Err(FrankenError::SchemaChanged);
        }
        if self.requires_schema_validation()
            && (self.conn.schema_cookie() != self.schema_cookie
                || self.conn.schema_generation() != self.schema_generation)
        {
            let invalidate_reason = if self.conn.schema_cookie() != self.schema_cookie {
                "schema_cookie_changed"
            } else {
                "schema_generation_changed"
            };
            let failure_diag = format!(
                "prepared_schema_identity={} current_schema_identity={}",
                format_schema_identity(self.schema_cookie, self.schema_generation),
                self.conn.current_schema_identity()
            );
            self.conn.log_statement_reuse_event(
                "prepared_schema_validation",
                &self.sql,
                false,
                invalidate_reason,
                0,
                0,
                failure_diag.as_str(),
            );
            return Err(FrankenError::SchemaChanged);
        }
        Ok(())
    }

    fn ensure_schema_unchanged_with_prebound_publication(
        &self,
        cx: &Cx,
    ) -> Result<PreparedDmlEntryProof> {
        if self.conn.function_registry_generation() != self.function_registry_generation {
            let failure_diag = format!(
                "prepared_function_registry_generation={} current_function_registry_generation={}",
                self.function_registry_generation,
                self.conn.function_registry_generation()
            );
            self.conn.log_statement_reuse_event(
                "prepared_schema_validation",
                &self.sql,
                false,
                "function_registry_changed",
                0,
                0,
                failure_diag.as_str(),
            );
            return Err(FrankenError::SchemaChanged);
        }
        let prebound_publication = if self.requires_external_schema_refresh() {
            self.conn.refresh_prepared_schema_state(
                cx,
                self.can_use_lightweight_external_schema_refresh(),
            )?
        } else {
            None
        };
        if self.requires_schema_validation()
            && (self.conn.schema_cookie() != self.schema_cookie
                || self.conn.schema_generation() != self.schema_generation)
        {
            let invalidate_reason = if self.conn.schema_cookie() != self.schema_cookie {
                "schema_cookie_changed"
            } else {
                "schema_generation_changed"
            };
            let failure_diag = format!(
                "prepared_schema_identity={} current_schema_identity={}",
                format_schema_identity(self.schema_cookie, self.schema_generation),
                self.conn.current_schema_identity()
            );
            self.conn.log_statement_reuse_event(
                "prepared_schema_validation",
                &self.sql,
                false,
                invalidate_reason,
                0,
                0,
                failure_diag.as_str(),
            );
            return Err(FrankenError::SchemaChanged);
        }
        Ok(PreparedDmlEntryProof {
            publication: prebound_publication,
            microbatch_carry_verified_in_txn: false,
        })
    }

    /// Returns `true` if this prepared statement is a DML statement
    /// (INSERT/UPDATE/DELETE).
    pub fn is_dml(&self) -> bool {
        self.dml_dispatch.is_some()
    }

    fn can_use_query_row_result_row_cap(&self) -> bool {
        self.deferred_query_statement.is_none()
            && !self.distinct
            && self.post_distinct_limit.is_none()
            && match self.expression_postprocess.as_ref() {
                Some(postprocess) => postprocess.order_by.is_empty() && postprocess.limit.is_none(),
                None => true,
            }
    }

    fn execute_table_program_with_reuse(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        track_last_insert_rowid: bool,
        prebound_publication: Option<BoundPagerPublication>,
    ) -> Result<(Vec<Row>, usize, Option<i64>)> {
        self.execute_table_program_with_reuse_mode(
            op_cx,
            params,
            track_last_insert_rowid,
            true,
            None,
            None,
            prebound_publication,
            false,
        )
    }

    fn execute_table_query_with_row_handler(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        prebound_publication: Option<BoundPagerPublication>,
        row_handler: &mut QueryRowHandler<'_>,
    ) -> Result<()> {
        self.execute_table_program_with_reuse_mode(
            op_cx,
            params,
            false,
            false,
            None,
            Some(row_handler),
            prebound_publication,
            false,
        )
        .map(|_| ())
    }

    fn execute_table_program_dml_with_reuse(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        track_last_insert_rowid: bool,
    ) -> Result<(usize, Option<i64>)> {
        if self.prepared_update_delete_fast_path().is_some()
            && self.conn.active_txn.borrow().is_some()
        {
            if hot_path_profile_enabled() {
                FSQLITE_PREPARED_UPDATE_DELETE_FAST_LANE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            return self.execute_update_delete_table_program_dml_with_reuse_active_txn(
                op_cx,
                params,
                track_last_insert_rowid,
            );
        }
        if hot_path_profile_enabled() {
            FSQLITE_PREPARED_UPDATE_DELETE_INSTRUMENTED_LANE_HITS
                .fetch_add(1, AtomicOrdering::Relaxed);
        }
        self.execute_table_program_with_reuse_mode(
            op_cx,
            params,
            track_last_insert_rowid,
            false,
            None,
            None,
            None,
            true,
        )
        .map(|(_, changes, last_insert_rowid)| (changes, last_insert_rowid))
    }

    fn execute_update_delete_table_program_dml_with_reuse_active_txn(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        track_last_insert_rowid: bool,
    ) -> Result<(usize, Option<i64>)> {
        let Some(db) = self.db.as_ref() else {
            return Err(FrankenError::Internal(
                "prepared table program missing database handle".to_owned(),
            ));
        };
        let Some(func_registry) = self.func_registry.as_ref() else {
            return Err(FrankenError::Internal(
                "prepared table program missing function registry".to_owned(),
            ));
        };
        let page_size = page_size_from_pragma_state(self.conn.pragma_state.borrow().page_size)?;

        let execution_span = tracing::enabled!(target: "fsqlite.execution", tracing::Level::DEBUG)
            .then(|| {
                let span = tracing::span!(
                    target: "fsqlite.execution",
                    tracing::Level::DEBUG,
                    "execution",
                    mode = "table_dml"
                );
                record_trace_span_created();
                span
            });
        let _execution_guard = execution_span.as_ref().map(tracing::Span::enter);

        let reject_mem = *self.conn.reject_mem_fallback.borrow();
        let (runtime_requirements, static_runtime_inputs) =
            self.prepared_table_program_runtime_inputs();
        let runtime_inputs = static_runtime_inputs.unwrap_or_else(|| {
            self.conn
                .table_execution_runtime_inputs(runtime_requirements)
        });
        let cookie = *self.conn.schema_cookie.borrow();
        let txn = self.conn.active_txn.borrow_mut().take().ok_or_else(|| {
            FrankenError::Internal(
                "prepared UPDATE/DELETE DML handoff expected active transaction".to_owned(),
            )
        })?;
        let concurrent_ctx = self.conn.concurrent_exec_context()?;

        let cached = self.conn.cached_vdbe_engine.borrow_mut().take();
        let ((result, txn_back), engine_back) = execute_table_program_with_db(
            self.program.as_ref(),
            params,
            func_registry,
            &self.conn.collation_registry,
            op_cx,
            db,
            Some(txn),
            cookie,
            concurrent_ctx,
            runtime_inputs.autoincrement_seq_by_root_page,
            runtime_inputs.rowid_alias_col_by_root_page,
            runtime_inputs.table_column_count_by_root_page,
            runtime_inputs.first_not_null_non_ipk_col_by_root_page,
            runtime_inputs.column_defaults_by_root_page,
            runtime_inputs.index_desc_flags_by_root_page,
            runtime_inputs.index_collations_by_root_page,
            reject_mem,
            self.conn.memdb_rows_loaded.get(),
            self.conn.memdb_storage_count_shortcuts_safe.get(),
            self.conn.version_store_for_program(self.program.as_ref()),
            page_size,
            false,
            None,
            None,
            false,
            true,
            cached,
        );
        let memdb_count_shortcuts_safe_after_exec = engine_back
            .as_ref()
            .is_some_and(|engine| engine.storage_cursor_memdb_count_shortcuts_safe());
        *self.conn.cached_vdbe_engine.borrow_mut() = engine_back;
        *self.conn.active_txn.borrow_mut() = txn_back;

        match result {
            Ok((_rows, changes, last_insert_rowid)) => {
                if hot_path_profile_enabled() {
                    FSQLITE_PREPARED_UPDATE_DELETE_DML_DIRECT_HANDOFF_RUNS
                        .fetch_add(1, AtomicOrdering::Relaxed);
                }
                self.conn.clear_table_program_error_state();
                let keep_memdb_stale_until_read_boundary =
                    self.conn.in_transaction.get() && !self.conn.implicit_txn.get();
                if keep_memdb_stale_until_read_boundary {
                    // Repeated prepared UPDATE/DELETE loops in an explicit
                    // transaction do not need an eagerly maintained MemDatabase
                    // mirror between writes. Mark it stale once and refresh on
                    // the next read boundary instead of paying per-write mirror
                    // upkeep through the whole batch.
                    self.conn.memdb_storage_count_shortcuts_safe.set(false);
                    self.conn.memdb_rows_loaded.set(false);
                    self.conn.memdb_requires_active_txn_reload.set(true);
                } else {
                    self.conn
                        .memdb_storage_count_shortcuts_safe
                        .set(memdb_count_shortcuts_safe_after_exec);
                    if !memdb_count_shortcuts_safe_after_exec {
                        self.conn.memdb_rows_loaded.set(false);
                        self.conn.memdb_requires_active_txn_reload.set(true);
                    }
                }
                if track_last_insert_rowid && let Some(last_insert_rowid) = last_insert_rowid {
                    self.conn
                        .set_last_insert_rowid_without_sync(last_insert_rowid);
                }
                Ok((
                    changes,
                    if track_last_insert_rowid {
                        last_insert_rowid
                    } else {
                        None
                    },
                ))
            }
            Err(exec_error) => {
                self.conn.memdb_storage_count_shortcuts_safe.set(false);
                self.conn.record_table_program_error_state(
                    exec_error.changes,
                    if track_last_insert_rowid {
                        exec_error.last_insert_rowid
                    } else {
                        None
                    },
                );
                Err(exec_error.error)
            }
        }
    }

    fn execute_table_query_row_with_row_cap(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        max_collected_result_rows: usize,
        prebound_publication: Option<BoundPagerPublication>,
    ) -> Result<Row> {
        self.execute_table_program_query_row_with_reuse_mode(
            op_cx,
            params,
            max_collected_result_rows,
            prebound_publication,
        )
    }

    fn execute_table_program_query_row_with_reuse_mode(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        max_collected_result_rows: usize,
        prebound_publication: Option<BoundPagerPublication>,
    ) -> Result<Row> {
        let Some(db) = self.db.as_ref() else {
            return Err(FrankenError::Internal(
                "prepared table program missing database handle".to_owned(),
            ));
        };
        let Some(func_registry) = self.func_registry.as_ref() else {
            return Err(FrankenError::Internal(
                "prepared table program missing function registry".to_owned(),
            ));
        };
        let page_size = page_size_from_pragma_state(self.conn.pragma_state.borrow().page_size)?;

        let execution_span = tracing::enabled!(target: "fsqlite.execution", tracing::Level::DEBUG)
            .then(|| {
                let span = tracing::span!(
                    target: "fsqlite.execution",
                    tracing::Level::DEBUG,
                    "execution",
                    mode = "table_query_row"
                );
                record_trace_span_created();
                span
            });
        let _execution_guard = execution_span.as_ref().map(tracing::Span::enter);

        let reject_mem = *self.conn.reject_mem_fallback.borrow();
        let (runtime_requirements, static_runtime_inputs) =
            self.prepared_table_program_runtime_inputs();
        let runtime_inputs = static_runtime_inputs.unwrap_or_else(|| {
            self.conn
                .table_execution_runtime_inputs(runtime_requirements)
        });
        let cookie = *self.conn.schema_cookie.borrow();
        let had_active_txn = self.conn.active_txn.borrow().is_some();
        let inherited_implicit_read_txn =
            had_active_txn && self.conn.implicit_txn.get() && !self.conn.in_transaction.get();
        let had_owned_txn = had_active_txn && !inherited_implicit_read_txn;

        let (result, txn_back, was_auto, memdb_count_shortcuts_safe_after_exec) = if had_owned_txn {
            let txn = self.conn.active_txn.borrow_mut().take();
            let concurrent_ctx = self.conn.concurrent_exec_context()?;

            let cached = self.conn.cached_vdbe_engine.borrow_mut().take();
            let ((result, txn_back), engine_back) = execute_table_program_exactly_one_row_with_db(
                self.program.as_ref(),
                params,
                func_registry,
                &self.conn.collation_registry,
                op_cx,
                db,
                txn,
                cookie,
                concurrent_ctx,
                runtime_inputs.autoincrement_seq_by_root_page,
                runtime_inputs.rowid_alias_col_by_root_page,
                runtime_inputs.table_column_count_by_root_page,
                runtime_inputs.first_not_null_non_ipk_col_by_root_page,
                runtime_inputs.column_defaults_by_root_page,
                runtime_inputs.index_desc_flags_by_root_page,
                runtime_inputs.index_collations_by_root_page,
                reject_mem,
                self.conn.memdb_rows_loaded.get(),
                self.conn.memdb_storage_count_shortcuts_safe.get(),
                self.conn.version_store_for_program(self.program.as_ref()),
                page_size,
                max_collected_result_rows,
                true,
                cached,
            );
            let memdb_count_shortcuts_safe_after_exec = engine_back
                .as_ref()
                .is_some_and(|engine| engine.storage_cursor_memdb_count_shortcuts_safe());
            *self.conn.cached_vdbe_engine.borrow_mut() = engine_back;
            (
                result,
                txn_back,
                false,
                memdb_count_shortcuts_safe_after_exec,
            )
        } else {
            let was_auto = if inherited_implicit_read_txn {
                true
            } else {
                self.conn.ensure_autocommit_txn_mode_with_cx(
                    TransactionMode::ReadOnly,
                    op_cx,
                    prebound_publication,
                )?
            };
            let txn = self.conn.active_txn.borrow_mut().take();
            let cached = self.conn.cached_vdbe_engine.borrow_mut().take();
            let ((result, txn_back), engine_back) = execute_table_program_exactly_one_row_with_db(
                self.program.as_ref(),
                params,
                func_registry,
                &self.conn.collation_registry,
                op_cx,
                db,
                txn,
                cookie,
                None,
                runtime_inputs.autoincrement_seq_by_root_page,
                runtime_inputs.rowid_alias_col_by_root_page,
                runtime_inputs.table_column_count_by_root_page,
                runtime_inputs.first_not_null_non_ipk_col_by_root_page,
                runtime_inputs.column_defaults_by_root_page,
                runtime_inputs.index_desc_flags_by_root_page,
                runtime_inputs.index_collations_by_root_page,
                reject_mem,
                self.conn.memdb_rows_loaded.get(),
                self.conn.memdb_storage_count_shortcuts_safe.get(),
                self.conn.version_store_for_program(self.program.as_ref()),
                page_size,
                max_collected_result_rows,
                true,
                cached,
            );
            let memdb_count_shortcuts_safe_after_exec = engine_back
                .as_ref()
                .is_some_and(|engine| engine.storage_cursor_memdb_count_shortcuts_safe());
            *self.conn.cached_vdbe_engine.borrow_mut() = engine_back;
            (
                result,
                txn_back,
                was_auto,
                memdb_count_shortcuts_safe_after_exec,
            )
        };

        if result.is_ok() {
            self.conn
                .memdb_storage_count_shortcuts_safe
                .set(memdb_count_shortcuts_safe_after_exec);
        }

        *self.conn.active_txn.borrow_mut() = txn_back;
        if !had_owned_txn {
            self.conn.resolve_autocommit_txn_with_capture_and_cx(
                was_auto,
                result.is_ok(),
                false,
                op_cx,
            )?;
        }

        match result {
            Ok((row_outcome, ..)) => {
                self.conn.clear_table_program_error_state();
                match row_outcome {
                    QueryRowCollectionOutcome::Row(row) => Ok(row),
                    QueryRowCollectionOutcome::NoRows => Err(FrankenError::QueryReturnedNoRows),
                    QueryRowCollectionOutcome::MultipleRows => {
                        Err(FrankenError::QueryReturnedMultipleRows)
                    }
                }
            }
            Err(exec_error) => {
                self.conn.record_table_program_error_state(
                    exec_error.changes,
                    exec_error.last_insert_rowid,
                );
                Err(exec_error.error)
            }
        }
    }

    #[allow(clippy::fn_params_excessive_bools, clippy::too_many_arguments)]
    fn execute_table_program_with_reuse_mode(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        track_last_insert_rowid: bool,
        collect_rows: bool,
        max_collected_result_rows: Option<usize>,
        row_handler: Option<&mut QueryRowHandler<'_>>,
        prebound_publication: Option<BoundPagerPublication>,
        invalidate_memdb_count_shortcuts_on_success: bool,
    ) -> Result<(Vec<Row>, usize, Option<i64>)> {
        let Some(db) = self.db.as_ref() else {
            return Err(FrankenError::Internal(
                "prepared table program missing database handle".to_owned(),
            ));
        };
        let Some(func_registry) = self.func_registry.as_ref() else {
            return Err(FrankenError::Internal(
                "prepared table program missing function registry".to_owned(),
            ));
        };
        let page_size = page_size_from_pragma_state(self.conn.pragma_state.borrow().page_size)?;

        let execution_span = tracing::enabled!(target: "fsqlite.execution", tracing::Level::DEBUG)
            .then(|| {
                let span = tracing::span!(
                    target: "fsqlite.execution",
                    tracing::Level::DEBUG,
                    "execution",
                    mode = "table"
                );
                record_trace_span_created();
                span
            });
        let _execution_guard = execution_span.as_ref().map(tracing::Span::enter);

        let reject_mem = *self.conn.reject_mem_fallback.borrow();
        let (runtime_requirements, static_runtime_inputs) =
            self.prepared_table_program_runtime_inputs();
        let runtime_inputs = static_runtime_inputs.unwrap_or_else(|| {
            self.conn
                .table_execution_runtime_inputs(runtime_requirements)
        });
        let cookie = *self.conn.schema_cookie.borrow();
        let had_active_txn = self.conn.active_txn.borrow().is_some();
        let inherited_implicit_read_txn =
            had_active_txn && self.conn.implicit_txn.get() && !self.conn.in_transaction.get();
        let had_owned_txn = had_active_txn && !inherited_implicit_read_txn;

        let (result, txn_back, was_auto, memdb_count_shortcuts_safe_after_exec) = if had_owned_txn {
            let txn = self.conn.active_txn.borrow_mut().take();
            let concurrent_ctx = self.conn.concurrent_exec_context()?;

            let cached = self.conn.cached_vdbe_engine.borrow_mut().take();
            let ((result, txn_back), engine_back) = execute_table_program_with_db(
                self.program.as_ref(),
                params,
                func_registry,
                &self.conn.collation_registry,
                op_cx,
                db,
                txn,
                cookie,
                concurrent_ctx,
                runtime_inputs.autoincrement_seq_by_root_page,
                runtime_inputs.rowid_alias_col_by_root_page,
                runtime_inputs.table_column_count_by_root_page,
                runtime_inputs.first_not_null_non_ipk_col_by_root_page,
                runtime_inputs.column_defaults_by_root_page,
                runtime_inputs.index_desc_flags_by_root_page,
                runtime_inputs.index_collations_by_root_page,
                reject_mem,
                self.conn.memdb_rows_loaded.get(),
                self.conn.memdb_storage_count_shortcuts_safe.get(),
                self.conn.version_store_for_program(self.program.as_ref()),
                page_size,
                collect_rows,
                max_collected_result_rows,
                row_handler,
                invalidate_memdb_count_shortcuts_on_success,
                true,
                cached,
            );
            let memdb_count_shortcuts_safe_after_exec = engine_back
                .as_ref()
                .is_some_and(|engine| engine.storage_cursor_memdb_count_shortcuts_safe());
            *self.conn.cached_vdbe_engine.borrow_mut() = engine_back;
            (
                result,
                txn_back,
                false,
                memdb_count_shortcuts_safe_after_exec,
            )
        } else {
            let was_auto = if inherited_implicit_read_txn {
                true
            } else {
                self.conn.ensure_autocommit_txn_mode_with_cx(
                    TransactionMode::ReadOnly,
                    op_cx,
                    prebound_publication,
                )?
            };
            let txn = self.conn.active_txn.borrow_mut().take();
            let cached = self.conn.cached_vdbe_engine.borrow_mut().take();
            let ((result, txn_back), engine_back) = execute_table_program_with_db(
                self.program.as_ref(),
                params,
                func_registry,
                &self.conn.collation_registry,
                op_cx,
                db,
                txn,
                cookie,
                None,
                runtime_inputs.autoincrement_seq_by_root_page,
                runtime_inputs.rowid_alias_col_by_root_page,
                runtime_inputs.table_column_count_by_root_page,
                runtime_inputs.first_not_null_non_ipk_col_by_root_page,
                runtime_inputs.column_defaults_by_root_page,
                runtime_inputs.index_desc_flags_by_root_page,
                runtime_inputs.index_collations_by_root_page,
                reject_mem,
                self.conn.memdb_rows_loaded.get(),
                self.conn.memdb_storage_count_shortcuts_safe.get(),
                self.conn.version_store_for_program(self.program.as_ref()),
                page_size,
                collect_rows,
                max_collected_result_rows,
                row_handler,
                invalidate_memdb_count_shortcuts_on_success,
                true,
                cached,
            );
            let memdb_count_shortcuts_safe_after_exec = engine_back
                .as_ref()
                .is_some_and(|engine| engine.storage_cursor_memdb_count_shortcuts_safe());
            *self.conn.cached_vdbe_engine.borrow_mut() = engine_back;
            (
                result,
                txn_back,
                was_auto,
                memdb_count_shortcuts_safe_after_exec,
            )
        };

        if invalidate_memdb_count_shortcuts_on_success && result.is_ok() {
            self.conn
                .memdb_storage_count_shortcuts_safe
                .set(memdb_count_shortcuts_safe_after_exec);
            if !memdb_count_shortcuts_safe_after_exec {
                self.conn.memdb_rows_loaded.set(false);
                self.conn.memdb_requires_active_txn_reload.set(true);
            }
        }

        *self.conn.active_txn.borrow_mut() = txn_back;
        if !had_owned_txn {
            self.conn.resolve_autocommit_txn_with_capture_and_cx(
                was_auto,
                result.is_ok(),
                false,
                op_cx,
            )?;
        }

        match result {
            Ok((rows, changes, last_insert_rowid)) => {
                self.conn.clear_table_program_error_state();
                if track_last_insert_rowid && let Some(last_insert_rowid) = last_insert_rowid {
                    self.conn
                        .set_last_insert_rowid_without_sync(last_insert_rowid);
                }
                if invalidate_memdb_count_shortcuts_on_success {
                    self.conn
                        .memdb_storage_count_shortcuts_safe
                        .set(memdb_count_shortcuts_safe_after_exec);
                }
                Ok((
                    rows,
                    changes,
                    if track_last_insert_rowid {
                        last_insert_rowid
                    } else {
                        None
                    },
                ))
            }
            Err(exec_error) => {
                if invalidate_memdb_count_shortcuts_on_success {
                    self.conn.memdb_storage_count_shortcuts_safe.set(false);
                }
                self.conn.record_table_program_error_state(
                    exec_error.changes,
                    if track_last_insert_rowid {
                        exec_error.last_insert_rowid
                    } else {
                        None
                    },
                );
                Err(exec_error.error)
            }
        }
    }

    fn execute_table_query(
        &self,
        op_cx: &Cx,
        params: Option<&[SqliteValue]>,
        prebound_publication: Option<BoundPagerPublication>,
    ) -> Result<Vec<Row>> {
        self.execute_table_program_with_reuse(op_cx, params, false, prebound_publication)
            .map(|(rows, ..)| rows)
    }

    /// Execute as a query and return all result rows.
    pub fn query(&self) -> Result<Vec<Row>> {
        self.conn.background_status()?;
        self.conn
            .query_prepared_with_params_after_background_status(self, &[])
    }

    /// Execute as a query with bound SQL parameters (`?1`, `?2`, ...).
    pub fn query_with_params(&self, params: &[SqliteValue]) -> Result<Vec<Row>> {
        self.conn.background_status()?;
        if let Some(rows) = self.try_query_clean_memory_indexed_equality_fast(params)? {
            return Ok(rows);
        }
        self.conn
            .query_prepared_with_params_after_background_status(self, params)
    }

    /// Execute as a query with bound SQL parameters, invoking `f` for each row.
    pub fn query_with_params_for_each<F>(&self, params: &[SqliteValue], f: F) -> Result<()>
    where
        F: FnMut(&Row) -> Result<()>,
    {
        self.conn.background_status()?;
        self.conn
            .query_prepared_with_params_for_each_after_background_status(self, params, f)
    }

    /// Execute as a query and return exactly one row.
    pub fn query_row(&self) -> Result<Row> {
        self.query_row_internal(None)
    }

    /// Execute as a query with parameters and return exactly one row.
    pub fn query_row_with_params(&self, params: &[SqliteValue]) -> Result<Row> {
        self.query_row_internal(Some(params))
    }

    fn query_row_internal(&self, params: Option<&[SqliteValue]>) -> Result<Row> {
        self.conn.background_status()?;
        if let Some(params) = params
            && let Some(row_outcome) = self.try_query_row_clean_memory_rowid_lookup_fast(params)?
        {
            return direct_query_row_outcome_result(row_outcome);
        }
        if params.is_none()
            && let Some(row) = self.try_query_row_clean_memory_count_star_fast()?
        {
            return Ok(direct_query_row_result(row));
        }
        if params.is_none()
            && let Some(row) = self.try_query_row_clean_memory_count_indexed_rowid_probe_fast()?
        {
            return Ok(direct_query_row_result(row));
        }
        self.conn
            .query_prepared_row_after_background_status(self, params)
    }

    /// Return the number of columns this statement will produce per row.
    #[must_use]
    pub fn column_count(&self) -> usize {
        if let Some(column_count) = self.deferred_query_column_count {
            return column_count;
        }
        self.program
            .ops()
            .iter()
            .find(|op| op.opcode == Opcode::ResultRow)
            .and_then(|op| usize::try_from(op.p2).ok())
            .unwrap_or(0)
    }

    /// Return best-effort result column labels inferred at prepare time.
    #[must_use]
    pub fn column_names(&self) -> &[String] {
        &self.column_names
    }

    /// Execute and return affected/output row count.
    ///
    /// For DML statements (INSERT/UPDATE/DELETE), this delegates to the
    /// parent Connection's execution pipeline, which handles triggers,
    /// constraints, and autocommit.  For SELECT statements, this returns
    /// the number of result rows.
    pub fn execute(&self) -> Result<usize> {
        if self.dml_dispatch.is_some() {
            return self.conn.execute_prepared(self);
        }
        Ok(self.query()?.len())
    }

    /// Execute with bound SQL parameters and return affected/output row count.
    ///
    /// For DML statements (INSERT/UPDATE/DELETE), this delegates to the
    /// parent Connection's execution pipeline, which handles triggers,
    /// constraints, and autocommit.  For SELECT statements, this returns
    /// the number of result rows.
    pub fn execute_with_params(&self, params: &[SqliteValue]) -> Result<usize> {
        if self.dml_dispatch.is_some() {
            return self.conn.execute_prepared_with_params(self, params);
        }
        Ok(self.query_with_params(params)?.len())
    }

    /// Return an EXPLAIN-style disassembly for the compiled program.
    pub fn explain(&self) -> String {
        if self.deferred_query_statement.is_some() {
            return "-- prepared SELECT is dispatched dynamically; no precompiled bytecode"
                .to_owned();
        }
        if self
            .precompiled_dml()
            .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
            .is_some_and(|direct| {
                !Connection::direct_simple_insert_prefers_reusable_table_program(direct)
            })
        {
            return "-- prepared INSERT uses the direct compiled lane; VDBE fallback is compiled lazily"
                .to_owned();
        }
        self.program.disassemble()
    }
}

/// A stored view definition: name + SELECT query.
#[derive(Debug, Clone)]
struct ViewDef {
    name: String,
    #[allow(dead_code)] // Retained for future PRAGMA table_info(view) and schema introspection.
    columns: Vec<String>,
    query: SelectStatement,
}

/// Connection-local differential stream events emitted to subscribers.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DifferentialEvent {
    /// Initial bootstrap payload captured at a committed MVCC snapshot.
    Snapshot {
        subscriber_id: u64,
        view_name: String,
        snapshot_seq: u64,
        next_commit_seq: u64,
        rows: Vec<Row>,
    },
    /// Placeholder stream mode until table-level differential routing lands.
    Invalidation {
        subscriber_id: u64,
        view_name: String,
        commit_seq: u64,
    },
}

/// Public status snapshot for one active differential subscriber.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DifferentialSubscriberStatus {
    pub subscriber_id: u64,
    pub view_name: String,
    pub snapshot_seq: u64,
    pub next_commit_seq: u64,
    pub bootstrap_row_count: usize,
}

#[derive(Clone)]
struct DifferentialSubscriber {
    id: u64,
    view_name: String,
    #[allow(dead_code)]
    // Needed for incremental view maintenance (re-eval delta on schema change).
    view_query: SelectStatement,
    snapshot_seq: CommitSeq,
    stream_begin_seq: CommitSeq,
    bootstrap_row_count: usize,
    sender: mpsc::Sender<DifferentialEvent>,
}

#[derive(Default)]
struct DifferentialRegistry {
    next_subscriber_id: AtomicU64,
    active_subscriber_count: AtomicUsize,
    subscribers: Mutex<HashMap<u64, DifferentialSubscriber>>,
    snapshot_bootstraps_total: AtomicU64,
    fallback_invalidations_total: AtomicU64,
}

/// A stored trigger definition captured from `CREATE TRIGGER`.
#[derive(Debug, Clone)]
struct TriggerDef {
    name: String,
    table_name: String,
    timing: fsqlite_ast::TriggerTiming,
    event: fsqlite_ast::TriggerEvent,
    #[allow(dead_code)] // SQLite-only: always true; retained for display/roundtrip fidelity.
    for_each_row: bool,
    when_clause: Option<Expr>,
    body: Vec<Statement>,
    temporary: bool,
    create_sql: String,
}

impl TriggerDef {
    fn from_create_statement(
        stmt: &fsqlite_ast::CreateTriggerStatement,
        create_sql: String,
    ) -> Self {
        Self {
            name: stmt.name.name.clone(),
            table_name: stmt.table.clone(),
            timing: stmt.timing,
            event: stmt.event.clone(),
            for_each_row: stmt.for_each_row,
            when_clause: stmt.when.clone(),
            body: stmt.body.clone(),
            temporary: stmt.temporary,
            create_sql,
        }
    }
}

#[derive(Debug, Clone)]
struct TriggerFrame {
    table_name: String,
    /// Name of the trigger being executed (for recursive_triggers guard).
    trigger_name: String,
    column_names: Vec<String>,
    rowid_alias_col_idx: Option<usize>,
    old_row: Option<Vec<SqliteValue>>,
    new_row: Option<Vec<SqliteValue>>,
}

impl TriggerFrame {
    fn column_index(&self, column_name: &str) -> Option<usize> {
        self.column_names
            .iter()
            .position(|name| name.eq_ignore_ascii_case(column_name))
    }

    fn references_pseudo_column(&self, table_prefix: Option<&str>, column_name: &str) -> bool {
        let hidden_rowid = self.hidden_rowid_column_index(column_name);
        if self.column_index(column_name).is_none() && hidden_rowid.is_none() {
            return false;
        }
        match table_prefix {
            Some(prefix) => {
                prefix.eq_ignore_ascii_case("old")
                    || prefix.eq_ignore_ascii_case("new")
                    || prefix.eq_ignore_ascii_case(&self.table_name)
            }
            // Bare column references (no table prefix) resolve to NEW/OLD
            // in trigger SELECT bodies (e.g. SELECT RAISE(...) WHERE val > 10).
            // DML trigger bodies (UPDATE/DELETE/INSERT) use the dedicated
            // `bind_trigger_prefixed_only_in_expr` which skips bare names so
            // they resolve against the DML's target table instead.
            None => true,
        }
    }

    fn lookup_value(&self, table_prefix: Option<&str>, column_name: &str) -> Option<SqliteValue> {
        let column_index = self
            .column_index(column_name)
            .or_else(|| self.hidden_rowid_column_index(column_name))?;
        match table_prefix {
            Some(prefix) if prefix.eq_ignore_ascii_case("old") => {
                Self::lookup_from_row(self.old_row.as_deref(), column_index)
            }
            Some(prefix) if prefix.eq_ignore_ascii_case("new") => {
                Self::lookup_from_row(self.new_row.as_deref(), column_index)
            }
            Some(prefix) if prefix.eq_ignore_ascii_case(&self.table_name) => self
                .new_row
                .as_ref()
                .and_then(|row| row.get(column_index).cloned())
                .or_else(|| Self::lookup_from_row(self.old_row.as_deref(), column_index)),
            Some(_) => None,
            None => self
                .new_row
                .as_ref()
                .and_then(|row| row.get(column_index).cloned())
                .or_else(|| Self::lookup_from_row(self.old_row.as_deref(), column_index)),
        }
    }

    fn lookup_from_row(row: Option<&[SqliteValue]>, column_index: usize) -> Option<SqliteValue> {
        row.and_then(|values| values.get(column_index).cloned())
    }

    fn hidden_rowid_column_index(&self, column_name: &str) -> Option<usize> {
        self.column_index(column_name)
            .is_none()
            .then_some(self.rowid_alias_col_idx)
            .flatten()
            .filter(|_| is_rowid_alias(column_name))
    }
}

struct TriggerFrameGuard<'a> {
    stack: &'a RefCell<Vec<TriggerFrame>>,
}

impl Drop for TriggerFrameGuard<'_> {
    fn drop(&mut self) {
        let _ = self.stack.borrow_mut().pop();
    }
}

struct StatementSavepointDepthGuard<'a> {
    depth: &'a Cell<usize>,
}

impl Drop for StatementSavepointDepthGuard<'_> {
    fn drop(&mut self) {
        self.depth.set(self.depth.get().saturating_sub(1));
    }
}

/// Check if a trigger event matches a DML event.
///
/// For INSERT/DELETE, this is an exact match.
/// For UPDATE, the trigger event must either be `Update([])` (any column) or
/// `Update([cols])` where at least one of the specified columns is being updated.
fn trigger_event_matches(
    trigger_event: &fsqlite_ast::TriggerEvent,
    dml_event: &fsqlite_ast::TriggerEvent,
) -> bool {
    use fsqlite_ast::TriggerEvent;
    match (trigger_event, dml_event) {
        (TriggerEvent::Insert, TriggerEvent::Insert)
        | (TriggerEvent::Delete, TriggerEvent::Delete) => true,
        (TriggerEvent::Update(trigger_cols), TriggerEvent::Update(dml_cols)) => {
            // If trigger specifies no columns (UPDATE OF <nothing>), match any UPDATE.
            if trigger_cols.is_empty() {
                return true;
            }
            // If DML specifies no columns, treat as "all columns" - match any trigger.
            if dml_cols.is_empty() {
                return true;
            }
            // Otherwise, check if any trigger column is in the DML column list.
            trigger_cols
                .iter()
                .any(|tc| dml_cols.iter().any(|dc| tc.eq_ignore_ascii_case(dc)))
        }
        _ => false,
    }
}

/// Evaluate a trigger WHEN clause against the current OLD/NEW frame.
///
/// Uses the connection-level evaluator so scalar subqueries and EXISTS
/// predicates honor bound OLD/NEW values instead of conservatively firing on a
/// join-evaluator fallback.
fn trigger_when_matches(
    connection: &Connection,
    when_clause: Option<&Expr>,
    frame: Option<&TriggerFrame>,
) -> Result<bool> {
    let Some(expr) = when_clause else {
        return Ok(true);
    };
    let mut bound_expr = expr.clone();
    if let Some(active_frame) = frame {
        bind_trigger_columns_in_expr(&mut bound_expr, active_frame);
    }
    let row: [SqliteValue; 0] = [];
    let col_map: [(String, String, bool); 0] = [];
    // Binding rewrites OLD/NEW references to literals before evaluation, but
    // an explicit COLLATE on those literals must still use the connection's
    // registered comparator.  Without a join-evaluation context,
    // `compare_join_expr_values` deliberately falls back to bytewise
    // comparison, so `NEW.label COLLATE NOCASE = 'fire'` incorrectly becomes
    // false for a bound value such as `FiRe`.  No live columns remain in this
    // outer expression, hence the empty metadata vectors; nested SELECTs push
    // their own column context while inheriting the same registry stack.
    let _join_eval_collation_guard =
        JoinEvalCollationContextGuard::push(JoinEvalCollationContext {
            column_collations: Vec::new(),
            column_affinities: Vec::new(),
            registry: lock_unpoisoned(connection.collation_registry.as_ref()).clone(),
        });
    connection
        .eval_expr_with_subqueries(&bound_expr, &row, &col_map, None)
        .map(|value| is_sqlite_truthy(&value))
}

/// For `UPDATE OF col1, col2` triggers, ensure at least one listed column
/// actually changed between OLD and NEW snapshots.
#[derive(Debug, Clone)]
struct TriggerRaiseDirective {
    action: fsqlite_ast::RaiseAction,
    message: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TriggerStatementOutcome {
    Continue,
    SkipDml,
}

/// Describes the action to take when a FK-referenced parent row is deleted.
#[allow(dead_code)]
enum FkDeleteAction {
    /// No child rows reference this parent — deletion is allowed.
    Allow,
    /// Child rows exist and ON DELETE CASCADE is specified.
    Cascade {
        child_table: String,
        child_columns: Vec<String>,
        parent_values: Vec<SqliteValue>,
    },
    /// Child rows exist and ON DELETE SET NULL is specified.
    SetNull {
        child_table: String,
        child_columns: Vec<String>,
        parent_values: Vec<SqliteValue>,
    },
    /// Child rows exist and ON DELETE SET DEFAULT is specified.
    SetDefault {
        child_table: String,
        child_columns: Vec<String>,
        /// SQL DEFAULT expression text per child column (`NULL` if none).
        child_defaults: Vec<String>,
        parent_values: Vec<SqliteValue>,
    },
}

/// Describes the action to take when a FK-referenced parent row is updated.
#[allow(dead_code)]
enum FkUpdateAction {
    Allow,
    Cascade {
        child_table: String,
        child_columns: Vec<String>,
        old_parent_values: Vec<SqliteValue>,
        new_parent_values: Vec<SqliteValue>,
    },
    SetNull {
        child_table: String,
        child_columns: Vec<String>,
        old_parent_values: Vec<SqliteValue>,
    },
    SetDefault {
        child_table: String,
        child_columns: Vec<String>,
        /// SQL DEFAULT expression text per child column (`NULL` if none).
        child_defaults: Vec<String>,
        old_parent_values: Vec<SqliteValue>,
    },
}

fn trigger_statement_raise_directive(
    statement: &Statement,
) -> Result<Option<TriggerRaiseDirective>> {
    let Statement::Select(select) = statement else {
        return Ok(None);
    };
    if select.with.is_some() || !select.order_by.is_empty() || select.limit.is_some() {
        return Ok(None);
    }
    if !select.body.compounds.is_empty() {
        return Ok(None);
    }

    let SelectCore::Select {
        columns,
        from,
        where_clause,
        group_by,
        having,
        windows,
        ..
    } = &select.body.select
    else {
        return Ok(None);
    };
    if from.is_some() || !group_by.is_empty() || having.is_some() || !windows.is_empty() {
        return Ok(None);
    }
    if columns.len() != 1 {
        return Ok(None);
    }

    let ResultColumn::Expr {
        expr: Expr::Raise {
            action, message, ..
        },
        ..
    } = &columns[0]
    else {
        return Ok(None);
    };

    if let Some(predicate) = where_clause {
        let row: [SqliteValue; 0] = [];
        let col_map: [(String, String, bool); 0] = [];
        let predicate_val = eval_join_expr(predicate, &row, &col_map)?;
        if !is_sqlite_truthy(&predicate_val) {
            return Ok(None);
        }
    }

    Ok(Some(TriggerRaiseDirective {
        action: *action,
        message: message.clone(),
    }))
}

/// Returns true if the statement is a `SELECT RAISE(...)` (with or without a
/// WHERE clause).  Used by `execute_bound_trigger_statement` to skip
/// RAISE-containing SELECTs whose WHERE clause evaluated to false.
fn statement_is_raise_select(statement: &Statement) -> bool {
    let Statement::Select(select) = statement else {
        return false;
    };
    let SelectCore::Select { columns, .. } = &select.body.select else {
        return false;
    };
    columns.len() == 1
        && matches!(
            &columns[0],
            ResultColumn::Expr {
                expr: Expr::Raise { .. },
                ..
            }
        )
}

fn select_is_plain_count_star(select: &SelectStatement) -> bool {
    if select.with.is_some() || !select.order_by.is_empty() || select.limit.is_some() {
        return false;
    }
    if !select.body.compounds.is_empty() {
        return false;
    }

    let SelectCore::Select {
        distinct,
        columns,
        from: Some(from),
        where_clause,
        group_by,
        having,
        windows,
    } = &select.body.select
    else {
        return false;
    };
    if *distinct != Distinctness::All
        || where_clause.is_some()
        || !group_by.is_empty()
        || having.is_some()
        || !windows.is_empty()
        || !from.joins.is_empty()
    {
        return false;
    }
    if columns.len() != 1 {
        return false;
    }

    matches!(
        &columns[0],
        ResultColumn::Expr {
            expr: Expr::FunctionCall {
                name,
                args: FunctionArgs::Star,
                distinct: false,
                order_by,
                filter: None,
                over: None,
                ..
            },
            ..
        } if name.eq_ignore_ascii_case("count") && order_by.is_empty()
    )
}

fn select_table_rowid_alias_name(
    table: &TableSchema,
    rowid_alias_col_idx: Option<usize>,
) -> Option<&str> {
    rowid_alias_col_idx
        .and_then(|idx| table.columns.get(idx))
        .map(|column| column.name.as_str())
}

fn table_exposes_hidden_rowid_alias(table: &TableSchema, name: &str) -> bool {
    !table.without_rowid && is_rowid_alias(name) && table.column_index(name).is_none()
}
fn select_table_column_index(table: &TableSchema, table_label: &str, expr: &Expr) -> Option<usize> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    if col_ref
        .table
        .as_deref()
        .is_some_and(|candidate| !candidate.eq_ignore_ascii_case(table_label))
    {
        return None;
    }
    table.column_index(&col_ref.column)
}

fn select_table_value_source(
    table: &TableSchema,
    table_label: &str,
    expr: &Expr,
    rowid_alias_name: Option<&str>,
) -> Option<PreparedMemValueSource> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    if col_ref
        .table
        .as_deref()
        .is_some_and(|candidate| !candidate.eq_ignore_ascii_case(table_label))
    {
        return None;
    }
    if column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) {
        Some(PreparedMemValueSource::Rowid)
    } else {
        table
            .column_index(&col_ref.column)
            .map(PreparedMemValueSource::Column)
    }
}

fn prepared_order_by_limit_has_storage_ordered_path(
    table: &TableSchema,
    order_source: PreparedMemValueSource,
    descending: bool,
    nulls_order: NullsOrder,
) -> bool {
    let default_direction = if descending {
        Some(SortDirection::Desc)
    } else {
        Some(SortDirection::Asc)
    };
    if nulls_order != default_nulls_order(default_direction) {
        return false;
    }
    match order_source {
        PreparedMemValueSource::Rowid => !table.without_rowid,
        PreparedMemValueSource::Column(column_index) => {
            let Some(column) = table.columns.get(column_index) else {
                return false;
            };
            table.indexes.iter().any(|index| {
                index.where_clause.is_none()
                    && index
                        .columns
                        .first()
                        .is_some_and(|name| name.eq_ignore_ascii_case(&column.name))
            })
        }
    }
}

fn select_labeled_table_value_source(
    table: &TableSchema,
    table_label: &str,
    expr: &Expr,
    rowid_alias_name: Option<&str>,
) -> Option<PreparedMemValueSource> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    col_ref
        .table
        .as_deref()
        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(table_label))
        .then(|| select_table_value_source(table, table_label, expr, rowid_alias_name))
        .flatten()
}

fn select_unambiguous_join_table_value_source(
    table: &TableSchema,
    table_label: &str,
    other_table: &TableSchema,
    other_table_label: &str,
    expr: &Expr,
    rowid_alias_name: Option<&str>,
    other_rowid_alias_name: Option<&str>,
) -> Option<PreparedMemValueSource> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    if col_ref.table.is_some() {
        return select_labeled_table_value_source(table, table_label, expr, rowid_alias_name);
    }

    let source = if column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) {
        Some(PreparedMemValueSource::Rowid)
    } else {
        table
            .column_index(&col_ref.column)
            .map(PreparedMemValueSource::Column)
    }?;

    let other_matches = column_ref_matches_table_rowid(
        col_ref,
        other_table,
        other_table_label,
        other_rowid_alias_name,
    ) || other_table.column_index(&col_ref.column).is_some();
    (!other_matches).then_some(source)
}

fn column_ref_matches_table_rowid(
    col_ref: &ColumnRef,
    table: &TableSchema,
    table_label: &str,
    rowid_alias_name: Option<&str>,
) -> bool {
    if col_ref
        .table
        .as_deref()
        .is_some_and(|table_name| !table_name.eq_ignore_ascii_case(table_label))
    {
        return false;
    }
    rowid_alias_name.is_some_and(|name| col_ref.column.eq_ignore_ascii_case(name))
        || table_exposes_hidden_rowid_alias(table, &col_ref.column)
}

fn select_numbered_placeholder_index(expr: &Expr) -> Option<usize> {
    let Expr::Placeholder(PlaceholderType::Numbered(index), _) = expr else {
        return None;
    };
    usize::try_from(*index).ok()?.checked_sub(1)
}

fn select_rowid_lookup_parameter_index(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
    rowid_alias_name: Option<&str>,
) -> Option<usize> {
    let Expr::BinaryOp {
        left, op, right, ..
    } = expr
    else {
        return None;
    };
    if *op != BinaryOp::Eq {
        return None;
    }

    match (left.as_ref(), right.as_ref()) {
        (Expr::Column(col_ref, _), value)
            if column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) =>
        {
            select_numbered_placeholder_index(value)
        }
        (value, Expr::Column(col_ref, _))
            if column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) =>
        {
            select_numbered_placeholder_index(value)
        }
        _ => None,
    }
}

fn select_column_lookup_parameter_index(
    expr: &Expr,
    table_label: &str,
    column_name: &str,
) -> Option<usize> {
    let Expr::BinaryOp {
        left, op, right, ..
    } = expr
    else {
        return None;
    };
    if *op != BinaryOp::Eq {
        return None;
    }

    match (left.as_ref(), right.as_ref()) {
        (Expr::Column(col_ref, _), value)
            if col_ref
                .table
                .as_deref()
                .is_none_or(|table| table.eq_ignore_ascii_case(table_label))
                && col_ref.column.eq_ignore_ascii_case(column_name) =>
        {
            select_numbered_placeholder_index(value)
        }
        (value, Expr::Column(col_ref, _))
            if col_ref
                .table
                .as_deref()
                .is_none_or(|table| table.eq_ignore_ascii_case(table_label))
                && col_ref.column.eq_ignore_ascii_case(column_name) =>
        {
            select_numbered_placeholder_index(value)
        }
        _ => None,
    }
}

fn select_rowid_range_parameter_indices(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
    rowid_alias_name: Option<&str>,
) -> Option<(usize, usize)> {
    fn extract_bound(
        expr: &Expr,
        table: &TableSchema,
        table_label: &str,
        rowid_alias_name: Option<&str>,
        expected_op: BinaryOp,
    ) -> Option<usize> {
        let Expr::BinaryOp {
            left, op, right, ..
        } = expr
        else {
            return None;
        };
        if *op != expected_op {
            return None;
        }
        let Expr::Column(col_ref, _) = left.as_ref() else {
            return None;
        };
        if !column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) {
            return None;
        }
        select_numbered_placeholder_index(right)
    }

    let Expr::BinaryOp {
        left, op, right, ..
    } = expr
    else {
        return None;
    };
    if *op != BinaryOp::And {
        return None;
    }

    extract_bound(left, table, table_label, rowid_alias_name, BinaryOp::Ge)
        .zip(extract_bound(
            right,
            table,
            table_label,
            rowid_alias_name,
            BinaryOp::Lt,
        ))
        .or_else(|| {
            extract_bound(right, table, table_label, rowid_alias_name, BinaryOp::Ge).zip(
                extract_bound(left, table, table_label, rowid_alias_name, BinaryOp::Lt),
            )
        })
}

fn select_count_star_rowid_range_parameter_indices(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
    rowid_alias_name: Option<&str>,
) -> Option<(usize, usize)> {
    select_rowid_range_parameter_indices(expr, table, table_label, rowid_alias_name)
}

fn select_integer_literal(expr: &Expr) -> Option<i64> {
    let Expr::Literal(Literal::Integer(value), _) = expr else {
        return None;
    };
    Some(*value)
}

fn select_numeric_literal(expr: &Expr) -> Option<SqliteValue> {
    match expr {
        Expr::Literal(Literal::Integer(value), _) => Some(SqliteValue::Integer(*value)),
        Expr::Literal(Literal::Float(value), _) => Some(SqliteValue::Float(*value)),
        _ => None,
    }
}

fn select_rowid_upper_bound_exclusive(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
    rowid_alias_name: Option<&str>,
) -> Option<i64> {
    let Expr::BinaryOp {
        left, op, right, ..
    } = expr
    else {
        return None;
    };

    let (column_expr, value_expr, inclusive) = match op {
        BinaryOp::Le => (left.as_ref(), right.as_ref(), true),
        BinaryOp::Lt => (left.as_ref(), right.as_ref(), false),
        _ => return None,
    };
    let Expr::Column(col_ref, _) = column_expr else {
        return None;
    };
    if !column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) {
        return None;
    }

    let bound = select_integer_literal(value_expr)?;
    Some(if inclusive {
        bound.saturating_add(1)
    } else {
        bound
    })
}

fn row_from_memdb_row_values(
    rowid: i64,
    values: &[SqliteValue],
    rowid_alias_column_index: Option<usize>,
) -> Row {
    let mut row_values = values.to_vec();
    if let Some(alias_idx) = rowid_alias_column_index.filter(|idx| *idx < row_values.len()) {
        row_values[alias_idx] = SqliteValue::Integer(rowid);
    }
    Row { values: row_values }
}

fn row_from_memdb_value_sources(
    rowid: i64,
    values: &[SqliteValue],
    sources: &[PreparedMemValueSource],
    rowid_alias_column_index: Option<usize>,
) -> Row {
    Row {
        values: sources
            .iter()
            .copied()
            .map(|source| {
                memdb_row_value_with_source(rowid, values, source, rowid_alias_column_index)
            })
            .collect(),
    }
}

fn memdb_row_value_with_rowid_alias(
    rowid: i64,
    values: &[SqliteValue],
    column_index: usize,
    rowid_alias_column_index: Option<usize>,
) -> SqliteValue {
    if Some(column_index) == rowid_alias_column_index {
        SqliteValue::Integer(rowid)
    } else {
        values
            .get(column_index)
            .cloned()
            .unwrap_or(SqliteValue::Null)
    }
}

fn memdb_row_value_with_source(
    rowid: i64,
    values: &[SqliteValue],
    source: PreparedMemValueSource,
    rowid_alias_column_index: Option<usize>,
) -> SqliteValue {
    match source {
        PreparedMemValueSource::Rowid => SqliteValue::Integer(rowid),
        PreparedMemValueSource::Column(column_index) => {
            memdb_row_value_with_rowid_alias(rowid, values, column_index, rowid_alias_column_index)
        }
    }
}

fn sqlite_value_exact_integer_join_key(value: &SqliteValue) -> Option<i64> {
    match normalize_join_key_value(value).as_ref() {
        SqliteValue::Integer(value) => Some(*value),
        SqliteValue::Float(value) => nth_value_integral_f64_to_i64(*value),
        SqliteValue::Null | SqliteValue::Text(_) | SqliteValue::Blob(_) => None,
    }
}

fn memdb_row_integer_join_key_with_source(
    rowid: i64,
    values: &[SqliteValue],
    source: PreparedMemValueSource,
    rowid_alias_column_index: Option<usize>,
) -> Option<i64> {
    match source {
        PreparedMemValueSource::Rowid => Some(rowid),
        PreparedMemValueSource::Column(column_index) => {
            if Some(column_index) == rowid_alias_column_index {
                Some(rowid)
            } else {
                values
                    .get(column_index)
                    .and_then(sqlite_value_exact_integer_join_key)
            }
        }
    }
}

#[inline]
fn push_memdb_value_as_text(output: &mut String, value: &SqliteValue) {
    if let Some(text) = value.as_text_str() {
        output.push_str(text);
        return;
    }
    match value {
        SqliteValue::Null => {}
        SqliteValue::Integer(integer) => {
            let mut buffer = itoa::Buffer::new();
            output.push_str(buffer.format(*integer));
        }
        SqliteValue::Float(_) | SqliteValue::Blob(_) => output.push_str(&value.to_text()),
        SqliteValue::Text(_) => unreachable!("text values return from as_text_str"),
    }
}

fn sqlite_value_matches_like_fast_path(
    value: &SqliteValue,
    matcher: &SqlLikeFastPathMatcher<'_>,
) -> bool {
    match value {
        SqliteValue::Null => false,
        SqliteValue::Text(text) => matcher.matches(text),
        SqliteValue::Blob(bytes) => {
            let text = String::from_utf8_lossy(bytes);
            matcher.matches(&text)
        }
        other => {
            let text = other.to_text();
            matcher.matches(&text)
        }
    }
}

fn memdb_row_matches_like_fast_path(
    rowid: i64,
    values: &[SqliteValue],
    column_index: usize,
    rowid_alias_column_index: Option<usize>,
    matcher: &SqlLikeFastPathMatcher<'_>,
) -> bool {
    if Some(column_index) == rowid_alias_column_index {
        let mut buffer = itoa::Buffer::new();
        return matcher.matches(buffer.format(rowid));
    }
    values
        .get(column_index)
        .is_some_and(|value| sqlite_value_matches_like_fast_path(value, matcher))
}

fn evaluate_prepared_simple_string_projection(
    projection: PreparedSimpleStringProjection,
    rowid: i64,
    row_values: &[SqliteValue],
    rowid_alias_column_index: Option<usize>,
) -> SqliteValue {
    match projection {
        // bd-wwqen.6 B6: Inline LENGTH/UPPER/SUBSTR to avoid eval_scalar_fn
        // string-name dispatch overhead. Exact SQLite semantics preserved.
        PreparedSimpleStringProjection::Length { column_index } => {
            evaluate_memdb_row_value_ref_with_rowid_alias(
                rowid,
                row_values,
                column_index,
                rowid_alias_column_index,
                direct_length,
            )
        }
        PreparedSimpleStringProjection::Upper { column_index } => {
            evaluate_memdb_row_value_ref_with_rowid_alias(
                rowid,
                row_values,
                column_index,
                rowid_alias_column_index,
                direct_upper,
            )
        }
        PreparedSimpleStringProjection::Substr {
            column_index,
            start,
            length,
        } => evaluate_memdb_row_value_ref_with_rowid_alias(
            rowid,
            row_values,
            column_index,
            rowid_alias_column_index,
            |value| direct_substr(value, start, length),
        ),
    }
}

#[inline]
fn evaluate_memdb_row_value_ref_with_rowid_alias(
    rowid: i64,
    values: &[SqliteValue],
    column_index: usize,
    rowid_alias_column_index: Option<usize>,
    f: impl FnOnce(&SqliteValue) -> SqliteValue,
) -> SqliteValue {
    if Some(column_index) == rowid_alias_column_index {
        let rowid_value = SqliteValue::Integer(rowid);
        return f(&rowid_value);
    }
    match values.get(column_index) {
        Some(value) => f(value),
        None => f(&SqliteValue::Null),
    }
}

/// SQLite LENGTH(): returns character count for text, byte count for blob,
/// text length for numeric values, NULL for NULL.
#[allow(clippy::cast_possible_wrap)]
fn direct_length(value: &SqliteValue) -> SqliteValue {
    match value {
        SqliteValue::Null => SqliteValue::Null,
        SqliteValue::Text(s) => {
            let text = s.as_str();
            let len = if text.is_ascii() {
                text.len()
            } else {
                text.chars().count()
            };
            SqliteValue::Integer(len as i64)
        }
        SqliteValue::Blob(b) => SqliteValue::Integer(b.len() as i64),
        SqliteValue::Integer(_) | SqliteValue::Float(_) => {
            SqliteValue::Integer(value.to_text().len() as i64)
        }
    }
}

/// SQLite UPPER(): ASCII uppercase after coercing non-NULL values to text.
fn direct_upper(value: &SqliteValue) -> SqliteValue {
    match value {
        SqliteValue::Null => SqliteValue::Null,
        SqliteValue::Text(text) => SqliteValue::Text(text.as_str().to_ascii_uppercase().into()),
        _ => SqliteValue::Text(value.to_text().to_ascii_uppercase().into()),
    }
}

/// SQLite SUBSTR(str, start [, length]): 1-based indexing, negative start
/// counts from end.  NULL input → NULL.
#[allow(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_possible_wrap
)]
fn direct_substr(value: &SqliteValue, start: i64, length: Option<i64>) -> SqliteValue {
    if value.is_null() {
        return SqliteValue::Null;
    }
    match value {
        SqliteValue::Text(text) => direct_substr_text(text, start, length),
        _ => {
            let text = sqlite_value_to_text(value);
            direct_substr_text(&text, start, length)
        }
    }
}

fn direct_substr_text(text: &str, start: i64, length: Option<i64>) -> SqliteValue {
    if text.is_ascii() {
        return direct_substr_ascii(text, start, length);
    }
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len() as i64;
    let p2 = match start.cmp(&0) {
        std::cmp::Ordering::Less => n + 1 + start,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => start,
    };
    match length {
        Some(length) => {
            let (y, z) = if length < 0 {
                (p2 + length, p2)
            } else {
                (p2, p2 + length)
            };
            let start = (y.max(1) - 1) as usize;
            let end = ((z - 1).max(0) as usize).min(chars.len());
            let start = start.min(chars.len());
            if start < end {
                SqliteValue::Text(chars[start..end].iter().collect::<String>().into())
            } else {
                SqliteValue::Text(String::new().into())
            }
        }
        None => {
            let idx = ((p2.max(1) - 1) as usize).min(chars.len());
            SqliteValue::Text(chars[idx..].iter().collect::<String>().into())
        }
    }
}

fn direct_substr_ascii(text: &str, start: i64, length: Option<i64>) -> SqliteValue {
    let n = text.len() as i64;
    let p2 = match start.cmp(&0) {
        std::cmp::Ordering::Less => n + 1 + start,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => start,
    };
    match length {
        Some(length) => {
            let (y, z) = if length < 0 {
                (p2 + length, p2)
            } else {
                (p2, p2 + length)
            };
            let start = usize::try_from(y.max(1) - 1)
                .unwrap_or(usize::MAX)
                .min(text.len());
            let end = usize::try_from((z - 1).max(0))
                .unwrap_or(usize::MAX)
                .min(text.len());
            if start < end {
                SqliteValue::Text(text[start..end].to_owned().into())
            } else {
                SqliteValue::Text(String::new().into())
            }
        }
        None => {
            let idx = usize::try_from(p2.max(1) - 1)
                .unwrap_or(usize::MAX)
                .min(text.len());
            SqliteValue::Text(text[idx..].to_owned().into())
        }
    }
}

fn simple_index_supports_prepared_text_equality_fast_path(index: &IndexSchema) -> bool {
    index.supports_direct_column_lookup()
        && index.key_term_count() == 1
        && !index.key_term_descending(0)
        && index
            .key_term_collation(0)
            .is_none_or(|collation| collation.eq_ignore_ascii_case("BINARY"))
}

fn select_indexed_numeric_probe_spec(
    table: &TableSchema,
    table_label: &str,
    expr: &Expr,
) -> Option<(usize, i32)> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    if col_ref
        .table
        .as_deref()
        .is_some_and(|candidate| !candidate.eq_ignore_ascii_case(table_label))
    {
        return None;
    }

    select_indexed_numeric_probe_spec_for_column(table, col_ref)
}

fn select_labeled_indexed_numeric_probe_spec(
    table: &TableSchema,
    table_label: &str,
    expr: &Expr,
) -> Option<(usize, i32)> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    if !col_ref
        .table
        .as_deref()
        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(table_label))
    {
        return None;
    }

    select_indexed_numeric_probe_spec_for_column(table, col_ref)
}

fn select_indexed_numeric_probe_spec_for_column(
    table: &TableSchema,
    col_ref: &ColumnRef,
) -> Option<(usize, i32)> {
    let column_index = table.column_index(&col_ref.column)?;
    let column = table.columns.get(column_index)?;
    if column.is_ipk || !matches!(column.affinity, 'D' | 'd' | 'C' | 'c') {
        return None;
    }

    let index_root_page = table
        .indexes
        .iter()
        .find(|index| {
            index.supports_direct_column_lookup()
                && index.key_term_count() == 1
                && !index.key_term_descending(0)
                && index
                    .key_term_collation(0)
                    .is_none_or(|collation| collation.eq_ignore_ascii_case("BINARY"))
                && index
                    .columns
                    .first()
                    .is_some_and(|name| name.eq_ignore_ascii_case(&col_ref.column))
        })?
        .root_page;

    Some((column_index, index_root_page))
}

