    /// Prepare and execute SQL, returning output/affected row count.
    ///
    /// For DML (INSERT/UPDATE/DELETE) this returns the number of affected
    /// rows.  For SELECT and other statement types it returns the number of
    /// result rows.
    pub fn execute(&self, sql: &str) -> Result<usize> {
        self.background_status()?;
        let statements = {
            let parse_span = tracing::enabled!(target: "fsqlite.parse", tracing::Level::TRACE)
                .then(|| {
                    let span = tracing::span!(
                        target: "fsqlite.parse",
                        tracing::Level::TRACE,
                        "parse",
                        parse_mode = "execute_multi",
                        sql_len = sql.len()
                    );
                    record_trace_span_created();
                    span
                });
            let _parse_guard = parse_span.as_ref().map(tracing::Span::enter);
            self.cached_parse_multi(sql)?
        };
        if statements.len() == 1
            && self.ad_hoc_execute_supports_prepared_reuse(statements[0].as_ref())?
        {
            let prepared = self.prepare_after_background_status(sql)?;
            return self.execute_prepared_with_params_after_background_status(
                &prepared,
                &[],
                false,
            );
        }
        let mut last_count = 0;
        for statement in statements {
            let is_dml = matches!(
                statement.as_ref(),
                Statement::Insert(_) | Statement::Update(_) | Statement::Delete(_)
            );
            let rows = self.execute_statement_after_background_status(statement.as_ref(), None)?;
            self.note_connection_statement_execution_count(1);
            last_count = if is_dml {
                self.last_changes.get()
            } else {
                rows.len()
            };
        }
        Ok(last_count)
    }

    /// Execute zero or more SQL statements separated by semicolons.
    ///
    /// Empty batches and batches containing only whitespace, semicolons, or
    /// SQL comments are treated as a no-op, matching SQLite batch semantics.
    pub fn execute_batch(&self, sql: &str) -> Result<()> {
        self.background_status()?;
        if batch_is_noop(sql)? {
            return Ok(());
        }
        self.execute(sql).map(|_| ())
    }

    /// Begin a transaction without going through SQL parsing/dispatch.
    ///
    /// This follows the same mode selection as plain `BEGIN`: explicit mode is
    /// absent, so `concurrent_mode_default` still controls whether the
    /// transaction auto-promotes to concurrent mode.
    pub fn begin_transaction(&self) -> Result<()> {
        self.background_status()?;
        self.execute_begin(fsqlite_ast::BeginStatement { mode: None })
    }

    /// Commit the active transaction without reparsing a `COMMIT` statement.
    pub fn commit_transaction(&self) -> Result<()> {
        self.background_status()?;
        let cx = self.op_cx_after_background_status();
        self.execute_commit_with_cx(&cx)
    }

    /// Roll back the active transaction without reparsing a `ROLLBACK` statement.
    pub fn rollback_transaction(&self) -> Result<()> {
        self.background_status()?;
        let cx = self.op_cx_after_background_status();
        self.execute_rollback_with_cx(&cx, &fsqlite_ast::RollbackStatement { to_savepoint: None })
    }

    /// Prepare and execute SQL with bound SQL parameters.
    pub fn execute_with_params(&self, sql: &str, params: &[SqliteValue]) -> Result<usize> {
        self.execute_with_params_with_statement_savepoint_policy(sql, params, false)
    }

    /// Prepare and execute SQL with bound SQL parameters, skipping the
    /// internal statement savepoint when the call runs inside an explicit
    /// transaction.
    ///
    /// This is a narrow performance escape hatch for callers that prevalidate
    /// statement inputs and treat the enclosing transaction as the rollback
    /// boundary. If execution fails inside an explicit transaction, callers
    /// must roll back that transaction to discard any partial effects.
    /// Outside an explicit transaction this behaves like `execute_with_params`.
    pub fn execute_with_params_skip_statement_savepoint_in_explicit_txn(
        &self,
        sql: &str,
        params: &[SqliteValue],
    ) -> Result<usize> {
        self.execute_with_params_with_statement_savepoint_policy(sql, params, true)
    }

    fn execute_with_params_with_statement_savepoint_policy(
        &self,
        sql: &str,
        params: &[SqliteValue],
        skip_statement_savepoint_in_explicit_txn: bool,
    ) -> Result<usize> {
        self.background_status()?;
        let statements = {
            let parse_span = tracing::enabled!(target: "fsqlite.parse", tracing::Level::TRACE)
                .then(|| {
                    let span = tracing::span!(
                        target: "fsqlite.parse",
                        tracing::Level::TRACE,
                        "parse",
                        parse_mode = "execute_multi_params",
                        sql_len = sql.len()
                    );
                    record_trace_span_created();
                    span
                });
            let _parse_guard = parse_span.as_ref().map(tracing::Span::enter);
            self.cached_parse_multi(sql)?
        };
        if statements.len() == 1
            && self.ad_hoc_execute_supports_prepared_reuse(statements[0].as_ref())?
        {
            let prepared = self.prepare_after_background_status(sql)?;
            return self.execute_prepared_with_params_after_background_status(
                &prepared,
                params,
                skip_statement_savepoint_in_explicit_txn,
            );
        }
        let mut last_count = 0;
        for statement in statements {
            let is_dml = matches!(
                statement.as_ref(),
                Statement::Insert(_) | Statement::Update(_) | Statement::Delete(_)
            );
            let rows =
                self.execute_statement_after_background_status(statement.as_ref(), Some(params))?;
            self.note_connection_statement_execution_count(1);
            last_count = if is_dml {
                self.last_changes.get()
            } else {
                rows.len()
            };
        }
        Ok(last_count)
    }

    fn ad_hoc_query_supports_prepared_reuse(&self, statement: &Statement) -> bool {
        matches!(statement, Statement::Select(_))
            && !self.prepared_select_requires_dispatch(statement)
    }

    fn ad_hoc_execute_supports_prepared_reuse(&self, statement: &Statement) -> Result<bool> {
        // DML on a view with a matching INSTEAD OF trigger must go through the
        // normal dispatcher, which routes to the trigger body. The prepared fast
        // lane would compile it as table DML and fail "no such table". bd-ffkpv.
        if self.statement_targets_instead_of_view(statement) {
            return Ok(false);
        }
        match statement {
            Statement::Select(_) => Ok(!self.prepared_select_requires_dispatch(statement)),
            Statement::Insert(insert) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&insert.table.name)
                {
                    return Ok(false);
                }
                let is_simple_values = matches!(
                    &insert.source,
                    fsqlite_ast::InsertSource::Values(_) | fsqlite_ast::InsertSource::DefaultValues
                ) || matches!(
                    &insert.source,
                    fsqlite_ast::InsertSource::Select(sel)
                    if matches!(sel.body.select, SelectCore::Values(_))
                       && sel.body.compounds.is_empty()
                );
                Ok(is_simple_values && !self.prepared_insert_requires_deferred_dispatch(insert)?)
            }
            Statement::Update(update) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&update.table.name.name)
                {
                    return Ok(false);
                }
                Ok(Self::prepared_update_supports_precompiled_program(update)
                    && !self.prepared_update_requires_deferred_dispatch(update)?)
            }
            Statement::Delete(delete) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&delete.table.name.name)
                {
                    return Ok(false);
                }
                Ok(Self::prepared_delete_supports_precompiled_program(delete)
                    && !self.prepared_delete_requires_deferred_dispatch(delete)?)
            }
            _ => Ok(false),
        }
    }

    /// Execute a prepared DML statement (INSERT/UPDATE/DELETE) with no parameters.
    pub fn execute_prepared(&self, stmt: &PreparedStatement<'_>) -> Result<usize> {
        self.execute_prepared_with_params(stmt, &[])
    }

    /// Execute a prepared DML statement (INSERT/UPDATE/DELETE) with bound parameters.
    pub fn execute_prepared_with_params(
        &self,
        stmt: &PreparedStatement<'_>,
        params: &[SqliteValue],
    ) -> Result<usize> {
        self.background_status()?;
        self.execute_prepared_with_params_after_background_status(stmt, params, false)
    }

    fn execute_prepared_with_params_after_background_status(
        &self,
        stmt: &PreparedStatement<'_>,
        params: &[SqliteValue],
        force_skip_statement_savepoint_in_explicit_txn: bool,
    ) -> Result<usize> {
        let _record_profile_scope = enter_record_profile_scope(RecordProfileScope::CoreConnection);
        if !std::ptr::eq(self, stmt.conn) {
            return Err(FrankenError::internal(
                "prepared statement belongs to a different connection",
            ));
        }
        if self.pragma_state.borrow().query_only
            && (stmt.precompiled_dml().is_some() || stmt.deferred_dml_statement().is_some())
        {
            return Err(FrankenError::ReadOnly);
        }
        if let Some(dispatch) = stmt.precompiled_dml() {
            // bd-6eyrg.1: FAST PATH — precompiled DML with valid schema.
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    kind = %format!("{:?}", dispatch.kind),
                    reason = "precompiled_dml",
                );
            }
            let op_cx = self.op_cx_after_background_status();
            let direct_simple_insert_profile = dispatch.kind == PreparedDmlKind::Insert
                && dispatch
                    .direct_simple_insert
                    .as_ref()
                    .is_some_and(|direct| {
                        !Self::direct_simple_insert_prefers_reusable_table_program(direct)
                    });
            let schema_validation_start =
                (hot_path_profile_enabled() && direct_simple_insert_profile).then(Instant::now);
            // AAC-P6: Renewal-amortization carry. For the in-txn prepared-DML
            // fast path, when the micro-batcher confirms the program pointer,
            // binds arity, schema cookie + generation, function-registry
            // generation, in-txn flag and concurrent-session id all match the
            // previous call, we can skip the per-call schema validation and
            // go straight into dispatch with `publication = None`.
            // Correctness: the carry check already compares every identity
            // bit that `ensure_schema_unchanged_with_prebound_publication`
            // inspects for :memory: databases. File-backed connections never
            // hit this lane while in an explicit txn (the publication path
            // only matters for autocommit boundaries) so the carry remains
            // safe on pager-backed connections too.
            // The in-txn carry path is only attempted when the live epoch
            // shape can honestly be compared (active explicit txn, stmt
            // does not touch connection change-tracking state). When the
            // check fails, we fall through to the normal schema-validation
            // path; the next carry attempt will self-correct because the
            // cached `in_explicit_txn` / concurrent-session fields will no
            // longer match.
            let can_use_microbatch_carry = self.stmt_microbatch_is_enabled()
                && self.in_transaction.get()
                && !stmt.may_observe_change_tracking
                && self.active_txn.borrow().is_some();
            let microbatch_hit = if can_use_microbatch_carry {
                let program_ptr = Arc::as_ptr(&stmt.program) as usize;
                let session_id = if self.concurrent_txn.get() {
                    *self.concurrent_session_id.borrow()
                } else {
                    None
                };
                self.stmt_microbatch_try_carry(program_ptr, params.len(), true, session_id)
            } else {
                false
            };
            let entry_proof = if microbatch_hit {
                PreparedDmlEntryProof {
                    publication: None,
                    microbatch_carry_verified_in_txn: true,
                }
            } else {
                stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?
            };
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_INSERT_SCHEMA_VALIDATION_TIME_NS,
                schema_validation_start,
            );
            let p = if params.is_empty() {
                None
            } else {
                Some(params)
            };
            let result = match dispatch.kind {
                PreparedDmlKind::Insert => self.execute_precompiled_prepared_insert(
                    &op_cx,
                    stmt,
                    &dispatch.table_name,
                    dispatch.post_write_action,
                    dispatch.rollback_on_constraint_violation,
                    dispatch.preserve_prior_changes_on_constraint_violation,
                    dispatch.skip_statement_savepoint_in_explicit_txn
                        || force_skip_statement_savepoint_in_explicit_txn,
                    entry_proof.publication,
                    p,
                    false,
                ),
                PreparedDmlKind::Update | PreparedDmlKind::Delete => self
                    .execute_precompiled_prepared_update_or_delete(
                        &op_cx,
                        stmt,
                        dispatch.kind,
                        dispatch.rollback_on_constraint_violation,
                        dispatch.preserve_prior_changes_on_constraint_violation,
                        dispatch.skip_statement_savepoint_in_explicit_txn
                            || force_skip_statement_savepoint_in_explicit_txn,
                        entry_proof,
                        p,
                    ),
            };
            if result.is_ok() {
                self.note_connection_statement_execution_count(1);
            } else {
                // AAC-P6: on error, drop the carry so the next prepared
                // call re-verifies schema and rebuilds its ceremony.
                self.stmt_microbatch_flush();
            }
            return result;
        }
        if let Some(dml) = stmt.deferred_dml_statement() {
            let op_cx = self.op_cx_after_background_status();
            let p = if params.is_empty() {
                None
            } else {
                Some(params)
            };
            // bd-db300.5.2.2.4 / T13: check direct-dispatch eligibility
            // first; only prebind the publication when the fast path will
            // actually use it. The slow/fallback path keeps the cheaper
            // ensure_schema_unchanged() without publication binding.
            if let Some(fast_path) = stmt.prepared_update_delete_fast_path()
                && fast_path.supports_direct_dispatch_now(self)
            {
                let has_precompiled_program = stmt.dispatch_precompiled_program().is_some();
                let can_use_programless_direct_dispatch = !has_precompiled_program
                    && fast_path.has_direct_simple_dispatch()
                    && self.fused_entry_control_mode.get() == FusedEntryControlMode::Auto
                    && !tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG)
                    && !tracing::enabled!(
                        target: "fsqlite.statement_reuse",
                        tracing::Level::INFO
                    );
                if !has_precompiled_program && !can_use_programless_direct_dispatch {
                    stmt.ensure_schema_unchanged(&op_cx)?;
                    if hot_path_profile_enabled() {
                        FSQLITE_SLOW_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                    }
                    let rows = self.execute_statement_impl_after_background_status(dml, p, None)?;
                    self.note_connection_statement_execution_count(1);
                    return Ok(
                        if matches!(
                            dml,
                            Statement::Insert(_) | Statement::Update(_) | Statement::Delete(_)
                        ) {
                            self.last_changes.get()
                        } else {
                            rows.len()
                        },
                    );
                }
                // Fast path: prebind publication so the autocommit begin
                // path can reuse it instead of double-refreshing.
                let entry_proof = stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
                if hot_path_profile_enabled() {
                    FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                    tracing::debug!(
                        target: "fsqlite.execute_path",
                        path = "fast",
                        kind = %format!("{:?}", fast_path.kind),
                        reason = "deferred_dml_direct_dispatch",
                    );
                }
                return self.execute_precompiled_prepared_update_or_delete(
                    &op_cx,
                    stmt,
                    fast_path.kind,
                    fast_path.rollback_on_constraint_violation,
                    fast_path.preserve_prior_changes_on_constraint_violation,
                    fast_path.skip_statement_savepoint_in_explicit_txn
                        || force_skip_statement_savepoint_in_explicit_txn,
                    entry_proof,
                    p,
                );
            }
            // Slow path: validate schema without prebinding publication.
            stmt.ensure_schema_unchanged(&op_cx)?;
            // bd-6eyrg.1: SLOW PATH — deferred DML requires full dispatch.
            if hot_path_profile_enabled() {
                FSQLITE_SLOW_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "slow",
                    reason = "deferred_dml",
                );
            }
            let rows = self.execute_statement_impl_after_background_status(
                dml,
                p,
                stmt.dispatch_precompiled_program(),
            )?;
            self.note_connection_statement_execution_count(1);
            let is_dml = matches!(
                dml,
                Statement::Insert(_) | Statement::Update(_) | Statement::Delete(_)
            );
            Ok(if is_dml {
                self.last_changes.get()
            } else {
                rows.len()
            })
        } else {
            Ok(self
                .query_prepared_with_params_after_background_status(stmt, params)?
                .len())
        }
    }

    fn query_prepared_with_params_after_background_status(
        &self,
        stmt: &PreparedStatement<'_>,
        params: &[SqliteValue],
    ) -> Result<Vec<Row>> {
        let _record_profile_scope = enter_record_profile_scope(RecordProfileScope::CoreConnection);
        if !std::ptr::eq(self, stmt.conn) {
            return Err(FrankenError::internal(
                "prepared statement belongs to a different connection",
            ));
        }
        if stmt.dml_dispatch.is_some() {
            return Err(FrankenError::Internal(
                "DML prepared statements must be executed through \
                 Connection::execute_prepared() or Connection::execute_prepared_with_params()"
                    .to_owned(),
            ));
        }
        if stmt.may_observe_change_tracking {
            self.sync_change_tracking_context();
        }
        let op_cx = self.op_cx_after_background_status();
        if self
            .retained_autocommit_overlay_dirty_fast_path(stmt)
            .is_some()
        {
            let _overlay_entry_proof =
                stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
            if let Some(mut rows) =
                self.try_execute_retained_autocommit_query_fast_path(stmt, params, &op_cx)?
            {
                let fast_path =
                    stmt.prepared_query_fast_path_metadata("retained overlay query fast path")?;
                fast_path.record_query_hit();
                if hot_path_profile_enabled() {
                    FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                    tracing::debug!(
                        target: "fsqlite.execute_path",
                        path = "fast",
                        reason = "retained_autocommit_overlay_query",
                    );
                }
                if stmt.distinct {
                    let coll_snap = lock_unpoisoned(self.collation_registry.as_ref()).clone();
                    dedup_rows_collated(&mut rows, &stmt.distinct_collations, &coll_snap);
                }
                if let Some(limit_clause) = stmt.post_distinct_limit.as_ref() {
                    apply_limit_clause(&mut rows, limit_clause);
                }
                self.note_connection_statement_execution_count(1);
                return Ok(rows);
            }
        }
        if self.prepare_clean_memory_prepared_memdb_fast_path(stmt, &op_cx)?
            && let Some(mut rows) = self.try_execute_prepared_query_fast_path(stmt, params)?
        {
            let fast_path =
                stmt.prepared_query_fast_path_metadata("clean memory query fast path")?;
            fast_path.record_query_hit();
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = fast_path.query_trace_reason(),
                    read_boundary = "skipped_clean_memory_memdb",
                );
            }
            if stmt.distinct {
                let coll_snap = lock_unpoisoned(self.collation_registry.as_ref()).clone();
                dedup_rows_collated(&mut rows, &stmt.distinct_collations, &coll_snap);
            }
            if let Some(limit_clause) = stmt.post_distinct_limit.as_ref() {
                apply_limit_clause(&mut rows, limit_clause);
            }
            self.note_connection_statement_execution_count(1);
            return Ok(rows);
        }
        if self.prepare_clean_file_backed_prepared_memdb_fast_path(stmt, &op_cx)?
            && let Some(mut rows) = self.try_execute_prepared_query_fast_path(stmt, params)?
        {
            let fast_path =
                stmt.prepared_query_fast_path_metadata("clean file-backed query fast path")?;
            fast_path.record_query_hit();
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = fast_path.query_trace_reason(),
                    read_boundary = "skipped_clean_file_backed_memdb",
                );
            }
            if stmt.distinct {
                let coll_snap = lock_unpoisoned(self.collation_registry.as_ref()).clone();
                dedup_rows_collated(&mut rows, &stmt.distinct_collations, &coll_snap);
            }
            if let Some(limit_clause) = stmt.post_distinct_limit.as_ref() {
                apply_limit_clause(&mut rows, limit_clause);
            }
            self.note_connection_statement_execution_count(1);
            return Ok(rows);
        }
        let prepared_auto_read = self.prepare_connection_for_prepared_read(stmt, &op_cx)?;
        let entry_proof = stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
        if let Some(mut rows) = self.try_execute_prepared_query_fast_path(stmt, params)? {
            let fast_path =
                match stmt.prepared_query_fast_path_metadata("prepared query fast path outcome") {
                    Ok(fast_path) => fast_path,
                    Err(err) => {
                        self.finish_prepared_read_autocommit(prepared_auto_read, false, &op_cx)?;
                        return Err(err);
                    }
                };
            fast_path.record_query_hit();
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = fast_path.query_trace_reason(),
                );
            }
            if stmt.distinct {
                let coll_snap = lock_unpoisoned(self.collation_registry.as_ref()).clone();
                dedup_rows_collated(&mut rows, &stmt.distinct_collations, &coll_snap);
            }
            if let Some(limit_clause) = stmt.post_distinct_limit.as_ref() {
                apply_limit_clause(&mut rows, limit_clause);
            }
            self.finish_prepared_read_autocommit(prepared_auto_read, true, &op_cx)?;
            self.note_connection_statement_execution_count(1);
            return Ok(rows);
        }
        if let Some(Statement::Select(select)) = stmt.deferred_query_statement.as_deref()
            && let Some(rows) =
                self.execute_top_category_cte_join_fast_path(select, Some(params))?
        {
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.finish_prepared_read_autocommit(prepared_auto_read, true, &op_cx)?;
            self.note_connection_statement_execution_count(1);
            return Ok(rows);
        }
        if let Some(statement) = &stmt.deferred_query_statement {
            if hot_path_profile_enabled() {
                FSQLITE_SLOW_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "slow",
                    reason = "deferred_query_statement",
                );
            }
            let rows_result =
                self.execute_statement_after_background_status(statement.as_ref(), Some(params));
            self.finish_prepared_read_autocommit(prepared_auto_read, rows_result.is_ok(), &op_cx)?;
            if rows_result.is_ok() {
                self.note_connection_statement_execution_count(1);
            }
            return rows_result;
        }
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast",
                reason = if stmt.db.is_some() { "table_query" } else { "program_execute" },
            );
        }
        let execute_body_start = hot_path_profile_enabled().then(Instant::now);
        let rows_result = if stmt.db.is_some() {
            stmt.execute_table_query(&op_cx, Some(params), entry_proof.publication)
        } else {
            execute_program_with_postprocess(
                stmt.program.as_ref(),
                Some(params),
                stmt.func_registry.as_ref(),
                Some(&self.collation_registry),
                &op_cx,
                stmt.expression_postprocess.as_ref(),
                page_size_from_pragma_state(self.pragma_state.borrow().page_size)?,
            )
        };
        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
        self.finish_prepared_read_autocommit(prepared_auto_read, rows_result.is_ok(), &op_cx)?;
        let mut rows = rows_result?;
        if stmt.distinct {
            let coll_snap = lock_unpoisoned(self.collation_registry.as_ref()).clone();
            dedup_rows_collated(&mut rows, &stmt.distinct_collations, &coll_snap);
        }
        if let Some(limit_clause) = stmt.post_distinct_limit.as_ref() {
            apply_limit_clause(&mut rows, limit_clause);
        }
        self.note_connection_statement_execution_count(1);
        Ok(rows)
    }

    fn query_prepared_with_params_for_each_after_background_status<F>(
        &self,
        stmt: &PreparedStatement<'_>,
        params: &[SqliteValue],
        mut f: F,
    ) -> Result<()>
    where
        F: FnMut(&Row) -> Result<()>,
    {
        let _record_profile_scope = enter_record_profile_scope(RecordProfileScope::CoreConnection);
        if !std::ptr::eq(self, stmt.conn) {
            return Err(FrankenError::internal(
                "prepared statement belongs to a different connection",
            ));
        }
        if stmt.dml_dispatch.is_some() {
            return Err(FrankenError::Internal(
                "DML prepared statements must be executed through \
                 Connection::execute_prepared() or Connection::execute_prepared_with_params()"
                    .to_owned(),
            ));
        }
        if stmt.may_observe_change_tracking {
            self.sync_change_tracking_context();
        }
        if self
            .retained_autocommit_overlay_dirty_fast_path(stmt)
            .is_some()
        {
            let op_cx = self.op_cx_after_background_status();
            let _overlay_entry_proof =
                stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
            if let Some(rows) =
                self.try_execute_retained_autocommit_query_fast_path(stmt, params, &op_cx)?
            {
                let fast_path = stmt.prepared_query_fast_path_metadata(
                    "retained overlay streaming query fast path",
                )?;
                fast_path.record_query_hit();
                if hot_path_profile_enabled() {
                    FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                    tracing::debug!(
                        target: "fsqlite.execute_path",
                        path = "fast_streaming",
                        reason = "retained_autocommit_overlay_query",
                    );
                }
                self.note_connection_statement_execution_count(1);
                for row in rows {
                    f(&row)?;
                }
                return Ok(());
            }
        }

        let can_stream_with_row_handler = stmt.db.is_some()
            && stmt.deferred_query_statement.is_none()
            && !stmt.distinct
            && stmt.post_distinct_limit.is_none();

        if !can_stream_with_row_handler {
            let rows = self.query_prepared_with_params_after_background_status(stmt, params)?;
            for row in rows {
                f(&row)?;
            }
            return Ok(());
        }

        let op_cx = self.op_cx_after_background_status();
        let prepared_auto_read = self.prepare_connection_for_prepared_read(stmt, &op_cx)?;
        let entry_proof = stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast_streaming",
                reason = "table_query_row_handler",
            );
        }
        let execute_body_start = hot_path_profile_enabled().then(Instant::now);
        let mut callback_error: Option<FrankenError> = None;
        let mut bridging_handler = |row: &Row| match f(row) {
            Ok(()) => Ok(()),
            Err(err) => {
                callback_error = Some(err);
                Err(FrankenError::Abort)
            }
        };
        let raw_rows_result = stmt.execute_table_query_with_row_handler(
            &op_cx,
            Some(params),
            entry_proof.publication,
            &mut bridging_handler,
        );
        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
        let callback_failed = callback_error.is_some();
        self.finish_prepared_read_autocommit(
            prepared_auto_read,
            raw_rows_result.is_ok() || callback_failed,
            &op_cx,
        )?;
        if raw_rows_result.is_ok() || callback_failed {
            self.note_connection_statement_execution_count(1);
        }
        match (raw_rows_result, callback_error) {
            (Err(FrankenError::Abort), Some(err)) => Err(err),
            (result, None) => result,
            (Ok(()), Some(err)) => Err(FrankenError::Internal(format!(
                "query row handler captured callback error without aborting execution: {err}"
            ))),
            (Err(err), Some(_)) => Err(err),
        }
    }

    fn query_prepared_row_after_background_status(
        &self,
        stmt: &PreparedStatement<'_>,
        params: Option<&[SqliteValue]>,
    ) -> Result<Row> {
        let _record_profile_scope = enter_record_profile_scope(RecordProfileScope::CoreConnection);
        if !std::ptr::eq(self, stmt.conn) {
            return Err(FrankenError::internal(
                "prepared statement belongs to a different connection",
            ));
        }
        if stmt.dml_dispatch.is_some() {
            return Err(FrankenError::Internal(
                "DML prepared statements must be executed through \
                 Connection::execute_prepared() or Connection::execute_prepared_with_params()"
                    .to_owned(),
            ));
        }
        if stmt.may_observe_change_tracking {
            self.sync_change_tracking_context();
        }
        let op_cx = self.op_cx_after_background_status();
        if self
            .retained_autocommit_overlay_dirty_fast_path(stmt)
            .is_some()
        {
            let _overlay_entry_proof =
                stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
            if let Some(row_outcome) =
                self.try_execute_retained_autocommit_query_row_fast_path(stmt, params, &op_cx)?
            {
                let fast_path =
                    stmt.prepared_query_fast_path_metadata("retained overlay query row fast path")?;
                fast_path.record_query_row_hit();
                if hot_path_profile_enabled() {
                    FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                    tracing::debug!(
                        target: "fsqlite.execute_path",
                        path = "fast",
                        reason = "retained_autocommit_overlay_query_row",
                    );
                }
                self.note_connection_statement_execution_count(1);
                return direct_query_row_outcome_result(row_outcome);
            }
        }
        if self.prepare_clean_memory_prepared_memdb_fast_path(stmt, &op_cx)?
            && let Some(row_outcome) =
                self.try_execute_prepared_query_row_fast_path(stmt, params)?
        {
            let fast_path =
                stmt.prepared_query_fast_path_metadata("clean memory query row fast path")?;
            fast_path.record_query_row_hit();
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = fast_path.query_row_trace_reason(),
                    read_boundary = "skipped_clean_memory_memdb",
                );
            }
            self.note_connection_statement_execution_count(1);
            return direct_query_row_outcome_result(row_outcome);
        }
        if self.prepare_clean_file_backed_prepared_memdb_fast_path(stmt, &op_cx)?
            && let Some(row_outcome) =
                self.try_execute_prepared_query_row_fast_path(stmt, params)?
        {
            let fast_path =
                stmt.prepared_query_fast_path_metadata("clean file-backed query row fast path")?;
            fast_path.record_query_row_hit();
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = fast_path.query_row_trace_reason(),
                    read_boundary = "skipped_clean_file_backed_memdb",
                );
            }
            self.note_connection_statement_execution_count(1);
            return direct_query_row_outcome_result(row_outcome);
        }
        let prepared_auto_read = self.prepare_connection_for_prepared_read(stmt, &op_cx)?;
        let entry_proof = stmt.ensure_schema_unchanged_with_prebound_publication(&op_cx)?;
        if let Some(row_outcome) = self.try_execute_prepared_query_row_fast_path(stmt, params)? {
            let fast_path = match stmt
                .prepared_query_fast_path_metadata("prepared query row fast path outcome")
            {
                Ok(fast_path) => fast_path,
                Err(err) => {
                    self.finish_prepared_read_autocommit(prepared_auto_read, false, &op_cx)?;
                    return Err(err);
                }
            };
            fast_path.record_query_row_hit();
            if hot_path_profile_enabled() {
                FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "fast",
                    reason = fast_path.query_row_trace_reason(),
                );
            }
            self.note_connection_statement_execution_count(1);
            let row_result = direct_query_row_outcome_result(row_outcome);
            self.finish_prepared_read_autocommit(
                prepared_auto_read,
                query_row_completed_without_engine_failure(&row_result),
                &op_cx,
            )?;
            return row_result;
        }
        if let Some(statement) = &stmt.deferred_query_statement {
            if hot_path_profile_enabled() {
                FSQLITE_SLOW_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
                tracing::debug!(
                    target: "fsqlite.execute_path",
                    path = "slow",
                    reason = "deferred_query_statement",
                );
            }
            let rows_result =
                self.execute_statement_after_background_status(statement.as_ref(), params);
            self.finish_prepared_read_autocommit(prepared_auto_read, rows_result.is_ok(), &op_cx)?;
            if rows_result.is_ok() {
                self.note_connection_statement_execution_count(1);
            }
            return exactly_one_row_or_error(rows_result?);
        }
        if hot_path_profile_enabled() {
            FSQLITE_FAST_PATH_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        if tracing::enabled!(target: "fsqlite.execute_path", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite.execute_path",
                path = "fast",
                reason = if stmt.db.is_some() {
                    "table_query_row"
                } else {
                    "program_query_row"
                },
            );
        }
        if stmt.can_use_query_row_result_row_cap() {
            let row_result = if stmt.db.is_some() {
                stmt.execute_table_query_row_with_row_cap(
                    &op_cx,
                    params,
                    QUERY_ROW_RESULT_ROW_CAP,
                    entry_proof.publication,
                )
            } else {
                execute_program_exactly_one_row_with_row_cap(
                    stmt.program.as_ref(),
                    params,
                    stmt.func_registry.as_ref(),
                    Some(&self.collation_registry),
                    &op_cx,
                    page_size_from_pragma_state(self.pragma_state.borrow().page_size)?,
                    Some(QUERY_ROW_RESULT_ROW_CAP),
                )
            };
            let completed = query_row_completed_without_engine_failure(&row_result);
            self.finish_prepared_read_autocommit(prepared_auto_read, completed, &op_cx)?;
            if completed {
                self.note_connection_statement_execution_count(1);
                if let Ok(row) = &row_result {
                    self.maybe_store_count_indexed_rowid_probe_result(stmt, params, row);
                }
            }
            return row_result;
        }
        let rows_result = if stmt.db.is_some() {
            stmt.execute_table_query(&op_cx, params, entry_proof.publication)
        } else {
            execute_program_with_postprocess(
                stmt.program.as_ref(),
                params,
                stmt.func_registry.as_ref(),
                Some(&self.collation_registry),
                &op_cx,
                stmt.expression_postprocess.as_ref(),
                page_size_from_pragma_state(self.pragma_state.borrow().page_size)?,
            )
        };
        self.finish_prepared_read_autocommit(prepared_auto_read, rows_result.is_ok(), &op_cx)?;
        let mut rows = rows_result?;
        self.note_connection_statement_execution_count(1);
        if stmt.distinct {
            let coll_snap = lock_unpoisoned(self.collation_registry.as_ref()).clone();
            dedup_rows_collated(&mut rows, &stmt.distinct_collations, &coll_snap);
        }
        if let Some(limit_clause) = stmt.post_distinct_limit.as_ref() {
            apply_limit_clause(&mut rows, limit_clause);
        }
        let row_result = exactly_one_row_or_error(rows);
        if let Ok(row) = &row_result {
            self.maybe_store_count_indexed_rowid_probe_result(stmt, params, row);
        }
        row_result
    }

    fn retained_autocommit_overlay_fast_path(
        stmt: &PreparedStatement<'_>,
    ) -> Option<RetainedAutocommitOverlayFastPath> {
        let fast_path = stmt.prepared_query_fast_path.as_ref()?;
        match fast_path {
            PreparedQueryFastPath::SimpleCountStar { root_page } => {
                Some(RetainedAutocommitOverlayFastPath::CountStar {
                    root_page: *root_page,
                })
            }
            PreparedQueryFastPath::SimpleCountStarSum {
                root_page,
                sum_column_index,
                rowid_alias_column_index,
            } => Some(RetainedAutocommitOverlayFastPath::CountStarSum {
                root_page: *root_page,
                sum_column_index: *sum_column_index,
                rowid_alias_column_index: *rowid_alias_column_index,
            }),
            PreparedQueryFastPath::SimpleRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
            } => Some(RetainedAutocommitOverlayFastPath::RowidLookup {
                root_page: *root_page,
                parameter_index: *parameter_index,
                rowid_alias_column_index: *rowid_alias_column_index,
            }),
            PreparedQueryFastPath::SimpleProjectedRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
                projections,
            } => Some(RetainedAutocommitOverlayFastPath::ProjectedRowidLookup {
                root_page: *root_page,
                parameter_index: *parameter_index,
                rowid_alias_column_index: *rowid_alias_column_index,
                projections: Arc::clone(projections),
            }),
            PreparedQueryFastPath::SimpleIndexedEqualityLookup {
                root_page,
                column_index,
                parameter_index,
                rowid_alias_column_index,
                projections,
                ..
            } => Some(RetainedAutocommitOverlayFastPath::IndexedEqualityLookup {
                root_page: *root_page,
                column_index: *column_index,
                parameter_index: *parameter_index,
                rowid_alias_column_index: *rowid_alias_column_index,
                projections: projections.as_ref().map(Arc::clone),
            }),
            PreparedQueryFastPath::SimpleRowidRangeScan {
                root_page,
                lower_parameter_index,
                upper_parameter_index,
                rowid_alias_column_index,
            } => Some(RetainedAutocommitOverlayFastPath::RowidRangeScan {
                root_page: *root_page,
                lower_parameter_index: *lower_parameter_index,
                upper_parameter_index: *upper_parameter_index,
                rowid_alias_column_index: *rowid_alias_column_index,
            }),
            PreparedQueryFastPath::SimpleCountStarRowidRange {
                root_page,
                lower_parameter_index,
                upper_parameter_index,
            } => Some(RetainedAutocommitOverlayFastPath::CountStarRowidRange {
                root_page: *root_page,
                lower_parameter_index: *lower_parameter_index,
                upper_parameter_index: *upper_parameter_index,
            }),
            PreparedQueryFastPath::SimpleFullTableScan { .. }
            | PreparedQueryFastPath::SimpleOrderByLimit { .. }
            | PreparedQueryFastPath::SimpleLimitedScalarRowidSubquery { .. }
            | PreparedQueryFastPath::SimpleCountLikePattern { .. }
            | PreparedQueryFastPath::SimpleCountIndexedRowidProbe { .. }
            | PreparedQueryFastPath::SimpleStringScalarProjection { .. }
            | PreparedQueryFastPath::SimpleGroupConcatByColumn { .. }
            | PreparedQueryFastPath::SimpleIndexedTwoTableJoin { .. }
            | PreparedQueryFastPath::SimpleInnerJoinGroupedAggregate { .. }
            | PreparedQueryFastPath::TopCategoryCteJoin { .. } => None,
        }
    }

    fn prepared_memdb_query_fast_path_ready_with_mode(
        &self,
        stmt: &PreparedStatement<'_>,
        allow_file_backed_memdb: bool,
    ) -> bool {
        stmt.db.is_some()
            && self.memdb_rows_loaded.get()
            && (self.pager.is_memory() || allow_file_backed_memdb)
    }

    fn prepared_memdb_query_fast_path_ready(&self, stmt: &PreparedStatement<'_>) -> bool {
        let allow_file_backed_memdb = stmt
            .prepared_query_fast_path
            .as_ref()
            .is_some_and(PreparedQueryFastPath::can_use_clean_file_backed_memdb);
        self.prepared_memdb_query_fast_path_ready_with_mode(stmt, allow_file_backed_memdb)
    }

    fn clean_memory_prepared_memdb_fast_path_candidate(
        &self,
        stmt: &PreparedStatement<'_>,
    ) -> bool {
        self.pager.is_memory()
            && !self.in_transaction.get()
            && !self.active_txn_is_open_or_borrowed()
            && self.retained_autocommit_txn.borrow().is_none()
            && self.pending_memdb_direct_upserts.borrow().is_empty()
            && stmt.prepared_query_fast_path.is_some()
    }

    fn clean_memory_prepared_memdb_direct_fast_path_candidate(
        &self,
        stmt: &PreparedStatement<'_>,
    ) -> bool {
        self.pager.is_memory()
            && !self.in_transaction.get()
            && !self.active_txn_is_open_or_borrowed()
            && self.pending_memdb_direct_upserts.borrow().is_empty()
            && self.retained_autocommit_dirty_tables.borrow().is_empty()
            && stmt.prepared_query_fast_path.is_some()
    }

    fn prepare_clean_memory_prepared_memdb_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
        cx: &Cx,
    ) -> Result<bool> {
        if !self.clean_memory_prepared_memdb_fast_path_candidate(stmt) {
            return Ok(false);
        }

        self.refresh_memdb_from_active_txn_if_dirty(cx)?;
        self.refresh_memdb_from_cached_write_txn_if_stale(cx)?;
        if self.pager.is_memory()
            && !self.memdb_rows_loaded.get()
            && !self.memdb_requires_active_txn_reload.get()
        {
            let _ = self.refresh_memdb_if_stale_with_publication_and_mode(
                cx,
                "memdb_staleness_check",
                true,
            )?;
        }
        if !self.clean_memory_prepared_memdb_fast_path_candidate(stmt) {
            return Ok(false);
        }

        stmt.ensure_schema_identity_unchanged_after_local_refresh()?;
        Ok(self.prepared_memdb_query_fast_path_ready_with_mode(stmt, false))
    }

    fn clean_file_backed_prepared_memdb_fast_path_candidate(
        &self,
        stmt: &PreparedStatement<'_>,
    ) -> bool {
        !self.pager.is_memory()
            && !self.in_transaction.get()
            && !self.active_txn_is_open_or_borrowed()
            && self.retained_autocommit_txn.borrow().is_none()
            && self.pending_memdb_direct_upserts.borrow().is_empty()
            && !self.memdb_requires_active_txn_reload.get()
            && stmt
                .prepared_query_fast_path
                .as_ref()
                .is_some_and(PreparedQueryFastPath::can_use_clean_file_backed_memdb)
    }

    fn prepare_clean_file_backed_prepared_memdb_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
        cx: &Cx,
    ) -> Result<bool> {
        if !self.clean_file_backed_prepared_memdb_fast_path_candidate(stmt) {
            return Ok(false);
        }

        self.refresh_memdb_from_active_txn_if_dirty(cx)?;
        self.refresh_memdb_from_cached_write_txn_if_stale(cx)?;
        if !self.clean_file_backed_prepared_memdb_fast_path_candidate(stmt) {
            return Ok(false);
        }

        let _ = self.refresh_memdb_if_stale_with_publication_and_mode(
            cx,
            "clean_file_backed_memdb_staleness_check",
            true,
        )?;
        stmt.ensure_schema_identity_unchanged_after_local_refresh()?;
        Ok(self.prepared_memdb_query_fast_path_ready(stmt))
    }

    fn table_schema_by_root_page(&self, root_page: i32) -> Option<TableSchema> {
        self.schema
            .borrow()
            .iter()
            .find(|table| table.root_page == root_page)
            .cloned()
    }

    fn try_clean_memory_storage_count_cached_count(&self, root_page: i32) -> Result<Option<i64>> {
        if !self.pager.is_memory()
            || self.in_transaction.get()
            || self.active_txn_is_open_or_borrowed()
        {
            return Ok(None);
        }
        if self
            .retained_autocommit_txn
            .try_borrow()
            .map_or(true, |retained| retained.is_some())
            || self
                .pending_memdb_direct_upserts
                .try_borrow()
                .map_or(true, |pending| !pending.is_empty())
        {
            return Ok(None);
        }

        let Some(table) = self.table_schema_by_root_page(root_page) else {
            return Ok(None);
        };
        let commit_seq = self.current_global_commit_seq();
        let schema_generation = self.schema_generation();
        if let Some(entry) = self.storage_count_cache.borrow().get(&root_page)
            && entry.commit_seq == commit_seq
            && entry.schema_generation == schema_generation
        {
            return Ok(Some(entry.count));
        }

        let cx = self.op_cx_after_background_status();
        let cached_txn_count = {
            let mut cached_write_txn = self.cached_write_txn.borrow_mut();
            if let Some(txn) = cached_write_txn.as_mut() {
                let visible_hint = txn.published_visible_commit_seq_hint();
                if visible_hint.is_none() || visible_hint == Some(commit_seq) {
                    Some(self.count_btree_entries_in_txn(&cx, txn, table.root_page, true)?)
                } else {
                    None
                }
            } else {
                None
            }
        };
        let count = if let Some(count) = cached_txn_count {
            count
        } else {
            let mut txn = self.begin_pager_txn_with_busy_timeout(
                &self.pager,
                &cx,
                TransactionMode::ReadOnly,
                false,
            )?;
            let count = self.count_btree_entries_in_txn(&cx, &mut txn, table.root_page, true)?;
            txn.rollback(&cx)?;
            count
        };
        let count = i64::try_from(count).map_err(|_| {
            FrankenError::Internal(format!(
                "table row count exceeds i64 for root page {}",
                table.root_page
            ))
        })?;
        self.storage_count_cache.borrow_mut().insert(
            root_page,
            StorageCountCacheEntry {
                commit_seq,
                schema_generation,
                count,
            },
        );
        Ok(Some(count))
    }

    fn retained_autocommit_overlay_dirty_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
    ) -> Option<RetainedAutocommitOverlayFastPath> {
        if self.retained_autocommit_txn.borrow().is_none() {
            return None;
        }
        let overlay = Self::retained_autocommit_overlay_fast_path(stmt)?;
        let root_page_dirty = self
            .table_schema_by_root_page(overlay.root_page())
            .is_some_and(|table| {
                self.retained_autocommit_dirty_tables
                    .borrow()
                    .contains(&table.name.to_lowercase())
            });
        let parsed_read_overlap = if root_page_dirty {
            true
        } else if let Some(statement) = &stmt.deferred_query_statement {
            match statement.as_ref() {
                Statement::Select(select) => {
                    let read_tables = Self::extract_table_names_from_select(select);
                    self.retained_autocommit_has_dirty_overlap(&read_tables)
                }
                _ => false,
            }
        } else {
            match parse_single_statement(stmt.sql.as_ref()) {
                Ok(Statement::Select(select)) => {
                    let read_tables = Self::extract_table_names_from_select(&select);
                    self.retained_autocommit_has_dirty_overlap(&read_tables)
                }
                _ => false,
            }
        };
        let overlaps_dirty = root_page_dirty || parsed_read_overlap;
        if overlaps_dirty { Some(overlay) } else { None }
    }

    fn record_retained_autocommit_overlay_hit(&self, read_shape: &'static str) {
        if hot_path_profile_enabled() {
            FSQLITE_RETAINED_AUTOCOMMIT_OVERLAY_HITS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        tracing::debug!(
            target: "fsqlite.retained_autocommit_overlay",
            action = "hit",
            overlay_reason = "same_connection_private_view",
            read_shape,
        );
    }

    fn record_retained_autocommit_overlay_miss(
        &self,
        read_shape: &'static str,
        overlay_reason: &'static str,
    ) {
        if hot_path_profile_enabled() {
            FSQLITE_RETAINED_AUTOCOMMIT_OVERLAY_MISSES.fetch_add(1, AtomicOrdering::Relaxed);
        }
        tracing::debug!(
            target: "fsqlite.retained_autocommit_overlay",
            action = "miss",
            overlay_reason,
            read_shape,
        );
    }

    fn decode_table_row_values_from_payload(
        &self,
        table: &TableSchema,
        rowid: i64,
        payload: &[u8],
        rowid_alias_column_index: Option<usize>,
    ) -> Result<Vec<SqliteValue>> {
        if table.without_rowid {
            return Err(FrankenError::NotImplemented(format!(
                "retained autocommit overlay does not support WITHOUT ROWID table `{}`",
                table.name
            )));
        }

        let values = parse_record(payload).ok_or_else(|| FrankenError::DatabaseCorrupt {
            detail: format!(
                "table `{}` rowid {rowid} payload is not a valid SQLite record",
                table.name
            ),
        })?;
        self.inflate_table_row_values_for_storage_reload(
            table,
            rowid,
            &values,
            rowid_alias_column_index,
        )
    }

    fn numeric_column_value_from_sqlite_value(value: SqliteValue) -> NumericColumnValue {
        match value {
            SqliteValue::Null => NumericColumnValue::Null,
            SqliteValue::Integer(n) => NumericColumnValue::Integer(n),
            SqliteValue::Float(f) => NumericColumnValue::Float(f),
            SqliteValue::Text(_) | SqliteValue::Blob(_) => NumericColumnValue::NonNumeric,
        }
    }

    fn projected_table_row_numeric_sum_value_from_payload(
        &self,
        table: &TableSchema,
        rowid: i64,
        payload: &[u8],
        rowid_alias_column_index: Option<usize>,
        column_index: usize,
    ) -> Result<NumericColumnValue> {
        if table.without_rowid {
            return Err(FrankenError::NotImplemented(format!(
                "retained autocommit overlay does not support WITHOUT ROWID table `{}`",
                table.name
            )));
        }

        let projected =
            parse_record_projected_column_offsets(payload, column_index, rowid_alias_column_index)
                .ok_or_else(|| FrankenError::DatabaseCorrupt {
                    detail: format!(
                        "table `{}` rowid {rowid} payload is not a valid SQLite record",
                        table.name
                    ),
                })?;
        let column_count = projected.column_count;
        let num_columns = table.columns.len();

        if column_count > num_columns {
            return Err(FrankenError::DatabaseCorrupt {
                detail: format!(
                    "table `{}` rowid {rowid} payload has {column_count} columns; expected at most {num_columns}",
                    table.name
                ),
            });
        }

        if let Some(ipk_idx) = rowid_alias_column_index {
            if column_count == num_columns {
                let alias_offset = if ipk_idx == column_index {
                    projected.primary.as_ref()
                } else {
                    projected.secondary.as_ref()
                }
                .ok_or_else(|| FrankenError::DatabaseCorrupt {
                    detail: format!(
                        "table `{}` rowid {rowid} payload is missing INTEGER PRIMARY KEY alias column",
                        table.name
                    ),
                })?;
                let alias_value =
                    decode_column_from_offset(payload, alias_offset, record_profile_enabled())
                        .ok_or_else(|| FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} INTEGER PRIMARY KEY alias column is not a valid SQLite record value",
                                table.name
                            ),
                        })?;
                match alias_value {
                    SqliteValue::Null => {}
                    SqliteValue::Integer(encoded_rowid) if encoded_rowid == rowid => {}
                    SqliteValue::Integer(encoded_rowid) => {
                        return Err(FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} stores inconsistent INTEGER PRIMARY KEY alias value {encoded_rowid}",
                                table.name
                            ),
                        });
                    }
                    other => {
                        return Err(FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} stores non-integer INTEGER PRIMARY KEY alias value {other:?}",
                                table.name
                            ),
                        });
                    }
                }
            } else {
                let values = self.decode_table_row_values_from_payload(
                    table,
                    rowid,
                    payload,
                    rowid_alias_column_index,
                )?;
                let value = memdb_row_value_with_rowid_alias(
                    rowid,
                    &values,
                    column_index,
                    rowid_alias_column_index,
                );
                return Ok(Self::numeric_column_value_from_sqlite_value(value));
            }

            if column_index == ipk_idx {
                return Ok(NumericColumnValue::Integer(rowid));
            }
        }

        if column_index >= num_columns {
            return Ok(NumericColumnValue::Null);
        }

        if let Some(column_offset) = projected.primary.as_ref() {
            return decode_numeric_column_from_offset(payload, column_offset).ok_or_else(|| {
                FrankenError::DatabaseCorrupt {
                    detail: format!(
                        "table `{}` rowid {rowid} column {column_index} is not a valid SQLite record value",
                        table.name
                    ),
                }
            });
        }

        let default_value = match table
            .columns
            .get(column_index)
            .and_then(|column| column.default_value.as_ref())
        {
            Some(default_sql) => self.evaluate_column_default_value(Some(default_sql))?,
            None => SqliteValue::Null,
        };
        Ok(Self::numeric_column_value_from_sqlite_value(default_value))
    }

    fn projected_table_row_value_from_payload(
        &self,
        table: &TableSchema,
        rowid: i64,
        payload: &[u8],
        rowid_alias_column_index: Option<usize>,
        column_index: usize,
        column_offsets: &mut Vec<ColumnOffset>,
    ) -> Result<SqliteValue> {
        if table.without_rowid {
            return Err(FrankenError::NotImplemented(format!(
                "retained autocommit overlay does not support WITHOUT ROWID table `{}`",
                table.name
            )));
        }

        let column_count = parse_record_header_into(payload, column_offsets).ok_or_else(|| {
            FrankenError::DatabaseCorrupt {
                detail: format!(
                    "table `{}` rowid {rowid} payload is not a valid SQLite record",
                    table.name
                ),
            }
        })?;
        let num_columns = table.columns.len();

        if column_count > num_columns {
            return Err(FrankenError::DatabaseCorrupt {
                detail: format!(
                    "table `{}` rowid {rowid} payload has {column_count} columns; expected at most {num_columns}",
                    table.name
                ),
            });
        }

        if let Some(ipk_idx) = rowid_alias_column_index {
            if column_count == num_columns {
                let alias_offset =
                    column_offsets
                        .get(ipk_idx)
                        .ok_or_else(|| FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} payload is missing INTEGER PRIMARY KEY alias column",
                                table.name
                            ),
                        })?;
                let alias_value =
                    decode_column_from_offset(payload, alias_offset, record_profile_enabled())
                        .ok_or_else(|| FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} INTEGER PRIMARY KEY alias column is not a valid SQLite record value",
                                table.name
                            ),
                        })?;
                match alias_value {
                    SqliteValue::Null => {}
                    SqliteValue::Integer(encoded_rowid) if encoded_rowid == rowid => {}
                    SqliteValue::Integer(encoded_rowid) => {
                        return Err(FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} stores inconsistent INTEGER PRIMARY KEY alias value {encoded_rowid}",
                                table.name
                            ),
                        });
                    }
                    other => {
                        return Err(FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{}` rowid {rowid} stores non-integer INTEGER PRIMARY KEY alias value {other:?}",
                                table.name
                            ),
                        });
                    }
                }
            } else {
                let values = self.decode_table_row_values_from_payload(
                    table,
                    rowid,
                    payload,
                    rowid_alias_column_index,
                )?;
                return Ok(memdb_row_value_with_rowid_alias(
                    rowid,
                    &values,
                    column_index,
                    rowid_alias_column_index,
                ));
            }

            if column_index == ipk_idx {
                return Ok(SqliteValue::Integer(rowid));
            }
        }

        if column_index >= num_columns {
            return Ok(SqliteValue::Null);
        }

        if let Some(column_offset) = column_offsets.get(column_index) {
            return decode_column_from_offset(payload, column_offset, record_profile_enabled())
                .ok_or_else(|| FrankenError::DatabaseCorrupt {
                    detail: format!(
                        "table `{}` rowid {rowid} column {column_index} is not a valid SQLite record value",
                        table.name
                    ),
                });
        }

        let default_value = match table
            .columns
            .get(column_index)
            .and_then(|column| column.default_value.as_ref())
        {
            Some(default_sql) => self.evaluate_column_default_value(Some(default_sql))?,
            None => SqliteValue::Null,
        };
        Ok(default_value)
    }

    fn row_from_txn_payload(
        &self,
        table: &TableSchema,
        rowid: i64,
        payload: &[u8],
        rowid_alias_column_index: Option<usize>,
    ) -> Result<Row> {
        Ok(Row {
            values: self.decode_table_row_values_from_payload(
                table,
                rowid,
                payload,
                rowid_alias_column_index,
            )?,
        })
    }

    fn row_from_txn_value_sources(
        &self,
        table: &TableSchema,
        rowid: i64,
        payload: &[u8],
        rowid_alias_column_index: Option<usize>,
        sources: &[PreparedMemValueSource],
    ) -> Result<Row> {
        let values = self.decode_table_row_values_from_payload(
            table,
            rowid,
            payload,
            rowid_alias_column_index,
        )?;
        Ok(row_from_memdb_value_sources(
            rowid,
            &values,
            sources,
            rowid_alias_column_index,
        ))
    }

    fn retained_autocommit_count_star_sum_row_in_txn(
        &self,
        cx: &Cx,
        txn: &mut dyn TransactionHandle,
        table: &TableSchema,
        sum_column_index: usize,
        rowid_alias_column_index: Option<usize>,
    ) -> Result<(Row, i64)> {
        let Some(root) = PageNumber::new(u32::try_from(table.root_page).unwrap_or(0)) else {
            return Ok((
                Row {
                    values: vec![SqliteValue::Integer(0), SqliteValue::Null],
                },
                0,
            ));
        };
        let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
        let mut count = 0_i64;
        let mut sum_non_null_count = 0_i64;
        let mut int_sum: i64 = 0;
        let mut float_sum: f64 = 0.0;
        let mut float_err = 0.0;
        let mut all_int = true;
        let mut int_overflowed = false;
        let mut has_any_non_null = false;
        let mut needs_fallback = false;

        if cursor.first(cx)? {
            loop {
                let value = {
                    let (rowid, payload) = cursor.rowid_and_payload_cow(cx)?;
                    self.projected_table_row_numeric_sum_value_from_payload(
                        table,
                        rowid,
                        payload.as_ref(),
                        rowid_alias_column_index,
                        sum_column_index,
                    )?
                };
                count = count.checked_add(1).ok_or_else(|| {
                    FrankenError::Internal(format!(
                        "table row count exceeds i64 for root page {}",
                        table.root_page
                    ))
                })?;
                match value {
                    NumericColumnValue::Null => {}
                    NumericColumnValue::Integer(n) => {
                        sum_non_null_count += 1;
                        has_any_non_null = true;
                        if all_int && !int_overflowed {
                            if let Some(sum) = int_sum.checked_add(n) {
                                int_sum = sum;
                            } else {
                                int_overflowed = true;
                            }
                        }
                        #[allow(clippy::cast_precision_loss)]
                        {
                            kbn_step(&mut float_sum, &mut float_err, n as f64);
                        }
                    }
                    NumericColumnValue::Float(f) => {
                        sum_non_null_count += 1;
                        has_any_non_null = true;
                        all_int = false;
                        kbn_step(&mut float_sum, &mut float_err, f);
                    }
                    NumericColumnValue::NonNumeric => {
                        sum_non_null_count += 1;
                        needs_fallback = true;
                    }
                }
                if !cursor.next(cx)? {
                    break;
                }
            }
        }

        let sum = if needs_fallback {
            let mut sum_values: Vec<SqliteValue> = Vec::new();
            let mut column_offsets = Vec::new();
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
            if cursor.first(cx)? {
                loop {
                    let value = {
                        let (rowid, payload) = cursor.rowid_and_payload_cow(cx)?;
                        self.projected_table_row_value_from_payload(
                            table,
                            rowid,
                            payload.as_ref(),
                            rowid_alias_column_index,
                            sum_column_index,
                            &mut column_offsets,
                        )?
                    };
                    if !value.is_null() {
                        sum_values.push(value);
                    }
                    if !cursor.next(cx)? {
                        break;
                    }
                }
            }
            let sum_refs = sum_values.iter().collect::<Vec<_>>();
            self.compute_sum_aggregate_with_registry(&sum_refs)?
        } else if !has_any_non_null {
            SqliteValue::Null
        } else if all_int && int_overflowed {
            return Err(FrankenError::IntegerOverflow);
        } else if all_int {
            SqliteValue::Integer(int_sum)
        } else {
            SqliteValue::Float(float_sum + float_err)
        };

        Ok((
            Row {
                values: vec![SqliteValue::Integer(count), sum],
            },
            sum_non_null_count,
        ))
    }

    fn retained_autocommit_indexed_equality_rows_in_txn(
        &self,
        cx: &Cx,
        txn: &mut dyn TransactionHandle,
        table: &TableSchema,
        column_index: usize,
        probe_value: &SqliteValue,
        rowid_alias_column_index: Option<usize>,
        projections: Option<&[PreparedMemValueSource]>,
    ) -> Result<Vec<Row>> {
        let Some(root) = PageNumber::new(u32::try_from(table.root_page).unwrap_or(0)) else {
            return Ok(Vec::new());
        };
        if let Some(rows) = self.retained_autocommit_indexed_equality_cache_rows(
            table.root_page,
            column_index,
            probe_value,
            rowid_alias_column_index,
            projections,
        ) {
            return Ok(rows);
        }
        let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
        let mut rows = Vec::new();
        let mut column_offsets = Vec::new();
        if cursor.first(cx)? {
            loop {
                let rowid = cursor.rowid(cx)?;
                let payload = cursor.payload(cx)?;
                let value = self.projected_table_row_value_from_payload(
                    table,
                    rowid,
                    &payload,
                    rowid_alias_column_index,
                    column_index,
                    &mut column_offsets,
                )?;
                if value == *probe_value {
                    rows.push(match projections {
                        Some(projections) => self.row_from_txn_value_sources(
                            table,
                            rowid,
                            &payload,
                            rowid_alias_column_index,
                            projections,
                        )?,
                        None => self.row_from_txn_payload(
                            table,
                            rowid,
                            &payload,
                            rowid_alias_column_index,
                        )?,
                    });
                }
                if !cursor.next(cx)? {
                    break;
                }
            }
        }
        self.store_retained_autocommit_indexed_equality_cache(
            table.root_page,
            column_index,
            probe_value,
            rowid_alias_column_index,
            projections,
            &rows,
        );
        Ok(rows)
    }

    fn try_execute_retained_autocommit_query_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
        params: &[SqliteValue],
        cx: &Cx,
    ) -> Result<Option<Vec<Row>>> {
        let Some(overlay) = self.retained_autocommit_overlay_dirty_fast_path(stmt) else {
            return Ok(None);
        };
        let read_shape = overlay.read_shape();
        let Some(table) = self.table_schema_by_root_page(overlay.root_page()) else {
            self.record_retained_autocommit_overlay_miss(read_shape, "missing_table_schema");
            return Ok(None);
        };
        let maybe_rows = {
            let mut retained = self.retained_autocommit_txn.borrow_mut();
            let txn = retained.as_mut().ok_or_else(|| {
                FrankenError::internal(
                    "retained autocommit transaction disappeared before overlay query",
                )
            })?;
            match overlay {
                RetainedAutocommitOverlayFastPath::CountStar { .. } => {
                    let count = self.count_btree_entries_in_txn(cx, txn, table.root_page, true)?;
                    let count = i64::try_from(count).map_err(|_| {
                        FrankenError::Internal(format!(
                            "table row count exceeds i64 for root page {}",
                            table.root_page
                        ))
                    })?;
                    Some(vec![Row {
                        values: vec![SqliteValue::Integer(count)],
                    }])
                }
                RetainedAutocommitOverlayFastPath::CountStarSum {
                    root_page,
                    sum_column_index,
                    rowid_alias_column_index,
                } => {
                    if let Some(row) = self.retained_autocommit_count_sum_cache_row(
                        root_page,
                        sum_column_index,
                        rowid_alias_column_index,
                    ) {
                        Some(vec![row])
                    } else {
                        let (row, sum_non_null_count) = self
                            .retained_autocommit_count_star_sum_row_in_txn(
                                cx,
                                txn,
                                &table,
                                sum_column_index,
                                rowid_alias_column_index,
                            )?;
                        self.store_retained_autocommit_count_sum_cache(
                            root_page,
                            sum_column_index,
                            rowid_alias_column_index,
                            sum_non_null_count,
                            &row,
                        );
                        Some(vec![row])
                    }
                }
                RetainedAutocommitOverlayFastPath::RowidLookup {
                    parameter_index,
                    rowid_alias_column_index,
                    ..
                } => {
                    let rowid = match params.get(parameter_index) {
                        Some(SqliteValue::Integer(rowid)) => *rowid,
                        _ => return Ok(None),
                    };
                    let Some(root) = PageNumber::new(u32::try_from(table.root_page).unwrap_or(0))
                    else {
                        return Ok(Some(Vec::new()));
                    };
                    let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
                    if !cursor.table_move_to(cx, rowid)?.is_found() {
                        Some(Vec::new())
                    } else {
                        let payload = cursor.payload(cx)?;
                        Some(vec![self.row_from_txn_payload(
                            &table,
                            rowid,
                            &payload,
                            rowid_alias_column_index,
                        )?])
                    }
                }
                RetainedAutocommitOverlayFastPath::ProjectedRowidLookup {
                    parameter_index,
                    rowid_alias_column_index,
                    projections,
                    ..
                } => {
                    let rowid = match params.get(parameter_index) {
                        Some(SqliteValue::Integer(rowid)) => *rowid,
                        _ => return Ok(None),
                    };
                    let Some(root) = PageNumber::new(u32::try_from(table.root_page).unwrap_or(0))
                    else {
                        return Ok(Some(Vec::new()));
                    };
                    let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
                    if !cursor.table_move_to(cx, rowid)?.is_found() {
                        Some(Vec::new())
                    } else {
                        let payload = cursor.payload(cx)?;
                        Some(vec![self.row_from_txn_value_sources(
                            &table,
                            rowid,
                            &payload,
                            rowid_alias_column_index,
                            projections.as_ref(),
                        )?])
                    }
                }
                RetainedAutocommitOverlayFastPath::IndexedEqualityLookup {
                    column_index,
                    parameter_index,
                    rowid_alias_column_index,
                    projections,
                    ..
                } => {
                    let Some(probe_value) = params.get(parameter_index) else {
                        return Ok(None);
                    };
                    if matches!(probe_value, SqliteValue::Null) {
                        Some(Vec::new())
                    } else {
                        let SqliteValue::Text(_) = probe_value else {
                            return Ok(None);
                        };
                        Some(self.retained_autocommit_indexed_equality_rows_in_txn(
                            cx,
                            txn,
                            &table,
                            column_index,
                            probe_value,
                            rowid_alias_column_index,
                            projections.as_deref(),
                        )?)
                    }
                }
                RetainedAutocommitOverlayFastPath::RowidRangeScan {
                    lower_parameter_index,
                    upper_parameter_index,
                    rowid_alias_column_index,
                    ..
                } => {
                    let lower = match params.get(lower_parameter_index) {
                        Some(SqliteValue::Integer(lower)) => *lower,
                        _ => return Ok(None),
                    };
                    let upper = match params.get(upper_parameter_index) {
                        Some(SqliteValue::Integer(upper)) => *upper,
                        _ => return Ok(None),
                    };
                    if lower >= upper {
                        Some(Vec::new())
                    } else {
                        let Some(root) =
                            PageNumber::new(u32::try_from(table.root_page).unwrap_or(0))
                        else {
                            return Ok(Some(Vec::new()));
                        };
                        let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
                        let _ = cursor.table_move_to(cx, lower)?;
                        let mut rows = Vec::new();
                        while !cursor.eof() {
                            let rowid = cursor.rowid(cx)?;
                            if rowid >= upper {
                                break;
                            }
                            let payload = cursor.payload(cx)?;
                            rows.push(self.row_from_txn_payload(
                                &table,
                                rowid,
                                &payload,
                                rowid_alias_column_index,
                            )?);
                            if !cursor.next(cx)? {
                                break;
                            }
                        }
                        Some(rows)
                    }
                }
                RetainedAutocommitOverlayFastPath::CountStarRowidRange {
                    lower_parameter_index,
                    upper_parameter_index,
                    ..
                } => {
                    let lower = match params.get(lower_parameter_index) {
                        Some(SqliteValue::Integer(lower)) => *lower,
                        _ => return Ok(None),
                    };
                    let upper = match params.get(upper_parameter_index) {
                        Some(SqliteValue::Integer(upper)) => *upper,
                        _ => return Ok(None),
                    };
                    let count = if lower >= upper {
                        0_i64
                    } else {
                        let Some(root) =
                            PageNumber::new(u32::try_from(table.root_page).unwrap_or(0))
                        else {
                            return Ok(Some(vec![Row {
                                values: vec![SqliteValue::Integer(0)],
                            }]));
                        };
                        let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
                        let _ = cursor.table_move_to(cx, lower)?;
                        let mut count = 0_i64;
                        while !cursor.eof() {
                            let rowid = cursor.rowid(cx)?;
                            if rowid >= upper {
                                break;
                            }
                            count = count.checked_add(1).ok_or_else(|| {
                                FrankenError::Internal(format!(
                                    "table row range count exceeds i64 for root page {}",
                                    table.root_page
                                ))
                            })?;
                            if !cursor.next(cx)? {
                                break;
                            }
                        }
                        count
                    };
                    Some(vec![Row {
                        values: vec![SqliteValue::Integer(count)],
                    }])
                }
            }
        };

        match maybe_rows {
            Some(rows) => {
                if self.retained_autocommit_batch_active() {
                    self.retained_autocommit_note_read();
                }
                self.record_retained_autocommit_overlay_hit(read_shape);
                Ok(Some(rows))
            }
            None => {
                self.record_retained_autocommit_overlay_miss(read_shape, "unsupported_params");
                Ok(None)
            }
        }
    }

    fn try_execute_retained_autocommit_query_row_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
        params: Option<&[SqliteValue]>,
        cx: &Cx,
    ) -> Result<Option<QueryRowCollectionOutcome>> {
        let empty_params = [];
        let params = params.unwrap_or(&empty_params);
        let Some(rows) = self.try_execute_retained_autocommit_query_fast_path(stmt, params, cx)?
        else {
            return Ok(None);
        };
        let outcome = match rows.len() {
            0 => QueryRowCollectionOutcome::NoRows,
            1 => QueryRowCollectionOutcome::Row(
                rows.into_iter()
                    .next()
                    .expect("single-row retained overlay result must contain one row"),
            ),
            _ => QueryRowCollectionOutcome::MultipleRows,
        };
        Ok(Some(outcome))
    }

    fn prepared_indexed_equality_cache_key(
        &self,
        root_page: i32,
        index_root_page: i32,
        column_index: usize,
    ) -> PreparedIndexedEqualityCacheKey {
        PreparedIndexedEqualityCacheKey {
            root_page,
            index_root_page,
            column_index,
            visible_commit_seq: *self.memdb_visible_commit_seq.borrow(),
            memdb_version: self.db.borrow().undo_version(),
        }
    }

    fn last_prepared_indexed_equality_rows(
        &self,
        cache_key: PreparedIndexedEqualityCacheKey,
        rowid_alias_column_index: Option<usize>,
        projections: Option<&Arc<[PreparedMemValueSource]>>,
        probe_value: &SqliteValue,
    ) -> Option<Vec<Row>> {
        let last_result = self.prepared_indexed_equality_last_result.borrow();
        let last_result = last_result.as_ref()?;
        last_result
            .matches(
                cache_key,
                rowid_alias_column_index,
                projections,
                probe_value,
            )
            .then(|| last_result.rows.clone())
    }

    fn store_prepared_indexed_equality_last_result(
        &self,
        cache_key: PreparedIndexedEqualityCacheKey,
        rowid_alias_column_index: Option<usize>,
        projections: Option<&Arc<[PreparedMemValueSource]>>,
        probe_value: &SqliteValue,
        rows: &[Row],
    ) {
        if rows.len() > PREPARED_INDEXED_EQUALITY_LAST_RESULT_MAX_ROWS {
            return;
        }
        *self.prepared_indexed_equality_last_result.borrow_mut() =
            Some(PreparedIndexedEqualityLastResult {
                cache_key,
                rowid_alias_column_index,
                projections: projections.cloned(),
                probe_value: probe_value.clone(),
                rows: rows.to_vec(),
            });
    }

    fn prepared_count_indexed_rowid_probe_cache_key(
        &self,
        root_page: i32,
        index_root_page: i32,
        column_index: usize,
        probe_root_page: i32,
        probe_rowid_upper_exclusive: Option<i64>,
    ) -> PreparedCountIndexedRowidProbeCacheKey {
        PreparedCountIndexedRowidProbeCacheKey {
            indexed_equality_key: self.prepared_indexed_equality_cache_key(
                root_page,
                index_root_page,
                column_index,
            ),
            probe_root_page,
            probe_rowid_upper_exclusive,
        }
    }

    fn last_prepared_count_indexed_rowid_probe(
        &self,
        cache_key: PreparedCountIndexedRowidProbeCacheKey,
    ) -> Option<i64> {
        let last_result = self.prepared_count_indexed_rowid_probe_last_result.borrow();
        let last_result = last_result.as_ref()?;
        (last_result.cache_key == cache_key).then_some(last_result.count)
    }

    fn store_prepared_count_indexed_rowid_probe_last_result(
        &self,
        cache_key: PreparedCountIndexedRowidProbeCacheKey,
        count: i64,
    ) {
        *self
            .prepared_count_indexed_rowid_probe_last_result
            .borrow_mut() = Some(PreparedCountIndexedRowidProbeLastResult { cache_key, count });
    }

    fn with_prepared_indexed_equality_cache_key<R>(
        &self,
        cache_key: PreparedIndexedEqualityCacheKey,
        f: impl FnOnce(&PreparedIndexedEqualityCache) -> R,
    ) -> Option<R> {
        {
            let caches = self.prepared_indexed_equality_cache.borrow();
            if let Some(cache) = caches.get(&cache_key) {
                return Some(f(cache));
            }
        }

        let cache = {
            let db = self.db.borrow();
            let table = db.get_table(cache_key.root_page)?;
            let mut rowids_by_value: HashMap<PreparedIndexedEqualityLookupKey, Vec<i64>> =
                HashMap::new();
            for (rowid, values) in table.iter_rows() {
                let Some(value) = values.get(cache_key.column_index).cloned() else {
                    continue;
                };
                rowids_by_value
                    .entry(PreparedIndexedEqualityLookupKey(value))
                    .or_default()
                    .push(rowid);
            }
            PreparedIndexedEqualityCache {
                rowids_by_value: rowids_by_value
                    .into_iter()
                    .map(|(value, rowids)| (value, rowids.into_boxed_slice()))
                    .collect(),
            }
        };

        let mut caches = self.prepared_indexed_equality_cache.borrow_mut();
        caches.retain(|key, _| {
            key.visible_commit_seq == cache_key.visible_commit_seq
                && key.memdb_version == cache_key.memdb_version
        });
        caches.insert(cache_key, cache);
        drop(caches);

        let caches = self.prepared_indexed_equality_cache.borrow();
        let cache = caches.get(&cache_key)?;
        Some(f(cache))
    }

    fn with_prepared_indexed_equality_cache<R>(
        &self,
        root_page: i32,
        index_root_page: i32,
        column_index: usize,
        f: impl FnOnce(&PreparedIndexedEqualityCache) -> R,
    ) -> Option<R> {
        let cache_key =
            self.prepared_indexed_equality_cache_key(root_page, index_root_page, column_index);
        self.with_prepared_indexed_equality_cache_key(cache_key, f)
    }

    fn with_prepared_indexed_equality_rowids<R>(
        &self,
        root_page: i32,
        index_root_page: i32,
        column_index: usize,
        probe_value: &SqliteValue,
        f: impl FnOnce(&[i64]) -> R,
    ) -> Option<R> {
        let cache_key =
            self.prepared_indexed_equality_cache_key(root_page, index_root_page, column_index);
        self.with_prepared_indexed_equality_rowids_for_key(cache_key, probe_value, f)
    }

    fn with_prepared_indexed_equality_rowids_for_key<R>(
        &self,
        cache_key: PreparedIndexedEqualityCacheKey,
        probe_value: &SqliteValue,
        f: impl FnOnce(&[i64]) -> R,
    ) -> Option<R> {
        let probe_key = PreparedIndexedEqualityLookupKey(probe_value.clone());
        self.with_prepared_indexed_equality_cache_key(cache_key, |cache| {
            let rowids = cache
                .rowids_by_value
                .get(&probe_key)
                .map_or(&[][..], |rowids| rowids.as_ref());
            f(rowids)
        })
    }

    fn prepared_indexed_equality_integer_probe_table_count_for_key(
        &self,
        cache_key: PreparedIndexedEqualityCacheKey,
        probe_root_page: i32,
        probe_rowid_upper_exclusive: Option<i64>,
    ) -> Option<usize> {
        self.with_prepared_indexed_equality_cache_key(cache_key, |cache| {
            let db = self.db.borrow();
            let probe_table = db.get_table(probe_root_page)?;
            let mut count = 0_usize;

            let mut add_probe = |probe_rowid| {
                let probe_key = PreparedIndexedEqualityLookupKey(SqliteValue::Integer(probe_rowid));
                let rowid_count = cache
                    .rowids_by_value
                    .get(&probe_key)
                    .map_or(0, |rowids| rowids.len());
                count = count.saturating_add(rowid_count);
            };

            if let Some(upper) = probe_rowid_upper_exclusive {
                for (probe_rowid, _) in probe_table.iter_rows_in_rowid_range(i64::MIN, upper) {
                    add_probe(probe_rowid);
                }
            } else {
                for (probe_rowid, _) in probe_table.iter_rows() {
                    add_probe(probe_rowid);
                }
            }
            Some(count)
        })?
    }

    fn prepared_count_indexed_rowid_probe_row(
        &self,
        root_page: i32,
        index_root_page: i32,
        column_index: usize,
        probe_root_page: i32,
        probe_rowid_upper_exclusive: Option<i64>,
    ) -> Result<Option<Row>> {
        let cache_key = self.prepared_count_indexed_rowid_probe_cache_key(
            root_page,
            index_root_page,
            column_index,
            probe_root_page,
            probe_rowid_upper_exclusive,
        );
        let count = if let Some(count) = self.last_prepared_count_indexed_rowid_probe(cache_key) {
            count
        } else {
            if !self.memdb_storage_count_shortcuts_safe.get() {
                return Ok(None);
            }
            let Some(count) = self.prepared_indexed_equality_integer_probe_table_count_for_key(
                cache_key.indexed_equality_key,
                probe_root_page,
                probe_rowid_upper_exclusive,
            ) else {
                return Ok(None);
            };
            let count = i64::try_from(count).map_err(|_| {
                FrankenError::Internal(format!(
                    "indexed rowid probe count exceeds i64 for root page {root_page}"
                ))
            })?;
            self.store_prepared_count_indexed_rowid_probe_last_result(cache_key, count);
            count
        };
        Ok(Some(Row {
            values: vec![SqliteValue::Integer(count)],
        }))
    }

    fn maybe_store_count_indexed_rowid_probe_result(
        &self,
        stmt: &PreparedStatement<'_>,
        params: Option<&[SqliteValue]>,
        row: &Row,
    ) {
        if params.is_some() {
            return;
        }
        if !self.clean_memory_prepared_memdb_fast_path_candidate(stmt)
            || self.memdb_requires_active_txn_reload.get()
        {
            return;
        }
        let Some(PreparedQueryFastPath::SimpleCountIndexedRowidProbe {
            root_page,
            index_root_page,
            column_index,
            probe_root_page,
            probe_rowid_upper_exclusive,
        }) = stmt.prepared_query_fast_path.as_ref()
        else {
            return;
        };
        let Some(SqliteValue::Integer(count)) = row.get(0) else {
            return;
        };
        let cache_key = self.prepared_count_indexed_rowid_probe_cache_key(
            *root_page,
            *index_root_page,
            *column_index,
            *probe_root_page,
            *probe_rowid_upper_exclusive,
        );
        self.store_prepared_count_indexed_rowid_probe_last_result(cache_key, *count);
    }

    fn prepared_count_star_sum_row(
        &self,
        root_page: i32,
        sum_column_index: usize,
        rowid_alias_column_index: Option<usize>,
    ) -> Result<Option<Row>> {
        if !self.memdb_storage_count_shortcuts_safe.get() {
            return Ok(None);
        }
        // bd-wwqen.4: Inline NULL/Integer/Float SUM accumulation to avoid
        // per-row dynamic dispatch through the aggregate function registry.
        // Falls back to the registered sum aggregate for Text/Blob values so
        // their numeric coercion remains centralized. SUM only reports integer
        // overflow if the final aggregate stayed all-integer.
        let (row, sum_non_null_count, cacheable) = {
            let db = self.db.borrow();
            let Some(table) = db.get_table(root_page) else {
                return Ok(None);
            };
            let mut count = 0_i64;
            let mut sum_non_null_count = 0_i64;
            let mut int_sum: i64 = 0;
            let mut float_sum: f64 = 0.0;
            let mut float_err: f64 = 0.0;
            let mut all_int = true;
            let mut int_overflowed = false;
            let mut has_any_non_null = false;
            let mut needs_fallback = false;
            for (rowid, row_values) in table.iter_rows() {
                count = count.checked_add(1).ok_or_else(|| {
                    FrankenError::Internal(format!(
                        "table row count exceeds i64 for root page {root_page}"
                    ))
                })?;
                let value = memdb_row_value_with_rowid_alias(
                    rowid,
                    row_values,
                    sum_column_index,
                    rowid_alias_column_index,
                );
                match &value {
                    SqliteValue::Null => {}
                    SqliteValue::Integer(n) => {
                        sum_non_null_count += 1;
                        has_any_non_null = true;
                        if all_int && !int_overflowed {
                            match int_sum.checked_add(*n) {
                                Some(s) => int_sum = s,
                                None => int_overflowed = true,
                            }
                        }
                        #[allow(clippy::cast_precision_loss)]
                        {
                            kbn_step(&mut float_sum, &mut float_err, *n as f64);
                        }
                    }
                    SqliteValue::Float(f) => {
                        sum_non_null_count += 1;
                        has_any_non_null = true;
                        all_int = false;
                        kbn_step(&mut float_sum, &mut float_err, *f);
                    }
                    SqliteValue::Text(_) | SqliteValue::Blob(_) => {
                        // Text/Blob: fall back to registered aggregate for
                        // correct coercion semantics (text→numeric parsing).
                        needs_fallback = true;
                        break;
                    }
                }
            }
            let (sum, cacheable) = if needs_fallback {
                // Rare path: Text/Blob values present. Use registered aggregate.
                drop(db);
                let registry = self.func_registry.borrow();
                let sum_func = registry
                    .find_aggregate("sum", 1)
                    .ok_or_else(|| FrankenError::internal("missing built-in aggregate: sum/1"))?;
                let mut sum_state = sum_func.initial_state();
                let db = self.db.borrow();
                let Some(table) = db.get_table(root_page) else {
                    return Ok(None);
                };
                for (rowid, row_values) in table.iter_rows() {
                    let value = memdb_row_value_with_rowid_alias(
                        rowid,
                        row_values,
                        sum_column_index,
                        rowid_alias_column_index,
                    );
                    if !value.is_null() {
                        sum_func.step(&mut sum_state, std::slice::from_ref(&value))?;
                    }
                }
                (sum_func.finalize(sum_state)?, false)
            } else if !has_any_non_null {
                (SqliteValue::Null, true)
            } else if all_int && int_overflowed {
                return Err(FrankenError::IntegerOverflow);
            } else if all_int {
                (SqliteValue::Integer(int_sum), true)
            } else {
                (SqliteValue::Float(float_sum + float_err), true)
            };
            (
                Row {
                    values: vec![SqliteValue::Integer(count), sum],
                },
                sum_non_null_count,
                cacheable,
            )
        };
        if cacheable && self.pager.is_memory() {
            let cache_already_current = self
                .retained_autocommit_count_sum_cache
                .borrow()
                .as_ref()
                .is_some_and(|cache| {
                    cache.matches(root_page, sum_column_index, rowid_alias_column_index)
                        && cache.sum_non_null_count == sum_non_null_count
                        && cache.row.values() == row.values()
                });
            if !cache_already_current {
                self.store_retained_autocommit_count_sum_cache(
                    root_page,
                    sum_column_index,
                    rowid_alias_column_index,
                    sum_non_null_count,
                    &row,
                );
            }
        }
        Ok(Some(row))
    }

    fn prepared_order_by_limit_rows(
        &self,
        root_page: i32,
        order_source: PreparedMemValueSource,
        rowid_alias_column_index: Option<usize>,
        descending: bool,
        nulls_order: NullsOrder,
        limit: usize,
    ) -> Option<Vec<Row>> {
        let order_term = ResolvedOrderTerm {
            column_index: 0,
            descending,
            nulls_order,
        };
        if limit == 0 {
            return Some(Vec::new());
        }
        // bd-wwqen.4: Deferred row materialization — track only
        // (order_value, rowid) during the scan. Only materialize the
        // final winning rows at the end, avoiding Row allocation for
        // every scanned candidate (which can be 100K+ rows for LIMIT 20).
        let winner_keys = {
            let db = self.db.borrow();
            let table = db.get_table(root_page)?;
            let mut winners: Vec<(SqliteValue, i64)> = Vec::with_capacity(limit);
            for (rowid, row_values) in table.iter_rows() {
                let order_value = memdb_row_value_with_source(
                    rowid,
                    row_values,
                    order_source,
                    rowid_alias_column_index,
                );
                if winners.len() < limit {
                    Self::insert_prepared_order_by_limit_winner(
                        &mut winners,
                        (order_value, rowid),
                        order_term,
                    );
                    continue;
                }
                let Some((worst_value, _)) = winners.last() else {
                    continue;
                };
                if compare_order_values(&order_value, worst_value, order_term)
                    == std::cmp::Ordering::Less
                {
                    winners.pop();
                    Self::insert_prepared_order_by_limit_winner(
                        &mut winners,
                        (order_value, rowid),
                        order_term,
                    );
                }
            }
            winners
        };
        // Materialize only the winning rows by rowid lookup.
        let db = self.db.borrow();
        let table = db.get_table(root_page)?;
        let rows = winner_keys
            .into_iter()
            .filter_map(|(_, rowid)| {
                let values = table.row_values_by_rowid(rowid)?;
                Some(row_from_memdb_row_values(
                    rowid,
                    values,
                    rowid_alias_column_index,
                ))
            })
            .collect();
        Some(rows)
    }

    fn insert_prepared_order_by_limit_winner(
        winners: &mut Vec<(SqliteValue, i64)>,
        winner: (SqliteValue, i64),
        order_term: ResolvedOrderTerm,
    ) {
        let insert_idx = winners.partition_point(|existing| {
            compare_order_values(&existing.0, &winner.0, order_term) != std::cmp::Ordering::Greater
        });
        winners.insert(insert_idx, winner);
    }

    fn prepared_indexed_two_table_join_rows(
        &self,
        left_root_page: i32,
        left_join_source: PreparedMemValueSource,
        left_join_rowid_alias_column_index: Option<usize>,
        right_root_page: i32,
        right_index_root_page: i32,
        right_join_column_index: usize,
        right_join_rowid_alias_column_index: Option<usize>,
        join_kind: JoinKind,
        projections: &[PreparedJoinProjectionSource],
    ) -> Option<Vec<Row>> {
        self.with_prepared_indexed_equality_cache(
            right_root_page,
            right_index_root_page,
            right_join_column_index,
            |cache| {
                let db = self.db.borrow();
                let left_table = db.get_table(left_root_page)?;
                let right_table = db.get_table(right_root_page)?;
                let mut rows =
                    Vec::with_capacity(left_table.row_count().max(right_table.row_count()));

                for (left_rowid, left_values) in left_table.iter_rows() {
                    let join_key = memdb_row_value_with_source(
                        left_rowid,
                        left_values,
                        left_join_source,
                        left_join_rowid_alias_column_index,
                    );
                    let matching_right_rowids = (!join_key.is_null())
                        .then(|| {
                            cache
                                .rowids_by_value
                                .get(&PreparedIndexedEqualityLookupKey(join_key))
                        })
                        .flatten();

                    if let Some(right_rowids) = matching_right_rowids {
                        for right_rowid in right_rowids.iter().copied() {
                            let right_values = right_table.row_values_by_rowid(right_rowid)?;
                            let mut values = Vec::with_capacity(projections.len());
                            for projection in projections {
                                values.push(match *projection {
                                    PreparedJoinProjectionSource::Left(source) => {
                                        memdb_row_value_with_source(
                                            left_rowid,
                                            left_values,
                                            source,
                                            left_join_rowid_alias_column_index,
                                        )
                                    }
                                    PreparedJoinProjectionSource::Right(source) => {
                                        memdb_row_value_with_source(
                                            right_rowid,
                                            right_values,
                                            source,
                                            right_join_rowid_alias_column_index,
                                        )
                                    }
                                });
                            }
                            rows.push(Row { values });
                        }
                    } else if matches!(join_kind, JoinKind::Left) {
                        let mut values = Vec::with_capacity(projections.len());
                        for projection in projections {
                            values.push(match *projection {
                                PreparedJoinProjectionSource::Left(source) => {
                                    memdb_row_value_with_source(
                                        left_rowid,
                                        left_values,
                                        source,
                                        left_join_rowid_alias_column_index,
                                    )
                                }
                                PreparedJoinProjectionSource::Right(_) => SqliteValue::Null,
                            });
                        }
                        rows.push(Row { values });
                    }
                }

                Some(rows)
            },
        )
        .flatten()
    }

    #[allow(clippy::too_many_arguments)]
    fn prepared_inner_join_grouped_rowid_count_rows(
        &self,
        left_root_page: i32,
        left_group_source: PreparedMemValueSource,
        left_group_rowid_alias_column_index: Option<usize>,
        right_root_page: i32,
        right_join_source: PreparedMemValueSource,
        right_join_rowid_alias_column_index: Option<usize>,
        having_count_filter: Option<&PreparedCountHavingFilter>,
    ) -> Result<Option<Vec<Row>>> {
        const ROWID_COUNT_SMALL_RIGHT_ROW_LIMIT: usize = 128;

        #[derive(Debug)]
        struct PreparedJoinCountGroupState {
            group_key: SqliteValue,
            count: i64,
        }

        let groups = {
            let db = self.db.borrow();
            let Some(left_table) = db.get_table(left_root_page) else {
                return Ok(None);
            };
            let Some(right_table) = db.get_table(right_root_page) else {
                return Ok(None);
            };
            if right_table.row_count() > ROWID_COUNT_SMALL_RIGHT_ROW_LIMIT {
                return Ok(None);
            }
            let mut groups: Vec<PreparedJoinCountGroupState> = Vec::new();
            let mut group_key_to_index: HashMap<HashableJoinKey, usize> = HashMap::new();
            let mut rowid_to_group_index: HashMap<i64, usize> =
                HashMap::with_capacity(left_table.row_count());

            for (rowid, row_values) in left_table.iter_rows() {
                let group_key = memdb_row_value_with_source(
                    rowid,
                    row_values,
                    left_group_source,
                    left_group_rowid_alias_column_index,
                );
                let group_hash = HashableJoinKey(smallvec::smallvec![group_key.clone()]);
                let group_idx = if let Some(existing) = group_key_to_index.get(&group_hash) {
                    *existing
                } else {
                    let next = groups.len();
                    groups.push(PreparedJoinCountGroupState {
                        group_key,
                        count: 0,
                    });
                    group_key_to_index.insert(group_hash, next);
                    next
                };
                rowid_to_group_index.insert(rowid, group_idx);
            }

            for (rowid, row_values) in right_table.iter_rows() {
                let Some(join_key) = memdb_row_integer_join_key_with_source(
                    rowid,
                    row_values,
                    right_join_source,
                    right_join_rowid_alias_column_index,
                ) else {
                    continue;
                };
                let Some(&group_idx) = rowid_to_group_index.get(&join_key) else {
                    continue;
                };
                let group = &mut groups[group_idx];
                group.count = group.count.checked_add(1).ok_or_else(|| {
                    FrankenError::Internal("prepared grouped join count exceeded i64".to_owned())
                })?;
            }

            groups
        };

        let mut rows = Vec::with_capacity(groups.len());
        for group in groups {
            if group.count == 0 || !prepared_count_having_matches(group.count, having_count_filter)
            {
                continue;
            }
            rows.push(Row {
                values: vec![group.group_key, SqliteValue::Integer(group.count)],
            });
        }
        Ok(Some(rows))
    }

    #[allow(clippy::too_many_arguments)]
    fn prepared_inner_join_grouped_indexed_aggregate_rows(
        &self,
        left_root_page: i32,
        left_join_source: PreparedMemValueSource,
        left_join_rowid_alias_column_index: Option<usize>,
        left_group_source: PreparedMemValueSource,
        left_group_rowid_alias_column_index: Option<usize>,
        right_root_page: i32,
        right_index_root_page: i32,
        right_join_column_index: usize,
        right_sum_rowid_alias_column_index: Option<usize>,
        sum_source: Option<PreparedMemValueSource>,
        having_count_filter: Option<&PreparedCountHavingFilter>,
    ) -> Result<Option<Vec<Row>>> {
        const INDEXED_GROUPED_AGG_SMALL_RIGHT_ROW_LIMIT: usize = 128;

        if sum_source.is_none() {
            return Ok(None);
        }

        #[derive(Debug)]
        struct PreparedJoinGroupState {
            group_key: SqliteValue,
            count: i64,
            sum: TopCategorySumAccumulator,
        }

        let Some(rows) = self.with_prepared_indexed_equality_cache(
            right_root_page,
            right_index_root_page,
            right_join_column_index,
            |cache| -> Result<Option<Vec<Row>>> {
                let groups = {
                    let db = self.db.borrow();
                    let Some(left_table) = db.get_table(left_root_page) else {
                        return Ok(None);
                    };
                    let Some(right_table) = db.get_table(right_root_page) else {
                        return Ok(None);
                    };
                    if right_table.row_count() > INDEXED_GROUPED_AGG_SMALL_RIGHT_ROW_LIMIT {
                        return Ok(None);
                    }
                    let mut groups: Vec<PreparedJoinGroupState> = Vec::new();
                    let mut group_key_to_index: HashMap<HashableJoinKey, usize> = HashMap::new();

                    for (left_rowid, left_values) in left_table.iter_rows() {
                        let group_key = memdb_row_value_with_source(
                            left_rowid,
                            left_values,
                            left_group_source,
                            left_group_rowid_alias_column_index,
                        );
                        let group_hash = HashableJoinKey(smallvec::smallvec![group_key.clone()]);
                        let group_idx = if let Some(existing) = group_key_to_index.get(&group_hash)
                        {
                            *existing
                        } else {
                            let next = groups.len();
                            groups.push(PreparedJoinGroupState {
                                group_key,
                                count: 0,
                                sum: TopCategorySumAccumulator::default(),
                            });
                            group_key_to_index.insert(group_hash, next);
                            next
                        };

                        let join_key = memdb_row_value_with_source(
                            left_rowid,
                            left_values,
                            left_join_source,
                            left_join_rowid_alias_column_index,
                        );
                        if join_key.is_null() {
                            continue;
                        }
                        let Some(right_rowids) = cache
                            .rowids_by_value
                            .get(&PreparedIndexedEqualityLookupKey(join_key))
                        else {
                            continue;
                        };
                        let rowid_count = i64::try_from(right_rowids.len()).map_err(|_| {
                            FrankenError::Internal(
                                "prepared indexed grouped join count exceeded i64".to_owned(),
                            )
                        })?;
                        let group = &mut groups[group_idx];
                        group.count = group.count.checked_add(rowid_count).ok_or_else(|| {
                            FrankenError::Internal(
                                "prepared indexed grouped join count exceeded i64".to_owned(),
                            )
                        })?;
                        if let Some(sum_source) = sum_source {
                            for right_rowid in right_rowids.iter().copied() {
                                let Some(right_values) =
                                    right_table.row_values_by_rowid(right_rowid)
                                else {
                                    return Ok(None);
                                };
                                let value = memdb_row_value_with_source(
                                    right_rowid,
                                    right_values,
                                    sum_source,
                                    right_sum_rowid_alias_column_index,
                                );
                                group.sum.add(&value);
                            }
                        }
                    }

                    groups
                };

                let mut rows = Vec::with_capacity(groups.len());
                for group in groups {
                    if group.count == 0
                        || !prepared_count_having_matches(group.count, having_count_filter)
                    {
                        continue;
                    }
                    let mut values = vec![group.group_key, SqliteValue::Integer(group.count)];
                    if sum_source.is_some() {
                        values.push(group.sum.finish()?);
                    }
                    rows.push(Row { values });
                }
                Ok(Some(rows))
            },
        ) else {
            return Ok(None);
        };
        rows
    }

    fn prepared_inner_join_grouped_aggregate_rows(
        &self,
        left_root_page: i32,
        left_join_source: PreparedMemValueSource,
        left_join_rowid_alias_column_index: Option<usize>,
        left_group_source: PreparedMemValueSource,
        left_group_rowid_alias_column_index: Option<usize>,
        right_root_page: i32,
        right_join_source: PreparedMemValueSource,
        right_index_root_page: Option<i32>,
        right_join_column_index: Option<usize>,
        right_join_rowid_alias_column_index: Option<usize>,
        sum_source: Option<PreparedMemValueSource>,
        right_sum_rowid_alias_column_index: Option<usize>,
        having_count_filter: Option<&PreparedCountHavingFilter>,
    ) -> Result<Option<Vec<Row>>> {
        if sum_source.is_none() && left_join_source == PreparedMemValueSource::Rowid {
            if let Some(rows) = self.prepared_inner_join_grouped_rowid_count_rows(
                left_root_page,
                left_group_source,
                left_group_rowid_alias_column_index,
                right_root_page,
                right_join_source,
                right_join_rowid_alias_column_index,
                having_count_filter,
            )? {
                return Ok(Some(rows));
            }
        }

        if let (Some(right_index_root_page), Some(right_join_column_index)) =
            (right_index_root_page, right_join_column_index)
            && let Some(rows) = self.prepared_inner_join_grouped_indexed_aggregate_rows(
                left_root_page,
                left_join_source,
                left_join_rowid_alias_column_index,
                left_group_source,
                left_group_rowid_alias_column_index,
                right_root_page,
                right_index_root_page,
                right_join_column_index,
                right_sum_rowid_alias_column_index,
                sum_source,
                having_count_filter,
            )?
        {
            return Ok(Some(rows));
        }

        #[derive(Debug)]
        struct PreparedJoinGroupState {
            group_key: SqliteValue,
            count: i64,
            sum: TopCategorySumAccumulator,
        }

        let groups = {
            let db = self.db.borrow();
            let Some(left_table) = db.get_table(left_root_page) else {
                return Ok(None);
            };
            let Some(right_table) = db.get_table(right_root_page) else {
                return Ok(None);
            };
            let mut groups: Vec<PreparedJoinGroupState> = Vec::new();
            let mut group_key_to_index: HashMap<HashableJoinKey, usize> = HashMap::new();
            let mut join_key_to_group_indices: HashMap<HashableJoinKey, Vec<usize>> =
                HashMap::new();

            for (rowid, row_values) in left_table.iter_rows() {
                let group_key = memdb_row_value_with_source(
                    rowid,
                    row_values,
                    left_group_source,
                    left_group_rowid_alias_column_index,
                );
                let group_hash = HashableJoinKey(smallvec::smallvec![group_key.clone()]);
                let group_idx = if let Some(existing) = group_key_to_index.get(&group_hash) {
                    *existing
                } else {
                    let next = groups.len();
                    groups.push(PreparedJoinGroupState {
                        group_key,
                        count: 0,
                        sum: TopCategorySumAccumulator::default(),
                    });
                    group_key_to_index.insert(group_hash, next);
                    next
                };

                let join_key = memdb_row_value_with_source(
                    rowid,
                    row_values,
                    left_join_source,
                    left_join_rowid_alias_column_index,
                );
                if !join_key.is_null() {
                    join_key_to_group_indices
                        .entry(HashableJoinKey(smallvec::smallvec![join_key]))
                        .or_default()
                        .push(group_idx);
                }
            }

            for (rowid, row_values) in right_table.iter_rows() {
                let join_key = memdb_row_value_with_source(
                    rowid,
                    row_values,
                    right_join_source,
                    right_join_rowid_alias_column_index,
                );
                if join_key.is_null() {
                    continue;
                }
                let Some(group_indices) =
                    join_key_to_group_indices.get(&HashableJoinKey(smallvec::smallvec![join_key]))
                else {
                    continue;
                };
                let sum_value = sum_source.map(|source| {
                    memdb_row_value_with_source(
                        rowid,
                        row_values,
                        source,
                        right_sum_rowid_alias_column_index,
                    )
                });
                for &group_idx in group_indices {
                    let group = &mut groups[group_idx];
                    group.count = group.count.checked_add(1).ok_or_else(|| {
                        FrankenError::Internal(
                            "prepared grouped join count exceeded i64".to_owned(),
                        )
                    })?;
                    if let Some(value) = sum_value.as_ref() {
                        group.sum.add(value);
                    }
                }
            }

            groups
        };

        let mut rows = Vec::with_capacity(groups.len());
        for group in groups {
            if group.count == 0 || !prepared_count_having_matches(group.count, having_count_filter)
            {
                continue;
            }
            let mut values = vec![group.group_key, SqliteValue::Integer(group.count)];
            if sum_source.is_some() {
                values.push(group.sum.finish()?);
            }
            rows.push(Row { values });
        }
        Ok(Some(rows))
    }

    #[allow(clippy::unnecessary_wraps)]
    fn try_execute_prepared_query_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
        params: &[SqliteValue],
    ) -> Result<Option<Vec<Row>>> {
        let Some(fast_path) = stmt.prepared_query_fast_path.clone() else {
            return Ok(None);
        };
        if !self.prepared_memdb_query_fast_path_ready(stmt) {
            return Ok(None);
        }

        match fast_path {
            PreparedQueryFastPath::SimpleFullTableScan {
                root_page,
                rowid_alias_column_index,
            } => {
                let rows = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    let mut rows = Vec::with_capacity(table.iter_rows().size_hint().0);
                    for (rowid, values) in table.iter_rows() {
                        rows.push(row_from_memdb_row_values(
                            rowid,
                            values,
                            rowid_alias_column_index,
                        ));
                    }
                    rows
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleOrderByLimit {
                root_page,
                order_source,
                rowid_alias_column_index,
                descending,
                nulls_order,
                limit,
            } => Ok(self.prepared_order_by_limit_rows(
                root_page,
                order_source,
                rowid_alias_column_index,
                descending,
                nulls_order,
                limit,
            )),
            PreparedQueryFastPath::SimpleLimitedScalarRowidSubquery {
                outer_root_page,
                outer_column_index,
                outer_fk_column_index,
                inner_root_page,
                inner_result_column_index,
                limit,
            } => {
                let rows = {
                    let db = self.db.borrow();
                    let Some(outer_table) = db.get_table(outer_root_page) else {
                        return Ok(None);
                    };
                    let Some(inner_table) = db.get_table(inner_root_page) else {
                        return Ok(None);
                    };
                    let mut rows = Vec::with_capacity(limit);
                    for (_, outer_values) in outer_table.iter_rows().take(limit) {
                        let outer_value = outer_values
                            .get(outer_column_index)
                            .cloned()
                            .unwrap_or(SqliteValue::Null);
                        let subquery_value = match outer_values.get(outer_fk_column_index) {
                            Some(SqliteValue::Integer(inner_rowid)) => inner_table
                                .row_values_by_rowid(*inner_rowid)
                                .and_then(|inner_values| {
                                    inner_values.get(inner_result_column_index)
                                })
                                .cloned()
                                .unwrap_or(SqliteValue::Null),
                            _ => SqliteValue::Null,
                        };
                        rows.push(Row {
                            values: vec![outer_value, subquery_value],
                        });
                    }
                    rows
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleCountStar { root_page } => {
                if !self.memdb_storage_count_shortcuts_safe.get() {
                    return Ok(None);
                }
                let count = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    i64::try_from(table.row_count()).map_err(|_| {
                        FrankenError::Internal(format!(
                            "table row count exceeds i64 for root page {root_page}"
                        ))
                    })?
                };
                Ok(Some(vec![Row {
                    values: vec![SqliteValue::Integer(count)],
                }]))
            }
            PreparedQueryFastPath::SimpleCountStarSum {
                root_page,
                sum_column_index,
                rowid_alias_column_index,
            } => Ok(self
                .prepared_count_star_sum_row(root_page, sum_column_index, rowid_alias_column_index)?
                .map(|row| vec![row])),
            PreparedQueryFastPath::SimpleStringScalarProjection {
                root_page,
                rowid_alias_column_index,
                projections,
            } => {
                let rows = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    let mut rows = Vec::with_capacity(table.iter_rows().size_hint().0);
                    for (rowid, row_values) in table.iter_rows() {
                        let values = projections
                            .iter()
                            .copied()
                            .map(|projection| {
                                evaluate_prepared_simple_string_projection(
                                    projection,
                                    rowid,
                                    row_values,
                                    rowid_alias_column_index,
                                )
                            })
                            .collect();
                        rows.push(Row { values });
                    }
                    rows
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleGroupConcatByColumn {
                root_page,
                group_column_index,
                value_column_index,
                rowid_alias_column_index,
                separator,
            } => {
                let rows = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    let mut groups: BTreeMap<SqliteValue, (bool, String)> = BTreeMap::new();
                    for (rowid, row_values) in table.iter_rows() {
                        let group_key = memdb_row_value_with_rowid_alias(
                            rowid,
                            row_values,
                            group_column_index,
                            rowid_alias_column_index,
                        );
                        let value = memdb_row_value_with_rowid_alias(
                            rowid,
                            row_values,
                            value_column_index,
                            rowid_alias_column_index,
                        );
                        let entry = groups
                            .entry(group_key)
                            .or_insert_with(|| (false, String::new()));
                        if value.is_null() {
                            continue;
                        }
                        if entry.0 {
                            entry.1.push_str(separator.as_ref());
                        }
                        push_memdb_value_as_text(&mut entry.1, &value);
                        entry.0 = true;
                    }
                    groups
                        .into_iter()
                        .map(|(group_key, (saw_value, concat))| Row {
                            values: vec![
                                group_key,
                                if saw_value {
                                    SqliteValue::Text(concat.into())
                                } else {
                                    SqliteValue::Null
                                },
                            ],
                        })
                        .collect()
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleIndexedTwoTableJoin {
                left_root_page,
                left_join_source,
                left_join_rowid_alias_column_index,
                right_root_page,
                right_index_root_page,
                right_join_column_index,
                right_join_rowid_alias_column_index,
                join_kind,
                projections,
            } => Ok(self.prepared_indexed_two_table_join_rows(
                left_root_page,
                left_join_source,
                left_join_rowid_alias_column_index,
                right_root_page,
                right_index_root_page,
                right_join_column_index,
                right_join_rowid_alias_column_index,
                join_kind,
                projections.as_ref(),
            )),
            PreparedQueryFastPath::SimpleInnerJoinGroupedAggregate {
                left_root_page,
                left_join_source,
                left_join_rowid_alias_column_index,
                left_group_source,
                left_group_rowid_alias_column_index,
                right_root_page,
                right_join_source,
                right_index_root_page,
                right_join_column_index,
                right_join_rowid_alias_column_index,
                sum_source,
                right_sum_rowid_alias_column_index,
                having_count_filter,
            } => self.prepared_inner_join_grouped_aggregate_rows(
                left_root_page,
                left_join_source,
                left_join_rowid_alias_column_index,
                left_group_source,
                left_group_rowid_alias_column_index,
                right_root_page,
                right_join_source,
                right_index_root_page,
                right_join_column_index,
                right_join_rowid_alias_column_index,
                sum_source,
                right_sum_rowid_alias_column_index,
                having_count_filter.as_ref(),
            ),
            PreparedQueryFastPath::TopCategoryCteJoin { plan } => {
                self.execute_top_category_cte_join_plan_fast_path(plan)
            }
            PreparedQueryFastPath::SimpleRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
            } => {
                let Some(SqliteValue::Integer(rowid)) = params.get(parameter_index) else {
                    return Ok(None);
                };
                let rows = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    match table.row_values_by_rowid(*rowid) {
                        Some(values) => {
                            vec![row_from_memdb_row_values(
                                *rowid,
                                values,
                                rowid_alias_column_index,
                            )]
                        }
                        None => Vec::new(),
                    }
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleProjectedRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
                projections,
            } => {
                let Some(SqliteValue::Integer(rowid)) = params.get(parameter_index) else {
                    return Ok(None);
                };
                let rows = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    match table.row_values_by_rowid(*rowid) {
                        Some(values) => vec![row_from_memdb_value_sources(
                            *rowid,
                            values,
                            projections.as_ref(),
                            rowid_alias_column_index,
                        )],
                        None => Vec::new(),
                    }
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleIndexedEqualityLookup {
                root_page,
                index_root_page,
                column_index,
                parameter_index,
                rowid_alias_column_index,
                projections,
            } => {
                let Some(probe_value) = params.get(parameter_index) else {
                    return Ok(None);
                };
                if matches!(probe_value, SqliteValue::Null) {
                    return Ok(Some(Vec::new()));
                }
                let SqliteValue::Text(_) = probe_value else {
                    return Ok(None);
                };
                let cache_key = self.prepared_indexed_equality_cache_key(
                    root_page,
                    index_root_page,
                    column_index,
                );
                let rows = if let Some(rows) = self.last_prepared_indexed_equality_rows(
                    cache_key,
                    rowid_alias_column_index,
                    projections.as_ref(),
                    probe_value,
                ) {
                    rows
                } else {
                    let Some(rows) = self.with_prepared_indexed_equality_rowids_for_key(
                        cache_key,
                        probe_value,
                        |rowids| {
                            let db = self.db.borrow();
                            let Some(table) = db.get_table(root_page) else {
                                return None;
                            };
                            let mut rows = Vec::with_capacity(rowids.len());
                            for rowid in rowids.iter().copied() {
                                let Some(values) = table.row_values_by_rowid(rowid) else {
                                    return None;
                                };
                                rows.push(match projections.as_deref() {
                                    Some(projections) => row_from_memdb_value_sources(
                                        rowid,
                                        values,
                                        projections,
                                        rowid_alias_column_index,
                                    ),
                                    None => row_from_memdb_row_values(
                                        rowid,
                                        values,
                                        rowid_alias_column_index,
                                    ),
                                });
                            }
                            Some(rows)
                        },
                    ) else {
                        return Ok(None);
                    };
                    let Some(rows) = rows else {
                        return Ok(None);
                    };
                    self.store_prepared_indexed_equality_last_result(
                        cache_key,
                        rowid_alias_column_index,
                        projections.as_ref(),
                        probe_value,
                        &rows,
                    );
                    rows
                };
                Ok(Some(rows))
            }
            PreparedQueryFastPath::SimpleRowidRangeScan {
                root_page,
                lower_parameter_index,
                upper_parameter_index,
                rowid_alias_column_index,
            } => {
                let Some(SqliteValue::Integer(lower)) = params.get(lower_parameter_index) else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(upper)) = params.get(upper_parameter_index) else {
                    return Ok(None);
                };
                let rows = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    let row_count = if lower >= upper {
                        0
                    } else {
                        table.count_rowid_range(*lower, *upper)
                    };
                    let mut rows = Vec::with_capacity(row_count);
                    if lower < upper {
                        for (rowid, values) in table.iter_rows_in_rowid_range(*lower, *upper) {
                            rows.push(row_from_memdb_row_values(
                                rowid,
                                values,
                                rowid_alias_column_index,
                            ));
                        }
                    }
                    rows
                };
                Ok(Some(rows))
            }
            _ => Ok(None),
        }
    }

    fn try_execute_prepared_query_row_fast_path(
        &self,
        stmt: &PreparedStatement<'_>,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<QueryRowCollectionOutcome>> {
        let Some(fast_path) = stmt.prepared_query_fast_path.clone() else {
            return Ok(None);
        };
        if !self.prepared_memdb_query_fast_path_ready(stmt) {
            return Ok(None);
        }

        match fast_path {
            PreparedQueryFastPath::SimpleFullTableScan { .. }
            | PreparedQueryFastPath::SimpleOrderByLimit { .. }
            | PreparedQueryFastPath::SimpleLimitedScalarRowidSubquery { .. }
            | PreparedQueryFastPath::SimpleStringScalarProjection { .. }
            | PreparedQueryFastPath::SimpleGroupConcatByColumn { .. }
            | PreparedQueryFastPath::SimpleIndexedTwoTableJoin { .. }
            | PreparedQueryFastPath::SimpleInnerJoinGroupedAggregate { .. }
            | PreparedQueryFastPath::TopCategoryCteJoin { .. } => Ok(None),
            // bd-wwqen.4 B4.2: Direct MemDB rowid range scan for query_row.
            PreparedQueryFastPath::SimpleRowidRangeScan {
                root_page,
                lower_parameter_index,
                upper_parameter_index,
                rowid_alias_column_index,
            } => {
                let Some(params) = params else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(lower)) = params.get(lower_parameter_index) else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(upper)) = params.get(upper_parameter_index) else {
                    return Ok(None);
                };
                let db = self.db.borrow();
                let Some(table) = db.get_table(root_page) else {
                    return Ok(None);
                };
                let mut found_row: Option<Vec<SqliteValue>> = None;
                for (rowid, values) in table.iter_rows_in_rowid_range(*lower, *upper) {
                    if found_row.is_some() {
                        return Ok(Some(QueryRowCollectionOutcome::MultipleRows));
                    }
                    let mut row_vec = values.to_vec();
                    if let Some(ipk_idx) = rowid_alias_column_index {
                        if let Some(slot) = row_vec.get_mut(ipk_idx) {
                            *slot = SqliteValue::Integer(rowid);
                        }
                    }
                    found_row = Some(row_vec);
                }
                match found_row {
                    Some(row) => Ok(Some(QueryRowCollectionOutcome::Row(Row { values: row }))),
                    None => Ok(Some(QueryRowCollectionOutcome::NoRows)),
                }
            }
            // bd-wwqen.4 B4.1: Direct MemDB equality scan for indexed
            // equality lookup, replacing the VDBE engine path.
            PreparedQueryFastPath::SimpleIndexedEqualityLookup {
                root_page,
                index_root_page,
                column_index,
                parameter_index,
                rowid_alias_column_index,
                projections,
            } => {
                let Some(probe_value) = params.and_then(|p| p.get(parameter_index)) else {
                    return Ok(None);
                };
                if matches!(probe_value, SqliteValue::Null) {
                    return Ok(Some(QueryRowCollectionOutcome::NoRows));
                }
                let SqliteValue::Text(_) = probe_value else {
                    return Ok(None);
                };
                let Some(outcome) = self.with_prepared_indexed_equality_rowids(
                    root_page,
                    index_root_page,
                    column_index,
                    probe_value,
                    |rowids| {
                        let Some((&rowid, remaining_rowids)) = rowids.split_first() else {
                            return Some(QueryRowCollectionOutcome::NoRows);
                        };
                        if !remaining_rowids.is_empty() {
                            return Some(QueryRowCollectionOutcome::MultipleRows);
                        }
                        let db = self.db.borrow();
                        let table = db.get_table(root_page)?;
                        let values = table.row_values_by_rowid(rowid)?;
                        Some(QueryRowCollectionOutcome::Row(
                            match projections.as_deref() {
                                Some(projections) => row_from_memdb_value_sources(
                                    rowid,
                                    values,
                                    projections,
                                    rowid_alias_column_index,
                                ),
                                None => row_from_memdb_row_values(
                                    rowid,
                                    values,
                                    rowid_alias_column_index,
                                ),
                            },
                        ))
                    },
                ) else {
                    return Ok(None);
                };
                Ok(outcome)
            }
            PreparedQueryFastPath::SimpleCountStar { root_page } => {
                if !self.memdb_storage_count_shortcuts_safe.get() {
                    return Ok(None);
                }
                let count = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    i64::try_from(table.row_count()).map_err(|_| {
                        FrankenError::Internal(format!(
                            "table row count exceeds i64 for root page {root_page}"
                        ))
                    })?
                };
                Ok(Some(QueryRowCollectionOutcome::Row(Row {
                    values: vec![SqliteValue::Integer(count)],
                })))
            }
            PreparedQueryFastPath::SimpleCountStarSum {
                root_page,
                sum_column_index,
                rowid_alias_column_index,
            } => Ok(self
                .prepared_count_star_sum_row(root_page, sum_column_index, rowid_alias_column_index)?
                .map(QueryRowCollectionOutcome::Row)),
            PreparedQueryFastPath::SimpleCountLikePattern {
                root_page,
                column_index,
                rowid_alias_column_index,
                kind,
                literal,
            } => {
                if !self.memdb_storage_count_shortcuts_safe.get() {
                    return Ok(None);
                }
                let count = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    let matcher = SqlLikeFastPathMatcher::new_cased(
                        kind,
                        literal.as_ref(),
                        case_sensitive_like_active(),
                    );
                    i64::try_from(
                        table
                            .iter_rows()
                            .filter(|(rowid, row_values)| {
                                memdb_row_matches_like_fast_path(
                                    *rowid,
                                    row_values,
                                    column_index,
                                    rowid_alias_column_index,
                                    &matcher,
                                )
                            })
                            .count(),
                    )
                    .map_err(|_| {
                        FrankenError::Internal(format!(
                            "LIKE count exceeds i64 for root page {root_page}"
                        ))
                    })?
                };
                Ok(Some(QueryRowCollectionOutcome::Row(Row {
                    values: vec![SqliteValue::Integer(count)],
                })))
            }
            PreparedQueryFastPath::SimpleCountIndexedRowidProbe {
                root_page,
                index_root_page,
                column_index,
                probe_root_page,
                probe_rowid_upper_exclusive,
            } => Ok(self
                .prepared_count_indexed_rowid_probe_row(
                    root_page,
                    index_root_page,
                    column_index,
                    probe_root_page,
                    probe_rowid_upper_exclusive,
                )?
                .map(QueryRowCollectionOutcome::Row)),
            PreparedQueryFastPath::SimpleRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
            } => {
                let Some(params) = params else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(rowid)) = params.get(parameter_index) else {
                    return Ok(None);
                };
                let outcome =
                    {
                        let db = self.db.borrow();
                        let Some(table) = db.get_table(root_page) else {
                            return Ok(None);
                        };
                        match table.row_values_by_rowid(*rowid) {
                            Some(values) => QueryRowCollectionOutcome::Row(
                                row_from_memdb_row_values(*rowid, values, rowid_alias_column_index),
                            ),
                            None => QueryRowCollectionOutcome::NoRows,
                        }
                    };
                Ok(Some(outcome))
            }
            PreparedQueryFastPath::SimpleProjectedRowidLookup {
                root_page,
                parameter_index,
                rowid_alias_column_index,
                projections,
            } => {
                let Some(params) = params else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(rowid)) = params.get(parameter_index) else {
                    return Ok(None);
                };
                let outcome = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    match table.row_values_by_rowid(*rowid) {
                        Some(values) => {
                            QueryRowCollectionOutcome::Row(row_from_memdb_value_sources(
                                *rowid,
                                values,
                                projections.as_ref(),
                                rowid_alias_column_index,
                            ))
                        }
                        None => QueryRowCollectionOutcome::NoRows,
                    }
                };
                Ok(Some(outcome))
            }
            PreparedQueryFastPath::SimpleCountStarRowidRange {
                root_page,
                lower_parameter_index,
                upper_parameter_index,
            } => {
                if !self.memdb_storage_count_shortcuts_safe.get() {
                    return Ok(None);
                }
                let Some(params) = params else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(lower)) = params.get(lower_parameter_index) else {
                    return Ok(None);
                };
                let Some(SqliteValue::Integer(upper)) = params.get(upper_parameter_index) else {
                    return Ok(None);
                };
                let count = {
                    let db = self.db.borrow();
                    let Some(table) = db.get_table(root_page) else {
                        return Ok(None);
                    };
                    if lower >= upper {
                        0
                    } else {
                        table.count_rowid_range(*lower, *upper)
                    }
                };
                let count = i64::try_from(count).map_err(|_| {
                    FrankenError::Internal(format!(
                        "table row range count exceeds i64 for root page {root_page}"
                    ))
                })?;
                Ok(Some(QueryRowCollectionOutcome::Row(Row {
                    values: vec![SqliteValue::Integer(count)],
                })))
            }
        }
    }

    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    fn execute_prepared_dml_entry<F>(
        &self,
        execution_cx: &Cx,
        statement_kind: &'static str,
        dirty_table_name: Option<&str>,
        rollback_on_constraint_violation: bool,
        preserve_prior_changes_on_constraint_violation: bool,
        skip_statement_savepoint_in_explicit_txn: bool,
        capture_time_travel_snapshot: bool,
        prebound_publication: Option<BoundPagerPublication>,
        autocommit_profile_mode: PreparedDmlAutocommitProfileMode,
        execute_body: F,
    ) -> PreparedDmlEntryExecutionOutcome
    where
        F: FnOnce() -> Result<usize>,
    {
        let direct_insert_autocommit_candidate = hot_path_profile_enabled()
            && autocommit_profile_mode == PreparedDmlAutocommitProfileMode::PreparedDirectInsert
            && self.active_txn.borrow().is_none()
            && !self.in_transaction.get();
        let autocommit_begin_start = direct_insert_autocommit_candidate.then(Instant::now);
        let was_auto = match self
            .ensure_autocommit_txn_with_publication_hint(execution_cx, prebound_publication)
        {
            Ok(was_auto) => was_auto,
            Err(error) => {
                return PreparedDmlEntryExecutionOutcome {
                    result: Err(error),
                    execution_ok: false,
                    resolve_succeeded: false,
                };
            }
        };
        if direct_insert_autocommit_candidate && was_auto {
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_INSERT_AUTOCOMMIT_BEGIN_TIME_NS,
                autocommit_begin_start,
            );
            if hot_path_profile_enabled() {
                FSQLITE_PREPARED_DIRECT_INSERT_AUTOCOMMIT_EXECUTIONS
                    .fetch_add(1, AtomicOrdering::Relaxed);
            }
        }

        let previous_total_changes = self.total_changes.get();
        let previous_last_insert_rowid = self.current_last_insert_rowid();
        self.txn_metrics_note_write();
        let use_statement_savepoint = !skip_statement_savepoint_in_explicit_txn
            && self.should_use_statement_savepoint(
                was_auto,
                preserve_prior_changes_on_constraint_violation,
            );
        let execute_body_start = hot_path_profile_enabled().then(Instant::now);
        let mut execute_body = Some(execute_body);
        let result = if use_statement_savepoint {
            self.with_internal_statement_savepoint_and_cx_policy(
                execution_cx,
                statement_kind,
                preserve_prior_changes_on_constraint_violation,
                || {
                    execute_body
                        .take()
                        .expect("prepared DML body should only run once")()
                },
            )
        } else {
            execute_body
                .take()
                .expect("prepared DML body should only run once")()
        };
        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
        let result = match result {
            Ok(affected) => Ok(affected),
            Err(error) => {
                self.restore_failed_statement_tracking(
                    preserve_prior_changes_on_constraint_violation,
                    &error,
                    previous_total_changes,
                    previous_last_insert_rowid,
                );
                match self.maybe_rollback_transaction_for_conflict_action(
                    rollback_on_constraint_violation,
                    was_auto,
                    &error,
                ) {
                    Ok(()) => Err(error),
                    Err(rollback_error) => Err(rollback_error),
                }
            }
        };
        let commit_autocommit_on_error = was_auto
            && matches!(
                result.as_ref(),
                Err(error) if error_preserves_prior_statement_rows(
                    preserve_prior_changes_on_constraint_violation,
                    error,
                )
            );
        let execution_ok = result.is_ok() || commit_autocommit_on_error;
        let autocommit_resolve_start =
            (direct_insert_autocommit_candidate && was_auto).then(Instant::now);
        let resolve_result = self.resolve_autocommit_txn_with_dirty_table_and_capture_and_cx(
            was_auto,
            execution_ok,
            dirty_table_name,
            capture_time_travel_snapshot,
            false,
            execution_cx,
        );
        if direct_insert_autocommit_candidate && was_auto {
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_INSERT_AUTOCOMMIT_RESOLVE_TIME_NS,
                autocommit_resolve_start,
            );
        }

        match resolve_result {
            Ok(()) => PreparedDmlEntryExecutionOutcome {
                result,
                execution_ok,
                resolve_succeeded: true,
            },
            Err(error) => PreparedDmlEntryExecutionOutcome {
                result: Err(error),
                execution_ok,
                resolve_succeeded: false,
            },
        }
    }

    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    fn execute_precompiled_prepared_insert(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        table_name: &str,
        post_write_action: PreparedInsertPostWriteAction,
        rollback_on_constraint_violation: bool,
        preserve_prior_changes_on_constraint_violation: bool,
        skip_statement_savepoint_in_explicit_txn: bool,
        prebound_publication: Option<BoundPagerPublication>,
        params: Option<&[SqliteValue]>,
        capture_time_travel_snapshot: bool,
    ) -> Result<usize> {
        self.clear_table_program_error_state();
        // Issue #110: an `INSERT OR REPLACE` / upsert can delete or mutate an
        // existing row (possibly a parent of a previously cached child FK).
        // This prepared lane bypasses the central dispatcher, so drop the
        // transaction-scoped FK parent-validation cache here. The hot plain-
        // INSERT path leaves the flag `false`, so the cache survives.
        if stmt
            .precompiled_dml()
            .is_some_and(|dml| dml.insert_may_invalidate_fk_parent_cache)
        {
            self.clear_fk_parent_validation_cache();
        }
        if stmt.may_observe_change_tracking {
            self.sync_change_tracking_context();
        }
        let statement_trace_enabled =
            tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG);
        let statement_reuse_enabled =
            tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO);
        let trace_registration = {
            let trace_registration = self.trace_registration.borrow();
            let compat_trace_stmt_enabled = trace_registration
                .as_ref()
                .is_some_and(|trace| trace.mask.contains(TraceMask::STMT));
            let compat_trace_profile_enabled = trace_registration
                .as_ref()
                .is_some_and(|trace| trace.mask.contains(TraceMask::PROFILE));
            // bd-db300.5.2.2.4: forced_fallback control mode bypasses the
            // fast lane so every prepared INSERT takes the instrumented path.
            let fused_control_mode = self.fused_entry_control_mode.get();
            let forced_fallback = fused_control_mode == FusedEntryControlMode::ForcedFallback;
            if !forced_fallback
                && !statement_trace_enabled
                && !compat_trace_stmt_enabled
                && !compat_trace_profile_enabled
                && !statement_reuse_enabled
            {
                if hot_path_profile_enabled() {
                    FSQLITE_PREPARED_INSERT_FAST_LANE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                tracing::debug!(
                    target: "fsqlite::fused_entry",
                    entry_path = "fused",
                    control_mode = %fused_control_mode,
                    dml_kind = "insert",
                    fallback_reason = "none",
                    "fused entry: insert fast lane"
                );
                return self.execute_precompiled_prepared_insert_fast(
                    execution_cx,
                    stmt,
                    table_name,
                    post_write_action,
                    skip_statement_savepoint_in_explicit_txn,
                    prebound_publication,
                    rollback_on_constraint_violation,
                    preserve_prior_changes_on_constraint_violation,
                    params,
                    capture_time_travel_snapshot,
                );
            }
            trace_registration.clone()
        };
        if hot_path_profile_enabled() {
            FSQLITE_PREPARED_INSERT_INSTRUMENTED_LANE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        let fused_control_mode = self.fused_entry_control_mode.get();
        tracing::debug!(
            target: "fsqlite::fused_entry",
            entry_path = "conservative",
            control_mode = %fused_control_mode,
            dml_kind = "insert",
            fallback_reason = if fused_control_mode == FusedEntryControlMode::ForcedFallback {
                "forced_fallback"
            } else {
                "tracing_or_reuse_enabled"
            },
            "fused entry: insert instrumented lane"
        );
        let trace_id = statement_trace_enabled.then(next_trace_id).unwrap_or(0);
        let decision_id = statement_trace_enabled.then(next_decision_id).unwrap_or(0);
        let compat_trace_stmt_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::STMT));
        let compat_trace_profile_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::PROFILE));
        let compat_trace_sql = (compat_trace_stmt_enabled || compat_trace_profile_enabled)
            .then(|| Rc::clone(&stmt.sql));
        let statement_span = statement_trace_enabled.then(|| {
            let span = tracing::span!(
                target: "fsqlite.statement",
                tracing::Level::DEBUG,
                "statement",
                trace_id,
                decision_id,
                statement_kind = "insert"
            );
            record_trace_span_created();
            span
        });
        let _statement_guard = statement_span.as_ref().map(tracing::Span::enter);
        if compat_trace_stmt_enabled {
            emit_compat_trace_event(
                trace_registration.as_ref(),
                TraceEvent::Statement {
                    sql: compat_trace_sql
                        .clone()
                        .unwrap_or_else(|| Rc::clone(&stmt.sql))
                        .as_ref()
                        .to_owned(),
                },
            );
        }
        let execution_started = (statement_reuse_enabled || compat_trace_profile_enabled)
            .then(fsqlite_types::sync_primitives::Instant::now);
        let outcome = self.execute_prepared_dml_entry(
            execution_cx,
            "insert",
            Some(table_name),
            rollback_on_constraint_violation,
            preserve_prior_changes_on_constraint_violation,
            skip_statement_savepoint_in_explicit_txn,
            capture_time_travel_snapshot,
            prebound_publication,
            PreparedDmlAutocommitProfileMode::None,
            || {
                self.execute_precompiled_prepared_insert_dispatch(
                    execution_cx,
                    stmt,
                    table_name,
                    post_write_action,
                    params,
                )
            },
        );
        if outcome.resolve_succeeded && (statement_reuse_enabled || compat_trace_profile_enabled) {
            let elapsed_ns = execution_started
                .map(|started| u64::try_from(started.elapsed().as_nanos()).unwrap_or(u64::MAX))
                .unwrap_or(0);
            if statement_reuse_enabled {
                let failure_diag = match outcome.result.as_ref() {
                    Ok(_) => Cow::Borrowed("none"),
                    Err(error) => Cow::Owned(error.to_string()),
                };
                self.log_statement_reuse_event(
                    "execution",
                    stmt.sql.as_ref(),
                    true,
                    if outcome.execution_ok {
                        "none"
                    } else {
                        "execution_error"
                    },
                    0,
                    elapsed_ns,
                    failure_diag.as_ref(),
                );
            }
            if compat_trace_profile_enabled {
                emit_compat_trace_event(
                    trace_registration.as_ref(),
                    TraceEvent::Profile {
                        sql: compat_trace_sql
                            .unwrap_or_else(|| Rc::clone(&stmt.sql))
                            .as_ref()
                            .to_owned(),
                        elapsed_ns,
                    },
                );
            }
        }
        outcome.result
    }

    #[allow(clippy::too_many_arguments)]
    fn try_execute_precompiled_prepared_insert_autocommit_direct_simple_fast(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        table_name: &str,
        post_write_action: PreparedInsertPostWriteAction,
        rollback_on_constraint_violation: bool,
        preserve_prior_changes_on_constraint_violation: bool,
        prebound_publication: Option<BoundPagerPublication>,
        params: Option<&[SqliteValue]>,
        capture_time_travel_snapshot: bool,
    ) -> Option<Result<usize>> {
        if stmt.may_observe_change_tracking
            || !matches!(post_write_action, PreparedInsertPostWriteAction::None)
            || self.in_transaction.get()
            || self.active_txn.borrow().is_some()
        {
            return None;
        }

        let direct = stmt
            .precompiled_dml()?
            .direct_simple_insert
            .as_ref()
            .filter(|direct| !Self::direct_simple_insert_prefers_reusable_table_program(direct))?;
        if self.fk_enforcement_enabled() && self.table_has_outbound_foreign_keys(table_name) {
            return None;
        }

        let autocommit_begin_start = hot_path_profile_enabled().then(Instant::now);
        let was_auto = match self
            .ensure_autocommit_txn_with_publication_hint(execution_cx, prebound_publication)
        {
            Ok(was_auto) => was_auto,
            Err(error) => return Some(Err(error)),
        };
        if !was_auto {
            return None;
        }
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_AUTOCOMMIT_BEGIN_TIME_NS,
            autocommit_begin_start,
        );
        if hot_path_profile_enabled() {
            FSQLITE_PREPARED_DIRECT_INSERT_AUTOCOMMIT_EXECUTIONS
                .fetch_add(1, AtomicOrdering::Relaxed);
        }

        self.txn_metrics_note_write();
        let execute_body_start = hot_path_profile_enabled().then(Instant::now);
        let result = match self.execute_prepared_direct_simple_insert(
            execution_cx,
            table_name,
            direct,
            params,
        ) {
            Ok(last_insert_rowid) => {
                record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
                let affected = usize::from(last_insert_rowid.is_some());
                if let Some(last_insert_rowid) = last_insert_rowid {
                    self.set_last_insert_rowid_without_sync(last_insert_rowid);
                }
                let change_tracking_start = hot_path_profile_enabled().then(Instant::now);
                self.record_statement_changes_without_sync(affected);
                record_hot_path_duration(
                    &FSQLITE_PREPARED_DIRECT_INSERT_CHANGE_TRACKING_TIME_NS,
                    change_tracking_start,
                );
                Ok(affected)
            }
            Err(error) => {
                record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
                self.reset_statement_change_count();
                match self.maybe_rollback_transaction_for_conflict_action(
                    rollback_on_constraint_violation,
                    was_auto,
                    &error,
                ) {
                    Ok(()) => Err(error),
                    Err(rollback_error) => Err(rollback_error),
                }
            }
        };

        let commit_autocommit_on_error = matches!(
            result.as_ref(),
            Err(error) if error_preserves_prior_statement_rows(
                preserve_prior_changes_on_constraint_violation,
                error,
            )
        );
        let ok = result.is_ok() || commit_autocommit_on_error;
        let autocommit_resolve_start = hot_path_profile_enabled().then(Instant::now);
        if matches!(result.as_ref(), Ok(0)) {
            // A zero-row direct INSERT (for example INSERT OR IGNORE on a
            // duplicate key) did not mutate the table. If an earlier retained
            // statement in the same parked batch already made the transaction
            // dirty, the commit resolver will still run the retained parking
            // branch; preserve any count+sum cache through that no-op mark.
            self.preserve_retained_autocommit_count_sum_cache_for_noop_write();
        }
        let resolve_result = self.resolve_autocommit_txn_with_dirty_table_and_capture_and_cx(
            was_auto,
            ok,
            Some(table_name),
            capture_time_travel_snapshot,
            false,
            execution_cx,
        );
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_AUTOCOMMIT_RESOLVE_TIME_NS,
            autocommit_resolve_start,
        );
        Some(match resolve_result {
            Ok(()) => result,
            Err(error) => Err(error),
        })
    }

    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    fn execute_precompiled_prepared_insert_fast(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        table_name: &str,
        post_write_action: PreparedInsertPostWriteAction,
        skip_statement_savepoint_in_explicit_txn: bool,
        prebound_publication: Option<BoundPagerPublication>,
        rollback_on_constraint_violation: bool,
        preserve_prior_changes_on_constraint_violation: bool,
        params: Option<&[SqliteValue]>,
        capture_time_travel_snapshot: bool,
    ) -> Result<usize> {
        // bd-pktso: In-transaction fast path — skip ceremony for repeated prepared
        // INSERT within an explicit BEGIN..COMMIT. Schema is unchanged (validated
        // at prepare time and checked once at first execution). Saves ~90ns/row.
        if self.in_transaction.get()
            && self.active_txn.borrow().is_some()
            && matches!(post_write_action, PreparedInsertPostWriteAction::None)
            && !capture_time_travel_snapshot
            && !stmt.may_observe_change_tracking
            && skip_statement_savepoint_in_explicit_txn
            && !rollback_on_constraint_violation
        {
            if let Some(direct) = stmt
                .precompiled_dml()
                .and_then(|d| d.direct_simple_insert.as_ref())
                .filter(|d| !Self::direct_simple_insert_prefers_reusable_table_program(d))
            {
                self.txn_metrics_note_write();
                let execute_body_start = hot_path_profile_enabled().then(Instant::now);
                let result = self.execute_prepared_direct_simple_insert(
                    execution_cx,
                    table_name,
                    direct,
                    params,
                );
                match result {
                    Ok(Some(rowid)) => {
                        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
                        let change_tracking_start = hot_path_profile_enabled().then(Instant::now);
                        self.set_last_insert_rowid_without_sync(rowid);
                        self.record_statement_changes_without_sync(1);
                        record_hot_path_duration(
                            &FSQLITE_PREPARED_DIRECT_INSERT_CHANGE_TRACKING_TIME_NS,
                            change_tracking_start,
                        );
                        return Ok(1);
                    }
                    Ok(None) => {
                        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
                        let change_tracking_start = hot_path_profile_enabled().then(Instant::now);
                        self.record_statement_changes_without_sync(0);
                        record_hot_path_duration(
                            &FSQLITE_PREPARED_DIRECT_INSERT_CHANGE_TRACKING_TIME_NS,
                            change_tracking_start,
                        );
                        return Ok(0);
                    }
                    Err(FrankenError::NotImplemented(_)) => {
                        // Fall through to standard path
                    }
                    Err(e) => {
                        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
                        self.reset_statement_change_count();
                        return Err(e);
                    }
                }
            }
        }
        if let Some(result) = self
            .try_execute_precompiled_prepared_insert_autocommit_direct_simple_fast(
                execution_cx,
                stmt,
                table_name,
                post_write_action,
                rollback_on_constraint_violation,
                preserve_prior_changes_on_constraint_violation,
                prebound_publication,
                params,
                capture_time_travel_snapshot,
            )
        {
            return result;
        }
        let direct_simple_insert_profile = stmt.precompiled_dml().is_some_and(|dispatch| {
            dispatch
                .direct_simple_insert
                .as_ref()
                .is_some_and(|direct| {
                    !Self::direct_simple_insert_prefers_reusable_table_program(direct)
                })
        });
        let outcome = self.execute_prepared_dml_entry(
            execution_cx,
            "insert",
            Some(table_name),
            rollback_on_constraint_violation,
            preserve_prior_changes_on_constraint_violation,
            skip_statement_savepoint_in_explicit_txn,
            capture_time_travel_snapshot,
            prebound_publication,
            if direct_simple_insert_profile {
                PreparedDmlAutocommitProfileMode::PreparedDirectInsert
            } else {
                PreparedDmlAutocommitProfileMode::None
            },
            || {
                self.execute_precompiled_prepared_insert_dispatch(
                    execution_cx,
                    stmt,
                    table_name,
                    post_write_action,
                    params,
                )
            },
        );
        outcome.result
    }

    fn execute_precompiled_prepared_insert_dispatch(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        table_name: &str,
        post_write_action: PreparedInsertPostWriteAction,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        let direct_simple_insert = stmt
            .precompiled_dml()
            .and_then(|dispatch| dispatch.direct_simple_insert.as_ref());
        let direct_simple_insert_profile = hot_path_profile_enabled()
            && direct_simple_insert.is_some_and(|direct| {
                !Self::direct_simple_insert_prefers_reusable_table_program(direct)
            });
        // s76h: track whether the inner path already enforced FK. The
        // direct-simple INSERT lane (Path B) checks FK in
        // execute_prepared_direct_simple_insert at the
        // direct_insert_requires_fk_check site. The reusable-table-program
        // lane (Path A), the NotImplemented fallback (Path C), and the
        // no-direct-dispatch lane (Path D) all run the VDBE program via
        // execute_table_program_dml_with_reuse, which does not enforce FK.
        // Mirror the non-prepared dispatch path's post-execute FK check for
        // those three lanes.
        let mut fk_enforced_by_inner = false;
        let (affected, last_insert_rowid) = if let Some(direct_simple_insert) = direct_simple_insert
        {
            if Self::direct_simple_insert_prefers_reusable_table_program(direct_simple_insert) {
                self.clear_prepared_direct_insert_append_hint();
                // bd-perf: Skip memdb refresh for VDBE DML path — the VDBE engine
                // operates through storage cursors (pager/btree), not MemDatabase.
                // Refreshing memdb here caused O(n²) behavior: each INSERT triggered
                // a full table scan to reload all existing rows into memdb.
                // The memdb will be lazily refreshed on the next read boundary.
                stmt.execute_table_program_dml_with_reuse(execution_cx, params, true)?
            } else {
                match self.execute_prepared_direct_simple_insert(
                    execution_cx,
                    table_name,
                    direct_simple_insert,
                    params,
                ) {
                    Ok(Some(rowid)) => {
                        fk_enforced_by_inner = true;
                        (1, Some(rowid))
                    }
                    Ok(None) => {
                        fk_enforced_by_inner = true;
                        (0, None)
                    }
                    Err(FrankenError::NotImplemented(_)) => {
                        self.clear_prepared_direct_insert_append_hint();
                        let outcome = self
                            .execute_prepared_insert_table_program_after_direct_fallback(
                                execution_cx,
                                stmt,
                                params,
                            )?;
                        // The fallback already enforces FK at its own exit
                        // (see s76h fix in
                        // execute_prepared_insert_table_program_after_direct_fallback).
                        fk_enforced_by_inner = true;
                        outcome
                    }
                    Err(error) => return Err(error),
                }
            }
        } else {
            self.clear_prepared_direct_insert_append_hint();
            // bd-perf: Skip memdb refresh — VDBE uses storage cursors
            stmt.execute_table_program_dml_with_reuse(execution_cx, params, true)?
        };
        // Gate FK enforcement on a row actually landing: an OR IGNORE PK
        // conflict drops the row (affected == 0) and SQLite does not FK-check a
        // row it never inserted (#111).
        if affected > 0
            && !fk_enforced_by_inner
            && self.fk_enforcement_enabled()
            && self.table_has_outbound_foreign_keys(table_name)
        {
            // Only re-parse on the cold FK path (rare: inserts into tables
            // with outbound FKs that didn't take the direct-simple lane).
            let statement = parse_single_statement(stmt.sql.as_ref())?;
            let Statement::Insert(insert) = statement else {
                return Err(FrankenError::internal(
                    "prepared INSERT FK enforcement expected canonical INSERT SQL",
                ));
            };
            if let Err(error) = self.enforce_fk_on_insert(&insert, table_name, params) {
                // The reusable table program has already completed every
                // physical row before this statement-boundary FK validation.
                // SQLite rolls those rows back and reports changes() == 0,
                // while retaining the last rowid attempted by the completed
                // multi-row program. Publish that attempted rowid to the
                // statement error unwinder without counting the rolled-back
                // outer rows in total_changes().
                self.record_table_program_error_state_with_total_changes(
                    0,
                    last_insert_rowid,
                    Some(self.total_changes.get()),
                );
                return Err(error);
            }
        }
        match post_write_action {
            PreparedInsertPostWriteAction::None => {}
            PreparedInsertPostWriteAction::RefreshSqliteSequenceCache => {
                self.refresh_sqlite_sequence_cache()?;
            }
            PreparedInsertPostWriteAction::RefreshAutoincrementSequence => {
                self.refresh_autoincrement_sequence_after_insert(
                    table_name,
                    affected,
                    last_insert_rowid,
                )?;
            }
        }
        if let Some(last_insert_rowid) = last_insert_rowid {
            self.set_last_insert_rowid_without_sync(last_insert_rowid);
        }
        let change_tracking_start = direct_simple_insert_profile.then(Instant::now);
        if stmt.may_observe_change_tracking {
            self.record_statement_changes(affected);
        } else {
            self.record_statement_changes_without_sync(affected);
        }
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_CHANGE_TRACKING_TIME_NS,
            change_tracking_start,
        );
        Ok(affected)
    }

    fn execute_prepared_insert_table_program_after_direct_fallback(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        params: Option<&[SqliteValue]>,
    ) -> Result<(usize, Option<i64>)> {
        let statement = parse_single_statement(stmt.sql.as_ref())?;
        let Statement::Insert(insert) = statement else {
            return Err(FrankenError::internal(
                "prepared INSERT fallback expected canonical INSERT SQL",
            ));
        };
        let sql_key = Self::sql_hash(stmt.sql.as_ref());
        let program = self.compile_with_cache(sql_key, stmt.sql.as_ref(), |conn| {
            conn.compile_table_insert(&insert)
        })?;
        let fallback_stmt = stmt.clone_with_program(program);
        // bd-perf: Skip memdb refresh — VDBE uses storage cursors and this
        // path only exists as a correctness fallback for the direct lane.
        let outcome =
            fallback_stmt.execute_table_program_dml_with_reuse(execution_cx, params, true)?;
        // s76h fix: this VDBE fallback runs the table program via reuse but
        // does not itself enforce FK. The non-prepared dispatch path enforces
        // FK after the table program (see Statement::Insert handler); mirror
        // that here so violations propagate as Err and the autocommit txn
        // rolls back the bad row. (Single-row VALUES FK inserts now stay on
        // the direct-simple lane with its own post-insert FK enforcement —
        // #111 — so this fallback FK path now covers the non-direct shapes:
        // multi-row VALUES, INSERT … SELECT, and any other NotImplemented
        // case.) Gate on `table_has_outbound_foreign_keys` to avoid the
        // `collect_insert_trigger_rows` re-evaluation cost when the table
        // has no FKs and the fallback fired for a non-FK NotImplemented case.
        // OR IGNORE PK-conflict rows are dropped by the table program
        // (outcome.0 == 0); SQLite does not run FK checks on a row it never
        // inserted, so gate FK enforcement on a row actually landing (#111).
        if outcome.0 > 0
            && self.fk_enforcement_enabled()
            && self.table_has_outbound_foreign_keys(&insert.table.name)
        {
            self.enforce_fk_on_insert(&insert, &insert.table.name, params)?;
        }
        Ok(outcome)
    }

    fn direct_simple_insert_prefers_reusable_table_program(
        direct: &PreparedDirectSimpleInsert,
    ) -> bool {
        // Phase-1 deterministic classifier: if prepare-time compilation
        // produced a compiled direct-row microplan, stay on the direct lane.
        // If the row still requires AST evaluation (functions, CASE, LIKE,
        // subquery-adjacent forms we intentionally leave unsupported here),
        // keep the reusable VDBE table program authoritative until that
        // shape is explicitly audited and proven safe.
        direct.prefers_reusable_table_program()
    }

    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    fn execute_prepared_direct_simple_insert_with_cursor<P: PageReader + PageWriter>(
        &self,
        execution_cx: &Cx,
        direct: &PreparedDirectSimpleInsert,
        explicit_rowid: Option<i64>,
        prepared_append_hint: &mut Option<PreparedDirectInsertAppendHint>,
        memdb_next_rowid_hint: Option<i64>,
        mem_row_values: &mut PreparedDirectInsertRowScratch,
        track_memdb_delta: bool,
        defer_memdb_upsert: bool,
        defer_lazy_memdb_materialization: bool,
        can_use_prebuilt_constant_record: bool,
        can_defer_page_run: bool,
        preserialized_record: Option<&[u8]>,
        profile_enabled: bool,
        cursor_setup_start: Option<Instant>,
        cursor: &mut fsqlite_btree::BtCursor<P>,
    ) -> Result<Option<i64>> {
        let (rowid, append_fast_path_candidate, use_prepared_append_hint) =
            if let Some(rowid) = explicit_rowid {
                let use_prepared_append_hint = prepared_append_hint
                    .as_ref()
                    .is_some_and(|hint| rowid > hint.last_rowid);
                if use_prepared_append_hint {
                    (rowid, true, true)
                } else if let Some(next_rowid_hint) = memdb_next_rowid_hint {
                    (rowid, rowid >= next_rowid_hint, false)
                } else if cursor.last(execution_cx)? {
                    let last_rowid = cursor.rowid(execution_cx)?;
                    (rowid, rowid > last_rowid, false)
                } else {
                    (rowid, true, false)
                }
            } else if let Some(hint) = prepared_append_hint.as_ref() {
                let rowid = hint.last_rowid.checked_add(1).ok_or_else(|| {
                    FrankenError::VdbeExecutionError {
                        detail: "rowid overflow: maximum rowid reached".to_owned(),
                    }
                })?;
                (rowid, true, true)
            } else if let Some(rowid) = memdb_next_rowid_hint {
                (rowid, true, false)
            } else if cursor.last(execution_cx)? {
                let rowid = cursor.rowid(execution_cx)?.checked_add(1).ok_or_else(|| {
                    FrankenError::VdbeExecutionError {
                        detail: "rowid overflow: maximum rowid reached".to_owned(),
                    }
                })?;
                (rowid, true, false)
            } else {
                (1, true, false)
            };
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_CURSOR_SETUP_TIME_NS,
            cursor_setup_start,
        );

        let conflict_action = direct
            .or_conflict
            .unwrap_or(fsqlite_ast::ConflictAction::Abort);
        let used_preserialized_record = preserialized_record.is_some();
        let mut record_scratch;
        let record_bytes = if let Some(record_bytes) = preserialized_record {
            record_bytes
        } else if can_use_prebuilt_constant_record {
            direct.prebuilt_constant_record.as_deref().ok_or_else(|| {
                FrankenError::internal(
                    "prepared direct insert constant-record fast path lost cached payload",
                )
            })?
        } else {
            record_scratch = self.prepared_direct_insert_record_scratch.borrow_mut();
            let serialize_start = profile_enabled.then(Instant::now);
            let mut cached_record_header = direct.cached_record_header.borrow_mut();
            let serialized_with_cached_header =
                cached_record_header.as_ref().is_some_and(|header| {
                    serialize_record_iter_with_precomputed_header_into(
                        mem_row_values.iter(),
                        header,
                        &mut record_scratch,
                    )
                });
            if !serialized_with_cached_header {
                serialize_record_iter_into(mem_row_values.iter(), &mut record_scratch);
                if cached_record_header.is_none() {
                    *cached_record_header =
                        try_build_runtime_precomputed_record_header(mem_row_values.as_slice());
                }
            }
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_INSERT_SERIALIZE_TIME_NS,
                serialize_start,
            );
            record_scratch.as_slice()
        };
        let btree_insert_start = profile_enabled.then(Instant::now);
        let can_buffer_current_page_run = can_defer_page_run
            && prepared_append_hint.is_none()
            && Self::can_buffer_prepared_direct_insert_page_run_record(
                can_use_prebuilt_constant_record,
                record_bytes,
            );
        let pending_insert_run_to_flush =
            if !can_buffer_current_page_run && self.pending_direct_insert_page_run_active.get() {
                self.pending_direct_insert_page_run.borrow_mut().take()
            } else {
                None
            };
        if let Some(run) = pending_insert_run_to_flush {
            self.pending_direct_insert_page_run_active.set(false);
            if run.root_page != direct.root_page
                || run.cursor_page_size != direct.cursor_page_size
                || run.cursor_reserved_per_page != direct.cursor_reserved_per_page
            {
                self.restore_pending_direct_insert_page_run(run);
                return Err(FrankenError::internal(
                    "pending direct insert page-run root changed without preflush",
                ));
            }
            self.flush_taken_pending_direct_insert_page_run_with_cursor(execution_cx, cursor, run)?;
        }
        fsqlite_vdbe::engine::record_external_insert_path_metric(append_fast_path_candidate);
        let buffered_page_run = can_buffer_current_page_run
            && self.try_buffer_prepared_direct_insert_page_run_with_cursor(
                execution_cx,
                direct,
                rowid,
                record_bytes,
                can_use_prebuilt_constant_record
                    && record_bytes.len() < PREPARED_DIRECT_INSERT_PAGE_RUN_MIN_RECORD_BYTES,
                cursor,
            )?;
        if buffered_page_run {
            self.clear_prepared_direct_insert_append_hint();
        } else {
            let mut append_fast_leaf_page = None;
            let mut append_cached_leaf = None;
            let insert_result = if use_prepared_append_hint {
                let append_hint = prepared_append_hint.as_mut().ok_or_else(|| {
                    FrankenError::internal("prepared direct insert lost owned append hint state")
                })?;
                if let Some(cached_leaf) = append_hint.cached_leaf.as_mut()
                    && cursor.table_try_append_cached_rightmost_leaf_hint(
                        execution_cx,
                        cached_leaf,
                        rowid,
                        record_bytes,
                    )?
                {
                    append_fast_leaf_page = Some(cached_leaf.leaf_page());
                    Ok(())
                } else {
                    match cursor.table_try_append_rightmost_leaf_hint_known_last_rowid_with_state(
                        execution_cx,
                        append_hint.leaf_page,
                        append_hint.last_rowid,
                        rowid,
                        record_bytes,
                    )? {
                        Some(cached_leaf) => {
                            append_fast_leaf_page = Some(cached_leaf.leaf_page());
                            append_hint.cached_leaf = Some(
                                self.prepare_prepared_direct_insert_cached_leaf_hint(cached_leaf),
                            );
                            Ok(())
                        }
                        None => cursor.table_append_after_last_position(
                            execution_cx,
                            rowid,
                            record_bytes,
                        ),
                    }
                }
            } else if append_fast_path_candidate {
                cursor.table_append_after_last_position(execution_cx, rowid, record_bytes)
            } else {
                cursor.table_insert(execution_cx, rowid, record_bytes)
            };
            let mut record_append_hint = false;
            let mut append_leaf_page = None;
            match insert_result {
                Ok(()) => {
                    if append_fast_path_candidate {
                        record_append_hint = true;
                        append_leaf_page = append_fast_leaf_page.or_else(|| cursor.current_page());
                        if prepared_append_hint
                            .as_ref()
                            .and_then(|hint| hint.cached_leaf.as_ref())
                            .is_none()
                        {
                            append_cached_leaf =
                                cursor
                                    .table_cached_rightmost_leaf_hint()
                                    .map(|cached_leaf| {
                                        self.prepare_prepared_direct_insert_cached_leaf_hint(
                                            cached_leaf,
                                        )
                                    });
                            if append_leaf_page.is_none() {
                                append_leaf_page =
                                    append_cached_leaf.as_ref().map(TableAppendHint::leaf_page);
                            }
                        }
                    }
                }
                Err(FrankenError::PrimaryKeyViolation) => match conflict_action {
                    fsqlite_ast::ConflictAction::Ignore => {
                        self.clear_prepared_direct_insert_append_hint_after_path_miss(
                            prepared_append_hint.as_ref(),
                        );
                        return Ok(None);
                    }
                    fsqlite_ast::ConflictAction::Replace => {
                        self.clear_prepared_direct_insert_append_hint_after_path_miss(
                            prepared_append_hint.as_ref(),
                        );
                        if !cursor.table_move_to(execution_cx, rowid)?.is_found() {
                            return Err(FrankenError::PrimaryKeyViolation);
                        }
                        cursor.delete(execution_cx)?;
                        cursor.table_insert(execution_cx, rowid, record_bytes)?;
                    }
                    fsqlite_ast::ConflictAction::Rollback
                    | fsqlite_ast::ConflictAction::Abort
                    | fsqlite_ast::ConflictAction::Fail => {
                        self.clear_prepared_direct_insert_append_hint_after_path_miss(
                            prepared_append_hint.as_ref(),
                        );
                        return Err(FrankenError::PrimaryKeyViolation);
                    }
                },
                Err(error) => {
                    self.clear_prepared_direct_insert_append_hint_after_path_miss(
                        prepared_append_hint.as_ref(),
                    );
                    return Err(error);
                }
            }
            if record_append_hint {
                if let Some(mut append_hint) = prepared_append_hint.take() {
                    append_hint.last_rowid = rowid;
                    if let Some(leaf_page) = append_leaf_page {
                        append_hint.leaf_page = leaf_page;
                    }
                    if append_cached_leaf.is_some() {
                        append_hint.cached_leaf = append_cached_leaf;
                    }
                    self.store_prepared_direct_insert_append_hint(Some(append_hint));
                } else {
                    self.store_prepared_direct_insert_append_hint(Some(
                        PreparedDirectInsertAppendHint {
                            root_page: direct.root_page,
                            leaf_page: append_leaf_page.ok_or_else(|| {
                                FrankenError::internal(
                                    "prepared direct insert append hint missing leaf page",
                                )
                            })?,
                            last_rowid: rowid,
                            cached_leaf: append_cached_leaf,
                        },
                    ));
                }
            } else {
                self.clear_prepared_direct_insert_append_hint_after_path_miss(
                    prepared_append_hint.as_ref(),
                );
            }
        }
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_BTREE_INSERT_TIME_NS,
            btree_insert_start,
        );
        Ok(Some(
            self.finish_prepared_direct_simple_insert_after_storage(
                direct,
                rowid,
                conflict_action,
                mem_row_values,
                track_memdb_delta,
                defer_memdb_upsert,
                defer_lazy_memdb_materialization,
                can_use_prebuilt_constant_record,
                used_preserialized_record,
                profile_enabled,
            ),
        ))
    }

    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    #[inline]
    fn finish_prepared_direct_simple_insert_after_storage(
        &self,
        direct: &PreparedDirectSimpleInsert,
        rowid: i64,
        conflict_action: fsqlite_ast::ConflictAction,
        mem_row_values: &mut PreparedDirectInsertRowScratch,
        track_memdb_delta: bool,
        defer_memdb_upsert: bool,
        defer_lazy_memdb_materialization: bool,
        can_use_prebuilt_constant_record: bool,
        used_preserialized_record: bool,
        profile_enabled: bool,
    ) -> i64 {
        if !can_use_prebuilt_constant_record
            && !used_preserialized_record
            && let Some(ipk_idx) = direct.rowid_alias_col_idx
        {
            mem_row_values[ipk_idx] = SqliteValue::Integer(rowid);
        }
        if !matches!(conflict_action, fsqlite_ast::ConflictAction::Replace) {
            self.retained_autocommit_count_sum_cache_note_insert(
                direct.root_page,
                mem_row_values.as_slice(),
            );
        } else {
            self.clear_retained_autocommit_count_sum_cache_for_root(direct.root_page);
        }
        let memdb_apply_start = profile_enabled.then(Instant::now);
        if track_memdb_delta {
            // Explicit transactions still need exact deferred row deltas because
            // SAVEPOINT / in-txn reads can force a MemDatabase boundary before
            // COMMIT. Autocommit `:memory:` writes do not: both retained-
            // autocommit batches and the cached-write-txn fast path leave the
            // compatibility mirror stale and repair it lazily on the next read
            // boundary.
            if used_preserialized_record {
                debug_assert!(defer_lazy_memdb_materialization);
                mem_row_values.clear();
                self.abandon_exact_memdb_row_mirror();
            } else if defer_memdb_upsert {
                let owned_values = std::mem::take(mem_row_values).into_vec();
                self.pending_memdb_direct_upserts
                    .borrow_mut()
                    .push(PendingMemdbDirectUpsert {
                        root_page: direct.root_page,
                        rowid,
                        num_columns: direct.columns.len(),
                        values: owned_values,
                    });
            } else if defer_lazy_memdb_materialization {
                mem_row_values.clear();
                self.abandon_exact_memdb_row_mirror();
            } else {
                let owned_values = std::mem::take(mem_row_values).into_vec();
                self.apply_prepared_direct_insert_memdb_row(
                    direct.root_page,
                    direct.columns.len(),
                    rowid,
                    owned_values,
                );
            }
        } else {
            mem_row_values.clear();
            self.abandon_exact_memdb_row_mirror();
        }
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_MEMDB_APPLY_TIME_NS,
            memdb_apply_start,
        );
        // IMPL-9a: keep the per-table QuotientFilter current so a later
        // DELETE/UPDATE of this just-inserted rowid cannot be falsely
        // short-circuited as "absent". No-op if no filter entry exists
        // for this root page yet (it will be seeded from the live B-tree
        // at first consultation, which already reflects the insert).
        self.qf_record_insert(direct.root_page, rowid);
        rowid
    }

    #[inline]
    fn try_append_prepared_direct_insert_active_page_run(
        &self,
        direct: &PreparedDirectSimpleInsert,
        rowid: i64,
        record_bytes: &[u8],
    ) -> bool {
        if !self.pending_direct_insert_page_run_active.get() {
            return false;
        }
        let mut pending = self.pending_direct_insert_page_run.borrow_mut();
        let Some(run) = pending.as_mut() else {
            return false;
        };
        if run.root_page != direct.root_page
            || run.cursor_page_size != direct.cursor_page_size
            || run.cursor_reserved_per_page != direct.cursor_reserved_per_page
            || rowid <= run.last_rowid
            || !run.records.accepts_record(record_bytes)
        {
            return false;
        }
        Self::push_pending_direct_insert_page_run_record(run, rowid, record_bytes);
        run.last_rowid = rowid;
        true
    }

    #[inline]
    fn push_pending_direct_insert_page_run_record(
        run: &mut PendingDirectInsertPageRun,
        rowid: i64,
        record_bytes: &[u8],
    ) {
        match &mut run.records {
            PendingDirectInsertPageRunRecords::Owned(records) => {
                records.push((rowid, record_bytes.to_vec()));
            }
            PendingDirectInsertPageRunRecords::Arena {
                records,
                record_bytes: arena,
            } => {
                let start = arena.len();
                arena.extend_from_slice(record_bytes);
                records.push((rowid, start..arena.len()));
            }
            PendingDirectInsertPageRunRecords::Repeated { rowids, record } => {
                debug_assert_eq!(record.as_slice(), record_bytes);
                rowids.push(rowid);
            }
        }
    }

    #[inline]
    fn can_buffer_prepared_direct_insert_page_run_record(
        can_use_prebuilt_constant_record: bool,
        record_bytes: &[u8],
    ) -> bool {
        record_bytes.len() >= PREPARED_DIRECT_INSERT_PAGE_RUN_MIN_RECORD_BYTES
            || can_use_prebuilt_constant_record
    }

    fn execute_prepared_direct_simple_insert(
        &self,
        execution_cx: &Cx,
        table_name: &str,
        direct: &PreparedDirectSimpleInsert,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<i64>> {
        let _lookaside_growth = StatementLookasideGrowthGuard::new(self);
        let profile_enabled = hot_path_profile_enabled();
        if profile_enabled {
            FSQLITE_PREPARED_DIRECT_INSERT_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        self.flush_pending_direct_update_leaf_patch_run(execution_cx)?;
        self.flush_pending_direct_delete_leaf_run(execution_cx)?;
        let direct_insert_requires_fk_check =
            self.fk_enforcement_enabled() && self.table_has_outbound_foreign_keys(table_name);
        let track_memdb_delta = self.should_track_prepared_direct_insert_memdb_delta();
        let defer_memdb_upsert =
            track_memdb_delta && self.in_transaction.get() && !self.pager.is_memory();
        // #111: FK-checked inserts must keep the MemDatabase row mirror EXACT
        // (apply each landed row's delta) rather than abandoning it. The
        // post-insert FK existence SELECT reads the parent table through the
        // memdb on `:memory:`; abandoning the mirror would mark
        // `memdb_requires_active_txn_reload` and force `fk_validation_query`
        // to re-hydrate every user table (including the growing child) on the
        // next insert — O(rows-so-far) per insert, i.e. the O(N^2) regression.
        // Applying the delta keeps the mirror current and exact so the FK
        // SELECT finds the parent without a reload. FK inserts already pay for
        // that SELECT, so the marginal cost of one `upsert_row` is negligible.
        let defer_lazy_memdb_materialization = track_memdb_delta
            && !defer_memdb_upsert
            && !direct_insert_requires_fk_check
            && (self.pager.is_memory()
                || (self.retained_autocommit_batch_active()
                    && self.retained_autocommit_stmt_count.get()
                        < self.adaptive_flush_threshold()));
        let can_use_prebuilt_constant_record = direct.prebuilt_constant_record.is_some()
            && (!track_memdb_delta || defer_lazy_memdb_materialization);
        let can_use_prebuilt_constant_record =
            can_use_prebuilt_constant_record && !direct_insert_requires_fk_check;
        // Direct INSERT is driven by pager/B-tree state. Only pay the MemDatabase
        // placeholder lookup on stale/reload boundaries; the common explicit-txn
        // hot path already has the table image resident.
        if track_memdb_delta && !self.memdb_rows_loaded.get() {
            self.ensure_memdb_table_placeholder(direct.root_page, direct.columns.len());
        }

        let empty_row: &[SqliteValue] = &[];
        let empty_col_map: &[(String, String, bool)] = &[];
        let mut explicit_rowid = None;
        let mut mem_row_values = self.prepared_direct_insert_row_scratch.borrow_mut();
        let mut preserialized_record_scratch: Option<std::cell::RefMut<'_, Vec<u8>>> = None;
        let row_build_start = profile_enabled.then(Instant::now);
        if can_use_prebuilt_constant_record {
            mem_row_values.clear();
            explicit_rowid =
                self.eval_prepared_direct_simple_insert_explicit_rowid_only(direct, params)?;
        } else {
            mem_row_values.clear();
            let retained_autocommit_direct_batch = self.retained_autocommit_batch_active()
                && self.retained_autocommit_stmt_count.get() < self.adaptive_flush_threshold();
            let can_try_preserialized_record = self.pager.is_memory()
                && (self.in_transaction.get() || retained_autocommit_direct_batch)
                && (!track_memdb_delta || defer_lazy_memdb_materialization)
                && !direct_insert_requires_fk_check
                && !matches!(
                    direct.or_conflict,
                    Some(fsqlite_ast::ConflictAction::Replace)
                )
                && self.retained_autocommit_count_sum_cache.borrow().is_none();
            if can_try_preserialized_record {
                let maybe_record_scratch = {
                    let mut record_scratch =
                        self.prepared_direct_insert_record_scratch.borrow_mut();
                    let mut text_scratch = self.prepared_direct_insert_text_scratch.borrow_mut();
                    let preserialize_start = profile_enabled.then(Instant::now);
                    let preserialize_result =
                        Self::try_serialize_prepared_direct_simple_insert_record(
                            table_name,
                            direct,
                            params,
                            &mut record_scratch,
                            &mut text_scratch,
                            profile_enabled,
                        );
                    record_hot_path_duration(
                        &FSQLITE_PREPARED_DIRECT_INSERT_PRESERIALIZE_TIME_NS,
                        preserialize_start,
                    );
                    match preserialize_result? {
                        PreparedDirectInsertRecordBuild::Serialized {
                            explicit_rowid: rowid,
                        } => {
                            explicit_rowid = rowid;
                            Some(record_scratch)
                        }
                        PreparedDirectInsertRecordBuild::Fallback => None,
                    }
                };
                preserialized_record_scratch = maybe_record_scratch;
            }
            if preserialized_record_scratch.is_none() {
                let row_value_build_start = profile_enabled.then(Instant::now);
                if mem_row_values.capacity() < direct.columns.len() {
                    let additional_capacity = direct.columns.len() - mem_row_values.capacity();
                    mem_row_values.reserve(additional_capacity);
                }
                if let Some(compiled_row_values) = direct.compiled_row_values.as_ref() {
                    let mut concat_text_scratch =
                        self.prepared_direct_insert_text_scratch.borrow_mut();
                    if compiled_row_values.len() != direct.columns.len() {
                        return Err(FrankenError::internal(format!(
                            "prepared direct insert compiled row width {} does not match table width {}",
                            compiled_row_values.len(),
                            direct.columns.len()
                        )));
                    }
                    for (col_idx, (column, expr)) in direct
                        .columns
                        .iter()
                        .zip(compiled_row_values.iter())
                        .enumerate()
                    {
                        let raw_value = Self::eval_prepared_direct_simple_insert_expr(
                            expr,
                            params,
                            Some(&mut concat_text_scratch),
                        )?;
                        Self::push_prepared_direct_simple_insert_value(
                            table_name,
                            direct,
                            col_idx,
                            column,
                            raw_value,
                            &mut explicit_rowid,
                            &mut mem_row_values,
                        )?;
                    }
                } else {
                    if direct.row_values.len() != direct.columns.len() {
                        return Err(FrankenError::internal(format!(
                            "prepared direct insert row width {} does not match table width {}",
                            direct.row_values.len(),
                            direct.columns.len()
                        )));
                    }
                    for (col_idx, (column, expr)) in direct
                        .columns
                        .iter()
                        .zip(direct.row_values.iter())
                        .enumerate()
                    {
                        let raw_value =
                            self.eval_expr_with_subqueries(expr, empty_row, empty_col_map, params)?;
                        Self::push_prepared_direct_simple_insert_value(
                            table_name,
                            direct,
                            col_idx,
                            column,
                            raw_value,
                            &mut explicit_rowid,
                            &mut mem_row_values,
                        )?;
                    }
                }
                record_hot_path_duration(
                    &FSQLITE_PREPARED_DIRECT_INSERT_ROW_VALUE_BUILD_TIME_NS,
                    row_value_build_start,
                );
            }
        }
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_ROW_BUILD_TIME_NS,
            row_build_start,
        );
        // #111: capture the FK row image BEFORE the storage insert. FK
        // enforcement on the direct lane must run AFTER the row physically
        // lands (gated on a row actually landing), to match SQLite's
        // PK-before-FK ordering: a dup-PK conflict (ABORT/FAIL/ROLLBACK) must
        // win over FK, and OR IGNORE must drop the conflicting row WITHOUT
        // raising FK. The storage insert below detects the PK conflict and
        // resolves the conflict clause; a row that survives returns
        // `Ok(Some(rowid))`. We then FK-check the surviving row. The statement
        // savepoint (kept for FK tables, see
        // `prepared_insert_can_skip_statement_savepoint_in_explicit_txn`)
        // rolls back the just-inserted row AND its applied memdb delta on an
        // FK Err. Cloning here is required because
        // `finish_prepared_direct_simple_insert_after_storage` may take/clear
        // `mem_row_values` (exact-apply / deferred-upsert branches). The clone
        // is O(columns) and only paid on FK-checked tables.
        let fk_check_row_values: Option<Vec<SqliteValue>> =
            direct_insert_requires_fk_check.then(|| mem_row_values.to_vec());

        let can_defer_page_run = self.pager.is_memory()
            && self.in_transaction.get()
            && explicit_rowid.is_some()
            && (!track_memdb_delta || defer_lazy_memdb_materialization)
            && !direct_insert_requires_fk_check
            && !matches!(
                direct.or_conflict,
                Some(fsqlite_ast::ConflictAction::Replace)
            )
            && self.retained_autocommit_count_sum_cache.borrow().is_none();
        if self.pending_direct_insert_page_run_requires_flush_before_insert(
            direct,
            explicit_rowid,
            can_defer_page_run,
        ) {
            self.flush_pending_direct_insert_page_run(execution_cx)?;
        }

        let preserialized_record = preserialized_record_scratch
            .as_ref()
            .map(|record| record.as_slice());
        let prebuilt_constant_record = if can_use_prebuilt_constant_record {
            Some(direct.prebuilt_constant_record.as_deref().ok_or_else(|| {
                FrankenError::internal(
                    "prepared direct insert constant-record fast path lost cached payload",
                )
            })?)
        } else {
            None
        };
        let active_page_run_record = preserialized_record
            .filter(|record| record.len() >= PREPARED_DIRECT_INSERT_PAGE_RUN_MIN_RECORD_BYTES)
            .or(prebuilt_constant_record);
        if can_defer_page_run
            && self.pending_direct_insert_page_run_active.get()
            && let Some(rowid) = explicit_rowid
            && let Some(record_bytes) = active_page_run_record
        {
            let btree_insert_start = profile_enabled.then(Instant::now);
            if self.try_append_prepared_direct_insert_active_page_run(direct, rowid, record_bytes) {
                self.clear_prepared_direct_insert_append_hint();
                record_hot_path_duration(
                    &FSQLITE_PREPARED_DIRECT_INSERT_BTREE_INSERT_TIME_NS,
                    btree_insert_start,
                );
                let conflict_action = direct
                    .or_conflict
                    .unwrap_or(fsqlite_ast::ConflictAction::Abort);
                return Ok(Some(
                    self.finish_prepared_direct_simple_insert_after_storage(
                        direct,
                        rowid,
                        conflict_action,
                        &mut mem_row_values,
                        track_memdb_delta,
                        defer_memdb_upsert,
                        defer_lazy_memdb_materialization,
                        can_use_prebuilt_constant_record,
                        preserialized_record.is_some(),
                        profile_enabled,
                    ),
                ));
            }
        }
        let root = page_number_from_schema_root(direct.root_page, table_name, "table")?;
        let mut prepared_append_hint =
            self.take_prepared_direct_insert_append_hint_for_root(direct.root_page);
        let memdb_next_rowid_hint = self.prepared_direct_insert_memdb_next_rowid_hint(
            direct.root_page,
            prepared_append_hint.is_none(),
        );
        let concurrent_ctx = self.concurrent_page_io_context()?;
        let result = if let Some(concurrent_ctx) = concurrent_ctx {
            let txn = self.active_txn.borrow_mut().take().ok_or_else(|| {
                FrankenError::internal("prepared direct insert missing active transaction")
            })?;
            let page_io = SharedTxnPageIo::with_concurrent(
                txn,
                concurrent_ctx.session_id,
                concurrent_ctx.handle,
                concurrent_ctx.lock_table,
                concurrent_ctx.commit_index,
                concurrent_ctx.busy_timeout_ms,
            );
            let result = {
                let cursor_setup_start = profile_enabled.then(Instant::now);
                let (usable_size, page_size) = Self::btree_cursor_sizes_from_header(
                    direct.cursor_page_size,
                    direct.cursor_reserved_per_page,
                );
                let mut cursor =
                    fsqlite_btree::BtCursor::new(page_io.clone(), root, usable_size, true);
                Self::configure_btree_cursor_page_size(&mut cursor, usable_size, page_size);
                let mut cell_scratch = self.prepared_direct_insert_cell_scratch.borrow_mut();
                cursor.swap_cell_scratch(&mut cell_scratch);
                let result = self.execute_prepared_direct_simple_insert_with_cursor(
                    execution_cx,
                    direct,
                    explicit_rowid,
                    &mut prepared_append_hint,
                    memdb_next_rowid_hint,
                    &mut mem_row_values,
                    track_memdb_delta,
                    defer_memdb_upsert,
                    defer_lazy_memdb_materialization,
                    can_use_prebuilt_constant_record,
                    can_defer_page_run,
                    preserialized_record,
                    profile_enabled,
                    cursor_setup_start,
                    &mut cursor,
                );
                cursor.swap_cell_scratch(&mut cell_scratch);
                result
            };
            let txn_back = page_io.into_inner()?;
            *self.active_txn.borrow_mut() = Some(txn_back);
            result
        } else {
            let mut active_txn = self.active_txn.borrow_mut();
            let txn = active_txn.as_mut().ok_or_else(|| {
                FrankenError::internal("prepared direct insert missing active transaction")
            })?;
            let cursor_setup_start = profile_enabled.then(Instant::now);
            let mut cursor = Self::new_header_btree_cursor(
                txn,
                root,
                direct.cursor_page_size,
                direct.cursor_reserved_per_page,
                true,
            );
            let mut cell_scratch = self.prepared_direct_insert_cell_scratch.borrow_mut();
            cursor.swap_cell_scratch(&mut cell_scratch);
            let result = self.execute_prepared_direct_simple_insert_with_cursor(
                execution_cx,
                direct,
                explicit_rowid,
                &mut prepared_append_hint,
                memdb_next_rowid_hint,
                &mut mem_row_values,
                track_memdb_delta,
                defer_memdb_upsert,
                defer_lazy_memdb_materialization,
                can_use_prebuilt_constant_record,
                can_defer_page_run,
                preserialized_record,
                profile_enabled,
                cursor_setup_start,
                &mut cursor,
            );
            cursor.swap_cell_scratch(&mut cell_scratch);
            result
        };
        if matches!(result.as_ref(), Ok(Some(_))) {
            self.discard_cached_vdbe_engine();
            self.sync_memory_concurrent_pending_write_pages(direct.root_page)?;
        }
        // #111: POST-insert FK enforcement. Only fires when a row actually
        // landed (`Ok(Some(rowid))`) — never for an OR IGNORE drop
        // (`Ok(None)`) or a PK conflict (`Err`), matching SQLite's
        // FK-after-PK / OR-IGNORE-drops-FK semantics. The row + its memdb
        // delta are already applied; on FK violation the surrounding statement
        // savepoint rolls both back. The just-inserted (and earlier in-flight)
        // rows are visible to a self-referential FK because the exact mirror
        // was updated before this check.
        if let Some(mut fk_row_values) = fk_check_row_values
            && let Ok(Some(rowid)) = result.as_ref()
        {
            // For an implicit (auto-assigned) rowid whose IPK column is itself
            // an FK child column, the captured clone holds NULL; patch in the
            // actual assigned rowid so the FK existence check sees the true
            // value. Explicit rowids already carry their value in the clone.
            if let Some(ipk_idx) = direct.rowid_alias_col_idx
                && fk_row_values.get(ipk_idx).is_some_and(SqliteValue::is_null)
            {
                fk_row_values[ipk_idx] = SqliteValue::Integer(*rowid);
            }
            self.check_fk_parent_exists(table_name, &fk_row_values)?;
        }
        result
    }

    /// Execute an eligible direct-simple UPDATE without dispatching to VDBE.
    ///
    /// Returns `Ok(affected_rows)` on success. If the WHERE rowid does not
    /// exist, returns `Ok(0)` (matches VDBE / SQLite semantics).
    fn execute_prepared_direct_simple_update(
        &self,
        execution_cx: &Cx,
        direct: &PreparedDirectSimpleUpdate,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        let _lookaside_growth = StatementLookasideGrowthGuard::new(self);
        let _statement_scratch_reset = PreparedDirectInsertScratchResetGuard { conn: self };
        self.flush_pending_direct_delete_leaf_run(execution_cx)?;
        self.flush_pending_direct_insert_page_run(execution_cx)?;

        // Resolve target rowid. NULL / non-integer params produce a no-op
        // (rowid lookup cannot match).
        let rowid_value =
            Self::prepared_direct_simple_insert_param(params, direct.rowid_param_one_based)?;
        let Some(rowid) = Self::coerce_rowid_lookup_value(rowid_value) else {
            return Ok(0);
        };

        if let Some((affected, abandon_memdb)) = self
            .try_execute_prepared_direct_simple_update_active_leaf_patch_run(
                execution_cx,
                direct,
                params,
                rowid,
            )?
        {
            if abandon_memdb {
                self.clear_prepared_direct_insert_append_hint();
                self.abandon_exact_memdb_row_mirror();
            }
            if affected > 0 {
                self.sync_memory_concurrent_pending_write_pages(direct.root_page)?;
            }
            return Ok(affected);
        }

        // Dedicated Vec scratch so `parse_record_into` can reuse Text/Blob
        // backing storage across row iterations.
        let mut new_values = self.prepared_direct_update_row_scratch.borrow_mut();
        let mut payload_buf = self.prepared_direct_insert_cell_scratch.borrow_mut();
        payload_buf.clear();

        let root = page_number_from_schema_root(direct.root_page, "<direct-update>", "table")?;
        let concurrent_ctx = self.concurrent_page_io_context()?;
        let (affected, abandon_memdb) = if let Some(concurrent_ctx) = concurrent_ctx {
            let txn = self.active_txn.borrow_mut().take().ok_or_else(|| {
                FrankenError::internal("prepared direct update missing active transaction")
            })?;
            let page_io = SharedTxnPageIo::with_concurrent(
                txn,
                concurrent_ctx.session_id,
                concurrent_ctx.handle,
                concurrent_ctx.lock_table,
                concurrent_ctx.commit_index,
                concurrent_ctx.busy_timeout_ms,
            );
            let result = {
                let (usable_size, page_size) = Self::btree_cursor_sizes_from_header(
                    direct.cursor_page_size,
                    direct.cursor_reserved_per_page,
                );
                let mut cursor =
                    fsqlite_btree::BtCursor::new(page_io.clone(), root, usable_size, true);
                Self::configure_btree_cursor_page_size(&mut cursor, usable_size, page_size);
                self.execute_prepared_direct_simple_update_with_cursor(
                    execution_cx,
                    direct,
                    params,
                    rowid,
                    &mut new_values,
                    &mut payload_buf,
                    &mut cursor,
                )
            };
            let txn_back = page_io.into_inner()?;
            *self.active_txn.borrow_mut() = Some(txn_back);
            result?
        } else {
            let mut active_txn = self.active_txn.borrow_mut();
            let txn = active_txn.as_mut().ok_or_else(|| {
                FrankenError::internal("prepared direct update missing active transaction")
            })?;
            let mut cursor = Self::new_header_btree_cursor(
                txn,
                root,
                direct.cursor_page_size,
                direct.cursor_reserved_per_page,
                true,
            );
            self.execute_prepared_direct_simple_update_with_cursor(
                execution_cx,
                direct,
                params,
                rowid,
                &mut new_values,
                &mut payload_buf,
                &mut cursor,
            )?
        };

        // The direct path mutates the btree without touching the MemDatabase
        // row mirror. Invalidate so the next read boundary reloads it.
        if abandon_memdb {
            drop(new_values);
            drop(payload_buf);
            self.clear_prepared_direct_insert_append_hint();
            self.abandon_exact_memdb_row_mirror();
        }
        if affected > 0 {
            self.discard_cached_vdbe_engine();
            self.sync_memory_concurrent_pending_write_pages(direct.root_page)?;
        }
        Ok(affected)
    }

    fn execute_prepared_direct_simple_update_with_cursor<P: PageReader + PageWriter>(
        &self,
        execution_cx: &Cx,
        direct: &PreparedDirectSimpleUpdate,
        params: Option<&[SqliteValue]>,
        rowid: i64,
        new_values: &mut Vec<SqliteValue>,
        payload_buf: &mut Vec<u8>,
        cursor: &mut fsqlite_btree::BtCursor<P>,
    ) -> Result<(usize, bool)> {
        // IMPL-9a: absent-rowid short-circuit BEFORE the B-tree descent.
        // `qf_maybe_short_circuit_for_rowid` is safe: it only returns
        // true when the per-table filter is built AND reflects the
        // committed B-tree state (or is confirmed current via our own
        // direct-simple INSERT/DELETE maintenance). In every other case
        // it returns false and we proceed with the normal descent.
        if self.qf_maybe_short_circuit_for_rowid(execution_cx, direct.root_page, rowid, cursor)? {
            return Ok((0, false));
        }
        let seek = cursor.table_move_to(execution_cx, rowid)?;
        if !seek.is_found() {
            return Ok((0, false));
        }

        self.maybe_seed_retained_autocommit_count_sum_cache_from_clean_memdb(direct.root_page);
        let cache_tracks_root =
            self.retained_autocommit_count_sum_cache_tracks_root(direct.root_page);
        let can_skip_old_payload_decode = !cache_tracks_root && direct.assigns_all_non_ipk_columns;
        if !cache_tracks_root
            && let Some(outcome) = self.try_execute_prepared_direct_simple_update_fixed_width_real(
                execution_cx,
                direct,
                params,
                rowid,
                payload_buf,
                cursor,
            )?
        {
            return Ok(outcome);
        }
        let old_cached_sum_value = if can_skip_old_payload_decode {
            new_values.clear();
            new_values.resize(direct.columns.len(), SqliteValue::Null);
            None
        } else {
            cursor.payload_into(execution_cx, payload_buf)?;

            // Decode the on-disk record into the scratch values. IPK columns are
            // stored as NULL in the payload (key is the rowid); we patch them
            // below when reserializing to keep the record shape identical.
            parse_record_into(payload_buf, new_values).ok_or_else(|| {
                FrankenError::DatabaseCorrupt {
                    detail: "prepared direct update: failed to parse existing row payload"
                        .to_owned(),
                }
            })?;
            // `parse_record_into` truncates to the decoded column count; pad/trim
            // back to the schema width so IPK / missing columns are explicit.
            while new_values.len() < direct.columns.len() {
                new_values.push(SqliteValue::Null);
            }
            new_values.truncate(direct.columns.len());
            if cache_tracks_root {
                self.retained_autocommit_count_sum_cache_project_value(
                    direct.root_page,
                    rowid,
                    new_values.as_slice(),
                )
            } else {
                None
            }
        };

        // Apply each SET assignment with column-affinity coercion and NOT NULL
        // validation. IPK columns cannot appear here (gate rejects).
        for (col_idx, set_value) in &direct.assignments {
            new_values[*col_idx] = Self::prepared_direct_simple_update_assignment_value(
                direct, params, *col_idx, set_value,
            )?;
        }
        let new_cached_sum_value = if cache_tracks_root {
            self.retained_autocommit_count_sum_cache_project_value(
                direct.root_page,
                rowid,
                new_values.as_slice(),
            )
        } else {
            None
        };

        // Re-NULL out IPK storage slots so the serialized record matches the
        // insert path (value comes from the btree key).
        for (col_idx, column) in direct.columns.iter().enumerate() {
            if column.is_ipk {
                new_values[col_idx] = SqliteValue::Null;
            }
        }

        // Serialize new record into a scratch buffer and replace the row
        // in place: delete at the current cursor position, insert at the
        // same rowid.
        let mut record_scratch = self.prepared_direct_insert_record_scratch.borrow_mut();
        record_scratch.clear();
        serialize_record_iter_into(new_values.iter(), &mut record_scratch);
        if !cursor.table_overwrite_current_payload_same_size_no_overflow(
            execution_cx,
            rowid,
            record_scratch.as_slice(),
        )? {
            cursor.delete(execution_cx)?;
            // `delete()` leaves the cursor at the deleted row's successor (or EOF).
            // The rowid is now known absent, so reuse that position instead of
            // sending the replacement through the general table_insert path, which
            // would perform another root-to-leaf seek for the same rowid.
            cursor.table_insert_prechecked_absent(
                execution_cx,
                rowid,
                record_scratch.as_slice(),
            )?;
        }
        self.retained_autocommit_count_sum_cache_note_update(
            direct.root_page,
            old_cached_sum_value,
            new_cached_sum_value,
        );

        Ok((1, true))
    }

    fn prepared_direct_simple_update_assignment_value(
        direct: &PreparedDirectSimpleUpdate,
        params: Option<&[SqliteValue]>,
        col_idx: usize,
        set_value: &PreparedDirectSimpleSetValue,
    ) -> Result<SqliteValue> {
        let column = &direct.columns[col_idx];
        let raw_value = match set_value {
            PreparedDirectSimpleSetValue::Literal(v) => v.clone(),
            PreparedDirectSimpleSetValue::Placeholder(one_based) => {
                Self::prepared_direct_simple_insert_param(params, *one_based)?.clone()
            }
        };
        if column.notnull && raw_value.is_null() {
            return Err(FrankenError::NotNullViolation {
                column: column.name.clone(),
            });
        }
        Ok(raw_value.apply_affinity(Self::type_affinity_for_direct_insert(column.affinity)))
    }

    fn try_execute_prepared_direct_simple_update_fixed_width_real<P: PageReader + PageWriter>(
        &self,
        execution_cx: &Cx,
        direct: &PreparedDirectSimpleUpdate,
        params: Option<&[SqliteValue]>,
        rowid: i64,
        payload_buf: &mut Vec<u8>,
        cursor: &mut fsqlite_btree::BtCursor<P>,
    ) -> Result<Option<(usize, bool)>> {
        let Some(patch) = direct.fixed_width_real_assignment else {
            return Ok(None);
        };
        let Some((col_idx, set_value)) = direct.assignments.first() else {
            return Ok(None);
        };
        if *col_idx != patch.column_index {
            return Ok(None);
        }
        let SqliteValue::Float(next_value) = Self::prepared_direct_simple_update_assignment_value(
            direct,
            params,
            patch.column_index,
            set_value,
        )?
        else {
            return Ok(None);
        };
        if next_value.is_nan() {
            return Ok(None);
        }

        if self.can_defer_prepared_direct_update_leaf_patch_run() {
            let profile_update_leaf_patch_run = hot_path_profile_enabled();
            if profile_update_leaf_patch_run {
                FSQLITE_PREPARED_DIRECT_UPDATE_LEAF_PATCH_RUN_START_ATTEMPTS
                    .fetch_add(1, AtomicOrdering::Relaxed);
            }
            let update_leaf_patch_start = profile_update_leaf_patch_run.then(Instant::now);
            let start_result = (|| -> Result<Option<TableLeafPayloadPatchRun>> {
                let Some(mut run) = cursor.table_leaf_payload_patch_run_current(rowid)? else {
                    return Ok(None);
                };
                let (usable_size, _) = Self::btree_cursor_sizes_from_header(
                    direct.cursor_page_size,
                    direct.cursor_reserved_per_page,
                );
                if run.patch_fixed_width_real(
                    execution_cx,
                    rowid,
                    patch.column_index,
                    direct.columns.len(),
                    next_value,
                    usable_size,
                )? {
                    Ok(Some(run))
                } else {
                    Ok(None)
                }
            })();
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_UPDATE_LEAF_PATCH_RUN_START_TIME_NS,
                update_leaf_patch_start,
            );
            if let Some(run) = start_result? {
                if profile_update_leaf_patch_run {
                    FSQLITE_PREPARED_DIRECT_UPDATE_LEAF_PATCH_RUN_START_HITS
                        .fetch_add(1, AtomicOrdering::Relaxed);
                }
                self.store_pending_direct_update_leaf_patch_run(direct, patch.column_index, run);
                self.retained_autocommit_count_sum_cache_note_update(direct.root_page, None, None);
                return Ok(Some((1, true)));
            }
        }

        cursor.payload_into(execution_cx, payload_buf)?;
        let projected =
            parse_record_projected_column_offsets(payload_buf, patch.column_index, None)
                .ok_or_else(|| FrankenError::DatabaseCorrupt {
                    detail: "prepared direct fixed-width REAL update: failed to parse row payload"
                        .to_owned(),
                })?;
        if projected.column_count != direct.columns.len() {
            return Ok(None);
        }
        let Some(column_offset) = projected.primary else {
            return Ok(None);
        };
        if column_offset.serial_type != 7 || column_offset.value_len != 8 {
            return Ok(None);
        }

        let start = usize::try_from(column_offset.body_offset).map_err(|_| {
            FrankenError::DatabaseCorrupt {
                detail:
                    "prepared direct fixed-width REAL update: column offset exceeds addressable size"
                        .to_owned(),
            }
        })?;
        let end = start
            .checked_add(8)
            .filter(|end| *end <= payload_buf.len())
            .ok_or_else(|| FrankenError::DatabaseCorrupt {
                detail:
                    "prepared direct fixed-width REAL update: column payload exceeds record size"
                        .to_owned(),
            })?;
        payload_buf[start..end].copy_from_slice(&next_value.to_bits().to_be_bytes());

        if !cursor.table_overwrite_current_payload_same_size_no_overflow(
            execution_cx,
            rowid,
            payload_buf.as_slice(),
        )? {
            cursor.delete(execution_cx)?;
            cursor.table_insert_prechecked_absent(execution_cx, rowid, payload_buf.as_slice())?;
        }

        self.retained_autocommit_count_sum_cache_note_update(direct.root_page, None, None);
        Ok(Some((1, true)))
    }

    /// Execute an eligible direct-simple DELETE without dispatching to VDBE.
    fn execute_prepared_direct_simple_delete(
        &self,
        execution_cx: &Cx,
        direct: &PreparedDirectSimpleDelete,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        let _lookaside_growth = StatementLookasideGrowthGuard::new(self);
        let profile_direct_delete = hot_path_profile_enabled();
        let preflush_start = profile_direct_delete.then(Instant::now);
        let preflush_result = (|| -> Result<()> {
            self.flush_pending_direct_update_leaf_patch_run(execution_cx)?;
            self.flush_pending_direct_insert_page_run(execution_cx)
        })();
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_DELETE_PREFLUSH_TIME_NS,
            preflush_start,
        );
        preflush_result?;

        let rowid_lookup_start = profile_direct_delete.then(Instant::now);
        let rowid_result = (|| -> Result<Option<i64>> {
            let rowid_value =
                Self::prepared_direct_simple_insert_param(params, direct.rowid_param_one_based)?;
            Ok(Self::coerce_rowid_lookup_value(rowid_value))
        })();
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_DELETE_ROWID_LOOKUP_TIME_NS,
            rowid_lookup_start,
        );
        let Some(rowid) = rowid_result? else {
            return Ok(0);
        };

        let active_leaf_result = self.try_execute_prepared_direct_simple_delete_active_leaf_run(
            execution_cx,
            direct,
            rowid,
        );
        if let Some((affected, abandon_memdb)) = active_leaf_result? {
            return self.finish_prepared_direct_simple_delete(direct, affected, abandon_memdb);
        }

        let root = page_number_from_schema_root(direct.root_page, "<direct-delete>", "table")?;
        let concurrent_ctx = self.concurrent_page_io_context()?;
        let (affected, abandon_memdb) = if let Some(concurrent_ctx) = concurrent_ctx {
            let cursor_setup_start = profile_direct_delete.then(Instant::now);
            let txn = self.active_txn.borrow_mut().take().ok_or_else(|| {
                FrankenError::internal("prepared direct delete missing active transaction")
            })?;
            let page_io = SharedTxnPageIo::with_concurrent(
                txn,
                concurrent_ctx.session_id,
                concurrent_ctx.handle,
                concurrent_ctx.lock_table,
                concurrent_ctx.commit_index,
                concurrent_ctx.busy_timeout_ms,
            );
            let result = {
                let (usable_size, page_size) = Self::btree_cursor_sizes_from_header(
                    direct.cursor_page_size,
                    direct.cursor_reserved_per_page,
                );
                let mut cursor =
                    fsqlite_btree::BtCursor::new(page_io.clone(), root, usable_size, true);
                Self::configure_btree_cursor_page_size(&mut cursor, usable_size, page_size);
                record_hot_path_duration(
                    &FSQLITE_PREPARED_DIRECT_DELETE_CURSOR_SETUP_TIME_NS,
                    cursor_setup_start,
                );
                self.execute_prepared_direct_simple_delete_with_cursor(
                    execution_cx,
                    direct,
                    rowid,
                    &mut cursor,
                )
            };
            let txn_back = page_io.into_inner()?;
            *self.active_txn.borrow_mut() = Some(txn_back);
            result?
        } else {
            let cursor_setup_start = profile_direct_delete.then(Instant::now);
            let mut active_txn = self.active_txn.borrow_mut();
            let txn = active_txn.as_mut().ok_or_else(|| {
                FrankenError::internal("prepared direct delete missing active transaction")
            })?;
            let mut cursor = Self::new_header_btree_cursor(
                txn,
                root,
                direct.cursor_page_size,
                direct.cursor_reserved_per_page,
                true,
            );
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_DELETE_CURSOR_SETUP_TIME_NS,
                cursor_setup_start,
            );
            // Inline a scope so the `active_txn` mutable borrow is not
            // held across a `self.` call that may re-borrow Connection
            // state (the QF consultation + maintenance take interior
            // `RefCell`s; none touch `active_txn`).
            self.execute_prepared_direct_simple_delete_with_cursor(
                execution_cx,
                direct,
                rowid,
                &mut cursor,
            )?
        };

        self.finish_prepared_direct_simple_delete(direct, affected, abandon_memdb)
    }

    fn finish_prepared_direct_simple_delete(
        &self,
        direct: &PreparedDirectSimpleDelete,
        affected: usize,
        abandon_memdb: bool,
    ) -> Result<usize> {
        let profile_direct_delete = hot_path_profile_enabled();
        if abandon_memdb {
            if profile_direct_delete {
                FSQLITE_PREPARED_DIRECT_DELETE_MEMDB_ABANDON_CALLS
                    .fetch_add(1, AtomicOrdering::Relaxed);
            }
            let abandon_start = profile_direct_delete.then(Instant::now);
            self.clear_prepared_direct_insert_append_hint();
            self.abandon_exact_memdb_row_mirror();
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_DELETE_MEMDB_ABANDON_TIME_NS,
                abandon_start,
            );
        }
        if affected > 0 {
            self.discard_cached_vdbe_engine();
            if profile_direct_delete {
                FSQLITE_PREPARED_DIRECT_DELETE_MEMORY_SYNC_CALLS
                    .fetch_add(1, AtomicOrdering::Relaxed);
            }
            let sync_start = profile_direct_delete.then(Instant::now);
            let sync_result = self.sync_memory_concurrent_pending_write_pages(direct.root_page);
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_DELETE_MEMORY_SYNC_TIME_NS,
                sync_start,
            );
            sync_result?;
        }
        Ok(affected)
    }

    fn execute_prepared_direct_simple_delete_with_cursor<P: PageReader + PageWriter>(
        &self,
        execution_cx: &Cx,
        direct: &PreparedDirectSimpleDelete,
        rowid: i64,
        cursor: &mut fsqlite_btree::BtCursor<P>,
    ) -> Result<(usize, bool)> {
        let profile_direct_delete = hot_path_profile_enabled();
        let root_page = direct.root_page;
        // IMPL-9a: absent-rowid short-circuit BEFORE the B-tree descent.
        // See `execute_prepared_direct_simple_update_with_cursor` for
        // safety argument (filter is consulted only when built and
        // coherent with the committed state).
        let qf_start = profile_direct_delete.then(Instant::now);
        let qf_result =
            self.qf_maybe_short_circuit_for_rowid(execution_cx, root_page, rowid, cursor);
        record_hot_path_duration(&FSQLITE_PREPARED_DIRECT_DELETE_QF_TIME_NS, qf_start);
        if qf_result? {
            return Ok((0, false));
        }
        let seek_start = profile_direct_delete.then(Instant::now);
        let seek_result = cursor.table_move_to(execution_cx, rowid);
        record_hot_path_duration(&FSQLITE_PREPARED_DIRECT_DELETE_SEEK_TIME_NS, seek_start);
        let seek = seek_result?;
        if !seek.is_found() {
            return Ok((0, false));
        }

        if self.can_defer_prepared_direct_delete_leaf_run() {
            let profile_delete_leaf_run = hot_path_profile_enabled();
            if profile_delete_leaf_run {
                FSQLITE_PREPARED_DIRECT_DELETE_LEAF_RUN_START_ATTEMPTS
                    .fetch_add(1, AtomicOrdering::Relaxed);
            }
            let delete_leaf_run_start = profile_delete_leaf_run.then(Instant::now);
            let delete_leaf_run_result = (|| -> Result<Option<TableLeafDeleteRun>> {
                let Some(mut run) = cursor.table_leaf_delete_run_current(rowid)? else {
                    return Ok(None);
                };
                let (usable_size, _) = Self::btree_cursor_sizes_from_header(
                    direct.cursor_page_size,
                    direct.cursor_reserved_per_page,
                );
                if run.delete_rowid(execution_cx, rowid, usable_size)? {
                    Ok(Some(run))
                } else {
                    Ok(None)
                }
            })();
            record_hot_path_duration(
                &FSQLITE_PREPARED_DIRECT_DELETE_LEAF_RUN_START_TIME_NS,
                delete_leaf_run_start,
            );
            if let Some(run) = delete_leaf_run_result? {
                if profile_delete_leaf_run {
                    FSQLITE_PREPARED_DIRECT_DELETE_LEAF_RUN_START_HITS
                        .fetch_add(1, AtomicOrdering::Relaxed);
                }
                self.store_pending_direct_delete_leaf_run(direct, run);
                self.qf_record_delete(root_page, rowid);
                self.retained_autocommit_count_sum_cache_note_delete(root_page, None);
                return Ok((1, true));
            }
        }

        self.maybe_seed_retained_autocommit_count_sum_cache_from_clean_memdb(root_page);
        let tracks_count_sum_cache =
            self.retained_autocommit_count_sum_cache_tracks_root(root_page);
        let old_cached_sum_value = if tracks_count_sum_cache {
            let _statement_scratch_reset = PreparedDirectInsertScratchResetGuard { conn: self };
            let mut payload_buf = self.prepared_direct_insert_cell_scratch.borrow_mut();
            payload_buf.clear();
            cursor.payload_into(execution_cx, &mut payload_buf)?;
            let mut old_values = self.prepared_direct_update_row_scratch.borrow_mut();
            old_values.clear();
            parse_record_into(&payload_buf, &mut old_values).ok_or_else(|| {
                FrankenError::DatabaseCorrupt {
                    detail: "prepared direct delete: failed to parse existing row payload"
                        .to_owned(),
                }
            })?;
            self.retained_autocommit_count_sum_cache_project_value(
                root_page,
                rowid,
                old_values.as_slice(),
            )
        } else {
            None
        };
        let physical_delete_start = profile_direct_delete.then(Instant::now);
        let delete_result = cursor.delete(execution_cx);
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_DELETE_PHYSICAL_DELETE_TIME_NS,
            physical_delete_start,
        );
        delete_result?;
        // IMPL-9a: maintenance — filter now learns the rowid is absent.
        self.qf_record_delete(root_page, rowid);
        self.retained_autocommit_count_sum_cache_note_delete(root_page, old_cached_sum_value);
        Ok((1, true))
    }

    // ---------------------------------------------------------------
    // IMPL-9a: QuotientFilter integration helpers.
    //
    // The filter short-circuits absent-rowid DELETE / UPDATE under the
    // direct-simple fast path so we don't pay a B-tree descent to
    // confirm "no such row". False-positives are tolerable (descent
    // confirms absent); false-negatives are FATAL (would under-delete).
    // We eliminate FNs by (a) only consulting once the filter is
    // fully seeded against the live B-tree, and (b) invalidating on
    // rollback so a filter that includes never-committed inserts can
    // never say "present" to the caller.
    //
    // Wiring status: dormant. The call sites still route through these helpers,
    // but the fast guard returns before touching the map unless a future
    // re-enablement explicitly creates entries and flips
    // `quotient_filters_may_have_entries`. This preserves the safe
    // maintenance/invalidation shape without reintroducing the rejected
    // build-on-first-consult full-table scan.
    //   - Consultation: `execute_prepared_direct_simple_{update,delete}
    //     _with_cursor` calls `qf_maybe_short_circuit_for_rowid` before
    //     the B-tree descent, but the dormant guard currently returns
    //     `false`.
    //   - INSERT/DELETE maintenance, rollback invalidation, and commit
    //     clearing are also guarded and no-op while the map has no entries.
    //   - DDL invalidation (`qf_invalidate_root`) is intentionally left
    //     unwired in this commit; the DROP TABLE / ALTER TABLE root-
    //     page plumbing is non-trivial and the filter can be safely
    //     (if wastefully) left behind — consultation only short-
    //     circuits for the OLD root page until the next seed attempt,
    //     and seeding runs against the live pager. Retained under
    //     `#[allow(dead_code)]` with the follow-up listed above.
    // ---------------------------------------------------------------

    /// Populate a freshly-constructed `QuotientFilter` by scanning
    /// every rowid in the table rooted at `cursor`. On success,
    /// returns `Ok(true)` with the entry marked `built`. If the scan
    /// exceeds `QUOTIENT_FILTER_BUILD_ROW_CAP`, returns `Ok(false)`
    /// and the entry is marked `too_large_to_build`. Clears any
    /// partial content before returning.
    #[allow(dead_code)] // build-on-first-consult disabled 4ea55010; retained for re-enablement
    fn quotient_filter_seed_from_cursor<P: PageReader + PageWriter>(
        entry: &mut QuotientFilterEntry,
        execution_cx: &Cx,
        cursor: &mut fsqlite_btree::BtCursor<P>,
    ) -> Result<bool> {
        entry.filter.clear();
        let has_any = cursor.first(execution_cx)?;
        if !has_any {
            // Empty table — filter is trivially seeded.
            entry.built = true;
            entry.too_large_to_build = false;
            return Ok(true);
        }
        let mut seen: usize = 0;
        loop {
            let rowid = cursor.rowid(execution_cx)?;
            // `insert` only fails past 4x capacity; at that point, the
            // FP rate has degraded past usefulness. Treat it like the
            // row-cap case: disable short-circuiting for this table.
            if entry
                .filter
                .insert(quotient_filter_hash_rowid(rowid))
                .is_err()
            {
                entry.filter.clear();
                entry.built = false;
                entry.too_large_to_build = true;
                return Ok(false);
            }
            seen = seen.saturating_add(1);
            if seen > QUOTIENT_FILTER_BUILD_ROW_CAP {
                entry.filter.clear();
                entry.built = false;
                entry.too_large_to_build = true;
                return Ok(false);
            }
            if !cursor.next(execution_cx)? {
                break;
            }
        }
        entry.built = true;
        entry.too_large_to_build = false;
        Ok(true)
    }

    /// Consult the per-table filter for an absent-rowid short-circuit
    /// opportunity. This is currently disabled because the old
    /// build-on-first-consult activation policy added a full-table scan to
    /// hot UPDATE/DELETE paths. Returns `Ok(true)` iff consultation proved the
    /// rowid is absent (caller may short-circuit with 0 rows affected).
    ///
    /// If the filter is unusable (too-large-to-build, or build
    /// failure), returns `Ok(false)` — safe default, caller descends
    /// the B-tree normally.
    ///
    /// Result and `&mut cursor` are preserved because
    /// `quotient_filter_seed_from_cursor` uses them on the re-enablement
    /// path; the current disabled state never returns Err and never
    /// mutates `cursor`.
    #[allow(clippy::unnecessary_wraps, clippy::needless_pass_by_ref_mut)]
    fn qf_maybe_short_circuit_for_rowid<P: PageReader + PageWriter>(
        &self,
        execution_cx: &Cx,
        root_page: i32,
        rowid: i64,
        cursor: &mut fsqlite_btree::BtCursor<P>,
    ) -> Result<bool> {
        if !self.quotient_filters_may_have_entries.get() {
            return Ok(false);
        }
        let mut filters = self.quotient_filters.borrow_mut();
        let Some(entry) = filters.get_mut(&root_page) else {
            // No filter entry yet. Building one requires a full-table
            // scan (O(rows)); for a typical workload that does
            // INSERT→DELETE/UPDATE within a single connection, the
            // INSERT path can maintain an already-existing filter entry. For a
            // fresh connection consulting DML on an existing table, the scan
            // would be strictly additive overhead with no offsetting
            // short-circuit benefit because the caller will descend the B-tree
            // anyway when the filter says "maybe".
            //
            // Decision (2026-04-20 BENCH-REGRESSION-TRIAGE): do NOT
            // build the filter on first consult. Consultation against an
            // absent entry returns `false` (no short-circuit). Future
            // re-enablement must create entries explicitly and flip
            // `quotient_filters_may_have_entries`.
            let _ = cursor;
            let _ = execution_cx;
            return Ok(false);
        };
        if entry.too_large_to_build || !entry.built {
            return Ok(false);
        }
        let hash = quotient_filter_hash_rowid(rowid);
        if entry.filter.contains(hash) {
            // "Maybe present" — caller must descend to confirm.
            Ok(false)
        } else {
            // "Definitely absent" — safe to short-circuit.
            self.quotient_filter_short_circuits
                .set(self.quotient_filter_short_circuits.get().saturating_add(1));
            Ok(true)
        }
    }

    /// Record a successful INSERT of `rowid` into the table rooted at
    /// `root_page`. No-op while the quotient-filter map is dormant. If a future
    /// re-enablement explicitly creates a built entry, this keeps it current so
    /// the next consultation sees the new row.
    fn qf_record_insert(&self, root_page: i32, rowid: i64) {
        if !self.quotient_filters_may_have_entries.get() {
            return;
        }
        let mut filters = self.quotient_filters.borrow_mut();
        if let Some(entry) = filters.get_mut(&root_page) {
            if entry.built {
                // Ignore Err(()): capacity exhaustion just means the
                // filter is no longer a reliable accelerator; the
                // next consultation will still descend the B-tree
                // normally if contains() answers "maybe".
                let _ = entry.filter.insert(quotient_filter_hash_rowid(rowid));
            }
            if self.in_transaction.get() {
                entry.modified_in_txn = true;
            }
        }
    }

    /// Record a successful DELETE of `rowid` from the table rooted at
    /// `root_page`. If the entry is built, removes the corresponding
    /// hash fingerprint; otherwise a no-op.
    fn qf_record_delete(&self, root_page: i32, rowid: i64) {
        if !self.quotient_filters_may_have_entries.get() {
            return;
        }
        let mut filters = self.quotient_filters.borrow_mut();
        if let Some(entry) = filters.get_mut(&root_page) {
            if entry.built {
                entry.filter.remove(quotient_filter_hash_rowid(rowid));
            }
            if self.in_transaction.get() {
                entry.modified_in_txn = true;
            }
        }
    }

    /// Invalidate all filters that were mutated during the current
    /// (about-to-be-rolled-back) transaction. Each such filter is
    /// reset to the unbuilt state.
    fn invalidate_qfs_on_rollback(&self) {
        if !self.quotient_filters_may_have_entries.get() {
            return;
        }
        let mut filters = self.quotient_filters.borrow_mut();
        for entry in filters.values_mut() {
            if entry.modified_in_txn {
                entry.filter.clear();
                entry.built = false;
                entry.too_large_to_build = false;
                entry.modified_in_txn = false;
            }
        }
    }

    /// Clear the per-transaction `modified_in_txn` flag on every
    /// filter. Called on successful COMMIT so subsequent rollbacks in
    /// later transactions do not wrongly invalidate filters whose
    /// writes were durably committed.
    fn clear_qf_txn_modifications(&self) {
        if !self.quotient_filters_may_have_entries.get() {
            return;
        }
        let mut filters = self.quotient_filters.borrow_mut();
        for entry in filters.values_mut() {
            entry.modified_in_txn = false;
        }
    }

    /// Drop the filter entry for a table whose root page is being
    /// freed (DROP TABLE) or whose schema is otherwise being
    /// invalidated (ALTER TABLE, schema reload). Subsequent lookups
    /// will re-seed from the live B-tree if the root is re-used.
    #[allow(dead_code)]
    fn qf_invalidate_root(&self, root_page: i32) {
        if !self.quotient_filters_may_have_entries.get() {
            return;
        }
        let mut filters = self.quotient_filters.borrow_mut();
        filters.remove(&root_page);
        if filters.is_empty() {
            self.quotient_filters_may_have_entries.set(false);
        }
    }

    /// Observability hook: number of times the QF has produced an
    /// absent-rowid short-circuit on this connection.
    #[cfg(test)]
    #[must_use]
    pub(crate) fn quotient_filter_short_circuit_count(&self) -> u64 {
        self.quotient_filter_short_circuits.get()
    }

    #[cfg(test)]
    pub(crate) fn reset_quotient_filter_short_circuit_count(&self) {
        self.quotient_filter_short_circuits.set(0);
    }

    fn eval_prepared_direct_simple_insert_explicit_rowid_only(
        &self,
        direct: &PreparedDirectSimpleInsert,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<i64>> {
        let Some(compiled_row_values) = direct.compiled_row_values.as_ref() else {
            return Ok(None);
        };
        let mut concat_text_scratch = self.prepared_direct_insert_text_scratch.borrow_mut();
        concat_text_scratch.clear();
        for (col_idx, (column, expr)) in direct
            .columns
            .iter()
            .zip(compiled_row_values.iter())
            .enumerate()
        {
            let is_rowid_alias = column.is_ipk || direct.rowid_alias_col_idx == Some(col_idx);
            if !is_rowid_alias {
                continue;
            }
            let raw_value = Self::eval_prepared_direct_simple_insert_expr(
                expr,
                params,
                Some(&mut concat_text_scratch),
            )?;
            let value = if let Some(strict_type) = column.strict_type {
                raw_value.validate_strict(strict_type).map_err(|error| {
                    FrankenError::DatatypeViolation {
                        column: column.name.clone(),
                        column_type: format!("{strict_type:?}").to_ascii_uppercase(),
                        actual: error.actual.to_string(),
                    }
                })?
            } else {
                raw_value
            };
            return Self::coerce_insert_rowid_value(&value);
        }
        Ok(None)
    }

    fn prepared_direct_simple_insert_param(
        params: Option<&[SqliteValue]>,
        one_based: usize,
    ) -> Result<&SqliteValue> {
        let Some(params) = params else {
            return Err(FrankenError::OutOfRange {
                what: "bind parameter index".to_owned(),
                value: one_based.to_string(),
            });
        };
        params
            .get(one_based.saturating_sub(1))
            .ok_or_else(|| FrankenError::OutOfRange {
                what: "bind parameter index".to_owned(),
                value: one_based.to_string(),
            })
    }

    fn push_prepared_direct_simple_insert_value(
        table_name: &str,
        direct: &PreparedDirectSimpleInsert,
        col_idx: usize,
        column: &ColumnInfo,
        raw_value: SqliteValue,
        explicit_rowid: &mut Option<i64>,
        mem_row_values: &mut PreparedDirectInsertRowScratch,
    ) -> Result<()> {
        let is_rowid_alias = column.is_ipk || direct.rowid_alias_col_idx == Some(col_idx);
        let value = if let Some(strict_type) = column.strict_type {
            raw_value.validate_strict(strict_type).map_err(|error| {
                FrankenError::DatatypeViolation {
                    column: format!("{table_name}.{}", column.name),
                    column_type: format!("{strict_type:?}").to_ascii_uppercase(),
                    actual: error.actual.to_string(),
                }
            })?
        } else {
            raw_value
        };

        if is_rowid_alias {
            *explicit_rowid = Self::coerce_insert_rowid_value(&value)?;
            mem_row_values.push(SqliteValue::Null);
            return Ok(());
        }

        if column.notnull && value.is_null() {
            return Err(FrankenError::NotNullViolation {
                column: format!("{table_name}.{}", column.name),
            });
        }

        let value = value.apply_affinity(Self::type_affinity_for_direct_insert(column.affinity));
        mem_row_values.push(value);
        Ok(())
    }

    fn append_prepared_direct_simple_insert_text(text: &mut String, value: &SqliteValue) {
        match value {
            SqliteValue::Null => {}
            SqliteValue::Integer(integer) => {
                let mut buffer = itoa::Buffer::new();
                text.push_str(buffer.format(*integer));
            }
            SqliteValue::Float(float) => text.push_str(&format_sqlite_float(*float)),
            SqliteValue::Text(segment_text) => text.push_str(segment_text),
            SqliteValue::Blob(bytes) => {
                let blob_text = String::from_utf8_lossy(bytes);
                text.push_str(&blob_text);
            }
        }
    }

    fn prepared_direct_insert_text_scratch_value<'a>(
        text_scratch: &mut String,
        text: &str,
    ) -> PreparedDirectInsertRecordValue<'a> {
        let start = text_scratch.len();
        text_scratch.push_str(text);
        PreparedDirectInsertRecordValue::TextScratch {
            start,
            len: text_scratch.len() - start,
        }
    }

    fn prepared_direct_insert_borrowed_record_value(
        value: &SqliteValue,
    ) -> PreparedDirectInsertRecordValue<'_> {
        match value {
            SqliteValue::Null => PreparedDirectInsertRecordValue::Null,
            SqliteValue::Integer(integer) => PreparedDirectInsertRecordValue::Integer(*integer),
            SqliteValue::Float(float) => PreparedDirectInsertRecordValue::Float(*float),
            SqliteValue::Text(text) => {
                PreparedDirectInsertRecordValue::TextBorrowed(text.as_bytes_direct())
            }
            SqliteValue::Blob(blob) => PreparedDirectInsertRecordValue::BlobBorrowed(blob),
        }
    }

    fn prepared_direct_insert_owned_record_value<'a>(
        value: SqliteValue,
        text_scratch: &mut String,
    ) -> Option<PreparedDirectInsertRecordValue<'a>> {
        match value {
            SqliteValue::Null => Some(PreparedDirectInsertRecordValue::Null),
            SqliteValue::Integer(integer) => {
                Some(PreparedDirectInsertRecordValue::Integer(integer))
            }
            SqliteValue::Float(float) => Some(PreparedDirectInsertRecordValue::Float(float)),
            SqliteValue::Text(text) => Some(Self::prepared_direct_insert_text_scratch_value(
                text_scratch,
                text.as_str(),
            )),
            SqliteValue::Blob(_) => None,
        }
    }

    #[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
    fn apply_prepared_direct_insert_record_affinity<'a>(
        value: PreparedDirectInsertRecordValue<'a>,
        affinity: TypeAffinity,
        text_scratch: &mut String,
    ) -> Option<PreparedDirectInsertRecordValue<'a>> {
        match affinity {
            TypeAffinity::Blob => Some(value),
            TypeAffinity::Text => match value {
                PreparedDirectInsertRecordValue::Null
                | PreparedDirectInsertRecordValue::TextBorrowed(_)
                | PreparedDirectInsertRecordValue::TextScratch { .. }
                | PreparedDirectInsertRecordValue::BlobBorrowed(_) => Some(value),
                PreparedDirectInsertRecordValue::Integer(integer) => {
                    let mut buffer = itoa::Buffer::new();
                    Some(Self::prepared_direct_insert_text_scratch_value(
                        text_scratch,
                        buffer.format(integer),
                    ))
                }
                PreparedDirectInsertRecordValue::Float(float) => {
                    let text = format_sqlite_float(float);
                    Some(Self::prepared_direct_insert_text_scratch_value(
                        text_scratch,
                        text.as_str(),
                    ))
                }
            },
            // NUMERIC and INTEGER affinity coerce identically for storage (they
            // differ only inside CAST): text falls back to the slow path, and a
            // REAL with an integral, in-range value is reduced to INTEGER so
            // e.g. `4.0` is stored as the integer `4`.
            TypeAffinity::Numeric | TypeAffinity::Integer => match value {
                PreparedDirectInsertRecordValue::TextBorrowed(_)
                | PreparedDirectInsertRecordValue::TextScratch { .. } => None,
                PreparedDirectInsertRecordValue::Float(float)
                    if (-9_223_372_036_854_775_808.0..9_223_372_036_854_775_808.0)
                        .contains(&float) =>
                {
                    let integer = float as i64;
                    if (integer as f64) == float {
                        Some(PreparedDirectInsertRecordValue::Integer(integer))
                    } else {
                        Some(PreparedDirectInsertRecordValue::Float(float))
                    }
                }
                _ => Some(value),
            },
            TypeAffinity::Real => match value {
                PreparedDirectInsertRecordValue::TextBorrowed(_)
                | PreparedDirectInsertRecordValue::TextScratch { .. } => None,
                PreparedDirectInsertRecordValue::Integer(integer) => {
                    Some(PreparedDirectInsertRecordValue::Float(integer as f64))
                }
                _ => Some(value),
            },
        }
    }

    fn try_append_prepared_direct_insert_concat_to_scratch(
        segments: &[PreparedDirectSimpleConcatSegment],
        params: Option<&[SqliteValue]>,
        text_scratch: &mut String,
        cached_param_one_integer_text: Option<&str>,
    ) -> Result<Option<Range<usize>>> {
        let start = text_scratch.len();
        let mut saw_null = false;
        for segment in segments {
            match segment {
                PreparedDirectSimpleConcatSegment::NullLiteral => {
                    saw_null = true;
                }
                PreparedDirectSimpleConcatSegment::TextLiteral(value) => {
                    if !saw_null {
                        text_scratch.push_str(value);
                    }
                }
                PreparedDirectSimpleConcatSegment::Literal(value) => {
                    if !saw_null {
                        Self::append_prepared_direct_simple_insert_text(text_scratch, value);
                    }
                }
                PreparedDirectSimpleConcatSegment::Placeholder(one_based) => {
                    if *one_based == 1
                        && let Some(cached_text) = cached_param_one_integer_text
                    {
                        text_scratch.push_str(cached_text);
                        continue;
                    }
                    let value = Self::prepared_direct_simple_insert_param(params, *one_based)?;
                    if value.is_null() {
                        saw_null = true;
                        continue;
                    }
                    if !saw_null {
                        Self::append_prepared_direct_simple_insert_text(text_scratch, value);
                    }
                }
                PreparedDirectSimpleConcatSegment::Expr(expr) => {
                    let value = Self::eval_prepared_direct_simple_insert_expr(expr, params, None)?;
                    if value.is_null() {
                        saw_null = true;
                        continue;
                    }
                    if !saw_null {
                        Self::append_prepared_direct_simple_insert_text(text_scratch, &value);
                    }
                }
            }
        }
        if saw_null {
            text_scratch.truncate(start);
            Ok(None)
        } else {
            Ok(Some(start..text_scratch.len()))
        }
    }

    fn try_eval_prepared_direct_insert_record_value<'a>(
        expr: &'a PreparedDirectSimpleInsertExpr,
        params: Option<&'a [SqliteValue]>,
        text_scratch: &mut String,
        cached_param_one_integer_text: Option<&str>,
    ) -> Result<Option<PreparedDirectInsertRecordValue<'a>>> {
        match expr {
            PreparedDirectSimpleInsertExpr::Literal(value) => Ok(Some(
                Self::prepared_direct_insert_borrowed_record_value(value),
            )),
            PreparedDirectSimpleInsertExpr::Placeholder(one_based) => {
                let value = Self::prepared_direct_simple_insert_param(params, *one_based)?;
                Ok(Some(Self::prepared_direct_insert_borrowed_record_value(
                    value,
                )))
            }
            PreparedDirectSimpleInsertExpr::ConcatChain(segments) => {
                let Some(range) = Self::try_append_prepared_direct_insert_concat_to_scratch(
                    segments,
                    params,
                    text_scratch,
                    cached_param_one_integer_text,
                )?
                else {
                    return Ok(Some(PreparedDirectInsertRecordValue::Null));
                };
                Ok(Some(PreparedDirectInsertRecordValue::TextScratch {
                    start: range.start,
                    len: range.end - range.start,
                }))
            }
            _ => {
                let value = Self::eval_prepared_direct_simple_insert_expr(expr, params, None)?;
                Ok(Self::prepared_direct_insert_owned_record_value(
                    value,
                    text_scratch,
                ))
            }
        }
    }

    fn prepared_direct_insert_record_header_size(content_size: usize) -> usize {
        let mut header_size = content_size + 1;
        loop {
            let needed = varint_len(u64::try_from(header_size).unwrap_or(u64::MAX)) + content_size;
            if needed <= header_size {
                return header_size;
            }
            header_size = needed;
        }
    }

    fn prepared_direct_insert_record_value_layout(
        value: PreparedDirectInsertRecordValue<'_>,
    ) -> (u64, usize) {
        match value {
            PreparedDirectInsertRecordValue::Null => (0, 0),
            PreparedDirectInsertRecordValue::Integer(integer) => {
                let serial_type = serial_type_for_integer(integer);
                (
                    serial_type,
                    usize::try_from(serial_type_len(serial_type).unwrap_or(0))
                        .unwrap_or(usize::MAX),
                )
            }
            PreparedDirectInsertRecordValue::Float(float) => {
                if float.is_nan() {
                    (0, 0)
                } else {
                    (7, 8)
                }
            }
            PreparedDirectInsertRecordValue::TextBorrowed(text) => {
                let len = text.len();
                (
                    serial_type_for_text(u64::try_from(len).unwrap_or(u64::MAX)),
                    len,
                )
            }
            PreparedDirectInsertRecordValue::TextScratch { len, .. } => (
                serial_type_for_text(u64::try_from(len).unwrap_or(u64::MAX)),
                len,
            ),
            PreparedDirectInsertRecordValue::BlobBorrowed(blob) => {
                let len = blob.len();
                (
                    serial_type_for_blob(u64::try_from(len).unwrap_or(u64::MAX)),
                    len,
                )
            }
        }
    }

    fn prepared_direct_insert_record_cell(
        value: PreparedDirectInsertRecordValue<'_>,
    ) -> PreparedDirectInsertRecordCell<'_> {
        let (serial_type, payload_len) = Self::prepared_direct_insert_record_value_layout(value);
        PreparedDirectInsertRecordCell {
            value,
            serial_type,
            payload_len,
        }
    }

    fn append_prepared_direct_insert_record_value(
        value: PreparedDirectInsertRecordValue<'_>,
        text_scratch: &str,
        payload_len: usize,
        buf: &mut Vec<u8>,
    ) {
        let start_len = buf.len();
        match value {
            PreparedDirectInsertRecordValue::Null => {}
            PreparedDirectInsertRecordValue::Integer(integer) => {
                if payload_len != 0 {
                    let bytes = integer.to_be_bytes();
                    buf.extend_from_slice(&bytes[8 - payload_len..]);
                }
            }
            PreparedDirectInsertRecordValue::Float(float) => {
                if !float.is_nan() {
                    buf.extend_from_slice(&float.to_bits().to_be_bytes());
                }
            }
            PreparedDirectInsertRecordValue::TextBorrowed(text) => {
                buf.extend_from_slice(text);
            }
            PreparedDirectInsertRecordValue::TextScratch { start, len } => {
                buf.extend_from_slice(&text_scratch.as_bytes()[start..start + len]);
            }
            PreparedDirectInsertRecordValue::BlobBorrowed(blob) => {
                buf.extend_from_slice(blob);
            }
        }
        debug_assert_eq!(buf.len() - start_len, payload_len);
    }

    fn serialize_prepared_direct_insert_record_cells_into(
        cells: &[PreparedDirectInsertRecordCell<'_>],
        header_content_size: usize,
        body_size: usize,
        text_scratch: &str,
        buf: &mut Vec<u8>,
    ) {
        debug_assert_eq!(
            header_content_size,
            cells
                .iter()
                .map(|cell| varint_len(cell.serial_type))
                .sum::<usize>()
        );
        debug_assert_eq!(
            body_size,
            cells.iter().map(|cell| cell.payload_len).sum::<usize>()
        );

        let header_size = Self::prepared_direct_insert_record_header_size(header_content_size);
        let total_size = header_size + body_size;
        buf.clear();
        if buf.capacity() < total_size {
            buf.reserve(total_size - buf.capacity());
        }
        buf.resize(header_size, 0);

        let mut header_offset = write_varint(
            buf.as_mut_slice(),
            u64::try_from(header_size).unwrap_or(u64::MAX),
        );
        for cell in cells {
            header_offset += write_varint(&mut buf[header_offset..], cell.serial_type);
            Self::append_prepared_direct_insert_record_value(
                cell.value,
                text_scratch,
                cell.payload_len,
                buf,
            );
        }

        debug_assert_eq!(header_offset, header_size);
        debug_assert_eq!(buf.len(), total_size);
    }

    #[allow(clippy::too_many_lines)]
    fn try_serialize_prepared_direct_simple_insert_record<'a>(
        table_name: &str,
        direct: &'a PreparedDirectSimpleInsert,
        params: Option<&'a [SqliteValue]>,
        record_scratch: &mut Vec<u8>,
        text_scratch: &mut String,
        profile_enabled: bool,
    ) -> Result<PreparedDirectInsertRecordBuild> {
        let Some(compiled_row_values) = direct.compiled_row_values.as_ref() else {
            return Ok(PreparedDirectInsertRecordBuild::Fallback);
        };
        if direct
            .columns
            .iter()
            .any(|column| column.strict_type.is_some())
        {
            return Ok(PreparedDirectInsertRecordBuild::Fallback);
        }
        if compiled_row_values.len() != direct.columns.len() {
            return Err(FrankenError::internal(format!(
                "prepared direct insert compiled row width {} does not match table width {}",
                compiled_row_values.len(),
                direct.columns.len()
            )));
        }
        let cell_build_start = profile_enabled.then(Instant::now);
        text_scratch.clear();
        let mut param_one_integer_buffer = itoa::Buffer::new();
        let cached_param_one_integer_text = match params.and_then(|values| values.first()) {
            Some(SqliteValue::Integer(value)) => Some(param_one_integer_buffer.format(*value)),
            _ => None,
        };
        let mut explicit_rowid = None;
        let mut cells: SmallVec<[PreparedDirectInsertRecordCell<'a>; 16]> =
            SmallVec::with_capacity(direct.columns.len());
        let mut header_content_size = 0usize;
        let mut body_size = 0usize;
        let mut eval_time_ns = 0u64;
        let mut affinity_time_ns = 0u64;
        let mut layout_time_ns = 0u64;
        for (col_idx, (column, expr)) in direct
            .columns
            .iter()
            .zip(compiled_row_values.iter())
            .enumerate()
        {
            let is_rowid_alias = column.is_ipk || direct.rowid_alias_col_idx == Some(col_idx);
            if is_rowid_alias {
                let eval_start = profile_enabled.then(Instant::now);
                let raw_value = Self::eval_prepared_direct_simple_insert_expr(expr, params, None)?;
                if let Some(elapsed_ns) = hot_path_elapsed_ns(eval_start) {
                    eval_time_ns = eval_time_ns.saturating_add(elapsed_ns);
                }
                explicit_rowid = Self::coerce_insert_rowid_value(&raw_value)?;
                let layout_start = profile_enabled.then(Instant::now);
                let cell =
                    Self::prepared_direct_insert_record_cell(PreparedDirectInsertRecordValue::Null);
                header_content_size += varint_len(cell.serial_type);
                body_size += cell.payload_len;
                cells.push(cell);
                if let Some(elapsed_ns) = hot_path_elapsed_ns(layout_start) {
                    layout_time_ns = layout_time_ns.saturating_add(elapsed_ns);
                }
                continue;
            }

            let eval_start = profile_enabled.then(Instant::now);
            let raw_value = Self::try_eval_prepared_direct_insert_record_value(
                expr,
                params,
                text_scratch,
                cached_param_one_integer_text,
            )?;
            let Some(raw_value) = raw_value else {
                return Ok(PreparedDirectInsertRecordBuild::Fallback);
            };
            let eval_elapsed_ns = hot_path_elapsed_ns(eval_start);
            if column.notnull && raw_value.is_null() {
                return Err(FrankenError::NotNullViolation {
                    column: format!("{table_name}.{}", column.name),
                });
            }
            let affinity = Self::type_affinity_for_direct_insert(column.affinity);
            let affinity_start = profile_enabled.then(Instant::now);
            let value = Self::apply_prepared_direct_insert_record_affinity(
                raw_value,
                affinity,
                text_scratch,
            );
            let affinity_elapsed_ns = hot_path_elapsed_ns(affinity_start);
            let Some(value) = value else {
                return Ok(PreparedDirectInsertRecordBuild::Fallback);
            };
            if let Some(elapsed_ns) = eval_elapsed_ns {
                eval_time_ns = eval_time_ns.saturating_add(elapsed_ns);
            }
            if let Some(elapsed_ns) = affinity_elapsed_ns {
                affinity_time_ns = affinity_time_ns.saturating_add(elapsed_ns);
            }
            let layout_start = profile_enabled.then(Instant::now);
            let cell = Self::prepared_direct_insert_record_cell(value);
            header_content_size += varint_len(cell.serial_type);
            body_size += cell.payload_len;
            cells.push(cell);
            if let Some(elapsed_ns) = hot_path_elapsed_ns(layout_start) {
                layout_time_ns = layout_time_ns.saturating_add(elapsed_ns);
            }
        }

        let cell_build_elapsed_ns = hot_path_elapsed_ns(cell_build_start);
        if profile_enabled {
            record_hot_path_elapsed_ns(
                &FSQLITE_PREPARED_DIRECT_INSERT_PRESERIALIZE_EVAL_TIME_NS,
                Some(eval_time_ns),
            );
            record_hot_path_elapsed_ns(
                &FSQLITE_PREPARED_DIRECT_INSERT_PRESERIALIZE_AFFINITY_TIME_NS,
                Some(affinity_time_ns),
            );
            record_hot_path_elapsed_ns(
                &FSQLITE_PREPARED_DIRECT_INSERT_PRESERIALIZE_LAYOUT_TIME_NS,
                Some(layout_time_ns),
            );
        }
        record_hot_path_elapsed_ns(
            &FSQLITE_PREPARED_DIRECT_INSERT_PRESERIALIZE_CELL_TIME_NS,
            cell_build_elapsed_ns,
        );
        let encode_start = profile_enabled.then(Instant::now);
        Self::serialize_prepared_direct_insert_record_cells_into(
            cells.as_slice(),
            header_content_size,
            body_size,
            text_scratch.as_str(),
            record_scratch,
        );
        record_hot_path_duration(
            &FSQLITE_PREPARED_DIRECT_INSERT_PRESERIALIZE_ENCODE_TIME_NS,
            encode_start,
        );
        Ok(PreparedDirectInsertRecordBuild::Serialized { explicit_rowid })
    }

    fn eval_prepared_direct_simple_insert_concat_chain(
        segments: &[PreparedDirectSimpleConcatSegment],
        params: Option<&[SqliteValue]>,
        text_scratch: &mut String,
    ) -> Result<SqliteValue> {
        text_scratch.clear();
        let mut saw_null = false;
        for segment in segments {
            match segment {
                PreparedDirectSimpleConcatSegment::NullLiteral => {
                    saw_null = true;
                }
                PreparedDirectSimpleConcatSegment::TextLiteral(value) => {
                    if !saw_null {
                        text_scratch.push_str(value);
                    }
                }
                PreparedDirectSimpleConcatSegment::Literal(value) => {
                    if !saw_null {
                        Self::append_prepared_direct_simple_insert_text(text_scratch, value);
                    }
                }
                PreparedDirectSimpleConcatSegment::Placeholder(one_based) => {
                    let value = Self::prepared_direct_simple_insert_param(params, *one_based)?;
                    if value.is_null() {
                        saw_null = true;
                        continue;
                    }
                    if !saw_null {
                        Self::append_prepared_direct_simple_insert_text(text_scratch, value);
                    }
                }
                PreparedDirectSimpleConcatSegment::Expr(expr) => {
                    let value = Self::eval_prepared_direct_simple_insert_expr(expr, params, None)?;
                    if value.is_null() {
                        saw_null = true;
                        continue;
                    }
                    if !saw_null {
                        Self::append_prepared_direct_simple_insert_text(text_scratch, &value);
                    }
                }
            }
        }
        if saw_null {
            Ok(SqliteValue::Null)
        } else {
            Ok(SqliteValue::Text(text_scratch.as_str().into()))
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn try_execute_precompiled_prepared_update_delete_autocommit_direct_simple_fast(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        kind: PreparedDmlKind,
        rollback_on_constraint_violation: bool,
        preserve_prior_changes_on_constraint_violation: bool,
        skip_statement_savepoint_in_explicit_txn: bool,
        prebound_publication: Option<BoundPagerPublication>,
        params: Option<&[SqliteValue]>,
    ) -> Option<Result<usize>> {
        if self.in_transaction.get()
            || self.active_txn.borrow().is_some()
            || !skip_statement_savepoint_in_explicit_txn
            || rollback_on_constraint_violation
        {
            return None;
        }

        let fast_path = stmt.prepared_update_delete_fast_path()?;
        let table_name = fast_path.table_name.as_str();
        let has_direct_shape = match kind {
            PreparedDmlKind::Update => fast_path.direct_simple_update.is_some(),
            PreparedDmlKind::Delete => fast_path.direct_simple_delete.is_some(),
            PreparedDmlKind::Insert => false,
        };
        if !has_direct_shape {
            return None;
        }

        // Reuse the publication that the prepared-schema-refresh step already
        // bound, mirroring the INSERT fast path. Without this the autocommit
        // begin would re-bind (a second `pager_publication_refresh`) for every
        // prepared UPDATE/DELETE (bd-db300.5.2.2.4 / T13).
        let was_auto = match self
            .ensure_autocommit_txn_with_publication_hint(execution_cx, prebound_publication)
        {
            Ok(was_auto) => was_auto,
            Err(error) => return Some(Err(error)),
        };
        if !was_auto {
            return Some(Err(FrankenError::internal(
                "autocommit direct UPDATE/DELETE entered non-autocommit transaction",
            )));
        }

        self.txn_metrics_note_write();
        let execute_body_start = hot_path_profile_enabled().then(Instant::now);
        let result = match kind {
            PreparedDmlKind::Update => {
                let direct = fast_path.direct_simple_update.as_ref()?;
                if hot_path_profile_enabled() {
                    FSQLITE_PREPARED_DIRECT_UPDATE_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                self.execute_prepared_direct_simple_update(execution_cx, direct, params)
            }
            PreparedDmlKind::Delete => {
                let direct = fast_path.direct_simple_delete.as_ref()?;
                if hot_path_profile_enabled() {
                    FSQLITE_PREPARED_DIRECT_DELETE_EXECUTIONS.fetch_add(1, AtomicOrdering::Relaxed);
                }
                self.execute_prepared_direct_simple_delete(execution_cx, direct, params)
            }
            PreparedDmlKind::Insert => return None,
        };
        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);

        let result = match result {
            Ok(affected) => {
                self.record_statement_changes_without_sync(affected);
                Ok(affected)
            }
            Err(error) => match self.maybe_rollback_transaction_for_conflict_action(
                rollback_on_constraint_violation,
                was_auto,
                &error,
            ) {
                Ok(()) => Err(error),
                Err(rollback_error) => Err(rollback_error),
            },
        };
        let commit_autocommit_on_error = matches!(
            result.as_ref(),
            Err(error) if error_preserves_prior_statement_rows(
                preserve_prior_changes_on_constraint_violation,
                error,
            )
        );
        let ok = result.is_ok() || commit_autocommit_on_error;
        if matches!(result.as_ref(), Ok(0)) {
            // Direct rowid UPDATE/DELETE can be a true no-op. In a retained
            // autocommit batch with older pending writes, the resolver still
            // sees a dirty transaction and parks it again; do not let that
            // bookkeeping invalidate an aggregate cache for a table that this
            // statement did not change.
            self.preserve_retained_autocommit_count_sum_cache_for_noop_write();
        }
        let resolve_result = self.resolve_autocommit_txn_with_dirty_table_and_capture_and_cx(
            was_auto,
            ok,
            Some(table_name),
            false,
            false,
            execution_cx,
        );
        Some(match resolve_result {
            Ok(()) => result,
            Err(error) => Err(error),
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn execute_precompiled_prepared_update_or_delete(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        kind: PreparedDmlKind,
        rollback_on_constraint_violation: bool,
        preserve_prior_changes_on_constraint_violation: bool,
        skip_statement_savepoint_in_explicit_txn: bool,
        entry_proof: PreparedDmlEntryProof,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        // Issue #110: a prepared UPDATE or DELETE may mutate or remove a parent
        // row that an earlier child INSERT validated and cached this
        // transaction. This fast lane bypasses the central statement
        // dispatcher, so drop the transaction-scoped FK parent-validation
        // cache here before executing.
        self.clear_fk_parent_validation_cache();
        // Direct-simple UPDATE/DELETE in-transaction fast lane.
        //
        // Mirrors the INSERT `execute_precompiled_prepared_insert_fast` shape:
        // when the statement was classified as a rowid-targeted simple DML
        // (no indexes / triggers / FK / constraints requiring validation) AND
        // we are already inside an explicit txn with statement-savepoint
        // elision, execute directly through a BtCursor — bypassing the VDBE
        // register file, dispatch loop, and memdb mirror ceremony.
        //
        // Note: we intentionally DO NOT gate on
        // `stmt.may_observe_change_tracking` here. That flag is set to `true`
        // for every UPDATE/DELETE by the conservative fallthrough in
        // `statement_may_observe_change_tracking` — it isn't wired to detect
        // the specific rowid-eq shape we accept. The direct-simple
        // eligibility gate forbids subqueries, function calls, and anything
        // else that could actually observe change tracking.
        let mut entry_proof = entry_proof;
        let in_txn_confirmed = if entry_proof.microbatch_carry_verified_in_txn {
            self.in_transaction.get()
        } else {
            self.in_transaction.get() && self.active_txn.borrow().is_some()
        };
        let fused_auto = self.fused_entry_control_mode.get() == FusedEntryControlMode::Auto;
        let tracing_off = !tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG);
        if fused_auto
            && tracing_off
            && !tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO)
            && let Some(result) = self
                .try_execute_precompiled_prepared_update_delete_autocommit_direct_simple_fast(
                    execution_cx,
                    stmt,
                    kind,
                    rollback_on_constraint_violation,
                    preserve_prior_changes_on_constraint_violation,
                    skip_statement_savepoint_in_explicit_txn,
                    entry_proof.publication.take(),
                    params,
                )
        {
            return result;
        }
        if in_txn_confirmed
            && skip_statement_savepoint_in_explicit_txn
            && !rollback_on_constraint_violation
            && fused_auto
            && tracing_off
            && !tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO)
            && let Some(fast_path) = stmt.prepared_update_delete_fast_path()
        {
            match kind {
                PreparedDmlKind::Update => {
                    if let Some(direct) = fast_path.direct_simple_update.as_ref() {
                        if hot_path_profile_enabled() {
                            FSQLITE_PREPARED_DIRECT_UPDATE_EXECUTIONS
                                .fetch_add(1, AtomicOrdering::Relaxed);
                        }
                        self.txn_metrics_note_write();
                        match self.execute_prepared_direct_simple_update(
                            execution_cx,
                            direct,
                            params,
                        ) {
                            Ok(affected) => {
                                self.record_statement_changes_without_sync(affected);
                                let _ = entry_proof;
                                return Ok(affected);
                            }
                            Err(FrankenError::NotImplemented(_)) => {
                                // Fall through to standard path.
                            }
                            Err(e) => return Err(e),
                        }
                    }
                }
                PreparedDmlKind::Delete => {
                    if let Some(direct) = fast_path.direct_simple_delete.as_ref() {
                        if hot_path_profile_enabled() {
                            FSQLITE_PREPARED_DIRECT_DELETE_EXECUTIONS
                                .fetch_add(1, AtomicOrdering::Relaxed);
                        }
                        self.txn_metrics_note_write();
                        match self.execute_prepared_direct_simple_delete(
                            execution_cx,
                            direct,
                            params,
                        ) {
                            Ok(affected) => {
                                self.record_statement_changes_without_sync(affected);
                                let _ = entry_proof;
                                return Ok(affected);
                            }
                            Err(FrankenError::NotImplemented(_)) => {
                                // Fall through to standard path.
                            }
                            Err(e) => return Err(e),
                        }
                    }
                }
                PreparedDmlKind::Insert => {}
            }
        }
        // VDBE UPDATE deletes the old row before validating CHECK / NOT NULL
        // constraints for the replacement row. If the direct-simple lane is
        // bypassed, keep the statement savepoint so a constraint error restores
        // the original row inside an explicit transaction.
        let vdbe_skip_statement_savepoint_in_explicit_txn =
            skip_statement_savepoint_in_explicit_txn && kind != PreparedDmlKind::Update;
        if in_txn_confirmed
            && !stmt.may_observe_change_tracking
            && vdbe_skip_statement_savepoint_in_explicit_txn
            && fused_auto
            && tracing_off
        {
            return self
                .execute_prepared_dml_entry(
                    execution_cx,
                    kind.statement_kind(),
                    stmt.precompiled_dml()
                        .map(|dispatch| dispatch.table_name.as_str()),
                    rollback_on_constraint_violation,
                    preserve_prior_changes_on_constraint_violation,
                    vdbe_skip_statement_savepoint_in_explicit_txn,
                    false,
                    entry_proof.publication,
                    PreparedDmlAutocommitProfileMode::None,
                    || {
                        self.execute_precompiled_prepared_update_or_delete_dispatch(
                            execution_cx,
                            stmt,
                            params,
                        )
                    },
                )
                .result;
        }
        self.clear_table_program_error_state();
        self.sync_change_tracking_context();
        // bd-perf: Skip memdb refresh for all VDBE DML paths — the VDBE engine
        // operates through storage cursors (pager/btree), not MemDatabase.
        // The previous conditional skip was too conservative (required
        // skip_statement_savepoint + static_runtime_inputs + no indexes).
        // Memdb will be lazily refreshed on the next read boundary.
        let statement_trace_enabled =
            tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG);
        let statement_reuse_enabled =
            tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO);
        let trace_registration = {
            let trace_registration = self.trace_registration.borrow();
            let compat_trace_stmt_enabled = trace_registration
                .as_ref()
                .is_some_and(|trace| trace.mask.contains(TraceMask::STMT));
            let compat_trace_profile_enabled = trace_registration
                .as_ref()
                .is_some_and(|trace| trace.mask.contains(TraceMask::PROFILE));
            // bd-db300.5.2.2.4: forced_fallback bypasses the fast lane.
            let fused_control_mode = self.fused_entry_control_mode.get();
            let forced_fallback = fused_control_mode == FusedEntryControlMode::ForcedFallback;
            if !forced_fallback
                && !statement_trace_enabled
                && !compat_trace_stmt_enabled
                && !compat_trace_profile_enabled
                && !statement_reuse_enabled
            {
                if hot_path_profile_enabled() {
                    FSQLITE_PREPARED_UPDATE_DELETE_FAST_LANE_HITS
                        .fetch_add(1, AtomicOrdering::Relaxed);
                }
                if tracing::enabled!(target: "fsqlite::fused_entry", tracing::Level::DEBUG) {
                    tracing::debug!(
                        target: "fsqlite::fused_entry",
                        entry_path = "fused",
                        control_mode = %fused_control_mode,
                        dml_kind = %kind.statement_kind(),
                        fallback_reason = "none",
                        "fused entry: update/delete fast lane"
                    );
                }
                return self
                    .execute_prepared_dml_entry(
                        execution_cx,
                        kind.statement_kind(),
                        stmt.precompiled_dml()
                            .map(|dispatch| dispatch.table_name.as_str())
                            .or_else(|| {
                                stmt.prepared_update_delete_fast_path()
                                    .map(|fast_path| fast_path.table_name.as_str())
                            }),
                        rollback_on_constraint_violation,
                        preserve_prior_changes_on_constraint_violation,
                        vdbe_skip_statement_savepoint_in_explicit_txn,
                        false,
                        entry_proof.publication,
                        PreparedDmlAutocommitProfileMode::None,
                        || {
                            self.execute_precompiled_prepared_update_or_delete_dispatch(
                                execution_cx,
                                stmt,
                                params,
                            )
                        },
                    )
                    .result;
            }
            trace_registration.clone()
        };
        if hot_path_profile_enabled() {
            FSQLITE_PREPARED_UPDATE_DELETE_INSTRUMENTED_LANE_HITS
                .fetch_add(1, AtomicOrdering::Relaxed);
        }
        let fused_control_mode = self.fused_entry_control_mode.get();
        if tracing::enabled!(target: "fsqlite::fused_entry", tracing::Level::DEBUG) {
            tracing::debug!(
                target: "fsqlite::fused_entry",
                entry_path = "conservative",
                control_mode = %fused_control_mode,
                dml_kind = %kind.statement_kind(),
                fallback_reason = if fused_control_mode == FusedEntryControlMode::ForcedFallback {
                    "forced_fallback"
                } else {
                    "tracing_or_reuse_enabled"
                },
                "fused entry: update/delete instrumented lane"
            );
        }
        let trace_id = statement_trace_enabled.then(next_trace_id).unwrap_or(0);
        let decision_id = statement_trace_enabled.then(next_decision_id).unwrap_or(0);
        let compat_trace_stmt_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::STMT));
        let compat_trace_profile_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::PROFILE));
        let compat_trace_sql = (compat_trace_stmt_enabled || compat_trace_profile_enabled)
            .then(|| Rc::clone(&stmt.sql));
        let statement_span = statement_trace_enabled.then(|| {
            let span = tracing::span!(
                target: "fsqlite.statement",
                tracing::Level::DEBUG,
                "statement",
                trace_id,
                decision_id,
                statement_kind = kind.statement_kind()
            );
            record_trace_span_created();
            span
        });
        let _statement_guard = statement_span.as_ref().map(tracing::Span::enter);
        if compat_trace_stmt_enabled {
            emit_compat_trace_event(
                trace_registration.as_ref(),
                TraceEvent::Statement {
                    sql: compat_trace_sql
                        .clone()
                        .unwrap_or_else(|| Rc::clone(&stmt.sql))
                        .as_ref()
                        .to_owned(),
                },
            );
        }
        let execution_started = (statement_reuse_enabled || compat_trace_profile_enabled)
            .then(fsqlite_types::sync_primitives::Instant::now);
        let outcome = self.execute_prepared_dml_entry(
            execution_cx,
            kind.statement_kind(),
            stmt.precompiled_dml()
                .map(|dispatch| dispatch.table_name.as_str())
                .or_else(|| {
                    stmt.prepared_update_delete_fast_path()
                        .map(|fast_path| fast_path.table_name.as_str())
                }),
            rollback_on_constraint_violation,
            preserve_prior_changes_on_constraint_violation,
            vdbe_skip_statement_savepoint_in_explicit_txn,
            false,
            entry_proof.publication,
            PreparedDmlAutocommitProfileMode::None,
            || {
                self.execute_precompiled_prepared_update_or_delete_dispatch(
                    execution_cx,
                    stmt,
                    params,
                )
            },
        );
        if outcome.resolve_succeeded && (statement_reuse_enabled || compat_trace_profile_enabled) {
            let elapsed_ns = execution_started
                .map(|started| u64::try_from(started.elapsed().as_nanos()).unwrap_or(u64::MAX))
                .unwrap_or(0);
            if statement_reuse_enabled {
                let failure_diag = match outcome.result.as_ref() {
                    Ok(_) => Cow::Borrowed("none"),
                    Err(error) => Cow::Owned(error.to_string()),
                };
                self.log_statement_reuse_event(
                    "execution",
                    stmt.sql.as_ref(),
                    true,
                    if outcome.execution_ok {
                        "none"
                    } else {
                        "execution_error"
                    },
                    0,
                    elapsed_ns,
                    failure_diag.as_ref(),
                );
            }
            if compat_trace_profile_enabled {
                emit_compat_trace_event(
                    trace_registration.as_ref(),
                    TraceEvent::Profile {
                        sql: compat_trace_sql
                            .unwrap_or_else(|| Rc::clone(&stmt.sql))
                            .as_ref()
                            .to_owned(),
                        elapsed_ns,
                    },
                );
            }
        }
        outcome.result
    }

    fn execute_precompiled_prepared_update_or_delete_dispatch(
        &self,
        execution_cx: &Cx,
        stmt: &PreparedStatement<'_>,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        self.clear_prepared_direct_insert_append_hint();
        let (affected, _) =
            stmt.execute_table_program_dml_with_reuse(execution_cx, params, false)?;
        self.record_statement_changes(affected);
        Ok(affected)
    }

    // ── Parse cache helpers (br-legjy.7.3) ─────────────────────────────

    /// Compute a 64-bit hash of an SQL string for parse cache lookup.
    fn sql_hash(sql: &str) -> u64 {
        use std::hash::BuildHasher;
        foldhash::fast::FixedState::default().hash_one(sql)
    }

    fn prepared_cache_key_for(
        sql: &str,
        schema_cookie: u32,
        schema_generation: u64,
        function_registry_generation: u64,
    ) -> u64 {
        use std::hash::BuildHasher;
        // bd-#70: db_generation (memdb_visible_commit_seq) and the finalized
        // global commit_epoch are deliberately NOT part of the cache *key* —
        // the key still hashes only schema-stable identity so the cache slot
        // is locatable across commits. Stale plans are evicted at lookup time
        // by `PreparedStatementTemplate::matches_cache_identity`, which now
        // also compares the commit_epoch (the bd-#70 wedge for the
        // cross-connection stale-read class). Mixing commit_epoch into the
        // hashed key would force a full re-prepare in commit loops even for
        // direct-DML templates that survive write commits (mt_mvcc_bench was
        // a ~2pp Lexer + write_ident regression on the 2026-04-23 MT capture).
        //
        // Conservative wedge: any commit invalidates non-direct-DML plans.
        // Future optimization: narrow by `pages_read_set ∩ pages_written_set`
        // so a commit that only touches unrelated pages leaves the plan live.
        foldhash::fast::FixedState::default().hash_one((
            sql,
            schema_cookie,
            schema_generation,
            function_registry_generation,
        ))
    }

    fn prepared_cache_key(&self, sql: &str) -> u64 {
        Self::prepared_cache_key_for(
            sql,
            self.schema_cookie(),
            self.schema_generation(),
            self.function_registry_generation(),
        )
    }

    /// Return a cached parsed single statement, or parse fresh and cache it.
    /// The cache is invalidated whenever the schema cookie changes (DDL).
    fn cached_parse_single(&self, sql: &str) -> Result<std::sync::Arc<Statement>> {
        let profile_enabled = hot_path_profile_enabled();
        if profile_enabled {
            FSQLITE_PARSE_SINGLE_CALLS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        let key = Self::sql_hash(sql);
        self.refresh_parse_cache_if_needed(sql);
        if let Some(cached) = self.lookup_parse_cache(key, sql) {
            if profile_enabled {
                FSQLITE_PARSE_CACHE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.log_statement_reuse_event("parse", sql, true, "none", 0, 0, "none");
            return Ok(std::sync::Arc::clone(&cached.statement));
        }
        #[cfg(not(test))]
        if let Some(cached) = Self::lookup_thread_parse_cache(key, sql) {
            if profile_enabled {
                FSQLITE_PARSE_CACHE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.insert_parse_cache_arc(key, sql, Arc::clone(&cached.statement));
            self.log_statement_reuse_event("parse", sql, true, "thread", 0, 0, "none");
            return Ok(std::sync::Arc::clone(&cached.statement));
        }
        if profile_enabled {
            FSQLITE_PARSE_CACHE_MISSES.fetch_add(1, AtomicOrdering::Relaxed);
            FSQLITE_PARSED_SQL_BYTES.fetch_add(
                u64::try_from(sql.len()).unwrap_or(u64::MAX),
                AtomicOrdering::Relaxed,
            );
        }
        let start = profile_enabled.then(Instant::now);
        let stmt = match self.parse_single_statement_with_statement_scratch(sql) {
            Ok(stmt) => stmt,
            Err(error) => {
                let failure_diag = error.to_string();
                self.log_statement_reuse_event(
                    "parse",
                    sql,
                    false,
                    "parse_error",
                    0,
                    0,
                    failure_diag.as_str(),
                );
                return Err(error);
            }
        };
        if let Some(start) = start {
            FSQLITE_PARSE_TIME_NS.fetch_add(
                u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX),
                AtomicOrdering::Relaxed,
            );
        }
        self.log_statement_reuse_event("parse", sql, false, "none", 0, 0, "none");
        let entry = self.insert_parse_cache(key, sql, stmt);
        #[cfg(not(test))]
        Self::insert_thread_parse_cache(key, sql, Arc::clone(&entry.statement));
        Ok(std::sync::Arc::clone(&entry.statement))
    }

    /// Return cached parsed multi-statement list, or parse fresh.
    /// Multi-statement SQL is less common and cache hit rate is lower,
    /// so we only cache single-statement SQL in this path.
    fn cached_parse_multi(&self, sql: &str) -> Result<Vec<std::sync::Arc<Statement>>> {
        let profile_enabled = hot_path_profile_enabled();
        if profile_enabled {
            FSQLITE_PARSE_MULTI_CALLS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        // Hot path optimization for repeated single-statement execute() calls.
        // Use the same collision-safe SQL equality check as cached_parse_single.
        let key = Self::sql_hash(sql);
        self.refresh_parse_cache_if_needed(sql);
        if let Some(cached) = self.lookup_parse_cache(key, sql) {
            if profile_enabled {
                FSQLITE_PARSE_CACHE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.log_statement_reuse_event("parse", sql, true, "none", 0, 0, "none");
            return Ok(vec![std::sync::Arc::clone(&cached.statement)]);
        }
        #[cfg(not(test))]
        if let Some(cached) = Self::lookup_thread_parse_cache(key, sql) {
            if profile_enabled {
                FSQLITE_PARSE_CACHE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.insert_parse_cache_arc(key, sql, Arc::clone(&cached.statement));
            self.log_statement_reuse_event("parse", sql, true, "thread", 0, 0, "none");
            return Ok(vec![std::sync::Arc::clone(&cached.statement)]);
        }

        // For single-statement SQL, use the cache.
        if profile_enabled {
            FSQLITE_PARSE_CACHE_MISSES.fetch_add(1, AtomicOrdering::Relaxed);
            FSQLITE_PARSED_SQL_BYTES.fetch_add(
                u64::try_from(sql.len()).unwrap_or(u64::MAX),
                AtomicOrdering::Relaxed,
            );
        }
        let start = profile_enabled.then(Instant::now);
        let stmts = match self.parse_statements_with_statement_scratch(sql) {
            Ok(stmts) => stmts,
            Err(error) => {
                let failure_diag = error.to_string();
                self.log_statement_reuse_event(
                    "parse",
                    sql,
                    false,
                    "parse_error",
                    0,
                    0,
                    failure_diag.as_str(),
                );
                return Err(error);
            }
        };
        if let Some(start) = start {
            FSQLITE_PARSE_TIME_NS.fetch_add(
                u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX),
                AtomicOrdering::Relaxed,
            );
        }
        if stmts.len() == 1 {
            let statement = stmts
                .into_iter()
                .next()
                .ok_or_else(|| FrankenError::ParseError {
                    offset: 0,
                    detail: "no SQL statement provided".to_owned(),
                })?;
            let entry = self.insert_parse_cache(key, sql, statement);
            #[cfg(not(test))]
            Self::insert_thread_parse_cache(key, sql, Arc::clone(&entry.statement));
            self.log_statement_reuse_event("parse", sql, false, "none", 0, 0, "none");
            return Ok(vec![Arc::clone(&entry.statement)]);
        }
        self.log_statement_reuse_event("parse", sql, false, "none", 0, 0, "none");
        Ok(stmts.into_iter().map(std::sync::Arc::new).collect())
    }

    fn refresh_parse_cache_if_needed(&self, sql: &str) {
        let current_cookie = *self.schema_cookie.borrow();
        let cached_cookie = *self.parse_cache_cookie.borrow();
        if cached_cookie != current_cookie {
            self.parse_cache.borrow_mut().clear();
            self.clear_compilation_reuse_caches();
            self.table_execution_metadata_cache.borrow_mut().take();
            *self.parse_cache_cookie.borrow_mut() = current_cookie;
            self.log_statement_reuse_event(
                "schema_invalidation",
                sql,
                false,
                "schema_cookie_changed",
                0,
                0,
                "none",
            );
        }
    }

    fn lookup_parse_cache(&self, key: u64, sql: &str) -> Option<Arc<ParseCacheEntry>> {
        let mut cache = self.parse_cache.borrow_mut();
        let entry = cache.get(&key)?;
        if entry.sql == sql {
            Some(Arc::clone(entry))
        } else {
            None
        }
    }

    fn insert_parse_cache(
        &self,
        key: u64,
        sql: &str,
        statement: Statement,
    ) -> Arc<ParseCacheEntry> {
        self.insert_parse_cache_arc(key, sql, Arc::new(statement))
    }

    fn insert_parse_cache_arc(
        &self,
        key: u64,
        sql: &str,
        statement: Arc<Statement>,
    ) -> Arc<ParseCacheEntry> {
        let mut cache = self.parse_cache.borrow_mut();
        let entry = Arc::new(ParseCacheEntry {
            sql: sql.to_owned(),
            statement,
        });
        cache.put(key, Arc::clone(&entry));
        entry
    }

    #[cfg(not(test))]
    fn lookup_thread_parse_cache(key: u64, sql: &str) -> Option<Arc<ParseCacheEntry>> {
        if sql.len() > THREAD_PARSE_CACHE_MAX_SQL_LEN {
            return None;
        }
        THREAD_PARSE_CACHE.with(|cache| {
            let mut cache = cache.borrow_mut();
            let entry = cache.get(&key)?;
            if entry.sql == sql {
                Some(Arc::clone(entry))
            } else {
                None
            }
        })
    }

    #[cfg(not(test))]
    fn insert_thread_parse_cache(key: u64, sql: &str, statement: Arc<Statement>) {
        if sql.len() > THREAD_PARSE_CACHE_MAX_SQL_LEN {
            return;
        }
        THREAD_PARSE_CACHE.with(|cache| {
            cache.borrow_mut().put(
                key,
                Arc::new(ParseCacheEntry {
                    sql: sql.to_owned(),
                    statement,
                }),
            );
        });
    }

    fn planner_directive_cache_key(sql: &str, feature_flags: PlannerFeatureFlags) -> u64 {
        Self::sql_hash(&format!(
            "{sql}|planner_flags:{}:{}",
            u8::from(feature_flags.leapfrog_join),
            u8::from(feature_flags.dpccp_join),
        ))
    }

    fn parse_error_to_franken_error(parse_error: fsqlite_parser::ParseError) -> FrankenError {
        FrankenError::ParseError {
            #[allow(clippy::cast_sign_loss)]
            offset: parse_error.span.start as usize,
            detail: parse_error.message,
        }
    }

    fn parse_single_statement_with_statement_scratch(&self, sql: &str) -> Result<Statement> {
        let statements = self.parse_statements_with_statement_scratch(sql)?;
        let mut iter = statements.into_iter();
        let statement = iter.next().ok_or_else(|| FrankenError::ParseError {
            offset: 0,
            detail: "no SQL statement provided".to_owned(),
        })?;
        if iter.next().is_some() {
            return Err(FrankenError::NotImplemented(
                "multiple statements are not supported in this API path".to_owned(),
            ));
        }
        Ok(statement)
    }

    fn parse_statements_with_statement_scratch(&self, sql: &str) -> Result<Vec<Statement>> {
        let _lookaside_growth = StatementLookasideGrowthGuard::new(self);
        let mut scratch = self.statement_parse_scratch.borrow_mut();
        parse_statements_with_scratch(sql, &mut scratch).map_err(Self::parse_error_to_franken_error)
    }

    fn statement_lookaside_retained_bytes(&self) -> usize {
        // Diagnostic-only measurement (hot-path profiling). It can run from the
        // StatementLookasideGrowthGuard Drop while one of these scratch cells is
        // still mutably borrowed by an in-flight INSERT — e.g. the direct-simple
        // lane holds `prepared_direct_insert_row_scratch` (as `mem_row_values`)
        // across the FK precheck/bail and the FK existence check. A hard
        // borrow() would panic there ("already mutably borrowed"), so read each
        // cell with try_borrow() and treat a busy cell as 0: undercounting a
        // single arena-growth sample is acceptable for a diagnostic counter; a
        // panic is not (#111).
        let parse_bytes = self
            .statement_parse_scratch
            .try_borrow()
            .map(|s| s.retained_bytes())
            .unwrap_or(0);
        let record_bytes = self
            .prepared_direct_insert_record_scratch
            .try_borrow()
            .map(|s| s.capacity())
            .unwrap_or(0);
        let row_bytes = self
            .prepared_direct_insert_row_scratch
            .try_borrow()
            .map(|s| {
                s.capacity()
                    .saturating_mul(std::mem::size_of::<SqliteValue>())
            })
            .unwrap_or(0);
        let text_bytes = self
            .prepared_direct_insert_text_scratch
            .try_borrow()
            .map(|s| s.capacity())
            .unwrap_or(0);
        let cell_bytes = self
            .prepared_direct_insert_cell_scratch
            .try_borrow()
            .map(|s| s.capacity())
            .unwrap_or(0);
        parse_bytes
            .saturating_add(record_bytes)
            .saturating_add(row_bytes)
            .saturating_add(text_bytes)
            .saturating_add(cell_bytes)
    }

    fn note_statement_lookaside_alloc_growth(&self, before_bytes: usize) {
        if !hot_path_profile_enabled() {
            return;
        }
        let after_bytes = self.statement_lookaside_retained_bytes();
        let growth = after_bytes.saturating_sub(before_bytes);
        if growth > 0 {
            FSQLITE_ARENA_ALLOC_BYTES.fetch_add(
                u64::try_from(growth).unwrap_or(u64::MAX),
                AtomicOrdering::Relaxed,
            );
        }
    }

    fn note_statement_lookaside_reset(&self) {
        if hot_path_profile_enabled() {
            FSQLITE_ARENA_RESET_COUNT.fetch_add(1, AtomicOrdering::Relaxed);
        }
    }

    fn note_statement_lookaside_fallback(&self) {
        if hot_path_profile_enabled() {
            FSQLITE_FALLBACK_TO_GENERAL_ALLOCATOR_COUNT.fetch_add(1, AtomicOrdering::Relaxed);
        }
    }

    fn lookup_planner_directive_cache(
        &self,
        key: u64,
        sql: &str,
        feature_flags: PlannerFeatureFlags,
    ) -> Option<Arc<PlannerDirectiveCacheEntry>> {
        let mut cache = self.planner_directive_cache.borrow_mut();
        let entry = cache.get(&key)?;
        if entry.sql == sql && entry.feature_flags == feature_flags {
            Some(Arc::clone(entry))
        } else {
            None
        }
    }

    fn insert_planner_directive_cache(
        &self,
        key: u64,
        sql: &str,
        feature_flags: PlannerFeatureFlags,
        directive: Option<SelectPlannerDirective>,
    ) -> Arc<PlannerDirectiveCacheEntry> {
        let mut cache = self.planner_directive_cache.borrow_mut();
        let entry = Arc::new(PlannerDirectiveCacheEntry {
            sql: sql.to_owned(),
            feature_flags,
            directive,
        });
        cache.put(key, Arc::clone(&entry));
        entry
    }

    fn discard_cached_vdbe_engine(&self) {
        let _ = self.cached_vdbe_engine.borrow_mut().take();
    }

    /// Clear all prepared-statement / compiled-program / planner-directive
    /// caches on this connection and reset statement lookaside scratch buffers.
    ///
    /// Intended to be called whenever cached plans may have become stale with
    /// respect to the schema, planner inputs, function registry, or committed
    /// row image. Write commits clear these caches because prepared execution
    /// templates may capture storage visibility assumptions, not just schema.
    ///
    /// Historical context: before post-write execution invalidation was added,
    /// downstream callers (notably `beads_rust`) had to wrap re-read paths in
    /// CTEs to force dispatch through the uncached slow path. See issue #72.
    pub fn clear_compilation_reuse_caches(&self) {
        self.compiled_cache.borrow_mut().clear();
        self.prepared_cache.borrow_mut().clear();
        self.planner_directive_cache.borrow_mut().clear();
        self.storage_count_cache.borrow_mut().clear();
        self.discard_cached_vdbe_engine();
        self.reset_statement_lookaside();
    }

    /// Clear compilation caches after an ordinary DML write commit.
    ///
    /// Table-backed read templates are bound to the pre-commit pager/MemDB
    /// visibility and must be evicted, but direct simple DML templates only
    /// cache schema-stable metadata (root page, column layout, cursor page
    /// size, bind slots). Keeping those avoids turning repeated UPDATE/DELETE
    /// loops back into a parse/compile benchmark while preserving the stale
    /// SELECT fix covered by `test_prepared_cache_clears_on_write_commit...`.
    fn clear_compilation_reuse_caches_after_write_commit(&self) {
        self.compiled_cache.borrow_mut().clear();
        self.prune_prepared_cache_after_write_commit();
        self.planner_directive_cache.borrow_mut().clear();
        self.storage_count_cache.borrow_mut().clear();
        self.discard_cached_vdbe_engine();
        self.reset_statement_lookaside();
    }

    fn prune_prepared_cache_after_write_commit(&self) {
        let mut cache = self.prepared_cache.borrow_mut();
        let stale_keys = cache
            .iter()
            .filter(|(_, entry)| !entry.template.can_survive_write_commit())
            .map(|(key, _)| *key)
            .collect::<Vec<_>>();
        for key in stale_keys {
            cache.pop(&key);
        }
    }

    fn reset_prepared_direct_insert_statement_scratch(&self) {
        self.prepared_direct_insert_record_scratch
            .borrow_mut()
            .clear();
        self.prepared_direct_insert_row_scratch.borrow_mut().clear();
        self.prepared_direct_insert_text_scratch
            .borrow_mut()
            .clear();
        self.prepared_direct_insert_cell_scratch
            .borrow_mut()
            .clear();
        self.prepared_direct_update_row_scratch.borrow_mut().clear();
    }

    fn reset_statement_lookaside(&self) {
        self.note_statement_lookaside_reset();
        self.statement_parse_scratch.borrow_mut().reset();
        self.reset_prepared_direct_insert_statement_scratch();
    }

    fn reset_transaction_lookaside(&self) {
        self.reset_statement_lookaside();
    }

    fn note_function_registry_changed(&self) {
        self.function_registry_generation
            .set(self.function_registry_generation.get().wrapping_add(1));
        self.clear_compilation_reuse_caches();
    }

    fn with_compiled_cache_bypass<T>(&self, f: impl FnOnce() -> Result<T>) -> Result<T> {
        let previous = self.bypass_compiled_cache.replace(true);
        let result = f();
        self.bypass_compiled_cache.set(previous);
        result
    }

    fn with_statement_memdb_refresh_bypass<T>(&self, f: impl FnOnce() -> Result<T>) -> Result<T> {
        let previous = self.skip_statement_memdb_refresh.replace(true);
        let result = f();
        self.skip_statement_memdb_refresh.set(previous);
        result
    }

    /// Commit epoch used for prepared-template cache identity, both on insert
    /// and on lookup.
    ///
    /// When a retained (deferred-finalization) autocommit transaction is pending
    /// on this connection, the finalized `stable_commit_seq` floor has not yet
    /// advanced to cover that write even though the template was compiled
    /// against its (already MemDB-visible) row image. `next_commit_seq` is the
    /// sequence the retained commit will eventually claim, so folding it in via
    /// `max` keeps insert and lookup observing the *same* epoch while the
    /// retained transaction is still pending — without it the insert recorded a
    /// higher epoch (`next`) than the immediate lookup compared against
    /// (`stable`), so every freshly inserted template missed and was evicted on
    /// the very next lookup. Computing the epoch identically on both paths is
    /// what makes the entry reusable; a cross-connection commit still raises
    /// `stable_commit_seq` past this value, so the bd-#70 stale-read wedge keeps
    /// invalidating non-direct-DML plans.
    fn prepared_cache_commit_epoch(&self) -> u64 {
        let stable = self.current_global_commit_seq().get();
        if self.retained_autocommit_txn.borrow().is_some() {
            stable.max(self.next_commit_seq.load(AtomicOrdering::Acquire))
        } else {
            stable
        }
    }

    fn lookup_prepared_cache(&self, key: u64, sql: &str) -> Option<Arc<PreparedCacheEntry>> {
        let schema_cookie = self.schema_cookie();
        let schema_generation = self.schema_generation();
        let function_registry_generation = self.function_registry_generation();
        let current_commit_epoch = self.prepared_cache_commit_epoch();
        let mut cache = self.prepared_cache.borrow_mut();
        let entry = cache.get(&key)?;
        if entry.sql == sql
            && entry.template.matches_cache_identity(
                schema_cookie,
                schema_generation,
                function_registry_generation,
                current_commit_epoch,
            )
        {
            Some(Arc::clone(entry))
        } else {
            cache.pop(&key);
            None
        }
    }

    #[allow(clippy::arc_with_non_send_sync)] // cache is per-connection (RefCell)
    fn insert_prepared_cache(
        &self,
        key: u64,
        sql: &str,
        stmt: &PreparedStatement<'_>,
    ) -> Arc<PreparedCacheEntry> {
        // bd-#70 plan-cache epoch wedge: snapshot the current finalized commit
        // epoch so cross-connection commits invalidate the template at the next
        // lookup (see `matches_cache_identity`). The retained-autocommit fold is
        // applied identically here and in `lookup_prepared_cache` via
        // `prepared_cache_commit_epoch`, so a freshly inserted template hits on
        // its very next lookup while a retained write is still pending.
        let commit_epoch = self.prepared_cache_commit_epoch();
        let mut cache = self.prepared_cache.borrow_mut();
        let entry = Arc::new(PreparedCacheEntry {
            sql: sql.to_owned(),
            template: PreparedStatementTemplate::from_statement(stmt, commit_epoch),
        });
        cache.put(key, Arc::clone(&entry));
        entry
    }

    // ── bd-1dp9.6.7.2.2: Schema-scoped compiled cache ─────────────────

    /// Look up a cached compiled VdbeProgram by SQL hash.
    fn lookup_compiled_cache(&self, key: u64, sql: &str) -> Option<Arc<CompiledCacheEntry>> {
        let mut cache = self.compiled_cache.borrow_mut();
        let entry = cache.get(&key)?;
        if entry.sql == sql {
            Some(Arc::clone(entry))
        } else {
            None
        }
    }

    /// Remove a cached compiled program by SQL text, if present.
    #[allow(dead_code)]
    fn invalidate_compiled_cache(&self, sql: &str) {
        let key = Self::sql_hash(sql);
        let mut cache = self.compiled_cache.borrow_mut();
        let compiled_removed = cache.peek(&key).is_some_and(|e| e.sql == sql);
        if compiled_removed {
            cache.pop(&key);
        }
        drop(cache);

        let mut prepared_cache = self.prepared_cache.borrow_mut();
        let prepared_keys = prepared_cache
            .iter()
            .filter(|(_, entry)| entry.sql == sql)
            .map(|(cache_key, _)| *cache_key)
            .collect::<Vec<_>>();
        let prepared_removed = !prepared_keys.is_empty();
        for cache_key in prepared_keys {
            prepared_cache.pop(&cache_key);
        }
        drop(prepared_cache);
        let mut planner_cache = self.planner_directive_cache.borrow_mut();
        let planner_removed = planner_cache.iter().any(|(_, entry)| entry.sql == sql);
        if planner_removed {
            planner_cache
                .iter()
                .map(|(cache_key, entry)| (*cache_key, entry.sql.clone()))
                .filter(|(_, cached_sql)| cached_sql == sql)
                .map(|(cache_key, _)| cache_key)
                .collect::<Vec<_>>()
                .into_iter()
                .for_each(|cache_key| {
                    planner_cache.pop(&cache_key);
                });
        }
        if compiled_removed || prepared_removed || planner_removed {
            self.log_statement_reuse_event(
                "compiled",
                sql,
                false,
                "explicit_invalidate",
                0,
                0,
                "none",
            );
        }
    }

    /// Store a compiled VdbeProgram in the schema-scoped cache.
    fn insert_compiled_cache(
        &self,
        key: u64,
        sql: &str,
        program: VdbeProgram,
    ) -> Arc<CompiledCacheEntry> {
        let mut cache = self.compiled_cache.borrow_mut();
        let entry = Arc::new(CompiledCacheEntry {
            sql: sql.to_owned(),
            program: Arc::new(program),
        });
        cache.put(key, Arc::clone(&entry));
        entry
    }

    /// Compile a statement, using the compiled cache when possible.
    /// The `sql_key` is the hash of the canonical SQL text; `sql` is the
    /// canonical SQL text for collision safety.
    fn compile_with_cache(
        &self,
        sql_key: u64,
        sql: &str,
        compile_fn: impl FnOnce(&Self) -> Result<VdbeProgram>,
    ) -> Result<Arc<VdbeProgram>> {
        let profile_enabled = hot_path_profile_enabled();
        if self.bypass_compiled_cache.get() {
            if profile_enabled {
                FSQLITE_COMPILED_CACHE_MISSES.fetch_add(1, AtomicOrdering::Relaxed);
            }
            let start = Instant::now();
            let program = match compile_fn(self) {
                Ok(program) => program,
                Err(error) => {
                    let compile_ns = u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX);
                    let failure_diag = error.to_string();
                    self.log_statement_reuse_event(
                        "compiled",
                        sql,
                        false,
                        "cache_bypass_compile_error",
                        compile_ns,
                        0,
                        failure_diag.as_str(),
                    );
                    return Err(error);
                }
            };
            let compile_ns = u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX);
            if profile_enabled {
                FSQLITE_COMPILE_TIME_NS.fetch_add(compile_ns, AtomicOrdering::Relaxed);
            }
            self.log_statement_reuse_event(
                "compiled",
                sql,
                false,
                "cache_bypass",
                compile_ns,
                0,
                "none",
            );
            return Ok(Arc::new(program));
        }
        if let Some(cached) = self.lookup_compiled_cache(sql_key, sql) {
            if profile_enabled {
                FSQLITE_COMPILED_CACHE_HITS.fetch_add(1, AtomicOrdering::Relaxed);
                // bd-db300.6.1.2: Track warmed-hit (cache hit).
                FSQLITE_STATEMENT_WARMED_HIT_COUNT.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.log_statement_reuse_event("compiled", sql, true, "none", 0, 0, "none");
            return Ok(Arc::clone(&cached.program));
        }
        if profile_enabled {
            FSQLITE_COMPILED_CACHE_MISSES.fetch_add(1, AtomicOrdering::Relaxed);
            // bd-db300.6.1.2: Track first-hit (cache miss requiring compile).
            FSQLITE_STATEMENT_FIRST_HIT_COUNT.fetch_add(1, AtomicOrdering::Relaxed);
        }
        let start = Instant::now();
        // bd-5310l: the compiled-program cache is active and now keys this SQL, so the separate
        // planner-directive cache is redundant on this path — signal `compile_table_select` to
        // bypass it. (Not set on the `bypass_compiled_cache` path above, where the planner cache is
        // the only reuse.)
        let program = {
            let _fronted = ProgramCacheFrontedGuard::enter();
            compile_fn(self)
        };
        let program = match program {
            Ok(program) => program,
            Err(error) => {
                let compile_ns = u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX);
                let failure_diag = error.to_string();
                self.log_statement_reuse_event(
                    "compiled",
                    sql,
                    false,
                    "compile_error",
                    compile_ns,
                    0,
                    failure_diag.as_str(),
                );
                return Err(error);
            }
        };
        let compile_ns = u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX);
        if profile_enabled {
            FSQLITE_COMPILE_TIME_NS.fetch_add(compile_ns, AtomicOrdering::Relaxed);
            // bd-db300.6.1.2: Track first-hit time (compile time is the dominant cost).
            FSQLITE_STATEMENT_FIRST_HIT_TIME_NS.fetch_add(compile_ns, AtomicOrdering::Relaxed);
        }
        self.log_statement_reuse_event("compiled", sql, false, "none", compile_ns, 0, "none");
        let entry = self.insert_compiled_cache(sql_key, sql, program);
        Ok(Arc::clone(&entry.program))
    }

    // ── Internal helpers ──────────────────────────────────────────────────

    fn next_internal_savepoint_name(&self, purpose: &str) -> String {
        let mut suffix = 0_u64;
        loop {
            let candidate = format!("__fsqlite_stmt_{purpose}_{}_{}", next_trace_id(), suffix);
            let conflicts = self
                .savepoints
                .borrow()
                .iter()
                .any(|savepoint| savepoint.name.eq_ignore_ascii_case(&candidate));
            if !conflicts {
                return candidate;
            }
            suffix = suffix.saturating_add(1);
        }
    }

    fn maybe_rollback_transaction_for_conflict_action(
        &self,
        rollback_on_constraint_violation: bool,
        was_auto: bool,
        error: &FrankenError,
    ) -> Result<()> {
        if !rollback_on_constraint_violation
            || was_auto
            || !error_triggers_conflict_action_rollback(error)
        {
            return Ok(());
        }
        if !self.in_transaction.get() && self.active_txn.borrow().is_none() {
            return Ok(());
        }
        let rollback_stmt = fsqlite_ast::RollbackStatement { to_savepoint: None };
        self.execute_rollback(&rollback_stmt)
    }

    #[cfg(test)]
    fn with_internal_statement_savepoint<T>(
        &self,
        purpose: &str,
        body: impl FnOnce() -> Result<T>,
    ) -> Result<T> {
        let cx = self.op_cx()?;
        self.with_internal_statement_savepoint_and_cx(&cx, purpose, body)
    }

    #[cfg(test)]
    fn with_internal_statement_savepoint_and_cx<T>(
        &self,
        cx: &Cx,
        purpose: &str,
        body: impl FnOnce() -> Result<T>,
    ) -> Result<T> {
        self.with_internal_statement_savepoint_and_cx_policy(cx, purpose, false, body)
    }

    /// Execute one logical statement behind an internal savepoint while
    /// honoring SQLite's conflict-algorithm distinction between row-local
    /// `FAIL` and statement-aborting errors.
    ///
    /// `OR FAIL` keeps rows completed before an ordinary uniqueness/NOT NULL/
    /// CHECK failure. Foreign-key violations are different: SQLite always
    /// treats them as `ABORT`, even when the DML spells `OR FAIL`, so they must
    /// roll back to this statement boundary.
    fn with_internal_statement_savepoint_and_cx_policy<T>(
        &self,
        cx: &Cx,
        purpose: &str,
        preserve_constraint_failure_rows: bool,
        body: impl FnOnce() -> Result<T>,
    ) -> Result<T> {
        // Pending direct-write runs belong to already-successful statements.
        // Flush them before this statement's savepoint so a rollback of `body`
        // cannot undo earlier statement effects.
        self.flush_pending_direct_write_runs(cx)?;
        let savepoint_name = self.next_internal_savepoint_name(purpose);
        let snapshot = self.snapshot();
        self.internal_statement_savepoint_depth.set(
            self.internal_statement_savepoint_depth
                .get()
                .saturating_add(1),
        );
        let _depth_guard = StatementSavepointDepthGuard {
            depth: &self.internal_statement_savepoint_depth,
        };

        if let Some(txn) = self.active_txn.borrow_mut().as_mut() {
            txn.savepoint(cx, &savepoint_name)?;
        }

        let concurrent_snapshot = if self.concurrent_txn.get() {
            let concurrent_result = (|| -> Result<Option<ConcurrentSavepoint>> {
                let session_id = self.concurrent_session_id.borrow().ok_or_else(|| {
                    FrankenError::Internal(
                        "concurrent transaction active but no session ID".to_owned(),
                    )
                })?;
                let registry = lock_unpoisoned(&self.concurrent_registry);
                let handle = registry.get(session_id).ok_or_else(|| {
                    FrankenError::Internal("concurrent session handle not found".to_owned())
                })?;
                let snapshot = concurrent_savepoint(&handle, &savepoint_name).map_err(|e| {
                    FrankenError::Internal(format!("concurrent savepoint failed: {e}"))
                })?;
                Ok(Some(snapshot))
            })();
            match concurrent_result {
                Ok(snapshot) => snapshot,
                Err(error) => {
                    let cleanup_errors =
                        self.cleanup_failed_savepoint_setup(cx, &savepoint_name, None);
                    if !cleanup_errors.is_empty() {
                        return Err(FrankenError::Internal(format!(
                            "statement savepoint setup failed after {purpose}: {error}; cleanup failed: {}",
                            cleanup_errors.join("; ")
                        )));
                    }
                    return Err(error);
                }
            }
        } else {
            None
        };
        let live_vtab_level = self.current_live_vtab_savepoint_level()?;
        if let Err(error) = self.live_vtab_savepoint_all(cx, live_vtab_level) {
            let cleanup_errors = self.cleanup_failed_savepoint_setup(
                cx,
                &savepoint_name,
                concurrent_snapshot.as_ref(),
            );
            if !cleanup_errors.is_empty() {
                return Err(FrankenError::Internal(format!(
                    "statement savepoint setup failed after {purpose}: {error}; cleanup failed: {}",
                    cleanup_errors.join("; ")
                )));
            }
            return Err(error);
        }

        match body() {
            Ok(value) => {
                if let Some(txn) = self.active_txn.borrow_mut().as_mut() {
                    txn.release_savepoint(cx, &savepoint_name)?;
                }
                self.live_vtab_release_all(cx, live_vtab_level)?;
                Ok(value)
            }
            Err(statement_error) => {
                // RAISE(FAIL), and ordinary constraint failures under an
                // explicit OR FAIL policy, keep rows completed before the
                // failure. Foreign-key violations are deliberately excluded
                // by `error_preserves_prior_statement_rows`.
                if error_preserves_prior_statement_rows(
                    preserve_constraint_failure_rows,
                    &statement_error,
                ) {
                    if let Some(txn) = self.active_txn.borrow_mut().as_mut() {
                        txn.release_savepoint(cx, &savepoint_name)?;
                    }
                    self.live_vtab_release_all(cx, live_vtab_level)?;
                    return Err(statement_error);
                }

                // Full ROLLBACK can clear the transaction underneath us
                // (for example via trigger RAISE(ROLLBACK)). In that case,
                // the outer rollback has already restored connection state.
                if self.active_txn.borrow().is_none() {
                    return Err(statement_error);
                }

                let mut cleanup_errors = Vec::new();
                let mut pager_rollback_succeeded = false;
                let mut concurrent_rollback_succeeded = true;
                if let Some(concurrent_snap) = concurrent_snapshot.as_ref() {
                    if let Some(session_id) = *self.concurrent_session_id.borrow() {
                        let registry = lock_unpoisoned(&self.concurrent_registry);
                        if let Some(mut handle) = registry.get_mut(session_id) {
                            if let Err(err) = concurrent_rollback_to_savepoint(
                                &mut handle,
                                &self.concurrent_lock_table,
                                session_id,
                                concurrent_snap,
                            ) {
                                concurrent_rollback_succeeded = false;
                                cleanup_errors.push(format!(
                                    "concurrent rollback_to_savepoint('{savepoint_name}') failed: {err}"
                                ));
                            }
                            if concurrent_rollback_succeeded {
                                self.clear_memory_concurrent_synced_write_roots();
                            }
                        } else {
                            concurrent_rollback_succeeded = false;
                            cleanup_errors.push(format!(
                                "concurrent session {session_id} missing during rollback"
                            ));
                        }
                    } else {
                        concurrent_rollback_succeeded = false;
                        cleanup_errors.push(
                            "concurrent transaction active but no session ID during rollback"
                                .to_owned(),
                        );
                    }
                }

                if concurrent_rollback_succeeded
                    && let Some(txn) = self.active_txn.borrow_mut().as_mut()
                {
                    match txn.rollback_to_savepoint(cx, &savepoint_name) {
                        Ok(()) => {
                            pager_rollback_succeeded = true;
                            if let Err(err) = txn.release_savepoint(cx, &savepoint_name) {
                                cleanup_errors.push(format!(
                                    "pager release_savepoint('{savepoint_name}') failed: {err}"
                                ));
                            }
                        }
                        Err(err) => cleanup_errors.push(format!(
                            "pager rollback_to_savepoint('{savepoint_name}') failed: {err}"
                        )),
                    }
                }

                if concurrent_rollback_succeeded && pager_rollback_succeeded {
                    match self.live_vtab_rollback_to_all(cx, live_vtab_level) {
                        Ok(()) => {
                            if let Err(err) = self.live_vtab_release_all(cx, live_vtab_level) {
                                cleanup_errors.push(format!(
                                    "virtual-table release({live_vtab_level}) failed: {err}"
                                ));
                            }
                        }
                        Err(err) => {
                            cleanup_errors.push(format!(
                                "virtual-table rollback_to({live_vtab_level}) failed: {err}"
                            ));
                        }
                    }
                }

                if pager_rollback_succeeded {
                    self.txn_metrics_note_rollback();
                    self.clear_prepared_direct_insert_append_hint();
                    // Rollback invalidates every cursor position established
                    // against the discarded statement image. Reopen storage
                    // cursors on the next statement.
                    self.discard_cached_vdbe_engine();
                    self.restore_snapshot(cx, &snapshot)?;
                }

                if !cleanup_errors.is_empty() {
                    return Err(FrankenError::Internal(format!(
                        "statement savepoint rollback failed after {purpose}: {statement_error}; cleanup failed: {}",
                        cleanup_errors.join("; ")
                    )));
                }

                Err(statement_error)
            }
        }
    }

    fn retained_autocommit_batch_active(&self) -> bool {
        self.retained_autocommit_stmt_count.get() > 0
    }

    fn clear_retained_autocommit_count_sum_cache(&self) {
        self.retained_autocommit_count_sum_cache.borrow_mut().take();
        self.retained_autocommit_count_sum_cache_preserve_next_write
            .set(false);
    }

    fn clear_retained_autocommit_count_sum_cache_for_root(&self, root_page: i32) {
        let cleared = {
            let mut cache_slot = self.retained_autocommit_count_sum_cache.borrow_mut();
            let should_clear = cache_slot
                .as_ref()
                .is_some_and(|cache| cache.root_page == root_page);
            if should_clear {
                cache_slot.take();
            }
            should_clear
        };
        if cleared {
            self.retained_autocommit_count_sum_cache_preserve_next_write
                .set(false);
        }
    }

    fn clear_retained_autocommit_indexed_equality_cache(&self) {
        self.retained_autocommit_indexed_equality_cache
            .borrow_mut()
            .take();
    }

    fn retained_autocommit_indexed_equality_cache_rows(
        &self,
        root_page: i32,
        column_index: usize,
        probe_value: &SqliteValue,
        rowid_alias_column_index: Option<usize>,
        projections: Option<&[PreparedMemValueSource]>,
    ) -> Option<Vec<Row>> {
        self.retained_autocommit_indexed_equality_cache
            .borrow()
            .as_ref()
            .filter(|cache| {
                cache.matches(
                    root_page,
                    column_index,
                    probe_value,
                    rowid_alias_column_index,
                    projections,
                )
            })
            .map(|cache| cache.rows.clone())
    }

    fn store_retained_autocommit_indexed_equality_cache(
        &self,
        root_page: i32,
        column_index: usize,
        probe_value: &SqliteValue,
        rowid_alias_column_index: Option<usize>,
        projections: Option<&[PreparedMemValueSource]>,
        rows: &[Row],
    ) {
        *self.retained_autocommit_indexed_equality_cache.borrow_mut() =
            Some(RetainedAutocommitIndexedEqualityCache {
                root_page,
                column_index,
                probe_value: probe_value.clone(),
                rowid_alias_column_index,
                projections: projections.map(Arc::from),
                rows: rows.to_vec(),
            });
    }

    fn remember_retained_autocommit_count_sum_interest(
        &self,
        root_page: i32,
        sum_column_index: usize,
        rowid_alias_column_index: Option<usize>,
    ) {
        if !self.pager.is_memory() {
            return;
        }
        *self.retained_autocommit_count_sum_interest.borrow_mut() =
            Some(RetainedAutocommitCountSumInterest {
                root_page,
                sum_column_index,
                rowid_alias_column_index,
                schema_cookie: self.schema_cookie(),
                schema_generation: self.schema_generation(),
            });
    }

    fn finish_retained_autocommit_count_sum_cache_flush(&self, commit_succeeded: bool) {
        if commit_succeeded && self.pager.is_memory() {
            self.retained_autocommit_count_sum_cache_preserve_next_write
                .set(false);
        } else {
            self.clear_retained_autocommit_count_sum_cache();
        }
    }

    fn retained_autocommit_count_sum_cache_row(
        &self,
        root_page: i32,
        sum_column_index: usize,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<Row> {
        self.retained_autocommit_count_sum_cache
            .borrow()
            .as_ref()
            .filter(|cache| cache.matches(root_page, sum_column_index, rowid_alias_column_index))
            .map(|cache| cache.row.clone())
    }

    fn store_retained_autocommit_count_sum_cache(
        &self,
        root_page: i32,
        sum_column_index: usize,
        rowid_alias_column_index: Option<usize>,
        sum_non_null_count: i64,
        row: &Row,
    ) {
        *self.retained_autocommit_count_sum_cache.borrow_mut() =
            Some(RetainedAutocommitCountSumCache {
                root_page,
                sum_column_index,
                rowid_alias_column_index,
                sum_non_null_count,
                row: row.clone(),
            });
    }

    fn preserve_retained_autocommit_count_sum_cache_for_noop_write(&self) {
        if self.retained_autocommit_count_sum_cache.borrow().is_some() {
            self.retained_autocommit_count_sum_cache_preserve_next_write
                .set(true);
        }
    }

    fn maybe_seed_retained_autocommit_count_sum_cache_from_clean_memdb(&self, root_page: i32) {
        if !self.pager.is_memory()
            || self.in_transaction.get()
            || !self.memdb_storage_count_shortcuts_safe.get()
            || self.retained_autocommit_stmt_count.get() != 0
            || self.retained_autocommit_count_sum_cache.borrow().is_some()
        {
            return;
        }
        let Some((sum_column_index, rowid_alias_column_index)) = self
            .retained_autocommit_count_sum_interest
            .borrow()
            .as_ref()
            .and_then(|interest| interest.matches_current(self, root_page))
        else {
            return;
        };
        let _ =
            self.prepared_count_star_sum_row(root_page, sum_column_index, rowid_alias_column_index);
    }

    fn retained_autocommit_count_sum_cache_note_insert(
        &self,
        root_page: i32,
        values: &[SqliteValue],
    ) {
        self.maybe_seed_retained_autocommit_count_sum_cache_from_clean_memdb(root_page);
        let mut cache_slot = self.retained_autocommit_count_sum_cache.borrow_mut();
        let Some(cache) = cache_slot.as_mut() else {
            return;
        };
        if cache.root_page != root_page {
            return;
        }
        let Some(sum_value) = values.get(cache.sum_column_index) else {
            drop(cache_slot);
            self.clear_retained_autocommit_count_sum_cache_for_root(root_page);
            return;
        };
        if Self::retained_autocommit_count_sum_cache_apply_insert_delta(
            &mut cache.row,
            &mut cache.sum_non_null_count,
            sum_value,
        ) {
            self.retained_autocommit_count_sum_cache_preserve_next_write
                .set(true);
        } else {
            drop(cache_slot);
            self.clear_retained_autocommit_count_sum_cache_for_root(root_page);
        }
    }

    fn retained_autocommit_count_sum_cache_apply_insert_delta(
        row: &mut Row,
        sum_non_null_count: &mut i64,
        sum_value: &SqliteValue,
    ) -> bool {
        let [count_value, sum_slot] = row.values.as_mut_slice() else {
            return false;
        };
        let SqliteValue::Integer(count) = count_value else {
            return false;
        };
        let Some(next_count) = count.checked_add(1) else {
            return false;
        };

        let (next_sum, non_null_delta) = match (sum_slot.clone(), sum_value) {
            (current, SqliteValue::Null) => (current, 0),
            (SqliteValue::Null, SqliteValue::Integer(n)) => (SqliteValue::Integer(*n), 1),
            (SqliteValue::Integer(current), SqliteValue::Integer(n)) => {
                if let Some(sum) = current.checked_add(*n) {
                    (SqliteValue::Integer(sum), 1)
                } else {
                    return false;
                }
            }
            (SqliteValue::Float(current), SqliteValue::Integer(n)) =>
            {
                #[allow(clippy::cast_precision_loss)]
                (SqliteValue::Float(current + *n as f64), 1)
            }
            (SqliteValue::Null, SqliteValue::Float(n)) => (SqliteValue::Float(*n), 1),
            (SqliteValue::Integer(current), SqliteValue::Float(n)) =>
            {
                #[allow(clippy::cast_precision_loss)]
                (SqliteValue::Float(current as f64 + *n), 1)
            }
            (SqliteValue::Float(current), SqliteValue::Float(n)) => {
                (SqliteValue::Float(current + *n), 1)
            }
            _ => return false,
        };

        let Some(next_non_null_count) = sum_non_null_count.checked_add(non_null_delta) else {
            return false;
        };
        *count_value = SqliteValue::Integer(next_count);
        *sum_non_null_count = next_non_null_count;
        *sum_slot = next_sum;
        true
    }

    fn retained_autocommit_count_sum_cache_project_value(
        &self,
        root_page: i32,
        rowid: i64,
        values: &[SqliteValue],
    ) -> Option<SqliteValue> {
        let cache_slot = self.retained_autocommit_count_sum_cache.borrow();
        let cache = cache_slot.as_ref()?;
        if cache.root_page != root_page {
            return None;
        }
        if cache.rowid_alias_column_index == Some(cache.sum_column_index) {
            Some(SqliteValue::Integer(rowid))
        } else {
            values.get(cache.sum_column_index).cloned()
        }
    }

    fn retained_autocommit_count_sum_cache_tracks_root(&self, root_page: i32) -> bool {
        self.retained_autocommit_count_sum_cache
            .borrow()
            .as_ref()
            .is_some_and(|cache| cache.root_page == root_page)
    }

    fn retained_autocommit_count_sum_cache_note_update(
        &self,
        root_page: i32,
        old_sum_value: Option<SqliteValue>,
        new_sum_value: Option<SqliteValue>,
    ) {
        let mut cache_slot = self.retained_autocommit_count_sum_cache.borrow_mut();
        let Some(cache) = cache_slot.as_mut() else {
            return;
        };
        if cache.root_page != root_page {
            return;
        }
        let (Some(old_sum_value), Some(new_sum_value)) = (old_sum_value, new_sum_value) else {
            drop(cache_slot);
            self.clear_retained_autocommit_count_sum_cache_for_root(root_page);
            return;
        };
        if Self::retained_autocommit_count_sum_cache_apply_update_delta(
            &mut cache.row,
            &mut cache.sum_non_null_count,
            &old_sum_value,
            &new_sum_value,
        ) {
            self.retained_autocommit_count_sum_cache_preserve_next_write
                .set(true);
        } else {
            drop(cache_slot);
            self.clear_retained_autocommit_count_sum_cache_for_root(root_page);
        }
    }

    fn retained_autocommit_count_sum_cache_note_delete(
        &self,
        root_page: i32,
        old_sum_value: Option<SqliteValue>,
    ) {
        let mut cache_slot = self.retained_autocommit_count_sum_cache.borrow_mut();
        let Some(cache) = cache_slot.as_mut() else {
            return;
        };
        if cache.root_page != root_page {
            return;
        }
        let Some(old_sum_value) = old_sum_value else {
            drop(cache_slot);
            self.clear_retained_autocommit_count_sum_cache_for_root(root_page);
            return;
        };
        if Self::retained_autocommit_count_sum_cache_apply_delete_delta(
            &mut cache.row,
            &mut cache.sum_non_null_count,
            &old_sum_value,
        ) {
            self.retained_autocommit_count_sum_cache_preserve_next_write
                .set(true);
        } else {
            drop(cache_slot);
            self.clear_retained_autocommit_count_sum_cache_for_root(root_page);
        }
    }

    fn retained_autocommit_count_sum_cache_integer_value(
        value: &SqliteValue,
    ) -> Option<RetainedCountSumIntegerValue> {
        match value {
            SqliteValue::Null => Some(RetainedCountSumIntegerValue::Null),
            SqliteValue::Integer(n) => Some(RetainedCountSumIntegerValue::Integer(*n)),
            _ => None,
        }
    }

    fn retained_autocommit_count_sum_cache_apply_update_delta(
        row: &mut Row,
        sum_non_null_count: &mut i64,
        old_sum_value: &SqliteValue,
        new_sum_value: &SqliteValue,
    ) -> bool {
        let old_value = match Self::retained_autocommit_count_sum_cache_integer_value(old_sum_value)
        {
            Some(value) => value,
            None => return false,
        };
        let new_value = match Self::retained_autocommit_count_sum_cache_integer_value(new_sum_value)
        {
            Some(value) => value,
            None => return false,
        };
        let [_, sum_slot] = row.values.as_mut_slice() else {
            return false;
        };

        let current_sum = match sum_slot {
            SqliteValue::Null if *sum_non_null_count == 0 => 0,
            SqliteValue::Integer(n) => *n,
            _ => return false,
        };
        let next_non_null_count = *sum_non_null_count + i64::from(new_value.is_non_null())
            - i64::from(old_value.is_non_null());
        if next_non_null_count < 0 {
            return false;
        }

        let old_delta = old_value.unwrap_or_zero();
        let new_delta = new_value.unwrap_or_zero();
        let Some(next_sum) = current_sum
            .checked_sub(old_delta)
            .and_then(|sum| sum.checked_add(new_delta))
        else {
            return false;
        };
        *sum_non_null_count = next_non_null_count;
        *sum_slot = if next_non_null_count == 0 {
            SqliteValue::Null
        } else {
            SqliteValue::Integer(next_sum)
        };
        true
    }

    fn retained_autocommit_count_sum_cache_apply_delete_delta(
        row: &mut Row,
        sum_non_null_count: &mut i64,
        old_sum_value: &SqliteValue,
    ) -> bool {
        let old_value = match Self::retained_autocommit_count_sum_cache_integer_value(old_sum_value)
        {
            Some(value) => value,
            None => return false,
        };
        let [count_value, sum_slot] = row.values.as_mut_slice() else {
            return false;
        };
        let SqliteValue::Integer(count) = count_value else {
            return false;
        };
        let Some(next_count) = count.checked_sub(1) else {
            return false;
        };
        let current_sum = match sum_slot {
            SqliteValue::Null if *sum_non_null_count == 0 => 0,
            SqliteValue::Integer(n) => *n,
            _ => return false,
        };
        let next_non_null_count = *sum_non_null_count - i64::from(old_value.is_non_null());
        if next_non_null_count < 0 {
            return false;
        }

        let Some(next_sum) = current_sum.checked_sub(old_value.unwrap_or_zero()) else {
            return false;
        };
        *count_value = SqliteValue::Integer(next_count);
        *sum_non_null_count = next_non_null_count;
        *sum_slot = if next_non_null_count == 0 {
            SqliteValue::Null
        } else {
            SqliteValue::Integer(next_sum)
        };
        true
    }

    fn should_use_statement_savepoint(
        &self,
        was_auto: bool,
        _preserve_prior_changes_on_constraint_violation: bool,
    ) -> bool {
        self.active_txn_is_open_or_borrowed()
            && self.internal_statement_savepoint_depth.get() == 0
            && (!was_auto || self.retained_autocommit_batch_active())
    }

    /// Execute a parsed statement, handling both DDL (CREATE TABLE) and
    /// DML (SELECT/INSERT/UPDATE/DELETE).
    #[allow(clippy::too_many_lines)]
    fn execute_statement(
        &self,
        statement: &Statement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        if hot_path_profile_enabled() {
            FSQLITE_STATEMENT_DISPATCH_BACKGROUND_GATES.fetch_add(1, AtomicOrdering::Relaxed);
        }
        self.background_status()?;
        self.execute_statement_after_background_status(statement, params)
    }

    fn execute_statement_after_background_status(
        &self,
        statement: &Statement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        self.execute_statement_impl_after_background_status(statement, params, None)
    }

    #[allow(clippy::too_many_lines)]
    fn execute_statement_impl_after_background_status(
        &self,
        statement: &Statement,
        params: Option<&[SqliteValue]>,
        precompiled: Option<&VdbeProgram>,
    ) -> Result<Vec<Row>> {
        let _record_profile_scope = enter_record_profile_scope(RecordProfileScope::CoreConnection);
        self.clear_table_program_error_state();
        self.sync_change_tracking_context();
        self.validate_statement_compound_select_arity(statement)?;
        let statement_kind = match &statement {
            Statement::Select(_) => "select",
            Statement::Insert(_) => "insert",
            Statement::Update(_) => "update",
            Statement::Delete(_) => "delete",
            Statement::CreateTable(_) => "create_table",
            Statement::CreateVirtualTable(_) => "create_virtual_table",
            Statement::Drop(_) => "drop",
            Statement::AlterTable(_) => "alter_table",
            Statement::CreateIndex(_) => "create_index",
            Statement::Pragma(_) => "pragma",
            Statement::Begin(_) => "begin",
            Statement::Commit => "commit",
            Statement::Rollback(_) => "rollback",
            Statement::Savepoint(_) => "savepoint",
            Statement::Release(_) => "release",
            Statement::CreateView(_) => "create_view",
            Statement::CreateTrigger(_) => "create_trigger",
            Statement::Explain { .. } => "explain",
            _ => "other",
        };
        let statement_trace_enabled =
            tracing::enabled!(target: "fsqlite.statement", tracing::Level::DEBUG);
        let parse_trace_enabled = tracing::enabled!(target: "fsqlite.parse", tracing::Level::TRACE);
        let trace_id = (statement_trace_enabled || parse_trace_enabled)
            .then(next_trace_id)
            .unwrap_or(0);
        let decision_id = statement_trace_enabled.then(next_decision_id).unwrap_or(0);
        let trace_registration = self.trace_registration.borrow().clone();
        let compat_trace_stmt_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::STMT));
        let compat_trace_profile_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::PROFILE));
        let compat_trace_row_enabled = trace_registration
            .as_ref()
            .is_some_and(|trace| trace.mask.contains(TraceMask::ROW));
        let statement_sql = (compat_trace_stmt_enabled || compat_trace_profile_enabled)
            .then(|| statement.to_string());
        let statement_reuse_enabled =
            tracing::enabled!(target: "fsqlite.statement_reuse", tracing::Level::INFO);
        let statement_reuse_sql = statement_reuse_enabled.then(|| {
            statement_sql
                .clone()
                .unwrap_or_else(|| statement.to_string())
        });
        let statement_span = statement_trace_enabled.then(|| {
            let span = tracing::span!(
                target: "fsqlite.statement",
                tracing::Level::DEBUG,
                "statement",
                trace_id,
                decision_id,
                statement_kind
            );
            record_trace_span_created();
            span
        });
        let _statement_guard = statement_span.as_ref().map(tracing::Span::enter);
        if compat_trace_stmt_enabled {
            emit_compat_trace_event(
                trace_registration.as_ref(),
                TraceEvent::Statement {
                    sql: statement_sql.clone().unwrap_or_default(),
                },
            );
        }
        let execution_started = (statement_reuse_enabled || compat_trace_profile_enabled)
            .then(fsqlite_types::sync_primitives::Instant::now);
        let derived_storage_log_select = match statement {
            Statement::Select(select) if flatten_simple_from_subquery_select(select).is_some() => {
                Some(select.clone())
            }
            _ => None,
        };
        let statement = {
            let parse_span = parse_trace_enabled.then(|| {
                let span = tracing::span!(
                    target: "fsqlite.parse",
                    tracing::Level::TRACE,
                    "parse",
                    trace_id,
                    statement_kind,
                    phase = "rewrite_subquery"
                );
                record_trace_span_created();
                span
            });
            let _parse_guard = parse_span.as_ref().map(tracing::Span::enter);
            self.rewrite_subquery_statement(statement, params)?
        };
        // 5B.5 + 5B.2 (bd-1yi8): autocommit wrapping — ensure a pager
        // transaction is active for data/DDL operations outside an
        // explicit BEGIN.  Writes use Immediate mode; reads use Deferred.
        // Transaction-control statements manage their own transactions.
        let is_write = matches!(
            statement.as_ref(),
            Statement::Insert(_)
                | Statement::Update(_)
                | Statement::Delete(_)
                | Statement::CreateTable(_)
                | Statement::CreateVirtualTable(_)
                | Statement::CreateView(_)
                | Statement::CreateTrigger(_)
                | Statement::Drop(_)
                | Statement::AlterTable(_)
                | Statement::CreateIndex(_)
                | Statement::Analyze(_)
                | Statement::Reindex(_)
        );
        // Issue #110: any statement that may delete or alter a parent row
        // invalidates a cached "parent present" result. Plain INSERTs only add
        // rows (safe), but UPDATE/DELETE, DDL, and INSERT OR REPLACE / upsert
        // (which can delete or mutate an existing — possibly parent — row)
        // must drop the transaction-scoped FK parent-validation cache. The
        // prepared UPDATE/DELETE fast lanes bypass this dispatcher and clear
        // the cache at their own entry point.
        if Self::statement_may_invalidate_fk_parent_cache(statement.as_ref()) {
            self.clear_fk_parent_validation_cache();
        }
        let is_txn_control = matches!(
            statement.as_ref(),
            Statement::Begin(_)
                | Statement::Commit
                | Statement::Rollback(_)
                | Statement::Savepoint(_)
                | Statement::Release(_)
                // VACUUM INTO needs the pager quiescent, so it cannot run
                // inside the implicit autocommit read transaction used for
                // ordinary statement dispatch.
                | Statement::Vacuum(_)
                // PRAGMA handlers that need pager access (for example
                // `PRAGMA wal_checkpoint`) manage their own pager operations.
                | Statement::Pragma(_)
        );
        let capture_time_travel_snapshot = !matches!(
            statement.as_ref(),
            Statement::Insert(_) | Statement::Update(_) | Statement::Delete(_)
        );
        let op_cx = self.op_cx_after_background_status();
        let should_refresh_active_txn_memdb = !self.skip_statement_memdb_refresh.get()
            && (self.memdb_requires_active_txn_reload.get()
                || !self.pending_memdb_direct_upserts.borrow().is_empty())
            && !matches!(statement.as_ref(), Statement::Commit)
            && !matches!(statement.as_ref(), Statement::Rollback(_));
        let writable_schema_dml = self.statement_is_writable_schema_dml(statement.as_ref());
        let schema_change_boundary =
            statement_starts_fresh_schema_change_boundary(statement.as_ref())
                || writable_schema_dml;
        if self.pragma_state.borrow().query_only
            && (statement_writes_under_query_only(statement.as_ref()) || writable_schema_dml)
        {
            return Err(FrankenError::ReadOnly);
        }
        // `PRAGMA writable_schema` DML edits page-1 schema rows directly and
        // may be repairing malformed rows. Do not refresh the normal MemDB
        // schema image before the raw edit has had a chance to run.
        if should_refresh_active_txn_memdb && !writable_schema_dml {
            self.refresh_memdb_from_active_txn_if_dirty(&op_cx)?;
        }
        if !self.skip_statement_memdb_refresh.get() && !is_txn_control && !is_write {
            self.refresh_memdb_from_cached_write_txn_if_stale(&op_cx)?;
        }
        if !self.skip_statement_memdb_refresh.get()
            && schema_change_boundary
            && self.cached_write_txn.borrow().is_some()
        {
            self.invalidate_cached_write_txn(&op_cx);
        }
        let retained_boundary_flush_required = self.retained_autocommit_txn.borrow().is_some()
            && (schema_change_boundary
                || matches!(
                    statement.as_ref(),
                    Statement::Pragma(_)
                        | Statement::Vacuum(_)
                        | Statement::Attach(_)
                        | Statement::Detach(_)
                ));
        if retained_boundary_flush_required {
            // Schema/pager boundaries must not reuse a parked retained
            // autocommit batch because they need a fresh durable view.
            self.flush_retained_autocommit_txn(&op_cx)?;
        }
        // bd-otbu1 / I1: Flush retained autocommit if read touches dirty tables.
        // This preserves read-after-write semantics for any retained batch.
        if !is_txn_control
            && !is_write
            && self.retained_autocommit_txn.borrow().is_some()
            && matches!(statement.as_ref(), Statement::Select(select) if {
                // Extract table names from the SELECT's FROM clause.
                let read_tables = Self::extract_table_names_from_select(select);
                self.retained_autocommit_has_dirty_overlap(&read_tables)
            })
        {
            self.flush_retained_autocommit_txn_for_read(&op_cx)?;
        }
        let was_auto = if is_txn_control {
            false // transaction-control manages its own transactions
        } else if is_write {
            self.ensure_autocommit_txn_with_cx(&op_cx)?
        } else {
            self.ensure_autocommit_txn_mode_with_cx(TransactionMode::ReadOnly, &op_cx, None)?
        };
        if !self.skip_statement_memdb_refresh.get()
            && !writable_schema_dml
            && schema_change_boundary
            && (self.memdb_requires_active_txn_reload.get()
                || !self.pending_memdb_direct_upserts.borrow().is_empty()
                || !self.memdb_rows_loaded.get())
        {
            self.refresh_memdb_from_active_txn_if_dirty(&op_cx)?;
        }
        let previous_total_changes = self.total_changes.get();
        let previous_last_insert_rowid = self.current_last_insert_rowid();
        if !is_txn_control {
            if is_write {
                self.txn_metrics_note_write();
            } else if matches!(statement.as_ref(), Statement::Select(_)) {
                self.txn_metrics_note_read();
                // bd-m1nte / I2: Track reads during an active retained batch
                // to detect mixed workloads and lower the flush threshold.
                if self.retained_autocommit_batch_active() {
                    self.retained_autocommit_note_read();
                }
            }
        }
        let preserve_prior_changes_on_constraint_violation =
            statement_preserves_prior_changes_on_constraint(statement.as_ref());
        let use_statement_savepoint = self.should_use_statement_savepoint(
            was_auto,
            preserve_prior_changes_on_constraint_violation,
        ) && matches!(
            statement.as_ref(),
            Statement::Insert(_)
                | Statement::Update(_)
                | Statement::Delete(_)
                | Statement::CreateIndex(_)
                | Statement::Reindex(_)
        );
        let rollback_on_constraint_violation =
            statement_rolls_back_transaction_on_constraint(statement.as_ref());
        let execute_body_start = hot_path_profile_enabled().then(Instant::now);
        let result = if use_statement_savepoint {
            self.with_internal_statement_savepoint_and_cx_policy(
                &op_cx,
                statement_kind,
                preserve_prior_changes_on_constraint_violation,
                || {
                    self.execute_statement_dispatch_impl(
                        &op_cx,
                        statement.as_ref(),
                        params,
                        precompiled,
                        derived_storage_log_select.as_ref(),
                    )
                },
            )
        } else {
            self.execute_statement_dispatch_impl(
                &op_cx,
                statement.as_ref(),
                params,
                precompiled,
                derived_storage_log_select.as_ref(),
            )
        };
        record_hot_path_duration(&FSQLITE_EXECUTE_BODY_TIME_NS, execute_body_start);
        let result = match result {
            Ok(rows) => Ok(rows),
            Err(error) => {
                if matches!(
                    statement.as_ref(),
                    Statement::Insert(_) | Statement::Update(_) | Statement::Delete(_)
                ) {
                    self.restore_failed_statement_tracking(
                        preserve_prior_changes_on_constraint_violation,
                        &error,
                        previous_total_changes,
                        previous_last_insert_rowid,
                    );
                }
                match self.maybe_rollback_transaction_for_conflict_action(
                    rollback_on_constraint_violation,
                    was_auto,
                    &error,
                ) {
                    Ok(()) => Err(error),
                    Err(rollback_error) => Err(rollback_error),
                }
            }
        };
        let commit_autocommit_on_error = was_auto
            && matches!(
                result.as_ref(),
                Err(error) if error_preserves_prior_statement_rows(
                    preserve_prior_changes_on_constraint_violation,
                    error,
                )
            );
        let ok = result.is_ok() || commit_autocommit_on_error;
        let dirty_table_name = if is_write {
            Self::extract_written_table_name(statement.as_ref())
        } else {
            None
        };
        // bd-xvv8f: an autocommit DDL statement applies its connection-local
        // schema mutation (and bumps `schema_cookie`) eagerly, before the
        // implicit commit below. If that commit fails — e.g. a concurrent writer
        // wins the first-committer race on the shared sqlite_master page — the
        // statement rolls back, but the eager in-memory mutation survives and the
        // rollback-recovery reload's schema-only fast path can skip repairing it
        // (its `header_cookie == schema_cookie` guard intermittently matches the
        // bumped local cookie). Arm a one-shot full-rebuild so the recovery reload
        // reconstructs the schema from committed state. Scoped to schema-change
        // boundaries so conflicted INSERT/UPDATE/DELETE rollbacks keep the cheap
        // fast-path reload. Cleared on the success path (no recovery reload ran,
        // so nothing consumed it) to avoid forcing an unrelated later reload.
        let armed_full_schema_reload = was_auto && schema_change_boundary;
        if armed_full_schema_reload {
            self.force_full_schema_reload_once.set(true);
        }
        let resolve_result = self.resolve_autocommit_txn_with_dirty_table_and_capture_and_cx(
            was_auto,
            ok,
            dirty_table_name,
            capture_time_travel_snapshot,
            schema_change_boundary,
            &op_cx,
        );
        if armed_full_schema_reload && resolve_result.is_ok() {
            self.force_full_schema_reload_once.set(false);
        }
        resolve_result?;
        if ok && writable_schema_dml {
            let flush_retained = self.retained_autocommit_txn.borrow().is_some();
            if flush_retained {
                self.flush_retained_autocommit_txn(&op_cx)?;
            }
        }
        if statement_reuse_enabled || compat_trace_profile_enabled {
            let elapsed_ns = execution_started
                .map(|started| u64::try_from(started.elapsed().as_nanos()).unwrap_or(u64::MAX))
                .unwrap_or(0);
            if let Some(statement_reuse_sql) = statement_reuse_sql.as_deref() {
                let failure_diag = match result.as_ref() {
                    Ok(_) => Cow::Borrowed("none"),
                    Err(error) => Cow::Owned(error.to_string()),
                };
                self.log_statement_reuse_event(
                    "execution",
                    statement_reuse_sql,
                    precompiled.is_some(),
                    if ok { "none" } else { "execution_error" },
                    0,
                    elapsed_ns,
                    failure_diag.as_ref(),
                );
            }
            if compat_trace_profile_enabled {
                emit_compat_trace_event(
                    trace_registration.as_ref(),
                    TraceEvent::Profile {
                        sql: statement_sql.unwrap_or_default(),
                        elapsed_ns,
                    },
                );
            }
        }
        if compat_trace_row_enabled && let Ok(rows) = result.as_ref() {
            for row in rows {
                emit_compat_trace_event(
                    trace_registration.as_ref(),
                    TraceEvent::Row {
                        values: row.values().to_vec(),
                    },
                );
            }
        }
        result
    }

    /// Inner dispatch for `execute_statement` — separated so that
    /// autocommit wrapping can bracket the entire execution.
    #[allow(clippy::too_many_lines)]
    #[allow(dead_code)]
    fn execute_statement_dispatch(
        &self,
        statement: &Statement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        let op_cx = self.op_cx()?;
        self.execute_statement_dispatch_impl(&op_cx, statement, params, None, None)
    }

    #[allow(clippy::too_many_lines)]
    fn execute_statement_dispatch_impl(
        &self,
        cx: &Cx,
        statement: &Statement,
        params: Option<&[SqliteValue]>,
        precompiled: Option<&VdbeProgram>,
        derived_storage_log_select: Option<&SelectStatement>,
    ) -> Result<Vec<Row>> {
        if let Some(rows) = self.maybe_execute_attached_target_statement(statement, params)? {
            return Ok(rows);
        }
        self.reject_unsupported_attached_target_schema(statement)?;
        // ATTACH/DETACH register or release a *separate* side connection and do
        // not write to the main database file, so a read-only / schema-only main
        // connection must still be allowed to run them — this matches SQLite,
        // which permits `ATTACH`/reads of attached schemas on a `mode=ro` main.
        // (Writability of the attached schema is governed by how the attached
        // connection itself is opened, handled in the ATTACH branch below.)
        if self.pager.is_readonly()
            && matches!(
                statement,
                Statement::Insert(_)
                    | Statement::Update(_)
                    | Statement::Delete(_)
                    | Statement::CreateTable(_)
                    | Statement::CreateVirtualTable(_)
                    | Statement::CreateView(_)
                    | Statement::CreateTrigger(_)
                    | Statement::CreateIndex(_)
                    | Statement::Drop(_)
                    | Statement::AlterTable(_)
                    | Statement::Vacuum(_)
                    | Statement::Analyze(_)
                    | Statement::Reindex(_)
            )
        {
            return Err(FrankenError::ReadOnly);
        }
        if !matches!(statement, Statement::Select(_) | Statement::Pragma(_)) {
            self.clear_prepared_direct_insert_append_hint();
        }
        // INSTEAD OF triggers make a view writable: route INSERT/UPDATE/DELETE on
        // a view with a matching INSTEAD OF trigger to the trigger body instead of
        // normal table DML (which would fail "no such table" — a view has no
        // B-tree). bd-ffkpv.
        if let Some(rows) = self.maybe_execute_instead_of_view_dml(statement, params)? {
            return Ok(rows);
        }
        match statement {
            Statement::CreateTable(create) => {
                self.execute_create_table(create)?;
                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                Ok(Vec::new())
            }
            Statement::CreateVirtualTable(create_virtual) => {
                self.execute_create_virtual_table(create_virtual)?;
                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                Ok(Vec::new())
            }
            Statement::Select(select) => {
                // bd-c9v0f + bd-pw68x: reject out-of-range ORDER BY/GROUP BY
                // ordinals and unknown INDEXED BY hints, matching SQLite.
                self.validate_select_ordinals_and_hints(select)?;
                // bd-fuxgg: reject aggregate-in-WHERE, nested aggregates,
                // aggregate/window in GROUP BY, window in HAVING, and aggregates
                // in a recursive-CTE recursive term, matching SQLite's "misuse"
                // errors (frank was too permissive).
                validate_aggregate_window_misuse(select)?;
                // bd-1zc9p: a constant LIMIT/OFFSET that is not losslessly
                // convertible to an integer (a fractional real, non-numeric
                // text, NULL, or a blob) is a "datatype mismatch" in SQLite.
                validate_limit_offset_lossless(select)?;
                // Time-travel: intercept FOR SYSTEM_TIME AS OF queries and
                // execute against a historical MemDatabase snapshot (#23).
                if let Some(target) = extract_temporal_clause(select) {
                    self.log_mem_execution_fallback("select", "time_travel_snapshot")?;
                    return self.execute_time_travel_select(select, params, &target);
                }
                // CTE (WITH clause): materialize as temporary tables.
                if select.with.is_some() {
                    self.log_mem_execution_fallback("select", "with_clause_materialization")?;
                    return self.execute_with_ctes(select, params);
                }
                // View expansion: materialize referenced views as temp tables.
                if self.has_view_references(select) {
                    self.log_mem_execution_fallback("select", "view_materialization")?;
                    return self.execute_with_materialized_views(select, params);
                }
                if let Some(rows) = self.maybe_execute_attached_select(select, params)? {
                    return Ok(rows);
                }
                // Compound SELECT (UNION/UNION ALL/INTERSECT/EXCEPT) must
                // route through the compound executor before attached-schema
                // mixed fallback. The fallback executes a single SELECT body
                // and would otherwise ignore the right-hand compound arms.
                if !select.body.compounds.is_empty() {
                    return self.execute_compound_select(select, params);
                }
                if self.attached_select_requires_local_fallback(select)? {
                    self.log_mem_execution_fallback("select", "attached_mixed_select_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    // bd-xvtao: a mixed main+attached JOIN with GROUP BY or
                    // aggregates must run through the aggregation-aware join path;
                    // execute_join_select alone returns raw un-grouped rows and
                    // evaluates aggregates (e.g. sum()) as scalars -> NULL.
                    let needs_aggregation = has_group_by(select)
                        || self.has_implicit_aggregation_with_registry(select)
                        || has_ordered_aggregate(select);
                    let mut rows = if needs_aggregation && has_joins(select) {
                        self.execute_group_by_join_select(cx, &bound, None)?
                    } else {
                        self.execute_join_select(&bound, None)?
                    };
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    return Ok(rows);
                }
                // 5G.4 (bd-3ly4): sqlite_master/sqlite_schema virtual table support.
                if self.has_sqlite_schema_references(select) {
                    self.log_mem_execution_fallback(
                        "select",
                        "sqlite_schema_virtual_materialization",
                    )?;
                    return self.execute_with_materialized_sqlite_schema(select, params);
                }
                let distinct = is_distinct_select(select);
                let distinct_collations = if distinct {
                    let schema_snap = self.schema.borrow().clone();
                    select_result_collations(select, &schema_snap)
                } else {
                    Vec::new()
                };
                let distinct_coll_snap = if distinct {
                    lock_unpoisoned(self.collation_registry.as_ref()).clone()
                } else {
                    CollationRegistry::default()
                };
                let ordered_aggregate = has_ordered_aggregate(select);
                let implicit_aggregate = self.has_implicit_aggregation_with_registry(select);
                let custom_implicit_aggregate =
                    self.has_custom_implicit_aggregation_with_registry(select);
                // FROM-less aggregate SELECT (e.g. SELECT COUNT(*), SUM(NULL)).
                // Must be checked before the expression-only path because the
                // expression-only VDBE codegen cannot handle aggregate functions.
                if is_expression_only_select(select) && implicit_aggregate {
                    return self.execute_fromless_aggregate(select, params);
                }
                // Expression-only SELECT with scalar subqueries in result
                // columns: the VDBE codegen cannot resolve table references
                // inside subqueries (e.g. CTE temp tables).  Evaluate via the
                // connection-level path that can call execute_statement.
                if is_expression_only_select(select) && expression_only_has_subquery(select) {
                    return self.execute_expression_only_with_subqueries(select, params);
                }
                if let Some(rows) = self.try_execute_plain_live_vtab_count_star(select)? {
                    return Ok(rows);
                }
                // Check if this is an expression-only SELECT (no FROM clause).
                if is_expression_only_select(select) {
                    // Fallback codegen: eagerly rewrite IN subqueries.
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let plan_span = tracing::span!(
                        target: "fsqlite.plan",
                        tracing::Level::TRACE,
                        "plan",
                        stage = "compile_expression_select"
                    );
                    record_trace_span_created();
                    let _plan_guard = plan_span.enter();
                    let program = compile_expression_select(rewritten.as_ref())?;
                    let registry = self.func_registry.borrow().clone();
                    let op_cx = self.op_cx()?;
                    let mut rows = execute_program_with_postprocess(
                        &program,
                        params,
                        Some(&registry),
                        Some(&self.collation_registry),
                        &op_cx,
                        Some(&build_expression_postprocess(rewritten.as_ref())),
                        page_size_from_pragma_state(self.pragma_state.borrow().page_size)?,
                    )?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    Ok(rows)
                } else if self.select_correlated_exists_where_requires_fallback(select) {
                    // Correlated EXISTS subqueries in the WHERE clause require
                    // per-row evaluation of outer column refs unless the exact
                    // validated indexed COUNT(*) semijoin fast path applies.
                    self.log_mem_execution_fallback("select", "correlated_exists_fallback")?;
                    self.execute_correlated_subquery_where_fallback(cx, select, params)
                } else if select_has_correlated_in_subquery_in_where(select) {
                    // bd-zvk68: a correlated `x IN (SELECT ...)` predicate in the
                    // WHERE clause references outer columns and must be evaluated
                    // per outer row. The VDBE codegen IN-subquery path builds the
                    // candidate set once with no outer binding (yielding an empty
                    // set), so route to the connection-level fallback where
                    // eval_expr_with_subqueries substitutes outer refs per row
                    // (the InSet::Subquery arm). The correlated scalar `=` form is
                    // already handled in VDBE via emit_scalar_subquery.
                    self.log_mem_execution_fallback("select", "correlated_in_subquery_fallback")?;
                    self.execute_correlated_subquery_where_fallback(cx, select, params)
                } else if (has_group_by(select) || implicit_aggregate || ordered_aggregate)
                    && (has_joins(select)
                        || has_fallback_from_source(select)
                        || self.has_primary_live_vtab_source(select))
                    && (!self.select_grouped_inner_join_count_sum_is_vdbe_eligible(select)
                        || self.prefer_memdb_hash_grouped_join_dispatch(select))
                {
                    // GROUP BY (or implicit aggregation) + JOIN/non-table source/live vtab:
                    // materialize the join as a temp table, then GROUP BY on that.
                    self.log_mem_execution_fallback("select", "group_by_join_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_group_by_join_select(cx, &bound, None)?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if custom_implicit_aggregate {
                    self.log_mem_execution_fallback("select", "custom_aggregate_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_group_by_select(&bound, None)?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if implicit_aggregate && select_minmax_bare_tracking(select).is_some() {
                    // bd-xplxa: a whole-table query whose only aggregate is a
                    // single min()/max() with bare columns must take the bare
                    // columns from the extremum row. The plain VDBE max/min fast
                    // path returns an arbitrary row, so route to the grouped
                    // interpreter which sources bare columns from that row.
                    self.log_mem_execution_fallback("select", "minmax_bare_tracking_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_group_by_select(&bound, None)?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if (has_group_by(select) || ordered_aggregate)
                    && has_window_functions(select)
                {
                    // GROUP BY + window functions: two-phase execution.
                    // Phase 1: GROUP BY with non-window columns to get grouped rows.
                    // Phase 2: apply window functions to the grouped result.
                    if self.can_execute_aggregate_window_storage_substrate() {
                        self.log_aggregate_window_storage_substrate_dispatch(
                            select,
                            "group_by_window_storage_substrate",
                        );
                    } else {
                        self.log_mem_execution_fallback("select", "group_by_window_fallback")?;
                    }
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_group_by_window_select(&bound, None)?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if (has_group_by(select) || ordered_aggregate)
                    && !self.select_grouped_inner_join_count_sum_is_vdbe_eligible(select)
                {
                    // Eagerly rewrite IN subqueries before choosing the storage-compatible
                    // grouped-aggregate substrate or the connection-level fallback.
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    if let Some(mut rows) = self.try_execute_group_by_storage_substrate(
                        cx,
                        &bound,
                        None,
                        "group_by_storage_substrate",
                    )? {
                        if distinct {
                            dedup_rows_collated(
                                &mut rows,
                                &distinct_collations,
                                &distinct_coll_snap,
                            );
                        }
                        return Ok(rows);
                    }
                    self.log_mem_execution_fallback("select", "group_by_fallback")?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_group_by_select(&bound, None)?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if has_window_functions(select) {
                    // Window function fallback: materialize rows, sort by
                    // window spec, compute window functions at connection level.
                    if self.can_execute_aggregate_window_storage_substrate() {
                        self.log_aggregate_window_storage_substrate_dispatch(
                            select,
                            "window_function_storage_substrate",
                        );
                    } else {
                        self.log_mem_execution_fallback("select", "window_function_fallback")?;
                    }
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_window_select(&bound, None)?;
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if self.has_primary_live_vtab_source(select) {
                    // Live virtual-table instances are not yet emitted through
                    // the table-only VDBE codegen path. Route single-source
                    // scans through the connection fallback, which can drive
                    // the registered vtab instance directly.
                    self.log_mem_execution_fallback("select", "live_vtab_select_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_join_select(&bound, None)?;
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if (has_joins(select) || has_subquery_source(select))
                    && (!select_join_is_vdbe_eligible(select)
                        || self.prefer_memdb_hash_join_dispatch(select))
                    && !self.select_grouped_inner_join_count_sum_is_vdbe_eligible(select)
                {
                    // Bead bd-bldc5.4.2 (T21): VDBE JOIN routing
                    //
                    // VDBE codegen for JOINs exists (codegen_join_select) and the
                    // eligibility check is ready (select_join_is_vdbe_eligible).
                    // Currently disabled because codegen produces incorrect results
                    // for several JOIN shapes (NATURAL, CROSS, multi-table, complex
                    // ON conditions). To enable:
                    // 1. Run oracle conformance suite through codegen_join_select
                    // 2. Fix failing cases in fsqlite-vdbe/src/codegen.rs
                    // 3. Uncomment routing:
                    //    if select_join_is_vdbe_eligible(select) {
                    //        try compile_table_select → execute_table_program
                    //    }
                    // 4. Keep fallback for unsupported patterns (subquery sources)

                    // Fallback path: eagerly rewrite IN subqueries.
                    // Also handles derived tables even without explicit JOINs.
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let native_join_dispatch =
                        self.can_execute_join_select_on_real_backend(rewritten.as_ref());
                    if !native_join_dispatch {
                        self.log_mem_execution_fallback("select", "join_or_subquery_fallback")?;
                    }
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let started = Instant::now();
                    let mut rows = self.execute_join_select(&bound, None)?;
                    if native_join_dispatch {
                        let elapsed_ns =
                            u64::try_from(started.elapsed().as_nanos()).unwrap_or(u64::MAX);
                        self.log_native_join_dispatch(&bound, rows.len(), elapsed_ns);
                    }
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if has_table_function_source(select) {
                    self.log_mem_execution_fallback("select", "join_or_subquery_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_join_select(&bound, None)?;
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else if select_has_correlated_join_subquery(select) {
                    // Correlated scalar subqueries with JOINs in their FROM
                    // clause cannot be handled by the VDBE emit_scalar_subquery
                    // (which only opens one table cursor). Route through the
                    // connection-level fallback which can inline-evaluate them.
                    self.log_mem_execution_fallback("select", "correlated_join_subquery_fallback")?;
                    let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                    let mut bound =
                        bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
                    let limit_clause = bound.limit.take();
                    let mut rows = self.execute_join_select(&bound, None)?;
                    if let Some(limit) = limit_clause {
                        apply_limit_clause(&mut rows, &limit);
                    }
                    Ok(rows)
                } else {
                    let limit_clause = select.limit.clone();
                    let arc_prog;
                    let program: &VdbeProgram = if let Some(p) = precompiled {
                        p
                    } else {
                        // Eagerly rewrite IN-subqueries that the VDBE codegen
                        // cannot handle (e.g. those with GROUP BY / HAVING).
                        let rewritten = self.rewrite_in_subqueries_select(select, params)?;
                        if let Some(rows) =
                            self.try_direct_count_star_in_list(rewritten.as_ref())?
                        {
                            return Ok(rows);
                        }
                        let compiled_select = if distinct && limit_clause.is_some() {
                            let mut unbounded = rewritten.as_ref().clone();
                            unbounded.limit = None;
                            Cow::Owned(unbounded)
                        } else {
                            rewritten
                        };
                        let plan_span = tracing::span!(
                            target: "fsqlite.plan",
                            tracing::Level::TRACE,
                            "plan",
                            stage = "compile_table_select"
                        );
                        record_trace_span_created();
                        let _plan_guard = plan_span.enter();
                        // Cache the actual compiled SELECT shape, not the original
                        // SQL text, because eager subquery rewriting can inline
                        // parameter-sensitive literal lists before codegen.
                        // Use SelectStatement::to_string() directly to avoid
                        // cloning the entire AST into a Statement wrapper.
                        let sql_text = compiled_select.to_string();
                        let sql_key = Self::sql_hash(&sql_text);
                        arc_prog = self.compile_with_cache(sql_key, &sql_text, |conn| {
                            conn.compile_table_select(compiled_select.as_ref())
                        })?;
                        &arc_prog
                    };

                    let vdbe_storage_log_select = if select_join_is_vdbe_eligible(select) {
                        Some((select, "join_vdbe_storage_cursors"))
                    } else {
                        derived_storage_log_select
                            .map(|source| (source, "derived_source_flattened_vdbe_storage_cursors"))
                    };
                    let vdbe_storage_started = vdbe_storage_log_select.is_some().then(Instant::now);
                    let (mut rows, _, _) = self.execute_table_program_with_cx(
                        program,
                        params,
                        false,
                        TableExecutionRuntimeRequirements::read_path(),
                        cx,
                        false,
                    )?;
                    if let (Some((log_select, decision_reason)), Some(started)) =
                        (vdbe_storage_log_select, vdbe_storage_started)
                    {
                        let elapsed_ns = hot_path_elapsed_ns(Some(started)).unwrap_or(u64::MAX);
                        self.log_vdbe_join_storage_dispatch(
                            log_select,
                            decision_reason,
                            rows.len(),
                            elapsed_ns,
                        );
                    }
                    if distinct {
                        dedup_rows_collated(&mut rows, &distinct_collations, &distinct_coll_snap);
                        if let Some(limit_clause) = limit_clause.as_ref() {
                            apply_limit_clause(&mut rows, limit_clause);
                        }
                    }
                    // Implicit aggregation empty-set fixup: the VDBE may
                    // return a row with NULL for aggregates that should have
                    // non-NULL defaults (COUNT→0, TOTAL→0.0).  This happens
                    // when the WHERE clause filters out all rows and AggFinal
                    // is bypassed or returns the uninitialized register value.
                    //
                    // Skip when HAVING is present: an empty result means the
                    // HAVING clause intentionally filtered the aggregate row.
                    if !has_group_by(select)
                        && has_implicit_aggregation(select)
                        && !matches!(
                            &select.body.select,
                            SelectCore::Select {
                                having: Some(_),
                                ..
                            }
                        )
                        && let SelectCore::Select { columns, .. } = &select.body.select
                    {
                        if rows.is_empty() {
                            let defaults: Vec<SqliteValue> = columns
                                .iter()
                                .map(|col| {
                                    if let ResultColumn::Expr {
                                        expr: Expr::FunctionCall { name, .. },
                                        ..
                                    } = col
                                        && is_agg_fn(name)
                                    {
                                        return empty_aggregate_default(&name.to_ascii_lowercase());
                                    }
                                    SqliteValue::Null
                                })
                                .collect();
                            rows = vec![Row { values: defaults }];
                        } else if rows.len() == 1 {
                            // Patch NULL → default for aggregates that must
                            // never return NULL (total→0.0, count→0).
                            let row = &mut rows[0];
                            for (i, col) in columns.iter().enumerate() {
                                if i < row.values.len()
                                    && row.values[i].is_null()
                                    && let ResultColumn::Expr { expr, .. } = col
                                    && expr_contains_never_null_agg(expr)
                                {
                                    // Re-evaluate the column expression with
                                    // empty-set aggregate defaults substituted.
                                    row.values[i] = eval_empty_set_agg_expr(expr);
                                }
                            }
                        }
                    }
                    Ok(rows)
                }
            }
            Statement::Insert(insert) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&insert.table.name)
                {
                    let affected = self.execute_writable_schema_insert(insert, params)?;
                    self.record_statement_changes(affected);
                    return Ok(Vec::new());
                }
                if self.execute_fts5_maintenance_insert(insert)? {
                    return Ok(Vec::new());
                }
                #[cfg(feature = "ext-fts5")]
                if let Some(affected) = self.execute_fts5_magic_delete_insert(insert, params)? {
                    self.record_statement_changes(affected);
                    return Ok(Vec::new());
                }
                if insert.with.is_some() {
                    self.log_mem_execution_fallback("insert", "with_clause_materialization")?;
                    return self.execute_insert_with_ctes(insert, params);
                }

                let table_name = &insert.table.name;
                let insert_event = fsqlite_ast::TriggerEvent::Insert;
                let is_live_vtab = self.has_live_vtab_instance(table_name);
                let has_before_insert = self.has_matching_triggers(
                    table_name,
                    fsqlite_ast::TriggerTiming::Before,
                    &insert_event,
                );
                let has_after_insert = self.has_matching_triggers(
                    table_name,
                    fsqlite_ast::TriggerTiming::After,
                    &insert_event,
                );
                if is_live_vtab {
                    if !insert.returning.is_empty() {
                        return Err(FrankenError::NotImplemented(
                            "RETURNING is not supported for live virtual-table INSERT".to_owned(),
                        ));
                    }
                    if insert.or_conflict.is_some() || !insert.upsert.is_empty() {
                        return Err(FrankenError::NotImplemented(
                            "UPSERT and conflict clauses are not supported for live virtual-table INSERT"
                                .to_owned(),
                        ));
                    }
                }
                if !is_live_vtab
                    && let fsqlite_ast::InsertSource::Select(select_stmt) = &insert.source
                {
                    // Detect simple VALUES clause (no compounds).
                    // We must use the VDBE path for simple VALUES to avoid infinite recursion
                    // in the fallback (which implements inserts by generating simple VALUES inserts).
                    let is_simple_values = matches!(select_stmt.body.select, SelectCore::Values(_))
                        && select_stmt.body.compounds.is_empty();

                    // Complex INSERT ... SELECT statements are replayed as
                    // per-row INSERT ... VALUES operations. Those inner
                    // statements already handle trigger firing and change
                    // tracking, so route around the outer trigger path here.
                    let needs_row_by_row_replay =
                        has_before_insert || has_after_insert || self.fk_enforcement_enabled();
                    if !is_simple_values || needs_row_by_row_replay {
                        self.log_mem_execution_fallback(
                            "insert_select",
                            "insert_select_row_by_row_fallback",
                        )?;
                        if insert.returning.is_empty() {
                            let _ =
                                self.execute_insert_select_fallback(insert, select_stmt, params)?;
                            return Ok(Vec::new());
                        }
                        return self.execute_insert_select_fallback_returning(
                            insert,
                            select_stmt,
                            params,
                        );
                    }
                }
                if !is_live_vtab
                    && (has_before_insert || has_after_insert || self.fk_enforcement_enabled())
                    && let fsqlite_ast::InsertSource::Values(rows) = &insert.source
                    && rows.len() > 1
                {
                    self.log_mem_execution_fallback(
                        "insert_values",
                        "insert_values_row_by_row_trigger_or_fk_fallback",
                    )?;
                    let source_rows = self.materialize_insert_values_source_rows(rows, params)?;
                    let outcome =
                        self.execute_insert_select_materialized_rows_outcome(insert, &source_rows)?;
                    return Ok(outcome.returning_rows);
                }
                // bd-xb07w: morsel-driven INSERT for large multi-row VALUES
                // without triggers, FK, RETURNING, or UPSERT. The morsel
                // scheduler splits the row stream into batches for future
                // parallel execution; this wiring executes them sequentially.
                if !is_live_vtab
                    && insert.returning.is_empty()
                    && !has_before_insert
                    && !has_after_insert
                    && !self.fk_enforcement_enabled()
                    && insert.upsert.is_empty()
                    && let fsqlite_ast::InsertSource::Values(rows) = &insert.source
                    && rows.len() >= MORSEL_INSERT_THRESHOLD
                {
                    self.log_mem_execution_fallback("insert_values", "morsel_insert_dispatch")?;
                    let source_rows = self.materialize_insert_values_source_rows(rows, params)?;
                    let _ = self.execute_morsel_insert(insert, source_rows)?;
                    return Ok(Vec::new());
                }
                let mut live_insert_rows = if is_live_vtab
                    && !has_before_insert
                    && !has_after_insert
                    && matches!(insert.source, InsertSource::Select(_))
                {
                    if let Some(affected) =
                        self.try_execute_streaming_live_vtab_insert_select(insert, params)?
                    {
                        self.record_statement_changes(affected);
                        return Ok(Vec::new());
                    }
                    Some(self.collect_live_vtab_insert_rows(insert, params)?)
                } else if is_live_vtab {
                    Some(self.collect_live_vtab_insert_rows(insert, params)?)
                } else {
                    None
                };
                let mut trigger_new_rows = if has_before_insert || has_after_insert {
                    if let Some(rows) = live_insert_rows.as_ref() {
                        rows.iter().map(|row| row.values.clone()).collect()
                    } else {
                        self.collect_insert_trigger_rows(insert, params)?
                    }
                } else {
                    Vec::new()
                };

                // Phase 5G.2 (bd-iqam): Fire BEFORE INSERT triggers.
                let skip_dml = if has_before_insert {
                    let mut skip = false;
                    for new_values in &trigger_new_rows {
                        if self.fire_before_triggers(
                            table_name,
                            &insert_event,
                            None,
                            Some(new_values),
                        )? {
                            skip = true;
                            break;
                        }
                    }
                    skip
                } else {
                    false
                };
                if skip_dml {
                    // RAISE(IGNORE) was called - skip the INSERT.
                    self.reset_statement_change_count();
                    return Ok(Vec::new());
                }

                if is_live_vtab {
                    let mut live_insert_rows = live_insert_rows.take().unwrap_or_else(Vec::new);
                    let patch_first_column_with_rowid = {
                        let key = table_name.to_ascii_uppercase();
                        self.vtab_instances
                            .borrow()
                            .get(&key)
                            .is_some_and(|instance| is_rtree_instance(instance.as_ref()))
                    };
                    let inserted_rowids =
                        self.execute_live_vtab_insert_rows(table_name, &live_insert_rows)?;

                    if has_after_insert {
                        if patch_first_column_with_rowid {
                            for (row, rowid) in
                                live_insert_rows.iter_mut().zip(inserted_rowids.iter())
                            {
                                if row.values.first().is_some_and(|value| value.is_null()) {
                                    row.values[0] = SqliteValue::Integer(*rowid);
                                }
                            }
                        }
                        for row in &live_insert_rows {
                            self.fire_after_triggers(
                                table_name,
                                &insert_event,
                                None,
                                Some(&row.values),
                            )?;
                        }
                    }

                    self.record_statement_changes(live_insert_rows.len());
                    return Ok(Vec::new());
                }

                // Phase 5B.2 (bd-1yi8): INSERT OR REPLACE / INSERT OR IGNORE
                // routes through VDBE which has UPSERT semantics in the
                // Insert opcode (table_move_to + delete + insert). The
                // previous execute_insert_or_conflict fast path read from
                // MemDatabase directly, which doesn't work now that
                // write-through stopped syncing inserts to MemDatabase.
                //
                // Performance note (bead bd-bldc5.4.3): re-enabling the fast
                // path requires updating execute_insert_or_conflict to read
                // from the pager via StorageCursor instead of MemDatabase.
                // The VDBE path is correct; this is an optimization only.

                let execute_insert_and_after_triggers = || {
                    let arc_prog;
                    let program: &VdbeProgram = if let Some(p) = precompiled {
                        p
                    } else {
                        let plan_span = tracing::span!(
                            target: "fsqlite.plan",
                            tracing::Level::TRACE,
                            "plan",
                            stage = "compile_table_insert"
                        );
                        record_trace_span_created();
                        let _plan_guard = plan_span.enter();
                        let sql_text = statement.to_string();
                        let sql_key = Self::sql_hash(&sql_text);
                        arc_prog = self.compile_with_cache(sql_key, &sql_text, |conn| {
                            conn.compile_table_insert(insert)
                        })?;
                        &arc_prog
                    };
                    let runtime_requirements = self.insert_runtime_requirements(insert)?;
                    let (rows, affected, last_insert_rowid) = self.execute_table_program_with_cx(
                        program,
                        params,
                        true,
                        runtime_requirements,
                        cx,
                        true,
                    )?;

                    // Implicit REPLACE deletes are real parent-row deletions for
                    // inbound FK purposes. The VDBE reports the exact victims
                    // after canonical conflict discovery; enforce their actions
                    // before validating the inserted child row or firing AFTER
                    // INSERT triggers.
                    self.enforce_fk_on_replace_victims(table_name)?;

                    // bd-thqgm: FK constraint checking on INSERT.
                    // Skip FK enforcement when no row was written (e.g. an OR IGNORE
                    // PK conflict, affected == 0): SQLite does not FK-check a row it
                    // never inserted (#111).
                    if affected > 0 && self.fk_enforcement_enabled() {
                        self.enforce_fk_on_insert(insert, table_name, params)?;
                    }

                    // Patch trigger NEW rows: fill in auto-assigned INTEGER
                    // PRIMARY KEY rowids that were NULL at pre-computation time.
                    if has_after_insert && !trigger_new_rows.is_empty() {
                        if affected == 0 {
                            trigger_new_rows.clear();
                        } else {
                            let tbl_key = table_name.to_ascii_lowercase();
                            if let Some(&ipk_idx) = self.rowid_alias_columns.borrow().get(&tbl_key)
                            {
                                let last_rowid = self.current_last_insert_rowid();
                                let count = trigger_new_rows.len();
                                for (i, new_row) in trigger_new_rows.iter_mut().enumerate() {
                                    if ipk_idx < new_row.len()
                                        && new_row[ipk_idx] == SqliteValue::Null
                                    {
                                        #[allow(clippy::cast_possible_wrap)]
                                        let rowid = last_rowid - (count as i64 - 1) + i as i64;
                                        new_row[ipk_idx] = SqliteValue::Integer(rowid);
                                    }
                                }
                            }
                        }
                    }

                    // Phase 5G.3: Fire AFTER INSERT triggers.
                    if has_after_insert {
                        for new_values in &trigger_new_rows {
                            self.fire_after_triggers(
                                table_name,
                                &insert_event,
                                None,
                                Some(new_values),
                            )?;
                        }
                    }

                    Ok((rows, affected, last_insert_rowid))
                };
                let (rows, affected, last_insert_rowid) = self.with_replace_fk_validation_scope(
                    table_name,
                    insert.or_conflict,
                    has_after_insert,
                    execute_insert_and_after_triggers,
                )?;

                if table_name.eq_ignore_ascii_case("sqlite_sequence") {
                    self.refresh_sqlite_sequence_cache()?;
                } else {
                    self.refresh_autoincrement_sequence_after_insert(
                        table_name,
                        affected,
                        last_insert_rowid,
                    )?;
                }

                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                self.record_statement_changes(affected);
                if insert.returning.is_empty() {
                    Ok(Vec::new())
                } else {
                    Ok(rows)
                }
            }
            Statement::Update(update) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&update.table.name.name)
                {
                    let affected = self.execute_writable_schema_update(update, params)?;
                    self.record_statement_changes(affected);
                    return Ok(Vec::new());
                }
                // CTE (WITH clause): materialize CTEs as temporary tables,
                // then execute the UPDATE with the WITH clause stripped.
                if update.with.is_some() {
                    self.log_mem_execution_fallback("update", "with_clause_materialization")?;
                    return self.execute_update_with_ctes(update, params);
                }
                let (effective_update, _limited_row_count_hint) =
                    self.materialize_update_limit_scope(update, params)?;
                let table_name = &effective_update.table.name.name;
                // Collect columns being updated for UPDATE OF trigger matching.
                let update_cols: Vec<String> = effective_update
                    .assignments
                    .iter()
                    .flat_map(|a| match &a.target {
                        fsqlite_ast::AssignmentTarget::Column(c) => vec![c.clone()],
                        fsqlite_ast::AssignmentTarget::ColumnList(cols) => cols.clone(),
                    })
                    .collect();
                let update_event = fsqlite_ast::TriggerEvent::Update(update_cols);
                let has_before_update = self.has_matching_triggers(
                    table_name,
                    fsqlite_ast::TriggerTiming::Before,
                    &update_event,
                );
                let has_after_update = self.has_matching_triggers(
                    table_name,
                    fsqlite_ast::TriggerTiming::After,
                    &update_event,
                );
                let needs_row_by_row_replay = effective_update.from.is_none()
                    && (has_before_update
                        || has_after_update
                        || self.fk_cascade_propagation_enabled());
                if needs_row_by_row_replay
                    && let Some((locator_columns, locator_rows)) =
                        self.materialize_update_replay_locators(&effective_update, params)?
                    && locator_rows.len() > 1
                {
                    self.log_mem_execution_fallback(
                        "update",
                        "update_row_by_row_trigger_or_fk_fallback",
                    )?;
                    return self.execute_update_row_by_row(
                        &effective_update,
                        params,
                        &locator_columns,
                        &locator_rows,
                    );
                }
                let trigger_rows = if has_before_update || has_after_update {
                    self.collect_update_trigger_rows(&effective_update, params)?
                } else {
                    Vec::new()
                };

                // Phase 5G.2 (bd-iqam): Fire BEFORE UPDATE triggers.
                let skip_dml = if has_before_update {
                    let mut skip = false;
                    for (old_values, new_values) in &trigger_rows {
                        if self.fire_before_triggers(
                            table_name,
                            &update_event,
                            Some(old_values),
                            Some(new_values),
                        )? {
                            skip = true;
                            break;
                        }
                    }
                    skip
                } else {
                    false
                };
                if skip_dml {
                    self.reset_statement_change_count();
                    return Ok(Vec::new());
                }

                // FK enforcement on UPDATE:
                // 1. Parent-side: check old values aren't orphaning children
                //    (uses cascade-propagation gate so multi-level cascades work)
                // 2. Child-side: check new FK values have valid parents
                //    (uses strict gate — not needed during cascade operations)
                if self.fk_cascade_propagation_enabled() {
                    let rows_to_check = if !trigger_rows.is_empty() {
                        trigger_rows
                            .iter()
                            .map(|(old, new)| (old.clone(), new.clone()))
                            .collect::<Vec<_>>()
                    } else {
                        self.collect_update_trigger_rows(&effective_update, params)?
                    };
                    for (old_values, new_values) in &rows_to_check {
                        // Parent-side: if this table is referenced by children,
                        // check that changing FK-referenced values doesn't orphan them.
                        // Use ON UPDATE actions (not ON DELETE) for UPDATE statements.
                        let fk_actions =
                            self.check_fk_on_update(table_name, old_values, new_values)?;
                        for action in &fk_actions {
                            self.execute_fk_update_action(action)?;
                        }
                        // Child-side: validate new FK values against parent tables.
                        // Only check when NOT inside a cascade action, because
                        // the cascade itself is modifying parent data.
                        if self.fk_enforcement_enabled() {
                            self.check_fk_parent_exists(table_name, new_values)?;
                        }
                    }
                }

                let execute_update_and_after_triggers = || {
                    let arc_prog;
                    let program: &VdbeProgram = if let Some(p) = precompiled {
                        p
                    } else {
                        let plan_span = tracing::span!(
                            target: "fsqlite.plan",
                            tracing::Level::TRACE,
                            "plan",
                            stage = "compile_table_update"
                        );
                        record_trace_span_created();
                        let _plan_guard = plan_span.enter();
                        let sql_text = effective_update.to_string();
                        let sql_key = Self::sql_hash(&sql_text);
                        arc_prog = self.compile_with_cache(sql_key, &sql_text, |conn| {
                            conn.compile_table_update(&effective_update)
                        })?;
                        &arc_prog
                    };
                    let (rows, affected, _) = self.execute_table_program_with_cx(
                        program,
                        params,
                        false,
                        TableExecutionRuntimeRequirements::read_path(),
                        cx,
                        true,
                    )?;

                    // UPDATE OR REPLACE may implicitly delete a different row that
                    // conflicts with the updated value. Apply inbound FK effects
                    // for that exact victim before AFTER UPDATE triggers.
                    self.enforce_fk_on_replace_victims(table_name)?;

                    // Phase 5G.3: Fire AFTER UPDATE triggers.
                    if has_after_update {
                        for (old_values, new_values) in &trigger_rows {
                            self.fire_after_triggers(
                                table_name,
                                &update_event,
                                Some(old_values),
                                Some(new_values),
                            )?;
                        }
                    }

                    Ok((rows, affected))
                };
                let (rows, affected) = self.with_replace_fk_validation_scope(
                    table_name,
                    effective_update.or_conflict,
                    has_after_update,
                    execute_update_and_after_triggers,
                )?;

                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                self.record_statement_changes(affected);
                if effective_update.returning.is_empty() {
                    Ok(Vec::new())
                } else {
                    Ok(rows)
                }
            }
            Statement::Delete(delete) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&delete.table.name.name)
                {
                    let affected = self.execute_writable_schema_delete(delete, params)?;
                    self.record_statement_changes(affected);
                    return Ok(Vec::new());
                }
                // CTE (WITH clause): materialize CTEs as temporary tables,
                // then execute the DELETE with the WITH clause stripped.
                if delete.with.is_some() {
                    self.log_mem_execution_fallback("delete", "with_clause_materialization")?;
                    return self.execute_delete_with_ctes(delete, params);
                }
                let (mut effective_delete, _limited_row_count_hint) =
                    self.materialize_delete_limit_scope(delete, params)?;
                // If the DELETE's WHERE contains a correlated EXISTS subquery,
                // collect matching rowids via connection-level evaluation (which
                // correctly substitutes outer refs per row) and rewrite the WHERE
                // to a simple rowid IN (...) predicate.
                // Pre-evaluate uncorrelated scalar subqueries that reference
                // the DELETE target table. Without this, the VDBE evaluates
                // them per-row during the scan, seeing partially-deleted
                // state from earlier rows (e.g., DELETE FROM t WHERE val >
                // (SELECT AVG(val) FROM t) cascades incorrectly).
                if let Some(wh) = effective_delete.where_clause.as_ref() {
                    if expr_has_self_referencing_scalar_subquery(
                        wh,
                        &effective_delete.table.name.name,
                    ) {
                        let mut rewritten = wh.clone();
                        self.inline_self_referencing_scalar_subqueries(
                            &mut rewritten,
                            &effective_delete.table.name.name,
                        )?;
                        effective_delete.where_clause = Some(rewritten);
                    }
                }
                if effective_delete.where_clause.as_ref().is_some_and(|wh| {
                    expr_has_self_referencing_correlated_exists(
                        wh,
                        &effective_delete.table.name.name,
                    )
                }) {
                    let matched_rows = self.select_matching_rows(
                        &effective_delete.table,
                        effective_delete.where_clause.as_ref(),
                        &[],
                        None,
                        params,
                    )?;
                    let rowid_literals: Vec<Expr> = matched_rows
                        .iter()
                        .filter_map(|row| {
                            row.values().first().and_then(|v| {
                                if let SqliteValue::Integer(i) = v {
                                    Some(Expr::Literal(
                                        Literal::Integer(*i),
                                        fsqlite_ast::Span::new(0, 0),
                                    ))
                                } else {
                                    None
                                }
                            })
                        })
                        .collect();
                    if rowid_literals.is_empty() {
                        self.reset_statement_change_count();
                        return Ok(Vec::new());
                    }
                    effective_delete.where_clause = Some(Expr::In {
                        expr: Box::new(Expr::Column(
                            fsqlite_ast::ColumnRef::bare("rowid"),
                            fsqlite_ast::Span::new(0, 0),
                        )),
                        not: false,
                        set: fsqlite_ast::InSet::List(rowid_literals),
                        span: fsqlite_ast::Span::new(0, 0),
                    });
                }
                let table_name = &effective_delete.table.name.name;
                let delete_event = fsqlite_ast::TriggerEvent::Delete;
                let has_before_delete = self.has_matching_triggers(
                    table_name,
                    fsqlite_ast::TriggerTiming::Before,
                    &delete_event,
                );
                let has_after_delete = self.has_matching_triggers(
                    table_name,
                    fsqlite_ast::TriggerTiming::After,
                    &delete_event,
                );
                let trigger_old_rows = if has_before_delete || has_after_delete {
                    self.collect_delete_trigger_rows(&effective_delete, params)?
                } else {
                    Vec::new()
                };

                // Phase 5G.2 (bd-iqam): Fire BEFORE DELETE triggers.
                let skip_dml = if has_before_delete {
                    let mut skip = false;
                    for old_values in &trigger_old_rows {
                        if self.fire_before_triggers(
                            table_name,
                            &delete_event,
                            Some(old_values),
                            None,
                        )? {
                            skip = true;
                            break;
                        }
                    }
                    skip
                } else {
                    false
                };
                if skip_dml {
                    self.reset_statement_change_count();
                    return Ok(Vec::new());
                }

                // FK enforcement on DELETE: check/cascade for each row.
                // Use `fk_cascade_propagation_enabled` (not `fk_enforcement_enabled`)
                // so that multi-level cascades propagate through intermediate
                // tables (e.g., grandparent -> parent -> child).
                if self.fk_cascade_propagation_enabled() {
                    let rows_to_check = if !trigger_old_rows.is_empty() {
                        trigger_old_rows.clone()
                    } else {
                        self.collect_delete_trigger_rows(&effective_delete, params)?
                    };
                    for row_values in &rows_to_check {
                        let fk_actions = self.check_fk_on_delete(table_name, row_values)?;
                        for action in &fk_actions {
                            self.execute_fk_delete_action(action)?;
                        }
                    }
                }

                // Live virtual-table DELETE: route each matching rowid through
                // the module's xUpdate delete branch so the in-memory module
                // state (FTS5 index/content/docsize) and the backing storage
                // B-tree stay consistent. The VDBE table-delete program below
                // only mutates ordinary B-tree tables and would otherwise leave
                // the live module instance stale (frankensqlite#94).
                if self.has_live_vtab_instance(table_name) {
                    if !effective_delete.returning.is_empty() {
                        return Err(FrankenError::NotImplemented(
                            "RETURNING is not supported for live virtual-table DELETE".to_owned(),
                        ));
                    }
                    let affected = self.execute_live_vtab_delete(&effective_delete, params)?;

                    // Phase 5G.3: Fire AFTER DELETE triggers.
                    if has_after_delete {
                        for old_values in &trigger_old_rows {
                            self.fire_after_triggers(
                                table_name,
                                &delete_event,
                                Some(old_values),
                                None,
                            )?;
                        }
                    }

                    self.record_statement_changes(affected);
                    return Ok(Vec::new());
                }

                let arc_prog;
                let program: &VdbeProgram = if let Some(p) = precompiled {
                    p
                } else {
                    let plan_span = tracing::span!(
                        target: "fsqlite.plan",
                        tracing::Level::TRACE,
                        "plan",
                        stage = "compile_table_delete"
                    );
                    record_trace_span_created();
                    let _plan_guard = plan_span.enter();
                    let sql_text = effective_delete.to_string();
                    let sql_key = Self::sql_hash(&sql_text);
                    arc_prog = self.compile_with_cache(sql_key, &sql_text, |conn| {
                        conn.compile_table_delete(&effective_delete)
                    })?;
                    &arc_prog
                };
                let (rows, affected, _) = self.execute_table_program_with_cx(
                    program,
                    params,
                    false,
                    TableExecutionRuntimeRequirements::read_path(),
                    cx,
                    true,
                )?;

                // Phase 5G.3: Fire AFTER DELETE triggers.
                if has_after_delete {
                    for old_values in &trigger_old_rows {
                        self.fire_after_triggers(
                            table_name,
                            &delete_event,
                            Some(old_values),
                            None,
                        )?;
                    }
                }

                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                self.record_statement_changes(affected);
                if effective_delete.returning.is_empty() {
                    Ok(Vec::new())
                } else {
                    Ok(rows)
                }
            }
            Statement::Begin(begin) => {
                self.execute_begin(*begin)?;
                Ok(Vec::new())
            }
            Statement::Commit => {
                self.execute_commit_with_cx(cx)?;
                Ok(Vec::new())
            }
            Statement::Rollback(rb) => {
                self.execute_rollback_with_cx(cx, rb)?;
                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                Ok(Vec::new())
            }
            Statement::Savepoint(name) => {
                self.execute_savepoint_with_cx(cx, name)?;
                Ok(Vec::new())
            }
            Statement::Release(name) => {
                self.execute_release_with_cx(cx, name)?;
                Ok(Vec::new())
            }
            Statement::Pragma(pragma) => self.execute_pragma(pragma),
            Statement::Drop(drop_stmt) => {
                self.execute_drop(drop_stmt)?;
                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                Ok(Vec::new())
            }
            Statement::AlterTable(alter) => {
                self.execute_alter_table(alter)?;
                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                Ok(Vec::new())
            }
            Statement::CreateIndex(create_idx) => {
                self.execute_create_index(create_idx)?;
                // 5D.4: Persistence now handled by pager WAL, not compat_persist.
                Ok(Vec::new())
            }
            Statement::CreateView(create_view) => {
                self.execute_create_view(create_view)?;
                Ok(Vec::new())
            }
            Statement::CreateTrigger(create_trigger) => {
                self.execute_create_trigger(create_trigger)?;
                Ok(Vec::new())
            }
            Statement::Vacuum(vacuum_stmt) => {
                self.execute_vacuum(vacuum_stmt, params)?;
                Ok(Vec::new())
            }
            Statement::Analyze(target) => {
                self.execute_analyze(target.as_ref())?;
                Ok(Vec::new())
            }
            Statement::Reindex(target) => {
                self.execute_reindex(target.as_ref())?;
                Ok(Vec::new())
            }
            Statement::Explain { query_plan, stmt } => {
                self.execute_explain(stmt, *query_plan, params)
            }
            Statement::Attach(attach) => {
                let path_rows = self.execute_statement(
                    &Statement::Select(SelectStatement {
                        with: None,
                        body: SelectBody {
                            select: SelectCore::Select {
                                distinct: Distinctness::All,
                                columns: vec![ResultColumn::Expr {
                                    expr: attach.expr.clone(),
                                    alias: None,
                                }],
                                from: None,
                                where_clause: None,
                                group_by: Vec::new(),
                                having: None,
                                windows: Vec::new(),
                            },
                            compounds: Vec::new(),
                        },
                        order_by: Vec::new(),
                        limit: None,
                    }),
                    params,
                )?;
                let path = path_rows
                    .first()
                    .and_then(|r| r.values().first())
                    .map(|v| match v {
                        SqliteValue::Text(s) => s.to_string(),
                        other => format!("{other}"),
                    })
                    .unwrap_or_default();
                tracing::debug!(
                    schema = %attach.schema,
                    path = %path,
                    page_buffer_max = ?self.attach_env.page_buffer_max(),
                    memory_vfs_config = ?self.attach_env.memory_vfs_config(),
                    "opening attached database with inherited connection environment"
                );
                // A read-only / schema-only main connection opens attached
                // databases read-only too, so writes through the attached schema
                // surface as `ReadOnly` rather than mutating a file the parent
                // was never granted write access to. A writable main opens the
                // attached database read-write as usual.
                let attached_connection = if self.pager.is_readonly() {
                    Box::new(Self::open_schema_only_with_env(
                        path.clone(),
                        self.attach_env.clone(),
                    )?)
                } else {
                    Box::new(Self::open_with_env(path.clone(), self.attach_env.clone())?)
                };
                self.attached_schemas
                    .borrow_mut()
                    .attach(attach.schema.clone(), path)?;
                self.attached_connections
                    .borrow_mut()
                    .insert(attached_schema_key(&attach.schema), attached_connection);
                Ok(Vec::new())
            }
            Statement::Detach(schema_name) => {
                self.attached_schemas.borrow_mut().detach(schema_name)?;
                self.attached_connections
                    .borrow_mut()
                    .remove(&attached_schema_key(schema_name));
                Ok(Vec::new())
            }
            #[allow(unreachable_patterns)]
            _ => Err(FrankenError::NotImplemented(
                "unsupported statement type".to_owned(),
            )),
        }
    }

    /// Pre-process statement-level subquery expressions before compilation.
    ///
    /// EXISTS and scalar subqueries are eagerly evaluated everywhere.
    /// Simple `IN (SELECT ...)` are left intact for VDBE probe, but IN
    /// subqueries with GROUP BY/HAVING/windows/compounds/WITH are eagerly
    /// evaluated since VDBE codegen emits NULL for those.  Fallback paths (GROUP BY,
    /// JOIN, expression-only SELECT) apply the IN rewrite separately.
    fn rewrite_subquery_statement<'a>(
        &self,
        statement: &'a Statement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Cow<'a, Statement>> {
        // Fast path: if the statement has no EXISTS/scalar-subquery expressions
        // in rewrite-covered locations, skip the clone/traversal rewrite pass.
        let has_flattenable_derived_table = matches!(
            statement,
            Statement::Select(select) if flatten_simple_from_subquery_select(select).is_some()
        );
        // bd-kkfok / bd-8ewbk: an `UPDATE ... FROM (subquery)` carries its only
        // subquery in the FROM source (leading source or a JOIN arm), which
        // `statement_contains_rewritable_subquery` does not flag. Without this the
        // fast path would skip the flatten/hoist rewrite below.
        let has_update_from_subquery = matches!(
            statement,
            Statement::Update(update)
                if update.with.is_none()
                    && update.from.as_ref().is_some_and(|from| {
                        matches!(from.source, TableOrSubquery::Subquery { .. })
                            || from.joins.iter().any(|join| {
                                matches!(join.table, TableOrSubquery::Subquery { .. })
                            })
                    })
        );
        if !statement_contains_rewritable_subquery(statement)
            && !statement_requires_in_table_name_rewrite(statement)
            && !has_flattenable_derived_table
            && !has_update_from_subquery
        {
            return Ok(Cow::Borrowed(statement));
        }
        match statement {
            Statement::Select(select) if select.with.is_some() => {
                // When the SELECT has a WITH clause, the CTE tables have not
                // been materialized yet.  Subqueries may reference CTE names,
                // so skip eager rewriting here — it will happen after CTE
                // materialization inside execute_with_ctes.
                Ok(Cow::Borrowed(statement))
            }
            Statement::Select(select)
                if is_expression_only_select(select) && expression_only_has_subquery(select) =>
            {
                // Expression-only SELECTs with scalar subqueries in result
                // columns are handled by execute_expression_only_with_subqueries
                // in dispatch.  Skip the eager rewrite here — evaluating each
                // subquery via execute_statement would create nested autocommit
                // transactions that can trigger reload_memdb_from_pager,
                // destroying CTE temp tables between subquery evaluations.
                Ok(Cow::Borrowed(statement))
            }
            Statement::Select(select) => {
                let rewritten = self.rewrite_subqueries(select, params)?;
                Ok(Cow::Owned(Statement::Select(rewritten)))
            }
            Statement::Insert(insert) if insert.with.is_some() => Ok(Cow::Borrowed(statement)),
            Statement::Insert(insert) => {
                let mut insert = insert.clone();
                let eager_in_subqueries = self.attached_target_schema(&insert.table)?.is_some();
                match &mut insert.source {
                    fsqlite_ast::InsertSource::Values(rows) => {
                        for row in rows {
                            for expr in row {
                                rewrite_dml_in_expr(expr, self, eager_in_subqueries, params)?;
                            }
                        }
                    }
                    fsqlite_ast::InsertSource::Select(select) => {
                        let rewritten =
                            self.rewrite_dml_select_source(select, eager_in_subqueries, params)?;
                        insert.source = fsqlite_ast::InsertSource::Select(Box::new(rewritten));
                    }
                    fsqlite_ast::InsertSource::DefaultValues => {}
                }
                for upsert in &mut insert.upsert {
                    if let Some(target) = &mut upsert.target
                        && let Some(where_clause) = &mut target.where_clause
                    {
                        rewrite_dml_in_expr(where_clause, self, eager_in_subqueries, params)?;
                    }
                    if let fsqlite_ast::UpsertAction::Update {
                        assignments,
                        where_clause,
                    } = &mut upsert.action
                    {
                        for assignment in assignments {
                            rewrite_dml_in_expr(
                                &mut assignment.value,
                                self,
                                eager_in_subqueries,
                                params,
                            )?;
                        }
                        if let Some(predicate) = where_clause {
                            rewrite_dml_in_expr(predicate, self, eager_in_subqueries, params)?;
                        }
                    }
                }
                for column in &mut insert.returning {
                    if let ResultColumn::Expr { expr, .. } = column {
                        rewrite_dml_in_expr(expr, self, eager_in_subqueries, params)?;
                    }
                }
                Ok(Cow::Owned(Statement::Insert(insert)))
            }
            Statement::Update(update) if update.with.is_some() => Ok(Cow::Borrowed(statement)),
            Statement::Update(update) => {
                let mut update = update.clone();
                // bd-kkfok: flatten a simple-projection subquery `UPDATE ... FROM`
                // source into its base table so the named-table nested-loop codegen
                // can drive it. Done before the IN/subquery rewrites so they see the
                // flattened (plain-table) shape.
                try_flatten_update_from_subquery(&mut update);
                // bd-8ewbk: any FROM subquery source that flattening could not
                // reduce to a base table (aggregate/GROUP BY/join/rename/...) is
                // hoisted into a CTE. The resulting WITH-clause UPDATE routes
                // through the CTE-materialization path (in both the prepared and
                // deferred dispatch paths), turning the subquery into a temporary
                // relation that `codegen_update_from` drives as a named table.
                if let Some(hoisted) = hoist_update_from_subqueries_to_ctes(&update) {
                    return Ok(Cow::Owned(Statement::Update(hoisted)));
                }
                let eager_in_subqueries =
                    self.attached_target_update_requires_eager_in_subquery_rewrite(&update)?;
                // Rewrite EXISTS / scalar subqueries, plus IN subqueries that
                // VDBE can't probe (GROUP BY, HAVING, windows, compounds, WITH).
                // Attached-target UPDATE that reads main/unqualified subqueries
                // also forces eager IN rewrite so the attached-child execution
                // path receives only local literals instead of outer-table
                // references it cannot resolve.
                for assignment in &mut update.assignments {
                    rewrite_dml_in_expr(&mut assignment.value, self, eager_in_subqueries, params)?;
                }
                if let Some(from) = update.from.as_mut() {
                    self.rewrite_dml_from_clause(from, eager_in_subqueries, params)?;
                }
                if let Some(where_expr) = update.where_clause.as_mut() {
                    rewrite_dml_in_expr(where_expr, self, eager_in_subqueries, params)?;
                }
                rewrite_dml_result_columns(
                    &mut update.returning,
                    self,
                    eager_in_subqueries,
                    params,
                )?;
                rewrite_in_ordering_terms(&mut update.order_by, self, eager_in_subqueries, params)?;
                if let Some(limit_clause) = update.limit.as_mut() {
                    rewrite_dml_limit_clause(limit_clause, self, eager_in_subqueries, params)?;
                }
                Ok(Cow::Owned(Statement::Update(update)))
            }
            Statement::Delete(delete) if delete.with.is_some() => Ok(Cow::Borrowed(statement)),
            Statement::Delete(delete) => {
                let mut delete = delete.clone();
                let eager_in_subqueries =
                    self.attached_target_delete_requires_eager_in_subquery_rewrite(&delete)?;
                // Rewrite EXISTS / scalar subqueries, plus IN subqueries that
                // VDBE can't probe (GROUP BY, HAVING, windows, compounds, WITH).
                // Attached-target DELETE that reads main/unqualified subqueries
                // also forces eager IN rewrite so delegation into the attached
                // child no longer depends on outer-schema visibility.
                if let Some(where_expr) = delete.where_clause.as_mut() {
                    rewrite_dml_in_expr(where_expr, self, eager_in_subqueries, params)?;
                }
                rewrite_dml_result_columns(
                    &mut delete.returning,
                    self,
                    eager_in_subqueries,
                    params,
                )?;
                rewrite_in_ordering_terms(&mut delete.order_by, self, eager_in_subqueries, params)?;
                if let Some(limit_clause) = delete.limit.as_mut() {
                    rewrite_dml_limit_clause(limit_clause, self, eager_in_subqueries, params)?;
                }
                Ok(Cow::Owned(Statement::Delete(delete)))
            }
            other => Ok(Cow::Borrowed(other)),
        }
    }

    fn attached_target_update_requires_eager_in_subquery_rewrite(
        &self,
        update: &fsqlite_ast::UpdateStatement,
    ) -> Result<bool> {
        let Some(_) = self.attached_target_schema(&update.table.name)? else {
            return Ok(false);
        };
        let registry = self.attached_schemas.borrow();
        match determine_attached_update_schema(update, &registry) {
            Ok(Some(_)) => Ok(true),
            Ok(None) => Ok(false),
            Err(FrankenError::NotImplemented(message))
                if message
                    == "statements mixing attached schemas with main/temp or unqualified tables are not yet supported" =>
            {
                Ok(true)
            }
            Err(FrankenError::NotImplemented(_)) => Ok(false),
            Err(err) => Err(err),
        }
    }

    fn attached_target_delete_requires_eager_in_subquery_rewrite(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
    ) -> Result<bool> {
        let Some(_) = self.attached_target_schema(&delete.table.name)? else {
            return Ok(false);
        };
        let registry = self.attached_schemas.borrow();
        match determine_attached_delete_schema(delete, &registry) {
            Ok(Some(_)) => Ok(true),
            Ok(None) => Ok(false),
            Err(FrankenError::NotImplemented(message))
                if message
                    == "statements mixing attached schemas with main/temp or unqualified tables are not yet supported" =>
            {
                Ok(true)
            }
            Err(FrankenError::NotImplemented(_)) => Ok(false),
            Err(err) => Err(err),
        }
    }

    fn rewrite_dml_from_clause(
        &self,
        from: &mut fsqlite_ast::FromClause,
        rewrite_in_subqueries: bool,
        params: Option<&[SqliteValue]>,
    ) -> Result<()> {
        self.rewrite_dml_table_or_subquery(&mut from.source, rewrite_in_subqueries, params)?;
        for join in &mut from.joins {
            self.rewrite_dml_table_or_subquery(&mut join.table, rewrite_in_subqueries, params)?;
            if let Some(JoinConstraint::On(expr)) = join.constraint.as_mut() {
                rewrite_dml_in_expr(expr, self, rewrite_in_subqueries, params)?;
            }
        }
        Ok(())
    }

    fn rewrite_dml_table_or_subquery(
        &self,
        source: &mut TableOrSubquery,
        rewrite_in_subqueries: bool,
        params: Option<&[SqliteValue]>,
    ) -> Result<()> {
        match source {
            TableOrSubquery::Table { .. } => Ok(()),
            TableOrSubquery::Subquery { query, .. } => {
                let rewritten =
                    self.rewrite_dml_select_source(query, rewrite_in_subqueries, params)?;
                **query = rewritten;
                Ok(())
            }
            TableOrSubquery::TableFunction { args, .. } => {
                for arg in args {
                    rewrite_dml_in_expr(arg, self, rewrite_in_subqueries, params)?;
                }
                Ok(())
            }
            TableOrSubquery::ParenJoin(from_clause) => {
                self.rewrite_dml_from_clause(from_clause, rewrite_in_subqueries, params)
            }
        }
    }

    fn rewrite_dml_select_source(
        &self,
        select: &SelectStatement,
        rewrite_in_subqueries: bool,
        params: Option<&[SqliteValue]>,
    ) -> Result<SelectStatement> {
        if select.with.is_some() {
            return Ok(select.clone());
        }
        if rewrite_in_subqueries {
            Ok(self
                .rewrite_in_subqueries_select(select, params)?
                .into_owned())
        } else {
            self.rewrite_subqueries(select, params)
        }
    }

    /// Maximum rows to materialize at once in the INSERT...SELECT fallback.
    /// Prevents OOM on large corpora by processing in bounded chunks.
    const INSERT_SELECT_CHUNK_SIZE: i64 = 10_000;

    #[allow(clippy::too_many_lines, clippy::significant_drop_tightening)]
    fn execute_insert_select_fallback(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        Ok(self
            .execute_insert_select_fallback_outcome(insert, select_stmt, params)?
            .changes)
    }

    fn execute_insert_select_fallback_returning(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        Ok(self
            .execute_insert_select_fallback_outcome(insert, select_stmt, params)?
            .returning_rows)
    }

    fn execute_insert_select_fallback_outcome(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<InsertSelectReplayOutcome> {
        let preserve_prior_changes_on_constraint_violation =
            insert.or_conflict == Some(fsqlite_ast::ConflictAction::Fail);
        let completed_changes = Cell::new(0usize);
        let completed_last_insert_rowid = Cell::new(None);
        let body_completed = Cell::new(false);
        let result = self.with_statement_fk_validation_scope(
            preserve_prior_changes_on_constraint_violation,
            || {
                let outcome = self.execute_insert_select_fallback_outcome_scoped(
                    insert,
                    select_stmt,
                    params,
                )?;
                completed_changes.set(outcome.changes);
                if outcome.changes > 0 {
                    completed_last_insert_rowid.set(Some(self.current_last_insert_rowid()));
                }
                body_completed.set(true);
                Ok(outcome)
            },
        );
        if result.is_err() && body_completed.get() {
            let statement_changes = completed_changes.get();
            self.record_table_program_error_state_with_total_changes(
                0,
                completed_last_insert_rowid.get(),
                Some(self.total_changes.get().saturating_sub(statement_changes)),
            );
        }
        result
    }

    fn execute_insert_select_fallback_outcome_scoped(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<InsertSelectReplayOutcome> {
        if let Some(changes) =
            self.try_execute_streaming_insert_select_fallback_outcome(insert, select_stmt, params)?
        {
            return Ok(changes);
        }
        // Fall back to single-shot materialization when chunking is unsafe:
        //  1. The SELECT already has a LIMIT — injecting LIMIT/OFFSET would
        //     change the query semantics.
        //  2. The INSERT has CTEs (WITH clause) — they may reference the
        //     target table indirectly, and we check the SELECT before CTE
        //     transfer so we'd miss that self-reference.
        //  3. The INSERT target table appears in the SELECT source tables
        //     (self-modifying query like INSERT INTO t SELECT FROM t).
        //     Chunking would cause each batch's SELECT to see rows inserted
        //     by prior batches, producing incorrect results.
        if select_stmt.limit.is_some() || insert.with.is_some() || {
            let target = &insert.table.name;
            let sources = Self::extract_table_names_from_select(select_stmt);
            sources.iter().any(|s| s.eq_ignore_ascii_case(target))
        } {
            let source_rows =
                self.materialize_insert_select_source_rows(insert, select_stmt, params)?;
            return self.execute_insert_select_materialized_rows_outcome(insert, &source_rows);
        }
        // Chunked materialization: wrap the source SELECT with LIMIT/OFFSET
        // and process in bounded batches to avoid OOM on large result sets.
        // Safe here because the source and destination tables are disjoint.
        let mut total_outcome = InsertSelectReplayOutcome::default();
        let mut offset: i64 = 0;
        loop {
            let mut chunked_select = select_stmt.clone();
            chunked_select.limit = Some(fsqlite_ast::LimitClause {
                limit: fsqlite_ast::Expr::Literal(
                    fsqlite_ast::Literal::Integer(Self::INSERT_SELECT_CHUNK_SIZE),
                    fsqlite_ast::Span::ZERO,
                ),
                offset: if offset > 0 {
                    Some(fsqlite_ast::Expr::Literal(
                        fsqlite_ast::Literal::Integer(offset),
                        fsqlite_ast::Span::ZERO,
                    ))
                } else {
                    None
                },
            });
            let source_rows =
                self.materialize_insert_select_source_rows(insert, &chunked_select, params)?;
            let chunk_len = source_rows.len();
            let chunk_outcome =
                self.execute_insert_select_materialized_rows_outcome(insert, &source_rows)?;
            total_outcome.changes = total_outcome.changes.saturating_add(chunk_outcome.changes);
            total_outcome
                .returning_rows
                .extend(chunk_outcome.returning_rows);
            // source_rows is dropped here, freeing memory before the next chunk.
            if (chunk_len as i64) < Self::INSERT_SELECT_CHUNK_SIZE {
                break;
            }
            offset += Self::INSERT_SELECT_CHUNK_SIZE;
        }
        Ok(total_outcome)
    }

    fn execute_materialized_insert_select_statement(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        source_rows: &[Row],
    ) -> Result<usize> {
        let was_auto = self.ensure_autocommit_txn()?;
        let preserve_prior_changes_on_constraint_violation =
            insert.or_conflict == Some(fsqlite_ast::ConflictAction::Fail);
        let use_statement_savepoint = self.should_use_statement_savepoint(
            was_auto,
            preserve_prior_changes_on_constraint_violation,
        );
        let result = if use_statement_savepoint {
            let cx = self.op_cx()?;
            self.with_internal_statement_savepoint_and_cx_policy(
                &cx,
                "insert_select",
                preserve_prior_changes_on_constraint_violation,
                || self.execute_insert_select_materialized_rows(insert, source_rows),
            )
        } else {
            self.execute_insert_select_materialized_rows(insert, source_rows)
        };
        let commit_autocommit_on_error = was_auto
            && matches!(
                result.as_ref(),
                Err(error) if error_preserves_prior_statement_rows(
                    preserve_prior_changes_on_constraint_violation,
                    error,
                )
            );
        let ok = result.is_ok() || commit_autocommit_on_error;
        self.resolve_autocommit_txn_with_capture(was_auto, ok, false)?;
        result
    }

    fn materialize_insert_select_source_rows(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        // If the INSERT has a WITH clause (CTEs), transfer it to the SELECT
        // so execute_statement will materialize the CTEs before evaluation.
        let effective_select = if let Some(ref with) = insert.with {
            let mut sel = select_stmt.clone();
            sel.with = Some(with.clone());
            sel
        } else {
            select_stmt.clone()
        };
        self.execute_statement(&Statement::Select(effective_select), params)
    }

    fn materialize_create_table_as_select_source_rows(
        &self,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        self.execute_statement(&Statement::Select(select_stmt.clone()), params)
    }

    fn infer_create_table_as_select_column_infos(
        &self,
        select_stmt: &fsqlite_ast::SelectStatement,
        rows: &[Row],
    ) -> Vec<ColumnInfo> {
        let col_names = self.select_result_column_names(select_stmt, &[], &mut Vec::new());
        let width = rows.first().map_or(
            if col_names.is_empty() {
                1
            } else {
                col_names.len()
            },
            |row| row.values().len(),
        );

        (0..width)
            .map(|i| {
                let affinity = rows
                    .iter()
                    .map(|row| row.values().get(i).cloned().unwrap_or(SqliteValue::Null))
                    .find(|value| !matches!(value, SqliteValue::Null))
                    .map_or('A', |value| match value {
                        SqliteValue::Integer(_) => 'D',
                        SqliteValue::Float(_) => 'E',
                        SqliteValue::Text(_) => 'B',
                        SqliteValue::Blob(_) | SqliteValue::Null => 'A',
                    });
                ColumnInfo {
                    name: col_names
                        .get(i)
                        .cloned()
                        .unwrap_or_else(|| format!("_c{i}")),
                    affinity,
                    is_ipk: false,
                    type_name: None,
                    notnull: false,
                    unique: false,
                    default_value: None,
                    strict_type: None,
                    generated_expr: None,
                    generated_stored: None,
                    collation: None,
                    conflict_action: None,
                }
            })
            .collect()
    }

    fn execute_materialized_create_table_as_select_statement(
        &self,
        create: &fsqlite_ast::CreateTableStatement,
        col_infos: Vec<ColumnInfo>,
        rows: &[Row],
    ) -> Result<()> {
        if create.strict {
            return Err(FrankenError::NotImplemented(
                "CREATE TABLE ... AS SELECT ... STRICT is not yet supported".to_owned(),
            ));
        }
        let table_name = create.name.name.clone();

        if self.schema_index_of(&table_name).is_some() {
            if create.if_not_exists {
                return Ok(());
            }
            return Err(FrankenError::Internal(format!(
                "table {table_name} already exists",
            )));
        }

        let width = col_infos.len();
        let root_page = self.allocate_root_page()?;
        self.db.borrow_mut().create_table_at(root_page, width);
        let table_schema = TableSchema {
            name: table_name,
            root_page,
            columns: col_infos,
            indexes: Vec::new(),
            strict: false,
            without_rowid: false,
            primary_key_constraints: Vec::new(),
            foreign_keys: Vec::new(),
            check_constraints: Vec::new(),
        };
        let create_sql = crate::compat_persist::build_create_table_sql(&table_schema);
        let root_page = table_schema.root_page;
        let table_name = table_schema.name.clone();
        self.schema.borrow_mut().push(table_schema);
        self.rebuild_schema_indices();
        if !rows.is_empty() {
            let placeholders: String = (1..=width)
                .map(|i| format!("?{i}"))
                .collect::<Vec<_>>()
                .join(", ");
            let insert_sql = format!("INSERT INTO \"{table_name}\" VALUES ({placeholders})");
            for row in rows {
                self.execute_with_params(&insert_sql, row.values())?;
            }
        }
        self.insert_sqlite_master_row("table", &table_name, &table_name, root_page, &create_sql)?;
        self.increment_schema_cookie()?;
        Ok(())
    }

    fn materialize_insert_values_source_rows(
        &self,
        rows: &[Vec<Expr>],
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        rows.iter()
            .map(|row_exprs| {
                Ok(Row {
                    values: self.evaluate_insert_source_row(row_exprs, params)?,
                })
            })
            .collect()
    }

    fn execute_insert_select_materialized_rows(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        source_rows: &[Row],
    ) -> Result<usize> {
        Ok(self
            .execute_insert_select_materialized_rows_outcome(insert, source_rows)?
            .changes)
    }

    fn execute_insert_select_materialized_rows_outcome(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        source_rows: &[Row],
    ) -> Result<InsertSelectReplayOutcome> {
        self.execute_insert_select_row_stream(insert, |emit_row| {
            for row in source_rows {
                emit_row(row.values())?;
            }
            Ok(())
        })
    }

    /// bd-xb07w: morsel-driven INSERT dispatch. Splits materialized rows into
    /// fixed-size morsels via [`MorselScheduler`] and executes each batch
    /// through the row-stream replay mechanism. Currently sequential; the
    /// morsel split validates the wiring and prepares for future parallel
    /// worker dispatch via `asupersync`.
    fn execute_morsel_insert(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        source_rows: Vec<Row>,
    ) -> Result<usize> {
        let total_rows = source_rows.len();
        let scheduler = MorselScheduler::new(1, MORSEL_INSERT_SIZE);
        let value_rows: Vec<Vec<SqliteValue>> = source_rows.into_iter().map(|r| r.values).collect();
        let morsels = scheduler.split_into_morsels(0, 0, value_rows);
        let mut total_changes = 0usize;
        for morsel in &morsels {
            let morsel_rows: Vec<Row> = morsel
                .rows
                .iter()
                .map(|values| Row {
                    values: values.clone(),
                })
                .collect();
            total_changes += self.execute_insert_select_materialized_rows(insert, &morsel_rows)?;
        }
        debug_assert_eq!(
            total_changes, total_rows,
            "morsel INSERT should affect exactly as many rows as input"
        );
        Ok(total_changes)
    }

    fn build_insert_select_replay_sql(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        layout: &InsertTargetLayout,
    ) -> String {
        let qualified_table = quote_qualified_name(&insert.table);
        let placeholders = (1..=layout.table_columns.len()).map(|idx| format!("?{idx}"));
        let conflict_clause = match &insert.or_conflict {
            Some(fsqlite_ast::ConflictAction::Replace) => "OR REPLACE ",
            Some(fsqlite_ast::ConflictAction::Ignore) => "OR IGNORE ",
            Some(fsqlite_ast::ConflictAction::Abort) => "OR ABORT ",
            Some(fsqlite_ast::ConflictAction::Fail) => "OR FAIL ",
            Some(fsqlite_ast::ConflictAction::Rollback) => "OR ROLLBACK ",
            None => "",
        };
        let returning_clause = if insert.returning.is_empty() {
            String::new()
        } else {
            format!(
                " RETURNING {}",
                insert
                    .returning
                    .iter()
                    .map(std::string::ToString::to_string)
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        };
        let insert_sql = if insert.columns.is_empty() {
            let placeholders = placeholders.collect::<Vec<_>>().join(", ");
            let upsert_sql = insert
                .upsert
                .iter()
                .map(std::string::ToString::to_string)
                .collect::<Vec<_>>()
                .join(" ");
            if upsert_sql.is_empty() {
                format!(
                    "INSERT {conflict_clause}INTO {qualified_table} VALUES ({placeholders}){returning_clause};"
                )
            } else {
                format!(
                    "INSERT {conflict_clause}INTO {qualified_table} VALUES ({placeholders}) {upsert_sql}{returning_clause};"
                )
            }
        } else {
            let quoted_targets = insert
                .columns
                .iter()
                .map(|column| quote_identifier(column))
                .collect::<Vec<_>>()
                .join(", ");
            let placeholders = (1..=layout.targets.len())
                .map(|idx| format!("?{idx}"))
                .collect::<Vec<_>>()
                .join(", ");
            let upsert_sql = insert
                .upsert
                .iter()
                .map(std::string::ToString::to_string)
                .collect::<Vec<_>>()
                .join(" ");
            if upsert_sql.is_empty() {
                format!(
                    "INSERT {conflict_clause}INTO {qualified_table} ({quoted_targets}) VALUES ({placeholders}){returning_clause};"
                )
            } else {
                format!(
                    "INSERT {conflict_clause}INTO {qualified_table} ({quoted_targets}) VALUES ({placeholders}) {upsert_sql}{returning_clause};"
                )
            }
        };

        insert_sql
    }

    fn execute_insert_select_row_stream<F>(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        mut producer: F,
    ) -> Result<InsertSelectReplayOutcome>
    where
        F: FnMut(&mut dyn FnMut(&[SqliteValue]) -> Result<()>) -> Result<()>,
    {
        let layout = self.resolve_insert_target_layout(insert)?;
        if layout.table_columns.is_empty() {
            return Err(FrankenError::Internal(format!(
                "table '{}' has no insertable columns",
                insert.table.name
            )));
        }
        let source_column_count = layout.targets.len();
        let insert_sql = self.build_insert_select_replay_sql(insert, &layout);
        let collect_returning = !insert.returning.is_empty();
        let preserve_prior_changes_on_constraint_violation =
            insert.or_conflict == Some(fsqlite_ast::ConflictAction::Fail);
        let completed_statement_changes = Cell::new(0usize);
        let completed_statement_last_insert_rowid = Cell::new(None);
        let replay_error_recorded = Cell::new(false);
        let mut execute_rows = || -> Result<InsertSelectReplayOutcome> {
            let result = self.with_statement_fk_validation_scope(
                preserve_prior_changes_on_constraint_violation,
                || {
                    let _fk_parent_validation_cache =
                        self.enter_fk_parent_validation_cache_scope(&insert.table.name);
                    let prepared = if collect_returning {
                        None
                    } else {
                        Some(self.prepare_after_background_status(&insert_sql)?)
                    };
                    let returning_statement = if collect_returning {
                        Some(parse_single_statement(&insert_sql)?)
                    } else {
                        None
                    };
                    let mut statement_changes = 0usize;
                    let mut returning_rows = Vec::new();
                    let mut produced_rows = 0usize;
                    let mut error_state_recorded = false;
                    let record_error_state =
                        |statement_changes: usize, error: &FrankenError| {
                            if error_preserves_prior_statement_rows(
                                preserve_prior_changes_on_constraint_violation,
                                error,
                            ) {
                                self.set_statement_change_count(statement_changes);
                                self.record_table_program_error_state_with_total_changes(
                                    statement_changes,
                                    (statement_changes > 0)
                                        .then(|| self.current_last_insert_rowid()),
                                    Some(self.total_changes.get()),
                                );
                            } else {
                                // ABORT/ROLLBACK undo the outer statement's
                                // rows, but SQLite still exposes the rowid of
                                // the last successful outer INSERT and retains
                                // total_changes contributions from completed
                                // nested trigger statements.
                                self.set_statement_change_count(0);
                                self.record_table_program_error_state_with_total_changes(
                                    0,
                                    (statement_changes > 0)
                                        .then(|| self.current_last_insert_rowid()),
                                    Some(
                                        self.total_changes
                                            .get()
                                            .saturating_sub(statement_changes),
                                    ),
                                );
                            }
                        };
                    let mut emit_row = |row_values: &[SqliteValue]| -> Result<()> {
                        let row_idx = produced_rows;
                        produced_rows = produced_rows.saturating_add(1);
                        if row_values.len() != source_column_count {
                            return Err(FrankenError::Internal(format!(
                                "INSERT ... SELECT column count mismatch: source row {row_idx} has {} values, SELECT produced {source_column_count}",
                                row_values.len()
                            )));
                        }
                        let row_result =
                            if let Some(returning_statement) = returning_statement.as_ref() {
                                self.execute_statement_impl_after_background_status(
                                    returning_statement,
                                    Some(row_values),
                                    None,
                                )
                                .map(|rows| {
                                    let affected = self.last_changes.get();
                                    returning_rows.extend(rows);
                                    affected
                                })
                            } else {
                                self.execute_prepared_with_params_after_background_status(
                                    prepared.as_ref().ok_or_else(|| {
                                        FrankenError::internal(
                                            "INSERT ... SELECT replay missing prepared statement",
                                        )
                                    })?,
                                    row_values,
                                    false,
                                )
                            };
                        match row_result {
                            Ok(affected) => {
                                statement_changes = statement_changes.saturating_add(affected);
                                completed_statement_changes.set(statement_changes);
                                if affected > 0 {
                                    completed_statement_last_insert_rowid
                                        .set(Some(self.current_last_insert_rowid()));
                                }
                                Ok(())
                            }
                            Err(error) => {
                                error_state_recorded = true;
                                replay_error_recorded.set(true);
                                record_error_state(statement_changes, &error);
                                Err(error)
                            }
                        }
                    };
                    if let Err(error) = producer(&mut emit_row) {
                        if !error_state_recorded {
                            replay_error_recorded.set(true);
                            record_error_state(statement_changes, &error);
                        }
                        return Err(error);
                    }
                    self.set_statement_change_count(statement_changes);
                    Ok(InsertSelectReplayOutcome {
                        changes: statement_changes,
                        returning_rows,
                    })
                },
            );
            // A statement-boundary FK validation error happens after every
            // physical row replayed successfully, so the per-row error branch
            // above never records it.  Preserve SQLite's attempted-insert
            // rowid while excluding rolled-back outer rows from total_changes.
            if result.is_err() && !replay_error_recorded.get() {
                let statement_changes = completed_statement_changes.get();
                self.record_table_program_error_state_with_total_changes(
                    0,
                    completed_statement_last_insert_rowid.get(),
                    Some(self.total_changes.get().saturating_sub(statement_changes)),
                );
            }
            result
        };

        if self.active_txn.borrow().is_some() && self.internal_statement_savepoint_depth.get() == 0
        {
            let cx = self.op_cx()?;
            self.with_internal_statement_savepoint_and_cx_policy(
                &cx,
                "insert_select",
                preserve_prior_changes_on_constraint_violation,
                execute_rows,
            )
        } else {
            execute_rows()
        }
    }

    fn try_execute_streaming_insert_select_fallback_outcome(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<InsertSelectReplayOutcome>> {
        if insert.with.is_some() {
            return Ok(None);
        }
        let mut streamed = false;
        let outcome = self.execute_insert_select_row_stream(insert, |emit_row| {
            streamed =
                self.try_stream_simple_join_select_rows(select_stmt, params, |source_row| {
                    emit_row(source_row)
                })?;
            Ok(())
        })?;
        if streamed {
            Ok(Some(outcome))
        } else {
            Ok(None)
        }
    }

    fn try_stream_simple_join_select_rows_with_scanner<F, S>(
        &self,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
        scan_source_rows: S,
        mut emit_row: F,
    ) -> Result<bool>
    where
        F: FnMut(&[SqliteValue]) -> Result<()>,
        S: FnMut(&JoinTableSource) -> Result<Option<Vec<Vec<SqliteValue>>>>,
    {
        let prep_cx = self.op_cx_after_background_status();
        self.prepare_streaming_join_select_read_boundary(select_stmt, &prep_cx)?;
        let Some(prepared) = self.prepare_simple_join_select_rows_with_scanner(
            select_stmt,
            params,
            scan_source_rows,
            |table_name| self.has_live_vtab_instance(table_name),
        )?
        else {
            return Ok(false);
        };
        self.emit_prepared_simple_join_rows(&prepared, |row| emit_row(row))?;
        Ok(true)
    }

    fn prepare_streaming_join_select_read_boundary(
        &self,
        select_stmt: &fsqlite_ast::SelectStatement,
        cx: &Cx,
    ) -> Result<()> {
        let pending_memdb_direct_upserts = !self.pending_memdb_direct_upserts.borrow().is_empty();
        let should_refresh_active_txn_memdb = self.active_txn.borrow().is_some()
            && (self.memdb_requires_active_txn_reload.get()
                || pending_memdb_direct_upserts
                || !self.memdb_rows_loaded.get()
                || !self.memdb_storage_count_shortcuts_safe.get());
        if should_refresh_active_txn_memdb {
            self.refresh_memdb_from_active_txn_if_dirty(cx)?;
        }

        self.refresh_memdb_from_cached_write_txn_if_stale(cx)?;

        if self.retained_autocommit_txn.borrow().is_some() {
            let read_tables = Self::extract_table_names_from_select(select_stmt);
            if self.retained_autocommit_has_dirty_overlap(&read_tables) {
                self.flush_retained_autocommit_txn_for_read(cx)?;
            }
        }

        if self.pager.is_memory() {
            // :memory: read boundaries must not blindly reload from pager
            // because a parked local txn may still be authoritative. The
            // targeted repairs above are the safe fast path for this mode.
            return Ok(());
        }

        if self.local_transaction_scope_is_active() {
            // Inside an explicit transaction, the pager's published snapshot
            // does not contain uncommitted DDL changes (CREATE TABLE, DROP
            // TABLE, ALTER TABLE).  Reloading from the pager here would
            // overwrite the in-memory schema with pre-transaction state,
            // causing subsequent DML against newly-created tables to fail
            // with "no such table".  The active-txn refresh above already
            // handled any pending reload from the transaction's own pages.
            return Ok(());
        }

        if !self.memdb_rows_loaded.get() {
            self.reload_memdb_from_pager(cx)
        } else {
            self.refresh_memdb_if_stale(cx)
        }
    }

    fn prepare_simple_join_select_rows_with_scanner<S>(
        &self,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
        mut scan_source_rows: S,
        mut is_live_vtab: impl FnMut(&str) -> bool,
    ) -> Result<Option<PreparedStreamingJoinRows>>
    where
        S: FnMut(&JoinTableSource) -> Result<Option<Vec<Vec<SqliteValue>>>>,
    {
        if select_stmt.with.is_some() {
            return Ok(None);
        }
        let bound_select = bind_placeholders_in_select_for_fallback(select_stmt, params)?;
        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            windows,
        } = &bound_select.body.select
        else {
            return Ok(None);
        };
        if *distinct != Distinctness::All
            || !bound_select.body.compounds.is_empty()
            || where_clause.is_some()
            || !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
            || bound_select.limit.is_some()
        {
            return Ok(None);
        }

        let mut active_ctes = Vec::new();
        let mut resolve_table_source = |source: &TableOrSubquery| -> Option<JoinTableSource> {
            let TableOrSubquery::Table { name, alias, .. } = source else {
                return None;
            };
            if is_live_vtab(&name.name) {
                return None;
            }
            let col_names =
                self.table_or_subquery_result_column_names(source, &[], &mut active_ctes);
            Some(JoinTableSource {
                binding_name: Some(name.clone()),
                scan_cache_key: join_scan_cache_key(name),
                table_name: name.name.clone(),
                alias: alias.clone(),
                hidden_rowid_projection: join_hidden_rowid_projection(
                    &col_names,
                    self.join_table_supports_hidden_rowid_for_binding(name),
                ),
                col_names,
            })
        };

        let mut table_sources = Vec::with_capacity(1 + from.joins.len());
        let Some(primary_source) = resolve_table_source(&from.source) else {
            return Ok(None);
        };
        table_sources.push(primary_source);
        let mut all_inner_joins = true;
        for join in &from.joins {
            if join.join_type.natural
                || !matches!(join.join_type.kind, JoinKind::Inner | JoinKind::Left)
                || !matches!(join.constraint, Some(JoinConstraint::On(_)))
            {
                return Ok(None);
            }
            if !matches!(join.join_type.kind, JoinKind::Inner) {
                all_inner_joins = false;
            }
            let Some(source) = resolve_table_source(&join.table) else {
                return Ok(None);
            };
            table_sources.push(source);
        }

        // PLANNER-3: reorder inner equi-joins by ascending scan cost using
        // sqlite_stat1 hints. Permutes table_sources, all_sources,
        // col_map/col_collations, table_rows, and join_plans in tandem.
        // ON constraints are greedy-matched to the permuted order via
        // try_extract_equi_join_indices; infeasible permutations bail out.
        let mut join_order_permutation: Option<Vec<usize>> = None;
        if all_inner_joins && table_sources.len() >= 2 {
            let row_hints = self.sqlite_stat1_row_counts();
            let refs: Vec<fsqlite_planner::TableRefWithStats> = table_sources
                .iter()
                .map(|source| {
                    let key = source.table_name.to_ascii_lowercase();
                    let n_rows = row_hints.get(&key).copied().unwrap_or(0);
                    let has_stats = row_hints.contains_key(&key);
                    // `n_pages` is a best-effort estimate: we approximate it
                    // from `n_rows` (the planner's cost model already
                    // tolerates coarse page counts). A precise page count
                    // requires pager introspection which we defer to the
                    // reshape follow-up.
                    let n_pages = n_rows.max(1);
                    fsqlite_planner::TableRefWithStats {
                        name: source.table_name.clone(),
                        n_pages,
                        n_rows,
                        has_stats,
                    }
                })
                .collect();
            let permutation = fsqlite_planner::order_join_inputs_with_hints(&refs);
            let is_identity = permutation.iter().enumerate().all(|(i, &p)| i == p);
            if !is_identity {
                let all_have_on = from
                    .joins
                    .iter()
                    .all(|j| matches!(j.constraint, Some(JoinConstraint::On(_))));
                if all_have_on {
                    let mut permuted_sources: Vec<JoinTableSource> =
                        Vec::with_capacity(table_sources.len());
                    for &idx in &permutation {
                        permuted_sources.push(table_sources[idx].clone());
                    }
                    table_sources = permuted_sources;
                    join_order_permutation = Some(permutation.clone());
                    tracing::debug!(
                        target: "fsqlite::planner",
                        permutation = ?permutation,
                        n_tables = table_sources.len(),
                        "PLANNER-3: applied join-order permutation"
                    );
                }
            }
        }

        let requires_primary_rowid_order = match bound_select.order_by.as_slice() {
            [] => false,
            [term]
                if Self::streaming_insert_select_orders_by_primary_rowid(
                    term,
                    &table_sources[0],
                ) =>
            {
                true
            }
            _ => return Ok(None),
        };

        let all_sources: Vec<&TableOrSubquery> = {
            let ast_order: Vec<&TableOrSubquery> = std::iter::once(&from.source)
                .chain(from.joins.iter().map(|join| &join.table))
                .collect();
            if let Some(ref perm) = join_order_permutation {
                perm.iter().map(|&idx| ast_order[idx]).collect()
            } else {
                ast_order
            }
        };

        let mut col_map: Vec<(String, String, bool)> = Vec::with_capacity(table_sources.len());
        for source in &table_sources {
            let label = source.alias.as_deref().unwrap_or(&source.table_name);
            for column_name in &source.col_names {
                col_map.push((label.to_owned(), column_name.clone(), false));
            }
            if source.hidden_rowid_projection.is_some() {
                col_map.push((label.to_owned(), "rowid".to_owned(), true));
            }
        }

        let mut projection_indices = Vec::with_capacity(columns.len());
        for column in columns {
            let ResultColumn::Expr {
                expr: Expr::Column(col_ref, _),
                ..
            } = column
            else {
                return Ok(None);
            };
            let Ok(index) =
                find_col_in_map(&col_map, col_ref.table.as_deref(), &col_ref.column, None)
            else {
                return Ok(None);
            };
            projection_indices.push(index);
        }

        let schema_snapshot = self.schema.borrow().clone();
        let mut col_collations = Vec::with_capacity(col_map.len());
        for (index, source) in all_sources.iter().enumerate() {
            let mut source_collations =
                table_or_subquery_result_collations(source, &schema_snapshot);
            source_collations.resize(table_sources[index].col_names.len(), None);
            source_collations.truncate(table_sources[index].col_names.len());
            col_collations.extend(source_collations);
            if table_sources[index].hidden_rowid_projection.is_some() {
                col_collations.push(None);
            }
        }
        let _join_eval_collation_guard =
            JoinEvalCollationContextGuard::push(JoinEvalCollationContext {
                column_collations: col_collations,
                column_affinities: col_affinities_for_sources(
                    &all_sources,
                    &table_sources,
                    &schema_snapshot,
                ),
                registry: lock_unpoisoned(self.collation_registry.as_ref()).clone(),
            });

        let mut scanned_cache: HashMap<String, Vec<Vec<SqliteValue>>> = HashMap::new();
        let mut table_rows: Vec<Vec<Vec<SqliteValue>>> = Vec::with_capacity(table_sources.len());
        for (index, source) in table_sources.iter().enumerate() {
            if let Some(cached) = scanned_cache.get(&source.scan_cache_key) {
                table_rows.push(cached.clone());
                continue;
            }
            let Some(row_data) = scan_source_rows(source)? else {
                return Ok(None);
            };
            let might_reuse = table_sources[index + 1..]
                .iter()
                .any(|later| later.scan_cache_key.eq(&source.scan_cache_key));
            if might_reuse {
                scanned_cache.insert(source.scan_cache_key.clone(), row_data.clone());
            }
            table_rows.push(row_data);
        }
        if requires_primary_rowid_order {
            let primary_width = table_sources[0].scan_width();
            let rowid_index = primary_width.saturating_sub(1);
            table_rows[0].sort_by(|left, right| {
                let left_rowid = left
                    .get(rowid_index)
                    .map(SqliteValue::to_integer)
                    .unwrap_or_default();
                let right_rowid = right
                    .get(rowid_index)
                    .map(SqliteValue::to_integer)
                    .unwrap_or_default();
                left_rowid.cmp(&right_rowid)
            });
        }

        let mut join_plans = Vec::with_capacity(from.joins.len());
        if join_order_permutation.is_some() {
            let on_exprs: Vec<&Expr> = from
                .joins
                .iter()
                .filter_map(|j| match &j.constraint {
                    Some(JoinConstraint::On(expr)) => Some(expr),
                    _ => None,
                })
                .collect();
            let mut used = vec![false; on_exprs.len()];
            for join_idx in 0..from.joins.len() {
                let left_width: usize = table_sources[..=join_idx]
                    .iter()
                    .map(JoinTableSource::scan_width)
                    .sum();
                let mut matched = false;
                for (on_idx, on_expr) in on_exprs.iter().enumerate() {
                    if used[on_idx] {
                        continue;
                    }
                    let Some(equi_pairs) =
                        try_extract_equi_join_indices(on_expr, &col_map, left_width)
                    else {
                        continue;
                    };
                    if !join_hash_pairs_are_binary(&equi_pairs, left_width) {
                        continue;
                    }
                    used[on_idx] = true;
                    let right_rows = &table_rows[join_idx + 1];
                    join_plans.push(StreamingHashJoinPlan {
                        left_width,
                        right_width: table_sources[join_idx + 1].scan_width(),
                        kind: JoinKind::Inner,
                        equi_pairs: equi_pairs.clone(),
                        right_index: build_streaming_hash_join_index(right_rows, &equi_pairs),
                    });
                    matched = true;
                    break;
                }
                if !matched {
                    return Ok(None);
                }
            }
        } else {
            for (join_idx, join) in from.joins.iter().enumerate() {
                let Some(JoinConstraint::On(expr)) = join.constraint.as_ref() else {
                    return Ok(None);
                };
                let left_width: usize = table_sources[..=join_idx]
                    .iter()
                    .map(JoinTableSource::scan_width)
                    .sum();
                let Some(equi_pairs) = try_extract_equi_join_indices(expr, &col_map, left_width)
                else {
                    return Ok(None);
                };
                if !join_hash_pairs_are_binary(&equi_pairs, left_width) {
                    return Ok(None);
                }
                let right_rows = &table_rows[join_idx + 1];
                join_plans.push(StreamingHashJoinPlan {
                    left_width,
                    right_width: table_sources[join_idx + 1].scan_width(),
                    kind: join.join_type.kind,
                    equi_pairs: equi_pairs.clone(),
                    right_index: build_streaming_hash_join_index(right_rows, &equi_pairs),
                });
            }
        }

        let total_width: usize = table_sources.iter().map(JoinTableSource::scan_width).sum();
        let primary_width = table_sources[0].scan_width();
        Ok(Some(PreparedStreamingJoinRows {
            projection_indices,
            table_rows,
            join_plans,
            total_width,
            primary_width,
        }))
    }

    fn emit_prepared_simple_join_rows<F>(
        &self,
        prepared: &PreparedStreamingJoinRows,
        mut emit_row: F,
    ) -> Result<()>
    where
        F: FnMut(&[SqliteValue]) -> Result<()>,
    {
        let mut projected_row = Vec::with_capacity(prepared.projection_indices.len());
        self.emit_prepared_simple_join_rows_raw(prepared, |joined_row| {
            projected_row.clear();
            for &projection_index in &prepared.projection_indices {
                projected_row.push(
                    joined_row
                        .get(projection_index)
                        .cloned()
                        .unwrap_or(SqliteValue::Null),
                );
            }
            emit_row(&projected_row)
        })
    }

    fn emit_prepared_simple_join_rows_raw<F>(
        &self,
        prepared: &PreparedStreamingJoinRows,
        mut emit_row: F,
    ) -> Result<()>
    where
        F: FnMut(&[SqliteValue]) -> Result<()>,
    {
        let mut current_row = Vec::with_capacity(prepared.total_width);
        for primary_row in &prepared.table_rows[0] {
            current_row.clear();
            current_row.extend_from_slice(&primary_row[..prepared.primary_width]);
            stream_hash_join_rows(
                &mut current_row,
                0,
                &prepared.join_plans,
                &prepared.table_rows,
                &mut |joined_row| emit_row(joined_row),
            )?;
        }
        Ok(())
    }

    fn try_stream_simple_join_select_rows<F>(
        &self,
        select_stmt: &fsqlite_ast::SelectStatement,
        params: Option<&[SqliteValue]>,
        mut emit_row: F,
    ) -> Result<bool>
    where
        F: FnMut(&[SqliteValue]) -> Result<()>,
    {
        self.try_stream_simple_join_select_rows_with_scanner(
            select_stmt,
            params,
            |source| {
                if let Some(row_data) = self.try_scan_join_source_from_memdb(source) {
                    return Ok(Some(row_data));
                }
                if let Some(result) = self.try_scan_join_source_from_pager(source) {
                    return Ok(Some(result?));
                }
                let scan_sql = build_join_scan_sql(source);
                let rows = self.query(&scan_sql)?;
                Ok(Some(rows_into_value_vectors(rows)))
            },
            |row| emit_row(row),
        )
    }

    fn validate_insert_target_columns(
        table_schema: &TableSchema,
        table_name: &str,
        insert_columns: &[String],
    ) -> Result<()> {
        if insert_columns.is_empty() {
            return Ok(());
        }

        for column in insert_columns {
            let Some(idx) = table_schema.column_index(column) else {
                if is_hidden_rowid_alias_name(column) {
                    continue;
                }
                return Err(FrankenError::Internal(format!(
                    "column '{column}' not found in table '{table_name}'"
                )));
            };
            // Generated (VIRTUAL/STORED) columns are read-only: SQLite rejects
            // any attempt to supply a value for one in an INSERT column list
            // ("cannot INSERT into generated column"). (bd-txni0)
            let col = &table_schema.columns[idx];
            if col.generated_expr.is_some() || col.generated_stored.is_some() {
                return Err(FrankenError::Internal(format!(
                    "cannot INSERT into generated column \"{column}\""
                )));
            }
        }

        Ok(())
    }

    /// Handle INSERT OR REPLACE / INSERT OR IGNORE for VALUES source by
    /// evaluating each row, resolving the INTEGER PRIMARY KEY rowid, and
    /// applying conflict resolution directly on the in-memory database.
    #[allow(dead_code)]
    #[allow(clippy::too_many_lines)]
    fn execute_insert_or_conflict(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        rows: &[Vec<Expr>],
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        use fsqlite_ast::ConflictAction;

        let conflict = insert
            .or_conflict
            .as_ref()
            .ok_or_else(|| FrankenError::Internal("expected or_conflict".to_owned()))?;

        let table_name = &insert.table.name;
        let schema = self.schema.borrow();
        let table_schema = schema
            .iter()
            .find(|t| t.name.eq_ignore_ascii_case(table_name))
            .ok_or_else(|| FrankenError::Internal(format!("no such table: {table_name}")))?
            .clone();
        Self::validate_insert_target_columns(&table_schema, table_name, &insert.columns)?;
        let root_page = table_schema.root_page;
        let num_cols = table_schema.columns.len();

        // Determine which VALUES position maps to the INTEGER PRIMARY KEY
        // column so we can extract the user-supplied rowid.
        let ipk_col_idx = self
            .rowid_alias_columns
            .borrow()
            .get(&table_name.to_ascii_lowercase())
            .copied();
        // Map from VALUES position to table target.
        let target_map: Vec<InsertTarget> = if insert.columns.is_empty() {
            (0..num_cols).map(InsertTarget::Column).collect()
        } else {
            insert
                .columns
                .iter()
                .map(|col| {
                    if let Some(index) = table_schema.column_index(col) {
                        Ok(InsertTarget::Column(index))
                    } else if is_hidden_rowid_alias_name(col) {
                        Ok(InsertTarget::HiddenRowid)
                    } else {
                        Err(FrankenError::Internal(format!(
                            "column '{col}' not found in table '{table_name}'"
                        )))
                    }
                })
                .collect::<Result<Vec<_>>>()?
        };
        // Which VALUES position (if any) maps to the rowid family target.
        let ipk_values_pos = target_map.iter().rposition(|target| match target {
            InsertTarget::HiddenRowid => true,
            InsertTarget::Column(index) => Some(*index) == ipk_col_idx,
        });

        drop(schema);

        let mut affected = 0usize;

        for row_exprs in rows {
            // Evaluate the row expressions by wrapping them in a SELECT.
            let expr_strs: Vec<String> = row_exprs.iter().map(|e| format!("{e}")).collect();
            let select_sql = format!("SELECT {}", expr_strs.join(", "));
            let eval_rows = if let Some(p) = params {
                self.query_with_params(&select_sql, p)?
            } else {
                self.query(&select_sql)?
            };
            let values: Vec<SqliteValue> = eval_rows
                .first()
                .map(|r| r.values().to_vec())
                .unwrap_or_default();

            // Extract the user-supplied rowid from the IPK column (if any).
            let explicit_rowid = ipk_values_pos
                .and_then(|pos| values.get(pos))
                .map(Self::coerce_insert_rowid_value)
                .transpose()?
                .flatten();

            // Build the full column value vector in table order. For ordinary
            // columns, duplicate targets keep the first assignment like SQLite.
            let mut col_values = vec![SqliteValue::Null; num_cols];
            let mut filled_columns = vec![false; num_cols];
            for (val_pos, target) in target_map.iter().enumerate() {
                let Some(v) = values.get(val_pos) else {
                    continue;
                };
                let InsertTarget::Column(tgt) = target else {
                    continue;
                };
                if Some(*tgt) == ipk_col_idx || filled_columns[*tgt] {
                    continue;
                }
                col_values[*tgt] = v.clone();
                filled_columns[*tgt] = true;
            }
            if let (Some(ipk_idx), Some(rowid)) = (ipk_col_idx, explicit_rowid) {
                col_values[ipk_idx] = SqliteValue::Integer(rowid);
            }

            // Verify we don't silently ignore STORED generated columns in the fallback path.
            for col_info in &table_schema.columns {
                if col_info.generated_stored == Some(true) {
                    return Err(FrankenError::NotImplemented(
                        "STORED generated columns are not yet supported in the INSERT OR REPLACE fallback path".to_owned()
                    ));
                }
            }

            let mut db = self.db.borrow_mut();
            if db.get_table(root_page).is_none() {
                return Err(FrankenError::Internal(format!(
                    "table not found at root page {root_page}"
                )));
            }

            // Check UNIQUE constraints on columns.
            let mut unique_violation_col: Option<String> = None;
            let mut conflicting_rowids = std::collections::BTreeSet::new();
            if let Some(table) = db.get_table(root_page) {
                let coll_snapshot = lock_unpoisoned(self.collation_registry.as_ref()).clone();
                // 1. Column-level UNIQUE constraints.
                for (i, col_info) in table_schema.columns.iter().enumerate() {
                    if col_info.unique && !col_info.is_ipk {
                        let new_val = &col_values[i];
                        if !new_val.is_null() {
                            for mem_row in table.iter_rows() {
                                if Some(mem_row.0) == explicit_rowid {
                                    continue; // Replacing this rowid.
                                }
                                if let Some(existing_val) = mem_row.1.get(i) {
                                    if cmp_sqlite_values_collated_snapshot(
                                        existing_val,
                                        new_val,
                                        col_info.collation.as_deref(),
                                        &coll_snapshot,
                                    ) == std::cmp::Ordering::Equal
                                    {
                                        if *conflict == ConflictAction::Replace {
                                            conflicting_rowids.insert(mem_row.0);
                                        } else {
                                            unique_violation_col = Some(col_info.name.clone());
                                        }
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    if unique_violation_col.is_some() {
                        break;
                    }
                }

                // 2. Index-level UNIQUE constraints (CREATE UNIQUE INDEX).
                if unique_violation_col.is_none() {
                    for idx in &table_schema.indexes {
                        if !idx.is_unique {
                            continue;
                        }
                        // Resolve index column names to positions in the table.
                        let idx_positions: Vec<usize> = idx
                            .columns
                            .iter()
                            .filter_map(|c| table_schema.column_index(c))
                            .collect();
                        if idx_positions.len() != idx.columns.len() {
                            continue; // Column resolution failed, skip.
                        }
                        // If any indexed value is NULL, skip (NULL is unique).
                        if idx_positions.iter().any(|&pos| col_values[pos].is_null()) {
                            continue;
                        }
                        let new_key: Vec<&SqliteValue> =
                            idx_positions.iter().map(|&pos| &col_values[pos]).collect();

                        for mem_row in table.iter_rows() {
                            if Some(mem_row.0) == explicit_rowid {
                                continue;
                            }
                            let keys_match = idx_positions.iter().enumerate().all(
                                |(key_idx, &pos)| match mem_row.1.get(pos) {
                                    Some(existing_value) => {
                                        let collation = idx
                                            .key_collations
                                            .get(key_idx)
                                            .and_then(|value| value.as_deref());
                                        cmp_sqlite_values_collated_snapshot(
                                            existing_value,
                                            new_key[key_idx],
                                            collation,
                                            &coll_snapshot,
                                        ) == std::cmp::Ordering::Equal
                                    }
                                    None => false,
                                },
                            );
                            if keys_match {
                                if *conflict == ConflictAction::Replace {
                                    conflicting_rowids.insert(mem_row.0);
                                } else {
                                    unique_violation_col = Some(idx.key_label());
                                }
                                break;
                            }
                        }
                        if unique_violation_col.is_some() {
                            break;
                        }
                    }
                }
            }

            if let Some(col_name) = unique_violation_col {
                if *conflict == ConflictAction::Ignore {
                    continue;
                }
                return Err(FrankenError::UniqueViolation {
                    columns: format!("{}.{}", table_name, col_name),
                });
            }

            // For REPLACE: delete rows that conflict on non-IPK UNIQUE columns.
            if *conflict == ConflictAction::Replace && !conflicting_rowids.is_empty() {
                for rid in conflicting_rowids {
                    db.delete_rowid(root_page, rid);
                }
            }

            if let Some(rowid) = explicit_rowid {
                let exists = db
                    .get_table(root_page)
                    .and_then(|t| t.find_by_rowid(rowid))
                    .is_some();

                match conflict {
                    ConflictAction::Replace => {
                        if let Some(ipk_idx) = ipk_col_idx {
                            col_values[ipk_idx] = SqliteValue::Integer(rowid);
                        }
                        db.upsert_row(root_page, rowid, col_values);
                        self.record_last_insert_rowid(rowid);
                        affected += 1;
                    }
                    ConflictAction::Ignore => {
                        if !exists {
                            if let Some(ipk_idx) = ipk_col_idx {
                                col_values[ipk_idx] = SqliteValue::Integer(rowid);
                            }
                            db.upsert_row(root_page, rowid, col_values);
                            self.record_last_insert_rowid(rowid);
                            affected += 1;
                        }
                        // else: silently skip this row
                    }
                    ConflictAction::Abort | ConflictAction::Fail | ConflictAction::Rollback => {
                        if exists {
                            return Err(FrankenError::UniqueViolation {
                                columns: format!("{table_name}.rowid"),
                            });
                        }
                        if let Some(ipk_idx) = ipk_col_idx {
                            col_values[ipk_idx] = SqliteValue::Integer(rowid);
                        }
                        db.upsert_row(root_page, rowid, col_values);
                        self.record_last_insert_rowid(rowid);
                        affected += 1;
                    }
                }
            } else {
                // No explicit rowid; auto-allocate.  Conflict on auto-generated
                // rowid is practically impossible.
                let new_rowid = db
                    .insert_auto_row(root_page, col_values, ipk_col_idx)
                    .ok_or_else(|| {
                        FrankenError::Internal(format!("table not found at root page {root_page}"))
                    })?;
                self.record_last_insert_rowid(new_rowid);
                affected += 1;
            }
        }

        Ok(affected)
    }

    fn resolve_insert_target_layout(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> Result<InsertTargetLayout> {
        let schema = self.schema.borrow();
        let table = schema
            .iter()
            .find(|tbl| tbl.name.eq_ignore_ascii_case(&insert.table.name))
            .ok_or_else(|| {
                FrankenError::Internal(format!("table not found: {}", insert.table.name))
            })?;
        Self::validate_insert_target_columns(table, &insert.table.name, &insert.columns)?;

        let table_columns: Vec<String> = table.columns.iter().map(|col| col.name.clone()).collect();
        let rowid_alias_col_idx = table.columns.iter().position(|column| column.is_ipk);

        if insert.columns.is_empty() {
            let targets = (0..table_columns.len()).map(InsertTarget::Column).collect();
            return Ok(InsertTargetLayout {
                explicit_rowid_source: rowid_alias_col_idx,
                rowid_alias_col_idx,
                table_columns,
                targets,
            });
        }

        let mut targets = Vec::with_capacity(insert.columns.len());
        for col in &insert.columns {
            if let Some(idx) = table.column_index(col) {
                targets.push(InsertTarget::Column(idx));
            } else if is_hidden_rowid_alias_name(col) {
                targets.push(InsertTarget::HiddenRowid);
            } else {
                return Err(FrankenError::Internal(format!(
                    "column '{col}' not found in table '{}'",
                    insert.table.name
                )));
            }
        }
        let explicit_rowid_source = targets.iter().rposition(|target| match target {
            InsertTarget::HiddenRowid => true,
            InsertTarget::Column(idx) => Some(*idx) == rowid_alias_col_idx,
        });
        Ok(InsertTargetLayout {
            table_columns,
            targets,
            rowid_alias_col_idx,
            explicit_rowid_source,
        })
    }

    fn streaming_insert_select_orders_by_primary_rowid(
        term: &OrderingTerm,
        primary_source: &JoinTableSource,
    ) -> bool {
        if term.nulls.is_some() || matches!(term.direction, Some(SortDirection::Desc)) {
            return false;
        }
        let Expr::Column(col_ref, _) = &term.expr else {
            return false;
        };
        primary_source
            .hidden_rowid_projection
            .as_deref()
            .is_some_and(|hidden_rowid_alias| {
                col_ref.table.as_deref().is_some_and(|table| {
                    table.eq_ignore_ascii_case(
                        primary_source
                            .alias
                            .as_deref()
                            .unwrap_or(&primary_source.table_name),
                    )
                }) && col_ref.column.eq_ignore_ascii_case(hidden_rowid_alias)
            })
    }

    fn wrap_deferred_prepared_dml<'conn>(
        &'conn self,
        sql: &str,
        statement: &Statement,
        func_registry: Option<Arc<FunctionRegistry>>,
        column_names: Vec<String>,
        may_observe_change_tracking: bool,
    ) -> Result<PreparedStatement<'conn>> {
        Ok(PreparedStatement {
            sql: Rc::<str>::from(sql),
            program: build_placeholder_program()?,
            func_registry,
            expression_postprocess: None,
            distinct: false,
            distinct_collations: Vec::new(),
            db: None,
            post_distinct_limit: None,
            schema_cookie: self.schema_cookie(),
            schema_generation: self.schema_generation(),
            function_registry_generation: self.function_registry_generation(),
            dml_dispatch: Some(PreparedDmlDispatch::Deferred(Arc::new(statement.clone()))),
            prepared_update_delete_fast_path: None,
            deferred_query_statement: None,
            deferred_query_column_count: None,
            column_names,
            prepared_query_fast_path: None,
            may_observe_change_tracking,
            conn: self,
        })
    }

    /// Compile and wrap a statement into a `PreparedStatement`.
    fn compile_and_wrap(&self, sql: &str, statement: &Statement) -> Result<PreparedStatement<'_>> {
        let registry = Some(Arc::clone(&*self.func_registry.borrow()));
        let prepared_column_names = self.prepared_statement_column_names(statement);
        let prepared_query_fast_path = self.prepared_query_fast_path(statement);
        let may_observe_change_tracking = self.statement_may_observe_change_tracking(statement);
        match statement {
            Statement::Select(_) if self.prepared_select_requires_dispatch(statement) => {
                Ok(PreparedStatement {
                    sql: Rc::<str>::from(sql),
                    program: build_placeholder_program()?,
                    func_registry: registry,
                    expression_postprocess: None,
                    distinct: false,
                    distinct_collations: Vec::new(),
                    db: prepared_query_fast_path
                        .as_ref()
                        .map(|_| Rc::clone(&self.db)),
                    post_distinct_limit: None,
                    schema_cookie: self.schema_cookie(),
                    schema_generation: self.schema_generation(),
                    function_registry_generation: self.function_registry_generation(),
                    dml_dispatch: None,
                    prepared_update_delete_fast_path: None,
                    deferred_query_statement: Some(Arc::new(statement.clone())),
                    deferred_query_column_count: Some(
                        self.prepared_statement_column_count(statement),
                    ),
                    column_names: prepared_column_names,
                    prepared_query_fast_path,
                    may_observe_change_tracking,
                    conn: self,
                })
            }
            Statement::Select(select) if is_expression_only_select(select) => {
                let program = Arc::new(compile_expression_select(select)?);
                let expression_postprocess = Some(build_expression_postprocess(select));
                let prep_distinct = is_distinct_select(select);
                let prep_collations = if prep_distinct {
                    select_result_collations(select, &self.schema.borrow())
                } else {
                    Vec::new()
                };
                Ok(PreparedStatement {
                    sql: Rc::<str>::from(sql),
                    program,
                    func_registry: registry,
                    expression_postprocess,
                    distinct: prep_distinct,
                    distinct_collations: prep_collations,
                    db: None,
                    post_distinct_limit: None,
                    schema_cookie: self.schema_cookie(),
                    schema_generation: self.schema_generation(),
                    function_registry_generation: self.function_registry_generation(),
                    dml_dispatch: None,
                    prepared_update_delete_fast_path: None,
                    deferred_query_statement: None,
                    deferred_query_column_count: None,
                    column_names: prepared_column_names,
                    prepared_query_fast_path: None,
                    may_observe_change_tracking,
                    conn: self,
                })
            }
            Statement::Select(select) => {
                let distinct = is_distinct_select(select);
                let prep_collations = if distinct {
                    select_result_collations(select, &self.schema.borrow())
                } else {
                    Vec::new()
                };
                let limit_clause = select.limit.clone();
                let program = if distinct && limit_clause.is_some() {
                    let mut unbounded = select.clone();
                    unbounded.limit = None;
                    let compiled_sql = unbounded.to_string();
                    let compiled_sql_key = Self::sql_hash(&compiled_sql);
                    self.compile_with_cache(compiled_sql_key, &compiled_sql, |conn| {
                        conn.compile_table_select(&unbounded)
                    })?
                } else {
                    let sql_key = Self::sql_hash(sql);
                    self.compile_with_cache(sql_key, sql, |conn| conn.compile_table_select(select))?
                };
                Ok(PreparedStatement {
                    sql: Rc::<str>::from(sql),
                    program,
                    func_registry: registry,
                    expression_postprocess: None,
                    distinct,
                    distinct_collations: prep_collations,
                    db: Some(Rc::clone(&self.db)),
                    post_distinct_limit: if distinct { limit_clause } else { None },
                    schema_cookie: self.schema_cookie(),
                    schema_generation: self.schema_generation(),
                    function_registry_generation: self.function_registry_generation(),
                    dml_dispatch: None,
                    prepared_update_delete_fast_path: None,
                    deferred_query_statement: None,
                    deferred_query_column_count: None,
                    column_names: prepared_column_names,
                    prepared_query_fast_path,
                    may_observe_change_tracking,
                    conn: self,
                })
            }
            Statement::Insert(insert) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&insert.table.name)
                {
                    return self.wrap_deferred_prepared_dml(
                        sql,
                        statement,
                        registry,
                        prepared_column_names,
                        may_observe_change_tracking,
                    );
                }
                // bd-1dp9.6.7.2.1: Simple VALUES-based INSERTs prepare through
                // the precompiled DML path. When the row shape is eligible for
                // the direct compiled insert lane, skip eager VDBE codegen and
                // compile the fallback program lazily only if that direct lane
                // ever bails out. INSERT...SELECT with complex subqueries still
                // gets a placeholder and falls back to full execute_statement.
                let requires_deferred_dispatch =
                    self.prepared_insert_requires_deferred_dispatch(insert)?;
                let is_simple_values = matches!(
                    &insert.source,
                    fsqlite_ast::InsertSource::Values(_) | fsqlite_ast::InsertSource::DefaultValues
                ) || matches!(
                    &insert.source,
                    fsqlite_ast::InsertSource::Select(sel)
                    if matches!(sel.body.select, SelectCore::Values(_))
                       && sel.body.compounds.is_empty()
                );

                if is_simple_values && !requires_deferred_dispatch {
                    let supports_direct_dispatch =
                        self.prepared_insert_supports_direct_dispatch(insert);
                    let direct_simple_insert = if supports_direct_dispatch {
                        self.prepared_direct_simple_insert_plan(insert)?
                    } else {
                        None
                    };
                    let direct_compiled_insert =
                        direct_simple_insert.as_ref().is_some_and(|direct| {
                            !Self::direct_simple_insert_prefers_reusable_table_program(direct)
                        });
                    let program = if direct_compiled_insert {
                        build_placeholder_program()?
                    } else {
                        let sql_key = Self::sql_hash(sql);
                        self.compile_with_cache(sql_key, sql, |conn| {
                            conn.compile_table_insert(insert)
                        })?
                    };
                    Ok(PreparedStatement {
                        sql: Rc::<str>::from(sql),
                        program,
                        func_registry: registry,
                        expression_postprocess: None,
                        distinct: false,
                        distinct_collations: Vec::new(),
                        db: Some(Rc::clone(&self.db)),
                        post_distinct_limit: None,
                        schema_cookie: self.schema_cookie(),
                        schema_generation: self.schema_generation(),
                        function_registry_generation: self.function_registry_generation(),
                        dml_dispatch: Some(if supports_direct_dispatch {
                            let runtime_requirements = self.insert_runtime_requirements(insert)?;
                            PreparedDmlDispatch::Precompiled(Rc::new(PreparedPrecompiledDml {
                                kind: PreparedDmlKind::Insert,
                                table_name: insert.table.name.clone(),
                                post_write_action: self
                                    .prepared_insert_post_write_action(&insert.table.name),
                                rollback_on_constraint_violation: insert.or_conflict
                                    == Some(fsqlite_ast::ConflictAction::Rollback),
                                preserve_prior_changes_on_constraint_violation: insert.or_conflict
                                    == Some(fsqlite_ast::ConflictAction::Fail),
                                skip_statement_savepoint_in_explicit_txn: self
                                    .prepared_insert_can_skip_statement_savepoint_in_explicit_txn(
                                        insert,
                                    ),
                                runtime_requirements,
                                static_runtime_inputs: self
                                    .prepared_static_table_runtime_inputs(runtime_requirements),
                                direct_simple_insert,
                                insert_may_invalidate_fk_parent_cache: insert.or_conflict
                                    == Some(fsqlite_ast::ConflictAction::Replace)
                                    || !insert.upsert.is_empty(),
                            }))
                        } else {
                            PreparedDmlDispatch::Deferred(Arc::new(statement.clone()))
                        }),
                        prepared_update_delete_fast_path: None,
                        deferred_query_statement: None,
                        deferred_query_column_count: None,
                        column_names: prepared_column_names.clone(),
                        prepared_query_fast_path: None,
                        may_observe_change_tracking,
                        conn: self,
                    })
                } else {
                    // Attached-target or complex INSERT statements must stay on
                    // the deferred path so execution can route through the
                    // statement dispatcher instead of main-schema bytecode.
                    Ok(PreparedStatement {
                        sql: Rc::<str>::from(sql),
                        program: build_placeholder_program()?,
                        func_registry: registry,
                        expression_postprocess: None,
                        distinct: false,
                        distinct_collations: Vec::new(),
                        db: None,
                        post_distinct_limit: None,
                        schema_cookie: self.schema_cookie(),
                        schema_generation: self.schema_generation(),
                        function_registry_generation: self.function_registry_generation(),
                        dml_dispatch: Some(PreparedDmlDispatch::Deferred(Arc::new(
                            statement.clone(),
                        ))),
                        prepared_update_delete_fast_path: None,
                        deferred_query_statement: None,
                        deferred_query_column_count: None,
                        column_names: prepared_column_names.clone(),
                        prepared_query_fast_path: None,
                        may_observe_change_tracking,
                        conn: self,
                    })
                }
            }
            Statement::Update(update) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&update.table.name.name)
                {
                    return self.wrap_deferred_prepared_dml(
                        sql,
                        statement,
                        registry,
                        prepared_column_names,
                        may_observe_change_tracking,
                    );
                }
                if Self::prepared_update_supports_precompiled_program(update)
                    && !self.prepared_update_requires_deferred_dispatch(update)?
                {
                    let fast_path = self.prepared_update_fast_path_metadata(update);
                    let (program, db) = if fast_path.has_direct_simple_dispatch() {
                        (build_placeholder_program()?, None)
                    } else {
                        let sql_key = Self::sql_hash(sql);
                        (
                            self.compile_with_cache(sql_key, sql, |conn| {
                                conn.compile_table_update(update)
                            })?,
                            Some(Rc::clone(&self.db)),
                        )
                    };
                    Ok(PreparedStatement {
                        sql: Rc::<str>::from(sql),
                        program,
                        func_registry: registry,
                        expression_postprocess: None,
                        distinct: false,
                        distinct_collations: Vec::new(),
                        db,
                        post_distinct_limit: None,
                        schema_cookie: self.schema_cookie(),
                        schema_generation: self.schema_generation(),
                        function_registry_generation: self.function_registry_generation(),
                        dml_dispatch: Some(PreparedDmlDispatch::Deferred(Arc::new(
                            statement.clone(),
                        ))),
                        prepared_update_delete_fast_path: Some(fast_path),
                        deferred_query_statement: None,
                        deferred_query_column_count: None,
                        column_names: prepared_column_names,
                        prepared_query_fast_path: None,
                        may_observe_change_tracking,
                        conn: self,
                    })
                } else {
                    Ok(PreparedStatement {
                        sql: Rc::<str>::from(sql),
                        program: build_placeholder_program()?,
                        func_registry: registry,
                        expression_postprocess: None,
                        distinct: false,
                        distinct_collations: Vec::new(),
                        db: None,
                        post_distinct_limit: None,
                        schema_cookie: self.schema_cookie(),
                        schema_generation: self.schema_generation(),
                        function_registry_generation: self.function_registry_generation(),
                        dml_dispatch: Some(PreparedDmlDispatch::Deferred(Arc::new(
                            statement.clone(),
                        ))),
                        prepared_update_delete_fast_path: None,
                        deferred_query_statement: None,
                        deferred_query_column_count: None,
                        column_names: prepared_column_names,
                        prepared_query_fast_path: None,
                        may_observe_change_tracking,
                        conn: self,
                    })
                }
            }
            Statement::Delete(delete) => {
                if self.pragma_state.borrow().writable_schema
                    && is_sqlite_schema_name(&delete.table.name.name)
                {
                    return self.wrap_deferred_prepared_dml(
                        sql,
                        statement,
                        registry,
                        prepared_column_names,
                        may_observe_change_tracking,
                    );
                }
                if Self::prepared_delete_supports_precompiled_program(delete)
                    && !self.prepared_delete_requires_deferred_dispatch(delete)?
                {
                    let fast_path = self.prepared_delete_fast_path_metadata(delete);
                    let (program, db) = if fast_path.has_direct_simple_dispatch() {
                        (build_placeholder_program()?, None)
                    } else {
                        let sql_key = Self::sql_hash(sql);
                        (
                            self.compile_with_cache(sql_key, sql, |conn| {
                                conn.compile_table_delete(delete)
                            })?,
                            Some(Rc::clone(&self.db)),
                        )
                    };
                    Ok(PreparedStatement {
                        sql: Rc::<str>::from(sql),
                        program,
                        func_registry: registry,
                        expression_postprocess: None,
                        distinct: false,
                        distinct_collations: Vec::new(),
                        db,
                        post_distinct_limit: None,
                        schema_cookie: self.schema_cookie(),
                        schema_generation: self.schema_generation(),
                        function_registry_generation: self.function_registry_generation(),
                        dml_dispatch: Some(PreparedDmlDispatch::Deferred(Arc::new(
                            statement.clone(),
                        ))),
                        prepared_update_delete_fast_path: Some(fast_path),
                        deferred_query_statement: None,
                        deferred_query_column_count: None,
                        column_names: prepared_column_names,
                        prepared_query_fast_path: None,
                        may_observe_change_tracking,
                        conn: self,
                    })
                } else {
                    Ok(PreparedStatement {
                        sql: Rc::<str>::from(sql),
                        program: build_placeholder_program()?,
                        func_registry: registry,
                        expression_postprocess: None,
                        distinct: false,
                        distinct_collations: Vec::new(),
                        db: None,
                        post_distinct_limit: None,
                        schema_cookie: self.schema_cookie(),
                        schema_generation: self.schema_generation(),
                        function_registry_generation: self.function_registry_generation(),
                        dml_dispatch: Some(PreparedDmlDispatch::Deferred(Arc::new(
                            statement.clone(),
                        ))),
                        prepared_update_delete_fast_path: None,
                        deferred_query_statement: None,
                        deferred_query_column_count: None,
                        column_names: prepared_column_names,
                        prepared_query_fast_path: None,
                        may_observe_change_tracking,
                        conn: self,
                    })
                }
            }
            Statement::Pragma(pragma) if pragma.value.is_some() => self.wrap_deferred_prepared_dml(
                sql,
                statement,
                registry,
                prepared_column_names,
                may_observe_change_tracking,
            ),
            Statement::Pragma(_) => Ok(PreparedStatement {
                sql: Rc::<str>::from(sql),
                program: build_placeholder_program()?,
                func_registry: registry,
                expression_postprocess: None,
                distinct: false,
                distinct_collations: Vec::new(),
                db: None,
                post_distinct_limit: None,
                schema_cookie: self.schema_cookie(),
                schema_generation: self.schema_generation(),
                function_registry_generation: self.function_registry_generation(),
                dml_dispatch: None,
                prepared_update_delete_fast_path: None,
                deferred_query_statement: Some(Arc::new(statement.clone())),
                deferred_query_column_count: None,
                column_names: prepared_column_names,
                prepared_query_fast_path: None,
                may_observe_change_tracking,
                conn: self,
            }),
            _ => Err(FrankenError::NotImplemented(
                "prepare() supports SELECT, INSERT, UPDATE, DELETE, and PRAGMA statements only"
                    .to_owned(),
            )),
        }
    }

    fn prepared_insert_supports_direct_dispatch(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> bool {
        #[cfg(feature = "ext-fts5")]
        if self.insert_targets_live_fts5_command_column(insert) {
            return false;
        }
        if fts5_maintenance_insert_command(insert).is_some() {
            return false;
        }
        if !insert.upsert.is_empty() {
            return false;
        }
        if !insert.returning.is_empty() {
            return false;
        }

        let table_name = insert.table.name.as_str();
        if self.has_live_vtab_instance(table_name) {
            return false;
        }
        if insert.or_conflict == Some(fsqlite_ast::ConflictAction::Replace)
            && self.table_is_foreign_key_parent(table_name)
        {
            // The direct-simple insert lane cannot report the exact row that
            // REPLACE implicitly deletes. Keep FK-parent REPLACE statements on
            // the VDBE path even if this statement was prepared while
            // PRAGMA foreign_keys was OFF and enabled before execution.
            return false;
        }
        let insert_event = fsqlite_ast::TriggerEvent::Insert;
        if self.has_matching_triggers(
            table_name,
            fsqlite_ast::TriggerTiming::Before,
            &insert_event,
        ) || self.has_matching_triggers(
            table_name,
            fsqlite_ast::TriggerTiming::After,
            &insert_event,
        ) {
            return false;
        }

        let Some(idx) = self.schema_index_of(table_name) else {
            return false;
        };
        let schema = self.schema.borrow();
        schema.get(idx).is_some_and(|table| {
            let fk_ok = table.foreign_keys.is_empty()
                || insert.or_conflict != Some(fsqlite_ast::ConflictAction::Replace);
            // A column or index that declares its own `ON CONFLICT <algo>`
            // requires the full codegen INSERT path, which honors per-constraint
            // conflict resolution; the direct-simple lane does not (bd-587fx,
            // bd-24hno). Decline so such tables fall back to codegen.
            let no_per_constraint_conflict =
                table.columns.iter().all(|c| c.conflict_action.is_none())
                    && table.indexes.iter().all(|i| i.conflict_action.is_none());
            fk_ok && no_per_constraint_conflict
        })
    }

    fn statement_may_observe_change_tracking(&self, statement: &Statement) -> bool {
        match statement {
            Statement::Select(select) => select_may_observe_change_tracking(select),
            Statement::Insert(insert) => {
                insert_may_observe_change_tracking(insert)
                    || self.insert_target_schema_may_observe_change_tracking(insert)
            }
            _ => true,
        }
    }

    fn insert_target_schema_may_observe_change_tracking(&self, insert: &InsertStatement) -> bool {
        let Some(idx) = self.schema_index_of(&insert.table.name) else {
            return true;
        };
        let schema = self.schema.borrow();
        schema
            .get(idx)
            .is_none_or(table_schema_may_observe_change_tracking)
    }

    fn prepared_direct_simple_insert_plan(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> Result<Option<PreparedDirectSimpleInsert>> {
        let resolved_insert = self.resolve_insert_values_subqueries(insert)?;
        if !resolved_insert.upsert.is_empty() {
            return Ok(None);
        }

        let mut row_values = match &resolved_insert.source {
            fsqlite_ast::InsertSource::Values(rows) if rows.len() == 1 => rows[0].clone(),
            fsqlite_ast::InsertSource::Select(select) if select.body.compounds.is_empty() => {
                match &select.body.select {
                    SelectCore::Values(rows) if rows.len() == 1 => rows[0].clone(),
                    _ => return Ok(None),
                }
            }
            _ => return Ok(None),
        };

        let table_name = resolved_insert.table.name.as_str();
        let schema = self.schema.borrow();
        let Some(table) = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(table_name))
        else {
            return Ok(None);
        };

        // bd-wwqen.3 B3: Support explicit column-list INSERT when ALL columns
        // are specified (just reordered). Partial column lists fall through.
        if !resolved_insert.columns.is_empty() {
            if resolved_insert.columns.len() != table.columns.len()
                || resolved_insert.columns.len() != row_values.len()
            {
                return Ok(None);
            }
            let mut reordered = Vec::with_capacity(table.columns.len());
            for table_col in &table.columns {
                let Some(idx) = resolved_insert
                    .columns
                    .iter()
                    .position(|c| c.eq_ignore_ascii_case(&table_col.name))
                else {
                    return Ok(None);
                };
                reordered.push(row_values[idx].clone());
            }
            row_values = reordered;
        }

        let mut bind_state = BindParamState::default();
        for expr in &mut row_values {
            canonicalize_expr_placeholders(expr, &mut bind_state)?;
        }

        if !row_values
            .iter()
            .all(Self::prepared_direct_simple_insert_expr_supported)
        {
            return Ok(None);
        }

        if table.without_rowid
            || !table.indexes.is_empty()
            || !table.check_constraints.is_empty()
            || self.prepared_insert_post_write_action(table_name)
                != PreparedInsertPostWriteAction::None
            || table
                .columns
                .iter()
                .any(|column| column.generated_expr.is_some())
            || row_values.len() != table.columns.len()
        {
            return Ok(None);
        }

        let rowid_alias_col_idx = self
            .rowid_alias_columns
            .borrow()
            .get(&table_name.to_ascii_lowercase())
            .copied();
        let compiled_row_values = row_values
            .iter()
            .map(Self::compile_prepared_direct_simple_insert_expr)
            .collect::<Option<Vec<_>>>();
        let _lookaside_growth = StatementLookasideGrowthGuard::new(self);
        let prebuilt_constant_record = self
            .try_build_prepared_direct_simple_insert_constant_record(
                &table.columns,
                rowid_alias_col_idx,
                compiled_row_values.as_deref(),
            );
        let lane =
            Self::classify_prepared_direct_simple_insert_lane(compiled_row_values.as_deref());
        let (cursor_page_size, cursor_reserved_per_page) = self
            .pragma_database_header()?
            .map(|header| (header.page_size, header.reserved_per_page))
            .unwrap_or((PageSize::DEFAULT, 0));
        Ok(Some(PreparedDirectSimpleInsert {
            root_page: table.root_page,
            rowid_alias_col_idx,
            lane,
            row_values,
            compiled_row_values,
            prebuilt_constant_record,
            cached_record_header: RefCell::new(None),
            cursor_page_size,
            cursor_reserved_per_page,
            columns: table.columns.clone(),
            or_conflict: resolved_insert.or_conflict,
        }))
    }

    fn classify_prepared_direct_simple_insert_lane(
        compiled_row_values: Option<&[PreparedDirectSimpleInsertExpr]>,
    ) -> PreparedDirectSimpleInsertLane {
        if compiled_row_values.is_some() {
            PreparedDirectSimpleInsertLane::DirectCompiled
        } else {
            PreparedDirectSimpleInsertLane::ReusableTableProgram
        }
    }

    fn try_build_prepared_direct_simple_insert_constant_record(
        &self,
        columns: &[ColumnInfo],
        rowid_alias_col_idx: Option<usize>,
        compiled_row_values: Option<&[PreparedDirectSimpleInsertExpr]>,
    ) -> Option<Vec<u8>> {
        let exprs = compiled_row_values?;
        if exprs.len() != columns.len() {
            return None;
        }

        let mut values = self.prepared_direct_insert_row_scratch.borrow_mut();
        values.clear();
        if values.capacity() < columns.len() {
            let additional_capacity = columns.len() - values.capacity();
            values.reserve(additional_capacity);
        }
        for (col_idx, (column, expr)) in columns.iter().zip(exprs.iter()).enumerate() {
            let is_rowid_alias = column.is_ipk || rowid_alias_col_idx == Some(col_idx);
            if is_rowid_alias {
                values.push(SqliteValue::Null);
                continue;
            }

            let PreparedDirectSimpleInsertExpr::Literal(raw_value) = expr else {
                return None;
            };
            if column.notnull && raw_value.is_null() {
                return None;
            }
            let value = if let Some(strict_type) = column.strict_type {
                raw_value.clone().validate_strict(strict_type).ok()?
            } else {
                raw_value.clone()
            };
            values
                .push(value.apply_affinity(Self::type_affinity_for_direct_insert(column.affinity)));
        }

        let mut record = self.prepared_direct_insert_record_scratch.borrow_mut();
        record.clear();
        serialize_record_iter_into(values.iter(), &mut record);
        self.note_statement_lookaside_fallback();
        Some(record.clone())
    }

    fn prepared_direct_simple_insert_expr_supported(expr: &Expr) -> bool {
        match expr {
            Expr::Literal(_, _) | Expr::Placeholder(_, _) => true,
            Expr::Column(_, _)
            | Expr::Raise { .. }
            | Expr::Exists { .. }
            | Expr::Subquery(_, _)
            | Expr::RowValue(_, _) => false,
            Expr::BinaryOp { left, right, .. } => {
                Self::prepared_direct_simple_insert_expr_supported(left)
                    && Self::prepared_direct_simple_insert_expr_supported(right)
            }
            Expr::UnaryOp { expr: inner, .. }
            | Expr::Cast { expr: inner, .. }
            | Expr::Collate { expr: inner, .. }
            | Expr::IsNull { expr: inner, .. } => {
                Self::prepared_direct_simple_insert_expr_supported(inner)
            }
            Expr::Between {
                expr: inner,
                low,
                high,
                ..
            } => {
                Self::prepared_direct_simple_insert_expr_supported(inner)
                    && Self::prepared_direct_simple_insert_expr_supported(low)
                    && Self::prepared_direct_simple_insert_expr_supported(high)
            }
            Expr::In {
                expr: inner, set, ..
            } => {
                Self::prepared_direct_simple_insert_expr_supported(inner)
                    && match set {
                        InSet::List(values) => values
                            .iter()
                            .all(Self::prepared_direct_simple_insert_expr_supported),
                        InSet::Subquery(_) | InSet::Table(_) => false,
                    }
            }
            Expr::Like {
                expr: inner,
                pattern,
                escape,
                ..
            } => {
                Self::prepared_direct_simple_insert_expr_supported(inner)
                    && Self::prepared_direct_simple_insert_expr_supported(pattern)
                    && escape
                        .as_deref()
                        .is_none_or(Self::prepared_direct_simple_insert_expr_supported)
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                operand
                    .as_deref()
                    .is_none_or(Self::prepared_direct_simple_insert_expr_supported)
                    && whens.iter().all(|(when_expr, then_expr)| {
                        Self::prepared_direct_simple_insert_expr_supported(when_expr)
                            && Self::prepared_direct_simple_insert_expr_supported(then_expr)
                    })
                    && else_expr
                        .as_deref()
                        .is_none_or(Self::prepared_direct_simple_insert_expr_supported)
            }
            Expr::FunctionCall {
                args,
                distinct,
                order_by,
                filter,
                over,
                ..
            } => {
                !*distinct
                    && order_by.is_empty()
                    && filter.is_none()
                    && over.is_none()
                    && match args {
                        FunctionArgs::Star => true,
                        FunctionArgs::List(arguments) => arguments
                            .iter()
                            .all(Self::prepared_direct_simple_insert_expr_supported),
                    }
            }
            Expr::JsonAccess {
                expr: inner, path, ..
            } => {
                Self::prepared_direct_simple_insert_expr_supported(inner)
                    && Self::prepared_direct_simple_insert_expr_supported(path)
            }
        }
    }

    fn type_affinity_for_direct_insert(ch: char) -> TypeAffinity {
        match ch {
            'B' | 'b' => TypeAffinity::Text,
            'C' | 'c' => TypeAffinity::Numeric,
            'D' | 'd' => TypeAffinity::Integer,
            'E' | 'e' => TypeAffinity::Real,
            _ => TypeAffinity::Blob,
        }
    }

    fn compile_prepared_direct_simple_insert_expr(
        expr: &Expr,
    ) -> Option<PreparedDirectSimpleInsertExpr> {
        match expr {
            Expr::Literal(literal, _) => {
                let value = match literal {
                    Literal::Null => SqliteValue::Null,
                    Literal::Integer(value) => SqliteValue::Integer(*value),
                    Literal::Float(value) => SqliteValue::Float(*value),
                    Literal::String(value) => SqliteValue::Text(value.clone().into()),
                    Literal::Blob(value) => SqliteValue::Blob(value.clone().into()),
                    Literal::True => SqliteValue::Integer(1),
                    Literal::False => SqliteValue::Integer(0),
                    Literal::CurrentTimestamp | Literal::CurrentDate | Literal::CurrentTime => {
                        return None;
                    }
                };
                Some(PreparedDirectSimpleInsertExpr::Literal(value))
            }
            Expr::Placeholder(PlaceholderType::Numbered(index), _) => {
                let one_based = usize::try_from(*index).ok()?;
                (one_based != 0).then_some(PreparedDirectSimpleInsertExpr::Placeholder(one_based))
            }
            Expr::BinaryOp {
                op: BinaryOp::Concat,
                ..
            } => {
                let mut segments = Vec::new();
                Self::collect_prepared_direct_simple_insert_concat_segments(expr, &mut segments)?;
                Some(PreparedDirectSimpleInsertExpr::ConcatChain(segments))
            }
            Expr::BinaryOp {
                left, op, right, ..
            } => Some(PreparedDirectSimpleInsertExpr::BinaryOp {
                left: Box::new(Self::compile_prepared_direct_simple_insert_expr(left)?),
                op: *op,
                right: Box::new(Self::compile_prepared_direct_simple_insert_expr(right)?),
            }),
            Expr::UnaryOp {
                op, expr: inner, ..
            } => Some(PreparedDirectSimpleInsertExpr::UnaryOp {
                op: *op,
                expr: Box::new(Self::compile_prepared_direct_simple_insert_expr(inner)?),
            }),
            Expr::Cast {
                expr: inner,
                type_name,
                ..
            } => Some(PreparedDirectSimpleInsertExpr::Cast {
                expr: Box::new(Self::compile_prepared_direct_simple_insert_expr(inner)?),
                type_name: type_name.name.clone(),
            }),
            Expr::Collate { expr: inner, .. } => Some(PreparedDirectSimpleInsertExpr::Collate(
                Box::new(Self::compile_prepared_direct_simple_insert_expr(inner)?),
            )),
            Expr::IsNull {
                expr: inner, not, ..
            } => Some(PreparedDirectSimpleInsertExpr::IsNull {
                expr: Box::new(Self::compile_prepared_direct_simple_insert_expr(inner)?),
                not: *not,
            }),
            Expr::Placeholder(_, _)
            | Expr::Column(_, _)
            | Expr::Raise { .. }
            | Expr::Exists { .. }
            | Expr::Subquery(_, _)
            | Expr::Between { .. }
            | Expr::In { .. }
            | Expr::Like { .. }
            | Expr::Case { .. }
            | Expr::FunctionCall { .. }
            | Expr::JsonAccess { .. }
            | Expr::RowValue(_, _) => None,
        }
    }

    fn collect_prepared_direct_simple_insert_concat_segments(
        expr: &Expr,
        segments: &mut Vec<PreparedDirectSimpleConcatSegment>,
    ) -> Option<()> {
        match expr {
            Expr::BinaryOp {
                left,
                op: BinaryOp::Concat,
                right,
                ..
            } => {
                Self::collect_prepared_direct_simple_insert_concat_segments(left, segments)?;
                Self::collect_prepared_direct_simple_insert_concat_segments(right, segments)?;
                Some(())
            }
            _ => {
                segments.push(Self::compile_prepared_direct_simple_insert_concat_segment(
                    expr,
                )?);
                Some(())
            }
        }
    }

    fn compile_prepared_direct_simple_insert_concat_segment(
        expr: &Expr,
    ) -> Option<PreparedDirectSimpleConcatSegment> {
        match expr {
            Expr::Literal(Literal::Null, _) => Some(PreparedDirectSimpleConcatSegment::NullLiteral),
            Expr::Literal(Literal::String(value), _) => Some(
                PreparedDirectSimpleConcatSegment::TextLiteral(value.clone()),
            ),
            Expr::Literal(literal, _) => {
                let value = match literal {
                    Literal::Null | Literal::String(_) => unreachable!("handled above"),
                    Literal::Integer(value) => SqliteValue::Integer(*value),
                    Literal::Float(value) => SqliteValue::Float(*value),
                    Literal::Blob(value) => SqliteValue::Blob(value.clone().into()),
                    Literal::True => SqliteValue::Integer(1),
                    Literal::False => SqliteValue::Integer(0),
                    Literal::CurrentTimestamp | Literal::CurrentDate | Literal::CurrentTime => {
                        return None;
                    }
                };
                Some(PreparedDirectSimpleConcatSegment::Literal(value))
            }
            Expr::Placeholder(PlaceholderType::Numbered(index), _) => {
                let one_based = usize::try_from(*index).ok()?;
                (one_based != 0)
                    .then_some(PreparedDirectSimpleConcatSegment::Placeholder(one_based))
            }
            _ => Some(PreparedDirectSimpleConcatSegment::Expr(Box::new(
                Self::compile_prepared_direct_simple_insert_expr(expr)?,
            ))),
        }
    }

    fn eval_prepared_direct_simple_insert_numeric_or_null(
        expr: &PreparedDirectSimpleInsertExpr,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<PreparedDirectSimpleInsertNumericOperand>> {
        match expr {
            PreparedDirectSimpleInsertExpr::Literal(SqliteValue::Null) => {
                Ok(Some(PreparedDirectSimpleInsertNumericOperand::Null))
            }
            PreparedDirectSimpleInsertExpr::Literal(SqliteValue::Integer(value)) => Ok(Some(
                PreparedDirectSimpleInsertNumericOperand::Integer(*value),
            )),
            PreparedDirectSimpleInsertExpr::Literal(SqliteValue::Float(value)) => Ok(Some(
                PreparedDirectSimpleInsertNumericOperand::Float(*value),
            )),
            PreparedDirectSimpleInsertExpr::Placeholder(one_based) => {
                match Self::prepared_direct_simple_insert_param(params, *one_based)? {
                    SqliteValue::Null => Ok(Some(PreparedDirectSimpleInsertNumericOperand::Null)),
                    SqliteValue::Integer(value) => Ok(Some(
                        PreparedDirectSimpleInsertNumericOperand::Integer(*value),
                    )),
                    SqliteValue::Float(value) => Ok(Some(
                        PreparedDirectSimpleInsertNumericOperand::Float(*value),
                    )),
                    _ => Ok(None),
                }
            }
            _ => Ok(None),
        }
    }

    #[allow(clippy::cast_precision_loss)]
    fn eval_prepared_direct_simple_insert_integer_binary_values(
        left_int: i64,
        op: BinaryOp,
        right_int: i64,
    ) -> Option<SqliteValue> {
        let value = match op {
            BinaryOp::Add => left_int.checked_add(right_int).map_or_else(
                || SqliteValue::Float(left_int as f64 + right_int as f64),
                SqliteValue::Integer,
            ),
            BinaryOp::Subtract => left_int.checked_sub(right_int).map_or_else(
                || SqliteValue::Float(left_int as f64 - right_int as f64),
                SqliteValue::Integer,
            ),
            BinaryOp::Multiply => left_int.checked_mul(right_int).map_or_else(
                || SqliteValue::Float(left_int as f64 * right_int as f64),
                SqliteValue::Integer,
            ),
            BinaryOp::Modulo => {
                if right_int == 0 {
                    SqliteValue::Null
                } else {
                    SqliteValue::Integer(left_int.checked_rem(right_int).unwrap_or(0))
                }
            }
            _ => return None,
        };
        Some(value)
    }

    fn prepared_direct_simple_insert_float_result(result: f64) -> SqliteValue {
        if result.is_nan() {
            SqliteValue::Null
        } else {
            SqliteValue::Float(result)
        }
    }

    fn eval_prepared_direct_simple_insert_float_binary_values(
        left_float: f64,
        op: BinaryOp,
        right_float: f64,
    ) -> Option<SqliteValue> {
        let result = match op {
            BinaryOp::Add => left_float + right_float,
            BinaryOp::Subtract => left_float - right_float,
            BinaryOp::Multiply => left_float * right_float,
            BinaryOp::Divide if right_float != 0.0 => left_float / right_float,
            BinaryOp::Divide => return Some(SqliteValue::Null),
            _ => return None,
        };
        Some(Self::prepared_direct_simple_insert_float_result(result))
    }

    #[allow(clippy::cast_precision_loss)]
    fn eval_prepared_direct_simple_insert_numeric_binary_op(
        left: &PreparedDirectSimpleInsertExpr,
        op: BinaryOp,
        right: &PreparedDirectSimpleInsertExpr,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<SqliteValue>> {
        let Some(left_value) =
            Self::eval_prepared_direct_simple_insert_numeric_or_null(left, params)?
        else {
            return Ok(None);
        };
        let Some(right_value) =
            Self::eval_prepared_direct_simple_insert_numeric_or_null(right, params)?
        else {
            return Ok(None);
        };
        match (left_value, right_value) {
            (
                PreparedDirectSimpleInsertNumericOperand::Null,
                PreparedDirectSimpleInsertNumericOperand::Null
                | PreparedDirectSimpleInsertNumericOperand::Integer(_)
                | PreparedDirectSimpleInsertNumericOperand::Float(_),
            )
            | (
                PreparedDirectSimpleInsertNumericOperand::Integer(_)
                | PreparedDirectSimpleInsertNumericOperand::Float(_),
                PreparedDirectSimpleInsertNumericOperand::Null,
            ) => Ok(Some(SqliteValue::Null)),
            (
                PreparedDirectSimpleInsertNumericOperand::Integer(left_int),
                PreparedDirectSimpleInsertNumericOperand::Integer(right_int),
            ) => Ok(
                Self::eval_prepared_direct_simple_insert_integer_binary_values(
                    left_int, op, right_int,
                ),
            ),
            (
                PreparedDirectSimpleInsertNumericOperand::Integer(left_int),
                PreparedDirectSimpleInsertNumericOperand::Float(right_float),
            ) => Ok(
                Self::eval_prepared_direct_simple_insert_float_binary_values(
                    left_int as f64,
                    op,
                    right_float,
                ),
            ),
            (
                PreparedDirectSimpleInsertNumericOperand::Float(left_float),
                PreparedDirectSimpleInsertNumericOperand::Integer(right_int),
            ) => Ok(
                Self::eval_prepared_direct_simple_insert_float_binary_values(
                    left_float,
                    op,
                    right_int as f64,
                ),
            ),
            (
                PreparedDirectSimpleInsertNumericOperand::Float(left_float),
                PreparedDirectSimpleInsertNumericOperand::Float(right_float),
            ) => Ok(
                Self::eval_prepared_direct_simple_insert_float_binary_values(
                    left_float,
                    op,
                    right_float,
                ),
            ),
        }
    }

    fn eval_prepared_direct_simple_insert_expr(
        expr: &PreparedDirectSimpleInsertExpr,
        params: Option<&[SqliteValue]>,
        reusable_concat_text_scratch: Option<&mut String>,
    ) -> Result<SqliteValue> {
        match expr {
            PreparedDirectSimpleInsertExpr::Literal(value) => Ok(value.clone()),
            PreparedDirectSimpleInsertExpr::Placeholder(one_based) => {
                Ok(Self::prepared_direct_simple_insert_param(params, *one_based)?.clone())
            }
            PreparedDirectSimpleInsertExpr::ConcatChain(segments) => {
                if let Some(text_scratch) = reusable_concat_text_scratch {
                    Self::eval_prepared_direct_simple_insert_concat_chain(
                        segments,
                        params,
                        text_scratch,
                    )
                } else {
                    let mut text = String::new();
                    Self::eval_prepared_direct_simple_insert_concat_chain(
                        segments, params, &mut text,
                    )
                }
            }
            PreparedDirectSimpleInsertExpr::BinaryOp { left, op, right } => {
                if let Some(value) = Self::eval_prepared_direct_simple_insert_numeric_binary_op(
                    left, *op, right, params,
                )? {
                    return Ok(value);
                }
                let left_value = Self::eval_prepared_direct_simple_insert_expr(left, params, None)?;
                let right_value =
                    Self::eval_prepared_direct_simple_insert_expr(right, params, None)?;
                Ok(crate::connection::eval_binary_op(
                    &left_value,
                    *op,
                    &right_value,
                ))
            }
            PreparedDirectSimpleInsertExpr::UnaryOp { op, expr: inner } => {
                let value = Self::eval_prepared_direct_simple_insert_expr(inner, params, None)?;
                match op {
                    UnaryOp::Negate => match &value {
                        SqliteValue::Integer(n) => Ok(n.checked_neg().map_or_else(
                            || SqliteValue::Float(-(*n as f64)),
                            SqliteValue::Integer,
                        )),
                        SqliteValue::Float(f) => Ok(SqliteValue::Float(-f)),
                        _ => Ok(SqliteValue::Null),
                    },
                    UnaryOp::Plus => Ok(value),
                    UnaryOp::Not => {
                        if value.is_null() {
                            Ok(SqliteValue::Null)
                        } else {
                            Ok(SqliteValue::Integer(i64::from(!is_sqlite_truthy(&value))))
                        }
                    }
                    UnaryOp::BitNot => {
                        if value.is_null() {
                            Ok(SqliteValue::Null)
                        } else {
                            Ok(SqliteValue::Integer(!value.to_integer()))
                        }
                    }
                }
            }
            PreparedDirectSimpleInsertExpr::Cast {
                expr: inner,
                type_name,
            } => {
                let value = Self::eval_prepared_direct_simple_insert_expr(inner, params, None)?;
                Ok(apply_cast(value, type_name))
            }
            PreparedDirectSimpleInsertExpr::Collate(inner) => {
                Self::eval_prepared_direct_simple_insert_expr(inner, params, None)
            }
            PreparedDirectSimpleInsertExpr::IsNull { expr: inner, not } => {
                let value = Self::eval_prepared_direct_simple_insert_expr(inner, params, None)?;
                Ok(SqliteValue::Integer(i64::from(if *not {
                    !value.is_null()
                } else {
                    value.is_null()
                })))
            }
        }
    }

    fn prepared_insert_requires_deferred_dispatch(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> Result<bool> {
        #[cfg(feature = "ext-fts5")]
        if self.insert_targets_live_fts5_command_column(insert) {
            return Ok(true);
        }
        Ok(fts5_maintenance_insert_command(insert).is_some()
            || self.attached_target_schema(&insert.table)?.is_some())
    }

    fn prepared_update_requires_deferred_dispatch(
        &self,
        update: &fsqlite_ast::UpdateStatement,
    ) -> Result<bool> {
        let registry = self.attached_schemas.borrow();
        Ok(determine_attached_update_schema(update, &registry)?.is_some())
    }

    fn prepared_delete_requires_deferred_dispatch(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
    ) -> Result<bool> {
        let registry = self.attached_schemas.borrow();
        Ok(determine_attached_delete_schema(delete, &registry)?.is_some())
    }

    fn prepared_update_supports_precompiled_program(update: &fsqlite_ast::UpdateStatement) -> bool {
        update.with.is_none()
            && update.order_by.is_empty()
            && update.limit.is_none()
            && !update
                .assignments
                .iter()
                .any(|assignment| expr_contains_rewritable_subquery(&assignment.value))
            && !update
                .where_clause
                .as_ref()
                .is_some_and(expr_contains_rewritable_subquery)
    }

    fn prepared_delete_supports_precompiled_program(delete: &fsqlite_ast::DeleteStatement) -> bool {
        delete.with.is_none()
            && delete.order_by.is_empty()
            && delete.limit.is_none()
            && !delete
                .where_clause
                .as_ref()
                .is_some_and(expr_contains_rewritable_subquery)
    }

    fn prepared_update_delete_static_fallback_reason(
        &self,
        table_name: &str,
        returning_present: bool,
        trigger_event: &fsqlite_ast::TriggerEvent,
    ) -> Option<PreparedUpdateDeleteFallbackReason> {
        if returning_present {
            return Some(PreparedUpdateDeleteFallbackReason::Returning);
        }
        if table_name.eq_ignore_ascii_case("sqlite_sequence") {
            return Some(PreparedUpdateDeleteFallbackReason::SqliteSequence);
        }
        if self.table_declares_without_rowid(table_name) {
            return Some(PreparedUpdateDeleteFallbackReason::WithoutRowid);
        }
        if self.has_live_vtab_instance(table_name) {
            return Some(PreparedUpdateDeleteFallbackReason::LiveVtab);
        }
        if self.has_matching_triggers(
            table_name,
            fsqlite_ast::TriggerTiming::Before,
            trigger_event,
        ) || self.has_matching_triggers(
            table_name,
            fsqlite_ast::TriggerTiming::After,
            trigger_event,
        ) {
            return Some(PreparedUpdateDeleteFallbackReason::Trigger);
        }
        None
    }

    fn prepared_update_fast_path_metadata(
        &self,
        update: &fsqlite_ast::UpdateStatement,
    ) -> PreparedUpdateDeleteFastPath {
        let table_name = update.table.name.name.as_str();
        let runtime_requirements = TableExecutionRuntimeRequirements::write_path(
            None,
            self.table_needs_runtime_column_defaults(table_name),
        );
        let update_cols: Vec<String> = update
            .assignments
            .iter()
            .flat_map(|assignment| match &assignment.target {
                fsqlite_ast::AssignmentTarget::Column(column) => vec![column.clone()],
                fsqlite_ast::AssignmentTarget::ColumnList(columns) => columns.clone(),
            })
            .collect();
        let update_event = fsqlite_ast::TriggerEvent::Update(update_cols);
        let static_fallback_reason = self.prepared_update_delete_static_fallback_reason(
            table_name,
            !update.returning.is_empty(),
            &update_event,
        );
        let foreign_key_work = self.table_has_foreign_key_work(table_name);
        let direct_simple_update = if static_fallback_reason.is_none() && !foreign_key_work {
            self.try_build_prepared_direct_simple_update(update)
                .ok()
                .flatten()
        } else {
            None
        };
        let skip_statement_savepoint_in_explicit_txn = direct_simple_update.is_some()
            && self.prepared_update_can_skip_statement_savepoint_in_explicit_txn(update);
        PreparedUpdateDeleteFastPath {
            kind: PreparedDmlKind::Update,
            table_name: table_name.to_owned(),
            rollback_on_constraint_violation: update.or_conflict
                == Some(fsqlite_ast::ConflictAction::Rollback),
            preserve_prior_changes_on_constraint_violation: update.or_conflict
                == Some(fsqlite_ast::ConflictAction::Fail),
            skip_statement_savepoint_in_explicit_txn,
            runtime_requirements,
            static_runtime_inputs: self.prepared_static_table_runtime_inputs(runtime_requirements),
            static_fallback_reason,
            foreign_key_work,
            direct_simple_update,
            direct_simple_delete: None,
        }
    }

    fn prepared_delete_fast_path_metadata(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
    ) -> PreparedUpdateDeleteFastPath {
        let table_name = delete.table.name.name.as_str();
        let runtime_requirements = TableExecutionRuntimeRequirements::write_path(
            None,
            self.table_needs_runtime_column_defaults(table_name),
        );
        let delete_event = fsqlite_ast::TriggerEvent::Delete;
        let static_fallback_reason = self.prepared_update_delete_static_fallback_reason(
            table_name,
            !delete.returning.is_empty(),
            &delete_event,
        );
        let foreign_key_work = self.table_is_foreign_key_parent(table_name);
        let direct_simple_delete = if static_fallback_reason.is_none() && !foreign_key_work {
            self.try_build_prepared_direct_simple_delete(delete)
                .ok()
                .flatten()
        } else {
            None
        };
        PreparedUpdateDeleteFastPath {
            kind: PreparedDmlKind::Delete,
            table_name: table_name.to_owned(),
            rollback_on_constraint_violation: false,
            preserve_prior_changes_on_constraint_violation: false,
            skip_statement_savepoint_in_explicit_txn: static_fallback_reason.is_none()
                && !foreign_key_work
                && self.prepared_delete_can_skip_statement_savepoint_in_explicit_txn(delete),
            runtime_requirements,
            static_runtime_inputs: self.prepared_static_table_runtime_inputs(runtime_requirements),
            static_fallback_reason,
            foreign_key_work,
            direct_simple_update: None,
            direct_simple_delete,
        }
    }

    /// Build the direct-simple UPDATE metadata when the statement shape allows
    /// bypassing VDBE. Very narrow: rowid-alias WHERE, no subqueries, no
    /// triggers, no constraints that require validation beyond NOT NULL /
    /// affinity, no assigned indexed columns, and each SET value must be a
    /// numbered placeholder or a literal constant.
    fn try_build_prepared_direct_simple_update(
        &self,
        update: &fsqlite_ast::UpdateStatement,
    ) -> Result<Option<PreparedDirectSimpleUpdate>> {
        // Structural guards that are cheap to re-check.
        if update.with.is_some()
            || !update.returning.is_empty()
            || !update.order_by.is_empty()
            || update.limit.is_some()
            || update.from.is_some()
            || update.or_conflict == Some(fsqlite_ast::ConflictAction::Rollback)
        {
            return Ok(None);
        }
        if update.table.name.schema.is_some()
            || update.table.index_hint.is_some()
            || update.table.time_travel.is_some()
        {
            return Ok(None);
        }
        let table_name = update.table.name.name.as_str();
        let schema = self.schema.borrow();
        let Some(table) = schema
            .iter()
            .find(|t| t.name.eq_ignore_ascii_case(table_name))
        else {
            return Ok(None);
        };
        // Narrow gate: no CHECK, no without-rowid, no generated, no strict,
        // no FK. The outer caller already verifies the last two via
        // `foreign_key_work` / static fallback reason; we re-assert here so
        // the helper is self-contained.
        if table.without_rowid
            || !table.check_constraints.is_empty()
            || !table.foreign_keys.is_empty()
            || table.columns.iter().any(|c| {
                c.generated_expr.is_some()
                    || c.generated_stored.is_some()
                    || c.strict_type.is_some()
            })
        {
            return Ok(None);
        }

        // WHERE must be `rowid_alias = ?N`.
        let Some(where_expr) = update.where_clause.as_ref() else {
            return Ok(None);
        };
        let rowid_alias_col_idx = self
            .rowid_alias_columns
            .borrow()
            .get(&table.name.to_ascii_lowercase())
            .copied();
        let rowid_alias_name = select_table_rowid_alias_name(table, rowid_alias_col_idx);
        let table_label = update
            .table
            .alias
            .as_deref()
            .unwrap_or(&update.table.name.name);
        let Some(rowid_param_zero_based) =
            select_rowid_lookup_parameter_index(where_expr, table, table_label, rowid_alias_name)
        else {
            return Ok(None);
        };
        let rowid_param_one_based = rowid_param_zero_based + 1;

        // Each assignment must target a plain column (not IPK, not UNIQUE),
        // and the RHS must be a numbered placeholder or a literal constant.
        let mut assignments = Vec::with_capacity(update.assignments.len());
        for assignment in &update.assignments {
            let column_name = match &assignment.target {
                fsqlite_ast::AssignmentTarget::Column(name) => name.as_str(),
                // (col1, col2) = expr is rarely used and would require us to
                // split `expr` — keep it on the VDBE path.
                fsqlite_ast::AssignmentTarget::ColumnList(_) => return Ok(None),
            };
            let Some(col_idx) = table.column_index(column_name) else {
                return Ok(None);
            };
            let column = &table.columns[col_idx];
            if column.is_ipk || column.unique {
                return Ok(None);
            }
            let value = match &assignment.value {
                Expr::Placeholder(PlaceholderType::Numbered(idx), _) => {
                    let Ok(u) = usize::try_from(*idx) else {
                        return Ok(None);
                    };
                    if u == 0 {
                        return Ok(None);
                    }
                    PreparedDirectSimpleSetValue::Placeholder(u)
                }
                Expr::Literal(literal, _) => {
                    let value = match literal {
                        Literal::Null => SqliteValue::Null,
                        Literal::Integer(v) => SqliteValue::Integer(*v),
                        Literal::Float(v) => SqliteValue::Float(*v),
                        Literal::String(v) => SqliteValue::Text(v.clone().into()),
                        Literal::Blob(v) => SqliteValue::Blob(v.clone().into()),
                        Literal::True => SqliteValue::Integer(1),
                        Literal::False => SqliteValue::Integer(0),
                        Literal::CurrentTimestamp | Literal::CurrentDate | Literal::CurrentTime => {
                            return Ok(None);
                        }
                    };
                    PreparedDirectSimpleSetValue::Literal(value)
                }
                _ => return Ok(None),
            };
            // Reject duplicate column assignments — our execution path applies
            // them in order but SQLite's behavior for duplicates is "last wins"
            // which we want to avoid regressions around.
            if assignments.iter().any(|(idx, _)| *idx == col_idx) {
                return Ok(None);
            }
            assignments.push((col_idx, value));
        }
        if assignments.is_empty() {
            return Ok(None);
        }
        let assigned_column_indices: SmallVec<[usize; 8]> =
            assignments.iter().map(|(col_idx, _)| *col_idx).collect();
        if !Self::prepared_direct_simple_update_skips_index_maintenance(
            table,
            &assigned_column_indices,
        ) {
            return Ok(None);
        }
        let assigns_all_non_ipk_columns =
            assignments.len() == table.columns.iter().filter(|column| !column.is_ipk).count();
        let fixed_width_real_assignment = assignments.first().and_then(|(col_idx, _)| {
            (assignments.len() == 1
                && Self::type_affinity_for_direct_insert(table.columns[*col_idx].affinity)
                    == TypeAffinity::Real)
                .then_some(PreparedDirectFixedWidthRealAssignment {
                    column_index: *col_idx,
                })
        });

        let (cursor_page_size, cursor_reserved_per_page) = self
            .pragma_database_header()?
            .map_or((PageSize::DEFAULT, 0), |header| {
                (header.page_size, header.reserved_per_page)
            });

        Ok(Some(PreparedDirectSimpleUpdate {
            root_page: table.root_page,
            columns: table.columns.clone(),
            assignments,
            assigns_all_non_ipk_columns,
            fixed_width_real_assignment,
            rowid_param_one_based,
            cursor_page_size,
            cursor_reserved_per_page,
        }))
    }

    fn prepared_direct_simple_update_skips_index_maintenance(
        table: &TableSchema,
        assigned_column_indices: &[usize],
    ) -> bool {
        table.indexes.iter().all(|index| {
            index.supports_direct_column_lookup()
                && index.columns.iter().all(|index_column| {
                    table
                        .column_index(index_column)
                        .is_some_and(|col_idx| !assigned_column_indices.contains(&col_idx))
                })
        })
    }

    /// Build the direct-simple DELETE metadata when the statement shape allows
    /// bypassing VDBE. Mirror of `try_build_prepared_direct_simple_update`.
    fn try_build_prepared_direct_simple_delete(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
    ) -> Result<Option<PreparedDirectSimpleDelete>> {
        if delete.with.is_some()
            || !delete.returning.is_empty()
            || !delete.order_by.is_empty()
            || delete.limit.is_some()
        {
            return Ok(None);
        }
        if delete.table.name.schema.is_some()
            || delete.table.index_hint.is_some()
            || delete.table.time_travel.is_some()
        {
            return Ok(None);
        }
        let table_name = delete.table.name.name.as_str();
        let schema = self.schema.borrow();
        let Some(table) = schema
            .iter()
            .find(|t| t.name.eq_ignore_ascii_case(table_name))
        else {
            return Ok(None);
        };
        if table.without_rowid
            || !table.indexes.is_empty()
            || !table.check_constraints.is_empty()
            || !table.foreign_keys.is_empty()
            || table
                .columns
                .iter()
                .any(|c| c.generated_expr.is_some() || c.generated_stored.is_some())
        {
            return Ok(None);
        }

        let Some(where_expr) = delete.where_clause.as_ref() else {
            // DELETE without WHERE is a full-table delete — intentionally not
            // covered by the direct fast path; VDBE handles it.
            return Ok(None);
        };
        let rowid_alias_col_idx = self
            .rowid_alias_columns
            .borrow()
            .get(&table.name.to_ascii_lowercase())
            .copied();
        let rowid_alias_name = select_table_rowid_alias_name(table, rowid_alias_col_idx);
        let table_label = delete
            .table
            .alias
            .as_deref()
            .unwrap_or(&delete.table.name.name);
        let Some(rowid_param_zero_based) =
            select_rowid_lookup_parameter_index(where_expr, table, table_label, rowid_alias_name)
        else {
            return Ok(None);
        };
        let rowid_param_one_based = rowid_param_zero_based + 1;

        let (cursor_page_size, cursor_reserved_per_page) = self
            .pragma_database_header()?
            .map_or((PageSize::DEFAULT, 0), |header| {
                (header.page_size, header.reserved_per_page)
            });

        Ok(Some(PreparedDirectSimpleDelete {
            root_page: table.root_page,
            rowid_param_one_based,
            cursor_page_size,
            cursor_reserved_per_page,
        }))
    }

    /// Rebuild the schema name side-indices after any mutation to `schema`,
    /// `views`, or `triggers`.
    ///
    /// Called atomically with every `push`/`remove`/`insert`/`clear`/replace
    /// operation on the three schema vectors. Lowercased keys provide
    /// case-insensitive lookups matching SQLite's semantics.
    ///
    /// Rebuilding from scratch is cheap because DDL is rare relative to reads;
    /// incremental maintenance would invite bugs around duplicate names during
    /// rename (brief window where both old and new index entries exist).
    fn rebuild_schema_indices(&self) {
        let schema = self.schema.borrow();
        let mut schema_idx = self.schema_by_name.borrow_mut();
        schema_idx.clear();
        schema_idx.reserve(schema.len());
        for (i, table) in schema.iter().enumerate() {
            schema_idx.insert(table.name.to_ascii_lowercase(), i);
        }
        drop(schema_idx);
        drop(schema);

        let views = self.views.borrow();
        let mut views_idx = self.views_by_name.borrow_mut();
        views_idx.clear();
        views_idx.reserve(views.len());
        for (i, view) in views.iter().enumerate() {
            views_idx.insert(view.name.to_ascii_lowercase(), i);
        }
        drop(views_idx);
        drop(views);

        let triggers = self.triggers.borrow();
        let mut triggers_idx = self.triggers_by_name.borrow_mut();
        triggers_idx.clear();
        triggers_idx.reserve(triggers.len());
        for (i, trigger) in triggers.iter().enumerate() {
            triggers_idx.insert(trigger.name.to_ascii_lowercase(), i);
        }
    }

    /// O(1) lookup of a table's index into the `schema` Vec by case-insensitive name.
    ///
    /// Returns `None` if no table with the given name exists.
    #[inline]
    fn schema_index_of(&self, name: &str) -> Option<usize> {
        let schema_idx = self.schema_by_name.borrow();
        if name.bytes().any(|byte| byte.is_ascii_uppercase()) {
            schema_idx.get(&name.to_ascii_lowercase()).copied()
        } else {
            schema_idx.get(name).copied()
        }
    }

    /// Index of a view by name (case-insensitive), or `None` if no such view.
    fn view_index_of(&self, name: &str) -> Option<usize> {
        let views_idx = self.views_by_name.borrow();
        if name.bytes().any(|byte| byte.is_ascii_uppercase()) {
            views_idx.get(&name.to_ascii_lowercase()).copied()
        } else {
            views_idx.get(name).copied()
        }
    }

    /// Debug-only invariant check: the HashMap side-indices agree with the backing Vecs.
    ///
    /// Invariant: `schema_by_name.get(&k.to_ascii_lowercase()) == Some(i)` implies
    /// `schema[i].name.eq_ignore_ascii_case(&k)`. Analogous for views and triggers.
    #[cfg(debug_assertions)]
    fn validate_schema_index(&self) {
        let schema = self.schema.borrow();
        let schema_idx = self.schema_by_name.borrow();
        assert_eq!(
            schema.len(),
            schema_idx.len(),
            "schema_by_name size {} != schema len {}",
            schema_idx.len(),
            schema.len(),
        );
        for (k, &i) in schema_idx.iter() {
            let entry = schema
                .get(i)
                .unwrap_or_else(|| panic!("schema_by_name[{k}] -> out-of-bounds {i}"));
            assert!(
                entry.name.eq_ignore_ascii_case(k),
                "schema_by_name[{k}] -> {i} but schema[{i}].name = {}",
                entry.name,
            );
        }
        drop(schema_idx);
        drop(schema);

        let views = self.views.borrow();
        let views_idx = self.views_by_name.borrow();
        assert_eq!(views.len(), views_idx.len(), "views_by_name size mismatch");
        for (k, &i) in views_idx.iter() {
            let entry = views
                .get(i)
                .unwrap_or_else(|| panic!("views_by_name[{k}] -> out-of-bounds {i}"));
            assert!(entry.name.eq_ignore_ascii_case(k));
        }
        drop(views_idx);
        drop(views);

        let triggers = self.triggers.borrow();
        let triggers_idx = self.triggers_by_name.borrow();
        assert_eq!(
            triggers.len(),
            triggers_idx.len(),
            "triggers_by_name size mismatch",
        );
        for (k, &i) in triggers_idx.iter() {
            let entry = triggers
                .get(i)
                .unwrap_or_else(|| panic!("triggers_by_name[{k}] -> out-of-bounds {i}"));
            assert!(entry.name.eq_ignore_ascii_case(k));
        }
    }

    /// No-op in release builds; the invariant check only runs with
    /// `debug_assertions`.
    #[cfg(not(debug_assertions))]
    #[inline]
    fn validate_schema_index(&self) {}

    fn table_is_foreign_key_parent(&self, table_name: &str) -> bool {
        self.schema.borrow().iter().any(|table| {
            table
                .foreign_keys
                .iter()
                .any(|fk| fk.parent_table.eq_ignore_ascii_case(table_name))
        })
    }

    fn table_needs_runtime_column_defaults(&self, table_name: &str) -> bool {
        let Some(idx) = self.schema_index_of(table_name) else {
            return false;
        };
        let schema = self.schema.borrow();
        schema.get(idx).is_some_and(|table| {
            table
                .columns
                .iter()
                .any(|column| column.default_value.is_some())
        })
    }

    fn table_has_outbound_foreign_keys(&self, table_name: &str) -> bool {
        let Some(idx) = self.schema_index_of(table_name) else {
            return false;
        };
        let schema = self.schema.borrow();
        schema
            .get(idx)
            .is_some_and(|table| !table.foreign_keys.is_empty())
    }

    fn table_has_foreign_key_work(&self, table_name: &str) -> bool {
        let schema = self.schema.borrow();
        let has_outbound_foreign_keys = self
            .schema_index_of(table_name)
            .and_then(|i| schema.get(i))
            .is_some_and(|table| !table.foreign_keys.is_empty());
        has_outbound_foreign_keys
            || schema.iter().any(|table| {
                table
                    .foreign_keys
                    .iter()
                    .any(|fk| fk.parent_table.eq_ignore_ascii_case(table_name))
            })
    }

    fn insert_runtime_requirements(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> Result<TableExecutionRuntimeRequirements> {
        let target_root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(&insert.table.name))
                .map(|table| table.root_page)
                .ok_or_else(|| {
                    FrankenError::Internal(format!("no such table: {}", insert.table.name))
                })?
        };
        let autoincrement_root_page = self
            .autoincrement_tables
            .borrow()
            .contains(&insert.table.name.to_ascii_lowercase())
            .then_some(target_root_page);
        // Simple VALUES/DEFAULT VALUES inserts already have omitted-column
        // defaults compiled directly into bytecode, so they do not need the
        // connection-level legacy short-record default map.
        let needs_column_defaults = match &insert.source {
            fsqlite_ast::InsertSource::Values(_) | fsqlite_ast::InsertSource::DefaultValues => {
                false
            }
            fsqlite_ast::InsertSource::Select(select_stmt) => {
                !matches!(select_stmt.body.select, SelectCore::Values(_))
                    || !select_stmt.body.compounds.is_empty()
            }
        };
        Ok(TableExecutionRuntimeRequirements::write_path(
            autoincrement_root_page,
            needs_column_defaults,
        ))
    }

    fn prepared_insert_can_skip_statement_savepoint_in_explicit_txn(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> bool {
        if insert.or_conflict == Some(fsqlite_ast::ConflictAction::Rollback) {
            return false;
        }
        if !self.prepared_insert_supports_direct_dispatch(insert) {
            return false;
        }

        let table_name = insert.table.name.as_str();
        let Some(idx) = self.schema_index_of(table_name) else {
            return false;
        };
        let schema = self.schema.borrow();
        let Some(table) = schema.get(idx) else {
            return false;
        };

        // L3: tables with outbound FKs need the statement savepoint so the
        // post-write FK check (added by the s76h fix in
        // execute_precompiled_prepared_insert_dispatch and the fallback
        // helper) rolls back the partial row when the violation is
        // detected during an explicit transaction. Without the savepoint,
        // an FK Err would still propagate to the caller, but the bad row
        // would remain visible to subsequent statements until ROLLBACK,
        // which violates SQLite's immediate-FK semantics.
        if !table.foreign_keys.is_empty() && self.fk_enforcement_enabled() {
            return false;
        }

        !table.without_rowid
            && table.indexes.is_empty()
            && self.prepared_insert_post_write_action(table_name)
                == PreparedInsertPostWriteAction::None
    }

    fn prepared_update_can_skip_statement_savepoint_in_explicit_txn(
        &self,
        update: &fsqlite_ast::UpdateStatement,
    ) -> bool {
        if update.or_conflict == Some(fsqlite_ast::ConflictAction::Rollback)
            || update.from.is_some()
        {
            return false;
        }
        if update.table.name.schema.is_some()
            || update.table.index_hint.is_some()
            || update.table.time_travel.is_some()
        {
            return false;
        }

        let Some(idx) = self.schema_index_of(&update.table.name.name) else {
            return false;
        };
        let schema = self.schema.borrow();
        let Some(table) = schema.get(idx) else {
            return false;
        };
        if table.without_rowid
            || table
                .columns
                .iter()
                .any(|column| column.generated_expr.is_some() || column.generated_stored.is_some())
        {
            return false;
        }

        let rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&table.name.to_ascii_lowercase())
            .copied();
        let rowid_alias_name = select_table_rowid_alias_name(table, rowid_alias_column_index);
        let table_label = update
            .table
            .alias
            .as_deref()
            .unwrap_or(&update.table.name.name);
        if !update.where_clause.as_ref().is_some_and(|predicate| {
            select_rowid_lookup_parameter_index(predicate, table, table_label, rowid_alias_name)
                .is_some()
        }) {
            return false;
        }

        let mut assigned_column_indices = SmallVec::<[usize; 8]>::new();
        for assignment in &update.assignments {
            match &assignment.target {
                fsqlite_ast::AssignmentTarget::Column(column) => {
                    let Some(column_index) = table.column_index(column) else {
                        return false;
                    };
                    let column = &table.columns[column_index];
                    if column.is_ipk
                        || column.unique
                        || column.generated_expr.is_some()
                        || column.generated_stored.is_some()
                        || column.strict_type.is_some()
                    {
                        return false;
                    }
                    assigned_column_indices.push(column_index);
                }
                fsqlite_ast::AssignmentTarget::ColumnList(columns) => {
                    for column_name in columns {
                        let Some(column_index) = table.column_index(column_name) else {
                            return false;
                        };
                        let column = &table.columns[column_index];
                        if column.is_ipk
                            || column.unique
                            || column.generated_expr.is_some()
                            || column.generated_stored.is_some()
                            || column.strict_type.is_some()
                        {
                            return false;
                        }
                        assigned_column_indices.push(column_index);
                    }
                }
            }
        }

        Self::prepared_direct_simple_update_skips_index_maintenance(table, &assigned_column_indices)
    }

    fn prepared_delete_can_skip_statement_savepoint_in_explicit_txn(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
    ) -> bool {
        self.prepared_update_delete_table_can_skip_statement_savepoint_in_explicit_txn(
            &delete.table,
            delete.where_clause.as_ref(),
        )
    }

    fn prepared_update_delete_table_can_skip_statement_savepoint_in_explicit_txn(
        &self,
        table_ref: &fsqlite_ast::QualifiedTableRef,
        where_clause: Option<&Expr>,
    ) -> bool {
        if table_ref.name.schema.is_some()
            || table_ref.index_hint.is_some()
            || table_ref.time_travel.is_some()
        {
            return false;
        }

        let schema = self.schema.borrow();
        let Some(table) = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&table_ref.name.name))
        else {
            return false;
        };
        if table.without_rowid
            || !table.indexes.is_empty()
            || table
                .columns
                .iter()
                .any(|column| column.generated_expr.is_some() || column.generated_stored.is_some())
        {
            return false;
        }

        let rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&table.name.to_ascii_lowercase())
            .copied();
        let rowid_alias_name = select_table_rowid_alias_name(table, rowid_alias_column_index);
        let table_label = table_ref.alias.as_deref().unwrap_or(&table_ref.name.name);
        where_clause.is_some_and(|predicate| {
            select_rowid_lookup_parameter_index(predicate, table, table_label, rowid_alias_name)
                .is_some()
        })
    }

    fn prepared_static_table_runtime_inputs(
        &self,
        requirements: TableExecutionRuntimeRequirements,
    ) -> Option<TableExecutionRuntimeInputs> {
        if requirements.autoincrement_root_page.is_some() || requirements.needs_column_defaults {
            return None;
        }

        let metadata = self.table_execution_metadata();
        Some(TableExecutionRuntimeInputs {
            autoincrement_seq_by_root_page: HbHashMap::new(),
            rowid_alias_col_by_root_page: Arc::clone(&metadata.rowid_alias_col_by_root_page),
            table_column_count_by_root_page: Arc::clone(&metadata.table_column_count_by_root_page),
            first_not_null_non_ipk_col_by_root_page: Arc::clone(
                &metadata.first_not_null_non_ipk_col_by_root_page,
            ),
            column_defaults_by_root_page: empty_column_defaults_arc(),
            index_desc_flags_by_root_page: Arc::clone(&metadata.index_desc_flags_by_root_page),
            index_collations_by_root_page: Arc::clone(&metadata.index_collations_by_root_page),
        })
    }

    fn prepared_insert_post_write_action(&self, table_name: &str) -> PreparedInsertPostWriteAction {
        if table_name.eq_ignore_ascii_case("sqlite_sequence") {
            PreparedInsertPostWriteAction::RefreshSqliteSequenceCache
        } else if self.is_autoincrement_table(table_name) {
            PreparedInsertPostWriteAction::RefreshAutoincrementSequence
        } else {
            PreparedInsertPostWriteAction::None
        }
    }

    fn select_grouped_inner_join_count_sum_is_vdbe_eligible(
        &self,
        select: &SelectStatement,
    ) -> bool {
        use fsqlite_ast::{FunctionArgs, JoinConstraint, JoinKind, TableOrSubquery};

        #[derive(Clone, Copy, PartialEq, Eq)]
        enum JoinSide {
            Left,
            Right,
        }

        let SelectCore::Select {
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            distinct,
            ..
        } = &select.body.select
        else {
            return false;
        };

        if from.joins.len() != 1
            || columns.len() != 3
            || group_by.len() != 1
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || where_clause.is_some()
            || having.is_some()
            || !select.order_by.is_empty()
            || select.limit.is_some()
            || *distinct != Distinctness::All
            || has_ordered_aggregate(select)
            || has_window_functions(select)
            || has_fallback_from_source(select)
            || has_table_function_source(select)
            || select_contains_match_operator(select)
            || select_contains_rewritable_subquery(select)
            || select_has_correlated_join_subquery(select)
        {
            return false;
        }

        let TableOrSubquery::Table {
            name: left_name,
            alias: left_alias,
            time_travel: None,
            ..
        } = &from.source
        else {
            return false;
        };
        let join = &from.joins[0];
        if join.join_type.kind != JoinKind::Inner || join.join_type.natural {
            return false;
        }
        let TableOrSubquery::Table {
            name: right_name,
            alias: right_alias,
            time_travel: None,
            ..
        } = &join.table
        else {
            return false;
        };
        let Some(JoinConstraint::On(on_expr)) = join.constraint.as_ref() else {
            return false;
        };
        let Expr::BinaryOp {
            left: on_left,
            op: BinaryOp::Eq,
            right: on_right,
            ..
        } = on_expr
        else {
            return false;
        };
        let (Expr::Column(on_left_col, _), Expr::Column(on_right_col, _)) =
            (&**on_left, &**on_right)
        else {
            return false;
        };
        if on_left_col.table.is_none() || on_right_col.table.is_none() {
            return false;
        }

        let ResultColumn::Expr {
            expr: group_key_expr,
            ..
        } = &columns[0]
        else {
            return false;
        };
        let Expr::Column(group_key_col, _) = group_key_expr else {
            return false;
        };
        let Expr::Column(group_by_col, _) = &group_by[0] else {
            return false;
        };
        if group_key_col.table.is_none()
            || group_by_col.table.is_none()
            || !group_key_col
                .column
                .eq_ignore_ascii_case(&group_by_col.column)
            || !group_key_col
                .table
                .as_deref()
                .zip(group_by_col.table.as_deref())
                .is_some_and(|(left, right)| left.eq_ignore_ascii_case(right))
        {
            return false;
        }

        let ResultColumn::Expr {
            expr: count_expr, ..
        } = &columns[1]
        else {
            return false;
        };
        match count_expr {
            Expr::FunctionCall {
                name,
                args: FunctionArgs::Star,
                distinct: false,
                filter: None,
                over: None,
                ..
            } if name.eq_ignore_ascii_case("count") => {}
            _ => return false,
        }

        let ResultColumn::Expr { expr: sum_expr, .. } = &columns[2] else {
            return false;
        };
        let sum_arg_expr = match sum_expr {
            Expr::FunctionCall {
                name,
                args: FunctionArgs::List(args),
                distinct: false,
                filter: None,
                over: None,
                ..
            } if name.eq_ignore_ascii_case("sum") && args.len() == 1 => &args[0],
            _ => return false,
        };
        let Expr::Column(sum_arg_col, _) = sum_arg_expr else {
            return false;
        };
        if sum_arg_col.table.is_none() {
            return false;
        }

        let schema = self.schema.borrow();
        let left_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&left_name.name));
        let right_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&right_name.name));
        let (Some(left_table), Some(right_table)) = (left_table, right_table) else {
            return false;
        };

        let resolve_qualified_column = |col_ref: &ColumnRef| -> Option<(JoinSide, &ColumnInfo)> {
            let qualifier = col_ref.table.as_deref()?;
            let (side, table) = if qualifier.eq_ignore_ascii_case(&left_name.name)
                || left_alias
                    .as_deref()
                    .is_some_and(|alias| qualifier.eq_ignore_ascii_case(alias))
            {
                (JoinSide::Left, left_table)
            } else if qualifier.eq_ignore_ascii_case(&right_name.name)
                || right_alias
                    .as_deref()
                    .is_some_and(|alias| qualifier.eq_ignore_ascii_case(alias))
            {
                (JoinSide::Right, right_table)
            } else {
                return None;
            };
            table
                .columns
                .iter()
                .find(|column| column.name.eq_ignore_ascii_case(&col_ref.column))
                .map(|column| (side, column))
        };

        let group_key_col_info = resolve_qualified_column(group_key_col).map(|(_, column)| column);
        if !group_key_col_info.is_some_and(|column| {
            column
                .collation
                .as_deref()
                .is_none_or(|collation| collation.eq_ignore_ascii_case("BINARY"))
        }) {
            return false;
        }

        let join_key_is_supported = |column: &ColumnInfo| {
            column
                .collation
                .as_deref()
                .is_none_or(|collation| collation.eq_ignore_ascii_case("BINARY"))
                && (column.is_ipk || matches!(column.affinity, 'D' | 'd' | 'C' | 'c'))
        };

        let Some((on_left_side, on_left_info)) = resolve_qualified_column(on_left_col) else {
            return false;
        };
        let Some((on_right_side, on_right_info)) = resolve_qualified_column(on_right_col) else {
            return false;
        };
        if on_left_side == on_right_side
            || !join_key_is_supported(on_left_info)
            || !join_key_is_supported(on_right_info)
        {
            return false;
        }

        let right_lookup_supported = match (on_left_side, on_right_side) {
            (JoinSide::Left, JoinSide::Right) => {
                on_right_info.is_ipk || right_table.index_for_column(&on_right_col.column).is_some()
            }
            (JoinSide::Right, JoinSide::Left) => {
                on_left_info.is_ipk || right_table.index_for_column(&on_left_col.column).is_some()
            }
            _ => false,
        };
        if !right_lookup_supported {
            return false;
        }

        resolve_qualified_column(sum_arg_col).is_some()
    }

    fn prepared_count_indexed_rowid_probe_fast_path(
        &self,
        select: &SelectStatement,
        table: &TableSchema,
        table_label: &str,
    ) -> Option<PreparedQueryFastPath> {
        let SelectCore::Select {
            distinct,
            columns,
            where_clause: Some(predicate),
            group_by,
            having,
            windows,
            ..
        } = &select.body.select
        else {
            return None;
        };
        if !matches!(distinct, Distinctness::All)
            || !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
        {
            return None;
        }
        let [
            ResultColumn::Expr {
                expr:
                    Expr::FunctionCall {
                        name,
                        args: FunctionArgs::Star,
                        distinct: false,
                        order_by,
                        filter: None,
                        over: None,
                        ..
                    },
                ..
            },
        ] = columns.as_slice()
        else {
            return None;
        };
        if !name.eq_ignore_ascii_case("count") || !order_by.is_empty() {
            return None;
        }

        let schema = self.schema.borrow();
        let rowid_alias_columns = self.rowid_alias_columns.borrow();

        let spec = match predicate.as_ref() {
            Expr::Exists {
                subquery,
                not: false,
                ..
            } => {
                if subquery.with.is_some()
                    || !subquery.body.compounds.is_empty()
                    || !subquery.order_by.is_empty()
                    || subquery.limit.is_some()
                {
                    return None;
                }
                let SelectCore::Select {
                    from: Some(probe_from),
                    where_clause: Some(sub_where),
                    group_by,
                    having,
                    windows,
                    ..
                } = &subquery.body.select
                else {
                    return None;
                };
                if !group_by.is_empty()
                    || having.is_some()
                    || !windows.is_empty()
                    || !probe_from.joins.is_empty()
                {
                    return None;
                }
                let TableOrSubquery::Table { name, alias, .. } = &probe_from.source else {
                    return None;
                };
                let probe_table = schema
                    .iter()
                    .find(|candidate| candidate.name.eq_ignore_ascii_case(&name.name))?;
                let probe_label = alias.as_deref().unwrap_or(&name.name);
                let probe_rowid_alias_name = select_table_rowid_alias_name(
                    probe_table,
                    rowid_alias_columns
                        .get(&probe_table.name.to_ascii_lowercase())
                        .copied(),
                );

                let mut terms = Vec::new();
                flatten_and_terms(sub_where, &mut terms);

                let mut probe_spec = None;
                let mut probe_rowid_upper_exclusive = None;
                for term in terms {
                    if probe_spec.is_none()
                        && let Expr::BinaryOp {
                            left,
                            op: BinaryOp::Eq,
                            right,
                            ..
                        } = term
                    {
                        if let Expr::Column(col_ref, _) = left.as_ref()
                            && column_ref_matches_table_rowid(
                                col_ref,
                                probe_table,
                                probe_label,
                                probe_rowid_alias_name,
                            )
                            && let Some((column_index, index_root_page)) =
                                select_labeled_indexed_numeric_probe_spec(table, table_label, right)
                        {
                            probe_spec = Some((column_index, index_root_page));
                            continue;
                        }
                        if let Expr::Column(col_ref, _) = right.as_ref()
                            && column_ref_matches_table_rowid(
                                col_ref,
                                probe_table,
                                probe_label,
                                probe_rowid_alias_name,
                            )
                            && let Some((column_index, index_root_page)) =
                                select_labeled_indexed_numeric_probe_spec(table, table_label, left)
                        {
                            probe_spec = Some((column_index, index_root_page));
                            continue;
                        }
                    }

                    let upper = select_rowid_upper_bound_exclusive(
                        term,
                        probe_table,
                        probe_label,
                        probe_rowid_alias_name,
                    )?;
                    if probe_rowid_upper_exclusive.replace(upper).is_some() {
                        return None;
                    }
                }

                let (column_index, index_root_page) = probe_spec?;
                PreparedCountIndexedRowidProbeSpec {
                    column_index,
                    index_root_page,
                    probe_root_page: probe_table.root_page,
                    probe_rowid_upper_exclusive,
                }
            }
            Expr::In {
                expr,
                set: InSet::Subquery(subquery),
                not: false,
                ..
            } => {
                if subquery.with.is_some()
                    || !subquery.body.compounds.is_empty()
                    || !subquery.order_by.is_empty()
                    || subquery.limit.is_some()
                {
                    return None;
                }
                let (column_index, index_root_page) =
                    select_indexed_numeric_probe_spec(table, table_label, expr)?;
                let SelectCore::Select {
                    columns,
                    from: Some(probe_from),
                    where_clause,
                    group_by,
                    having,
                    windows,
                    ..
                } = &subquery.body.select
                else {
                    return None;
                };
                if !group_by.is_empty()
                    || having.is_some()
                    || !windows.is_empty()
                    || !probe_from.joins.is_empty()
                {
                    return None;
                }
                let [
                    ResultColumn::Expr {
                        expr: probe_expr, ..
                    },
                ] = columns.as_slice()
                else {
                    return None;
                };
                let TableOrSubquery::Table { name, alias, .. } = &probe_from.source else {
                    return None;
                };
                let probe_table = schema
                    .iter()
                    .find(|candidate| candidate.name.eq_ignore_ascii_case(&name.name))?;
                let probe_label = alias.as_deref().unwrap_or(&name.name);
                let probe_rowid_alias_name = select_table_rowid_alias_name(
                    probe_table,
                    rowid_alias_columns
                        .get(&probe_table.name.to_ascii_lowercase())
                        .copied(),
                );
                let Expr::Column(col_ref, _) = probe_expr else {
                    return None;
                };
                if !column_ref_matches_table_rowid(
                    col_ref,
                    probe_table,
                    probe_label,
                    probe_rowid_alias_name,
                ) {
                    return None;
                }

                let probe_rowid_upper_exclusive =
                    where_clause.as_deref().map_or(Some(None), |expr| {
                        select_rowid_upper_bound_exclusive(
                            expr,
                            probe_table,
                            probe_label,
                            probe_rowid_alias_name,
                        )
                        .map(Some)
                    })?;

                PreparedCountIndexedRowidProbeSpec {
                    column_index,
                    index_root_page,
                    probe_root_page: probe_table.root_page,
                    probe_rowid_upper_exclusive,
                }
            }
            _ => return None,
        };

        Some(PreparedQueryFastPath::SimpleCountIndexedRowidProbe {
            root_page: table.root_page,
            index_root_page: spec.index_root_page,
            column_index: spec.column_index,
            probe_root_page: spec.probe_root_page,
            probe_rowid_upper_exclusive: spec.probe_rowid_upper_exclusive,
        })
    }

    fn prepared_select_requires_dispatch(&self, statement: &Statement) -> bool {
        let Statement::Select(select) = statement else {
            return false;
        };

        let expression_only = is_expression_only_select(select);
        let has_ordered_aggregate = has_ordered_aggregate(select);
        let has_grouping =
            has_group_by(select) || has_implicit_aggregation(select) || has_ordered_aggregate;
        let has_join_like_source = has_joins(select) || has_fallback_from_source(select);
        let has_vdbe_eligible_join = has_joins(select) && select_join_is_vdbe_eligible(select);
        let has_vdbe_eligible_grouped_join =
            self.select_grouped_inner_join_count_sum_is_vdbe_eligible(select);
        let has_vdbe_eligible_group_by =
            self.select_group_by_storage_substrate_is_vdbe_eligible(select);
        let has_dispatch_only_subquery = select_contains_prepared_dispatch_subquery(select, self);
        let has_primary_live_vtab_source = self.has_primary_live_vtab_source(select);
        let prefer_memdb_hash_join_dispatch = self.prefer_memdb_hash_join_dispatch(select);
        let prefer_memdb_hash_grouped_join_dispatch =
            self.prefer_memdb_hash_grouped_join_dispatch(select);

        prefer_memdb_hash_join_dispatch
            || prefer_memdb_hash_grouped_join_dispatch
            || has_dispatch_only_subquery
            || select.with.is_some()
            || self.has_view_references(select)
            || self.has_sqlite_schema_references(select)
            || select_references_non_main_schema(select)
            || !select.body.compounds.is_empty()
            || has_primary_live_vtab_source
            || (expression_only && has_implicit_aggregation(select))
            || (expression_only && expression_only_has_subquery(select))
            || (has_grouping && has_join_like_source && !has_vdbe_eligible_grouped_join)
            || (has_group_by(select)
                && !has_vdbe_eligible_grouped_join
                && !has_vdbe_eligible_group_by)
            || has_ordered_aggregate
            || has_window_functions(select)
            || (has_join_like_source && !has_vdbe_eligible_join && !has_vdbe_eligible_grouped_join)
            || select_has_correlated_join_subquery(select)
            || self.select_correlated_exists_where_requires_fallback(select)
    }

    fn select_correlated_exists_where_requires_fallback(&self, select: &SelectStatement) -> bool {
        if !select_has_correlated_exists_in_where(select) {
            return false;
        }
        !self.select_correlated_exists_where_can_use_indexed_count_probe(select)
    }

    fn execute_correlated_subquery_where_fallback(
        &self,
        cx: &Cx,
        select: &SelectStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        let rewritten = self.rewrite_in_subqueries_select(select, params)?;
        let mut bound = bind_placeholders_in_select_for_fallback(rewritten.as_ref(), params)?;
        let limit_clause = bound.limit.take();
        let mut rows = if has_group_by(&bound)
            || has_implicit_aggregation(&bound)
            || has_ordered_aggregate(&bound)
        {
            self.execute_group_by_join_select(cx, &bound, None)?
        } else {
            self.execute_join_select(&bound, None)?
        };
        if let Some(limit) = limit_clause {
            apply_limit_clause(&mut rows, &limit);
        }
        Ok(rows)
    }

    fn select_correlated_exists_where_can_use_indexed_count_probe(
        &self,
        select: &SelectStatement,
    ) -> bool {
        let Ok(normalized) = canonicalize_select_placeholders(select) else {
            return false;
        };
        let SelectCore::Select {
            distinct,
            from: Some(from),
            ..
        } = &normalized.body.select
        else {
            return false;
        };
        if !matches!(distinct, Distinctness::All)
            || normalized.with.is_some()
            || !normalized.body.compounds.is_empty()
            || !normalized.order_by.is_empty()
            || normalized.limit.is_some()
            || !from.joins.is_empty()
        {
            return false;
        }
        let TableOrSubquery::Table {
            name,
            alias,
            index_hint,
            time_travel,
            ..
        } = &from.source
        else {
            return false;
        };
        if name.schema.is_some() || index_hint.is_some() || time_travel.is_some() {
            return false;
        }

        let schema = self.schema.borrow();
        let Some(table) = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&name.name))
        else {
            return false;
        };
        let table_label = alias.as_deref().unwrap_or(&name.name);
        self.prepared_count_indexed_rowid_probe_fast_path(&normalized, table, table_label)
            .is_some()
    }

    fn prepared_query_fast_path(&self, statement: &Statement) -> Option<PreparedQueryFastPath> {
        let Statement::Select(select) = statement else {
            return None;
        };
        self.prepared_select_fast_path(select)
    }

    fn prepared_simple_order_by_limit_fast_path(
        &self,
        select: &SelectStatement,
        schema: &[TableSchema],
    ) -> Option<PreparedQueryFastPath> {
        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            windows,
        } = &select.body.select
        else {
            return None;
        };
        if *distinct != Distinctness::All
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || where_clause.is_some()
            || !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
            || !matches!(columns.as_slice(), [ResultColumn::Star])
            || !from.joins.is_empty()
        {
            return None;
        }

        let [order_term] = select.order_by.as_slice() else {
            return None;
        };
        let limit = select
            .limit
            .as_ref()
            .filter(|limit| limit.offset.is_none())
            .and_then(|limit| select_integer_literal(&limit.limit))
            .and_then(|limit| usize::try_from(limit).ok())?;

        let TableOrSubquery::Table {
            name,
            alias,
            index_hint,
            time_travel,
            ..
        } = &from.source
        else {
            return None;
        };
        if name.schema.is_some() || index_hint.is_some() || time_travel.is_some() {
            return None;
        }
        let table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&name.name))?;
        let table_label = alias.as_deref().unwrap_or(&name.name);
        let rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&table.name.to_ascii_lowercase())
            .copied();
        let rowid_alias_name = select_table_rowid_alias_name(table, rowid_alias_column_index);
        let order_source =
            select_table_value_source(table, table_label, &order_term.expr, rowid_alias_name)?;
        let descending = order_term.direction == Some(SortDirection::Desc);
        let nulls_order = order_term
            .nulls
            .unwrap_or_else(|| default_nulls_order(order_term.direction));
        if prepared_order_by_limit_has_storage_ordered_path(
            table,
            order_source,
            descending,
            nulls_order,
        ) {
            return None;
        }

        Some(PreparedQueryFastPath::SimpleOrderByLimit {
            root_page: table.root_page,
            order_source,
            rowid_alias_column_index,
            descending,
            nulls_order,
            limit,
        })
    }

    fn prepared_simple_inner_join_grouped_aggregate_fast_path(
        &self,
        select: &SelectStatement,
        schema: &[TableSchema],
    ) -> Option<PreparedQueryFastPath> {
        use fsqlite_ast::{FunctionArgs, JoinConstraint, JoinKind, TableOrSubquery};

        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            windows,
        } = &select.body.select
        else {
            return None;
        };
        if *distinct != Distinctness::All
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || where_clause.is_some()
            || !windows.is_empty()
            || !select.order_by.is_empty()
            || select.limit.is_some()
            || from.joins.len() != 1
            || group_by.len() != 1
            || !(columns.len() == 2 || columns.len() == 3)
        {
            return None;
        }

        let TableOrSubquery::Table {
            name: left_name,
            alias: left_alias,
            index_hint: left_index_hint,
            time_travel: left_time_travel,
            ..
        } = &from.source
        else {
            return None;
        };
        if left_name.schema.is_some() || left_index_hint.is_some() || left_time_travel.is_some() {
            return None;
        }
        let join = &from.joins[0];
        if join.join_type.kind != JoinKind::Inner || join.join_type.natural {
            return None;
        }
        let TableOrSubquery::Table {
            name: right_name,
            alias: right_alias,
            index_hint: right_index_hint,
            time_travel: right_time_travel,
            ..
        } = &join.table
        else {
            return None;
        };
        if right_name.schema.is_some() || right_index_hint.is_some() || right_time_travel.is_some()
        {
            return None;
        }

        let left_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&left_name.name))?;
        let right_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&right_name.name))?;
        let left_label = left_alias.as_deref().unwrap_or(&left_name.name);
        let right_label = right_alias.as_deref().unwrap_or(&right_name.name);
        let left_rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&left_table.name.to_ascii_lowercase())
            .copied();
        let right_rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&right_table.name.to_ascii_lowercase())
            .copied();
        let left_rowid_alias_name =
            select_table_rowid_alias_name(left_table, left_rowid_alias_column_index);
        let right_rowid_alias_name =
            select_table_rowid_alias_name(right_table, right_rowid_alias_column_index);

        let Some(JoinConstraint::On(on_expr)) = join.constraint.as_ref() else {
            return None;
        };
        let Expr::BinaryOp {
            left: on_left,
            op: BinaryOp::Eq,
            right: on_right,
            ..
        } = on_expr
        else {
            return None;
        };
        let (left_join_source, right_join_source) = match (
            select_labeled_table_value_source(
                left_table,
                left_label,
                on_left,
                left_rowid_alias_name,
            ),
            select_labeled_table_value_source(
                right_table,
                right_label,
                on_right,
                right_rowid_alias_name,
            ),
        ) {
            (Some(left_source), Some(right_source)) => (left_source, right_source),
            _ => match (
                select_labeled_table_value_source(
                    left_table,
                    left_label,
                    on_right,
                    left_rowid_alias_name,
                ),
                select_labeled_table_value_source(
                    right_table,
                    right_label,
                    on_left,
                    right_rowid_alias_name,
                ),
            ) {
                (Some(left_source), Some(right_source)) => (left_source, right_source),
                _ => return None,
            },
        };

        let ResultColumn::Expr {
            expr: group_expr, ..
        } = &columns[0]
        else {
            return None;
        };
        let left_group_source = select_unambiguous_join_table_value_source(
            left_table,
            left_label,
            right_table,
            right_label,
            group_expr,
            left_rowid_alias_name,
            right_rowid_alias_name,
        )?;
        let group_by_source = select_unambiguous_join_table_value_source(
            left_table,
            left_label,
            right_table,
            right_label,
            &group_by[0],
            left_rowid_alias_name,
            right_rowid_alias_name,
        )?;
        let (Expr::Column(group_by_col, _), Expr::Column(group_result_col, _)) =
            (&group_by[0], group_expr)
        else {
            return None;
        };
        if group_by_source != left_group_source
            || !group_by_col
                .column
                .eq_ignore_ascii_case(&group_result_col.column)
        {
            return None;
        }

        let ResultColumn::Expr {
            expr: count_expr,
            alias: count_alias,
        } = &columns[1]
        else {
            return None;
        };
        let Expr::FunctionCall {
            name,
            args: FunctionArgs::Star,
            distinct: false,
            order_by,
            filter: None,
            over: None,
            ..
        } = count_expr
        else {
            return None;
        };
        if !name.eq_ignore_ascii_case("count") || !order_by.is_empty() {
            return None;
        }

        let sum_source = if columns.len() == 3 {
            let ResultColumn::Expr { expr: sum_expr, .. } = &columns[2] else {
                return None;
            };
            let Expr::FunctionCall {
                name,
                args: FunctionArgs::List(args),
                distinct: false,
                order_by,
                filter: None,
                over: None,
                ..
            } = sum_expr
            else {
                return None;
            };
            if !name.eq_ignore_ascii_case("sum") || !order_by.is_empty() || args.len() != 1 {
                return None;
            }
            Some(select_unambiguous_join_table_value_source(
                right_table,
                right_label,
                left_table,
                left_label,
                &args[0],
                right_rowid_alias_name,
                left_rowid_alias_name,
            )?)
        } else {
            None
        };

        let having_count_filter = if let Some(expr) = having.as_ref() {
            Some(prepared_count_having_filter(expr, count_alias.as_deref())?)
        } else {
            None
        };

        let indexed_right_join =
            if let PreparedMemValueSource::Column(right_join_column_index) = right_join_source {
                let right_join_column = right_table.columns.get(right_join_column_index)?;
                right_table
                    .indexes
                    .iter()
                    .filter(|index| simple_index_supports_prepared_text_equality_fast_path(index))
                    .find(|index| {
                        index.columns.first().is_some_and(|column| {
                            column.eq_ignore_ascii_case(&right_join_column.name)
                        })
                    })
                    .map(|index| (index.root_page, right_join_column_index))
            } else {
                None
            };

        Some(PreparedQueryFastPath::SimpleInnerJoinGroupedAggregate {
            left_root_page: left_table.root_page,
            left_join_source,
            left_join_rowid_alias_column_index: left_rowid_alias_column_index,
            left_group_source,
            left_group_rowid_alias_column_index: left_rowid_alias_column_index,
            right_root_page: right_table.root_page,
            right_join_source,
            right_index_root_page: indexed_right_join.map(|(root_page, _)| root_page),
            right_join_column_index: indexed_right_join.map(|(_, column_index)| column_index),
            right_join_rowid_alias_column_index: right_rowid_alias_column_index,
            sum_source,
            right_sum_rowid_alias_column_index: right_rowid_alias_column_index,
            having_count_filter,
        })
    }

    fn prepared_simple_select_projection_sources(
        columns: &[ResultColumn],
        table: &TableSchema,
        table_label: &str,
        rowid_alias_name: Option<&str>,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<Arc<[PreparedMemValueSource]>> {
        let mut sources = Vec::new();
        for column in columns {
            match column {
                ResultColumn::Star => {
                    sources.extend((0..table.columns.len()).map(|column_index| {
                        if Some(column_index) == rowid_alias_column_index {
                            PreparedMemValueSource::Rowid
                        } else {
                            PreparedMemValueSource::Column(column_index)
                        }
                    }));
                }
                ResultColumn::TableStar(name)
                    if name.schema.is_none() && name.name.eq_ignore_ascii_case(table_label) =>
                {
                    sources.extend((0..table.columns.len()).map(|column_index| {
                        if Some(column_index) == rowid_alias_column_index {
                            PreparedMemValueSource::Rowid
                        } else {
                            PreparedMemValueSource::Column(column_index)
                        }
                    }));
                }
                ResultColumn::Expr { expr, .. } => {
                    sources.push(select_table_value_source(
                        table,
                        table_label,
                        expr,
                        rowid_alias_name,
                    )?);
                }
                ResultColumn::TableStar(_) => return None,
            }
        }
        (!sources.is_empty()).then_some(Arc::from(sources))
    }

    fn prepared_simple_rowid_lookup_fast_path(
        &self,
        columns: &[ResultColumn],
        predicate: &Expr,
        table: &TableSchema,
        table_label: &str,
        rowid_alias_name: Option<&str>,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<PreparedQueryFastPath> {
        let parameter_index =
            select_rowid_lookup_parameter_index(predicate, table, table_label, rowid_alias_name)?;
        if matches!(columns, [ResultColumn::Star]) {
            return Some(PreparedQueryFastPath::SimpleRowidLookup {
                root_page: table.root_page,
                parameter_index,
                rowid_alias_column_index,
            });
        }
        let projections = Self::prepared_simple_select_projection_sources(
            columns,
            table,
            table_label,
            rowid_alias_name,
            rowid_alias_column_index,
        )?;
        Some(PreparedQueryFastPath::SimpleProjectedRowidLookup {
            root_page: table.root_page,
            parameter_index,
            rowid_alias_column_index,
            projections,
        })
    }

    fn prepared_simple_indexed_two_table_join_fast_path(
        &self,
        select: &SelectStatement,
        schema: &[TableSchema],
    ) -> Option<PreparedQueryFastPath> {
        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            windows,
        } = &select.body.select
        else {
            return None;
        };
        if *distinct != Distinctness::All
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || where_clause.is_some()
            || !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
            || !select.order_by.is_empty()
            || select.limit.is_some()
            || from.joins.len() != 1
        {
            return None;
        }

        let TableOrSubquery::Table {
            name: left_name,
            alias: left_alias,
            index_hint: left_index_hint,
            time_travel: left_time_travel,
            ..
        } = &from.source
        else {
            return None;
        };
        if left_name.schema.is_some() || left_index_hint.is_some() || left_time_travel.is_some() {
            return None;
        }

        let join = &from.joins[0];
        if join.join_type.natural
            || !matches!(join.join_type.kind, JoinKind::Inner | JoinKind::Left)
        {
            return None;
        }
        let TableOrSubquery::Table {
            name: right_name,
            alias: right_alias,
            index_hint: right_index_hint,
            time_travel: right_time_travel,
            ..
        } = &join.table
        else {
            return None;
        };
        if right_name.schema.is_some() || right_index_hint.is_some() || right_time_travel.is_some()
        {
            return None;
        }

        let left_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&left_name.name))?;
        let right_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&right_name.name))?;
        let left_label = left_alias.as_deref().unwrap_or(&left_name.name);
        let right_label = right_alias.as_deref().unwrap_or(&right_name.name);
        let left_rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&left_table.name.to_ascii_lowercase())
            .copied();
        let right_rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&right_table.name.to_ascii_lowercase())
            .copied();
        let left_rowid_alias_name =
            select_table_rowid_alias_name(left_table, left_rowid_alias_column_index);
        let right_rowid_alias_name =
            select_table_rowid_alias_name(right_table, right_rowid_alias_column_index);

        let Some(JoinConstraint::On(on_expr)) = join.constraint.as_ref() else {
            return None;
        };
        let Expr::BinaryOp {
            left: on_left,
            op: BinaryOp::Eq,
            right: on_right,
            ..
        } = on_expr
        else {
            return None;
        };
        let (left_join_source, right_join_source) = match (
            select_labeled_table_value_source(
                left_table,
                left_label,
                on_left,
                left_rowid_alias_name,
            ),
            select_labeled_table_value_source(
                right_table,
                right_label,
                on_right,
                right_rowid_alias_name,
            ),
        ) {
            (Some(left_source), Some(right_source)) => (left_source, right_source),
            _ => match (
                select_labeled_table_value_source(
                    left_table,
                    left_label,
                    on_right,
                    left_rowid_alias_name,
                ),
                select_labeled_table_value_source(
                    right_table,
                    right_label,
                    on_left,
                    right_rowid_alias_name,
                ),
            ) {
                (Some(left_source), Some(right_source)) => (left_source, right_source),
                _ => return None,
            },
        };
        let PreparedMemValueSource::Column(right_join_column_index) = right_join_source else {
            return None;
        };
        let right_join_column = right_table.columns.get(right_join_column_index)?;
        let right_index_root_page = right_table
            .indexes
            .iter()
            .filter(|index| simple_index_supports_prepared_text_equality_fast_path(index))
            .find(|index| {
                index
                    .columns
                    .first()
                    .is_some_and(|column| column.eq_ignore_ascii_case(&right_join_column.name))
            })
            .map(|index| index.root_page)?;

        let mut projections = Vec::with_capacity(columns.len());
        for column in columns {
            let ResultColumn::Expr { expr, .. } = column else {
                return None;
            };
            let projection = select_unambiguous_join_table_value_source(
                left_table,
                left_label,
                right_table,
                right_label,
                expr,
                left_rowid_alias_name,
                right_rowid_alias_name,
            )
            .map(PreparedJoinProjectionSource::Left)
            .or_else(|| {
                select_unambiguous_join_table_value_source(
                    right_table,
                    right_label,
                    left_table,
                    left_label,
                    expr,
                    right_rowid_alias_name,
                    left_rowid_alias_name,
                )
                .map(PreparedJoinProjectionSource::Right)
            })?;
            projections.push(projection);
        }

        Some(PreparedQueryFastPath::SimpleIndexedTwoTableJoin {
            left_root_page: left_table.root_page,
            left_join_source,
            left_join_rowid_alias_column_index: left_rowid_alias_column_index,
            right_root_page: right_table.root_page,
            right_index_root_page,
            right_join_column_index,
            right_join_rowid_alias_column_index: right_rowid_alias_column_index,
            join_kind: join.join_type.kind,
            projections: Arc::from(projections),
        })
    }

    fn prepared_select_fast_path(&self, select: &SelectStatement) -> Option<PreparedQueryFastPath> {
        let normalized = canonicalize_select_placeholders(select).ok()?;
        let schema = self.schema.borrow();
        if let Some(plan) = self.top_category_cte_join_plan(&normalized) {
            return Some(PreparedQueryFastPath::TopCategoryCteJoin { plan });
        }
        if let Some(fast_path) =
            self.prepared_limited_scalar_rowid_subquery_fast_path(&normalized, &schema)
        {
            return Some(fast_path);
        }
        if let Some(fast_path) = self.prepared_simple_order_by_limit_fast_path(&normalized, &schema)
        {
            return Some(fast_path);
        }
        if let Some(fast_path) =
            self.prepared_simple_indexed_two_table_join_fast_path(&normalized, &schema)
        {
            return Some(fast_path);
        }
        if let Some(fast_path) =
            self.prepared_simple_inner_join_grouped_aggregate_fast_path(&normalized, &schema)
        {
            return Some(fast_path);
        }

        let SelectCore::Select {
            distinct,
            from: Some(from),
            ..
        } = &normalized.body.select
        else {
            return None;
        };
        if !matches!(distinct, Distinctness::All)
            || normalized.with.is_some()
            || !normalized.body.compounds.is_empty()
            || !normalized.order_by.is_empty()
            || normalized.limit.is_some()
            || !from.joins.is_empty()
        {
            return None;
        }
        let TableOrSubquery::Table {
            name,
            alias,
            index_hint,
            time_travel,
            ..
        } = &from.source
        else {
            return None;
        };
        if name.schema.is_some() || index_hint.is_some() || time_travel.is_some() {
            return None;
        }

        let table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&name.name))?;
        let table_label = alias.as_deref().unwrap_or(&name.name);
        if select_is_plain_count_star(&normalized) {
            return Some(PreparedQueryFastPath::SimpleCountStar {
                root_page: table.root_page,
            });
        }

        let SelectCore::Select {
            columns,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } = &normalized.body.select
        else {
            return None;
        };
        let rowid_alias_column_index = self
            .rowid_alias_columns
            .borrow()
            .get(&table.name.to_ascii_lowercase())
            .copied();
        if where_clause.is_none()
            && group_by.is_empty()
            && having.is_none()
            && windows.is_empty()
            && let Some(fast_path) = self.prepared_count_star_sum_fast_path(
                columns,
                table,
                table_label,
                rowid_alias_column_index,
            )
        {
            return Some(fast_path);
        }
        if let Some(fast_path) = self.prepared_count_like_pattern_fast_path(
            &normalized,
            table,
            table_label,
            rowid_alias_column_index,
        ) {
            return Some(fast_path);
        }
        if let Some(fast_path) =
            self.prepared_count_indexed_rowid_probe_fast_path(&normalized, table, table_label)
        {
            return Some(fast_path);
        }
        let rowid_alias_name = select_table_rowid_alias_name(table, rowid_alias_column_index);
        if let Some(fast_path) = self.prepared_simple_group_concat_fast_path(
            &normalized,
            table,
            table_label,
            rowid_alias_column_index,
        ) {
            return Some(fast_path);
        }
        if !group_by.is_empty() || having.is_some() || !windows.is_empty() {
            return None;
        }

        if matches!(columns.as_slice(), [ResultColumn::Star]) && where_clause.is_none() {
            return Some(PreparedQueryFastPath::SimpleFullTableScan {
                root_page: table.root_page,
                rowid_alias_column_index,
            });
        }
        if where_clause.is_none()
            && let Some(fast_path) = self.prepared_simple_string_projection_fast_path(
                columns,
                table,
                table_label,
                rowid_alias_column_index,
            )
        {
            return Some(fast_path);
        }

        if let Some(predicate) = where_clause.as_ref()
            && let Some(fast_path) = self.prepared_simple_rowid_lookup_fast_path(
                columns,
                predicate,
                table,
                table_label,
                rowid_alias_name,
                rowid_alias_column_index,
            )
        {
            return Some(fast_path);
        }

        if let Some(predicate) = where_clause.as_ref()
            && let Some((column_index, parameter_index, index_root_page)) = table
                .indexes
                .iter()
                .filter(|index| simple_index_supports_prepared_text_equality_fast_path(index))
                .find_map(|index| {
                    let column_name = index.columns.first()?;
                    let column_index = table.column_index(column_name)?;
                    let column = table.columns.get(column_index)?;
                    (!column.is_ipk && column.affinity == 'B').then_some((
                        column_index,
                        select_column_lookup_parameter_index(predicate, table_label, column_name)?,
                        index.root_page,
                    ))
                })
        {
            let projections = if matches!(columns.as_slice(), [ResultColumn::Star]) {
                None
            } else {
                Some(Self::prepared_simple_select_projection_sources(
                    columns,
                    table,
                    table_label,
                    rowid_alias_name,
                    rowid_alias_column_index,
                )?)
            };
            return Some(PreparedQueryFastPath::SimpleIndexedEqualityLookup {
                root_page: table.root_page,
                index_root_page,
                column_index,
                parameter_index,
                rowid_alias_column_index,
                projections,
            });
        }

        if matches!(columns.as_slice(), [ResultColumn::Star])
            && let Some(predicate) = where_clause.as_ref()
            && let Some((lower_parameter_index, upper_parameter_index)) =
                select_rowid_range_parameter_indices(
                    predicate,
                    table,
                    table_label,
                    rowid_alias_name,
                )
        {
            return Some(PreparedQueryFastPath::SimpleRowidRangeScan {
                root_page: table.root_page,
                lower_parameter_index,
                upper_parameter_index,
                rowid_alias_column_index,
            });
        }

        if let Some(predicate) = where_clause.as_ref()
            && let Some((lower_parameter_index, upper_parameter_index)) =
                select_count_star_rowid_range_parameter_indices(
                    predicate,
                    table,
                    table_label,
                    rowid_alias_name,
                )
            && select_is_plain_count_star(&SelectStatement {
                with: normalized.with.clone(),
                body: SelectBody {
                    select: SelectCore::Select {
                        distinct: *distinct,
                        columns: columns.clone(),
                        from: Some(from.clone()),
                        where_clause: None,
                        group_by: group_by.clone(),
                        having: None,
                        windows: windows.clone(),
                    },
                    compounds: normalized.body.compounds.clone(),
                },
                order_by: normalized.order_by.clone(),
                limit: normalized.limit.clone(),
            })
        {
            return Some(PreparedQueryFastPath::SimpleCountStarRowidRange {
                root_page: table.root_page,
                lower_parameter_index,
                upper_parameter_index,
            });
        }

        None
    }

    fn prepared_count_star_sum_fast_path(
        &self,
        columns: &[ResultColumn],
        table: &TableSchema,
        table_label: &str,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<PreparedQueryFastPath> {
        let [
            ResultColumn::Expr {
                expr: count_expr, ..
            },
            ResultColumn::Expr { expr: sum_expr, .. },
        ] = columns
        else {
            return None;
        };

        match count_expr {
            Expr::FunctionCall {
                name,
                args: FunctionArgs::Star,
                distinct: false,
                order_by,
                filter: None,
                over: None,
                ..
            } if name.eq_ignore_ascii_case("count") && order_by.is_empty() => {}
            _ => return None,
        }

        let sum_arg = match sum_expr {
            Expr::FunctionCall {
                name,
                args: FunctionArgs::List(arguments),
                distinct: false,
                order_by,
                filter: None,
                over: None,
                ..
            } if name.eq_ignore_ascii_case("sum")
                && order_by.is_empty()
                && arguments.len() == 1 =>
            {
                &arguments[0]
            }
            _ => return None,
        };

        let sum_column_index = select_table_column_index(table, table_label, sum_arg)?;
        self.remember_retained_autocommit_count_sum_interest(
            table.root_page,
            sum_column_index,
            rowid_alias_column_index,
        );
        Some(PreparedQueryFastPath::SimpleCountStarSum {
            root_page: table.root_page,
            sum_column_index,
            rowid_alias_column_index,
        })
    }

    fn prepared_limited_scalar_rowid_subquery_fast_path(
        &self,
        select: &SelectStatement,
        schema: &[TableSchema],
    ) -> Option<PreparedQueryFastPath> {
        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            windows,
            ..
        } = &select.body.select
        else {
            return None;
        };
        if !matches!(distinct, Distinctness::All)
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || !select.order_by.is_empty()
            || where_clause.is_some()
            || !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
            || !from.joins.is_empty()
        {
            return None;
        }
        let limit = select
            .limit
            .as_ref()
            .filter(|limit| limit.offset.is_none())
            .and_then(|limit| select_integer_literal(&limit.limit))
            .and_then(|limit| usize::try_from(limit).ok())
            .filter(|limit| *limit > 0)?;

        let [
            ResultColumn::Expr {
                expr: Expr::Column(outer_result_col, _),
                ..
            },
            ResultColumn::Expr {
                expr: Expr::Subquery(subquery, _),
                ..
            },
        ] = columns.as_slice()
        else {
            return None;
        };

        let TableOrSubquery::Table {
            name: outer_name,
            alias: outer_alias,
            index_hint: outer_index_hint,
            time_travel: outer_time_travel,
            ..
        } = &from.source
        else {
            return None;
        };
        if outer_name.schema.is_some() || outer_index_hint.is_some() || outer_time_travel.is_some()
        {
            return None;
        }
        let outer_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&outer_name.name))?;
        let outer_label = outer_alias.as_deref().unwrap_or(&outer_name.name);
        if outer_result_col
            .table
            .as_deref()
            .is_some_and(|table| !table.eq_ignore_ascii_case(outer_label))
        {
            return None;
        }
        let outer_column_index = outer_table.column_index(&outer_result_col.column)?;

        let rowid_alias_columns = self.rowid_alias_columns.borrow();
        let outer_rowid_alias_name = select_table_rowid_alias_name(
            outer_table,
            rowid_alias_columns
                .get(&outer_table.name.to_ascii_lowercase())
                .copied(),
        );

        let SelectCore::Select {
            distinct: inner_distinct,
            columns: inner_columns,
            from: Some(inner_from),
            where_clause: Some(inner_where),
            group_by: inner_group_by,
            having: inner_having,
            windows: inner_windows,
            ..
        } = &subquery.body.select
        else {
            return None;
        };
        if !matches!(inner_distinct, Distinctness::All)
            || subquery.with.is_some()
            || !subquery.body.compounds.is_empty()
            || !subquery.order_by.is_empty()
            || subquery.limit.is_some()
            || !inner_group_by.is_empty()
            || inner_having.is_some()
            || !inner_windows.is_empty()
            || !inner_from.joins.is_empty()
        {
            return None;
        }

        let [
            ResultColumn::Expr {
                expr: Expr::Column(inner_result_col, _),
                ..
            },
        ] = inner_columns.as_slice()
        else {
            return None;
        };

        let TableOrSubquery::Table {
            name: inner_name,
            alias: inner_alias,
            index_hint: inner_index_hint,
            time_travel: inner_time_travel,
            ..
        } = &inner_from.source
        else {
            return None;
        };
        if inner_name.schema.is_some() || inner_index_hint.is_some() || inner_time_travel.is_some()
        {
            return None;
        }
        let inner_table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&inner_name.name))?;
        let inner_label = inner_alias.as_deref().unwrap_or(&inner_name.name);
        if inner_result_col
            .table
            .as_deref()
            .is_some_and(|table| !table.eq_ignore_ascii_case(inner_label))
        {
            return None;
        }
        let inner_result_column_index = inner_table.column_index(&inner_result_col.column)?;
        let inner_rowid_alias_name = select_table_rowid_alias_name(
            inner_table,
            rowid_alias_columns
                .get(&inner_table.name.to_ascii_lowercase())
                .copied(),
        );

        let Expr::BinaryOp {
            left, op, right, ..
        } = inner_where.as_ref()
        else {
            return None;
        };
        if *op != BinaryOp::Eq {
            return None;
        }
        let outer_fk_col = match (left.as_ref(), right.as_ref()) {
            (Expr::Column(inner_col, _), Expr::Column(outer_col, _))
                if column_ref_matches_table_rowid(
                    inner_col,
                    inner_table,
                    inner_label,
                    inner_rowid_alias_name,
                ) && outer_col
                    .table
                    .as_deref()
                    .is_none_or(|table| table.eq_ignore_ascii_case(outer_label)) =>
            {
                outer_col
            }
            (Expr::Column(outer_col, _), Expr::Column(inner_col, _))
                if column_ref_matches_table_rowid(
                    inner_col,
                    inner_table,
                    inner_label,
                    inner_rowid_alias_name,
                ) && outer_col
                    .table
                    .as_deref()
                    .is_none_or(|table| table.eq_ignore_ascii_case(outer_label)) =>
            {
                outer_col
            }
            _ => return None,
        };
        if column_ref_matches_table_rowid(
            outer_fk_col,
            outer_table,
            outer_label,
            outer_rowid_alias_name,
        ) {
            return None;
        }
        let outer_fk_column_index = outer_table.column_index(&outer_fk_col.column)?;

        Some(PreparedQueryFastPath::SimpleLimitedScalarRowidSubquery {
            outer_root_page: outer_table.root_page,
            outer_column_index,
            outer_fk_column_index,
            inner_root_page: inner_table.root_page,
            inner_result_column_index,
            limit,
        })
    }

    #[allow(clippy::unused_self)]
    fn prepared_count_like_pattern_fast_path(
        &self,
        select: &SelectStatement,
        table: &TableSchema,
        table_label: &str,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<PreparedQueryFastPath> {
        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause: Some(where_clause),
            group_by,
            having,
            windows,
        } = &select.body.select
        else {
            return None;
        };
        if *distinct != Distinctness::All
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || !select.order_by.is_empty()
            || select.limit.is_some()
            || !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
            || !from.joins.is_empty()
        {
            return None;
        }

        let [
            ResultColumn::Expr {
                expr:
                    Expr::FunctionCall {
                        name,
                        args: FunctionArgs::Star,
                        distinct: false,
                        order_by,
                        filter: None,
                        over: None,
                        ..
                    },
                ..
            },
        ] = columns.as_slice()
        else {
            return None;
        };
        if !name.eq_ignore_ascii_case("count") || !order_by.is_empty() {
            return None;
        }

        let Expr::Like {
            expr,
            pattern,
            escape,
            op: LikeOp::Like,
            not: false,
            ..
        } = where_clause.as_ref()
        else {
            return None;
        };
        if escape.is_some() {
            return None;
        }

        let column_index = select_table_column_index(table, table_label, expr)?;
        let Expr::Literal(Literal::String(pattern_text), _) = pattern.as_ref() else {
            return None;
        };
        let (kind, literal) = classify_sql_like_fast_path(pattern_text, None)?;
        Some(PreparedQueryFastPath::SimpleCountLikePattern {
            root_page: table.root_page,
            column_index,
            rowid_alias_column_index,
            kind,
            literal: Arc::from(literal),
        })
    }

    #[allow(clippy::unused_self)]
    fn prepared_simple_string_projection_fast_path(
        &self,
        columns: &[ResultColumn],
        table: &TableSchema,
        table_label: &str,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<PreparedQueryFastPath> {
        let mut projections = Vec::with_capacity(columns.len());
        for column in columns {
            let ResultColumn::Expr { expr, .. } = column else {
                return None;
            };
            let Expr::FunctionCall {
                name,
                args: FunctionArgs::List(arg_list),
                distinct: false,
                order_by,
                filter: None,
                over: None,
                ..
            } = expr
            else {
                return None;
            };
            if !order_by.is_empty() {
                return None;
            }

            if name.eq_ignore_ascii_case("length") && arg_list.len() == 1 {
                projections.push(PreparedSimpleStringProjection::Length {
                    column_index: select_table_column_index(table, table_label, &arg_list[0])?,
                });
                continue;
            }
            if name.eq_ignore_ascii_case("upper") && arg_list.len() == 1 {
                projections.push(PreparedSimpleStringProjection::Upper {
                    column_index: select_table_column_index(table, table_label, &arg_list[0])?,
                });
                continue;
            }
            if (name.eq_ignore_ascii_case("substr") || name.eq_ignore_ascii_case("substring"))
                && (arg_list.len() == 2 || arg_list.len() == 3)
            {
                projections.push(PreparedSimpleStringProjection::Substr {
                    column_index: select_table_column_index(table, table_label, &arg_list[0])?,
                    start: select_integer_literal(&arg_list[1])?,
                    length: match arg_list.get(2) {
                        Some(length_expr) => Some(select_integer_literal(length_expr)?),
                        None => None,
                    },
                });
                continue;
            }
            return None;
        }

        (!projections.is_empty()).then_some(PreparedQueryFastPath::SimpleStringScalarProjection {
            root_page: table.root_page,
            rowid_alias_column_index,
            projections: Arc::from(projections),
        })
    }

    #[allow(clippy::unused_self)]
    fn prepared_simple_group_concat_fast_path(
        &self,
        select: &SelectStatement,
        table: &TableSchema,
        table_label: &str,
        rowid_alias_column_index: Option<usize>,
    ) -> Option<PreparedQueryFastPath> {
        let SelectCore::Select {
            distinct,
            columns,
            from: Some(from),
            where_clause,
            group_by,
            having,
            windows,
        } = &select.body.select
        else {
            return None;
        };
        if *distinct != Distinctness::All
            || select.with.is_some()
            || !select.body.compounds.is_empty()
            || !select.order_by.is_empty()
            || select.limit.is_some()
            || where_clause.is_some()
            || group_by.len() != 1
            || having.is_some()
            || !windows.is_empty()
            || !from.joins.is_empty()
        {
            return None;
        }

        let [
            ResultColumn::Expr {
                expr: group_expr, ..
            },
            ResultColumn::Expr {
                expr: aggregate_expr,
                ..
            },
        ] = columns.as_slice()
        else {
            return None;
        };
        let group_column_index = select_table_column_index(table, table_label, group_expr)?;
        let Expr::Column(group_by_col, _) = &group_by[0] else {
            return None;
        };
        if group_by_col
            .table
            .as_deref()
            .is_some_and(|candidate| !candidate.eq_ignore_ascii_case(table_label))
        {
            return None;
        }
        if !group_by_col
            .column
            .eq_ignore_ascii_case(&table.columns.get(group_column_index)?.name)
        {
            return None;
        }

        let Expr::FunctionCall {
            name,
            args: FunctionArgs::List(arg_list),
            distinct: false,
            order_by,
            filter: None,
            over: None,
            ..
        } = aggregate_expr
        else {
            return None;
        };
        if !(name.eq_ignore_ascii_case("group_concat") || name.eq_ignore_ascii_case("string_agg"))
            || !order_by.is_empty()
            || arg_list.len() != 2
        {
            return None;
        }

        let value_column_index = select_table_column_index(table, table_label, &arg_list[0])?;
        let Expr::Literal(Literal::String(separator), _) = &arg_list[1] else {
            return None;
        };
        Some(PreparedQueryFastPath::SimpleGroupConcatByColumn {
            root_page: table.root_page,
            group_column_index,
            value_column_index,
            rowid_alias_column_index,
            separator: Arc::from(separator.as_str()),
        })
    }

    fn prepared_statement_column_count(&self, statement: &Statement) -> usize {
        let Statement::Select(select) = statement else {
            return 0;
        };
        self.select_result_column_count(select, &[], &mut Vec::new())
    }

    fn validate_statement_compound_select_arity(&self, statement: &Statement) -> Result<()> {
        match statement {
            Statement::Select(select) => self.validate_compound_select_arity(select),
            Statement::Insert(insert) => {
                if let InsertSource::Select(select) = &insert.source {
                    self.validate_compound_select_arity(select)?;
                }
                Ok(())
            }
            Statement::CreateTable(create) => {
                if let CreateTableBody::AsSelect(select) = &create.body {
                    self.validate_compound_select_arity(select)?;
                }
                Ok(())
            }
            Statement::CreateView(create) => self.validate_compound_select_arity(&create.query),
            Statement::Explain { stmt, .. } => self.validate_statement_compound_select_arity(stmt),
            _ => Ok(()),
        }
    }

    fn validate_compound_select_arity(&self, select: &SelectStatement) -> Result<()> {
        if let Some(with) = &select.with {
            for cte in &with.ctes {
                self.validate_compound_select_arity(&cte.query)?;
            }
        }

        if select.body.compounds.is_empty() {
            return Ok(());
        }

        let expected = self.compound_select_core_column_count(select, &select.body.select);
        for (op, core) in &select.body.compounds {
            let actual = self.compound_select_core_column_count(select, core);
            if actual != expected {
                return Err(FrankenError::ParseError {
                    offset: 0,
                    detail: format!(
                        "SELECTs to the left and right of {} do not have the same number of result columns",
                        compound_op_error_name(*op)
                    ),
                });
            }
        }
        Ok(())
    }

    fn compound_select_core_column_count(
        &self,
        select: &SelectStatement,
        core: &SelectCore,
    ) -> usize {
        let single_core = SelectStatement {
            with: select.with.clone(),
            body: SelectBody {
                select: core.clone(),
                compounds: Vec::new(),
            },
            order_by: Vec::new(),
            limit: None,
        };
        self.select_result_column_count(&single_core, &[], &mut Vec::new())
    }

    fn prepared_statement_column_names(&self, statement: &Statement) -> Vec<String> {
        let Statement::Select(select) = statement else {
            return Vec::new();
        };
        self.select_result_column_names(select, &[], &mut Vec::new())
    }

    fn select_result_column_names(
        &self,
        select: &SelectStatement,
        outer_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> Vec<String> {
        let mut visible_ctes = outer_ctes.to_vec();
        if let Some(with) = &select.with {
            visible_ctes.extend(with.ctes.clone());
        }

        let SelectCore::Select { columns, from, .. } = &select.body.select else {
            return infer_select_column_names(select);
        };

        let mut resolved = Vec::with_capacity(columns.len());
        for (i, column) in columns.iter().enumerate() {
            match column {
                ResultColumn::Star => {
                    if let Some(from_clause) = from {
                        let expanded = self.from_clause_result_column_names(
                            from_clause,
                            &visible_ctes,
                            active_ctes,
                        );
                        if expanded.is_empty() {
                            resolved.push("*".to_owned());
                        } else {
                            resolved.extend(expanded);
                        }
                    } else {
                        resolved.push("*".to_owned());
                    }
                }
                ResultColumn::TableStar(name) => {
                    if let Some(from_clause) = from {
                        if let Some(expanded) = self.named_source_result_column_names(
                            from_clause,
                            name,
                            &visible_ctes,
                            active_ctes,
                        ) {
                            resolved.extend(expanded);
                        } else {
                            resolved.push(format!("{name}.*"));
                        }
                    } else {
                        resolved.push(format!("{name}.*"));
                    }
                }
                ResultColumn::Expr {
                    alias: Some(alias), ..
                } => resolved.push(alias.clone()),
                ResultColumn::Expr { expr, .. } => match expr {
                    Expr::Column(col_ref, _) => resolved.push(col_ref.column.to_string()),
                    _ => resolved.push(format!("_c{i}")),
                },
            }
        }

        resolved
    }

    /// bd-c9v0f + bd-pw68x: reject a top-level SELECT that SQLite would reject:
    /// an ORDER BY / GROUP BY integer ordinal outside `1..=ncol`, or an
    /// `INDEXED BY <name>` naming an index the table does not have. FrankenSQLite
    /// otherwise silently treats an out-of-range ordinal as a constant and
    /// ignores an unknown index hint.
    fn validate_select_ordinals_and_hints(&self, select: &SelectStatement) -> Result<()> {
        let ncol = self.select_result_column_count(select, &[], &mut Vec::new());
        let ncol_i = i64::try_from(ncol).unwrap_or(i64::MAX);
        // Only validate ordinals when the output column count is determinable;
        // ncol == 0 means it could not be resolved, so don't risk a false error.
        if ncol_i >= 1 {
            let check_ordinal = |kind: &str, expr: &Expr| -> Result<()> {
                // SQLite treats a (possibly signed) bare integer literal as a
                // column ordinal; `-1`/`0` are out of range. `1+1` etc. are
                // expressions, not ordinals, so are intentionally not matched.
                let ordinal = match expr {
                    Expr::Literal(Literal::Integer(n), _) => Some(*n),
                    Expr::UnaryOp {
                        op: fsqlite_ast::UnaryOp::Negate,
                        expr,
                        ..
                    } => match expr.as_ref() {
                        Expr::Literal(Literal::Integer(n), _) => Some(-*n),
                        _ => None,
                    },
                    Expr::UnaryOp {
                        op: fsqlite_ast::UnaryOp::Plus,
                        expr,
                        ..
                    } => match expr.as_ref() {
                        Expr::Literal(Literal::Integer(n), _) => Some(*n),
                        _ => None,
                    },
                    _ => None,
                };
                if let Some(n) = ordinal {
                    if n < 1 || n > ncol_i {
                        return Err(FrankenError::FunctionError(format!(
                            "{kind} term out of range - should be between 1 and {ncol_i}"
                        )));
                    }
                }
                Ok(())
            };
            for term in &select.order_by {
                check_ordinal("ORDER BY", &term.expr)?;
            }
            if let SelectCore::Select { group_by, .. } = &select.body.select {
                for expr in group_by {
                    check_ordinal("GROUP BY", expr)?;
                }
            }
        }
        // INDEXED BY <name> must reference an existing index on the named table.
        if let SelectCore::Select {
            from: Some(from), ..
        } = &select.body.select
        {
            let mut sources: Vec<&TableOrSubquery> = vec![&from.source];
            sources.extend(from.joins.iter().map(|j| &j.table));
            for tos in sources {
                if let TableOrSubquery::Table {
                    name,
                    index_hint: Some(fsqlite_ast::IndexHint::IndexedBy(idx)),
                    ..
                } = tos
                {
                    // Only validate against a known local table; an unknown table
                    // is reported by the normal execution path.
                    if let Some(ti) = self.schema_index_of(&name.name) {
                        let known = self.schema.borrow().get(ti).is_some_and(|t| {
                            t.indexes.iter().any(|i| i.name.eq_ignore_ascii_case(idx))
                        });
                        if !known {
                            return Err(FrankenError::FunctionError(format!(
                                "no such index: {idx}"
                            )));
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn select_result_column_count(
        &self,
        select: &SelectStatement,
        outer_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> usize {
        let mut visible_ctes = outer_ctes.to_vec();
        if let Some(with) = &select.with {
            visible_ctes.extend(with.ctes.clone());
        }

        match &select.body.select {
            SelectCore::Values(rows) => rows.first().map_or(0, Vec::len),
            SelectCore::Select { columns, from, .. } => columns
                .iter()
                .map(|column| match column {
                    ResultColumn::Expr { .. } => 1,
                    ResultColumn::Star => from.as_ref().map_or(1, |from_clause| {
                        self.from_clause_result_column_count(
                            from_clause,
                            &visible_ctes,
                            active_ctes,
                        )
                    }),
                    ResultColumn::TableStar(name) => from.as_ref().map_or(1, |from_clause| {
                        self.named_source_result_column_count(
                            from_clause,
                            name,
                            &visible_ctes,
                            active_ctes,
                        )
                    }),
                })
                .sum(),
        }
    }

    #[allow(clippy::wrong_self_convention)]
    fn from_clause_result_column_count(
        &self,
        from: &FromClause,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> usize {
        self.from_clause_result_column_names(from, visible_ctes, active_ctes)
            .len()
            .max(1)
    }

    #[allow(clippy::wrong_self_convention)]
    fn from_clause_result_column_names(
        &self,
        from: &FromClause,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> Vec<String> {
        let mut names =
            self.table_or_subquery_result_column_names(&from.source, visible_ctes, active_ctes);
        for join in &from.joins {
            let right_names =
                self.table_or_subquery_result_column_names(&join.table, visible_ctes, active_ctes);
            let using_cols = if join.join_type.natural {
                right_names
                    .iter()
                    .filter(|right_name| {
                        names
                            .iter()
                            .any(|left_name| left_name.eq_ignore_ascii_case(right_name))
                    })
                    .cloned()
                    .collect::<Vec<_>>()
            } else if let Some(JoinConstraint::Using(cols)) = join.constraint.as_ref() {
                cols.clone()
            } else {
                Vec::new()
            };
            names.extend(right_names.into_iter().filter(|right_name| {
                !using_cols
                    .iter()
                    .any(|using_col| using_col.eq_ignore_ascii_case(right_name))
            }));
        }
        names
    }

    fn named_source_result_column_count(
        &self,
        from: &FromClause,
        source_name: &QualifiedName,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> usize {
        self.named_source_result_column_names(from, source_name, visible_ctes, active_ctes)
            .map_or(1, |names| names.len().max(1))
    }

    fn named_source_result_column_names(
        &self,
        from: &FromClause,
        source_name: &QualifiedName,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> Option<Vec<String>> {
        std::iter::once(&from.source)
            .chain(from.joins.iter().map(|join| &join.table))
            .find(|source| source_matches_name(source, source_name))
            .map(|source| {
                self.table_or_subquery_result_column_names(source, visible_ctes, active_ctes)
            })
    }

    fn table_function_result_column_names(&self, name: &str) -> Option<Vec<String>> {
        if let Some(columns) = table_function_column_names(name) {
            return Some(columns.iter().map(|col| (*col).to_owned()).collect());
        }

        let module_key = name.to_ascii_uppercase();
        self.vtab_modules
            .borrow()
            .get(&module_key)
            .map(|factory| {
                factory
                    .column_info(&[])
                    .into_iter()
                    .map(|(column_name, _)| column_name)
                    .collect::<Vec<_>>()
            })
            .filter(|columns| !columns.is_empty())
    }

    fn table_or_subquery_result_column_names(
        &self,
        source: &TableOrSubquery,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> Vec<String> {
        match source {
            // `map_or_else` would build both closures at once and each wants
            // `&mut *active_ctes`, so use an explicit match on the schema
            // option to keep only one mutable borrow live at a time.
            TableOrSubquery::Table { name, .. } => match name.schema.as_deref() {
                None => {
                    self.named_relation_result_column_names(&name.name, visible_ctes, active_ctes)
                }
                Some(schema_name) if is_builtin_schema(schema_name) => {
                    self.named_relation_result_column_names(&name.name, visible_ctes, active_ctes)
                }
                Some(schema_name) => self
                    .with_attached_connection(schema_name, |attached| {
                        Ok(attached.named_relation_result_column_names(
                            &name.name,
                            visible_ctes,
                            active_ctes,
                        ))
                    })
                    .unwrap_or_else(|_| vec![name.name.clone()]),
            },
            TableOrSubquery::Subquery { query, .. } => {
                self.select_result_column_names(query, visible_ctes, active_ctes)
            }
            TableOrSubquery::TableFunction { name, .. } => self
                .table_function_result_column_names(name)
                .unwrap_or_else(|| vec![name.clone()]),
            TableOrSubquery::ParenJoin(from) => {
                self.from_clause_result_column_names(from, visible_ctes, active_ctes)
            }
        }
    }

    fn expand_table_star_result_columns_from_col_map(
        &self,
        sources: &[&TableOrSubquery],
        col_map: &[(String, String, bool)],
        qualifier: &QualifiedName,
    ) -> Vec<ResultColumn> {
        let matching_labels: Vec<String> = sources
            .iter()
            .filter(|source| source_matches_name(source, qualifier))
            .filter_map(|source| source_projection_label(source))
            .collect();
        if matching_labels.is_empty() {
            return Vec::new();
        }

        col_map
            .iter()
            .filter(|(table, _, hidden)| {
                !*hidden
                    && matching_labels
                        .iter()
                        .any(|label| label.eq_ignore_ascii_case(table))
            })
            .map(|(table, column, _)| ResultColumn::Expr {
                expr: Expr::Column(
                    ColumnRef::qualified(table.clone(), column.clone()),
                    Span::new(0, 0),
                ),
                alias: None,
            })
            .collect()
    }

    fn named_relation_result_column_names(
        &self,
        relation_name: &str,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> Vec<String> {
        if let Some(cte) = visible_ctes
            .iter()
            .rev()
            .find(|cte| cte.name.eq_ignore_ascii_case(relation_name))
        {
            return self.cte_result_column_names(cte, visible_ctes, active_ctes);
        }

        if let Some(i) = self.schema_index_of(relation_name) {
            let schema = self.schema.borrow();
            if let Some(table) = schema.get(i) {
                return table
                    .columns
                    .iter()
                    .map(|column| column.name.clone())
                    .collect();
            }
        }

        let view_idx = self
            .views_by_name
            .borrow()
            .get(&relation_name.to_ascii_lowercase())
            .copied();
        if let Some(i) = view_idx {
            let views = self.views.borrow();
            if let Some(view) = views.get(i) {
                let query = view.query.clone();
                drop(views);
                return self.select_result_column_names(&query, visible_ctes, active_ctes);
            }
        }

        vec![relation_name.to_owned()]
    }

    fn cte_result_column_names(
        &self,
        cte: &fsqlite_ast::Cte,
        visible_ctes: &[fsqlite_ast::Cte],
        active_ctes: &mut Vec<String>,
    ) -> Vec<String> {
        if !cte.columns.is_empty() {
            return cte.columns.clone();
        }
        if active_ctes
            .iter()
            .any(|active_name| active_name.eq_ignore_ascii_case(&cte.name))
        {
            let inferred = infer_select_column_names(&cte.query);
            if inferred.is_empty() {
                return vec!["_c0".to_owned()];
            }
            return inferred;
        }

        active_ctes.push(cte.name.clone());
        let column_names = self.select_result_column_names(&cte.query, visible_ctes, active_ctes);
        active_ctes.pop();
        if column_names.is_empty() {
            vec!["_c0".to_owned()]
        } else {
            column_names
        }
    }

    /// Count the number of rows in `table_name` matching an optional WHERE
    /// clause.  Used by UPDATE/DELETE to compute the affected-row count
    /// without modifying the VDBE engine.
    fn select_matching_rows(
        &self,
        table_ref: &fsqlite_ast::QualifiedTableRef,
        where_clause: Option<&Expr>,
        order_by: &[fsqlite_ast::OrderingTerm],
        limit: Option<&fsqlite_ast::LimitClause>,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Row>> {
        let select = Self::build_single_table_select(
            table_ref,
            vec![ResultColumn::Star],
            where_clause,
            order_by,
            limit,
        );
        self.execute_statement(&Statement::Select(select), params)
    }

    /// Freeze stable row locators for a multi-row UPDATE before its first
    /// trigger or mutation runs. Rowid tables use the first unshadowed hidden
    /// rowid alias (falling back to an INTEGER PRIMARY KEY alias); WITHOUT
    /// ROWID tables use the complete declared composite primary key.
    ///
    /// `None` means the table has no unambiguous locator expressible through
    /// the SQL surface, in which case callers retain the ordinary VDBE path
    /// instead of risking duplicate or skipped updates.
    fn materialize_update_replay_locators(
        &self,
        update: &fsqlite_ast::UpdateStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<UpdateReplayLocatorSet>> {
        let table_name = &update.table.name.name;
        let schema = self.schema.borrow();
        let table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(table_name))
            .ok_or_else(|| FrankenError::NoSuchTable {
                name: table_name.clone(),
            })?;

        let locator_columns = if table.without_rowid {
            let primary_key = table.primary_key_constraints.first().ok_or_else(|| {
                FrankenError::NotImplemented(format!(
                    "WITHOUT ROWID table {} has no PRIMARY KEY",
                    table.name
                ))
            })?;
            if primary_key.is_empty() {
                return Err(FrankenError::NotImplemented(format!(
                    "WITHOUT ROWID table {} has an empty PRIMARY KEY",
                    table.name
                )));
            }
            for column in primary_key {
                if table.column_index(column).is_none() {
                    return Err(FrankenError::Internal(format!(
                        "no such column: {column} in table {}",
                        table.name
                    )));
                }
            }
            primary_key.clone()
        } else {
            let shadowed = table
                .columns
                .iter()
                .map(|column| column.name.to_ascii_lowercase())
                .collect::<HashSet<_>>();
            if let Some(hidden_rowid) = ["rowid", "_rowid_", "oid"]
                .into_iter()
                .find(|candidate| !shadowed.contains(*candidate))
            {
                vec![hidden_rowid.to_owned()]
            } else if let Some(ipk_column) = table.columns.iter().find(|column| column.is_ipk) {
                vec![ipk_column.name.clone()]
            } else {
                return Ok(None);
            }
        };
        drop(schema);

        if locator_columns.is_empty() {
            return Ok(None);
        }
        let projections = locator_columns
            .iter()
            .map(|column| ResultColumn::Expr {
                expr: Self::build_limit_scope_projection_expr(&update.table, column),
                alias: None,
            })
            .collect();
        let select = Self::build_single_table_select(
            &update.table,
            projections,
            update.where_clause.as_ref(),
            &[],
            None,
        );
        let locator_rows = self
            .execute_statement(&Statement::Select(select), params)?
            .into_iter()
            .map(|row| row.values().to_vec())
            .collect();
        Ok(Some((locator_columns, locator_rows)))
    }

    fn build_update_replay_locator_filter(
        table_ref: &fsqlite_ast::QualifiedTableRef,
        locator_columns: &[String],
        locator_values: &[SqliteValue],
    ) -> Result<Expr> {
        if locator_columns.len() != locator_values.len() || locator_columns.is_empty() {
            return Err(FrankenError::Internal(format!(
                "UPDATE row replay locator arity mismatch: columns={}, values={}",
                locator_columns.len(),
                locator_values.len()
            )));
        }

        let mut predicates = locator_columns
            .iter()
            .zip(locator_values)
            .map(|(column, value)| Expr::BinaryOp {
                left: Box::new(Self::build_limit_scope_projection_expr(table_ref, column)),
                op: BinaryOp::Eq,
                right: Box::new(value_to_literal_expr(value.clone())),
                span: Span::ZERO,
            });
        let first = predicates.next().ok_or_else(|| {
            FrankenError::Internal("UPDATE row replay locator cannot be empty".to_owned())
        })?;
        Ok(predicates.fold(first, |left, right| Expr::BinaryOp {
            left: Box::new(left),
            op: BinaryOp::And,
            right: Box::new(right),
            span: Span::ZERO,
        }))
    }

    fn execute_update_row_by_row(
        &self,
        update: &fsqlite_ast::UpdateStatement,
        params: Option<&[SqliteValue]>,
        locator_columns: &[String],
        locator_rows: &[Vec<SqliteValue>],
    ) -> Result<Vec<Row>> {
        let preserve_prior_changes_on_constraint_violation =
            update.or_conflict == Some(fsqlite_ast::ConflictAction::Fail);
        let completed_statement_changes = Cell::new(0usize);

        let result = self.with_statement_fk_validation_scope(
            preserve_prior_changes_on_constraint_violation,
            || {
                let mut statement_changes = 0usize;
                let mut returning_rows = Vec::new();
                for (row_index, locator_values) in locator_rows.iter().enumerate() {
                    let mut row_update = update.clone();
                    row_update.where_clause = Some(Self::build_update_replay_locator_filter(
                        &row_update.table,
                        locator_columns,
                        locator_values,
                    )?);
                    row_update.order_by.clear();
                    row_update.limit = None;

                    match self.execute_statement_impl_after_background_status(
                        &Statement::Update(row_update),
                        params,
                        None,
                    ) {
                        Ok(rows) => {
                            statement_changes =
                                statement_changes.saturating_add(self.last_changes.get());
                            completed_statement_changes.set(statement_changes);
                            returning_rows.extend(rows);
                        }
                        Err(error) => {
                            if error_preserves_prior_statement_rows(
                                preserve_prior_changes_on_constraint_violation,
                                &error,
                            ) {
                                self.set_statement_change_count(statement_changes);
                                self.record_table_program_error_state_with_total_changes(
                                    statement_changes,
                                    (statement_changes > 0)
                                        .then(|| self.current_last_insert_rowid()),
                                    Some(self.total_changes.get()),
                                );
                            } else {
                                self.set_statement_change_count(0);
                                self.record_table_program_error_state_with_total_changes(
                                    0,
                                    (statement_changes > 0)
                                        .then(|| self.current_last_insert_rowid()),
                                    Some(
                                        self.total_changes.get().saturating_sub(statement_changes),
                                    ),
                                );
                            }
                            tracing::debug!(
                                target: "fsqlite.statement",
                                table = %update.table.name.name,
                                row_index,
                                locator_columns = ?locator_columns,
                                locator_values = ?locator_values,
                                error = %error,
                                "row-replayed UPDATE failed"
                            );
                            return Err(error);
                        }
                    }
                }
                self.set_statement_change_count(statement_changes);
                Ok(returning_rows)
            },
        );
        if result.is_err() && self.last_table_program_error_state.borrow().is_none() {
            let statement_changes = completed_statement_changes.get();
            self.record_table_program_error_state_with_total_changes(
                0,
                (statement_changes > 0).then(|| self.current_last_insert_rowid()),
                Some(self.total_changes.get().saturating_sub(statement_changes)),
            );
        }
        result
    }

    /// Pre-evaluate and inline scalar subqueries in `expr` that reference
    /// `target_table`. Replaces each matching `Expr::Subquery(...)` with a
    /// literal of the evaluated result. This ensures the subquery runs against
    /// the table's pre-DML state, not the partially-modified state during a
    /// DELETE or UPDATE scan.
    fn inline_self_referencing_scalar_subqueries(
        &self,
        expr: &mut Expr,
        target_table: &str,
    ) -> Result<()> {
        match expr {
            Expr::Subquery(subquery, _)
                if !is_correlated_subquery(subquery)
                    && subquery_references_table(subquery, target_table) =>
            {
                let rows =
                    self.execute_statement(&Statement::Select(subquery.as_ref().clone()), None)?;
                let value = rows
                    .first()
                    .and_then(|r| r.values().first().cloned())
                    .unwrap_or(SqliteValue::Null);
                *expr = match value {
                    SqliteValue::Null => Expr::Literal(Literal::Null, fsqlite_ast::Span::ZERO),
                    SqliteValue::Integer(n) => {
                        Expr::Literal(Literal::Integer(n), fsqlite_ast::Span::ZERO)
                    }
                    SqliteValue::Float(f) => {
                        Expr::Literal(Literal::Float(f), fsqlite_ast::Span::ZERO)
                    }
                    SqliteValue::Text(s) => {
                        Expr::Literal(Literal::String(s.to_string()), fsqlite_ast::Span::ZERO)
                    }
                    SqliteValue::Blob(b) => {
                        Expr::Literal(Literal::Blob(b.to_vec()), fsqlite_ast::Span::ZERO)
                    }
                };
                Ok(())
            }
            Expr::BinaryOp { left, right, .. } => {
                self.inline_self_referencing_scalar_subqueries(left, target_table)?;
                self.inline_self_referencing_scalar_subqueries(right, target_table)
            }
            Expr::UnaryOp { expr: inner, .. }
            | Expr::IsNull { expr: inner, .. }
            | Expr::Cast { expr: inner, .. }
            | Expr::Collate { expr: inner, .. } => {
                self.inline_self_referencing_scalar_subqueries(inner, target_table)
            }
            Expr::FunctionCall {
                args: FunctionArgs::List(args),
                ..
            } => {
                for arg in args.iter_mut() {
                    self.inline_self_referencing_scalar_subqueries(arg, target_table)?;
                }
                Ok(())
            }
            _ => Ok(()),
        }
    }

    /// Count rows matching UPDATE/DELETE scope using the existing SELECT
    /// helper so affected-row accounting is decoupled from VDBE opcode shape.
    #[allow(dead_code)]
    fn count_matching_rows(
        &self,
        table_ref: &fsqlite_ast::QualifiedTableRef,
        where_clause: Option<&Expr>,
        order_by: &[fsqlite_ast::OrderingTerm],
        limit: Option<&fsqlite_ast::LimitClause>,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        self.select_matching_rows(table_ref, where_clause, order_by, limit, params)
            .map(|rows| rows.len())
    }

    /// Materialize the target row-set for `UPDATE ... ORDER BY/LIMIT` into a
    /// deterministic key-filter expression so VDBE execution mutates only the
    /// selected rows.
    fn materialize_update_limit_scope(
        &self,
        update: &fsqlite_ast::UpdateStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<(fsqlite_ast::UpdateStatement, Option<usize>)> {
        if update.order_by.is_empty() && update.limit.is_none() {
            return Ok((update.clone(), None));
        }
        if update.from.is_some() {
            return Err(FrankenError::NotImplemented(
                "UPDATE ... FROM with ORDER BY/LIMIT is not yet supported".to_owned(),
            ));
        }

        let (key_column, _is_hidden_rowid) = self.resolve_dml_limit_key(&update.table.name.name)?;
        let selected_keys = self.select_matching_limit_keys(
            &update.table,
            update.where_clause.as_ref(),
            &update.order_by,
            update.limit.as_ref(),
            params,
            &key_column,
        )?;

        let mut effective = update.clone();
        effective.where_clause = Some(Self::build_limit_scope_filter_expr(
            &effective.table,
            &key_column,
            &selected_keys,
        ));
        effective.order_by.clear();
        effective.limit = None;
        Ok((effective, Some(selected_keys.len())))
    }

    /// Materialize the target row-set for `DELETE ... ORDER BY/LIMIT` into a
    /// deterministic key-filter expression so VDBE execution deletes only the
    /// selected rows.
    fn materialize_delete_limit_scope(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<(fsqlite_ast::DeleteStatement, Option<usize>)> {
        if delete.order_by.is_empty() && delete.limit.is_none() {
            return Ok((delete.clone(), None));
        }

        let (key_column, _is_hidden_rowid) = self.resolve_dml_limit_key(&delete.table.name.name)?;
        let selected_keys = self.select_matching_limit_keys(
            &delete.table,
            delete.where_clause.as_ref(),
            &delete.order_by,
            delete.limit.as_ref(),
            params,
            &key_column,
        )?;

        let mut effective = delete.clone();
        effective.where_clause = Some(Self::build_limit_scope_filter_expr(
            &effective.table,
            &key_column,
            &selected_keys,
        ));
        effective.order_by.clear();
        effective.limit = None;
        Ok((effective, Some(selected_keys.len())))
    }

    /// Resolve a stable key column for DML LIMIT scoping.
    ///
    /// Prefers hidden rowid aliases when available; otherwise falls back to the
    /// INTEGER PRIMARY KEY column when all rowid aliases are shadowed.
    fn resolve_dml_limit_key(&self, table_name: &str) -> Result<(String, bool)> {
        let idx = self
            .schema_index_of(table_name)
            .ok_or_else(|| FrankenError::NoSuchTable {
                name: table_name.to_owned(),
            })?;
        let schema = self.schema.borrow();
        let table = schema.get(idx).ok_or_else(|| FrankenError::NoSuchTable {
            name: table_name.to_owned(),
        })?;

        let shadowed: HashSet<String> = table
            .columns
            .iter()
            .map(|column| column.name.to_ascii_lowercase())
            .collect();

        for candidate in ["rowid", "_rowid_", "oid"] {
            if !shadowed.contains(candidate) {
                return Ok((candidate.to_owned(), true));
            }
        }

        if let Some(ipk_column) = table.columns.iter().find(|column| column.is_ipk) {
            return Ok((ipk_column.name.clone(), false));
        }

        Err(FrankenError::NotImplemented(format!(
            "ORDER BY/LIMIT for UPDATE/DELETE requires rowid or INTEGER PRIMARY KEY on table `{table_name}`"
        )))
    }

    /// Select key values for UPDATE/DELETE LIMIT scoping using the statement's
    /// original WHERE/ORDER BY/LIMIT clauses.
    #[allow(clippy::too_many_arguments)]
    fn select_matching_limit_keys(
        &self,
        table_ref: &fsqlite_ast::QualifiedTableRef,
        where_clause: Option<&Expr>,
        order_by: &[fsqlite_ast::OrderingTerm],
        limit: Option<&fsqlite_ast::LimitClause>,
        params: Option<&[SqliteValue]>,
        key_column: &str,
    ) -> Result<Vec<i64>> {
        let select = Self::build_single_table_select(
            table_ref,
            vec![ResultColumn::Expr {
                expr: Self::build_limit_scope_projection_expr(table_ref, key_column),
                alias: None,
            }],
            where_clause,
            order_by,
            limit,
        );
        let rows = self.execute_statement(&Statement::Select(select), params)?;

        rows.iter()
            .map(|row| {
                let key_value = row.values().first().ok_or_else(|| {
                    FrankenError::Internal(
                        "DML LIMIT key materialization returned an empty row".to_owned(),
                    )
                })?;
                Self::decode_limit_scope_key(key_value, key_column)
            })
            .collect()
    }

    fn build_single_table_select(
        table_ref: &fsqlite_ast::QualifiedTableRef,
        columns: Vec<ResultColumn>,
        where_clause: Option<&Expr>,
        order_by: &[OrderingTerm],
        limit: Option<&LimitClause>,
    ) -> SelectStatement {
        SelectStatement {
            with: None,
            body: SelectBody {
                select: SelectCore::Select {
                    distinct: Distinctness::All,
                    columns,
                    from: Some(FromClause {
                        source: TableOrSubquery::Table {
                            name: table_ref.name.clone(),
                            alias: table_ref.alias.clone(),
                            index_hint: table_ref.index_hint.clone(),
                            time_travel: table_ref.time_travel.clone(),
                        },
                        joins: Vec::new(),
                    }),
                    where_clause: where_clause.cloned().map(Box::new),
                    group_by: Vec::new(),
                    having: None,
                    windows: Vec::new(),
                },
                compounds: Vec::new(),
            },
            order_by: order_by.to_vec(),
            limit: limit.cloned(),
        }
    }

    fn build_limit_scope_projection_expr(
        table_ref: &fsqlite_ast::QualifiedTableRef,
        key_column: &str,
    ) -> Expr {
        Expr::Column(
            ColumnRef {
                table: table_ref.alias.clone().map(Into::into),
                column: key_column.into(),
            },
            Span::ZERO,
        )
    }

    fn build_limit_scope_filter_expr(
        table_ref: &fsqlite_ast::QualifiedTableRef,
        key_column: &str,
        selected_keys: &[i64],
    ) -> Expr {
        if selected_keys.is_empty() {
            return Expr::Literal(Literal::Integer(0), Span::ZERO);
        }

        let key_ref = Expr::Column(
            ColumnRef {
                table: table_ref.alias.clone().map(Into::into),
                column: key_column.into(),
            },
            Span::ZERO,
        );
        let list = selected_keys
            .iter()
            .map(|value| Expr::Literal(Literal::Integer(*value), Span::ZERO))
            .collect();

        Expr::In {
            expr: Box::new(key_ref),
            set: InSet::List(list),
            not: false,
            span: Span::ZERO,
        }
    }

    fn decode_limit_scope_key(value: &SqliteValue, key_column: &str) -> Result<i64> {
        match value {
            SqliteValue::Integer(n) => Ok(*n),
            SqliteValue::Float(f) => {
                if f.is_finite()
                    && f.fract() == 0.0
                    && *f >= i64::MIN as f64
                    && *f <= i64::MAX as f64
                {
                    Ok(*f as i64)
                } else {
                    Err(FrankenError::Internal(format!(
                        "non-integral key value `{f}` materialized for `{key_column}`"
                    )))
                }
            }
            SqliteValue::Text(text) => text.parse::<i64>().map_err(|err| {
                FrankenError::Internal(format!(
                    "failed to parse key `{text}` for `{key_column}` as INTEGER: {err}"
                ))
            }),
            other => Err(FrankenError::Internal(format!(
                "unsupported key type `{other:?}` materialized for `{key_column}`"
            ))),
        }
    }

    fn collect_insert_trigger_rows(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Vec<SqliteValue>>> {
        let layout = self.resolve_insert_target_layout(insert)?;
        let default_sqls = self.collect_insert_default_sqls(&insert.table.name)?;
        let table_column_count = layout.table_columns.len();
        if default_sqls.len() != table_column_count {
            return Err(FrankenError::Internal(format!(
                "INSERT trigger snapshot: default row width {} does not match table width {table_column_count}",
                default_sqls.len()
            )));
        }
        match &insert.source {
            fsqlite_ast::InsertSource::Values(rows) => {
                // The FK/trigger enforcement path can reach here with a freshly
                // re-parsed, NON-canonicalized insert: the cold FK path re-parses
                // stmt.sql (the original text), which may carry anonymous `?` or
                // named `:x`/`@x`/`$x` placeholders. evaluate_insert_source_row
                // evaluates these directly and requires canonical Numbered
                // placeholders, so a non-canonical placeholder tripped the
                // internal invariant "expected canonicalized numbered placeholder".
                // Canonicalize the VALUES placeholders once across all rows with a
                // shared bind_state (statement-level positions matching the bound
                // params); idempotent for already-Numbered placeholders.
                let mut bind_state = BindParamState::default();
                rows.iter()
                    .enumerate()
                    .map(|(row_idx, row_exprs)| {
                        let mut canonical_exprs = row_exprs.clone();
                        for expr in &mut canonical_exprs {
                            canonicalize_expr_placeholders(expr, &mut bind_state)?;
                        }
                        let source_values =
                            self.evaluate_insert_source_row(&canonical_exprs, params)?;
                        let default_row = self.evaluate_default_row_from_sqls(&default_sqls)?;
                        self.map_insert_source_row_to_table_row(
                            &default_row,
                            &layout.targets,
                            layout.rowid_alias_col_idx,
                            layout.explicit_rowid_source,
                            &source_values,
                            &format!("INSERT VALUES row {}", row_idx + 1),
                        )
                    })
                    .collect()
            }
            fsqlite_ast::InsertSource::Select(select) => {
                let source_rows =
                    self.execute_statement(&Statement::Select(*select.clone()), params)?;
                source_rows
                    .iter()
                    .enumerate()
                    .map(|(row_idx, row)| {
                        let default_row = self.evaluate_default_row_from_sqls(&default_sqls)?;
                        self.map_insert_source_row_to_table_row(
                            &default_row,
                            &layout.targets,
                            layout.rowid_alias_col_idx,
                            layout.explicit_rowid_source,
                            row.values(),
                            &format!("INSERT SELECT row {}", row_idx + 1),
                        )
                    })
                    .collect()
            }
            fsqlite_ast::InsertSource::DefaultValues => {
                Ok(vec![self.evaluate_default_row_from_sqls(&default_sqls)?])
            }
        }
    }

    fn evaluate_insert_source_row(
        &self,
        row_exprs: &[Expr],
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<SqliteValue>> {
        // GH#116: evaluate the VALUES row expressions directly rather than
        // materializing them through a nested `SELECT <projection>` prepared
        // read. The prepared-read boundary unconditionally runs
        // `refresh_memdb_from_active_txn_if_dirty` (a full O(rows-so-far) memdb
        // reload + unique-index rebuild). On an FK-enforced INSERT loop this
        // function is called once per inserted row, so the reload turned the
        // whole loop into O(N^2) for tables with a secondary (e.g. composite
        // UNIQUE) index. VALUES rows reference no columns, so an empty
        // row/col_map is sufficient; `eval_expr_with_subqueries` evaluates
        // literals, bound parameters, scalar functions, and subqueries
        // identically to the projection SELECT, but without the reload.
        let empty_row: &[SqliteValue] = &[];
        let empty_col_map: &[(String, String, bool)] = &[];
        row_exprs
            .iter()
            .map(|expr| self.eval_expr_with_subqueries(expr, empty_row, empty_col_map, params))
            .collect()
    }

    fn resolve_live_vtab_insert_layout(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> Result<LiveVtabInsertLayout> {
        let idx = self.schema_index_of(&insert.table.name).ok_or_else(|| {
            FrankenError::Internal(format!("table not found: {}", insert.table.name))
        })?;
        let schema = self.schema.borrow();
        let table = schema
            .get(idx)
            .ok_or_else(|| {
                FrankenError::Internal(format!("table not found: {}", insert.table.name))
            })?
            .clone();
        drop(schema);

        let table_columns: Vec<String> = table.columns.iter().map(|col| col.name.clone()).collect();
        let default_sqls = self.collect_insert_default_sqls(&insert.table.name)?;
        if default_sqls.len() != table_columns.len() {
            return Err(FrankenError::Internal(format!(
                "live virtual-table INSERT default row width {} does not match table width {}",
                default_sqls.len(),
                table_columns.len()
            )));
        }

        let source_targets = if insert.columns.is_empty() {
            (0..table_columns.len()).map(Some).collect::<Vec<_>>()
        } else {
            let mut targets = Vec::with_capacity(insert.columns.len());
            for column in &insert.columns {
                if let Some(idx) = table.column_index(column) {
                    targets.push(Some(idx));
                    continue;
                }
                if is_rowid_alias(column) {
                    targets.push(None);
                    continue;
                }
                return Err(FrankenError::Internal(format!(
                    "column '{column}' not found in table '{}'",
                    insert.table.name
                )));
            }
            targets
        };

        let direct_projection =
            Self::try_build_live_vtab_direct_projection(table_columns.len(), &source_targets);

        Ok(LiveVtabInsertLayout {
            default_sqls,
            source_targets,
            direct_projection,
        })
    }

    fn try_build_live_vtab_direct_projection(
        table_width: usize,
        source_targets: &[Option<usize>],
    ) -> Option<DirectLiveVtabInsertProjection> {
        let mut explicit_rowid_source = None;
        let mut value_sources = vec![None; table_width];

        for (source_idx, target_idx) in source_targets.iter().copied().enumerate() {
            if let Some(target_idx) = target_idx {
                let source_slot = value_sources.get_mut(target_idx)?;
                if source_slot.is_some() {
                    return None;
                }
                *source_slot = Some(source_idx);
            } else if explicit_rowid_source.replace(source_idx).is_some() {
                return None;
            }
        }

        Some(DirectLiveVtabInsertProjection {
            explicit_rowid_source,
            value_sources: value_sources.into_iter().collect::<Option<Vec<_>>>()?,
        })
    }

    fn build_live_vtab_insert_row(
        &self,
        layout: &LiveVtabInsertLayout,
        source_values: &[SqliteValue],
        context: &str,
    ) -> Result<LiveVtabInsertRow> {
        if source_values.len() != layout.source_targets.len() {
            return Err(FrankenError::Internal(format!(
                "{context}: column count mismatch (source has {}, target expects {})",
                source_values.len(),
                layout.source_targets.len()
            )));
        }

        if let Some(direct_projection) = &layout.direct_projection {
            return Ok(LiveVtabInsertRow {
                explicit_rowid: direct_projection
                    .explicit_rowid_source
                    .map(|source_idx| source_values[source_idx].clone()),
                values: direct_projection
                    .value_sources
                    .iter()
                    .map(|&source_idx| source_values[source_idx].clone())
                    .collect(),
            });
        }

        let mut row = self.evaluate_default_row_from_sqls(&layout.default_sqls)?;
        let mut explicit_rowid = None;
        let mut filled_columns = vec![false; row.len()];
        for (source_idx, target_idx) in layout.source_targets.iter().copied().enumerate() {
            if let Some(target_idx) = target_idx {
                if filled_columns[target_idx] {
                    continue;
                }
                row[target_idx] = source_values[source_idx].clone();
                filled_columns[target_idx] = true;
            } else {
                explicit_rowid = Some(source_values[source_idx].clone());
            }
        }

        Ok(LiveVtabInsertRow {
            explicit_rowid,
            values: row,
        })
    }

    fn collect_live_vtab_insert_rows(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<LiveVtabInsertRow>> {
        let layout = self.resolve_live_vtab_insert_layout(insert)?;

        match &insert.source {
            fsqlite_ast::InsertSource::Values(rows) => rows
                .iter()
                .enumerate()
                .map(|(row_idx, row_exprs)| {
                    let source_values = self.evaluate_insert_source_row(row_exprs, params)?;
                    self.build_live_vtab_insert_row(
                        &layout,
                        &source_values,
                        &format!("live virtual-table INSERT VALUES row {}", row_idx + 1),
                    )
                })
                .collect(),
            fsqlite_ast::InsertSource::Select(select) => {
                let source_rows =
                    self.execute_statement(&Statement::Select(*select.clone()), params)?;
                source_rows
                    .iter()
                    .enumerate()
                    .map(|(row_idx, row)| {
                        self.build_live_vtab_insert_row(
                            &layout,
                            row.values(),
                            &format!("live virtual-table INSERT SELECT row {}", row_idx + 1),
                        )
                    })
                    .collect()
            }
            fsqlite_ast::InsertSource::DefaultValues => Ok(vec![self.build_live_vtab_insert_row(
                &layout,
                &[],
                "live virtual-table INSERT DEFAULT VALUES",
            )?]),
        }
    }

    fn try_execute_streaming_live_vtab_insert_select(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<usize>> {
        let InsertSource::Select(select_stmt) = &insert.source else {
            return Ok(None);
        };
        if insert.with.is_some() {
            return Ok(None);
        }
        let prep_cx = self.op_cx_after_background_status();
        self.prepare_streaming_join_select_read_boundary(select_stmt, &prep_cx)?;
        let prepared = self.prepare_simple_join_select_rows_with_scanner(
            select_stmt,
            params,
            |source| {
                if let Some(row_data) = self.try_scan_join_source_from_memdb(source) {
                    return Ok(Some(row_data));
                }
                if let Some(result) = self.try_scan_join_source_from_pager(source) {
                    return Ok(Some(result?));
                }
                let scan_sql = build_join_scan_sql(source);
                let rows = self.query(&scan_sql)?;
                Ok(Some(rows_into_value_vectors(rows)))
            },
            |table_name| self.has_live_vtab_instance(table_name),
        )?;
        let Some(prepared) = prepared else {
            return Ok(None);
        };
        let layout = self.resolve_live_vtab_insert_layout(insert)?;
        let table_name = insert.table.name.as_str();
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        #[cfg(feature = "ext-fts5")]
        if root_page == 0 && self.is_live_fts5_instance(table_name) {
            return Ok(None);
        }
        let root = page_number_from_schema_root(root_page, table_name, "table")?;
        let key = table_name.to_ascii_uppercase();
        let mut inserted_row_count = 0usize;
        let mut source_row_count = 0usize;
        let streamed = self.with_pager_write_txn(|cx, txn| {
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
            let mut instances = self.vtab_instances.borrow_mut();
            let instance = instances.get_mut(&key).ok_or_else(|| {
                FrankenError::Internal(format!("virtual table not found: {table_name}"))
            })?;
            self.begin_live_vtab_transaction_if_needed(table_name, instance.as_mut(), cx)?;
            #[cfg(feature = "ext-fts5")]
            if let Some(fts5) = instance.as_any_mut().downcast_mut::<Fts5Table>()
                && fts5.is_empty()
                && !cursor.first(cx)?
            {
                fts5.ensure_shadow_rows_materializable_for_mutation()?;
                let tokenizer = fts5.create_tokenizer_instance();
                let mut seen_rowids = HashSet::new();
                if let Some(direct_projection) = layout.direct_projection.as_ref() {
                    let explicit_rowid_projection = direct_projection
                        .explicit_rowid_source
                        .map(|source_idx| prepared.projection_indices[source_idx]);
                    let value_projection_indices = direct_projection
                        .value_sources
                        .iter()
                        .map(|&source_idx| prepared.projection_indices[source_idx])
                        .collect::<Vec<_>>();
                    self.emit_prepared_simple_join_rows_raw(&prepared, |joined_row| {
                        source_row_count = source_row_count.saturating_add(1);
                        let rowid = explicit_rowid_projection
                            .and_then(|projection_idx| joined_row.get(projection_idx))
                            .map(Self::coerce_insert_rowid_value)
                            .transpose()?
                            .flatten()
                            .unwrap_or_else(|| fts5.allocate_rowid());
                        if !seen_rowids.insert(rowid) {
                            fts5.delete_document(rowid);
                            if cursor.table_move_to(cx, rowid)?.is_found() {
                                cursor.delete(cx)?;
                            }
                        }
                        let persisted_values = value_projection_indices
                            .iter()
                            .map(|&projection_idx| {
                                joined_row
                                    .get(projection_idx)
                                    .cloned()
                                    .unwrap_or(SqliteValue::Null)
                            })
                            .collect::<Vec<_>>();
                        let column_values = persisted_values
                            .iter()
                            .map(SqliteValue::to_text)
                            .collect::<Vec<_>>();
                        fts5.insert_document_owned_with_tokenizer(
                            rowid,
                            column_values,
                            tokenizer.as_ref(),
                        );
                        let record = serialize_record(&persisted_values);
                        cursor.table_insert(cx, rowid, &record)?;
                        inserted_row_count = inserted_row_count.saturating_add(1);
                        self.record_last_insert_rowid(rowid);
                        Ok(())
                    })?;
                    return Ok(true);
                }
                self.emit_prepared_simple_join_rows(&prepared, |source_values| {
                    source_row_count = source_row_count.saturating_add(1);
                    let row = self.build_live_vtab_insert_row(
                        &layout,
                        source_values,
                        &format!("live virtual-table INSERT SELECT row {}", source_row_count),
                    )?;
                    let rowid = row
                        .explicit_rowid
                        .as_ref()
                        .map(Self::coerce_insert_rowid_value)
                        .transpose()?
                        .flatten()
                        .unwrap_or_else(|| fts5.allocate_rowid());
                    if !seen_rowids.insert(rowid) {
                        fts5.delete_document(rowid);
                        if cursor.table_move_to(cx, rowid)?.is_found() {
                            cursor.delete(cx)?;
                        }
                    }
                    let persisted_values = row.values;
                    let column_values = persisted_values
                        .iter()
                        .map(SqliteValue::to_text)
                        .collect::<Vec<_>>();
                    fts5.insert_document_owned_with_tokenizer(
                        rowid,
                        column_values,
                        tokenizer.as_ref(),
                    );
                    let record = serialize_record(&persisted_values);
                    cursor.table_insert(cx, rowid, &record)?;
                    inserted_row_count = inserted_row_count.saturating_add(1);
                    self.record_last_insert_rowid(rowid);
                    Ok(())
                })?;
                return Ok(true);
            }
            let patch_first_column_with_rowid = is_rtree_instance(instance.as_ref());
            self.emit_prepared_simple_join_rows(&prepared, |source_values| {
                source_row_count = source_row_count.saturating_add(1);
                let row = self.build_live_vtab_insert_row(
                    &layout,
                    source_values,
                    &format!("live virtual-table INSERT SELECT row {}", source_row_count),
                )?;
                let mut args = Vec::with_capacity(row.values.len() + 2);
                args.push(SqliteValue::Null);
                let new_rowid = if patch_first_column_with_rowid {
                    row.explicit_rowid
                        .clone()
                        .or_else(|| row.values.first().cloned())
                        .unwrap_or(SqliteValue::Null)
                } else {
                    row.explicit_rowid.clone().unwrap_or(SqliteValue::Null)
                };
                args.push(new_rowid);
                args.extend(row.values.iter().cloned());
                let rowid = instance.update(cx, &args)?.ok_or_else(|| {
                    FrankenError::Internal(format!(
                        "virtual table {table_name} did not return a rowid for INSERT",
                    ))
                })?;
                let mut persisted_values = row.values;
                if patch_first_column_with_rowid
                    && persisted_values.first().is_some_and(SqliteValue::is_null)
                {
                    persisted_values[0] = SqliteValue::Integer(rowid);
                }
                if cursor.table_move_to(cx, rowid)?.is_found() {
                    cursor.delete(cx)?;
                }
                let record = serialize_record(&persisted_values);
                cursor.table_insert(cx, rowid, &record)?;
                inserted_row_count = inserted_row_count.saturating_add(1);
                self.record_last_insert_rowid(rowid);
                Ok(())
            })?;
            Ok(true)
        })?;
        if !streamed {
            return Ok(None);
        }
        Ok(Some(inserted_row_count))
    }

    fn execute_live_vtab_insert_rows(
        &self,
        table_name: &str,
        rows: &[LiveVtabInsertRow],
    ) -> Result<Vec<i64>> {
        let cx = self.op_cx()?;
        let key = table_name.to_ascii_uppercase();
        #[cfg(feature = "ext-fts5")]
        {
            let is_lazy = {
                let instances = self.vtab_instances.borrow();
                instances
                    .get(&key)
                    .and_then(|instance| instance.as_any().downcast_ref::<Fts5Table>())
                    .is_some_and(Fts5Table::is_lazy_on_disk)
            };
            if is_lazy {
                self.promote_lazy_fts5_table(table_name)?;
            }
        }
        let mut instances = self.vtab_instances.borrow_mut();
        let instance = instances.get_mut(&key).ok_or_else(|| {
            FrankenError::Internal(format!("virtual table not found: {table_name}"))
        })?;
        self.begin_live_vtab_transaction_if_needed(table_name, instance.as_mut(), &cx)?;
        let patch_first_column_with_rowid = is_rtree_instance(instance.as_ref());

        let mut inserted_rowids = Vec::with_capacity(rows.len());
        for row in rows {
            let mut args = Vec::with_capacity(row.values.len() + 2);
            args.push(SqliteValue::Null);
            let new_rowid = if is_rtree_instance(instance.as_ref()) {
                row.explicit_rowid
                    .clone()
                    .or_else(|| row.values.first().cloned())
                    .unwrap_or(SqliteValue::Null)
            } else {
                row.explicit_rowid.clone().unwrap_or(SqliteValue::Null)
            };
            args.push(new_rowid);
            args.extend(row.values.iter().cloned());
            let rowid = instance.update(&cx, &args)?.ok_or_else(|| {
                FrankenError::Internal(format!(
                    "virtual table {table_name} did not return a rowid for INSERT",
                ))
            })?;
            inserted_rowids.push(rowid);
            self.record_last_insert_rowid(rowid);
        }
        drop(instances);

        #[cfg(feature = "ext-fts5")]
        if self.persist_rootpage_zero_fts5_insert_rows(table_name, rows, &inserted_rowids)? {
            return Ok(inserted_rowids);
        }

        self.persist_materialized_live_vtab_rows(
            table_name,
            rows,
            &inserted_rowids,
            patch_first_column_with_rowid,
        )?;

        Ok(inserted_rowids)
    }

    /// Execute a `DELETE` against a live virtual-table instance (FTS5, R-Tree,
    /// etc.) by enumerating the target rowids through the live scan path and
    /// routing each one through the instance's `xUpdate` delete branch. This
    /// keeps the in-memory module state (e.g. the FTS5 inverted index and the
    /// per-document content/docsize records) consistent with the backing
    /// storage B-tree, which is the source of truth on schema reload.
    ///
    /// This mirrors real SQLite, where `DELETE FROM <fts>` — with or without a
    /// `WHERE` clause — issues one `xUpdate(argc==1)` delete per matching
    /// rowid. The connection-level VDBE table-delete program only knows how to
    /// mutate ordinary B-tree tables; without this interception a vtab DELETE
    /// would silently delete the backing records while leaving the live module
    /// instance stale, so a subsequent re-`INSERT` of the same rowid trips the
    /// module's primary-key guard (frankensqlite#94).
    fn execute_live_vtab_delete(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<usize> {
        let table_name = delete.table.name.name.clone();

        // Enumerate the rowids to delete via the live scan path. `SELECT rowid`
        // routes through the same scan the user sees, so an empty/no-WHERE
        // delete enumerates every live row and a `WHERE`/`MATCH` predicate is
        // honored exactly as for a normal query.
        let rowid_select = Self::build_single_table_select(
            &delete.table,
            vec![ResultColumn::Expr {
                expr: Expr::Column(
                    fsqlite_ast::ColumnRef::bare("rowid"),
                    fsqlite_ast::Span::new(0, 0),
                ),
                alias: None,
            }],
            delete.where_clause.as_ref(),
            &[],
            None,
        );
        let matched = self.execute_statement(&Statement::Select(rowid_select), params)?;
        let mut rowids: Vec<i64> = Vec::with_capacity(matched.len());
        for row in &matched {
            match row.values().first() {
                Some(SqliteValue::Integer(rowid)) => rowids.push(*rowid),
                Some(SqliteValue::Null) | None => {
                    return Err(FrankenError::Internal(format!(
                        "live virtual-table DELETE on {table_name} produced a row without a rowid",
                    )));
                }
                Some(other) => {
                    return Err(FrankenError::Internal(format!(
                        "live virtual-table DELETE on {table_name} produced a non-integer rowid: {other:?}",
                    )));
                }
            }
        }

        if rowids.is_empty() {
            return Ok(0);
        }

        self.execute_live_vtab_delete_rowids(&table_name, &rowids)
    }

    fn execute_live_vtab_delete_rowids(&self, table_name: &str, rowids: &[i64]) -> Result<usize> {
        if rowids.is_empty() {
            return Ok(0);
        }

        let key = table_name.to_ascii_uppercase();
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        #[cfg(feature = "ext-fts5")]
        {
            let is_lazy = {
                let instances = self.vtab_instances.borrow();
                instances
                    .get(&key)
                    .and_then(|instance| instance.as_any().downcast_ref::<Fts5Table>())
                    .is_some_and(Fts5Table::is_lazy_on_disk)
            };
            if is_lazy {
                self.promote_lazy_fts5_table(table_name)?;
            }
        }
        #[cfg(feature = "ext-fts5")]
        if root_page == 0 && self.is_live_fts5_instance(table_name) {
            let cx = self.op_cx()?;
            let deleted = {
                let mut instances = self.vtab_instances.borrow_mut();
                let instance = instances.get_mut(&key).ok_or_else(|| {
                    FrankenError::Internal(format!("virtual table not found: {table_name}"))
                })?;
                self.begin_live_vtab_transaction_if_needed(table_name, instance.as_mut(), &cx)?;
                let mut count = 0usize;
                for rowid in rowids {
                    // `xUpdate(argc==1)`: a single old-rowid argument is a delete.
                    instance.update(&cx, &[SqliteValue::Integer(*rowid)])?;
                    count = count.saturating_add(1);
                }
                count
            };
            self.persist_rootpage_zero_fts5_deleted_rowids(table_name, rowids)?;
            return Ok(deleted);
        }
        let root = page_number_from_schema_root(root_page, table_name, "table")?;

        // First route each rowid through the module's delete branch so the
        // in-memory index/content/docsize state is updated and any module-level
        // delete rules (e.g. contentless_delete) are enforced. Then remove the
        // backing storage record so the two stay in lockstep.
        let deleted = self.with_pager_write_txn(|cx, txn| {
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
            let mut instances = self.vtab_instances.borrow_mut();
            let instance = instances.get_mut(&key).ok_or_else(|| {
                FrankenError::Internal(format!("virtual table not found: {table_name}"))
            })?;
            self.begin_live_vtab_transaction_if_needed(table_name, instance.as_mut(), cx)?;
            let mut count = 0usize;
            for rowid in rowids {
                // `xUpdate(argc==1)`: a single old-rowid argument is a delete.
                instance.update(cx, &[SqliteValue::Integer(*rowid)])?;
                if cursor.table_move_to(cx, *rowid)?.is_found() {
                    cursor.delete(cx)?;
                }
                count = count.saturating_add(1);
            }
            Ok(count)
        })?;

        Ok(deleted)
    }

    #[cfg(feature = "ext-fts5")]
    fn execute_fts5_magic_delete_insert(
        &self,
        insert: &fsqlite_ast::InsertStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Option<usize>> {
        if !self.insert_targets_live_fts5_command_column(insert) {
            return Ok(None);
        }
        let fsqlite_ast::InsertSource::Values(rows) = &insert.source else {
            return Ok(None);
        };
        let [row_exprs] = rows.as_slice() else {
            return Ok(None);
        };
        let source_values = self.evaluate_insert_source_row(row_exprs, params)?;
        let Some(SqliteValue::Text(command)) = source_values.first() else {
            return Ok(None);
        };
        if !command.eq_ignore_ascii_case("delete") {
            return Ok(None);
        }
        let rowid = source_values
            .get(1)
            .ok_or_else(|| {
                FrankenError::Internal(format!(
                    "FTS5 delete command for `{}` is missing rowid argument",
                    insert.table.name
                ))
            })
            .and_then(Self::coerce_insert_rowid_value)?
            .ok_or_else(|| FrankenError::TypeMismatch {
                expected: "non-NULL FTS5 delete rowid".to_owned(),
                actual: "null".to_owned(),
            })?;
        let affected = self.execute_live_vtab_delete_rowids(&insert.table.name, &[rowid])?;
        Ok(Some(affected))
    }

    #[cfg(feature = "ext-fts5")]
    fn insert_targets_live_fts5_command_column(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> bool {
        if !fts5_insert_uses_command_column(insert) {
            return false;
        }
        let key = insert.table.name.to_ascii_uppercase();
        let instances = self.vtab_instances.borrow();
        instances
            .get(&key)
            .and_then(|instance| instance.as_any().downcast_ref::<Fts5Table>())
            .is_some()
    }

    #[cfg(feature = "ext-fts5")]
    fn execute_fts5_maintenance_insert(
        &self,
        insert: &fsqlite_ast::InsertStatement,
    ) -> Result<bool> {
        let Some(command) = fts5_maintenance_insert_command(insert) else {
            return Ok(false);
        };
        if !self.insert_targets_live_fts5_command_column(insert) {
            return Ok(false);
        }

        {
            let key = insert.table.name.to_ascii_uppercase();
            let is_lazy = {
                let instances = self.vtab_instances.borrow();
                instances
                    .get(&key)
                    .and_then(|instance| instance.as_any().downcast_ref::<Fts5Table>())
                    .is_some_and(Fts5Table::is_lazy_on_disk)
            };
            if is_lazy {
                self.promote_lazy_fts5_table(insert.table.name.as_str())?;
            }
        }

        match command {
            Fts5MaintenanceCommand::Optimize => {}
            Fts5MaintenanceCommand::Rebuild => {
                let key = insert.table.name.to_ascii_uppercase();
                let mut instances = self.vtab_instances.borrow_mut();
                #[cfg(feature = "ext-fts5")]
                if let Some(instance) = instances.get_mut(&key)
                    && let Some(fts5) = instance.as_any_mut().downcast_mut::<Fts5Table>()
                {
                    fts5.ensure_rebuild_supported()?;
                    fts5.ensure_shadow_rows_materializable_for_mutation()?;
                    let rows = fts5.all_rows();
                    for (rowid, _) in &rows {
                        fts5.delete_document(*rowid);
                    }
                    for (rowid, columns) in &rows {
                        fts5.insert_document(*rowid, columns);
                    }
                }
                drop(instances);
                self.persist_rootpage_zero_fts5_shadow_rows(&insert.table.name)?;
            }
        }

        self.reset_statement_change_count();
        Ok(true)
    }

    #[cfg(not(feature = "ext-fts5"))]
    fn execute_fts5_maintenance_insert(
        &self,
        _insert: &fsqlite_ast::InsertStatement,
    ) -> Result<bool> {
        Ok(false)
    }

    fn persist_materialized_live_vtab_rows(
        &self,
        table_name: &str,
        rows: &[LiveVtabInsertRow],
        inserted_rowids: &[i64],
        patch_first_column_with_rowid: bool,
    ) -> Result<()> {
        if rows.is_empty() {
            return Ok(());
        }
        if rows.len() != inserted_rowids.len() {
            return Err(FrankenError::Internal(format!(
                "live virtual-table insert row count mismatch for {table_name}: {} rows vs {} rowids",
                rows.len(),
                inserted_rowids.len()
            )));
        }

        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        let root = page_number_from_schema_root(root_page, table_name, "table")?;

        // MonetDB/X100-style two-pass batch encoding: materialize every
        // post-patch row into a flat Vec, then let `encode_batch` emit the
        // whole blob of records with a single resize-and-fill.  The output
        // is byte-identical to the per-row `serialize_record` path, so this
        // fast lane is enabled by default and gated off via
        // `PRAGMA fsqlite.vectorized_makerecord = OFF`.
        let use_vectorized = self.vectorized_makerecord_enabled.get();

        self.with_pager_write_txn(|cx, txn| {
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;

            if use_vectorized {
                // Pass 0: materialize the patched values (we need to own the
                // rowid substitution before handing slices to encode_batch).
                let mut patched_rows: Vec<Vec<SqliteValue>> = Vec::with_capacity(rows.len());
                for (row, rowid) in rows.iter().zip(inserted_rowids.iter().copied()) {
                    let mut persisted_values = row.values.clone();
                    if patch_first_column_with_rowid
                        && persisted_values.first().is_some_and(SqliteValue::is_null)
                    {
                        persisted_values[0] = SqliteValue::Integer(rowid);
                    }
                    patched_rows.push(persisted_values);
                }
                let row_refs: Vec<&[SqliteValue]> =
                    patched_rows.iter().map(Vec::as_slice).collect();
                let mut encoded = Vec::new();
                let mut offsets = Vec::with_capacity(rows.len());
                encode_batch(&row_refs, &mut encoded, &mut offsets)?;

                for (i, rowid) in inserted_rowids.iter().copied().enumerate() {
                    if cursor.table_move_to(cx, rowid)?.is_found() {
                        cursor.delete(cx)?;
                    }
                    let start = offsets[i];
                    let end = offsets.get(i + 1).copied().unwrap_or(encoded.len());
                    cursor.table_insert(cx, rowid, &encoded[start..end])?;
                }
            } else {
                for (row, rowid) in rows.iter().zip(inserted_rowids.iter().copied()) {
                    let mut persisted_values = row.values.clone();
                    if patch_first_column_with_rowid
                        && persisted_values.first().is_some_and(SqliteValue::is_null)
                    {
                        persisted_values[0] = SqliteValue::Integer(rowid);
                    }
                    if cursor.table_move_to(cx, rowid)?.is_found() {
                        cursor.delete(cx)?;
                    }
                    let record = serialize_record(&persisted_values);
                    cursor.table_insert(cx, rowid, &record)?;
                }
            }
            Ok(())
        })
    }

    #[cfg(feature = "ext-fts5")]
    fn persist_rootpage_zero_fts5_shadow_rows(&self, table_name: &str) -> Result<bool> {
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        if root_page != 0 {
            return Ok(false);
        }

        let shadow_rows = {
            let instances = self.vtab_instances.borrow();
            let key = table_name.to_ascii_uppercase();
            let instance = instances.get(&key).ok_or_else(|| {
                FrankenError::Internal(format!("virtual table not found: {table_name}"))
            })?;
            let fts5 = instance
                .as_any()
                .downcast_ref::<Fts5Table>()
                .ok_or_else(|| {
                    FrankenError::Internal(format!(
                        "rootpage=0 virtual table {table_name} is not an FTS5 instance"
                    ))
                })?;
            fts5.encode_shadow_rows()
        };

        self.replace_storage_table_rows(
            &format!("{table_name}_data"),
            shadow_rows.data.into_iter().map(|row| {
                (
                    row.id,
                    vec![
                        SqliteValue::Integer(row.id),
                        SqliteValue::Blob(Arc::from(row.block.into_boxed_slice())),
                    ],
                )
            }),
        )?;

        self.replace_storage_table_rows(
            &format!("{table_name}_idx"),
            shadow_rows.idx.into_iter().enumerate().map(|(index, row)| {
                (
                    i64::try_from(index).unwrap_or(i64::MAX).saturating_add(1),
                    vec![
                        SqliteValue::Integer(i64::from(row.segid)),
                        SqliteValue::Blob(Arc::from(row.term.into_boxed_slice())),
                        SqliteValue::Integer(i64::from(row.btree_page)),
                    ],
                )
            }),
        )?;

        self.replace_storage_table_rows(
            &format!("{table_name}_config"),
            shadow_rows
                .config
                .into_iter()
                .enumerate()
                .map(|(index, row)| {
                    (
                        i64::try_from(index).unwrap_or(i64::MAX).saturating_add(1),
                        vec![SqliteValue::Text(row.key.into()), row.value],
                    )
                }),
        )?;

        let content_name = format!("{table_name}_content");
        if self.schema_table_exists(&content_name) {
            self.replace_storage_table_rows(
                &content_name,
                shadow_rows.content.into_iter().map(|row| {
                    let mut values = Vec::with_capacity(row.values.len() + 1);
                    values.push(SqliteValue::Integer(row.rowid));
                    values.extend(
                        row.values
                            .into_iter()
                            .map(|value| SqliteValue::Text(value.into())),
                    );
                    (row.rowid, values)
                }),
            )?;
        }

        let docsize_name = format!("{table_name}_docsize");
        if self.schema_table_exists(&docsize_name) {
            self.replace_storage_table_rows(
                &docsize_name,
                shadow_rows.docsize.into_iter().map(|row| {
                    let sz = encode_fts5_docsize_blob(&row.column_token_counts);
                    (
                        row.rowid,
                        vec![
                            SqliteValue::Integer(row.rowid),
                            SqliteValue::Blob(Arc::from(sz.into_boxed_slice())),
                        ],
                    )
                }),
            )?;
        }

        Ok(true)
    }

    #[cfg(feature = "ext-fts5")]
    fn persist_rootpage_zero_fts5_insert_rows(
        &self,
        table_name: &str,
        rows: &[LiveVtabInsertRow],
        inserted_rowids: &[i64],
    ) -> Result<bool> {
        if rows.len() != inserted_rowids.len() {
            return Err(FrankenError::Internal(format!(
                "live FTS5 insert row count mismatch for {table_name}: {} rows vs {} rowids",
                rows.len(),
                inserted_rowids.len()
            )));
        }
        let Some(layout) = self.rootpage_zero_fts5_persistence_layout(table_name)? else {
            return Ok(false);
        };
        if !layout.has_internal_content_shadow {
            return self.persist_rootpage_zero_fts5_contentless_incremental_insert(
                table_name,
                rows,
                inserted_rowids,
                layout.column_count,
            );
        }

        self.reset_rootpage_zero_fts5_segment_metadata(table_name, layout.column_count)?;

        let content_name = format!("{table_name}_content");
        if self.schema_table_exists(&content_name) {
            self.upsert_storage_table_rows(
                &content_name,
                rows.iter()
                    .zip(inserted_rowids.iter().copied())
                    .map(|(row, rowid)| {
                        let texts = fts5_live_insert_row_text_values(row, layout.column_count);
                        let mut values = Vec::with_capacity(texts.len() + 1);
                        values.push(SqliteValue::Integer(rowid));
                        values.extend(
                            texts
                                .into_iter()
                                .map(|value| SqliteValue::Text(value.into())),
                        );
                        (rowid, values)
                    }),
            )?;
        }

        let docsize_name = format!("{table_name}_docsize");
        if self.schema_table_exists(&docsize_name) {
            let (indexed_columns, tokenizer) = {
                let instances = self.vtab_instances.borrow();
                let key = table_name.to_ascii_uppercase();
                let instance = instances.get(&key).ok_or_else(|| {
                    FrankenError::Internal(format!("virtual table not found: {table_name}"))
                })?;
                let fts5 = instance
                    .as_any()
                    .downcast_ref::<Fts5Table>()
                    .ok_or_else(|| {
                        FrankenError::Internal(format!(
                            "rootpage=0 virtual table {table_name} is not an FTS5 instance"
                        ))
                    })?;
                (
                    fts5.indexed_columns().to_vec(),
                    fts5.create_tokenizer_instance(),
                )
            };
            self.upsert_storage_table_rows(
                &docsize_name,
                rows.iter()
                    .zip(inserted_rowids.iter().copied())
                    .map(|(row, rowid)| {
                        let texts = fts5_live_insert_row_text_values(row, layout.column_count);
                        let counts = fts5_docsize_counts_for_values(
                            &texts,
                            &indexed_columns,
                            tokenizer.as_ref(),
                        );
                        let sz = encode_fts5_docsize_blob(&counts);
                        (
                            rowid,
                            vec![
                                SqliteValue::Integer(rowid),
                                SqliteValue::Blob(Arc::from(sz.into_boxed_slice())),
                            ],
                        )
                    }),
            )?;
        }

        Ok(true)
    }

    /// Persist a contentless rootpage-zero FTS5 INSERT as an incremental
    /// segment append.
    ///
    /// Avoids re-encoding the whole inverted index on every insert. The legacy
    /// contentless path delegated to
    /// [`Self::persist_rootpage_zero_fts5_shadow_rows`], which rebuilds the
    /// single `_data` segment from the entire in-memory index on every INSERT —
    /// O(table) per insert, O(table^2) over a batch rebuild. That wedged
    /// `cass index --full` above ~15-30 MB of content (bd-sf8dx / cass#301).
    ///
    /// This appends one fresh segment (containing only the current statement's
    /// rows) onto the persisted structure: point-read the current structure +
    /// averages, encode the delta in O(new rows), then upsert the new leaf and
    /// the two changed metadata rows. Until a real segment exists (the first
    /// insert, or runs of empty/all-unindexed rows), it falls back to the full
    /// encode, which also lays down the `_config`/`_idx`/`_docsize` shadows.
    #[cfg(feature = "ext-fts5")]
    fn persist_rootpage_zero_fts5_contentless_incremental_insert(
        &self,
        table_name: &str,
        rows: &[LiveVtabInsertRow],
        inserted_rowids: &[i64],
        column_count: usize,
    ) -> Result<bool> {
        // The incremental append needs an existing `_data` shadow to read the
        // current structure from; without one, fall back to the full encode.
        if !self.schema_table_exists(&format!("{table_name}_data")) {
            return self.persist_rootpage_zero_fts5_shadow_rows(table_name);
        }

        // Point-read the current on-disk structure + averages. `with_lazy_fts5_reader`
        // reuses the active write txn when one is open, so these reflect this
        // connection's own prior appends within the same transaction
        // (read-your-writes), keeping `next_segid` collision-free.
        let (structure, averages) = self.with_lazy_fts5_reader(table_name, |reader| {
            let structure = match reader.read_data_block(FTS5_STRUCTURE_ROWID)? {
                Some(block) => Some(Fts5StructureRecord::decode(&block)?),
                None => None,
            };
            let averages = match reader.read_data_block(FTS5_AVERAGES_ROWID)? {
                Some(block) => Some(Fts5AveragesRecord::decode(&block, column_count)?),
                None => None,
            };
            Ok((structure, averages))
        })?;

        // No persisted segment yet (fresh table, or only empty rows so far):
        // the full encode lays down the first segment plus the config/idx/docsize
        // shadows. Once a segment exists, every later INSERT appends incrementally.
        let Some(structure) = structure.filter(|s| s.segment_count() > 0) else {
            return self.persist_rootpage_zero_fts5_shadow_rows(table_name);
        };
        // Segments imply at least one tokenised document, so the full encode
        // always wrote a (non-empty) averages row alongside them. If it is
        // somehow missing, the `_data` shadow is inconsistent: rebuild from the
        // in-memory index rather than appending onto undercounted corpus stats.
        let Some(averages) = averages else {
            return self.persist_rootpage_zero_fts5_shadow_rows(table_name);
        };
        let next_segid = structure
            .levels
            .iter()
            .flat_map(|level| level.segments.iter())
            .map(|segment| segment.segid)
            .max()
            .unwrap_or(0)
            .saturating_add(1);

        let flush = {
            let instances = self.vtab_instances.borrow();
            let key = table_name.to_ascii_uppercase();
            let fts5 = instances
                .get(&key)
                .and_then(|instance| instance.as_any().downcast_ref::<Fts5Table>())
                .ok_or_else(|| {
                    FrankenError::Internal(format!(
                        "rootpage=0 virtual table {table_name} is not an FTS5 instance"
                    ))
                })?;
            let new_docs: Vec<(i64, &[SqliteValue])> = inserted_rowids
                .iter()
                .copied()
                .zip(rows.iter().map(|row| row.values.as_slice()))
                .collect();
            fts5.encode_incremental_insert_flush(&new_docs, &structure, &averages, next_segid)?
        };
        let Some(flush) = flush else {
            return Ok(true);
        };

        // Append the new segment leaf and replace the structure + averages rows
        // (point upserts — O(new), never touching the existing leaves).
        let mut data_rows: Vec<(i64, Vec<SqliteValue>)> = Vec::with_capacity(3);
        for row in flush
            .leaf_data_row
            .into_iter()
            .chain([flush.structure_data_row, flush.averages_data_row])
        {
            data_rows.push((
                row.id,
                vec![
                    SqliteValue::Integer(row.id),
                    SqliteValue::Blob(Arc::from(row.block.into_boxed_slice())),
                ],
            ));
        }
        self.upsert_storage_table_rows(&format!("{table_name}_data"), data_rows)?;

        // Append the new documents' docsize rows (read back on reopen for BM25).
        let docsize_name = format!("{table_name}_docsize");
        if self.schema_table_exists(&docsize_name) {
            self.upsert_storage_table_rows(
                &docsize_name,
                flush.docsize_rows.into_iter().map(|row| {
                    let sz = encode_fts5_docsize_blob(&row.column_token_counts);
                    (
                        row.rowid,
                        vec![
                            SqliteValue::Integer(row.rowid),
                            SqliteValue::Blob(Arc::from(sz.into_boxed_slice())),
                        ],
                    )
                }),
            )?;
        }

        tracing::debug!(
            table = table_name,
            segid = next_segid,
            new_rows = inserted_rowids.len(),
            "fts5: appended incremental contentless segment (bd-sf8dx)"
        );
        Ok(true)
    }

    #[cfg(feature = "ext-fts5")]
    fn persist_rootpage_zero_fts5_deleted_rowids(
        &self,
        table_name: &str,
        rowids: &[i64],
    ) -> Result<bool> {
        let Some(layout) = self.rootpage_zero_fts5_persistence_layout(table_name)? else {
            return Ok(false);
        };
        if !layout.has_internal_content_shadow {
            return self.persist_rootpage_zero_fts5_shadow_rows(table_name);
        }

        self.reset_rootpage_zero_fts5_segment_metadata(table_name, layout.column_count)?;

        let content_name = format!("{table_name}_content");
        if self.schema_table_exists(&content_name) {
            self.delete_storage_table_rowids(&content_name, rowids)?;
        }
        let docsize_name = format!("{table_name}_docsize");
        if self.schema_table_exists(&docsize_name) {
            self.delete_storage_table_rowids(&docsize_name, rowids)?;
        }
        Ok(true)
    }

    #[cfg(feature = "ext-fts5")]
    fn rootpage_zero_fts5_persistence_layout(
        &self,
        table_name: &str,
    ) -> Result<Option<RootpageZeroFts5PersistenceLayout>> {
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        if root_page != 0 {
            return Ok(None);
        }
        let has_internal_content_shadow =
            self.rootpage_zero_fts5_has_internal_content_shadow(table_name);
        let instances = self.vtab_instances.borrow();
        let key = table_name.to_ascii_uppercase();
        let instance = instances.get(&key).ok_or_else(|| {
            FrankenError::Internal(format!("virtual table not found: {table_name}"))
        })?;
        let fts5 = instance
            .as_any()
            .downcast_ref::<Fts5Table>()
            .ok_or_else(|| {
                FrankenError::Internal(format!(
                    "rootpage=0 virtual table {table_name} is not an FTS5 instance"
                ))
            })?;
        Ok(Some(RootpageZeroFts5PersistenceLayout {
            column_count: fts5.columns().len(),
            has_internal_content_shadow,
        }))
    }

    #[cfg(feature = "ext-fts5")]
    fn rootpage_zero_fts5_has_internal_content_shadow(&self, table_name: &str) -> bool {
        let fallback_content_name = format!("{table_name}_content");
        let fallback = || self.schema_table_exists(&fallback_content_name);
        let ddl = self.original_ddl_sql.borrow();
        let Some(create_sql) = ddl.get(&table_name.to_ascii_lowercase()) else {
            return fallback();
        };
        let Ok(Statement::CreateVirtualTable(create_stmt)) = parse_single_statement(create_sql)
        else {
            return fallback();
        };
        if !create_stmt.module.eq_ignore_ascii_case("fts5") {
            return false;
        }
        virtual_table_option_value(&create_stmt.args, "content").is_none()
    }

    #[cfg(feature = "ext-fts5")]
    fn reset_rootpage_zero_fts5_segment_metadata(
        &self,
        table_name: &str,
        column_count: usize,
    ) -> Result<()> {
        self.replace_storage_table_rows(
            &format!("{table_name}_data"),
            empty_fts5_data_storage_rows(column_count),
        )?;
        self.replace_storage_table_rows(
            &format!("{table_name}_idx"),
            std::iter::empty::<(i64, Vec<SqliteValue>)>(),
        )
    }

    #[cfg(feature = "ext-fts5")]
    fn is_live_fts5_instance(&self, table_name: &str) -> bool {
        let key = table_name.to_ascii_uppercase();
        self.vtab_instances
            .borrow()
            .get(&key)
            .is_some_and(|instance| instance.as_any().downcast_ref::<Fts5Table>().is_some())
    }

    #[cfg(feature = "ext-fts5")]
    fn schema_table_exists(&self, table_name: &str) -> bool {
        self.schema
            .borrow()
            .iter()
            .any(|table| table.name.eq_ignore_ascii_case(table_name))
    }

    #[cfg(feature = "ext-fts5")]
    fn replace_storage_table_rows<I>(&self, table_name: &str, rows: I) -> Result<()>
    where
        I: IntoIterator<Item = (i64, Vec<SqliteValue>)>,
    {
        let (root_page, without_rowid) = {
            let schema = self.schema.borrow();
            let table = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?;
            (table.root_page, table.without_rowid)
        };
        let root = page_number_from_schema_root(root_page, table_name, "table")?;
        let rows = rows.into_iter().collect::<Vec<_>>();

        self.with_pager_write_txn(|cx, txn| {
            // A stock-SQLite-created FTS5 store persists the `%_idx` (and
            // `%_config`) shadows as `WITHOUT ROWID` tables — index-structured
            // b-trees, not rowid tables. They MUST be opened as *index* cursors
            // and mutated via full-record index-key insert/delete. Opening a
            // *table* cursor on an index-structured root page trips the
            // `is_table` guard in `table_seek_for_insert`, aborting an
            // otherwise-valid UPDATE with a false "database disk image is
            // malformed: table_seek called on index page … cursor is_table flag
            // likely incorrect". (frankensqlite#121)
            //
            // FrankenSQLite-created FTS5 stores model these same shadows as
            // rowid tables (`without_rowid == false`), so they keep the table
            // path unchanged.
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, !without_rowid)?;
            if without_rowid {
                // Clear every existing key (the leftmost entry shrinks the tree
                // by one each iteration), then re-insert the full-record keys.
                // WITHOUT ROWID cells store the entire row as the index key, with
                // the PRIMARY KEY columns leading — for `%_idx`
                // (segid, term, pgno PRIMARY KEY(segid, term)) and `%_config`
                // (k PRIMARY KEY, v) the supplied column order already matches,
                // and the synthetic rowid the caller supplies is irrelevant.
                while cursor.first(cx)? {
                    cursor.delete(cx)?;
                }
                for (_synthetic_rowid, values) in rows {
                    let record = serialize_record(&values);
                    cursor.index_insert(cx, &record)?;
                }
                return Ok(());
            }
            let mut existing_rowids = Vec::new();
            if cursor.first(cx)? {
                loop {
                    existing_rowids.push(cursor.rowid(cx)?);
                    if !cursor.next(cx)? {
                        break;
                    }
                }
            }
            for rowid in existing_rowids {
                if cursor.table_move_to(cx, rowid)?.is_found() {
                    cursor.delete(cx)?;
                }
            }
            for (rowid, values) in rows {
                let record = serialize_record(&values);
                cursor.table_insert(cx, rowid, &record)?;
            }
            Ok(())
        })
    }

    /// Physically rewrite every row of `table_name`, deleting the record slot at
    /// `removed_slot` (the dropped column's position in the pre-drop schema).
    ///
    /// ALTER TABLE DROP COLUMN must realign trailing columns: the read path
    /// (cursor_column) decodes a row by physical slot index, so updating only the
    /// schema metadata leaves the old record layout and every column after the
    /// dropped position misreads the wrong physical slot (and mixed-width records
    /// can trip the payload-width consistency check). bd-nb2j9 / bd-w50nr.
    ///
    /// Records narrower than `removed_slot` (columns added via ALTER ADD COLUMN
    /// that were never physically materialized) are left untouched — the slot
    /// they would occupy does not exist on disk.
    fn rewrite_table_records_remove_slot(
        &self,
        table_name: &str,
        removed_slot: usize,
    ) -> Result<()> {
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        if root_page <= 0 {
            return Ok(());
        }
        let root = page_number_from_schema_root(root_page, table_name, "table")?;
        self.with_pager_write_txn(|cx, txn| {
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
            // Collect (rowid, rewritten record) first, then delete+reinsert so we
            // never mutate the tree while iterating it.
            let mut rewritten: Vec<(i64, Vec<u8>)> = Vec::new();
            if cursor.first(cx)? {
                loop {
                    let rowid = cursor.rowid(cx)?;
                    let payload = cursor.payload(cx)?;
                    let mut values =
                        parse_record(&payload).ok_or_else(|| FrankenError::DatabaseCorrupt {
                            detail: format!(
                                "table `{table_name}` rowid {rowid} payload is not a valid SQLite record"
                            ),
                        })?;
                    if removed_slot < values.len() {
                        values.remove(removed_slot);
                    }
                    rewritten.push((rowid, serialize_record(&values)));
                    if !cursor.next(cx)? {
                        break;
                    }
                }
            }
            for (rowid, _) in &rewritten {
                if cursor.table_move_to(cx, *rowid)?.is_found() {
                    cursor.delete(cx)?;
                }
            }
            for (rowid, record) in &rewritten {
                cursor.table_insert(cx, *rowid, record)?;
            }
            Ok(())
        })
    }

    #[cfg(feature = "ext-fts5")]
    fn upsert_storage_table_rows<I>(&self, table_name: &str, rows: I) -> Result<()>
    where
        I: IntoIterator<Item = (i64, Vec<SqliteValue>)>,
    {
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        let root = page_number_from_schema_root(root_page, table_name, "table")?;
        let rows = rows.into_iter().collect::<Vec<_>>();

        self.with_pager_write_txn(|cx, txn| {
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
            for (rowid, values) in rows {
                if cursor.table_move_to(cx, rowid)?.is_found() {
                    cursor.delete(cx)?;
                }
                let record = serialize_record(&values);
                cursor.table_insert(cx, rowid, &record)?;
            }
            Ok(())
        })
    }

    #[cfg(feature = "ext-fts5")]
    fn delete_storage_table_rowids(&self, table_name: &str, rowids: &[i64]) -> Result<()> {
        let root_page = {
            let schema = self.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(table_name))
                .map(|table| table.root_page)
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?
        };
        let root = page_number_from_schema_root(root_page, table_name, "table")?;

        self.with_pager_write_txn(|cx, txn| {
            let mut cursor = Self::new_pager_btree_cursor(cx, txn, root, true)?;
            for rowid in rowids {
                if cursor.table_move_to(cx, *rowid)?.is_found() {
                    cursor.delete(cx)?;
                }
            }
            Ok(())
        })
    }

    #[cfg(feature = "ext-fts5")]
    fn create_rootpage_zero_fts5_virtual_table(
        &self,
        table_name: &str,
        col_infos: Vec<ColumnInfo>,
        create_sql: &str,
        instance: Box<dyn ErasedVtabInstance>,
        args: &[String],
    ) -> Result<()> {
        self.preflight_fts5_shadow_table_names(table_name, args)?;
        self.schema.borrow_mut().push(TableSchema {
            name: table_name.to_owned(),
            root_page: 0,
            columns: col_infos.clone(),
            indexes: Vec::new(),
            strict: false,
            without_rowid: false,
            primary_key_constraints: Vec::new(),
            foreign_keys: Vec::new(),
            check_constraints: Vec::new(),
        });
        self.rebuild_schema_indices();
        let replaced = self
            .vtab_instances
            .borrow_mut()
            .insert(table_name.to_ascii_uppercase(), instance);
        if replaced.is_some() {
            return Err(FrankenError::Internal(format!(
                "live virtual table registry already contains {table_name}"
            )));
        }
        self.note_live_vtab_created(table_name);
        self.insert_sqlite_master_row("table", table_name, table_name, 0, create_sql)?;
        self.create_fts5_shadow_tables(table_name, args, &col_infos)?;
        self.persist_rootpage_zero_fts5_shadow_rows(table_name)?;
        self.increment_schema_cookie()?;
        Ok(())
    }

    #[cfg(feature = "ext-fts5")]
    fn preflight_fts5_shadow_table_names(&self, table_name: &str, args: &[String]) -> Result<()> {
        let shadow_names = fts5_shadow_drop_names(table_name, args);
        let schema = self.schema.borrow();
        if let Some(existing) = shadow_names.iter().find(|shadow_name| {
            schema
                .iter()
                .any(|table| table.name.eq_ignore_ascii_case(shadow_name))
        }) {
            return Err(FrankenError::Internal(format!(
                "table {existing} already exists"
            )));
        }
        Ok(())
    }

    #[cfg(feature = "ext-fts5")]
    fn create_fts5_shadow_tables(
        &self,
        table_name: &str,
        args: &[String],
        fts_columns: &[ColumnInfo],
    ) -> Result<()> {
        for table in fts5_shadow_table_defs(table_name, args, fts_columns) {
            self.create_fts5_shadow_table(table)?;
        }
        Ok(())
    }

    #[cfg(feature = "ext-fts5")]
    fn create_fts5_shadow_table(&self, table: Fts5ShadowTableDef) -> Result<()> {
        let root_page = self.allocate_root_page()?;
        self.db
            .borrow_mut()
            .create_table_at(root_page, table.columns.len());
        if let Some(rowid_alias_idx) = table.columns.iter().position(|column| column.is_ipk) {
            self.rowid_alias_columns
                .borrow_mut()
                .insert(table.name.to_ascii_lowercase(), rowid_alias_idx);
        }
        self.schema.borrow_mut().push(TableSchema {
            name: table.name.clone(),
            root_page,
            columns: table.columns,
            indexes: Vec::new(),
            strict: false,
            without_rowid: false,
            primary_key_constraints: Vec::new(),
            foreign_keys: Vec::new(),
            check_constraints: Vec::new(),
        });
        self.rebuild_schema_indices();
        self.insert_sqlite_master_row(
            "table",
            &table.name,
            &table.name,
            root_page,
            &table.create_sql,
        )
    }

    #[allow(clippy::unused_self)]
    fn map_insert_source_row_to_table_row(
        &self,
        default_row: &[SqliteValue],
        source_targets: &[InsertTarget],
        rowid_alias_col_idx: Option<usize>,
        explicit_rowid_source: Option<usize>,
        source_values: &[SqliteValue],
        context: &str,
    ) -> Result<Vec<SqliteValue>> {
        if source_values.len() != source_targets.len() {
            return Err(FrankenError::Internal(format!(
                "{context}: column count mismatch (source has {}, target expects {})",
                source_values.len(),
                source_targets.len()
            )));
        }

        let mut row = default_row.to_vec();
        let explicit_rowid = explicit_rowid_source
            .and_then(|source_idx| source_values.get(source_idx))
            .map(Self::coerce_insert_rowid_value)
            .transpose()?
            .flatten();
        let mut filled_targets = vec![false; row.len()];
        for (source_idx, target) in source_targets.iter().copied().enumerate() {
            let InsertTarget::Column(target_idx) = target else {
                continue;
            };
            if Some(target_idx) == rowid_alias_col_idx || filled_targets[target_idx] {
                continue;
            }
            row[target_idx] = source_values[source_idx].clone();
            filled_targets[target_idx] = true;
        }
        if let (Some(ipk_idx), Some(rowid)) = (rowid_alias_col_idx, explicit_rowid) {
            row[ipk_idx] = SqliteValue::Integer(rowid);
        }
        Ok(row)
    }

    fn collect_insert_default_sqls(&self, table_name: &str) -> Result<Vec<Option<String>>> {
        let default_sqls: Vec<Option<String>> = {
            let schema = self.schema.borrow();
            let table = schema
                .iter()
                .find(|tbl| tbl.name.eq_ignore_ascii_case(table_name))
                .ok_or_else(|| FrankenError::Internal(format!("table not found: {table_name}")))?;
            table
                .columns
                .iter()
                .map(|column| column.default_value.clone())
                .collect()
        };

        Ok(default_sqls)
    }

    fn coerce_rowid_lookup_value(value: &SqliteValue) -> Option<i64> {
        Self::coerce_integral_rowid_value(value)
    }

    fn coerce_insert_rowid_value(value: &SqliteValue) -> Result<Option<i64>> {
        if value.is_null() {
            return Ok(None);
        }
        if let Some(rowid) = Self::coerce_integral_rowid_value(value) {
            Ok(Some(rowid))
        } else {
            Err(FrankenError::TypeMismatch {
                expected: "INTEGER PRIMARY KEY rowid".to_owned(),
                actual: value.typeof_str().to_owned(),
            })
        }
    }

    fn coerce_integral_rowid_value(value: &SqliteValue) -> Option<i64> {
        match value {
            SqliteValue::Null => None,
            SqliteValue::Integer(rowid) => Some(*rowid),
            other => match other.clone().apply_affinity(TypeAffinity::Integer) {
                SqliteValue::Integer(rowid) => Some(rowid),
                _ => None,
            },
        }
    }

    fn suppress_column_default_runtime_inputs(&self) -> ColumnDefaultEvalGuard<'_> {
        let next_depth = self.column_default_eval_depth.get().saturating_add(1);
        self.column_default_eval_depth.set(next_depth);
        ColumnDefaultEvalGuard { conn: self }
    }

    fn is_evaluating_column_default(&self) -> bool {
        self.column_default_eval_depth.get() > 0
    }

    fn evaluate_default_row_from_sqls(
        &self,
        default_sqls: &[Option<String>],
    ) -> Result<Vec<SqliteValue>> {
        default_sqls
            .iter()
            .map(|default_sql| self.evaluate_column_default_value(default_sql.as_deref()))
            .collect()
    }

    fn evaluate_column_default_value(&self, default_sql: Option<&str>) -> Result<SqliteValue> {
        let Some(default_sql) = default_sql else {
            return Ok(SqliteValue::Null);
        };
        let trimmed = default_sql.trim();
        if trimmed.is_empty() {
            return Ok(SqliteValue::Null);
        }

        let literal_sql = Self::strip_wrapping_default_parens(trimmed);
        if let Some(value) = Self::parse_wrapped_default_text(literal_sql, '\'')
            .or_else(|| Self::parse_wrapped_default_text(literal_sql, '"'))
        {
            return Ok(value);
        }

        let sql = format!("SELECT {trimmed}");
        let statement = parse_single_statement(&sql)?;
        if let Statement::Select(select) = &statement
            && select.with.is_none()
            && select.order_by.is_empty()
            && select.limit.is_none()
            && select.body.compounds.is_empty()
            && let SelectCore::Select {
                columns,
                from: None,
                where_clause: None,
                group_by,
                having: None,
                ..
            } = &select.body.select
            && group_by.is_empty()
            && columns.len() == 1
            && let ResultColumn::Expr { expr, .. } = &columns[0]
        {
            let has_registered_agg = {
                let registry = self.func_registry.borrow();
                expr_contains_registered_agg(expr, registry.as_ref())
            };
            if default_expr_is_self_contained(expr) {
                if !has_registered_agg {
                    let empty_row = [];
                    let empty_col_map = [];
                    return self
                        .eval_expr_with_subqueries(expr, &empty_row, &empty_col_map, None)
                        .map_err(|error| {
                            FrankenError::Internal(format!(
                                "failed to evaluate DEFAULT expression `{trimmed}`: {error}"
                            ))
                        });
                }

                let rows = self
                    .execute_fromless_aggregate(select, None)
                    .map_err(|error| {
                        FrankenError::Internal(format!(
                            "failed to evaluate DEFAULT expression `{trimmed}`: {error}"
                        ))
                    })?;
                return Ok(rows
                    .first()
                    .and_then(|row| row.values().first())
                    .cloned()
                    .unwrap_or(SqliteValue::Null));
            }
            if let Expr::Column(col_ref, _) = expr
                && col_ref.table.is_none()
            {
                return Ok(SqliteValue::Text(col_ref.column.clone().into()));
            }
        }

        let _guard = self.suppress_column_default_runtime_inputs();
        let rows = self.execute_statement(&statement, None).map_err(|error| {
            FrankenError::Internal(format!(
                "failed to evaluate DEFAULT expression `{trimmed}`: {error}"
            ))
        })?;

        Ok(rows
            .first()
            .and_then(|row| row.values().first())
            .cloned()
            .unwrap_or(SqliteValue::Null))
    }

    fn collect_update_trigger_rows(
        &self,
        update: &fsqlite_ast::UpdateStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<(Vec<SqliteValue>, Vec<SqliteValue>)>> {
        let matched_rows = self.select_matching_rows(
            &update.table,
            update.where_clause.as_ref(),
            &[],
            None,
            params,
        )?;
        if matched_rows.is_empty() {
            return Ok(Vec::new());
        }

        let table_name = &update.table.name.name;
        let schema = self.schema.borrow();
        let table = schema
            .iter()
            .find(|t| t.name.eq_ignore_ascii_case(table_name))
            .ok_or_else(|| FrankenError::NoSuchTable {
                name: table_name.clone(),
            })?;
        let column_names: Vec<String> = table.columns.iter().map(|col| col.name.clone()).collect();
        let table_label = update
            .table
            .alias
            .as_deref()
            .unwrap_or(table_name)
            .to_owned();
        drop(schema);

        let col_map = column_names
            .iter()
            .cloned()
            .map(|name| (table_label.clone(), name, false))
            .collect::<Vec<_>>();

        // Bind placeholders in assignment values so eval_join_expr can
        // evaluate them.  Without this, numbered placeholders (`?1`, `?2`, ...)
        // would reach the catch-all arm and fail with "unsupported expression
        // type: Placeholder".  This is particularly triggered when
        // PRAGMA foreign_keys=ON causes collect_update_trigger_rows to be
        // called for FK constraint checking.
        let bound_assignments = if let Some(p) = params {
            let mut cloned = update.assignments.clone();
            let mut bind_state = BindParamState::default();
            for a in &mut cloned {
                bind_placeholders_in_expr(&mut a.value, &mut bind_state, p)?;
            }
            cloned
        } else {
            update.assignments.clone()
        };

        let mut trigger_rows = Vec::with_capacity(matched_rows.len());
        for row in matched_rows {
            let old_values = row.values().to_vec();
            let mut new_values = old_values.clone();

            for assignment in &bound_assignments {
                match &assignment.target {
                    fsqlite_ast::AssignmentTarget::Column(column_name) => {
                        let target_index =
                            find_column_index_case_insensitive(&column_names, column_name)
                                .ok_or_else(|| {
                                    FrankenError::Internal(format!(
                                        "UPDATE trigger snapshot: unknown column `{column_name}`"
                                    ))
                                })?;
                        new_values[target_index] =
                            eval_join_expr(&assignment.value, &old_values, &col_map)?;
                    }
                    fsqlite_ast::AssignmentTarget::ColumnList(columns) => {
                        if columns.len() == 1 {
                            let target_index =
                                find_column_index_case_insensitive(&column_names, &columns[0])
                                    .ok_or_else(|| {
                                        FrankenError::Internal(format!(
                                            "UPDATE trigger snapshot: unknown column `{}`",
                                            columns[0]
                                        ))
                                    })?;
                            let value_expr = match &assignment.value {
                                Expr::RowValue(values, _) if values.len() == 1 => &values[0],
                                other => other,
                            };
                            new_values[target_index] =
                                eval_join_expr(value_expr, &old_values, &col_map)?;
                            continue;
                        }

                        match &assignment.value {
                            Expr::RowValue(values, _) if values.len() == columns.len() => {
                                for (column_name, value_expr) in columns.iter().zip(values) {
                                    let target_index = find_column_index_case_insensitive(
                                        &column_names,
                                        column_name,
                                    )
                                    .ok_or_else(|| {
                                        FrankenError::Internal(format!(
                                            "UPDATE trigger snapshot: unknown column `{column_name}`"
                                        ))
                                    })?;
                                    new_values[target_index] =
                                        eval_join_expr(value_expr, &old_values, &col_map)?;
                                }
                            }
                            _ => {
                                return Err(FrankenError::Internal(
                                    "UPDATE trigger snapshot: column-list assignment requires row-value expression of matching arity".to_owned(),
                                ));
                            }
                        }
                    }
                }
            }

            trigger_rows.push((old_values, new_values));
        }
        Ok(trigger_rows)
    }

    fn collect_delete_trigger_rows(
        &self,
        delete: &fsqlite_ast::DeleteStatement,
        params: Option<&[SqliteValue]>,
    ) -> Result<Vec<Vec<SqliteValue>>> {
        let matched_rows = self.select_matching_rows(
            &delete.table,
            delete.where_clause.as_ref(),
            &[],
            None,
            params,
        )?;
        Ok(matched_rows
            .into_iter()
            .map(|row| row.values().to_vec())
            .collect())
    }

    fn txn_metrics_mark_started(&self) {
        let mut started = false;
        {
            let mut metrics = self.txn_lifecycle_metrics.borrow_mut();
            if metrics.active_started_at.is_none() {
                metrics.active_started_at = Some(Instant::now());
                metrics.active_first_read_at = None;
                metrics.active_first_write_at = None;
                metrics.active_read_ops = 0;
                metrics.active_write_ops = 0;
                metrics.active_savepoint_depth = 0;
                metrics.active_rollbacks = 0;
                started = true;
            }
        }
        if started {
            self.note_connection_transaction_started();
        }
    }

    fn txn_metrics_note_read(&self) {
        let mut metrics = self.txn_lifecycle_metrics.borrow_mut();
        if metrics.active_started_at.is_some() {
            metrics.active_read_ops = metrics.active_read_ops.saturating_add(1);
            if metrics.active_first_read_at.is_none() {
                metrics.active_first_read_at = Some(Instant::now());
            }
        }
    }

    fn txn_metrics_note_write(&self) {
        let mut metrics = self.txn_lifecycle_metrics.borrow_mut();
        if metrics.active_started_at.is_some() {
            metrics.active_write_ops = metrics.active_write_ops.saturating_add(1);
            if metrics.active_first_write_at.is_none() {
                metrics.active_first_write_at = Some(Instant::now());
            }
        }
    }

    fn txn_metrics_set_savepoint_depth(&self, depth: usize) {
        let mut metrics = self.txn_lifecycle_metrics.borrow_mut();
        if metrics.active_started_at.is_some() {
            metrics.active_savepoint_depth = u64::try_from(depth).unwrap_or(u64::MAX);
        }
    }

    fn txn_metrics_note_rollback(&self) {
        let mut metrics = self.txn_lifecycle_metrics.borrow_mut();
        metrics.rollback_count_total = metrics.rollback_count_total.saturating_add(1);
        if metrics.active_started_at.is_some() {
            metrics.active_rollbacks = metrics.active_rollbacks.saturating_add(1);
        }
    }

    fn txn_metrics_mark_finished(&self) {
        {
            let mut metrics = self.txn_lifecycle_metrics.borrow_mut();
            let Some(started_at) = metrics.active_started_at.take() else {
                return;
            };

            let elapsed_ms_u128 = started_at.elapsed().as_millis();
            let elapsed_ms = u64::try_from(elapsed_ms_u128).unwrap_or(u64::MAX);
            metrics.completed_count = metrics.completed_count.saturating_add(1);
            metrics.completed_duration_ms_total = metrics
                .completed_duration_ms_total
                .saturating_add(elapsed_ms_u128);
            metrics.max_snapshot_age_ms = metrics.max_snapshot_age_ms.max(elapsed_ms);
            if elapsed_ms >= metrics.long_txn_threshold_ms {
                metrics.long_running_count = metrics.long_running_count.saturating_add(1);
            }
            metrics.active_first_read_at = None;
            metrics.active_first_write_at = None;
            metrics.active_read_ops = 0;
            metrics.active_write_ops = 0;
            metrics.active_savepoint_depth = 0;
            metrics.active_rollbacks = 0;
        }
        self.note_connection_transaction_finished();
    }

    fn note_connection_prepare_call(&self) {
        let metrics = self.pool_metrics.get();
        if let Some(metrics) = metrics {
            self._shared_mvcc_state
                .note_connection_prepare(metrics.as_ref());
        }
    }

    fn note_connection_statement_execution_count(&self, count: usize) {
        if count == 0 {
            return;
        }
        let metrics = self.pool_metrics.get();
        if let Some(metrics) = metrics {
            self._shared_mvcc_state
                .note_connection_statement_execution_count(metrics.as_ref(), count);
        }
    }

    fn note_connection_transaction_started(&self) {
        let metrics = self.pool_metrics.get();
        if let Some(metrics) = metrics {
            self._shared_mvcc_state
                .note_connection_transaction_started(metrics.as_ref());
        }
    }

    fn note_connection_transaction_finished(&self) {
        let metrics = self.pool_metrics.get();
        if let Some(metrics) = metrics {
            self._shared_mvcc_state
                .note_connection_transaction_finished(metrics.as_ref());
        }
    }

    #[cfg(feature = "diagnostic-pragmas")]
    fn connection_pool_stats_rows(&self) -> Vec<Row> {
        let snapshot = self._shared_mvcc_state.connection_pool_snapshot();
        let current_connection_id = self.pool_metrics.get().map(|metrics| metrics.connection_id);
        let current_connection = current_connection_id.and_then(|connection_id| {
            snapshot
                .connections
                .iter()
                .find(|entry| entry.lifecycle.connection_id == connection_id)
        });
        let to_i64 = |value: u64| i64::try_from(value).unwrap_or(i64::MAX);
        let to_i64_usize = |value: usize| i64::try_from(value).unwrap_or(i64::MAX);

        let mut rows = vec![
            Row {
                values: vec![
                    SqliteValue::Text("pool_size_estimate".into()),
                    SqliteValue::Integer(to_i64_usize(snapshot.open_connections)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("open_connections".into()),
                    SqliteValue::Integer(to_i64_usize(snapshot.open_connections)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("idle_connections".into()),
                    SqliteValue::Integer(to_i64_usize(snapshot.idle_connections)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("active_transactions".into()),
                    SqliteValue::Integer(to_i64_usize(snapshot.active_transactions)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("connection_age_max_ms".into()),
                    SqliteValue::Integer(to_i64(snapshot.connection_age_max_ms)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("idle_ms_max".into()),
                    SqliteValue::Integer(to_i64(snapshot.idle_ms_max)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("connect_events".into()),
                    SqliteValue::Integer(to_i64(snapshot.connect_events_total)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("disconnect_events".into()),
                    SqliteValue::Integer(to_i64(snapshot.disconnect_events_total)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("queries_executed_total".into()),
                    SqliteValue::Integer(to_i64(snapshot.queries_executed_total)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("prepare_calls_total".into()),
                    SqliteValue::Integer(to_i64(snapshot.prepare_calls_total)),
                ],
            },
            Row {
                values: vec![
                    SqliteValue::Text("transactions_started_total".into()),
                    SqliteValue::Integer(to_i64(snapshot.transactions_started_total)),
                ],
            },
        ];

        if let Some(current_connection) = current_connection {
            rows.extend([
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_id".into()),
                        SqliteValue::Integer(
                            i64::try_from(current_connection.lifecycle.connection_id)
                                .unwrap_or(i64::MAX),
                        ),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_age_ms".into()),
                        SqliteValue::Integer(to_i64(current_connection.lifecycle.age_ms)),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_idle_ms".into()),
                        SqliteValue::Integer(to_i64(current_connection.lifecycle.idle_ms)),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_queries_executed".into()),
                        SqliteValue::Integer(to_i64(current_connection.lifecycle.queries_executed)),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_prepare_calls".into()),
                        SqliteValue::Integer(to_i64(current_connection.lifecycle.prepare_calls)),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_transactions_started".into()),
                        SqliteValue::Integer(to_i64(current_connection.transactions_started)),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_open_transactions".into()),
                        SqliteValue::Integer(i64::from(
                            current_connection.lifecycle.open_transactions,
                        )),
                    ],
                },
                Row {
                    values: vec![
                        SqliteValue::Text("current_connection_active_snapshot_age_ms".into()),
                        current_connection
                            .lifecycle
                            .active_snapshot_age_ms
                            .map_or(SqliteValue::Null, |age| SqliteValue::Integer(to_i64(age))),
                    ],
                },
            ]);
        }

        rows
    }

    #[cfg(feature = "diagnostic-pragmas")]
    fn txn_metrics_rows(&self) -> Vec<Row> {
        let to_i64 = |value: u64| i64::try_from(value).unwrap_or(i64::MAX);
        let metrics = self.txn_lifecycle_metrics.borrow();
        let active_count = u64::from(metrics.active_started_at.is_some());
        let avg_duration_ms_u128 = if metrics.completed_count == 0 {
            0
        } else {
            metrics.completed_duration_ms_total / u128::from(metrics.completed_count)
        };
        let avg_duration_ms = u64::try_from(avg_duration_ms_u128).unwrap_or(u64::MAX);
        let snapshot_age_ms = metrics.current_snapshot_age_ms();
        let max_snapshot_age_ms = metrics.max_snapshot_age_ms.max(snapshot_age_ms);
        let first_read_ms = metrics.current_first_read_ms();
        let first_write_ms = metrics.current_first_write_ms();
        let active_long_running = u64::from(
            metrics.active_started_at.is_some() && snapshot_age_ms >= metrics.long_txn_threshold_ms,
        );
        let long_running_count = metrics
            .long_running_count
            .saturating_add(active_long_running);
        let entries = [
            ("active_count", active_count),
            ("avg_duration_ms", avg_duration_ms),
            ("long_running_count", long_running_count),
            ("max_snapshot_age_ms", max_snapshot_age_ms),
            ("first_read_ms", first_read_ms),
            ("first_write_ms", first_write_ms),
            ("read_ops", metrics.active_read_ops),
            ("write_ops", metrics.active_write_ops),
            ("savepoint_depth", metrics.active_savepoint_depth),
            ("rollback_count_active", metrics.active_rollbacks),
            ("rollback_count_total", metrics.rollback_count_total),
            ("long_txn_threshold_ms", metrics.long_txn_threshold_ms),
            (
                "advisor_large_read_ops_threshold",
                metrics.advisor_large_read_ops_threshold,
            ),
            (
                "advisor_savepoint_depth_threshold",
                metrics.advisor_savepoint_depth_threshold,
            ),
            (
                "advisor_rollback_ratio_percent",
                metrics.advisor_rollback_ratio_percent,
            ),
            ("completed_count", metrics.completed_count),
        ];
        entries
            .into_iter()
            .map(|(name, value)| Row {
                values: vec![
                    SqliteValue::Text(name.into()),
                    SqliteValue::Integer(to_i64(value)),
                ],
            })
            .collect()
    }

    #[cfg(feature = "diagnostic-pragmas")]
    fn txn_live_rows(&self) -> Vec<Row> {
        let to_i64 = |value: u64| i64::try_from(value).unwrap_or(i64::MAX);
        let (active_duration_ms, active_read_ops, active_write_ops) = {
            let metrics = self.txn_lifecycle_metrics.borrow();
            (
                metrics.current_snapshot_age_ms(),
                metrics.active_read_ops,
                metrics.active_write_ops,
            )
        };

        let session_id = *self.concurrent_session_id.borrow();
        if let Some(session_id) = session_id {
            let registry = lock_unpoisoned(&self.concurrent_registry);
            if let Some(handle) = registry.get(session_id) {
                let pages_read = u64::try_from(handle.read_set().len()).unwrap_or(u64::MAX);
                let pages_written =
                    u64::try_from(handle.write_set_pages().len()).unwrap_or(u64::MAX);
                return vec![Row {
                    values: vec![
                        SqliteValue::Integer(i64::try_from(session_id).unwrap_or(i64::MAX)),
                        SqliteValue::Integer(to_i64(active_duration_ms)),
                        SqliteValue::Integer(to_i64(pages_read)),
                        SqliteValue::Integer(to_i64(pages_written)),
                        SqliteValue::Integer(to_i64(active_duration_ms)),
                    ],
                }];
            }
        }

        if self.active_txn.borrow().is_some() {
            return vec![Row {
                values: vec![
                    SqliteValue::Integer(0),
                    SqliteValue::Integer(to_i64(active_duration_ms)),
                    SqliteValue::Integer(to_i64(active_read_ops)),
                    SqliteValue::Integer(to_i64(active_write_ops)),
                    SqliteValue::Integer(to_i64(active_duration_ms)),
                ],
            }];
        }

        Vec::new()
    }

