    impl Connection {
        pub(crate) fn open_in_memory() -> std::result::Result<Self, FrankenError> {
            Self::open(":memory:")
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct TxnAwareVtabSnapshot {
        rows: Vec<(i64, String)>,
        next_rowid: i64,
    }

    #[derive(Debug, Clone, Default)]
    struct TxnAwareTestVtab {
        rows: Vec<(i64, String)>,
        next_rowid: i64,
        txn_state: TransactionalVtabState<TxnAwareVtabSnapshot>,
        hook_log: Vec<String>,
        fail_sync: bool,
        fail_savepoint_at: Option<i32>,
        fail_rollback_to_at: Option<i32>,
    }

    #[derive(Debug, Clone, Default)]
    struct TxnAwareTestCursor {
        rows: Vec<(i64, String)>,
        pos: usize,
    }

    #[derive(Debug, Clone, Default)]
    struct SchemaAwareTestVtab;

    #[derive(Debug, Clone, Default)]
    struct SchemaAwareTestCursor {
        emitted: bool,
    }

    struct SchemaAwareTestFactory;

    impl TxnAwareTestVtab {
        fn snapshot_state(&self) -> TxnAwareVtabSnapshot {
            TxnAwareVtabSnapshot {
                rows: self.rows.clone(),
                next_rowid: self.next_rowid,
            }
        }

        fn restore_state(&mut self, snapshot: TxnAwareVtabSnapshot) {
            self.rows = snapshot.rows;
            self.next_rowid = snapshot.next_rowid;
        }

        fn record_hook(&mut self, hook: impl Into<String>) {
            self.hook_log.push(hook.into());
        }
    }

    fn with_txn_test_vtab<T>(
        conn: &Connection,
        table_name: &str,
        f: impl FnOnce(&mut TxnAwareTestVtab) -> T,
    ) -> T {
        let key = table_name.to_ascii_uppercase();
        let mut instances = conn.vtab_instances.borrow_mut();
        let instance = instances
            .get_mut(&key)
            .unwrap_or_else(|| panic!("missing live vtab instance {key}"));
        let vtab = instance
            .as_any_mut()
            .downcast_mut::<TxnAwareTestVtab>()
            .unwrap_or_else(|| panic!("live vtab {key} is not TxnAwareTestVtab"));
        f(vtab)
    }

    impl VirtualTable for TxnAwareTestVtab {
        type Cursor = TxnAwareTestCursor;

        fn connect(_cx: &Cx, _args: &[&str]) -> Result<Self> {
            Ok(Self {
                rows: Vec::new(),
                next_rowid: 1,
                txn_state: TransactionalVtabState::default(),
                hook_log: Vec::new(),
                fail_sync: false,
                fail_savepoint_at: None,
                fail_rollback_to_at: None,
            })
        }

        fn best_index(&self, _info: &mut VtabIndexInfo) -> Result<()> {
            Ok(())
        }

        fn open(&self) -> Result<Self::Cursor> {
            Ok(TxnAwareTestCursor {
                rows: self.rows.clone(),
                pos: 0,
            })
        }

        fn update(&mut self, _cx: &Cx, args: &[SqliteValue]) -> Result<Option<i64>> {
            self.record_hook("update");
            if args.is_empty() {
                return Err(FrankenError::Internal(
                    "txn-aware test vtab received no args".to_owned(),
                ));
            }
            if args.len() == 1 && !args[0].is_null() {
                let rowid = args[0].to_integer();
                self.rows.retain(|(existing, _)| *existing != rowid);
                return Ok(None);
            }
            let value = args.get(2).map(SqliteValue::to_text).ok_or_else(|| {
                FrankenError::Internal("txn-aware test vtab missing value".to_owned())
            })?;
            if value.eq_ignore_ascii_case("boom") {
                return Err(FrankenError::Internal(
                    "txn-aware test vtab forced failure".to_owned(),
                ));
            }
            let rowid = args
                .get(1)
                .and_then(SqliteValue::as_integer)
                .unwrap_or_else(|| {
                    let next = self.next_rowid;
                    self.next_rowid += 1;
                    next
                });
            self.next_rowid = self.next_rowid.max(rowid.saturating_add(1));
            self.rows.push((rowid, value));
            Ok(Some(rowid))
        }

        fn begin(&mut self, _cx: &Cx) -> Result<()> {
            self.record_hook("begin");
            self.txn_state.begin(self.snapshot_state());
            Ok(())
        }

        fn sync_txn(&mut self, _cx: &Cx) -> Result<()> {
            self.record_hook("sync");
            if self.fail_sync {
                return Err(FrankenError::Internal(
                    "txn-aware test vtab forced sync failure".to_owned(),
                ));
            }
            Ok(())
        }

        fn commit(&mut self, _cx: &Cx) -> Result<()> {
            self.record_hook("commit");
            self.txn_state.commit();
            Ok(())
        }

        fn rollback(&mut self, _cx: &Cx) -> Result<()> {
            self.record_hook("rollback");
            if let Some(snapshot) = self.txn_state.rollback() {
                self.restore_state(snapshot);
            }
            Ok(())
        }

        fn savepoint(&mut self, _cx: &Cx, n: i32) -> Result<()> {
            self.record_hook(format!("savepoint:{n}"));
            if self.fail_savepoint_at == Some(n) {
                return Err(FrankenError::Internal(format!(
                    "txn-aware test vtab forced savepoint failure at level {n}",
                )));
            }
            self.txn_state.savepoint(n, self.snapshot_state());
            Ok(())
        }

        fn release(&mut self, _cx: &Cx, n: i32) -> Result<()> {
            self.record_hook(format!("release:{n}"));
            self.txn_state.release(n);
            Ok(())
        }

        fn rollback_to(&mut self, _cx: &Cx, n: i32) -> Result<()> {
            self.record_hook(format!("rollback_to:{n}"));
            if self.fail_rollback_to_at == Some(n) {
                return Err(FrankenError::Internal(format!(
                    "txn-aware test vtab forced rollback_to failure at level {n}",
                )));
            }
            if let Some(snapshot) = self.txn_state.rollback_to(n) {
                self.restore_state(snapshot);
            }
            Ok(())
        }

        fn destroy(&mut self, _cx: &Cx) -> Result<()> {
            self.record_hook("destroy");
            Ok(())
        }
    }

    impl VirtualTableCursor for TxnAwareTestCursor {
        fn filter(
            &mut self,
            _cx: &Cx,
            _idx_num: i32,
            _idx_str: Option<&str>,
            _args: &[SqliteValue],
        ) -> Result<()> {
            self.pos = 0;
            Ok(())
        }

        fn next(&mut self, _cx: &Cx) -> Result<()> {
            self.pos = self.pos.saturating_add(1);
            Ok(())
        }

        fn eof(&self) -> bool {
            self.pos >= self.rows.len()
        }

        fn column(&self, ctx: &mut VtabColumnContext, col: i32) -> Result<()> {
            let Some((_, value)) = self.rows.get(self.pos) else {
                ctx.set_value(SqliteValue::Null);
                return Ok(());
            };
            if col == 0 {
                ctx.set_value(SqliteValue::Text(value.clone().into()));
            } else {
                ctx.set_value(SqliteValue::Null);
            }
            Ok(())
        }

        fn rowid(&self) -> Result<i64> {
            Ok(self.rows.get(self.pos).map_or(0, |(rowid, _)| *rowid))
        }
    }

    impl VirtualTable for SchemaAwareTestVtab {
        type Cursor = SchemaAwareTestCursor;

        fn connect(_cx: &Cx, _args: &[&str]) -> Result<Self> {
            Ok(Self)
        }

        fn best_index(&self, info: &mut VtabIndexInfo) -> Result<()> {
            info.estimated_cost = 1.0;
            info.estimated_rows = 1;
            Ok(())
        }

        fn open(&self) -> Result<Self::Cursor> {
            Ok(SchemaAwareTestCursor::default())
        }
    }

    impl VirtualTableCursor for SchemaAwareTestCursor {
        fn filter(
            &mut self,
            _cx: &Cx,
            _idx_num: i32,
            _idx_str: Option<&str>,
            _args: &[SqliteValue],
        ) -> Result<()> {
            self.emitted = false;
            Ok(())
        }

        fn next(&mut self, _cx: &Cx) -> Result<()> {
            self.emitted = true;
            Ok(())
        }

        fn eof(&self) -> bool {
            self.emitted
        }

        fn column(&self, ctx: &mut VtabColumnContext, col: i32) -> Result<()> {
            if self.eof() {
                ctx.set_value(SqliteValue::Null);
                return Ok(());
            }

            match col {
                0 => ctx.set_value(SqliteValue::Text("alpha".into())),
                1 => ctx.set_value(SqliteValue::Integer(7)),
                _ => ctx.set_value(SqliteValue::Null),
            }
            Ok(())
        }

        fn rowid(&self) -> Result<i64> {
            Ok(if self.eof() { 0 } else { 1 })
        }
    }

    impl VtabModuleFactory for SchemaAwareTestFactory {
        fn create(&self, cx: &Cx, args: &[&str]) -> Result<Box<dyn ErasedVtabInstance>> {
            let vtab = SchemaAwareTestVtab::create(cx, args)?;
            Ok(Box::new(vtab))
        }

        fn connect(&self, cx: &Cx, args: &[&str]) -> Result<Box<dyn ErasedVtabInstance>> {
            let vtab = SchemaAwareTestVtab::connect(cx, args)?;
            Ok(Box::new(vtab))
        }

        fn column_info(&self, _args: &[&str]) -> Vec<(String, char)> {
            vec![("label".to_owned(), 'T'), ("score".to_owned(), 'I')]
        }
    }

    #[test]
    fn test_implicit_autoindex_classification_requires_provenance_and_canonical_mapping() {
        assert!(is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_1",
            "link_table",
            None
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_1",
            "link_table",
            Some("CREATE UNIQUE INDEX explicit_name ON link_table(a,b)")
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_v23_1",
            "link_table",
            None
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_other_table_1",
            "link_table",
            None
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_0",
            "link_table",
            None
        ));
        for noncanonical in [
            "sqlite_autoindex_link_table_01",
            "sqlite_autoindex_link_table_+1",
            "sqlite_autoindex_link_table_١",
        ] {
            assert!(
                !is_implicit_autoindex_entry(noncanonical, "link_table", None),
                "{noncanonical} must not be classified as a canonical implicit autoindex"
            );
        }
        let overflowing = format!("sqlite_autoindex_link_table_{}0", usize::MAX);
        assert!(!is_implicit_autoindex_entry(
            &overflowing,
            "link_table",
            None
        ));
    }

