    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    #[test]
    fn test_spawn_write_coordinator_task_drains_on_last_connection_close() {
        use asupersync::runtime::RuntimeBuilder;
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::mpsc::channel;

        let runtime = RuntimeBuilder::new()
            .worker_threads(1)
            .build()
            .expect("runtime build");
        let started = Arc::new(AtomicBool::new(false));
        let cancelled = Arc::new(AtomicBool::new(false));
        let finished = Arc::new(AtomicBool::new(false));
        let (started_tx, started_rx) = channel();
        let (finished_tx, finished_rx) = channel();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("manual-write-coordinator-task.db");
        let db_path = db_path.to_string_lossy().into_owned();

        let conn = runtime.block_on(async {
            // Create RuntimeContext inside block_on so it captures the
            // active asupersync runtime handle.
            let runtime_context = Arc::new(RuntimeContext::new(RuntimeConfig {
                worker_threads: 1,
                io_poll_strategy: IoPollStrategy::Auto,
            }));
            let conn = Connection::open_with_env(
                &db_path,
                ConnectionEnv::new(Arc::clone(&runtime_context)),
            )
            .expect("connection should open");

            conn._shared_mvcc_state
                .spawn_write_coordinator_task({
                    let started = Arc::clone(&started);
                    let cancelled = Arc::clone(&cancelled);
                    let finished = Arc::clone(&finished);
                    move |task_cx| async move {
                        started.store(true, Ordering::SeqCst);
                        started_tx.send(()).expect("start signal should send");
                        while task_cx.checkpoint().is_ok() {
                            std::hint::spin_loop();
                        }
                        cancelled.store(task_cx.is_cancel_requested(), Ordering::SeqCst);
                        finished.store(true, Ordering::SeqCst);
                        finished_tx.send(()).expect("finish signal should send");
                    }
                })
                .expect("write coordinator task should spawn");

            started_rx
                .recv_timeout(std::time::Duration::from_secs(1))
                .expect("task should start before shutdown");
            conn
        });

        drop(conn);
        finished_rx
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("task should finish during connection shutdown");
        assert!(started.load(Ordering::SeqCst));
        assert!(cancelled.load(Ordering::SeqCst));
        assert!(finished.load(Ordering::SeqCst));
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    #[test]
    fn test_open_with_env_starts_write_coordinator_service_once_per_shared_database() {
        use asupersync::runtime::RuntimeBuilder;

        let runtime = RuntimeBuilder::new()
            .worker_threads(1)
            .build()
            .expect("runtime build");
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("write-coordinator-service.db");
        let db_path = db_path.to_string_lossy().into_owned();

        let (conn1, conn2, shared) = runtime.block_on(async {
            let runtime_context = Arc::new(RuntimeContext::new(RuntimeConfig {
                worker_threads: 1,
                io_poll_strategy: IoPollStrategy::Auto,
            }));
            let conn1 = Connection::open_with_env(
                &db_path,
                ConnectionEnv::new(Arc::clone(&runtime_context)),
            )
            .expect("first connection should open");
            let conn2 = Connection::open_with_env(
                &db_path,
                ConnectionEnv::new(Arc::clone(&runtime_context)),
            )
            .expect("second connection should open");
            let shared = Arc::clone(&conn1._shared_mvcc_state);

            {
                let state = lock_unpoisoned(&shared.runtime_state);
                let region = write_coordinator_region_for_test(&state);
                assert!(!state.write_coordinator_service_starting);
                assert!(state.write_coordinator_service_running);
                assert_eq!(state.write_coordinator_service_launch_count, 1);
                assert_eq!(state.regions.active_tasks(region), 1);
            }

            (conn1, conn2, shared)
        });

        drop(conn1);
        {
            let state = lock_unpoisoned(&shared.runtime_state);
            let region = write_coordinator_region_for_test(&state);
            assert!(!state.write_coordinator_service_starting);
            assert!(state.write_coordinator_service_running);
            assert_eq!(state.write_coordinator_service_launch_count, 1);
            assert_eq!(state.regions.active_tasks(region), 1);
        }

        drop(conn2);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        loop {
            let (running, active_tasks) = {
                let state = lock_unpoisoned(&shared.runtime_state);
                let region = write_coordinator_region_for_test(&state);
                (
                    state.write_coordinator_service_running,
                    state.regions.active_tasks(region),
                )
            };
            if !running && active_tasks == 0 {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "write coordinator service should stop after last connection close"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    #[test]
    fn test_dormant_shared_state_remains_runtime_scoped_when_active_runtime_opens_later() {
        let _serial = super::fsqlite_core_test_serializer();
        use asupersync::runtime::RuntimeBuilder;

        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("write-coordinator-dormant.db");
        let db_path = db_path.to_string_lossy().into_owned();
        // First connection opens without a native runtime — service stays dormant.
        let runtime_context_dormant = Arc::new(RuntimeContext::new(RuntimeConfig {
            worker_threads: 1,
            io_poll_strategy: IoPollStrategy::Auto,
        }));
        let conn1 = Connection::open_with_env(
            &db_path,
            ConnectionEnv::new(Arc::clone(&runtime_context_dormant)),
        )
        .expect("first connection should open");
        let shared = Arc::clone(&conn1._shared_mvcc_state);

        {
            let state = lock_unpoisoned(&shared.runtime_state);
            let region = write_coordinator_region_for_test(&state);
            assert!(!state.write_coordinator_service_starting);
            assert!(!state.write_coordinator_service_running);
            assert_eq!(state.write_coordinator_service_launch_count, 0);
            assert_eq!(state.regions.active_tasks(region), 0);
        }

        let runtime = RuntimeBuilder::new()
            .worker_threads(1)
            .build()
            .expect("runtime build");
        // Create RuntimeContext inside block_on so it captures the native handle.
        let runtime_context = runtime.block_on(async {
            Arc::new(RuntimeContext::new(RuntimeConfig {
                worker_threads: 1,
                io_poll_strategy: IoPollStrategy::Auto,
            }))
        });
        let conn2 = runtime.block_on(async {
            Connection::open_with_env(&db_path, ConnectionEnv::new(Arc::clone(&runtime_context)))
                .expect("second connection should open")
        });
        let active_shared = Arc::clone(&conn2._shared_mvcc_state);

        assert!(
            !Arc::ptr_eq(&shared, &active_shared),
            "same path with distinct explicit runtimes must keep runtime-scoped shared state"
        );

        {
            let state = lock_unpoisoned(&shared.runtime_state);
            let region = write_coordinator_region_for_test(&state);
            assert!(!state.write_coordinator_service_starting);
            assert!(!state.write_coordinator_service_running);
            assert_eq!(state.write_coordinator_service_launch_count, 0);
            assert_eq!(state.regions.active_tasks(region), 0);
        }

        {
            let state = lock_unpoisoned(&active_shared.runtime_state);
            let region = write_coordinator_region_for_test(&state);
            assert!(!state.write_coordinator_service_starting);
            assert!(state.write_coordinator_service_running);
            assert_eq!(state.write_coordinator_service_launch_count, 1);
            assert_eq!(state.regions.active_tasks(region), 1);
        }

        drop(conn2);
        drop(conn1);
    }

