    fn live_vtab_instance_ptr(conn: &Connection, table_name: &str) -> *const () {
        let key = table_name.to_ascii_uppercase();
        let instances = conn.vtab_instances.borrow();
        let instance = instances
            .get(&key)
            .unwrap_or_else(|| panic!("missing live vtab instance {key}"));
        let ptr: *const dyn ErasedVtabInstance = &**instance;
        ptr.cast::<()>()
    }

