    #[test]
    fn test_connection_op_cx_inherits_trace_id_and_allocates_decision_id() {
        let conn = Connection::open(":memory:").unwrap();
        let root = conn.root_cx().clone();
        let op_cx = conn.op_cx().unwrap();

        assert_eq!(
            op_cx.trace_id(),
            root.trace_id(),
            "operation contexts should inherit the connection trace id"
        );
        assert_eq!(
            op_cx.policy_id(),
            root.policy_id(),
            "operation contexts should preserve policy lineage"
        );
        assert_ne!(
            op_cx.decision_id(),
            0,
            "operation contexts should allocate a fresh decision id"
        );
    }

    #[test]
    fn test_connection_root_cx_has_eprocess_oracle_attached() {
        let conn = Connection::open(":memory:").unwrap();
        assert!(conn.root_cx().checkpoint().is_ok());
        let before = conn.eprocess_oracle.snapshot().observations;
        // The oracle only refreshes every 64 statements, so execute enough
        // queries to guarantee at least one refresh cycle.
        for _ in 0..65 {
            let _ = conn.query("SELECT 1").unwrap();
        }
        let after = conn.eprocess_oracle.snapshot().observations;
        assert!(
            after > before,
            "per-operation Cx derivation should feed e-process observations"
        );
    }

