    #[test]
    fn test_cass_orphan_not_exists_survives_subquery_rewrite_as_correlated() {
        let conn = Connection::open(":memory:").unwrap();
        let statement = conn
            .cached_parse_single(
                "SELECT message_id FROM message_metrics \
                 WHERE NOT EXISTS (\
                     SELECT 1 FROM messages \
                     WHERE messages.id = message_metrics.message_id\
                 ) \
                 ORDER BY message_id;",
            )
            .unwrap();
        let Statement::Select(select) = statement.as_ref() else {
            panic!("expected SELECT");
        };

        assert!(
            super::select_has_correlated_exists_in_where(select),
            "cass orphan cleanup NOT EXISTS must be detected as correlated"
        );

        let rewritten = conn
            .rewrite_subquery_statement(statement.as_ref(), None)
            .unwrap();
        let Statement::Select(rewritten_select) = rewritten.as_ref() else {
            panic!("expected rewritten SELECT");
        };
        assert!(
            super::select_has_correlated_exists_in_where(rewritten_select),
            "eager subquery rewrite must leave correlated NOT EXISTS intact"
        );
    }

