        conn.execute("CREATE TABLE config(key TEXT NOT NULL, value TEXT NOT NULL);")
            .unwrap();
        conn.execute("CREATE INDEX idx_config_key ON config(key);")
            .unwrap();
        conn.execute("CREATE TABLE metadata(key TEXT NOT NULL, value TEXT NOT NULL);")
            .unwrap();
        conn.execute("CREATE INDEX idx_metadata_key ON metadata(key);")
            .unwrap();

        // Set config (as rebuild_database_family does)
