    #[test]
    fn test_compound_select_mismatched_column_count_rejected() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE a (x INTEGER, y INTEGER);")
            .unwrap();
        conn.execute("INSERT INTO a VALUES (1, 2);").unwrap();

        let query_error = conn
            .query("SELECT x FROM a UNION SELECT x, y FROM a;")
            .expect_err("mismatched UNION arm widths must fail");
        assert!(
            matches!(query_error, FrankenError::ParseError { ref detail, .. } if detail.contains("same number of result columns")),
            "unexpected query error: {query_error}"
        );

        let prepare_error = match conn.prepare("SELECT x FROM a INTERSECT SELECT x, y FROM a;") {
            Ok(_) => panic!("prepare must reject mismatched compound arm widths"),
            Err(error) => error,
        };
        assert!(
            matches!(prepare_error, FrankenError::ParseError { ref detail, .. } if detail.contains("same number of result columns")),
            "unexpected prepare error: {prepare_error}"
        );

        let explain_error = match conn.prepare("EXPLAIN SELECT x FROM a EXCEPT SELECT x, y FROM a;")
        {
            Ok(_) => panic!("EXPLAIN prepare must reject mismatched compound arm widths"),
            Err(error) => error,
        };
        assert!(
            matches!(explain_error, FrankenError::ParseError { ref detail, .. } if detail.contains("same number of result columns")),
            "unexpected EXPLAIN error: {explain_error}"
        );
    }

