    #[test]
    fn test_prepared_statement_with_cte_preserves_unrelated_reuse_caches() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE cache_probe (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO cache_probe VALUES (1, 'alpha');")
            .unwrap();

        let cached_sql = "SELECT val FROM cache_probe WHERE id = 1;";
        let _prepared = conn.prepare(cached_sql).unwrap();
        let cached_key = conn.prepared_cache_key(cached_sql);
        let cached_statement = super::parse_statements(cached_sql).unwrap().remove(0);
        let Statement::Select(cached_select) = &cached_statement else {
            panic!("expected SELECT cache probe statement");
        };
        let compiled_key = Connection::sql_hash(cached_sql);
        conn.compile_with_cache(compiled_key, cached_sql, |inner_conn| {
            inner_conn.compile_table_select(cached_select)
        })
        .unwrap();
        assert!(
            conn.lookup_prepared_cache(cached_key, cached_sql).is_some(),
            "priming query should populate prepared cache"
        );
        assert!(
            conn.lookup_compiled_cache(compiled_key, cached_sql)
                .is_some(),
            "priming query should populate compiled cache"
        );

        let cte_stmt = conn
            .prepare("WITH base(val) AS (SELECT 7) SELECT val FROM base;")
            .unwrap();
        let cte_rows = cte_stmt.query().unwrap();
        assert_eq!(cte_rows.len(), 1);
        assert_eq!(row_values(&cte_rows[0]), vec![SqliteValue::Integer(7)]);

        assert!(
            conn.lookup_prepared_cache(cached_key, cached_sql).is_some(),
            "executing a CTE should not clear unrelated prepared cache entries"
        );
        assert!(
            conn.lookup_compiled_cache(compiled_key, cached_sql)
                .is_some(),
            "executing a CTE should not clear unrelated compiled cache entries"
        );
    }

