    #[test]
    fn test_file_backed_runtime_inputs_evaluate_added_column_defaults_without_recursion() {
        let tmp = tempfile::tempdir().unwrap();
        let db_path = tmp.path().join("prep-defaults-file.db");
        let conn = Connection::open(db_path.to_string_lossy().to_string()).unwrap();
        conn.execute("CREATE TABLE prep_defaults_file (id INTEGER PRIMARY KEY);")
            .unwrap();
        conn.execute("INSERT INTO prep_defaults_file(id) VALUES (1);")
            .unwrap();
        conn.execute("ALTER TABLE prep_defaults_file ADD COLUMN tags TEXT DEFAULT '[]';")
            .unwrap();

        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case("prep_defaults_file"))
            .map(|table| table.root_page)
            .expect("prep_defaults_file root page should exist");

        let read_path = conn.table_execution_runtime_inputs(
            crate::connection::TableExecutionRuntimeRequirements::read_path(),
        );
        assert_eq!(
            read_path.column_defaults_by_root_page.get(&root_page),
            Some(&vec![None, Some(SqliteValue::Text("[]".into()))]),
            "file-backed read paths should build added-column defaults without recursion"
        );

        let rows = conn
            .query("SELECT tags FROM prep_defaults_file WHERE id = 1;")
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(row_values(&rows[0]), vec![SqliteValue::Text("[]".into())]);
    }

    #[test]
    fn test_file_backed_compound_select_with_added_column_defaults_uses_direct_default_eval() {
        let tmp = tempfile::tempdir().unwrap();
        let db_path = tmp.path().join("compound-defaults-file.db");
        let conn = Connection::open(db_path.to_string_lossy().to_string()).unwrap();
        conn.execute(
            "CREATE TABLE skill_cache (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                description TEXT,
                category TEXT,
                is_jeffreys INTEGER DEFAULT 0,
                compatibility_tags TEXT DEFAULT '[]',
                version_number INTEGER DEFAULT 1
            );",
        )
        .unwrap();
        conn.execute(
            "CREATE TABLE installed_skills (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                description TEXT,
                category TEXT,
                version_number INTEGER DEFAULT 1
            );",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO installed_skills (id, name, description, category, version_number)
             VALUES ('skill-1', 'Example Skill', 'desc', 'utility', 7);",
        )
        .unwrap();
        conn.execute("ALTER TABLE installed_skills ADD COLUMN tags TEXT DEFAULT '[]';")
            .unwrap();

        let row = conn
            .query_row(
                "SELECT id, name, description, category, is_jeffreys, compatibility_tags, COALESCE(version_number, 0) AS version
                 FROM (
                     SELECT id, name, description, category, is_jeffreys, compatibility_tags, version_number
                     FROM skill_cache
                     WHERE id = 'skill-1'
                     UNION ALL
                     SELECT id, name, description, category, 0 AS is_jeffreys, '[]' AS compatibility_tags, version_number
                     FROM installed_skills
                     WHERE id = 'skill-1' AND id NOT IN (SELECT id FROM skill_cache)
                 )
                 LIMIT 1;",
            )
            .unwrap();

        assert_eq!(
            row.values(),
            &[
                SqliteValue::Text("skill-1".into()),
                SqliteValue::Text("Example Skill".into()),
                SqliteValue::Text("desc".into()),
                SqliteValue::Text("utility".into()),
                SqliteValue::Integer(0),
                SqliteValue::Text("[]".into()),
                SqliteValue::Integer(7),
            ]
        );
    }

