        let direct = conn
            .query("SELECT DISTINCT v FROM t ORDER BY v LIMIT 2;")
            .unwrap();
        assert_eq!(direct.len(), 2);

        let stmt = conn
            .prepare("SELECT DISTINCT v FROM t ORDER BY v LIMIT 2;")
            .unwrap();
        let rows = stmt.query().unwrap();
