    #[test]
    fn test_prepared_indexed_two_table_join_uses_query_fast_path() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT);")
            .unwrap();
        conn.execute(
            "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);",
        )
        .unwrap();
        conn.execute("CREATE INDEX idx_orders_cust ON orders(customer_id);")
            .unwrap();
        conn.execute(
            "INSERT INTO customers VALUES
                (1, 'Alice'),
                (2, 'Bob'),
                (3, 'Carol');",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO orders VALUES
                (1, 1, 100),
                (2, 1, 200),
                (3, 2, 50),
                (4, 9, 999);",
        )
        .unwrap();

        let inner = conn
            .prepare(
                "SELECT c.name, o.amount \
                 FROM customers c JOIN orders o ON o.customer_id = c.id;",
            )
            .unwrap();
        assert!(matches!(
            inner.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleIndexedTwoTableJoin {
                join_kind: JoinKind::Inner,
                ..
            })
        ));

        super::reset_hot_path_profile();
        let inner_rows = inner.query().unwrap();
        assert_eq!(
            inner_rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Text("Alice".into()), SqliteValue::Integer(100)],
                vec![SqliteValue::Text("Alice".into()), SqliteValue::Integer(200)],
                vec![SqliteValue::Text("Bob".into()), SqliteValue::Integer(50)],
            ]
        );
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.parser.fast_path_executions, 1);
        assert_eq!(profile.parser.slow_path_executions, 0);

        let left = conn
            .prepare(
                "SELECT c.name, o.amount \
                 FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;",
            )
            .unwrap();
        assert!(matches!(
            left.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleIndexedTwoTableJoin {
                join_kind: JoinKind::Left,
                ..
            })
        ));

        let initial_left_rows = left.query().unwrap();
        assert_eq!(
            initial_left_rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Text("Alice".into()), SqliteValue::Integer(100)],
                vec![SqliteValue::Text("Alice".into()), SqliteValue::Integer(200)],
                vec![SqliteValue::Text("Bob".into()), SqliteValue::Integer(50)],
                vec![SqliteValue::Text("Carol".into()), SqliteValue::Null],
            ]
        );

        conn.execute("INSERT INTO orders VALUES (5, 3, 70);")
            .unwrap();
        let refreshed_left_rows = left.query().unwrap();
        assert_eq!(
            refreshed_left_rows
                .iter()
                .map(row_values)
                .collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Text("Alice".into()), SqliteValue::Integer(100)],
                vec![SqliteValue::Text("Alice".into()), SqliteValue::Integer(200)],
                vec![SqliteValue::Text("Bob".into()), SqliteValue::Integer(50)],
                vec![SqliteValue::Text("Carol".into()), SqliteValue::Integer(70)],
            ]
        );
    }

