    #[test]
    fn test_prepared_table_program_scalar_functions_keep_registry_and_match_rusqlite() {
        let fconn = Connection::open(":memory:").unwrap();
        let rconn = rusqlite::Connection::open_in_memory().unwrap();

        for sql in [
            "CREATE TABLE prep_func_registry (id INTEGER PRIMARY KEY, name TEXT, nickname TEXT);",
            "INSERT INTO prep_func_registry VALUES (1, 'alpha', NULL), (2, 'beta', 'bee');",
        ] {
            fconn.execute(sql).unwrap();
            rconn.execute_batch(sql).unwrap();
        }

        let sql = "SELECT upper(name), length(name), coalesce(nickname, 'missing') \
             FROM prep_func_registry WHERE id = ?1";
        let stmt = fconn.prepare(sql).unwrap();
        assert!(
            stmt.db.is_some(),
            "table-backed prepared SELECT should compile to a reusable table program"
        );
        assert!(
            stmt.func_registry.is_some(),
            "prepared table programs must carry a function registry for scalar execution"
        );

        let row = stmt.query_with_params(&[SqliteValue::Integer(2)]).unwrap();
        let expected: (String, i64, String) = rconn
            .query_row(sql, rusqlite::params![2_i64], |row| {
                Ok((row.get(0)?, row.get(1)?, row.get(2)?))
            })
            .unwrap();
        assert_eq!(row.len(), 1);
        assert_eq!(
            row[0].values(),
            &[
                SqliteValue::Text(expected.0.into()),
                SqliteValue::Integer(expected.1),
                SqliteValue::Text(expected.2.into()),
            ]
        );
    }

    #[test]
    fn test_prepared_count_star_query_row_uses_fast_path_and_tracks_write_through_rows() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_count_runtime (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_count_runtime VALUES (1, 'alpha'), (2, 'beta');")
            .unwrap();

        let stmt = conn
            .prepare("SELECT COUNT(*) FROM prep_count_runtime;")
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleCountStar { .. })
        ));

        super::reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(2)));

        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.parser.fast_path_executions, 1,
            "prepared COUNT(*) should count as exactly one fast-path execution: {profile:?}"
        );
        assert_eq!(
            profile.parser.slow_path_executions, 0,
            "prepared COUNT(*) should not fall back to the slow path: {profile:?}"
        );
        assert_eq!(profile.direct_count_star_query_row_hits, 1);
        assert_eq!(profile.direct_rowid_lookup_query_row_hits, 0);
        assert_eq!(profile.direct_count_star_rowid_range_query_row_hits, 0);

        conn.execute("INSERT INTO prep_count_runtime VALUES (3, 'gamma');")
            .unwrap();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(3)));

        conn.execute("DELETE FROM prep_count_runtime WHERE id = 2;")
            .unwrap();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(2)));
    }

    #[test]
    fn test_clean_memory_prepared_count_star_skips_read_boundary_after_explicit_writes() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE clean_memory_count (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                score INTEGER NOT NULL
            );",
        )
        .unwrap();
        conn.execute("BEGIN").unwrap();
        for id in 0..32_i64 {
            conn.execute_with_params(
                "INSERT INTO clean_memory_count VALUES (?1, ('name_' || ?1), (?1 * 7));",
                &[SqliteValue::Integer(id)],
            )
            .unwrap();
        }
        conn.execute("COMMIT").unwrap();
        conn.execute("CREATE INDEX idx_clean_memory_count_name ON clean_memory_count(name);")
            .unwrap();
        assert!(
            conn.retained_autocommit_txn.borrow().is_none(),
            "explicit setup plus index creation should leave a clean autocommit memory image"
        );

        let stmt = conn
            .prepare("SELECT COUNT(*) FROM clean_memory_count;")
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleCountStar { .. })
        ));

        super::reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(32)));
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.direct_count_star_query_row_hits, 1);
        assert_eq!(
            profile.begin_setup_time_ns, 0,
            "clean memory COUNT(*) query_row should not open an autocommit read transaction: {profile:?}"
        );

        super::reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(32)));
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.direct_count_star_query_row_hits, 1);
        assert_eq!(
            profile.memdb_refresh_count, 0,
            "warm cached write transaction mirror should not reload rows before COUNT(*): {profile:?}"
        );

        super::reset_hot_path_profile();
        let rows = stmt.query().unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].get(0), Some(&SqliteValue::Integer(32)));
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.begin_setup_time_ns, 0,
            "clean memory COUNT(*) query should not open an autocommit read transaction: {profile:?}"
        );
        assert_eq!(
            profile.parser.slow_path_executions, 0,
            "clean memory COUNT(*) should remain on the fast path: {profile:?}"
        );
    }

    #[test]
    fn test_clean_memory_prepared_count_star_caches_storage_count_when_memdb_rows_are_lazy() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA fsqlite_capture_time_travel_snapshots=false;")
            .unwrap();
        conn.execute(
            "CREATE TABLE clean_memory_count_storage_cache (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                score INTEGER NOT NULL
            );",
        )
        .unwrap();
        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| {
                table
                    .name
                    .eq_ignore_ascii_case("clean_memory_count_storage_cache")
            })
            .map(|table| table.root_page)
            .expect("test table root page");
        let insert = conn
            .prepare(
                "INSERT INTO clean_memory_count_storage_cache \
                 VALUES (?1, ('name_' || ?1), (?1 * 7));",
            )
            .unwrap();
        let expected_count = super::PREPARED_DIRECT_INSERT_PENDING_MEMDB_UPSERT_LIMIT as i64 + 1;

        conn.execute("BEGIN;").unwrap();
        for id in 1..=expected_count {
            let affected = conn
                .execute_prepared_with_params(&insert, &[SqliteValue::Integer(id)])
                .unwrap();
            assert_eq!(affected, 1);
        }
        conn.execute("COMMIT;").unwrap();
        assert!(
            !conn.memdb_storage_count_shortcuts_safe.get(),
            "snapshot-free benchmark setup should leave the MemDatabase row mirror lazy"
        );
        assert!(
            conn.storage_count_cache.borrow().is_empty(),
            "the storage count cache should seed lazily from the first COUNT(*)"
        );

        let count = conn
            .prepare("SELECT COUNT(*) FROM clean_memory_count_storage_cache;")
            .unwrap();
        assert!(matches!(
            count.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleCountStar { .. })
        ));
        conn.memdb_storage_count_shortcuts_safe.set(false);

        super::reset_hot_path_profile();
        let row = count.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(expected_count)));
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.direct_count_star_query_row_hits, 1,
            "lazy committed COUNT(*) should still use the direct query_row path: {profile:?}"
        );
        assert_eq!(
            conn.storage_count_cache
                .borrow()
                .get(&root_page)
                .map(|entry| entry.count),
            Some(expected_count),
            "first COUNT(*) should seed the committed storage count cache"
        );
        assert!(
            !conn.memdb_storage_count_shortcuts_safe.get(),
            "COUNT(*) should avoid a full MemDatabase row reload when the storage count cache is enough"
        );

        super::reset_hot_path_profile();
        let row = count.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(expected_count)));
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.direct_count_star_query_row_hits, 1,
            "warm COUNT(*) should stay on the direct cached count path: {profile:?}"
        );
        assert_eq!(
            profile.begin_setup_time_ns, 0,
            "warm storage-count cache hits should not open an autocommit read transaction: {profile:?}"
        );
    }

