    #[test]
    fn test_explicit_pk_unique_index_counts_table_vs_index_vs_sql() {
        const ROW_COUNT: i64 = 2_048;
        let _guard = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("explicit_pk_unique_index_count_probe.db");
        let conn = Connection::open(db_path.to_str().unwrap()).unwrap();
        conn.execute(
            "CREATE TABLE bench (
                id INTEGER PRIMARY KEY,
                name TEXT,
                email TEXT,
                score INTEGER,
                created TEXT
            );",
        )
        .unwrap();
        conn.execute("CREATE UNIQUE INDEX idx_bench_email_unique ON bench(email);")
            .unwrap();

        let (table_root_page, index_root_page) = {
            let schema = conn.schema.borrow();
            let table = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("bench"))
                .expect("bench table should exist");
            let index_root_page = table
                .indexes
                .iter()
                .find(|index| index.name.eq_ignore_ascii_case("idx_bench_email_unique"))
                .map(|index| index.root_page)
                .expect("unique email index should exist");
            (table.root_page, index_root_page)
        };

        let insert = conn
            .prepare(
                "INSERT INTO bench VALUES (?1, ('name_' || ?1), ('user_' || ?1 || '@test.com'), (?1 * 7), ('2026-01-' || ((?1 % 28) + 1)))",
            )
            .unwrap();

        for i in 0..ROW_COUNT {
            conn.execute_prepared_with_params(&insert, &[SqliteValue::Integer(i)])
                .unwrap();
        }

        assert!(
            !conn.memdb_storage_count_shortcuts_safe.get(),
            "file-backed diagnostic expects SQL COUNT(*) to avoid the MemDB table-row shortcut"
        );

        let read_root_count = |conn: &Connection, root_page: i32, is_table: bool| -> i64 {
            let cx = Cx::new();
            conn.invalidate_cached_write_txn(&cx);
            conn.invalidate_cached_read_snapshot(&cx);
            let mut txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                .unwrap();
            let mut cursor = Connection::new_pager_btree_cursor(
                &cx,
                &mut txn,
                PageNumber::new(u32::try_from(root_page).expect("root page fits in u32"))
                    .expect("root page should be valid"),
                is_table,
            )
            .unwrap();
            cursor.count_all_rows(&cx).unwrap()
        };

        let table_count = read_root_count(&conn, table_root_page, true);
        let index_count = read_root_count(&conn, index_root_page, false);
        let sql_rows = conn.query("SELECT COUNT(*) FROM bench;").unwrap();
        let sql_count = sql_rows[0]
            .get(0)
            .cloned()
            .expect("COUNT(*) should produce one value");

        assert_eq!(
            table_count, ROW_COUNT,
            "table root undercount: table_count={table_count} index_count={index_count} sql_count={sql_count:?}"
        );
        assert_eq!(
            index_count, ROW_COUNT,
            "index root undercount: table_count={table_count} index_count={index_count} sql_count={sql_count:?}"
        );
        assert_eq!(
            sql_count,
            SqliteValue::Integer(ROW_COUNT),
            "SQL count undercount: table_count={table_count} index_count={index_count} sql_count={sql_count:?}"
        );
    }

