    #[test]
    fn test_explicit_txn_update_with_scalar_subqueries_preserves_exact_count() {
        let _guard = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir
            .path()
            .join("explicit_txn_update_with_subqueries_count.db");
        let conn = Connection::open(db_path.to_str().unwrap()).unwrap();

        conn.execute(
            "CREATE TABLE conversations (
                id INTEGER PRIMARY KEY,
                ended_at INTEGER,
                total_tokens INTEGER,
                user_message_count INTEGER
            );",
        )
        .unwrap();
        conn.execute(
            "CREATE TABLE token_usage (
                id INTEGER PRIMARY KEY,
                conversation_id INTEGER NOT NULL,
                total_tokens INTEGER,
                role TEXT
            );",
        )
        .unwrap();
        conn.execute("CREATE INDEX idx_token_usage_conv ON token_usage(conversation_id);")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        conn.execute(
            "INSERT INTO conversations(id, ended_at, total_tokens, user_message_count)
             VALUES (1, 10, 0, 0);",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO token_usage(id, conversation_id, total_tokens, role) VALUES
                (1, 1, 10, 'user'),
                (2, 1, 20, 'assistant'),
                (3, 1, 30, 'user'),
                (4, 1, 40, 'assistant');",
        )
        .unwrap();
        conn.execute(
            "UPDATE conversations SET ended_at = MAX(COALESCE(ended_at, 0), 20) WHERE id = 1;",
        )
        .unwrap();
        let summary_update = "UPDATE conversations SET
                total_tokens = (SELECT SUM(total_tokens) FROM token_usage WHERE conversation_id = 1),
                user_message_count = (SELECT COUNT(*) FROM token_usage WHERE conversation_id = 1 AND role = 'user')
             WHERE id = 1;";
        conn.execute(summary_update).unwrap();
        conn.execute(summary_update).unwrap();
        conn.execute("COMMIT;").unwrap();

        let ids = conn
            .query("SELECT id FROM conversations ORDER BY id;")
            .unwrap();
        assert_eq!(ids.len(), 1);
        assert_eq!(ids[0].get(0), Some(&SqliteValue::Integer(1)));

        let rows = conn.query("SELECT COUNT(*) FROM conversations;").unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].get(0), Some(&SqliteValue::Integer(1)));

        let reopened = Connection::open(db_path.to_str().unwrap()).unwrap();
        let reopened_rows = reopened
            .query("SELECT COUNT(*) FROM conversations;")
            .unwrap();
        assert_eq!(reopened_rows.len(), 1);
        assert_eq!(reopened_rows[0].get(0), Some(&SqliteValue::Integer(1)));
    }

    #[test]
    fn test_explicit_txn_indexed_row_update_preserves_exact_count() {
        let _guard = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("explicit_txn_indexed_update_count.db");
        let conn = Connection::open(db_path.to_str().unwrap()).unwrap();

        conn.execute(
            "CREATE TABLE conversations (
                id INTEGER PRIMARY KEY,
                agent_id INTEGER,
                source_id TEXT,
                external_id TEXT,
                title TEXT,
                source_path TEXT,
                started_at INTEGER,
                ended_at INTEGER
            );",
        )
        .unwrap();
        conn.execute(
            "CREATE UNIQUE INDEX idx_conversations_provenance
             ON conversations(source_id, agent_id, external_id);",
        )
        .unwrap();
        conn.execute(
            "CREATE INDEX idx_conversations_source_id
             ON conversations(source_id);",
        )
        .unwrap();
        conn.execute(
            "CREATE INDEX idx_conversations_source_path
             ON conversations(source_path);",
        )
        .unwrap();

        let (table_root_page, provenance_index_root, source_id_index_root, source_path_index_root) = {
            let schema = conn.schema.borrow();
            let table = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("conversations"))
                .expect("conversations table should exist");
            let find_index_root = |name: &str| {
                table
                    .indexes
                    .iter()
                    .find(|index| index.name.eq_ignore_ascii_case(name))
                    .map(|index| index.root_page)
                    .expect("expected index root page")
            };
            (
                table.root_page,
                find_index_root("idx_conversations_provenance"),
                find_index_root("idx_conversations_source_id"),
                find_index_root("idx_conversations_source_path"),
            )
        };

        let read_root_count = |conn: &Connection, root_page: i32| -> i64 {
            let cx = Cx::new();
            conn.invalidate_cached_write_txn(&cx);
            conn.invalidate_cached_read_snapshot(&cx);
            let mut txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                .unwrap();
            let mut cursor = Connection::new_pager_btree_cursor(
                &cx,
                &mut txn,
                PageNumber::new(u32::try_from(root_page).expect("root page fits in u32"))
                    .expect("root page should be valid"),
                true,
            )
            .unwrap();
            cursor.count_all_rows(&cx).unwrap()
        };

        let read_root_leaf_state =
            |conn: &Connection,
             root_page: i32|
             -> (fsqlite_btree::cell::BtreePageType, u16, Vec<u16>, Vec<i64>) {
                let cx = Cx::new();
                conn.invalidate_cached_write_txn(&cx);
                conn.invalidate_cached_read_snapshot(&cx);
                let txn = conn
                    .pager
                    .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                    .unwrap();
                let page_no =
                    PageNumber::new(u32::try_from(root_page).expect("root page fits in u32"))
                        .expect("root page should be valid");
                let page = txn.get_page(&cx, page_no).unwrap();
                let header_offset = fsqlite_btree::header_offset_for_page(page_no);
                let header =
                    fsqlite_btree::cell::parse_page_header(page.as_ref(), page_no).unwrap();
                let ptrs = fsqlite_btree::read_cell_pointers(page.as_ref(), &header, header_offset)
                    .unwrap();
                let rowids = if header.page_type == fsqlite_btree::cell::BtreePageType::LeafTable {
                    ptrs.iter()
                        .map(|ptr| {
                            let cell_data = &page.as_ref()[usize::from(*ptr)..];
                            let (_, payload_varint_len) =
                                fsqlite_types::serial_type::read_varint(cell_data)
                                    .expect("table cell payload varint should decode");
                            let (rowid, _) = fsqlite_types::serial_type::read_varint(
                                &cell_data[payload_varint_len..],
                            )
                            .expect("table cell rowid varint should decode");
                            rowid as i64
                        })
                        .collect()
                } else {
                    Vec::new()
                };
                (header.page_type, header.cell_count, ptrs, rowids)
            };

        let format_bytes = |bytes: &[u8]| -> String {
            let mut out = String::with_capacity(bytes.len().saturating_mul(3));
            for (idx, byte) in bytes.iter().enumerate() {
                if idx > 0 {
                    out.push(' ');
                }
                use std::fmt::Write as _;
                write!(&mut out, "{byte:02x}").expect("writing to String should succeed");
            }
            out
        };

        let read_index_entries = |conn: &Connection, root_page: i32| -> Vec<String> {
            let cx = Cx::new();
            conn.invalidate_cached_write_txn(&cx);
            conn.invalidate_cached_read_snapshot(&cx);
            let mut txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                .unwrap();
            let mut cursor = Connection::new_pager_btree_cursor(
                &cx,
                &mut txn,
                PageNumber::new(u32::try_from(root_page).expect("root page fits in u32"))
                    .expect("root page should be valid"),
                false,
            )
            .unwrap();
            let mut rows = Vec::new();
            if cursor.first(&cx).unwrap() {
                loop {
                    let payload = cursor.payload(&cx).unwrap();
                    let decoded = fsqlite_types::record::parse_record(&payload).map_or_else(
                        || "<decode failed>".to_owned(),
                        |values| format!("{values:?}"),
                    );
                    rows.push(format!(
                        "cursor payload bytes=[{}] decoded={decoded}",
                        format_bytes(&payload)
                    ));
                    if !cursor.next(&cx).unwrap() {
                        break;
                    }
                }
            }
            rows
        };

        let read_index_root_cells = |conn: &Connection, root_page: i32| -> Vec<String> {
            let cx = Cx::new();
            conn.invalidate_cached_write_txn(&cx);
            conn.invalidate_cached_read_snapshot(&cx);
            let txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                .unwrap();
            let page_no = PageNumber::new(u32::try_from(root_page).expect("root page fits in u32"))
                .expect("root page should be valid");
            let page = txn.get_page(&cx, page_no).unwrap();
            let header_offset = fsqlite_btree::header_offset_for_page(page_no);
            let header = fsqlite_btree::cell::parse_page_header(page.as_ref(), page_no).unwrap();
            let ptrs =
                fsqlite_btree::read_cell_pointers(page.as_ref(), &header, header_offset).unwrap();
            ptrs.iter()
                .map(|ptr| {
                    let cell = fsqlite_btree::CellRef::parse(
                        page.as_ref(),
                        usize::from(*ptr),
                        header.page_type,
                        4096,
                    )
                    .unwrap();
                    let payload = cell.local_payload(page.as_ref());
                    let decoded = fsqlite_types::record::parse_record(payload).map_or_else(
                        || "<decode failed>".to_owned(),
                        |values| format!("{values:?}"),
                    );
                    format!(
                        "ptr={ptr} left_child={:?} rowid={:?} payload_bytes=[{}] decoded={decoded}",
                        cell.left_child,
                        cell.rowid,
                        format_bytes(payload),
                    )
                })
                .collect()
        };

        conn.execute("BEGIN;").unwrap();
        conn.execute(
            "INSERT INTO conversations(
                id, agent_id, source_id, external_id, title, source_path, started_at, ended_at
             ) VALUES (
                1, 1, 'local', 'dup-session', 'Shared Session', '/tmp/rollout.jsonl', 1700000000000, 1700000000000
             );",
        )
        .unwrap();
        conn.execute(
            "UPDATE conversations
             SET ended_at = MAX(COALESCE(ended_at, 0), 1700000000300)
             WHERE id = 1;",
        )
        .unwrap();
        conn.execute("COMMIT;").unwrap();

        let direct_count = read_root_count(&conn, table_root_page);
        let (root_page_type, root_cell_count, root_ptrs, root_rowids) =
            read_root_leaf_state(&conn, table_root_page);
        let provenance_index_count = read_root_count(&conn, provenance_index_root);
        let source_id_index_count = read_root_count(&conn, source_id_index_root);
        let source_path_index_count = read_root_count(&conn, source_path_index_root);
        let provenance_entries = read_index_entries(&conn, provenance_index_root);
        let source_id_entries = read_index_entries(&conn, source_id_index_root);
        let source_path_entries = read_index_entries(&conn, source_path_index_root);
        let provenance_root_cells = read_index_root_cells(&conn, provenance_index_root);
        let source_id_root_cells = read_index_root_cells(&conn, source_id_index_root);
        let source_path_root_cells = read_index_root_cells(&conn, source_path_index_root);
        let (source_id_page_type, source_id_cell_count, source_id_ptrs, _source_id_rowids) =
            read_root_leaf_state(&conn, source_id_index_root);
        let memdb_shortcuts_safe = conn.memdb_storage_count_shortcuts_safe.get();
        let count_stmt = conn.prepare("SELECT COUNT(*) FROM conversations;").unwrap();
        let count_explain = count_stmt.explain();
        let prepared_query_rows = count_stmt.query().unwrap();
        let prepared_query_row = count_stmt.query_row().unwrap();

        let ids = conn
            .query("SELECT id FROM conversations ORDER BY id;")
            .unwrap();
        assert_eq!(ids.len(), 1);
        assert_eq!(ids[0].get(0), Some(&SqliteValue::Integer(1)));

        let rows = conn.query("SELECT COUNT(*) FROM conversations;").unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(
            direct_count, 1,
            "direct root count mismatch: page_type={root_page_type:?} root_cell_count={root_cell_count} ptrs={root_ptrs:?} rowids={root_rowids:?}"
        );
        assert_eq!(
            provenance_index_count, 1,
            "unique provenance index count mismatch: entries={provenance_entries:?} root_cells={provenance_root_cells:?}"
        );
        assert_eq!(
            source_path_index_count, 1,
            "source_path index count mismatch: entries={source_path_entries:?} root_cells={source_path_root_cells:?}"
        );
        assert_eq!(
            source_id_index_count, 1,
            "source_id index count mismatch: page_type={source_id_page_type:?} root_cell_count={source_id_cell_count} ptrs={source_id_ptrs:?} entries={source_id_entries:?} root_cells={source_id_root_cells:?}"
        );
        assert_eq!(
            root_cell_count, 1,
            "root header cell_count mismatch: page_type={root_page_type:?} ptrs={root_ptrs:?} rowids={root_rowids:?}"
        );
        assert_eq!(
            prepared_query_rows[0].get(0),
            Some(&SqliteValue::Integer(1)),
            "prepared query count mismatch: memdb_shortcuts_safe={memdb_shortcuts_safe} explain=\n{count_explain}"
        );
        assert_eq!(
            prepared_query_row.get(0),
            Some(&SqliteValue::Integer(1)),
            "prepared query_row count mismatch: memdb_shortcuts_safe={memdb_shortcuts_safe} explain=\n{count_explain}"
        );
        assert_eq!(
            rows[0].get(0),
            Some(&SqliteValue::Integer(1)),
            "sql count mismatch: direct_count={direct_count} memdb_shortcuts_safe={memdb_shortcuts_safe} page_type={root_page_type:?} root_cell_count={root_cell_count} ptrs={root_ptrs:?} rowids={root_rowids:?} explain=\n{count_explain}"
        );

        let reopened = Connection::open(db_path.to_str().unwrap()).unwrap();
        let reopened_direct_count = read_root_count(&reopened, table_root_page);
        let (reopened_page_type, reopened_cell_count, reopened_ptrs, reopened_rowids) =
            read_root_leaf_state(&reopened, table_root_page);
        let reopened_memdb_shortcuts_safe = reopened.memdb_storage_count_shortcuts_safe.get();
        let reopened_count_stmt = reopened
            .prepare("SELECT COUNT(*) FROM conversations;")
            .unwrap();
        let reopened_count_explain = reopened_count_stmt.explain();
        let reopened_prepared_query_rows = reopened_count_stmt.query().unwrap();
        let reopened_prepared_query_row = reopened_count_stmt.query_row().unwrap();
        let reopened_rows = reopened
            .query("SELECT COUNT(*) FROM conversations;")
            .unwrap();
        assert_eq!(reopened_rows.len(), 1);
        assert_eq!(
            reopened_direct_count, 1,
            "reopened direct root count mismatch: page_type={reopened_page_type:?} root_cell_count={reopened_cell_count} ptrs={reopened_ptrs:?} rowids={reopened_rowids:?}"
        );
        assert_eq!(
            reopened_prepared_query_rows[0].get(0),
            Some(&SqliteValue::Integer(1)),
            "reopened prepared query count mismatch: memdb_shortcuts_safe={reopened_memdb_shortcuts_safe} explain=\n{reopened_count_explain}"
        );
        assert_eq!(
            reopened_prepared_query_row.get(0),
            Some(&SqliteValue::Integer(1)),
            "reopened prepared query_row count mismatch: memdb_shortcuts_safe={reopened_memdb_shortcuts_safe} explain=\n{reopened_count_explain}"
        );
        assert_eq!(
            reopened_rows[0].get(0),
            Some(&SqliteValue::Integer(1)),
            "reopened sql count mismatch: direct_count={reopened_direct_count} memdb_shortcuts_safe={reopened_memdb_shortcuts_safe} page_type={reopened_page_type:?} root_cell_count={reopened_cell_count} ptrs={reopened_ptrs:?} rowids={reopened_rowids:?} explain=\n{reopened_count_explain}"
        );
    }

    #[test]
    fn test_prepared_count_star_sum_query_row_uses_fast_path_and_tracks_write_through_rows() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_count_sum_runtime (id INTEGER PRIMARY KEY, score INTEGER);",
        )
        .unwrap();
        conn.execute("INSERT INTO prep_count_sum_runtime VALUES (1, 10), (2, 20);")
            .unwrap();
        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case("prep_count_sum_runtime"))
            .map(|table| table.root_page)
            .expect("test table root page");

        let stmt = conn
            .prepare("SELECT COUNT(*), SUM(score) FROM prep_count_sum_runtime;")
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleCountStarSum { .. })
        ));

        super::reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(2)));
        assert_eq!(row.get(1), Some(&SqliteValue::Integer(30)));
        assert_eq!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .as_ref()
                .map(Row::values),
            Some(&[SqliteValue::Integer(2), SqliteValue::Integer(30)][..])
        );

        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.parser.fast_path_executions, 1,
            "prepared COUNT(*)+SUM() should count as exactly one fast-path execution: {profile:?}"
        );
        assert_eq!(
            profile.parser.slow_path_executions, 0,
            "prepared COUNT(*)+SUM() should not fall back to the slow path: {profile:?}"
        );
        assert_eq!(profile.direct_count_star_query_row_hits, 0);
        assert_eq!(profile.direct_rowid_lookup_query_row_hits, 0);
        assert_eq!(profile.direct_count_star_rowid_range_query_row_hits, 0);

        conn.execute("INSERT INTO prep_count_sum_runtime VALUES (3, 30);")
            .unwrap();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(3)));
        assert_eq!(row.get(1), Some(&SqliteValue::Integer(60)));

        conn.execute("DELETE FROM prep_count_sum_runtime WHERE id = 2;")
            .unwrap();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(2)));
        assert_eq!(row.get(1), Some(&SqliteValue::Integer(40)));
    }

    #[test]
    fn test_prepared_count_star_sum_errors_on_all_integer_overflow_after_cached_seed() -> Result<()>
    {
        let conn = Connection::open(":memory:")?;
        conn.execute(
            "CREATE TABLE prep_count_sum_overflow (
                id INTEGER PRIMARY KEY,
                score INTEGER
            );",
        )?;
        conn.execute("INSERT INTO prep_count_sum_overflow VALUES (1, 9223372036854775807);")?;

        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case("prep_count_sum_overflow"))
            .map(|table| table.root_page)
            .ok_or_else(|| FrankenError::internal("missing prep_count_sum_overflow schema"))?;
        let stmt = conn.prepare("SELECT COUNT(*), SUM(score) FROM prep_count_sum_overflow;")?;
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleCountStarSum { .. })
        ));
        assert_eq!(
            stmt.query_row()?.values(),
            &[SqliteValue::Integer(1), SqliteValue::Integer(i64::MAX)]
        );
        assert!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .is_some(),
            "first read should seed the retained count+sum cache"
        );

        conn.execute("INSERT INTO prep_count_sum_overflow VALUES (2, 1);")?;
        let err = match stmt.query_row() {
            Ok(row) => {
                return Err(FrankenError::internal(format!(
                    "all-integer SUM overflow was hidden by the retained cache: {row:?}"
                )));
            }
            Err(err) => err,
        };
        assert!(matches!(err, FrankenError::IntegerOverflow));
        Ok(())
    }

