    #[test]
    fn test_prepared_simple_string_projection_query_matches_scalar_semantics_for_null_numeric_and_negative_substr()
     {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_string_projection_semantics (
                id INTEGER PRIMARY KEY,
                n INTEGER,
                tag TEXT,
                body TEXT
            );",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO prep_string_projection_semantics VALUES
                (1, 12345, 'alpha', 'abcdef'),
                (2, NULL, NULL, NULL);",
        )
        .unwrap();

        let stmt = conn
            .prepare(
                "SELECT LENGTH(n), UPPER(n), SUBSTR(body, 1, 2), UPPER(tag)
                 FROM prep_string_projection_semantics;",
            )
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleStringScalarProjection { .. })
        ));

        super::reset_hot_path_profile();
        let rows = stmt.query().unwrap();
        let actual = rows.iter().map(row_values).collect::<Vec<_>>();
        assert_eq!(
            actual,
            vec![
                vec![
                    SqliteValue::Integer(5),
                    SqliteValue::Text("12345".into()),
                    SqliteValue::Text("ab".into()),
                    SqliteValue::Text("ALPHA".into()),
                ],
                vec![
                    SqliteValue::Null,
                    SqliteValue::Null,
                    SqliteValue::Null,
                    SqliteValue::Null,
                ],
            ]
        );
        assert_eq!(
            super::direct_substr(&SqliteValue::Text("abcdef".into()), -3, Some(2)),
            super::eval_scalar_fn(
                "substr",
                &[
                    SqliteValue::Text("abcdef".into()),
                    SqliteValue::Integer(-3),
                    SqliteValue::Integer(2),
                ],
            )
        );
        assert_eq!(
            super::direct_length(&SqliteValue::Text("éclair".into())),
            SqliteValue::Integer(6)
        );

        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.parser.fast_path_executions, 1);
        assert_eq!(profile.parser.slow_path_executions, 0);

        let rowid_stmt = conn
            .prepare(
                "SELECT LENGTH(id), UPPER(id), SUBSTR(id, 1, 1)
                 FROM prep_string_projection_semantics;",
            )
            .unwrap();
        assert!(matches!(
            rowid_stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleStringScalarProjection { .. })
        ));
        let rowid_rows = rowid_stmt.query().unwrap();
        let rowid_actual = rowid_rows.iter().map(row_values).collect::<Vec<_>>();
        assert_eq!(
            rowid_actual,
            vec![
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Text("1".into()),
                    SqliteValue::Text("1".into()),
                ],
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Text("2".into()),
                    SqliteValue::Text("2".into()),
                ],
            ]
        );
    }

