    #[test]
    fn test_prepared_projected_rowid_lookup_alias_hides_base_table_star() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_pk_projection_alias_star (
                id INTEGER PRIMARY KEY,
                val TEXT
            );",
        )
        .unwrap();
        conn.execute("INSERT INTO prep_pk_projection_alias_star VALUES (1, 'alpha');")
            .unwrap();

        let err = conn
            .query_with_params(
                "SELECT prep_pk_projection_alias_star.* \
                 FROM prep_pk_projection_alias_star AS p \
                 WHERE p.rowid = ?1;",
                &[SqliteValue::Integer(1)],
            )
            .expect_err("base table name must not resolve after aliasing");
        assert!(
            err.to_string()
                .contains("no such table: prep_pk_projection_alias_star"),
            "unexpected error: {err:?}"
        );

        let rows = conn
            .query_with_params(
                "SELECT p.* \
                 FROM prep_pk_projection_alias_star AS p \
                 WHERE p.rowid = ?1;",
                &[SqliteValue::Integer(1)],
            )
            .expect("the alias itself should still resolve through the fast path");
        assert_eq!(
            rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(1),
                SqliteValue::Text("alpha".into()),
            ]]
        );
    }

