    #[test]
    fn test_prepared_count_indexed_exists_rowid_probe_query_row_uses_fast_path() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL);")
            .unwrap();
        conn.execute(
            "CREATE TABLE products (
                id INTEGER PRIMARY KEY,
                category_id INTEGER NOT NULL,
                name TEXT NOT NULL
            );",
        )
        .unwrap();
        conn.execute("CREATE INDEX products_category_id_idx ON products(category_id);")
            .unwrap();
        conn.execute(
            "INSERT INTO categories VALUES
                (1, 'alpha'),
                (2, 'beta'),
                (3, 'gamma'),
                (4, 'delta'),
                (5, 'epsilon');",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO products VALUES
                (1, 1, 'p1'),
                (2, 1, 'p2'),
                (3, 2, 'p3'),
                (4, 3, 'p4'),
                (5, 4, 'p5'),
                (6, 5, 'p6');",
        )
        .unwrap();

        let stmt = conn
            .prepare(
                "SELECT COUNT(*) FROM products p \
                 WHERE EXISTS (
                     SELECT 1 FROM categories c
                     WHERE c.id = p.category_id AND c.id <= 3
                 );",
            )
            .unwrap();
        assert!(
            matches!(
                stmt.prepared_query_fast_path.as_ref(),
                Some(&super::PreparedQueryFastPath::SimpleCountIndexedRowidProbe { .. })
            ),
            "actual fast path: {:?}",
            stmt.prepared_query_fast_path
        );

        super::reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(4)));

        conn.execute("INSERT INTO products VALUES (7, 2, 'p7');")
            .unwrap();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(5)));

        conn.execute("DELETE FROM categories WHERE id = 3;")
            .unwrap();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.get(0), Some(&SqliteValue::Integer(4)));

        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.direct_count_indexed_rowid_probe_query_row_hits, 3);
        assert!(
            profile.parser.fast_path_executions
                >= profile.direct_count_indexed_rowid_probe_query_row_hits,
            "aggregate fast-path counter also includes DML fast paths in this test: {profile:?}"
        );
        assert_eq!(profile.parser.slow_path_executions, 0);
        assert_eq!(profile.direct_count_star_query_row_hits, 0);
        assert_eq!(profile.direct_rowid_lookup_query_row_hits, 0);
        assert_eq!(profile.direct_count_star_rowid_range_query_row_hits, 0);
    }

