    #[test]
    fn test_benchmark_in_subquery_repeat_count_cache_tracks_write() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        populate_benchmark_subquery_fixture(&conn, 1_000);

        let stmt = conn
            .prepare(
                "SELECT COUNT(*) FROM products \
                 WHERE category_id IN (SELECT id FROM categories WHERE id <= 5)",
            )
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleCountIndexedRowidProbe { .. })
        ));

        super::reset_hot_path_profile();
        let first = stmt.query_row().unwrap();
        assert_eq!(first.get(0), Some(&SqliteValue::Integer(100)));
        assert_eq!(
            conn.prepared_count_indexed_rowid_probe_last_result
                .borrow()
                .as_ref()
                .map(|result| result.count),
            Some(100)
        );

        let second = stmt.query_row().unwrap();
        assert_eq!(second, first);

        conn.execute("INSERT INTO products VALUES (1001, 'prod_1001', 3.14, 2)")
            .unwrap();
        let after_write = stmt.query_row().unwrap();
        assert_eq!(after_write.get(0), Some(&SqliteValue::Integer(101)));
        assert_eq!(
            conn.prepared_count_indexed_rowid_probe_last_result
                .borrow()
                .as_ref()
                .map(|result| result.count),
            Some(101)
        );

        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.direct_count_indexed_rowid_probe_query_row_hits, 3);
        assert_eq!(profile.parser.slow_path_executions, 0);
    }

