    #[test]
    fn test_file_backed_clean_prepared_projected_rowid_lookup_uses_memdb_fast_path() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let dir = tempfile::TempDir::new().unwrap();
        let db_path = dir.path().join("clean-projected-rowid-lookup.db");
        let db_path = db_path.to_string_lossy().into_owned();
        let conn = Connection::open(db_path.clone()).unwrap();
        conn.execute(
            "CREATE TABLE clean_projected_lookup (
                id INTEGER PRIMARY KEY,
                score INTEGER NOT NULL
            );",
        )
        .unwrap();
        conn.execute("BEGIN").unwrap();
        conn.execute("INSERT INTO clean_projected_lookup VALUES (1, 11), (2, 22);")
            .unwrap();
        conn.execute("COMMIT").unwrap();
        assert!(
            conn.retained_autocommit_txn.borrow().is_none(),
            "explicit setup transaction should leave no retained autocommit overlay"
        );

        let stmt = conn
            .prepare("SELECT score FROM clean_projected_lookup WHERE id = ?1;")
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleProjectedRowidLookup { .. })
        ));

        super::reset_hot_path_profile();
        let row = stmt
            .query_row_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        assert_eq!(row.values(), &[SqliteValue::Integer(22)]);
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.direct_rowid_lookup_query_row_hits, 1,
            "clean file-backed prepared lookup should use the direct MemDB fast path: {profile:?}"
        );
        assert_eq!(
            profile.retained_autocommit_overlay_hits, 0,
            "clean read should not depend on retained-overlay semantics: {profile:?}"
        );
        assert_eq!(
            profile.prepared_schema_refreshes, 0,
            "clean direct MemDB lookup should validate the refreshed local schema without a second prepared-schema refresh: {profile:?}"
        );
        assert_eq!(
            profile.begin_setup_time_ns, 0,
            "clean direct MemDB lookup should not open an autocommit read transaction: {profile:?}"
        );

        let writer = Connection::open(db_path).unwrap();
        writer.execute("BEGIN").unwrap();
        writer
            .execute("INSERT INTO clean_projected_lookup VALUES (3, 33);")
            .unwrap();
        writer.execute("COMMIT").unwrap();

        super::reset_hot_path_profile();
        let row = stmt
            .query_row_with_params(&[SqliteValue::Integer(3)])
            .unwrap();
        assert_eq!(row.values(), &[SqliteValue::Integer(33)]);
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(
            profile.direct_rowid_lookup_query_row_hits, 1,
            "external commit should refresh before the direct MemDB lookup: {profile:?}"
        );
        assert_eq!(
            profile.prepared_schema_refreshes, 0,
            "external commit refresh should still avoid redundant prepared-schema refresh: {profile:?}"
        );
        assert_eq!(
            profile.begin_setup_time_ns, 0,
            "external commit refresh should still avoid opening an autocommit read transaction: {profile:?}"
        );
    }

