    #[test]
    fn test_file_backed_clean_prepared_indexed_equality_repeat_probe_uses_last_result_cache() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let dir = tempfile::TempDir::new().unwrap();
        let db_path = dir.path().join("clean-indexed-equality-repeat.db");
        let db_path = db_path.to_string_lossy().into_owned();
        let conn = Connection::open(db_path.clone()).unwrap();
        conn.execute(
            "CREATE TABLE clean_indexed_repeat (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                score INTEGER NOT NULL
            );",
        )
        .unwrap();
        conn.execute("CREATE INDEX clean_indexed_repeat_name ON clean_indexed_repeat(name);")
            .unwrap();
        conn.execute("BEGIN").unwrap();
        conn.execute(
            "INSERT INTO clean_indexed_repeat VALUES
                (1, 'beta', 11),
                (2, 'gamma', 22);",
        )
        .unwrap();
        conn.execute("COMMIT").unwrap();

        let stmt = conn
            .prepare("SELECT * FROM clean_indexed_repeat WHERE name = ?1;")
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(&super::PreparedQueryFastPath::SimpleIndexedEqualityLookup { .. })
        ));

        let beta_param = [SqliteValue::Text("beta".into())];
        super::reset_hot_path_profile();
        let first = stmt.query_with_params(&beta_param).unwrap();
        assert_eq!(
            first.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(1),
                SqliteValue::Text("beta".into()),
                SqliteValue::Integer(11),
            ]]
        );
        assert!(
            conn.prepared_indexed_equality_last_result
                .borrow()
                .is_some(),
            "first clean file-backed indexed-equality probe should seed the last-result cache"
        );

        let cached = stmt.query_with_params(&beta_param).unwrap();
        assert_eq!(cached, first);
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.parser.fast_path_executions, 2);
        assert_eq!(profile.parser.slow_path_executions, 0);
        assert_eq!(profile.direct_indexed_equality_query_hits, 2);
        assert_eq!(
            profile.begin_setup_time_ns, 0,
            "clean indexed-equality probes should stay boundary-free: {profile:?}"
        );

        let writer = Connection::open(db_path).unwrap();
        writer.execute("BEGIN").unwrap();
        writer
            .execute("INSERT INTO clean_indexed_repeat VALUES (3, 'beta', 33);")
            .unwrap();
        writer.execute("COMMIT").unwrap();

        super::reset_hot_path_profile();
        let refreshed = stmt.query_with_params(&beta_param).unwrap();
        assert_eq!(
            refreshed.iter().map(row_values).collect::<Vec<_>>(),
            vec![
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Text("beta".into()),
                    SqliteValue::Integer(11),
                ],
                vec![
                    SqliteValue::Integer(3),
                    SqliteValue::Text("beta".into()),
                    SqliteValue::Integer(33),
                ],
            ]
        );
        let profile = super::hot_path_profile_snapshot();
        assert_eq!(profile.parser.fast_path_executions, 1);
        assert_eq!(profile.parser.slow_path_executions, 0);
        assert_eq!(
            profile.memdb_refresh_count, 1,
            "external commit should invalidate the old last-result key before reuse: {profile:?}"
        );
    }

