        assert!(trigger_sql.contains("UPDATE OF new_col"), "{trigger_sql}");
        assert!(trigger_sql.contains("NEW.new_col"), "{trigger_sql}");
        assert!(!trigger_sql.contains("old_col"), "{trigger_sql}");
