    #[test]
    fn test_prepared_update_keeps_secondary_and_partial_indexes_sqlite_compatible() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("issues_prepared_update_indexes.db");
        let db_str = db_path.to_string_lossy().to_string();

        let conn = Connection::open(&db_str).unwrap();
        conn.execute(
            "CREATE TABLE issues (
                id TEXT PRIMARY KEY,
                content_hash TEXT,
                priority INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'open',
                is_template INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL,
                closed_at TEXT,
                close_reason TEXT DEFAULT ''
            );",
        )
        .unwrap();
        conn.execute("CREATE INDEX idx_issues_content_hash ON issues(content_hash);")
            .unwrap();
        conn.execute(
            "CREATE INDEX idx_issues_list_active_order
             ON issues(priority, created_at DESC)
             WHERE status NOT IN ('closed', 'tombstone')
               AND ((is_template = 0) OR is_template IS NULL);",
        )
        .unwrap();

        conn.execute(
            "INSERT INTO issues(
                id, content_hash, priority, created_at, status, is_template, updated_at, closed_at, close_reason
             ) VALUES
                ('bd-a', 'hash-a0', 1, '2026-03-11 10:00:00', 'open', 0, '2026-03-11 10:00:00', NULL, ''),
                ('bd-b', 'hash-b0', 2, '2026-03-11 11:00:00', 'open', 0, '2026-03-11 11:00:00', NULL, ''),
                ('bd-c', 'hash-c0', 3, '2026-03-11 12:00:00', 'closed', 0, '2026-03-11 12:00:00', '2026-03-11 12:00:00', 'done');",
        )
        .unwrap();

        let stmt = conn
            .prepare(
                "UPDATE issues
                 SET content_hash = ?1,
                     priority = ?2,
                     created_at = ?3,
                     status = ?4,
                     updated_at = ?5,
                     closed_at = ?6,
                     close_reason = ?7
                 WHERE id = ?8",
            )
            .unwrap();

        conn.execute_prepared_with_params(
            &stmt,
            &[
                SqliteValue::Text("hash-a1".into()),
                SqliteValue::Integer(1),
                SqliteValue::Text("2026-03-11 10:00:00".into()),
                SqliteValue::Text("closed".into()),
                SqliteValue::Text("2026-03-11 13:00:00".into()),
                SqliteValue::Text("2026-03-11 13:00:00".into()),
                SqliteValue::Text("completed".into()),
                SqliteValue::Text("bd-a".into()),
            ],
        )
        .unwrap();

        conn.execute_prepared_with_params(
            &stmt,
            &[
                SqliteValue::Text("hash-c1".into()),
                SqliteValue::Integer(1),
                SqliteValue::Text("2026-03-11 14:00:00".into()),
                SqliteValue::Text("open".into()),
                SqliteValue::Text("2026-03-11 14:00:00".into()),
                SqliteValue::Null,
                SqliteValue::Text("".into()),
                SqliteValue::Text("bd-c".into()),
            ],
        )
        .unwrap();

        conn.execute_prepared_with_params(
            &stmt,
            &[
                SqliteValue::Text("hash-b1".into()),
                SqliteValue::Integer(2),
                SqliteValue::Text("2026-03-11 11:30:00".into()),
                SqliteValue::Text("open".into()),
                SqliteValue::Text("2026-03-11 11:30:00".into()),
                SqliteValue::Null,
                SqliteValue::Text("".into()),
                SqliteValue::Text("bd-b".into()),
            ],
        )
        .unwrap();

        drop(stmt);
        drop(conn);

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "prepared UPDATE should keep ordinary and partial secondary indexes SQLite-compatible"
        );
    }

    #[test]
    fn test_prepared_update_keeps_large_secondary_and_partial_indexes_sqlite_compatible() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("issues_prepared_update_large_indexes.db");
        let db_str = db_path.to_string_lossy().to_string();

        let conn = Connection::open(&db_str).unwrap();
        conn.execute(
            "CREATE TABLE issues (
                id TEXT PRIMARY KEY,
                content_hash TEXT,
                priority INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'open',
                is_template INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL,
                closed_at TEXT,
                close_reason TEXT DEFAULT ''
            );",
        )
        .unwrap();
        conn.execute("CREATE INDEX idx_issues_content_hash ON issues(content_hash);")
            .unwrap();
        conn.execute(
            "CREATE INDEX idx_issues_list_active_order
             ON issues(priority, created_at DESC)
             WHERE status NOT IN ('closed', 'tombstone')
               AND ((is_template = 0) OR is_template IS NULL);",
        )
        .unwrap();

        let insert = conn
            .prepare(
                "INSERT INTO issues(
                    id, content_hash, priority, created_at, status, is_template, updated_at, closed_at, close_reason
                 ) VALUES (?1, ?2, ?3, ?4, 'open', 0, ?5, NULL, '')",
            )
            .unwrap();
        conn.execute("BEGIN;").unwrap();
        for i in 0_i64..1200 {
            let hash = format!("{i:032x}{:032x}", i + 1);
            let ts = format!("2026-03-11T{:02}:{:02}:00Z", i % 24, i % 60);
            conn.execute_prepared_with_params(
                &insert,
                &[
                    SqliteValue::Text(format!("bd-{i:04}").into()),
                    SqliteValue::Text(hash.into()),
                    SqliteValue::Integer(i % 5),
                    SqliteValue::Text(ts.clone().into()),
                    SqliteValue::Text(ts.into()),
                ],
            )
            .unwrap();
        }
        conn.execute("COMMIT;").unwrap();
        drop(insert);

        let target = 600_i64;
        let old_hash = format!("{target:032x}{:032x}", target + 1);
        let new_hash = "4548b222a696de7a7fd04b23869ebef9b3e70e1b183e2936e0f554ee41bead05";
        let stmt = conn
            .prepare(
                "UPDATE issues
                 SET content_hash = ?1,
                     priority = ?2,
                     created_at = ?3,
                     status = ?4,
                     updated_at = ?5,
                     closed_at = ?6,
                     close_reason = ?7
                 WHERE id = ?8",
            )
            .unwrap();
        conn.execute_prepared_with_params(
            &stmt,
            &[
                SqliteValue::Text(new_hash.into()),
                SqliteValue::Integer(0),
                SqliteValue::Text("2026-03-12T02:43:28Z".into()),
                SqliteValue::Text("closed".into()),
                SqliteValue::Text("2026-03-12T02:43:28Z".into()),
                SqliteValue::Text("2026-03-12T02:43:28Z".into()),
                SqliteValue::Text("closed during stress regression".into()),
                SqliteValue::Text(format!("bd-{target:04}").into()),
            ],
        )
        .unwrap();
        drop(stmt);
        drop(conn);

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "prepared UPDATE should remain SQLite-compatible after the content-hash index grows beyond a single small leaf"
        );

        let stale_count: i64 = sqlite
            .query_row(
                "SELECT COUNT(*) FROM issues WHERE content_hash = ?1",
                [old_hash],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            stale_count, 0,
            "old content hash should not remain query-visible"
        );
    }

    #[test]
    fn test_beads_like_schema_survives_reopen_updates_and_comments() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("beads_like_schema_compat.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute(
                "CREATE TABLE issues (
                    id TEXT PRIMARY KEY,
                    title TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'open',
                    priority INTEGER NOT NULL DEFAULT 2,
                    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    is_template INTEGER NOT NULL DEFAULT 0
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE INDEX idx_issues_list_active_order
                 ON issues(priority, created_at DESC)
                 WHERE status NOT IN ('closed', 'tombstone')
                   AND ((is_template = 0) OR is_template IS NULL);",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE comments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    issue_id TEXT NOT NULL,
                    author TEXT NOT NULL,
                    text TEXT NOT NULL,
                    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (issue_id) REFERENCES issues (id) ON DELETE CASCADE
                );",
            )
            .unwrap();
            conn.execute("CREATE INDEX idx_comments_issue ON comments(issue_id);")
                .unwrap();
            conn.execute("CREATE INDEX idx_comments_created_at ON comments(created_at);")
                .unwrap();

            conn.execute(
                "INSERT INTO issues(id, title, status, priority, created_at, is_template)
                 VALUES
                    ('bd-10t6', 'Aggregate functions', 'open', 1, '2026-03-11 10:00:00', 0),
                    ('bd-cfzef', 'Cancellation checkpoints', 'open', 1, '2026-03-11 11:00:00', 0),
                    ('bd-zjisk', 'Default backend cutover', 'closed', 2, '2026-03-11 12:00:00', 0),
                    ('bd-template', 'Template row', 'open', 0, '2026-03-11 09:00:00', 1);",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO comments(issue_id, author, text, created_at)
                 VALUES ('bd-10t6', 'Dicklesworthstone', 'seed comment', '2026-03-12T00:00:00Z');",
            )
            .unwrap();
        }

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute(
                "UPDATE issues
                 SET status = 'open', created_at = '2026-03-11 13:00:00'
                 WHERE id = 'bd-zjisk';",
            )
            .unwrap();
            conn.execute(
                "UPDATE issues
                 SET status = 'closed'
                 WHERE id = 'bd-10t6';",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO comments(issue_id, author, text)
                 VALUES ('bd-cfzef', 'ScarletFalcon', 'follow-up comment');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO comments(issue_id, author, text, created_at)
                 VALUES ('bd-zjisk', 'BlueOwl', 'reopened and verified', '2026-03-12T00:01:00Z');",
            )
            .unwrap();
        }

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "Beads-style issues/comments workload should remain SQLite-compatible after reopen"
        );

        let active_issue_rows = sqlite
            .prepare(
                "SELECT id, priority, created_at
                 FROM issues INDEXED BY idx_issues_list_active_order
                 WHERE status NOT IN ('closed', 'tombstone')
                   AND ((is_template = 0) OR is_template IS NULL)
                   AND status = 'open'
                   AND is_template = 0
                 ORDER BY priority, created_at DESC",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();

        assert_eq!(
            active_issue_rows,
            vec![
                ("bd-cfzef".to_owned(), 1, "2026-03-11 11:00:00".to_owned()),
                ("bd-zjisk".to_owned(), 2, "2026-03-11 13:00:00".to_owned()),
            ],
            "descending partial index query over active Beads issues should match expected rows"
        );

        let comment_rows = sqlite
            .prepare(
                "SELECT id, issue_id, author, text, created_at, typeof(created_at)
                 FROM comments
                 ORDER BY id",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(4)?,
                    row.get::<_, String>(5)?,
                ))
            })
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();

        assert_eq!(comment_rows.len(), 3);
        assert_eq!(
            comment_rows[0],
            (
                1,
                "bd-10t6".to_owned(),
                "Dicklesworthstone".to_owned(),
                "seed comment".to_owned(),
                "2026-03-12T00:00:00Z".to_owned(),
                "text".to_owned(),
            )
        );
        assert_eq!(comment_rows[1].0, 2);
        assert_eq!(comment_rows[1].1, "bd-cfzef");
        assert_eq!(comment_rows[1].2, "ScarletFalcon");
        assert_eq!(comment_rows[1].3, "follow-up comment");
        assert!(!comment_rows[1].4.is_empty());
        assert_eq!(comment_rows[1].5, "text");
        assert_eq!(
            comment_rows[2],
            (
                3,
                "bd-zjisk".to_owned(),
                "BlueOwl".to_owned(),
                "reopened and verified".to_owned(),
                "2026-03-12T00:01:00Z".to_owned(),
                "text".to_owned(),
            )
        );
    }

    #[test]
    fn test_beads_like_events_ipk_payload_survives_reopen() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("beads_like_events_compat.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute(
                "CREATE TABLE issues (
                    id TEXT PRIMARY KEY,
                    title TEXT NOT NULL
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    issue_id TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    actor TEXT NOT NULL DEFAULT '',
                    old_value TEXT,
                    new_value TEXT,
                    comment TEXT,
                    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (issue_id) REFERENCES issues (id) ON DELETE CASCADE
                );",
            )
            .unwrap();
            conn.execute("CREATE INDEX idx_events_issue_id ON events(issue_id);")
                .unwrap();
            conn.execute("CREATE INDEX idx_events_created_at ON events(created_at);")
                .unwrap();
            conn.execute(
                "INSERT INTO issues(id, title) VALUES ('bd-10t6', 'Aggregate functions');",
            )
            .unwrap();

            conn.execute(
                "INSERT INTO events(issue_id, event_type, actor, comment, created_at)
                 VALUES (
                    'bd-10t6',
                    'created',
                    'ubuntu',
                    'Created issue: Aggregate functions',
                    '2026-03-12T01:38:03.704848018+00:00'
                 );",
            )
            .unwrap();
        }

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute(
                "INSERT INTO events(issue_id, event_type, actor, comment)
                 VALUES (
                    'bd-10t6',
                    'commented',
                    'CloudyPine',
                    'Follow-up comment event'
                 );",
            )
            .unwrap();
        }

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "Beads-style events payloads should remain SQLite-compatible after reopen"
        );

        let event_rows = sqlite
            .prepare(
                "SELECT id, issue_id, event_type, actor, old_value, new_value, comment, created_at, typeof(created_at)
                 FROM events
                 ORDER BY id",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, Option<String>>(4)?,
                    row.get::<_, Option<String>>(5)?,
                    row.get::<_, Option<String>>(6)?,
                    row.get::<_, String>(7)?,
                    row.get::<_, String>(8)?,
                ))
            })
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();

        assert_eq!(event_rows.len(), 2);
        assert_eq!(
            event_rows[0],
            (
                1,
                "bd-10t6".to_owned(),
                "created".to_owned(),
                "ubuntu".to_owned(),
                None,
                None,
                Some("Created issue: Aggregate functions".to_owned()),
                "2026-03-12T01:38:03.704848018+00:00".to_owned(),
                "text".to_owned(),
            )
        );
        assert_eq!(event_rows[1].0, 2);
        assert_eq!(event_rows[1].1, "bd-10t6");
        assert_eq!(event_rows[1].2, "commented");
        assert_eq!(event_rows[1].3, "CloudyPine");
        assert_eq!(event_rows[1].4, None);
        assert_eq!(event_rows[1].5, None);
        assert_eq!(event_rows[1].6, Some("Follow-up comment event".to_owned()));
        assert!(!event_rows[1].7.is_empty());
        assert_eq!(event_rows[1].8, "text");
    }

    #[test]
    fn test_create_index_if_not_exists() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (a INTEGER);").unwrap();
        conn.execute("CREATE INDEX idx_a ON t (a);").unwrap();
        // Duplicate without IF NOT EXISTS should fail.
        assert!(conn.execute("CREATE INDEX idx_a ON t (a);").is_err());
        // With IF NOT EXISTS should succeed silently.
        conn.execute("CREATE INDEX IF NOT EXISTS idx_a ON t (a);")
            .unwrap();
    }

    #[test]
    fn test_create_named_index_on_unique_columns_with_existing_autoindex() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE messages (
                id INTEGER PRIMARY KEY,
                conversation_id INTEGER NOT NULL,
                idx INTEGER NOT NULL,
                UNIQUE(conversation_id, idx)
            );",
        )
        .unwrap();

        conn.execute("CREATE INDEX idx_messages_conv_idx ON messages(conversation_id, idx);")
            .unwrap();
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_messages_conv_idx ON messages(conversation_id, idx);",
        )
        .unwrap();

        let index_count: i64 = conn
            .query(
                "SELECT COUNT(*) FROM sqlite_master
                 WHERE type='index'
                   AND name IN ('idx_messages_conv_idx', 'sqlite_autoindex_messages_1');",
            )
            .unwrap()
            .into_iter()
            .next()
            .and_then(|row| match row.values()[0] {
                SqliteValue::Integer(value) => Some(value),
                _ => None,
            })
            .unwrap();
        assert_eq!(index_count, 2);
    }

