    fn test_trigger_raise_fail_keeps_prior_rows() {
        // RAISE(FAIL) fails the statement but KEEPS rows already inserted before
        // the failing one (unlike RAISE(ABORT), which undoes them). bd-dkp13.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER);").unwrap();
        conn.execute(
            "CREATE TRIGGER trg_raise_fail BEFORE INSERT ON t WHEN NEW.id = 3 \
             BEGIN SELECT RAISE(FAIL, 'fail insert'); END;",
        )
        .unwrap();

        let err = conn
            .execute("INSERT INTO t VALUES (1),(2),(3),(4);")
            .expect_err("INSERT should fail via RAISE(FAIL)");
        // FAIL surfaces as RaiseFail (a distinct signal from ABORT's
        // FunctionError) carrying the same verbatim message.
        assert!(matches!(
            err,
            FrankenError::RaiseFail(ref msg) if msg == "fail insert"
        ));

        // Rows 1 and 2 (inserted before the failing row 3) must survive.
        let rows = conn.query("SELECT id FROM t ORDER BY id;").unwrap();
        let ids: Vec<i64> = rows
            .iter()
            .map(|row| match row.values()[0] {
                SqliteValue::Integer(n) => n,
                ref other => panic!("unexpected value {other:?}"),
            })
            .collect();
        assert_eq!(ids, vec![1, 2], "RAISE(FAIL) must keep prior rows");
    }

    #[test]
    fn test_trigger_raise_rollback_aborts_transaction() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER);").unwrap();
        conn.execute(
            "CREATE TRIGGER trg_raise_rb BEFORE INSERT ON t BEGIN SELECT RAISE(ROLLBACK, 'rollback insert'); END;",
        )
        .unwrap();

        conn.execute("BEGIN;").unwrap();
        let err = conn
            .execute("INSERT INTO t VALUES (1);")
            .expect_err("INSERT should fail via RAISE(ROLLBACK)");
        assert!(matches!(
            err,
            FrankenError::TransactionRolledBack { ref reason } if reason == "rollback insert"
        ));

        let rows = conn.query("SELECT id FROM t;").unwrap();
        assert!(
            rows.is_empty(),
            "transaction should be rolled back by RAISE(ROLLBACK)"
        );
    }

    #[test]
    fn test_fk_violation_rolls_back_only_failed_statement_in_explicit_txn() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").unwrap();
        conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
            .unwrap();
        conn.execute("CREATE TABLE child (parent_id INTEGER REFERENCES parent(id));")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        let err = conn
            .execute("INSERT INTO child VALUES (1);")
            .expect_err("FK violation should abort the statement");
        assert!(matches!(err, FrankenError::ForeignKeyViolation));
        assert!(
            conn.in_transaction(),
            "explicit transaction should remain open"
        );

        let rows = conn.query("SELECT COUNT(*) FROM child;").unwrap();
        assert_eq!(
            rows[0].values()[0],
            SqliteValue::Integer(0),
            "failed INSERT should not leave partial child rows behind"
        );

        conn.execute("INSERT INTO parent VALUES (1);").unwrap();
        conn.execute("INSERT INTO child VALUES (1);").unwrap();
        conn.execute("COMMIT;").unwrap();

        let rows = conn.query("SELECT COUNT(*) FROM child;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
    }

