        conn.execute(&create_table_sql).unwrap();
        conn.execute("CREATE TABLE log (v INTEGER);").unwrap();
        conn.execute(
            "CREATE TRIGGER trg_large AFTER INSERT ON t BEGIN INSERT INTO log VALUES (NEW.c100); END;",
        )
