    // ── GROUP BY + rowid alias resolution (bd-399s) ──────

    #[test]
    fn test_group_by_rowid_alias() {
        // GROUP BY rowid must resolve to the INTEGER PRIMARY KEY column
        // so that each row has a distinct group key.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, val TEXT, num REAL);")
            .unwrap();
        conn.execute("INSERT INTO t VALUES (1, 'alpha', 1.5);")
            .unwrap();
        conn.execute("INSERT INTO t VALUES (2, 'beta', 2.5);")
            .unwrap();
        conn.execute("INSERT INTO t VALUES (3, 'gamma', 3.5);")
            .unwrap();

        // Each rowid is unique, so COUNT(*) should be 1 for every group.
        let rows = conn
            .query("SELECT rowid, COUNT(*) AS cnt FROM t GROUP BY rowid ORDER BY rowid;")
            .unwrap();
        assert_eq!(rows.len(), 3);
        assert_eq!(
            row_values(&rows[0]),
            vec![SqliteValue::Integer(1), SqliteValue::Integer(1)]
        );
        assert_eq!(
            row_values(&rows[2]),
            vec![SqliteValue::Integer(3), SqliteValue::Integer(1)]
        );

        // HAVING cnt > 1 should return nothing (no duplicate rowids).
        let dups = conn
            .query("SELECT rowid, COUNT(*) AS cnt FROM t GROUP BY rowid HAVING cnt > 1;")
            .unwrap();
        assert!(dups.is_empty(), "expected no duplicate rowids");
    }

    #[test]
    fn test_group_by_rowid_alias_variants() {
        // _rowid_ and oid should also resolve correctly.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t2 (pk INTEGER PRIMARY KEY, x TEXT);")
            .unwrap();
        conn.execute("INSERT INTO t2 VALUES (10, 'a');").unwrap();
        conn.execute("INSERT INTO t2 VALUES (20, 'b');").unwrap();

        let rows = conn
            .query("SELECT _rowid_, COUNT(*) FROM t2 GROUP BY _rowid_ ORDER BY _rowid_;")
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(10));
        assert_eq!(row_values(&rows[1])[0], SqliteValue::Integer(20));

        let rows = conn
            .query("SELECT oid, COUNT(*) FROM t2 GROUP BY oid ORDER BY oid;")
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(10));
    }

    #[test]
    fn test_group_by_rowid_bucket_sum() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE bench (id INTEGER PRIMARY KEY, value REAL);")
            .unwrap();
        conn.execute("BEGIN;").unwrap();
        let insert = conn
            .prepare("INSERT INTO bench VALUES (?1, (?1 + 0.5));")
            .unwrap();
        for id in 0..25_i64 {
            insert
                .execute_with_params(&[SqliteValue::Integer(id)])
                .unwrap();
        }
        conn.execute("COMMIT;").unwrap();

        let rows = conn
            .query("SELECT (id / 10), SUM(value) FROM bench GROUP BY (id / 10);")
            .unwrap();
        assert_eq!(
            rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Integer(0), SqliteValue::Float(50.0)],
                vec![SqliteValue::Integer(1), SqliteValue::Float(150.0)],
                vec![SqliteValue::Integer(2), SqliteValue::Float(112.5)],
            ]
        );

        let reversed_rows = conn
            .query("SELECT SUM(value), (id / 10) FROM bench GROUP BY (id / 10);")
            .unwrap();
        assert_eq!(
            reversed_rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Float(50.0), SqliteValue::Integer(0)],
                vec![SqliteValue::Float(150.0), SqliteValue::Integer(1)],
                vec![SqliteValue::Float(112.5), SqliteValue::Integer(2)],
            ]
        );

        conn.execute("CREATE TABLE hidden_rowid_bucket (value INTEGER);")
            .unwrap();
        conn.execute("INSERT INTO hidden_rowid_bucket VALUES (10), (20), (30);")
            .unwrap();
        let hidden_rows = conn
            .query(
                "SELECT (rowid / 2), SUM(value) \
                 FROM hidden_rowid_bucket \
                 GROUP BY (rowid / 2);",
            )
            .unwrap();
        assert_eq!(
            hidden_rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Integer(0), SqliteValue::Integer(10)],
                vec![SqliteValue::Integer(1), SqliteValue::Integer(50)],
            ]
        );
    }

