    #[test]
    fn test_rewrite_dml_from_clause_eagerly_rewrites_subquery_source_in_subqueries() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE src (a INTEGER);").unwrap();
        conn.execute("CREATE TABLE allowed (a INTEGER);").unwrap();
        conn.execute("INSERT INTO src VALUES (1);").unwrap();
        conn.execute("INSERT INTO src VALUES (2);").unwrap();
        conn.execute("INSERT INTO allowed VALUES (2);").unwrap();

        let statement = super::parse_single_statement(
            "UPDATE dst \
             SET a = s.a \
             FROM (SELECT a FROM src WHERE a IN (SELECT a FROM allowed)) AS s \
             WHERE dst.a = s.a;",
        )
        .unwrap();
        let Statement::Update(mut update) = statement else {
            panic!("expected UPDATE statement");
        };
        let from = update.from.as_mut().expect("expected FROM clause");

        conn.rewrite_dml_from_clause(from, true, None).unwrap();

        let fsqlite_ast::TableOrSubquery::Subquery { query, .. } = &from.source else {
            panic!("expected subquery source");
        };
        let fsqlite_ast::SelectCore::Select {
            where_clause: Some(where_clause),
            ..
        } = &query.body.select
        else {
            panic!("expected subquery WHERE clause");
        };
        let fsqlite_ast::Expr::In { set, .. } = where_clause.as_ref() else {
            panic!("expected IN expression");
        };
        assert!(
            matches!(set, fsqlite_ast::InSet::List(_)),
            "eager DML FROM-subquery rewrite should materialize IN subqueries"
        );
    }

