    #[test]
    fn test_join_hidden_rowid_projection_skips_without_rowid_tables() {
        let columns = vec!["id".to_owned(), "payload".to_owned()];
        let mut original_ddl_sql = HashMap::new();
        original_ddl_sql.insert(
            "wr".to_owned(),
            "CREATE TABLE wr (id INTEGER PRIMARY KEY, payload TEXT) WITHOUT ROWID".to_owned(),
        );

        assert!(!join_table_supports_hidden_rowid("wr", &original_ddl_sql));
        assert_eq!(
            join_hidden_rowid_projection(
                &columns,
                join_table_supports_hidden_rowid("wr", &original_ddl_sql),
            ),
            None
        );
    }

    #[test]
    fn test_join_hidden_rowid_projection_skips_virtual_tables() {
        // Regression: FTS5 (and other virtual) tables materialize only their
        // declared columns; appending a hidden rowid projection over-reports
        // scan_width() and slices out of bounds during joins. A virtual table
        // must therefore NOT report hidden-rowid support.
        let columns = vec!["body".to_owned(), "title".to_owned()];
        let mut original_ddl_sql = HashMap::new();
        original_ddl_sql.insert(
            "fts_messages".to_owned(),
            "CREATE VIRTUAL TABLE fts_messages USING fts5(body, title)".to_owned(),
        );

        assert!(!join_table_supports_hidden_rowid(
            "fts_messages",
            &original_ddl_sql
        ));
        assert_eq!(
            join_hidden_rowid_projection(
                &columns,
                join_table_supports_hidden_rowid("fts_messages", &original_ddl_sql),
            ),
            None
        );
    }

    #[test]
    fn test_select_rowid_from_contentless_fts5_does_not_panic() {
        // End-to-end regression for the cass v0.6.2 panic:
        //   connection.rs:53272 "range end index N out of range for slice of length M"
        // cass probes `SELECT rowid FROM fts_messages LIMIT 1` during archive open.
        // A single-table query still flows through the join combiner
        // (table_rows[0] sliced to scan_width), so a virtual-table scan_width
        // over-count panics even with zero JOINs. Mirrors the exact contentless
        // FTS5 schema cass creates.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute_batch(
            "CREATE VIRTUAL TABLE fts_messages USING fts5(\
                 content, title, agent, workspace, source_path, created_at, message_id, \
                 content='', tokenize='porter unicode61');",
        )
        .unwrap();
        // Must not panic; an empty contentless table yields zero rows.
        let rows = conn
            .query("SELECT rowid FROM fts_messages LIMIT 1")
            .unwrap();
        assert!(rows.is_empty());
    }

