    #[test]
    fn test_shadowed_rowid_fast_path_prefers_visible_rowid_but_preserves_oid_lookup() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE shadowed (rowid INTEGER, payload TEXT);")
            .unwrap();
        conn.execute("INSERT INTO shadowed(rowid, payload) VALUES (41, 'alpha');")
            .unwrap();
        conn.execute("INSERT INTO shadowed(rowid, payload) VALUES (42, 'beta');")
            .unwrap();

        let visible = conn
            .query_with_params(
                "SELECT * FROM shadowed WHERE rowid = ?1;",
                &[SqliteValue::Integer(42)],
            )
            .unwrap();
        assert_eq!(
            visible.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(42),
                SqliteValue::Text("beta".into()),
            ]],
        );

        let hidden = conn
            .query_with_params(
                "SELECT * FROM shadowed WHERE oid = ?1;",
                &[SqliteValue::Integer(2)],
            )
            .unwrap();
        assert_eq!(
            hidden.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(42),
                SqliteValue::Text("beta".into()),
            ]],
        );
    }

