    #[test]
    fn test_fsqlite_htm_metrics_table_function_available_via_registry() {
        let conn = Connection::open(":memory:").unwrap();
        let before = conn
            .query(
                "SELECT attempts, aborts_conflict, aborts_capacity, aborts_explicit, aborts_other, aborts_total, success_estimate, abort_rate_pct FROM fsqlite_htm_metrics();",
            )
            .unwrap();
        assert_eq!(
            before.len(),
            1,
            "htm metrics should expose a single snapshot row"
        );

        fsqlite_mvcc::flat_combining::note_htm_attempt();
        fsqlite_mvcc::flat_combining::note_htm_attempt();
        fsqlite_mvcc::flat_combining::note_htm_attempt();
        fsqlite_mvcc::flat_combining::note_htm_abort((1 << 2) | (1 << 1));
        fsqlite_mvcc::flat_combining::note_htm_abort(1 << 3);

        let after = conn
            .query(
                "SELECT attempts, aborts_conflict, aborts_capacity, aborts_explicit, aborts_other, aborts_total, success_estimate, abort_rate_pct FROM fsqlite_htm_metrics();",
            )
            .unwrap();
        assert_eq!(after.len(), 1, "htm metrics should stay single-row");

        let before_values = row_values(&before[0]);
        let after_values = row_values(&after[0]);

        let delta = |idx: usize| {
            let before = match &before_values[idx] {
                SqliteValue::Integer(value) => *value,
                other => panic!("expected integer before value at {idx}, got {other:?}"),
            };
            let after = match &after_values[idx] {
                SqliteValue::Integer(value) => *value,
                other => panic!("expected integer after value at {idx}, got {other:?}"),
            };
            after - before
        };

        assert_eq!(delta(0), 3, "attempts delta should match injected attempts");
        assert_eq!(delta(1), 1, "conflict abort delta should be tracked");
        assert_eq!(delta(2), 1, "capacity abort delta should be tracked");
        assert_eq!(delta(3), 0, "explicit abort delta should remain unchanged");
        assert_eq!(delta(4), 0, "other abort delta should remain unchanged");

        let attempts = match after_values[0] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected attempts integer, got {other:?}"),
        };
        let conflict = match after_values[1] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected conflict integer, got {other:?}"),
        };
        let capacity = match after_values[2] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected capacity integer, got {other:?}"),
        };
        let explicit = match after_values[3] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected explicit integer, got {other:?}"),
        };
        let other = match after_values[4] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected other integer, got {other:?}"),
        };
        let aborts_total = match after_values[5] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected abort total integer, got {other:?}"),
        };
        let success_estimate = match after_values[6] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected success estimate integer, got {other:?}"),
        };
        let abort_rate_pct = match after_values[7] {
            SqliteValue::Integer(value) => value,
            ref other => panic!("expected abort rate integer, got {other:?}"),
        };

        assert_eq!(aborts_total, conflict + capacity + explicit + other);
        assert_eq!(success_estimate, attempts - aborts_total);
        assert_eq!(
            abort_rate_pct,
            if attempts == 0 {
                0
            } else {
                aborts_total * 100 / attempts
            }
        );
    }

    #[test]
    fn test_htm_metrics_cursor_past_end_returns_null_and_zero_rowid() {
        let mut cursor = super::HtmMetricsCursor::default();
        let cx = Cx::new();
        cursor.filter(&cx, 0, None, &[]).unwrap();
        cursor.next(&cx).unwrap();
        assert!(cursor.eof());

        let mut ctx = fsqlite_func::vtab::ColumnContext::new();
        cursor.column(&mut ctx, 0).unwrap();
        assert_eq!(ctx.take_value(), Some(SqliteValue::Null));
        assert_eq!(cursor.rowid().unwrap(), 0);
    }

    #[test]
    fn test_fsqlite_cache_pages_table_function_available_via_registry() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE cache_probe (id INTEGER PRIMARY KEY, payload TEXT);")
            .unwrap();
        conn.execute("INSERT INTO cache_probe(id, payload) VALUES (1, 'alpha');")
            .unwrap();
        let _ = conn.query("SELECT payload FROM cache_probe;").unwrap();

        let cx = Cx::new();
        let mut txn = conn.pager.begin(&cx, TransactionMode::ReadOnly).unwrap();
        let _ = txn.get_page(&cx, PageNumber::ONE).unwrap();
        txn.rollback(&cx).unwrap();

        let expected = conn.pager.cache_page_snapshots().unwrap();
        assert!(
            !expected.is_empty(),
            "cache page diagnostics should expose at least one resident page"
        );

        let rows = conn
            .query(
                "SELECT pgno, version_txn_id, in_t1_or_t2, dirty, ref_count, access_count \
                 FROM fsqlite_cache_pages() ORDER BY pgno;",
            )
            .unwrap();
        assert!(
            rows.len() == expected.len(),
            "cache page diagnostics should expose every resident page: sql={} pager={}",
            rows.len(),
            expected.len()
        );

        for (row, snapshot) in rows.iter().zip(expected.iter()) {
            let expected_version = snapshot
                .version_txn_id
                .and_then(|value| i64::try_from(value).ok())
                .map_or(SqliteValue::Null, SqliteValue::Integer);
            let expected_queue = match snapshot.queue {
                Some(PageCacheQueueKind::T1) => SqliteValue::Text("t1".into()),
                Some(PageCacheQueueKind::T2) => SqliteValue::Text("t2".into()),
                _ => SqliteValue::Null,
            };
            assert_eq!(
                row_values(row),
                vec![
                    SqliteValue::Integer(i64::from(snapshot.page_no.get())),
                    expected_version,
                    expected_queue,
                    SqliteValue::Integer(if snapshot.dirty { 1 } else { 0 }),
                    SqliteValue::Integer(i64::from(snapshot.ref_count)),
                    SqliteValue::Integer(i64::try_from(snapshot.access_count).unwrap_or(i64::MAX)),
                ],
            );
        }
    }

    #[test]
    fn test_fsqlite_cache_pages_table_function_is_read_only_observer() {
        let conn = Connection::open(":memory:").unwrap();
        conn.query("PRAGMA fsqlite_cache_reset;").unwrap();

        let cx = Cx::new();
        let mut txn = conn.pager.begin(&cx, TransactionMode::ReadOnly).unwrap();
        let _ = txn.get_page(&cx, PageNumber::ONE).unwrap();
        txn.rollback(&cx).unwrap();

        let before = conn.pager.cache_metrics_snapshot().unwrap();
        let rows = conn
            .query("SELECT pgno, access_count FROM fsqlite_cache_pages() ORDER BY pgno;")
            .unwrap();
        assert!(
            !rows.is_empty(),
            "cache monitor table should return resident pages without mutating cache state"
        );
        let after = conn.pager.cache_metrics_snapshot().unwrap();
        assert_eq!(
            after, before,
            "cache observer must not perturb pager metrics"
        );
    }

