    #[test]
    fn test_blob_literal_codegen_emits_p4_bytes() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (bl BLOB);").unwrap();

        let stmt = super::parse_single_statement("INSERT INTO t VALUES (X'DEADBEEF');").unwrap();
        let insert = match stmt {
            Statement::Insert(insert) => insert,
            other => unreachable!("expected INSERT statement, got {other:?}"),
        };

        let program = conn.compile_table_insert(&insert).unwrap();
        let blob_ops: Vec<_> = program
            .ops()
            .iter()
            .filter(|op| op.opcode == Opcode::Blob)
            .collect();

        assert!(
            !blob_ops.is_empty(),
            "expected at least one OP_Blob, found {}",
            blob_ops.len()
        );
        // The blob literal's P4 bytes should appear in at least one OP_Blob.
        let has_deadbeef = blob_ops
            .iter()
            .any(|op| matches!(&op.p4, P4::Blob(bytes) if bytes == &vec![0xDE, 0xAD, 0xBE, 0xEF]));
        assert!(
            has_deadbeef,
            "expected at least one OP_Blob with P4::Blob([0xDE, 0xAD, 0xBE, 0xEF])"
        );
    }

