    #[test]
    fn test_memory_synthetic_publication_preserves_schema_visibility_after_ddl() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT);")
            .unwrap();

        let cx = conn.op_cx().unwrap();
        assert!(
            conn.cached_write_txn.borrow().is_none(),
            "DDL autocommit should not retain the cached write txn on :memory:"
        );
        let fresh_read_txn_contains_t = {
            let mut txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::ReadOnly)
                .expect("fresh read txn should open");
            let page1 = txn.get_page(&cx, PageNumber::ONE).unwrap();
            let header = super::parse_database_header_checked(page1.as_ref()).unwrap();
            let mut cursor = Connection::new_header_btree_cursor(
                &mut txn,
                PageNumber::ONE,
                header.page_size,
                header.reserved_per_page,
                true,
            );
            let mut found = false;
            if cursor.first(&cx).unwrap() {
                loop {
                    let payload = cursor.payload(&cx).unwrap();
                    let values = super::parse_record(&payload).unwrap();
                    if let Some(SqliteValue::Text(name)) = values.get(1)
                        && name.eq_ignore_ascii_case("t")
                    {
                        found = true;
                        break;
                    }
                    if !cursor.next(&cx).unwrap() {
                        break;
                    }
                }
            }
            txn.rollback(&cx).unwrap();
            found
        };
        assert!(
            fresh_read_txn_contains_t,
            "sqlite_master visibility after CREATE TABLE regressed in a fresh read transaction"
        );
        assert!(
            conn.schema
                .borrow()
                .iter()
                .any(|table| table.name.eq_ignore_ascii_case("t")),
            "CREATE TABLE should leave the connection schema aware of `t`"
        );

        let stmt = conn.prepare("INSERT INTO t VALUES (?1, 'val');").unwrap();
        let affected = stmt
            .execute_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(affected, 1);
    }

