    #[test]
    fn test_commit_fails_when_concurrent_session_is_missing() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER);")
            .unwrap();
        conn.execute("BEGIN CONCURRENT;").unwrap();
        conn.execute("INSERT INTO t VALUES (1, 1);").unwrap();

        // Simulate a stale/missing MVCC session and ensure COMMIT fails closed
        // instead of bypassing FCW/SSI planning.
        *conn.concurrent_session_id.borrow_mut() = None;

        let err = conn.execute("COMMIT;").expect_err(
            "concurrent commit must fail when session is missing; rollback is required",
        );
        match err {
            FrankenError::Internal(message) => {
                assert!(
                    message.contains("rollback required"),
                    "expected rollback-required guardrail message, got: {message}"
                );
            }
            other => panic!(
                "expected Internal rollback-required error for missing concurrent session, got {other:?}"
            ),
        }
    }

    #[test]
    fn test_commit_planning_tracks_existing_freelist_trunk_pages_from_pending_commit_surface() {
        use fsqlite_pager::TransactionMode;

        let conn = Connection::open(":memory:").unwrap();
        let cx = conn.op_cx().unwrap();
        let ps = PageSize::MIN.as_usize();

        let (p2, p3) = {
            let mut seed = conn.pager.begin(&cx, TransactionMode::Immediate).unwrap();
            let p2 = seed.allocate_page(&cx).unwrap();
            let p3 = seed.allocate_page(&cx).unwrap();
            seed.write_page(&cx, p2, &vec![0x11; ps]).unwrap();
            seed.write_page(&cx, p3, &vec![0x22; ps]).unwrap();
            seed.commit(&cx).unwrap();
            (p2, p3)
        };

        {
            let mut establish_committed_freelist =
                conn.pager.begin(&cx, TransactionMode::Immediate).unwrap();
            establish_committed_freelist.free_page(&cx, p2).unwrap();
            establish_committed_freelist.commit(&cx).unwrap();
        }

        conn.execute("BEGIN CONCURRENT;").unwrap();
        let session_id = conn
            .concurrent_session_id
            .borrow()
            .expect("BEGIN CONCURRENT should register a session");

        let conflict_surface = {
            let mut txn_guard = conn.active_txn.borrow_mut();
            let txn = txn_guard
                .as_mut()
                .expect("concurrent transaction should keep an active pager handle");
            txn.free_page(&cx, p3).unwrap();
            let predicted = txn.pending_conflict_pages().unwrap();
            assert!(
                predicted.contains(&p2),
                "commit planning must still see the committed freelist trunk page in the conflict surface"
            );
            predicted
        };

        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            let handle = registry
                .get(session_id)
                .expect("concurrent handle should be present before commit planning");
            assert!(
                !handle.tracks_write_conflict_page(p2),
                "precondition: the existing committed freelist trunk page should not already be tracked before commit planning"
            );
        }

        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            conn.track_pending_conflict_pages_with_registry(
                &registry,
                session_id,
                &conflict_surface,
            )
            .expect("commit planning should track pending conflict pages before SSI validation");
        }

        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            let handle = registry
                .get(session_id)
                .expect("concurrent handle should remain present after pending surface tracking");
            assert!(
                handle.tracks_write_conflict_page(p2),
                "commit planning must acquire the existing committed freelist trunk page before validation"
            );
            assert!(
                handle.held_locks().contains(&p2),
                "commit planning must hold the committed freelist trunk page lock once it becomes part of the pending surface"
            );
        }

        conn.execute("ROLLBACK;").unwrap();
    }

    #[test]
    fn test_commit_planning_tracks_free_only_conservative_surface() {
        use fsqlite_pager::TransactionMode;

        let conn = Connection::open(":memory:").unwrap();
        let cx = conn.op_cx().unwrap();
        let page_size = conn.pager.page_size().as_usize();

        let (first_freed, second_freed) = {
            let mut seed = conn.pager.begin(&cx, TransactionMode::Immediate).unwrap();
            let first = seed.allocate_page(&cx).unwrap();
            let second = seed.allocate_page(&cx).unwrap();
            seed.write_page(&cx, first, &vec![0x31; page_size]).unwrap();
            seed.write_page(&cx, second, &vec![0x32; page_size])
                .unwrap();
            seed.commit(&cx).unwrap();
            (first, second)
        };

        let prepare_free_only_surface = || {
            conn.execute("BEGIN CONCURRENT;").unwrap();
            let session_id = conn
                .concurrent_session_id
                .borrow()
                .expect("BEGIN CONCURRENT should register a session");
            let surface = {
                let mut txn_guard = conn.active_txn.borrow_mut();
                let txn = txn_guard
                    .as_mut()
                    .expect("concurrent transaction should keep an active pager handle");
                txn.free_page(&cx, first_freed).unwrap();
                txn.free_page(&cx, second_freed).unwrap();
                assert!(
                    txn.write_set_page_numbers().is_empty(),
                    "the regression requires a genuinely free-only pager transaction"
                );
                txn.pending_conflict_pages_conservative()
            };
            assert_eq!(
                surface,
                vec![PageNumber::ONE, first_freed, second_freed],
                "lock-free commit planning must carry freed pages and the shared freelist metadata token"
            );
            (session_id, surface)
        };

        let (first_session, first_surface) = prepare_free_only_surface();
        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            conn.track_pending_conflict_pages_with_registry(
                &registry,
                first_session,
                &first_surface,
            )
            .unwrap();
            let handle = registry
                .get(first_session)
                .expect("first free-only session should remain active");
            for page in &first_surface {
                assert!(
                    handle.tracks_write_conflict_page(*page),
                    "commit planning must track free-only conflict page {page}"
                );
                assert!(
                    handle.held_locks().contains(page),
                    "commit planning must lock free-only conflict page {page}"
                );
            }
        }
        conn.execute("ROLLBACK;").unwrap();

        let (second_session, second_surface) = prepare_free_only_surface();
        let snapshot_high = {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            registry
                .get(second_session)
                .expect("second free-only session should remain active")
                .snapshot()
                .high
        };
        conn.concurrent_commit_index
            .update(first_freed, snapshot_high.next());
        let conflict = {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            conn.track_pending_conflict_pages_with_registry(
                &registry,
                second_session,
                &second_surface,
            )
            .expect_err("a newer freed-page publication must fail first-committer-wins")
        };
        assert!(
            matches!(conflict, FrankenError::BusySnapshot { .. }),
            "free-only FCW conflict must fail with BusySnapshot, got {conflict:?}"
        );
        conn.execute("ROLLBACK;").unwrap();
    }

    #[test]
    fn test_commit_planning_ignores_synthetic_page_one_for_disjoint_concurrent_growth_writers() {
        let _serial = super::fsqlite_core_test_serializer();
        use fsqlite_pager::{JournalMode, TransactionMode};
        use fsqlite_types::Snapshot;

        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("synthetic_page_one_growth.db");
        let conn = Connection::open(db_path.to_str().unwrap()).unwrap();
        assert_eq!(conn.pager.journal_mode(), JournalMode::Wal);

        let cx = conn.op_cx().unwrap();
        let ps = conn.pager.page_size().as_usize();

        let (conflict_one, conflict_two, page_one_data, page_two_data) = {
            let mut txn_one = conn.pager.begin(&cx, TransactionMode::Concurrent).unwrap();
            let mut txn_two = conn.pager.begin(&cx, TransactionMode::Concurrent).unwrap();

            let page_one_data = txn_one.allocate_page(&cx).unwrap();
            txn_one
                .write_page(&cx, page_one_data, &vec![0xA1; ps])
                .unwrap();

            let page_two_data = txn_two.allocate_page(&cx).unwrap();
            txn_two
                .write_page(&cx, page_two_data, &vec![0xB2; ps])
                .unwrap();

            assert_ne!(
                page_one_data, page_two_data,
                "concurrent growth writers must allocate distinct data pages for this proof"
            );

            let predicted_one = txn_one.pending_commit_pages().unwrap();
            let predicted_two = txn_two.pending_commit_pages().unwrap();
            let conflict_one = txn_one.pending_conflict_pages().unwrap();
            let conflict_two = txn_two.pending_conflict_pages().unwrap();

            assert!(
                !predicted_one.contains(&PageNumber::ONE),
                "pure WAL growth keeps commit-time synthetic page 1 out of the pre-commit surface"
            );
            assert!(
                !predicted_two.contains(&PageNumber::ONE),
                "a second pure WAL growth writer also keeps synthetic page 1 out of the pre-commit surface"
            );
            assert!(
                predicted_one.contains(&page_one_data) && !predicted_one.contains(&page_two_data),
                "first writer should only contribute its own data page plus structural pages"
            );
            assert!(
                predicted_two.contains(&page_two_data) && !predicted_two.contains(&page_one_data),
                "second writer should only contribute its own data page plus structural pages"
            );
            assert!(
                !conflict_one.contains(&PageNumber::ONE),
                "synthetic WAL page-1 growth metadata must not participate in FCW for the first writer"
            );
            assert!(
                !conflict_two.contains(&PageNumber::ONE),
                "synthetic WAL page-1 growth metadata must not participate in FCW for the second writer"
            );
            assert!(
                conflict_one.contains(&page_one_data) && !conflict_one.contains(&page_two_data),
                "the first writer's conflict surface should retain only its real data page"
            );
            assert!(
                conflict_two.contains(&page_two_data) && !conflict_two.contains(&page_one_data),
                "the second writer's conflict surface should retain only its real data page"
            );

            (conflict_one, conflict_two, page_one_data, page_two_data)
        };

        let snapshot = Snapshot::new(CommitSeq::ZERO, SchemaEpoch::new(0));
        let (session_one, session_two) = {
            let mut registry = lock_unpoisoned(&conn.concurrent_registry);
            (
                registry.begin_concurrent(snapshot).unwrap(),
                registry.begin_concurrent(snapshot).unwrap(),
            )
        };

        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            conn.track_pending_conflict_pages_with_registry(&registry, session_one, &conflict_one)
                .expect("first disjoint growth writer should track only its real conflict surface");
        }

        conn.concurrent_commit_index
            .update(PageNumber::ONE, CommitSeq::new(1));

        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            conn.track_pending_conflict_pages_with_registry(&registry, session_two, &conflict_two)
                .expect(
                    "stale page-one publish must not block the second disjoint growth writer once page 1 is removed from the FCW surface",
                );
        }

        {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            let handle_one = registry
                .get(session_one)
                .expect("session one handle missing");
            let handle_two = registry
                .get(session_two)
                .expect("session two handle missing");
            assert!(
                !handle_one.tracks_write_conflict_page(PageNumber::ONE),
                "the first writer must not synthesize page 1 into its tracked FCW surface"
            );
            assert!(
                !handle_two.tracks_write_conflict_page(PageNumber::ONE),
                "the second writer must not synthesize page 1 into its tracked FCW surface"
            );
            assert!(
                handle_one.tracks_write_conflict_page(page_one_data),
                "the first writer must still track its real data page {}",
                page_one_data.get()
            );
            assert!(
                handle_two.tracks_write_conflict_page(page_two_data),
                "the second writer must still track its real data page {}",
                page_two_data.get()
            );
        }
    }

    #[test]
    fn test_concurrent_mode_with_single_vs_mvcc_workload() {
        // Run the same workload in both modes and verify the report
        // notes capture the correct mode label.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT);")
            .unwrap();

        // Single-writer mode (explicitly disable concurrent default).
        conn.execute("PRAGMA concurrent_mode=OFF;").unwrap();
        conn.execute("BEGIN;").unwrap();
        assert!(!conn.is_concurrent_transaction());
        conn.execute("INSERT INTO t VALUES (1, 'a');").unwrap();
        conn.execute("COMMIT;").unwrap();

        // MVCC concurrent mode (re-enable).
        conn.execute("PRAGMA concurrent_mode=ON;").unwrap();
        conn.execute("BEGIN;").unwrap();
        assert!(conn.is_concurrent_transaction());
        conn.execute("INSERT INTO t VALUES (2, 'b');").unwrap();
        conn.execute("COMMIT;").unwrap();

        // Verify both rows exist.
        let rows = conn.query("SELECT COUNT(*) FROM t;").unwrap();
        assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(2));
    }

