    fn assert_ambiguous_column(error: FrankenError, expected: &str) {
        assert!(
            matches!(error, FrankenError::AmbiguousColumn { ref name } if name == expected),
            "unexpected error: {error:?}"
        );
    }

    fn assert_column_not_found(error: FrankenError, expected: &str) {
        let message = error.to_string();
        assert!(
            message.contains("column not found") && message.contains(expected),
            "unexpected error: {error:?}"
        );
    }

