    #[test]
    fn test_persist_begin_insert_rollback_no_changes() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("test.db");
        let db_str = db_path.to_str().unwrap();

        // Create the table (outside any explicit transaction).
        {
            let conn = Connection::open(db_str).unwrap();
            conn.execute("CREATE TABLE t (x INTEGER)").unwrap();
        }

        // Begin, insert, then rollback.
        {
            let conn = Connection::open(db_str).unwrap();
            conn.execute("BEGIN").unwrap();
            conn.execute("INSERT INTO t VALUES (99)").unwrap();
            conn.execute("ROLLBACK").unwrap();

            // Within the same connection, data should be gone.
            let rows = conn.query("SELECT x FROM t").unwrap();
            assert!(rows.is_empty(), "rollback should discard INSERT");
        }

        // Re-open: data should still be gone.
        {
            let conn = Connection::open(db_str).unwrap();
            let rows = conn.query("SELECT x FROM t").unwrap();
            assert!(rows.is_empty(), "rolled-back data must not persist to disk");
        }
    }

    #[test]
    fn test_reload_memdb_from_pager_handles_multi_page_table_scan() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("reload-multipage.db");
        let db_str = db_path.to_str().unwrap();

        let conn = Connection::open(db_str).unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, payload TEXT)")
            .unwrap();

        let payload = "x".repeat(256);
        for id in 1..=1_024 {
            let sql = format!("INSERT INTO t VALUES ({id}, '{payload}')");
            conn.execute(&sql).unwrap();
        }

        let root_page = {
            let schema = conn.schema.borrow();
            schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .map(|table| table.root_page)
                .expect("table root page should exist")
        };
        let cx = Cx::new();
        let txn = conn.pager.begin(&cx, TransactionMode::Deferred).unwrap();
        let root_pgno = PageNumber::new(u32::try_from(root_page).unwrap()).unwrap();
        let root_page_data = txn.get_page(&cx, root_pgno).unwrap();
        assert_eq!(
            root_page_data.as_ref()[0],
            0x05,
            "test must force an interior table root so reload traverses multiple levels"
        );

        let reload_cx = conn.op_cx().unwrap();
        conn.reload_memdb_from_pager(&reload_cx).unwrap();

        let count_rows = conn.query("SELECT COUNT(*) FROM t").unwrap();
        assert_eq!(
            count_rows[0].get(0),
            Some(&SqliteValue::Integer(1_024)),
            "reload must preserve every row in a multi-page table"
        );
        let max_rows = conn.query("SELECT MAX(id) FROM t").unwrap();
        assert_eq!(
            max_rows[0].get(0),
            Some(&SqliteValue::Integer(1_024)),
            "reload must keep table traversal semantics for rightmost rows"
        );
    }

    #[test]
    fn test_reload_memdb_from_pager_preserves_live_vtab_instance_after_local_file_backed_commit() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("reload-local-vtab.db");
        let db_str = db_path.to_str().unwrap();

        let conn = Connection::open(db_str).unwrap();
        conn.execute("CREATE VIRTUAL TABLE docs USING fts5(title, body, tokenize='porter')")
            .unwrap();
        conn.execute("INSERT INTO docs(rowid, title, body) VALUES (1, 'hello', 'rust world');")
            .unwrap();

        let before_ptr = live_vtab_instance_ptr(&conn, "docs");
        let reload_cx = conn.op_cx().unwrap();
        conn.reload_memdb_from_pager(&reload_cx).unwrap();
        let after_ptr = live_vtab_instance_ptr(&conn, "docs");

        assert_eq!(
            before_ptr, after_ptr,
            "schema-stable reload after a local commit should preserve the existing live vtab instance"
        );

        let rows = conn
            .query("SELECT rowid FROM docs WHERE docs MATCH 'rust' ORDER BY rowid;")
            .unwrap();
        assert_eq!(
            rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![SqliteValue::Integer(1)]],
        );
    }

    #[test]
    fn test_reload_memdb_from_pager_preserves_live_vtab_instance_after_local_memory_commit() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE VIRTUAL TABLE docs USING fts5(title, body, tokenize='porter')")
            .unwrap();
        conn.execute("INSERT INTO docs(rowid, title, body) VALUES (1, 'hello', 'rust world');")
            .unwrap();

        let before_ptr = live_vtab_instance_ptr(&conn, "docs");
        let reload_cx = conn.op_cx().unwrap();
        conn.reload_memdb_from_pager(&reload_cx).unwrap();
        let after_ptr = live_vtab_instance_ptr(&conn, "docs");

        assert_eq!(
            before_ptr, after_ptr,
            "schema-stable reload after a local :memory: commit should preserve the existing live vtab instance"
        );

        let rows = conn
            .query("SELECT rowid FROM docs WHERE docs MATCH 'rust' ORDER BY rowid;")
            .unwrap();
        assert_eq!(
            rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![SqliteValue::Integer(1)]],
        );
    }

    #[test]
    fn test_reload_memdb_from_pager_rebuilds_live_vtab_instance_after_external_commit() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("reload-external-vtab.db");
        let db_str = db_path.to_str().unwrap();

        let conn = Connection::open(db_str).unwrap();
        conn.execute("CREATE VIRTUAL TABLE docs USING fts5(title, body, tokenize='porter')")
            .unwrap();
        conn.execute("INSERT INTO docs(rowid, title, body) VALUES (1, 'hello', 'rust world');")
            .unwrap();
        let before_ptr = live_vtab_instance_ptr(&conn, "docs");

        let other = Connection::open(db_str).unwrap();
        other
            .execute("INSERT INTO docs(rowid, title, body) VALUES (2, 'outside', 'beta term');")
            .unwrap();

        let reload_cx = conn.op_cx().unwrap();
        conn.reload_memdb_from_pager(&reload_cx).unwrap();
        let after_ptr = live_vtab_instance_ptr(&conn, "docs");

        assert_ne!(
            before_ptr, after_ptr,
            "reload must rebuild the live vtab instance when another connection commits new rows"
        );

        let rows = conn
            .query("SELECT rowid FROM docs WHERE docs MATCH 'beta' ORDER BY rowid;")
            .unwrap();
        assert_eq!(
            rows.iter().map(row_values).collect::<Vec<_>>(),
            vec![vec![SqliteValue::Integer(2)]],
        );
    }

