    #[test]
    fn test_recursive_cte_direct_sum_consumer_restores_reject_mem_fallback_on_error() {
        let _serial = super::fsqlite_core_test_serializer();
        FSQLITE_RECURSIVE_CTE_DIRECT_SUM_CONSUMER_HITS.store(0, AtomicOrdering::Relaxed);

        let conn = Connection::open(":memory:").unwrap();
        conn.set_reject_mem_fallback(true);
        let err = conn
            .query_row(
                "WITH RECURSIVE cnt(x) AS (\
                   SELECT 9223372036854775807 \
                   UNION ALL \
                   SELECT 1 \
                   UNION ALL \
                   SELECT x FROM cnt WHERE 0\
                 ) SELECT SUM(x) FROM cnt",
            )
            .expect_err("overflowing recursive SUM should error");

        assert!(
            matches!(err, fsqlite_error::FrankenError::IntegerOverflow),
            "unexpected recursive SUM overflow error: {err:?}"
        );
        assert!(
            *conn.reject_mem_fallback.borrow(),
            "reject_mem_fallback should be restored after direct SUM errors"
        );
    }

