    #[test]
    fn test_drop_materialized_virtual_table_preserves_shadow_named_user_tables() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE VIRTUAL TABLE docs USING fts5(content)")
            .unwrap();
        // `docs_data` is now a REAL shadow table owned by `docs` (the
        // rootpage-zero shadow-backed FTS5 model reserves the _content/_data/
        // _idx/_docsize suffixes), so a user table cannot claim that name. The
        // surviving intent of this test is that DROP TABLE on the FTS5 vtab
        // cascades to its own shadow tables ONLY and leaves an unrelated user
        // table — one whose name merely *resembles* a shadow suffix but is
        // owned by no virtual table — untouched.
        conn.execute("CREATE TABLE notes_data (marker INTEGER);")
            .unwrap();
        conn.execute("INSERT INTO notes_data VALUES (42);").unwrap();

        conn.execute("DROP TABLE docs;").unwrap();

        // The vtab and all of its owned shadow tables are gone.
        let dropped = conn
            .query(
                "SELECT COUNT(*) FROM sqlite_master \
                 WHERE type = 'table' \
                   AND name IN ('docs', 'docs_data', 'docs_content', 'docs_idx', 'docs_docsize');",
            )
            .unwrap();
        assert_eq!(dropped[0].values()[0], SqliteValue::Integer(0));
        // The unrelated, shadow-resembling user table survives intact.
        let preserved = conn.query("SELECT marker FROM notes_data;").unwrap();
        assert_eq!(preserved[0].values()[0], SqliteValue::Integer(42));
    }

    #[test]
    fn test_reopen_keeps_materialized_virtual_tables_with_real_root_page() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("materialized_vtab_reopen.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("CREATE VIRTUAL TABLE docs USING fts5(subject, body, tokenize='porter')")
                .unwrap();
            conn.execute(
                "INSERT INTO docs(rowid, subject, body) VALUES (1, 'Hello', 'Rust world')",
            )
            .unwrap();
            conn.execute("INSERT INTO docs(rowid, subject, body) VALUES (2, 'Other', 'Nothing')")
                .unwrap();

            let root_page = match &conn
                .query("SELECT rootpage FROM sqlite_master WHERE name = 'docs'")
                .unwrap()[0]
                .values()[0]
            {
                SqliteValue::Integer(value) => *value,
                other => panic!("expected integer rootpage, got {other:?}"),
            };
            // FrankenSQLite-created FTS5 tables are now stock-compatible
            // rootpage=0 virtual tables backed by real shadow tables (359eb0a3 /
            // the shadow-backed FTS5 contract: "Catalog row for the virtual
            // table uses rootpage=0" is mandatory parity). The durable state
            // lives in the _content/_data/_idx/_docsize shadow tables, not in a
            // positive-rootpage materialized b-tree, so the catalog row must
            // carry rootpage=0 — and the table must still survive reopen with
            // its rows fully readable (asserted below).
            assert_eq!(
                root_page, 0,
                "FrankenSQLite-created FTS5 virtual table must use a stock-compatible rootpage=0 catalog row"
            );
            conn.close().unwrap();
        }

        let conn = Connection::open(&db_str).unwrap();
        let schema = conn.schema.borrow();
        let table = schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case("docs"))
            .expect("materialized virtual table should survive schema reload");
        let column_names: Vec<&str> = table
            .columns
            .iter()
            .map(|column| column.name.as_str())
            .collect();
        assert_eq!(column_names, vec!["subject", "body"]);
        drop(schema);

        let rows = conn
            .query("SELECT rowid, subject, body FROM docs ORDER BY rowid")
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
        assert_eq!(rows[0].values()[1], SqliteValue::Text("Hello".into()));
        assert_eq!(rows[0].values()[2], SqliteValue::Text("Rust world".into()));
        assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
        assert_eq!(rows[1].values()[1], SqliteValue::Text("Other".into()));
        assert_eq!(rows[1].values()[2], SqliteValue::Text("Nothing".into()));
    }

    /// bd-fts5-lazy-shadow-reads-itcc4.1: the lazy `Fts5OnDiskReader` must
    /// point-read a persisted FTS5 table's shadow b-trees correctly. The
    /// fixture is built by *stock* SQLite (rusqlite), so this doubles as a
    /// format-interop check: frankensqlite reads a standard FTS5 index.
    #[cfg(all(unix, feature = "ext-fts5"))]
    #[test]
    fn test_fts5_live_shadow_reader_reads_persisted_index() {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("fts5_live_reader_fixture.db");
        let db_str = db_path.to_string_lossy().into_owned();

        // Build a standard on-disk FTS5 index with stock SQLite. `optimize`
        // flushes pending postings into on-disk segments so `_data`/`_idx`/
        // `_docsize`/`_content` are all populated.
        {
            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            sqlite
                .execute_batch(
                    "CREATE VIRTUAL TABLE docs USING fts5(body);\n\
                     INSERT INTO docs(rowid, body) VALUES (1, 'alpha rust beta');\n\
                     INSERT INTO docs(rowid, body) VALUES (2, 'gamma rust delta');\n\
                     INSERT INTO docs(docs) VALUES('optimize');",
                )
                .unwrap();
            sqlite.close().unwrap();
        }

        let conn = Connection::open(&db_str).unwrap();
        let root = |name: &str| -> Option<fsqlite_types::PageNumber> {
            let rows = conn
                .query(&format!(
                    "SELECT rootpage FROM sqlite_master WHERE name = '{name}';"
                ))
                .ok()?;
            let raw = rows.first()?.values().first()?.to_integer();
            fsqlite_types::PageNumber::new(u32::try_from(raw).ok()?)
        };
        let data_root = root("docs_data").expect("docs_data rootpage");
        let idx_root = root("docs_idx");
        let docsize_root = root("docs_docsize");
        let content_root = root("docs_content");

        conn.with_integrity_txn(|cx, txn| {
            let page1 = txn.get_page(cx, fsqlite_types::PageNumber::ONE)?;
            let header = super::parse_database_header_checked(page1.as_ref())?;
            let registry = std::sync::Arc::new(std::sync::Mutex::new(
                fsqlite_func::collation::CollationRegistry::new(),
            ));
            let mut reader = super::Fts5LiveShadowReader::with_roots(
                cx,
                txn,
                header.page_size,
                header.reserved_per_page,
                data_root,
                idx_root,
                docsize_root,
                content_root,
                registry,
            );

            // Special `_data` rows: id=1 averages, id=10 structure.
            assert!(reader.read_data_block(1)?.is_some(), "averages row (id=1)");
            assert!(
                reader.read_data_block(10)?.is_some(),
                "structure row (id=10)"
            );
            assert!(
                reader.read_data_block(123_456_789)?.is_none(),
                "absent _data id -> None"
            );

            // Content point reads for known rowids + absent -> None.
            assert_eq!(
                reader.read_content(1, 1)?.expect("content for rowid 1"),
                vec!["alpha rust beta".to_owned()],
            );
            assert_eq!(
                reader.read_content(2, 1)?.expect("content for rowid 2"),
                vec!["gamma rust delta".to_owned()],
            );
            assert!(
                reader.read_content(9999, 1)?.is_none(),
                "absent content rowid -> None"
            );

            // Docsize token counts (alpha rust beta = 3 tokens).
            assert_eq!(
                reader
                    .read_docsize(1, 1)?
                    .expect("docsize for rowid 1")
                    .total_tokens(),
                3,
            );

            Ok(())
        })
        .unwrap();
    }

    /// bd-fts5-lazy-shadow-reads-itcc4.2(a): the lazy on-disk segment scan
    /// (`lazy_exact_doclist_entries`) must return exactly the documents a term
    /// occurs in, reading only the leaf pages it needs — driven by the `.1`
    /// reader over a stock-SQLite-built index.
    #[cfg(all(unix, feature = "ext-fts5"))]
    #[test]
    fn test_fts5_lazy_exact_doclist_entries_match_known_terms() {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("fts5_lazy_doclist_fixture.db");
        let db_str = db_path.to_string_lossy().into_owned();

        {
            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            sqlite
                .execute_batch(
                    "CREATE VIRTUAL TABLE docs USING fts5(body);\n\
                     INSERT INTO docs(rowid, body) VALUES (1, 'alpha rust beta');\n\
                     INSERT INTO docs(rowid, body) VALUES (2, 'gamma rust delta');\n\
                     INSERT INTO docs(rowid, body) VALUES (3, 'epsilon zeta');\n\
                     INSERT INTO docs(docs) VALUES('optimize');",
                )
                .unwrap();
            sqlite.close().unwrap();
        }

        let conn = Connection::open(&db_str).unwrap();
        let root = |name: &str| -> Option<fsqlite_types::PageNumber> {
            let rows = conn
                .query(&format!(
                    "SELECT rootpage FROM sqlite_master WHERE name = '{name}';"
                ))
                .ok()?;
            let raw = rows.first()?.values().first()?.to_integer();
            fsqlite_types::PageNumber::new(u32::try_from(raw).ok()?)
        };
        let data_root = root("docs_data").expect("docs_data rootpage");
        let idx_root = root("docs_idx");
        let docsize_root = root("docs_docsize");
        let content_root = root("docs_content");

        conn.with_integrity_txn(|cx, txn| {
            let page1 = txn.get_page(cx, fsqlite_types::PageNumber::ONE)?;
            let header = super::parse_database_header_checked(page1.as_ref())?;
            let registry = std::sync::Arc::new(std::sync::Mutex::new(
                fsqlite_func::collation::CollationRegistry::new(),
            ));
            let mut reader = super::Fts5LiveShadowReader::with_roots(
                cx,
                txn,
                header.page_size,
                header.reserved_per_page,
                data_root,
                idx_root,
                docsize_root,
                content_root,
                registry,
            );

            let structure_block = reader.read_data_block(10)?.expect("structure row (id=10)");
            let structure = fsqlite_ext_fts5::Fts5StructureRecord::decode(&structure_block)?;

            let mut rowids = |term: &[u8]| -> Result<Vec<u64>> {
                let mut ids: Vec<u64> =
                    fsqlite_ext_fts5::lazy_exact_doclist_entries(&mut reader, &structure, term)?
                        .into_iter()
                        .map(|entry| entry.rowid)
                        .collect();
                ids.sort_unstable();
                ids.dedup();
                Ok(ids)
            };

            assert_eq!(rowids(b"rust")?, vec![1, 2], "'rust' is in docs 1 and 2");
            assert_eq!(rowids(b"alpha")?, vec![1], "'alpha' only in doc 1");
            assert_eq!(rowids(b"zeta")?, vec![3], "'zeta' only in doc 3");
            assert!(rowids(b"nonexistent")?.is_empty(), "absent term -> no docs");

            Ok(())
        })
        .unwrap();
    }

    /// bd-fts5-lazy-shadow-reads-itcc4.3: multi-segment recency parity. With
    /// docs spread across many on-disk segments (separate autocommit inserts)
    /// plus a DELETE and an UPDATE, stock SQLite records the removals as
    /// delete-markers / tombstones in NEWER segments while the original live
    /// postings still physically exist in older segments. The lazy merge must
    /// apply FTS5 newest-wins recency per `(term, rowid)` so a deleted or
    /// updated-away document never resurfaces. Stock is the oracle.
    #[cfg(all(unix, feature = "ext-fts5"))]
    #[test]
    fn test_fts5_lazy_query_matches_stock_after_multisegment_delete_update() {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("fts5_multiseg_recency.db");
        let db_str = db_path.to_string_lossy().into_owned();

        {
            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            sqlite
                .execute_batch("CREATE VIRTUAL TABLE docs USING fts5(body);")
                .unwrap();
            // Separate autocommit statements => separate level-0 segments.
            for (rowid, body) in [
                (1_i64, "rust alpha"),
                (2, "rust beta"),
                (3, "rust gamma"),
                (4, "rust delta"),
                (5, "zeta only"),
            ] {
                sqlite
                    .execute(
                        "INSERT INTO docs(rowid, body) VALUES (?1, ?2)",
                        rusqlite::params![rowid, body],
                    )
                    .unwrap();
            }
            // doc 2 deleted; doc 3 updated so it no longer contains `rust`/`gamma`.
            sqlite
                .execute("DELETE FROM docs WHERE rowid = 2", [])
                .unwrap();
            sqlite
                .execute(
                    "UPDATE docs SET body = 'replaced epsilon' WHERE rowid = 3",
                    [],
                )
                .unwrap();
            sqlite.close().unwrap();
        }

        let queries: &[&str] = &[
            "rust",            // 1, 4 (2 deleted, 3 updated away)
            "alpha",           // 1
            "beta",            // none (2 deleted)
            "gamma",           // none (3 updated away)
            "replaced",        // 3 (new content)
            "epsilon",         // 3
            "zeta",            // 5
            "rust*",           // 1, 4
            "rust OR epsilon", // 1, 3, 4
        ];

        let stock: Vec<(String, Vec<i64>)> = {
            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let captured = queries
                .iter()
                .map(|query| {
                    let mut stmt = sqlite
                        .prepare("SELECT rowid FROM docs WHERE docs MATCH ?1 ORDER BY rowid")
                        .unwrap();
                    let ids: Vec<i64> = stmt
                        .query_map(rusqlite::params![query], |row| row.get::<_, i64>(0))
                        .unwrap()
                        .map(std::result::Result::unwrap)
                        .collect();
                    ((*query).to_owned(), ids)
                })
                .collect();
            sqlite.close().unwrap();
            captured
        };

        let conn = Connection::open(&db_str).unwrap();
        let root = |name: &str| -> Option<fsqlite_types::PageNumber> {
            let rows = conn
                .query(&format!(
                    "SELECT rootpage FROM sqlite_master WHERE name = '{name}';"
                ))
                .ok()?;
            let raw = rows.first()?.values().first()?.to_integer();
            fsqlite_types::PageNumber::new(u32::try_from(raw).ok()?)
        };
        let data_root = root("docs_data").expect("docs_data rootpage");
        let idx_root = root("docs_idx");
        let docsize_root = root("docs_docsize");
        let content_root = root("docs_content");

        conn.with_integrity_txn(|cx, txn| {
            let page1 = txn.get_page(cx, fsqlite_types::PageNumber::ONE)?;
            let header = super::parse_database_header_checked(page1.as_ref())?;
            let registry = std::sync::Arc::new(std::sync::Mutex::new(
                fsqlite_func::collation::CollationRegistry::new(),
            ));
            let mut reader = super::Fts5LiveShadowReader::with_roots(
                cx,
                txn,
                header.page_size,
                header.reserved_per_page,
                data_root,
                idx_root,
                docsize_root,
                content_root,
                registry,
            );

            let columns = vec!["body".to_owned()];
            let tokenizer = fsqlite_ext_fts5::create_tokenizer("unicode61")
                .expect("unicode61 tokenizer available");
            let weights = vec![1.0_f64; columns.len()];
            let query = fsqlite_ext_fts5::Fts5LazyQuery::new(
                &mut reader,
                &columns,
                tokenizer.as_ref(),
                fsqlite_ext_fts5::DetailMode::Full,
            )
            .expect("build lazy query");

            for (q, expected_ids) in &stock {
                let ranked = query
                    .search_queries_with_weights(&[q.as_str()], &weights)
                    .map_err(|e| FrankenError::function_error(format!("lazy query `{q}`: {e}")))?;
                let mut lazy_ids: Vec<i64> = ranked.iter().map(|(rowid, _)| *rowid).collect();
                lazy_ids.sort_unstable();
                lazy_ids.dedup();
                let mut want = expected_ids.clone();
                want.sort_unstable();
                want.dedup();
                assert_eq!(
                    lazy_ids, want,
                    "multi-segment recency: lazy MATCH `{q}` must equal stock (lazy={lazy_ids:?}, stock={want:?})"
                );
            }

            Ok(())
        })
        .unwrap();
    }

    /// bd-fts5-lazy-shadow-reads-itcc4.2(c): differential parity of the lazy
    /// on-disk query engine (`Fts5LazyQuery`) against stock SQLite across the
    /// FTS5 operator matrix (term, AND/OR/NOT, prefix, phrase, NEAR, column
    /// filter). The lazy path point-reads the persisted segments a query needs;
    /// it MUST return exactly the documents stock SQLite returns. Stock is the
    /// reference: its MATCH results are captured up front, then compared to the
    /// shared query engine running over the same on-disk index via the `.1`
    /// reader. A ranking-direction check confirms BM25 ordering is wired (the
    /// term-frequency winner ranks first in both engines).
    #[cfg(all(unix, feature = "ext-fts5"))]
    #[test]
    fn test_fts5_lazy_query_matches_stock_sqlite_across_operator_matrix() {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("fts5_lazy_diffparity_fixture.db");
        let db_str = db_path.to_string_lossy().into_owned();

        // Two indexed columns so column filters are discriminating. `rust`
        // appears in different columns and with different term frequencies so
        // BM25 ordering is observable.
        let docs: &[(i64, &str, &str)] = &[
            (1, "alpha", "rust beta gamma"),
            (2, "gamma news", "rust delta rust"),
            (3, "epsilon", "zeta eta theta"),
            (4, "rust weekly", "programming language"),
            (5, "gamma", "delta epsilon"),
            (6, "metals", "rusty beta"),
            (7, "alpha beta", "gamma delta"),
        ];

        {
            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            sqlite
                .execute_batch("CREATE VIRTUAL TABLE docs USING fts5(title, body);")
                .unwrap();
            for (rowid, title, body) in docs {
                sqlite
                    .execute(
                        "INSERT INTO docs(rowid, title, body) VALUES (?1, ?2, ?3)",
                        rusqlite::params![rowid, title, body],
                    )
                    .unwrap();
            }
            // Force a single merged on-disk segment so the read path exercises
            // structure + idx + leaf decoding exactly as a mature index would.
            sqlite
                .execute("INSERT INTO docs(docs) VALUES('optimize')", [])
                .unwrap();
            sqlite.close().unwrap();
        }

        // The operator matrix. Stock SQLite is the oracle for every entry.
        let queries: &[&str] = &[
            "rust",
            "gamma",
            "epsilon",
            "rust AND gamma",
            "rust OR zeta",
            "rust NOT gamma",
            "rust*",
            "\"gamma delta\"",
            "NEAR(rust gamma, 5)",
            "title:rust",
            "body:rust",
            "title:gamma OR body:gamma",
        ];

        // Capture stock results (ordered by rank) up front, then drop the
        // sqlite handle before opening the frankensqlite connection.
        let stock: Vec<(String, Vec<i64>)> = {
            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let captured = queries
                .iter()
                .map(|query| {
                    let mut stmt = sqlite
                        .prepare("SELECT rowid FROM docs WHERE docs MATCH ?1 ORDER BY rank")
                        .unwrap();
                    let ids: Vec<i64> = stmt
                        .query_map(rusqlite::params![query], |row| row.get::<_, i64>(0))
                        .unwrap()
                        .map(std::result::Result::unwrap)
                        .collect();
                    ((*query).to_owned(), ids)
                })
                .collect();
            sqlite.close().unwrap();
            captured
        };

        let conn = Connection::open(&db_str).unwrap();
        let root = |name: &str| -> Option<fsqlite_types::PageNumber> {
            let rows = conn
                .query(&format!(
                    "SELECT rootpage FROM sqlite_master WHERE name = '{name}';"
                ))
                .ok()?;
            let raw = rows.first()?.values().first()?.to_integer();
            fsqlite_types::PageNumber::new(u32::try_from(raw).ok()?)
        };
        let data_root = root("docs_data").expect("docs_data rootpage");
        let idx_root = root("docs_idx");
        let docsize_root = root("docs_docsize");
        let content_root = root("docs_content");

        conn.with_integrity_txn(|cx, txn| {
            let page1 = txn.get_page(cx, fsqlite_types::PageNumber::ONE)?;
            let header = super::parse_database_header_checked(page1.as_ref())?;
            let registry = std::sync::Arc::new(std::sync::Mutex::new(
                fsqlite_func::collation::CollationRegistry::new(),
            ));
            let mut reader = super::Fts5LiveShadowReader::with_roots(
                cx,
                txn,
                header.page_size,
                header.reserved_per_page,
                data_root,
                idx_root,
                docsize_root,
                content_root,
                registry,
            );

            let columns = vec!["title".to_owned(), "body".to_owned()];
            let tokenizer = fsqlite_ext_fts5::create_tokenizer("unicode61")
                .expect("unicode61 tokenizer available");
            let weights = vec![1.0_f64; columns.len()];
            let query = fsqlite_ext_fts5::Fts5LazyQuery::new(
                &mut reader,
                &columns,
                tokenizer.as_ref(),
                fsqlite_ext_fts5::DetailMode::Full,
            )
            .expect("build lazy query");

            let sorted = |mut ids: Vec<i64>| -> Vec<i64> {
                ids.sort_unstable();
                ids.dedup();
                ids
            };

            for (q, expected_ids) in &stock {
                let ranked = query
                    .search_queries_with_weights(&[q.as_str()], &weights)
                    .map_err(|e| FrankenError::function_error(format!("lazy query `{q}`: {e}")))?;
                let lazy_ids: Vec<i64> = ranked.iter().map(|(rowid, _score)| *rowid).collect();

                assert_eq!(
                    sorted(lazy_ids.clone()),
                    sorted(expected_ids.clone()),
                    "lazy MATCH `{q}` document set must equal stock SQLite (lazy={lazy_ids:?}, stock={expected_ids:?})"
                );

                // Ranking-direction check on the `rust` term: doc 2 carries two
                // `rust` occurrences in a short document, so BM25 ranks it first
                // in stock; the lazy engine must agree.
                if q == "rust" {
                    assert_eq!(
                        lazy_ids.first(),
                        expected_ids.first(),
                        "lazy BM25 top result for `rust` must match stock (lazy={lazy_ids:?}, stock={expected_ids:?})"
                    );
                    assert_eq!(
                        expected_ids.first(),
                        Some(&2),
                        "fixture sanity: doc 2 (rust x2) should rank first in stock"
                    );
                }
            }

            Ok(())
        })
        .unwrap();
    }

    /// Regression for meta_skill#113 ("`ms search` broken — `skills_fts`
    /// virtual table never usable; internal error: column not found:
    /// skills_fts"). A FrankenSQLite-created FTS5 table must be fully usable on
    /// a *subsequent* connection: after create→insert→close→reopen, both a
    /// plain `SELECT rowid FROM t` scan and a `... WHERE t MATCH 'word'` query
    /// must succeed and return the right rows. Before the rootpage-zero
    /// shadow-table persistence work (359eb0a3 / c09135c4) the vtab lived only
    /// in in-memory state and was not re-registered on reopen, so the bare
    /// table label in the MATCH predicate fell through to the column resolver
    /// and errored `column not found: <table>` — and a plain scan found no live
    /// instance at all. This test pins the full reopen contract end to end.
    #[test]
    fn test_reopen_fsqlite_created_fts5_usable_after_close_meta_skill_113() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("fts5_reopen_issue_113.db");
        let db_str = db_path.to_string_lossy().to_string();

        // Connection 1: create the FTS5 table, insert rows, close.
        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("CREATE VIRTUAL TABLE t USING fts5(content)")
                .unwrap();
            conn.execute("INSERT INTO t(rowid, content) VALUES (1, 'the quick brown fox')")
                .unwrap();
            conn.execute("INSERT INTO t(rowid, content) VALUES (2, 'lazy dog sleeps')")
                .unwrap();
            conn.execute("INSERT INTO t(rowid, content) VALUES (3, 'quick rust engine')")
                .unwrap();
            conn.close().unwrap();
        }

        // Connection 2 (the failing-before path): REOPEN the file and exercise
        // both query shapes the issue reported as broken.
        {
            let conn = Connection::open(&db_str).unwrap();

            // (a) Plain scan must see the live vtab and return every rowid.
            assert!(
                conn.has_live_vtab_instance("t"),
                "reopened FrankenSQLite-created FTS5 table must reconnect as a live vtab"
            );
            let scan = conn
                .query("SELECT rowid FROM t ORDER BY rowid")
                .expect("plain SELECT rowid FROM t must succeed after reopen");
            assert_eq!(
                scan.iter()
                    .map(|row| row.values()[0].clone())
                    .collect::<Vec<_>>(),
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(2),
                    SqliteValue::Integer(3),
                ],
                "plain scan after reopen must return all persisted rowids"
            );

            // (b) MATCH must resolve the bare table label and return the right
            // rows (this is the exact `t MATCH 'word'` shape from the issue).
            let matched = conn
                .query("SELECT rowid FROM t WHERE t MATCH 'quick' ORDER BY rowid")
                .expect("MATCH after reopen must succeed (issue #113 regression)");
            assert_eq!(
                matched
                    .iter()
                    .map(|row| row.values()[0].clone())
                    .collect::<Vec<_>>(),
                vec![SqliteValue::Integer(1), SqliteValue::Integer(3)],
                "MATCH after reopen must return the rows whose content matched, with content preserved (not re-tokenized from empty)"
            );

            // A non-matching token must return nothing — proves we restored the
            // real posting lists, not a blanket "everything matches" fallback.
            let none = conn
                .query("SELECT rowid FROM t WHERE t MATCH 'nonexistentword'")
                .unwrap();
            assert!(
                none.is_empty(),
                "a token absent from every document must match no rows after reopen"
            );
            conn.close().unwrap();
        }
    }

    #[test]
    fn test_reopen_rebinds_materialized_fts5_for_match_queries_and_new_inserts() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("materialized_fts5_rebind.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("CREATE VIRTUAL TABLE docs USING fts5(content)")
                .unwrap();
            conn.execute("INSERT INTO docs(rowid, content) VALUES (4, 'alpha rust beta')")
                .unwrap();
            conn.execute("INSERT INTO docs(rowid, content) VALUES (7, 'gamma rust delta')")
                .unwrap();
            conn.close().unwrap();
        }

        {
            let conn = Connection::open(&db_str).unwrap();
            let rows = conn
                .query("SELECT rowid FROM docs WHERE docs MATCH 'rust' ORDER BY rowid")
                .unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(4));
            assert_eq!(rows[1].values()[0], SqliteValue::Integer(7));

            conn.execute("INSERT INTO docs(content) VALUES ('reopened followup')")
                .unwrap();
            let inserted = conn
                .query("SELECT rowid FROM docs WHERE docs MATCH 'followup'")
                .unwrap();
            assert_eq!(inserted.len(), 1);
            assert_eq!(inserted[0].values()[0], SqliteValue::Integer(8));
            conn.close().unwrap();
        }

        let conn = Connection::open(&db_str).unwrap();
        let rows = conn
            .query("SELECT rowid FROM docs WHERE docs MATCH 'followup'")
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(8));
    }

