    #[test]
    fn test_pragma_connection_stats_reports_shared_pool_lifecycle() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("pool-stats.db");
        let db_path = db_path.to_string_lossy().into_owned();

        let conn1 = Connection::open(&db_path).unwrap();
        let conn2 = Connection::open(&db_path).unwrap();

        let _prepared = conn1.prepare("SELECT 1;").unwrap();
        conn1.query("SELECT 1;").unwrap();

        let stats = txn_metrics_map(&conn2.query("PRAGMA fsqlite.connection_stats;").unwrap());
        assert_eq!(stats.get("pool_size_estimate"), Some(&2));
        assert_eq!(stats.get("open_connections"), Some(&2));
        assert_eq!(stats.get("idle_connections"), Some(&2));
        assert_eq!(stats.get("active_transactions"), Some(&0));
        assert_eq!(stats.get("connect_events"), Some(&2));
        assert!(
            stats
                .get("prepare_calls_total")
                .copied()
                .unwrap_or_default()
                >= 1,
            "prepare_calls_total should include successful prepare() calls",
        );
        assert!(
            stats
                .get("queries_executed_total")
                .copied()
                .unwrap_or_default()
                >= 1,
            "query totals should include prior successful statements observed by the pool",
        );
        assert!(
            stats
                .get("connection_age_max_ms")
                .copied()
                .unwrap_or_default()
                >= 0,
            "connection age must be exposed",
        );
        assert!(
            stats.contains_key("current_connection_id"),
            "connection_stats should expose current connection identity fields"
        );
    }

    #[test]
    fn test_pragma_connection_stats_tracks_active_transactions_and_disconnects() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("pool-lifecycle.db");
        let db_path = db_path.to_string_lossy().into_owned();

        let mut conn1 = Connection::open(&db_path).unwrap();
        let conn2 = Connection::open(&db_path).unwrap();

        conn1.execute("BEGIN;").unwrap();
        let in_txn = txn_metrics_map(&conn2.query("PRAGMA connection_stats;").unwrap());
        assert_eq!(in_txn.get("pool_size_estimate"), Some(&2));
        assert_eq!(in_txn.get("active_transactions"), Some(&1));
        assert_eq!(in_txn.get("idle_connections"), Some(&1));
        assert!(
            in_txn
                .get("transactions_started_total")
                .copied()
                .unwrap_or_default()
                >= 1,
            "starting a transaction should be reflected in shared pool stats",
        );

        conn1.close_in_place().unwrap();

        let after_close =
            txn_metrics_map(&conn2.query("PRAGMA fsqlite_connection_stats;").unwrap());
        assert_eq!(after_close.get("pool_size_estimate"), Some(&1));
        assert_eq!(after_close.get("open_connections"), Some(&1));
        assert_eq!(after_close.get("active_transactions"), Some(&0));
        assert_eq!(after_close.get("disconnect_events"), Some(&1));
    }

