    #[test]
    fn test_file_backed_overflow_updates_preserve_table_routing_order() {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("overflow-update-routing.db");
        let db_path_text = db_path.to_string_lossy().into_owned();
        let original_payload = "A".repeat(3_500);
        let replacement_payload = "B".repeat(3_500);

        let conn = Connection::open(&db_path_text).expect("open file-backed database");
        conn.execute("PRAGMA fsqlite.concurrent_mode=OFF;").unwrap();
        conn.execute("PRAGMA journal_mode='delete';").unwrap();
        conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, payload TEXT NOT NULL);")
            .unwrap();

        conn.execute("BEGIN IMMEDIATE;").unwrap();
        for rowid in 1..=700_i64 {
            conn.execute_with_params(
                "INSERT INTO t(id, payload) VALUES (?1, ?2);",
                &[
                    SqliteValue::Integer(rowid),
                    SqliteValue::Text(original_payload.clone().into()),
                ],
            )
            .unwrap();
        }
        conn.execute("COMMIT;").unwrap();

        // Each overflow-sized row occupies a singleton leaf. Replacing every
        // row exercises delete + prechecked-absent reinsertion at separators
        // from every level of the table B-tree.
        conn.execute("BEGIN IMMEDIATE;").unwrap();
        for rowid in 1..=700_i64 {
            let changed = conn
                .execute_with_params(
                    "UPDATE t SET payload = ?1 WHERE id = ?2;",
                    &[
                        SqliteValue::Text(replacement_payload.clone().into()),
                        SqliteValue::Integer(rowid),
                    ],
                )
                .unwrap();
            assert_eq!(changed, 1, "rowid {rowid} must be replaced exactly once");
        }
        conn.execute("COMMIT;").unwrap();

        for rowid in 1..=700_i64 {
            let rows = conn
                .query_with_params(
                    "SELECT length(payload) FROM t WHERE id = ?1;",
                    &[SqliteValue::Integer(rowid)],
                )
                .unwrap();
            assert_eq!(
                rows.len(),
                1,
                "rowid {rowid} must remain reachable by a routed point lookup"
            );
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(3_500));
        }

        let integrity_rows = conn.query("PRAGMA integrity_check;").unwrap();
        assert_eq!(
            integrity_rows[0].values()[0],
            SqliteValue::Text("ok".into()),
            "FrankenSQLite must not observe an out-of-order table B-tree"
        );
        conn.close().unwrap();

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "stock SQLite must accept the table after overflow-row replacements"
        );
    }

    #[test]
    fn test_file_backed_delete_repairs_table_separator_for_sqlite_integrity_check() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("separator_repair.db");
        let db_str = db_path.to_str().unwrap();
        let payload = "S".repeat(1_400);

        let conn = Connection::open(db_str).expect("open file-backed db");
        conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, payload TEXT NOT NULL);")
            .expect("create table");
        conn.execute("BEGIN;").expect("begin bulk insert");
        for rowid in 1..=4_000_i64 {
            conn.execute(&format!(
                "INSERT INTO t(id, payload) VALUES ({rowid}, '{payload}');"
            ))
            .expect("insert row");
        }
        conn.execute("COMMIT;").expect("commit bulk insert");

        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case("t"))
            .map(|table| table.root_page)
            .expect("test table root page");
        let root_pgno = PageNumber::new(u32::try_from(root_page).unwrap()).unwrap();

        let inspect_first_nonroot_separator = |conn: &Connection| {
            let cx = Cx::new();
            conn.invalidate_cached_write_txn(&cx);
            conn.invalidate_cached_read_snapshot(&cx);
            let txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                .unwrap();
            let (usable_size, _) = Connection::current_btree_cursor_sizes_in_txn(&cx, &txn)
                .expect("inspect usable size");

            let root_data = txn.get_page(&cx, root_pgno).unwrap().into_vec();
            let root_header_offset = fsqlite_btree::header_offset_for_page(root_pgno);
            let root_header =
                fsqlite_btree::BtreePageHeader::parse(&root_data, root_header_offset).unwrap();
            assert_eq!(
                root_header.page_type,
                fsqlite_btree::cell::BtreePageType::InteriorTable,
                "test requires an interior table root"
            );
            let root_ptrs =
                fsqlite_btree::read_cell_pointers(&root_data, &root_header, root_header_offset)
                    .unwrap();
            let root_cell = fsqlite_btree::CellRef::parse(
                &root_data,
                usize::from(root_ptrs[0]),
                root_header.page_type,
                usable_size,
            )
            .unwrap();
            let root_separator = root_cell.rowid.unwrap();
            let left_subtree_page = root_cell.left_child.unwrap();

            let child_data = txn.get_page(&cx, left_subtree_page).unwrap().into_vec();
            let child_header_offset = fsqlite_btree::header_offset_for_page(left_subtree_page);
            let child_header =
                fsqlite_btree::BtreePageHeader::parse(&child_data, child_header_offset).unwrap();
            assert_eq!(
                child_header.page_type,
                fsqlite_btree::cell::BtreePageType::InteriorTable,
                "test requires a depth-3 table tree"
            );
            let child_ptrs =
                fsqlite_btree::read_cell_pointers(&child_data, &child_header, child_header_offset)
                    .unwrap();
            let child_cell = fsqlite_btree::CellRef::parse(
                &child_data,
                usize::from(child_ptrs[0]),
                child_header.page_type,
                usable_size,
            )
            .unwrap();

            (
                root_separator,
                left_subtree_page,
                child_cell.rowid.expect("child separator rowid"),
            )
        };

        let (root_separator_before, left_subtree_page, target_rowid) =
            inspect_first_nonroot_separator(&conn);
        assert!(
            target_rowid > 1,
            "target delete must leave the leaf non-empty"
        );

        conn.execute(&format!("DELETE FROM t WHERE id = {target_rowid};"))
            .expect("delete subtree maximum");

        let (root_separator_after, left_subtree_after_page, repaired_separator) =
            inspect_first_nonroot_separator(&conn);
        assert_eq!(left_subtree_after_page, left_subtree_page);
        assert_eq!(
            root_separator_after, root_separator_before,
            "repairing a non-root separator must not perturb the enclosing subtree maximum"
        );
        assert_eq!(
            repaired_separator,
            target_rowid - 1,
            "file-backed delete must lower the non-root separator to the deleted leaf's new maximum"
        );

        drop(conn);

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "C SQLite integrity_check must accept the on-disk table after deleting a subtree maximum"
        );
    }

    #[test]
    fn test_file_backed_delete_repairs_index_separator_for_sqlite_integrity_check() {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("index_separator_repair.db");
        let db_str = db_path.to_str().unwrap();
        let email_pad = "x".repeat(180);

        let conn = Connection::open(db_str).expect("open file-backed db");
        conn.execute(
            "CREATE TABLE users(
                id INTEGER PRIMARY KEY,
                email TEXT NOT NULL,
                payload TEXT NOT NULL
            );",
        )
        .expect("create table");
        conn.execute("CREATE UNIQUE INDEX idx_users_email ON users(email);")
            .expect("create unique index");

        conn.execute("BEGIN;").expect("begin bulk insert");
        for rowid in 1..=3_000_i64 {
            let email = format!("user_{rowid:05}_{email_pad}@example.com");
            let payload = format!("payload_{rowid:05}");
            conn.execute(&format!(
                "INSERT INTO users(id, email, payload) VALUES ({rowid}, '{email}', '{payload}');"
            ))
            .expect("insert row");
        }
        conn.execute("COMMIT;").expect("commit bulk insert");

        let index_root_page = {
            let schema = conn.schema.borrow();
            let table = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("users"))
                .expect("users table should exist");
            table
                .indexes
                .iter()
                .find(|index| index.name.eq_ignore_ascii_case("idx_users_email"))
                .map(|index| index.root_page)
                .expect("unique email index should exist")
        };
        let index_root_pgno = PageNumber::new(u32::try_from(index_root_page).unwrap()).unwrap();

        let inspect_first_nonroot_index_separator = |conn: &Connection| {
            let cx = Cx::new();
            conn.invalidate_cached_write_txn(&cx);
            conn.invalidate_cached_read_snapshot(&cx);
            let txn = conn
                .pager
                .begin(&cx, fsqlite_pager::TransactionMode::Deferred)
                .unwrap();
            let (usable_size, _) = Connection::current_btree_cursor_sizes_in_txn(&cx, &txn)
                .expect("inspect usable size");

            let root_data = txn.get_page(&cx, index_root_pgno).unwrap().into_vec();
            let root_header_offset = fsqlite_btree::header_offset_for_page(index_root_pgno);
            let root_header =
                fsqlite_btree::BtreePageHeader::parse(&root_data, root_header_offset).unwrap();
            assert_eq!(
                root_header.page_type,
                fsqlite_btree::cell::BtreePageType::InteriorIndex,
                "test requires an interior index root"
            );
            let root_ptrs =
                fsqlite_btree::read_cell_pointers(&root_data, &root_header, root_header_offset)
                    .unwrap();
            let root_cell = fsqlite_btree::CellRef::parse(
                &root_data,
                usize::from(root_ptrs[0]),
                root_header.page_type,
                usable_size,
            )
            .unwrap();
            let left_subtree_page = root_cell.left_child.unwrap();

            let child_data = txn.get_page(&cx, left_subtree_page).unwrap().into_vec();
            let child_header_offset = fsqlite_btree::header_offset_for_page(left_subtree_page);
            let child_header =
                fsqlite_btree::BtreePageHeader::parse(&child_data, child_header_offset).unwrap();
            assert_eq!(
                child_header.page_type,
                fsqlite_btree::cell::BtreePageType::InteriorIndex,
                "test requires a depth-3 index tree"
            );
            let child_ptrs =
                fsqlite_btree::read_cell_pointers(&child_data, &child_header, child_header_offset)
                    .unwrap();
            let child_cell = fsqlite_btree::CellRef::parse(
                &child_data,
                usize::from(child_ptrs[0]),
                child_header.page_type,
                usable_size,
            )
            .unwrap();
            assert!(
                child_cell.overflow_page.is_none(),
                "test separator payload should fit on-page"
            );

            let payload = child_cell.local_payload(&child_data);
            let values = fsqlite_types::record::parse_record(payload)
                .expect("decode index separator payload");
            let email = match values.first() {
                Some(SqliteValue::Text(text)) => text.to_string(),
                other => panic!("expected text email in index separator payload, got {other:?}"),
            };
            let rowid = match values.last() {
                Some(SqliteValue::Integer(id)) => *id,
                other => {
                    panic!("expected trailing rowid in index separator payload, got {other:?}")
                }
            };

            (email, rowid)
        };

        let (target_email, target_rowid) = inspect_first_nonroot_index_separator(&conn);
        conn.execute(&format!("DELETE FROM users WHERE id = {target_rowid};"))
            .expect("delete row owning interior separator key");

        drop(conn);

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let integrity_check: String = sqlite
            .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            integrity_check, "ok",
            "C SQLite integrity_check must accept the on-disk index after deleting an interior separator key"
        );

        let remaining: i64 = sqlite
            .query_row("SELECT COUNT(*) FROM users;", [], |row| row.get(0))
            .unwrap();
        assert_eq!(remaining, 2_999);

        let deleted_matches: i64 = sqlite
            .query_row(
                "SELECT COUNT(*) FROM users WHERE email = ?1;",
                rusqlite::params![target_email],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(deleted_matches, 0);
    }

