    #[test]
    fn test_file_backed_concurrent_write_conflict_produces_busy_snapshot() {
        // Two file-backed connections with concurrent mode, writing to the same
        // row. The second committer must get BusySnapshot (not a silent overwrite).
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("conflict_test.db");
        let path_str = db_path.to_str().unwrap();

        let conn1 = Connection::open(path_str).unwrap();
        conn1
            .execute("CREATE TABLE conflict_tbl (id INTEGER PRIMARY KEY, val INTEGER);")
            .unwrap();
        conn1
            .execute("INSERT INTO conflict_tbl VALUES (1, 0);")
            .unwrap();

        // Both connections start transactions and read the same row.
        let conn2 = Connection::open(path_str).unwrap();

        conn1.execute("BEGIN;").unwrap();
        conn2.execute("BEGIN;").unwrap();

        // Both read the current value.
        let _rows1 = conn1
            .query("SELECT val FROM conflict_tbl WHERE id = 1;")
            .unwrap();
        let _rows2 = conn2
            .query("SELECT val FROM conflict_tbl WHERE id = 1;")
            .unwrap();

        // conn1 writes and commits first.
        conn1
            .execute("UPDATE conflict_tbl SET val = 100 WHERE id = 1;")
            .unwrap();
        conn1.execute("COMMIT;").unwrap();

        // conn2 writes the same row against a stale snapshot. The transient
        // conflict may surface at UPDATE time or COMMIT time.
        let update_result = conn2.execute("UPDATE conflict_tbl SET val = 200 WHERE id = 1;");

        match update_result {
            Err(err) => {
                assert!(
                    err.is_transient(),
                    "stale concurrent write must be a transient error: {err}"
                );
            }
            Ok(_) => {
                let commit_result = conn2.execute("COMMIT;");
                if let Err(err) = commit_result {
                    assert!(
                        err.is_transient(),
                        "commit conflict must be a transient error: {err}"
                    );
                }
            }
        }

        let final_val = conn1
            .query("SELECT val FROM conflict_tbl WHERE id = 1;")
            .unwrap();
        let v = match final_val[0].values()[0] {
            SqliteValue::Integer(v) => v,
            _ => panic!("expected integer"),
        };
        assert!(
            v == 100 || v == 200,
            "final value must be from one committer: {v}"
        );
    }

    #[test]
    fn test_busy_snapshot_retry_rebinds_latest_row_before_rewrite_bd_rjc() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("busy_snapshot_retry_rebind.db");
        let db = db_path.to_string_lossy().to_string();

        let table_root_page = {
            let conn = Connection::open(&db).unwrap();
            conn.execute("PRAGMA busy_timeout=5000;").unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .unwrap();
            let root_page = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .map(|table| table.root_page)
                .expect("table t should exist after CREATE TABLE");
            conn.execute("INSERT INTO t (id, v) VALUES (1, 0);")
                .unwrap();
            root_page
        };
        let table_root_pgno = fsqlite_types::PageNumber::new(
            u32::try_from(table_root_page).expect("root page should fit in u32"),
        )
        .expect("root page should be valid");

        let read_active_row = |conn: &Connection| -> Vec<SqliteValue> {
            let mut active_txn = conn.active_txn.borrow_mut();
            let txn = active_txn
                .as_mut()
                .expect("active transaction should exist while probing staged row");
            let mut cursor = fsqlite_btree::BtCursor::new(
                fsqlite_btree::TransactionPageIo::new(txn),
                table_root_pgno,
                u32::try_from(fsqlite_types::PageSize::DEFAULT.as_usize())
                    .expect("page size should fit in u32"),
                true,
            );
            let seek = cursor
                .table_move_to(&Cx::new(), 1)
                .expect("staged row lookup should succeed");
            assert!(seek.is_found(), "staged row must remain present");
            let payload = cursor
                .payload(&Cx::new())
                .expect("staged row payload should be readable");
            fsqlite_types::record::parse_record(&payload)
                .expect("staged row payload should decode as a SQLite record")
        };

        let conn1 = Connection::open(&db).unwrap();
        let conn2 = Connection::open(&db).unwrap();
        for conn in [&conn1, &conn2] {
            conn.execute("PRAGMA busy_timeout=5000;").unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
        }

        conn1.execute("BEGIN CONCURRENT;").unwrap();
        conn2.execute("BEGIN CONCURRENT;").unwrap();

        assert_eq!(
            conn1
                .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                .unwrap(),
            1
        );
        assert_eq!(
            read_active_row(&conn1),
            vec![SqliteValue::Null, SqliteValue::Integer(1)],
            "first writer should stage v=1"
        );

        let loser_err = match conn2.execute("UPDATE t SET v = v + 1 WHERE id = 1;") {
            Ok(changes) => {
                assert_eq!(
                    changes, 1,
                    "second writer should affect one row when UPDATE wins"
                );
                assert_eq!(
                    read_active_row(&conn2),
                    vec![SqliteValue::Null, SqliteValue::Integer(1)],
                    "second writer should initially stage the same stale increment"
                );
                conn1.execute("COMMIT;").unwrap();
                let loser_commit = conn2.execute("COMMIT;");
                assert!(
                    loser_commit.is_err(),
                    "losing writer must fail transiently instead of silently overwriting"
                );
                loser_commit.unwrap_err()
            }
            Err(err) => {
                conn1.execute("COMMIT;").unwrap();
                err
            }
        };
        let winner_commit_seq = conn1
            .concurrent_commit_index
            .latest(table_root_pgno)
            .expect("winner commit should publish commit-index entry");
        assert!(
            loser_err.is_transient(),
            "losing writer should surface as transient retryable error: {loser_err}"
        );

        conn2.execute("ROLLBACK;").unwrap();

        let visible_after_rollback = conn2.query_row("SELECT v FROM t WHERE id = 1;").unwrap();
        assert_eq!(
            visible_after_rollback.get(0),
            Some(&SqliteValue::Integer(1)),
            "loser connection must see winner state after rollback"
        );

        conn2.execute("BEGIN CONCURRENT;").unwrap();
        let retry_session_id = conn2
            .concurrent_session_id
            .borrow()
            .expect("retry BEGIN CONCURRENT should create a fresh session");
        let retry_snapshot_high = {
            let registry = lock_unpoisoned(&conn2.concurrent_registry);
            registry
                .get(retry_session_id)
                .expect("retry session handle should exist")
                .snapshot()
                .high
        };
        assert!(
            retry_snapshot_high >= winner_commit_seq,
            "retry BEGIN CONCURRENT bound stale snapshot_high={} winner_commit_seq={}",
            retry_snapshot_high.get(),
            winner_commit_seq.get()
        );

        assert_eq!(
            conn2
                .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                .unwrap(),
            1
        );
        let retry_staged_row = read_active_row(&conn2);
        assert_eq!(
            retry_staged_row,
            vec![SqliteValue::Null, SqliteValue::Integer(2)],
            "retrying loser must re-read committed row before rewrite; snapshot_high={} winner_commit_seq={} latest_commit_index={:?}",
            retry_snapshot_high.get(),
            winner_commit_seq.get(),
            conn2
                .concurrent_commit_index
                .latest(table_root_pgno)
                .map(|seq| seq.get())
        );

        conn2.execute("COMMIT;").unwrap();

        let final_row = conn1.query_row("SELECT v FROM t WHERE id = 1;").unwrap();
        assert_eq!(
            final_row.get(0),
            Some(&SqliteValue::Integer(2)),
            "retrying loser should advance the row to 2 after rebinding"
        );
    }

    #[test]
    fn test_disjoint_concurrent_prepared_inserts_keep_distinct_conflict_surfaces() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("disjoint_concurrent_prepared_inserts.db");
        let db = db_path.to_string_lossy().to_string();

        let (left_root_page, right_root_page) = {
            let conn = Connection::open(&db).unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
            conn.execute("CREATE TABLE left_t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .unwrap();
            conn.execute("CREATE TABLE right_t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .unwrap();

            let schema = conn.schema.borrow();
            let left_root_page = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("left_t"))
                .map(|table| table.root_page)
                .expect("left_t root page must exist");
            let right_root_page = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("right_t"))
                .map(|table| table.root_page)
                .expect("right_t root page must exist");
            (left_root_page, right_root_page)
        };

        assert_ne!(
            left_root_page, right_root_page,
            "disjoint-table proof requires distinct root pages"
        );

        let left_root_pgno =
            PageNumber::new(u32::try_from(left_root_page).expect("left root page fits u32"))
                .expect("left root page valid");
        let right_root_pgno =
            PageNumber::new(u32::try_from(right_root_page).expect("right root page fits u32"))
                .expect("right root page valid");

        let conn1 = Connection::open(&db).unwrap();
        let conn2 = Connection::open(&db).unwrap();
        for conn in [&conn1, &conn2] {
            conn.execute("PRAGMA busy_timeout=5000;").unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
        }

        let insert_left = conn1
            .prepare("INSERT INTO left_t (id, v) VALUES (?1, ?2)")
            .unwrap();
        let insert_right = conn2
            .prepare("INSERT INTO right_t (id, v) VALUES (?1, ?2)")
            .unwrap();

        conn1.execute("BEGIN CONCURRENT;").unwrap();
        conn2.execute("BEGIN CONCURRENT;").unwrap();

        conn1
            .execute_prepared_with_params(
                &insert_left,
                &[SqliteValue::Integer(1), SqliteValue::Integer(11)],
            )
            .unwrap();
        conn2
            .execute_prepared_with_params(
                &insert_right,
                &[SqliteValue::Integer(1), SqliteValue::Integer(22)],
            )
            .unwrap();

        let left_conflict_surface = {
            let mut txn_guard = conn1.active_txn.borrow_mut();
            let txn = txn_guard
                .as_mut()
                .expect("left concurrent transaction should have active pager handle");
            txn.pending_conflict_pages().unwrap()
        };
        let right_conflict_surface = {
            let mut txn_guard = conn2.active_txn.borrow_mut();
            let txn = txn_guard
                .as_mut()
                .expect("right concurrent transaction should have active pager handle");
            txn.pending_conflict_pages().unwrap()
        };

        assert!(
            left_conflict_surface.contains(&left_root_pgno),
            "left insert must track its own table root in the conflict surface: {left_conflict_surface:?}"
        );
        assert!(
            !left_conflict_surface.contains(&right_root_pgno),
            "left insert must not pull in right_t root page: left={left_conflict_surface:?} right_root={right_root_pgno:?}"
        );
        assert!(
            right_conflict_surface.contains(&right_root_pgno),
            "right insert must track its own table root in the conflict surface: {right_conflict_surface:?}"
        );
        assert!(
            !right_conflict_surface.contains(&left_root_pgno),
            "right insert must not pull in left_t root page: right={right_conflict_surface:?} left_root={left_root_pgno:?}"
        );

        conn1.execute("COMMIT;").unwrap();
        conn2.execute("COMMIT;").unwrap();

        let rows = conn1
            .query("SELECT (SELECT COUNT(*) FROM left_t), (SELECT COUNT(*) FROM right_t);")
            .unwrap();
        assert_eq!(
            rows[0].values(),
            &[SqliteValue::Integer(1), SqliteValue::Integer(1)],
            "both disjoint concurrent inserts must commit successfully"
        );
    }

    #[test]
    fn test_disjoint_concurrent_prepared_insert_reuse_across_rounds_refreshes_snapshot() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir
            .path()
            .join("disjoint_concurrent_prepared_insert_reuse_rounds.db");
        let db = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db).unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
            conn.execute("CREATE TABLE left_t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .unwrap();
            conn.execute("CREATE TABLE right_t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .unwrap();
        }

        let conn1 = Connection::open(&db).unwrap();
        let conn2 = Connection::open(&db).unwrap();
        for conn in [&conn1, &conn2] {
            conn.execute("PRAGMA busy_timeout=5000;").unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
        }

        let insert_left = conn1
            .prepare("INSERT INTO left_t (id, v) VALUES (?1, ?2)")
            .unwrap();
        let insert_right = conn2
            .prepare("INSERT INTO right_t (id, v) VALUES (?1, ?2)")
            .unwrap();

        let mut left_snapshots = Vec::new();
        let mut right_snapshots = Vec::new();

        for round in 0_i64..4 {
            conn1.execute("BEGIN CONCURRENT;").unwrap();
            conn2.execute("BEGIN CONCURRENT;").unwrap();
            left_snapshots.push(conn1.current_concurrent_snapshot_seq().unwrap());
            right_snapshots.push(conn2.current_concurrent_snapshot_seq().unwrap());

            conn1
                .execute_prepared_with_params(
                    &insert_left,
                    &[
                        SqliteValue::Integer(round + 1),
                        SqliteValue::Integer(100 + round),
                    ],
                )
                .unwrap();
            conn2
                .execute_prepared_with_params(
                    &insert_right,
                    &[
                        SqliteValue::Integer(round + 1),
                        SqliteValue::Integer(200 + round),
                    ],
                )
                .unwrap();

            conn1.execute("COMMIT;").unwrap();
            conn2.execute("COMMIT;").unwrap();
        }

        assert!(
            left_snapshots.windows(2).all(|pair| pair[1] >= pair[0]),
            "left connection snapshot_high must refresh monotonically across rounds: {left_snapshots:?}"
        );
        assert!(
            right_snapshots.windows(2).all(|pair| pair[1] >= pair[0]),
            "right connection snapshot_high must refresh monotonically across rounds: {right_snapshots:?}"
        );

        let rows = conn1
            .query("SELECT (SELECT COUNT(*) FROM left_t), (SELECT COUNT(*) FROM right_t);")
            .unwrap();
        assert_eq!(
            rows[0].values(),
            &[SqliteValue::Integer(4), SqliteValue::Integer(4)],
            "prepared insert reuse across concurrent rounds must preserve all disjoint commits"
        );
    }

    #[test]
    fn test_same_table_concurrent_prepared_insert_reuse_across_rounds_preserves_all_rows_after_reopen()
     {
        let _serial = super::fsqlite_core_test_serializer();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir
            .path()
            .join("same_table_concurrent_prepared_insert_reuse_rounds.db");
        let db = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db).unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
            conn.execute("CREATE TABLE items (id INTEGER PRIMARY KEY, v TEXT NOT NULL);")
                .unwrap();
        }

        fn is_retryable(err: &FrankenError) -> bool {
            matches!(
                err,
                FrankenError::Busy
                    | FrankenError::BusyRecovery
                    | FrankenError::BusySnapshot { .. }
                    | FrankenError::DatabaseLocked { .. }
                    | FrankenError::WriteConflict { .. }
                    | FrankenError::SerializationFailure { .. }
            )
        }

        let thread_results = std::thread::scope(|scope| {
            let mut handles = Vec::new();
            for worker_idx in 0_i64..4 {
                let db = db.clone();
                handles.push(scope.spawn(move || {
                    let conn = open_connection_with_transient_retry(&db);
                    conn.execute("PRAGMA busy_timeout=5000;").unwrap();
                    conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
                    let insert = conn
                        .prepare("INSERT INTO items (id, v) VALUES (?1, ?2)")
                        .unwrap();

                    let mut committed_ids = Vec::new();
                    let mut retry_trace = Vec::new();

                    for round in 0_i64..3 {
                        let id = round * 4 + worker_idx + 1;
                        let payload = format!("worker-{}-round-{round}", worker_idx + 1);
                        let mut attempt = 0_u32;
                        loop {
                            attempt += 1;
                            let op_result = conn.execute("BEGIN CONCURRENT;").and_then(|_| {
                                conn.execute_prepared_with_params(
                                    &insert,
                                    &[
                                        SqliteValue::Integer(id),
                                        SqliteValue::Text(payload.clone().into()),
                                    ],
                                )
                                .and_then(|_| conn.execute("COMMIT;"))
                            });

                            match op_result {
                                Ok(_) => {
                                    committed_ids.push(id);
                                    retry_trace.push((round, id, attempt, "ok".to_owned()));
                                    break;
                                }
                                Err(err) if attempt < 16 && is_retryable(&err) => {
                                    let err_text = err.to_string();
                                    let _ = conn.execute("ROLLBACK;");
                                    retry_trace.push((round, id, attempt, err_text));
                                    std::thread::sleep(Duration::from_millis(
                                        2_u64.saturating_pow(attempt.min(6)),
                                    ));
                                }
                                Err(err) => {
                                    let _ = conn.execute("ROLLBACK;");
                                    panic!(
                                        "worker={} round={} id={} failed after {} attempt(s): {err}; retry_trace={retry_trace:?}",
                                        worker_idx + 1,
                                        round,
                                        id,
                                        attempt
                                    );
                                }
                            }
                        }
                    }

                    (committed_ids, retry_trace)
                }));
            }

            handles
                .into_iter()
                .map(|handle| handle.join().unwrap())
                .collect::<Vec<_>>()
        });

        let retry_traces = thread_results
            .iter()
            .map(|(_, trace)| trace.clone())
            .collect::<Vec<_>>();

        let reader = Connection::open(&db).unwrap();
        let count_rows = reader.query("SELECT COUNT(*) FROM items;").unwrap();
        let visible_ids = reader
            .query("SELECT id FROM items ORDER BY id;")
            .unwrap()
            .into_iter()
            .map(|row| row.get(0).cloned().unwrap_or(SqliteValue::Null))
            .collect::<Vec<_>>();
        assert_eq!(
            count_rows[0].get(0),
            Some(&SqliteValue::Integer(12)),
            "same-table concurrent prepared insert rounds must preserve all rows before reopen; ids={visible_ids:?}; retry_traces={retry_traces:?}"
        );

        let reopened = Connection::open(&db).unwrap();
        let reopened_count_rows = reopened.query("SELECT COUNT(*) FROM items;").unwrap();
        let reopened_ids = reopened
            .query("SELECT id FROM items ORDER BY id;")
            .unwrap()
            .into_iter()
            .map(|row| row.get(0).cloned().unwrap_or(SqliteValue::Null))
            .collect::<Vec<_>>();
        assert_eq!(
            reopened_count_rows[0].get(0),
            Some(&SqliteValue::Integer(12)),
            "same-table concurrent prepared insert rounds must preserve all rows after reopen; ids={reopened_ids:?}; retry_traces={retry_traces:?}"
        );
    }

    #[test]
    fn test_reader_rw_hot_select_does_not_track_unrelated_writer_progress_root_pages() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("reader_rw_hot_read_set_scope.db");
        let db = db_path.to_string_lossy().to_string();

        let (rw_hot_root_page, writer_progress_root_page) = {
            let conn = Connection::open(&db).unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
            conn.execute(
                "CREATE TABLE rw_hot (id INTEGER PRIMARY KEY, v INTEGER NOT NULL DEFAULT 0);",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE writer_progress_0 (round INTEGER PRIMARY KEY, committed INTEGER NOT NULL);",
            )
            .unwrap();
            conn.execute("INSERT INTO rw_hot (id, v) VALUES (0, 0), (1, 0);")
                .unwrap();

            let schema = conn.schema.borrow();
            let rw_hot_root_page = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("rw_hot"))
                .map(|table| table.root_page)
                .expect("rw_hot root page must exist");
            let writer_progress_root_page = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("writer_progress_0"))
                .map(|table| table.root_page)
                .expect("writer_progress_0 root page must exist");
            (rw_hot_root_page, writer_progress_root_page)
        };

        assert_ne!(
            rw_hot_root_page, writer_progress_root_page,
            "fixture requires disjoint root pages"
        );

        let rw_hot_root_pgno =
            PageNumber::new(u32::try_from(rw_hot_root_page).expect("rw_hot root page fits u32"))
                .expect("rw_hot root page valid");
        let writer_progress_root_pgno = PageNumber::new(
            u32::try_from(writer_progress_root_page).expect("writer_progress root page fits u32"),
        )
        .expect("writer_progress root page valid");

        let reader = Connection::open(&db).unwrap();
        reader.execute("PRAGMA busy_timeout=5000;").unwrap();
        reader
            .execute("PRAGMA fsqlite.concurrent_mode=ON;")
            .unwrap();

        reader.execute("BEGIN CONCURRENT;").unwrap();
        assert_eq!(
            reader.query("SELECT SUM(v) FROM rw_hot;").unwrap().len(),
            1,
            "reader aggregate should execute successfully"
        );
        assert_eq!(
            reader
                .query("SELECT v FROM rw_hot WHERE id = 1;")
                .unwrap()
                .len(),
            1,
            "reader point lookup should execute successfully"
        );

        let session_id = reader
            .concurrent_session_id
            .borrow()
            .expect("reader BEGIN CONCURRENT should create a session");
        let read_pages = {
            let registry = lock_unpoisoned(&reader.concurrent_registry);
            let handle = registry
                .get(session_id)
                .expect("reader concurrent handle should exist");
            let mut pages = handle.read_set().iter().copied().collect::<Vec<_>>();
            pages.sort_by_key(|page| page.get());
            pages
        };

        assert!(
            read_pages.contains(&rw_hot_root_pgno),
            "reader must track rw_hot root page reads: {read_pages:?}"
        );
        assert!(
            !read_pages.contains(&writer_progress_root_pgno),
            "reader SELECT on rw_hot must not pull in unrelated writer_progress root page: read_pages={read_pages:?} writer_progress_root={writer_progress_root_pgno:?}"
        );

        reader.execute("ROLLBACK;").unwrap();
    }

    #[test]
    fn test_mixed_reader_and_disjoint_writer_rounds_do_not_self_conflict() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("mixed_reader_writer_disjoint_rounds.db");
        let db = db_path.to_string_lossy().to_string();

        let writer_progress_root_pgno = {
            let conn = Connection::open(&db).unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
            conn.execute(
                "CREATE TABLE rw_hot (id INTEGER PRIMARY KEY, v INTEGER NOT NULL DEFAULT 0);",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE writer_progress_0 (round INTEGER PRIMARY KEY, committed INTEGER NOT NULL);",
            )
            .unwrap();
            conn.execute("INSERT INTO rw_hot (id, v) VALUES (0, 0), (1, 0);")
                .unwrap();
            let writer_progress_root_page = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("writer_progress_0"))
                .map(|table| table.root_page)
                .expect("writer_progress_0 root page must exist");
            PageNumber::new(
                u32::try_from(writer_progress_root_page)
                    .expect("writer_progress_0 root page fits u32"),
            )
            .expect("writer_progress_0 root page valid")
        };

        let reader = Connection::open(&db).unwrap();
        let writer = Connection::open(&db).unwrap();
        for conn in [&reader, &writer] {
            conn.execute("PRAGMA busy_timeout=5000;").unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").unwrap();
        }

        for round in 0_i64..8 {
            reader.execute("BEGIN CONCURRENT;").unwrap();
            writer.execute("BEGIN CONCURRENT;").unwrap();

            let writer_snapshot = writer
                .current_concurrent_snapshot_seq()
                .expect("writer BEGIN CONCURRENT must bind a snapshot");
            let latest_writer_commit = writer
                .concurrent_commit_index
                .latest(writer_progress_root_pgno)
                .map_or(0, CommitSeq::get);
            assert!(
                writer_snapshot >= latest_writer_commit,
                "writer BEGIN CONCURRENT bound stale snapshot before round {round}: snapshot_high={writer_snapshot} latest_writer_commit={latest_writer_commit}"
            );

            assert_eq!(reader.query("SELECT SUM(v) FROM rw_hot;").unwrap().len(), 1);
            assert_eq!(
                reader
                    .query("SELECT v FROM rw_hot WHERE id = 1;")
                    .unwrap()
                    .len(),
                1
            );

            writer
                .execute(&format!(
                    "INSERT INTO writer_progress_0 (round, committed) VALUES ({round}, 1);"
                ))
                .unwrap_or_else(|err| {
                    panic!(
                        "writer insert in disjoint mixed round {round} failed unexpectedly: {err:?}"
                    )
                });

            reader.execute("COMMIT;").unwrap();
            writer.execute("COMMIT;").unwrap_or_else(|err| {
                panic!("writer COMMIT in disjoint mixed round {round} failed unexpectedly: {err:?}")
            });
        }

        let final_rows = writer
            .query("SELECT COUNT(*) FROM writer_progress_0;")
            .unwrap();
        assert_eq!(
            final_rows[0].get(0),
            Some(&SqliteValue::Integer(8)),
            "all disjoint writer rounds must commit successfully under concurrent readers"
        );
    }

