    #[test]
    fn test_zjisk1_pragma_parity_cert_strict_toggle() {
        // Strict parity-cert fallback rejection is opt-in for certifying runs.
        let conn = Connection::open(":memory:").unwrap();

        let rows = conn.query("PRAGMA fsqlite.parity_cert_strict;").unwrap();
        assert_eq!(
            rows[0].values()[0],
            SqliteValue::Integer(0),
            "default strict parity-cert mode must be OFF"
        );

        conn.execute("PRAGMA fsqlite.parity_cert_strict = ON;")
            .unwrap();
        assert!(
            *conn.reject_mem_fallback_strict.borrow(),
            "strict parity-cert pragma ON must enable hard rejection"
        );
        let rows = conn.query("PRAGMA fsqlite.parity_cert_strict;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));

        conn.execute("PRAGMA fsqlite.parity_cert_strict = OFF;")
            .unwrap();
        assert!(
            !*conn.reject_mem_fallback_strict.borrow(),
            "strict parity-cert pragma OFF must disable hard rejection"
        );
        let rows = conn.query("PRAGMA fsqlite.parity_cert_strict;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(0));
    }

    #[test]
    fn test_zjisk1_strict_mode_rejects_join_fallback_dispatch() {
        // JOIN...USING still uses interpreted fallback dispatch in this path.
        // In strict parity-cert mode, that fallback must hard-fail.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE items (id INTEGER, name TEXT);")
            .unwrap();
        conn.execute("CREATE TABLE tags (id INTEGER, tag TEXT);")
            .unwrap();
        conn.execute("INSERT INTO items VALUES (1, 'alpha');")
            .unwrap();
        conn.execute("INSERT INTO tags VALUES (1, 'fruit');")
            .unwrap();

        let sql = "SELECT items.name, tags.tag \
                   FROM items JOIN tags USING (id);";

        // Default behavior (non-strict) still allows fallback execution.
        let rows = conn.query(sql).unwrap();
        assert_eq!(rows.len(), 1);

        conn.execute("PRAGMA fsqlite.parity_cert_strict = ON;")
            .unwrap();
        let err = conn
            .query(sql)
            .expect_err("strict parity-cert mode must reject fallback dispatch");
        assert!(
            err.to_string()
                .contains("in-memory fallback disabled in strict parity-cert mode"),
            "unexpected strict fallback error: {err}"
        );

        // parity_cert OFF should allow fallback even when strict flag is ON.
        conn.execute("PRAGMA fsqlite.parity_cert = OFF;").unwrap();
        let rows = conn.query(sql).unwrap();
        assert_eq!(rows.len(), 1);
    }

    #[test]
    fn test_zjisk1_internal_mem_fallback_guard_rejects_strict_certifying_scope() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA fsqlite.parity_cert_strict = ON;")
            .unwrap();

        let err = match conn
            .disable_mem_fallback_rejection_for_internal_scope("select", "view_materialization")
        {
            Ok(_) => panic!("strict parity-cert mode must reject helper-local fallback bypass"),
            Err(error) => error,
        };
        assert!(
            err.to_string()
                .contains("in-memory fallback disabled in strict parity-cert mode"),
            "unexpected strict helper fallback error: {err}"
        );
        assert!(
            *conn.reject_mem_fallback.borrow(),
            "failed helper scope must leave Mem fallback rejection enabled"
        );
        assert_eq!(
            conn.query("PRAGMA fsqlite.backend_mode;").unwrap()[0].values()[0],
            SqliteValue::Text("parity_cert_strict".into())
        );
    }

    #[test]
    fn test_zjisk1_internal_mem_fallback_guard_restores_nonstrict_scope() {
        let conn = Connection::open(":memory:").unwrap();
        assert!(
            *conn.reject_mem_fallback.borrow(),
            "parity-cert fallback rejection must default ON"
        );

        {
            let _guard = conn
                .disable_mem_fallback_rejection_for_internal_scope(
                    "select",
                    "with_clause_materialization",
                )
                .unwrap();
            assert!(
                !*conn.reject_mem_fallback.borrow(),
                "helper scope should temporarily allow Mem fallback in non-strict mode"
            );
            assert_eq!(
                conn.query("PRAGMA fsqlite.backend_mode;").unwrap()[0].values()[0],
                SqliteValue::Text("fallback_allowed".into())
            );
        }

        assert!(
            *conn.reject_mem_fallback.borrow(),
            "helper scope must restore parity-cert fallback rejection on drop"
        );
        assert_eq!(
            conn.query("PRAGMA fsqlite.backend_mode;").unwrap()[0].values()[0],
            SqliteValue::Text("parity_cert".into())
        );
    }

