        conn.execute("INSERT INTO sp VALUES (1, 'in savepoint');")
            .unwrap();
        conn.execute("RELEASE s1;").unwrap();
        let rows = conn.query("SELECT val FROM sp;").unwrap();
        assert_eq!(rows.len(), 1);
