    #[test]
    fn test_lazy_dirty_insert_after_delete_read_boundary_keeps_visibility() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE lazy_dirty_insert_after_delete (id INTEGER PRIMARY KEY, val TEXT, note INTEGER);",
        )
        .unwrap();
        let root_page = test_table_root_page(&conn, "lazy_dirty_insert_after_delete");

        let delete_stmt = conn
            .prepare("DELETE FROM lazy_dirty_insert_after_delete WHERE id = ?1")
            .unwrap();
        assert!(delete_stmt.prepared_update_delete_fast_path.is_some());

        conn.execute("BEGIN;").unwrap();
        conn.execute("INSERT INTO lazy_dirty_insert_after_delete VALUES (1, 'alpha', 10);")
            .unwrap();
        conn.execute("INSERT INTO lazy_dirty_insert_after_delete VALUES (2, 'beta', 20);")
            .unwrap();
        conn.execute("UPDATE lazy_dirty_insert_after_delete SET val = 'alpha2' WHERE id = 1;")
            .unwrap();
        delete_stmt
            .execute_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            "DELETE should leave the MemDatabase mirror dirty until the next read boundary"
        );

        let deleted = conn
            .query("SELECT COUNT(*) FROM lazy_dirty_insert_after_delete WHERE id = 2")
            .unwrap();
        assert_eq!(deleted[0].values()[0], SqliteValue::Integer(0));
        assert!(
            !conn.memdb_requires_active_txn_reload.get(),
            "the delete read boundary should refresh the MemDatabase mirror"
        );
        assert!(
            conn.memdb_rows_loaded.get() && conn.memdb_storage_count_shortcuts_safe.get(),
            "after the delete read boundary, the MemDatabase mirror should be exact again"
        );

        conn.execute("INSERT INTO lazy_dirty_insert_after_delete VALUES (3, 'gamma', 30);")
            .unwrap();
        let pending_direct_upserts = conn.pending_memdb_direct_upserts.borrow().len();
        let memdb_dirty = conn.memdb_requires_active_txn_reload.get();
        assert!(
            pending_direct_upserts > 0 || memdb_dirty,
            "insert after a dirty read boundary must either queue a deferred MemDatabase row delta or re-arm active-txn reload; pending={pending_direct_upserts} dirty={memdb_dirty}"
        );
        let cx = conn.op_cx().unwrap();
        conn.refresh_memdb_from_active_txn_if_dirty(&cx).unwrap();
        assert_eq!(
            memdb_column_values(&conn, root_page, 1),
            vec![
                (1, SqliteValue::Text("alpha2".into())),
                (3, SqliteValue::Text("gamma".into())),
            ],
            "an explicit active-txn refresh after the post-delete insert must rebuild the MemDatabase mirror with the new row still visible"
        );

        let rows = conn
            .query("SELECT id, val FROM lazy_dirty_insert_after_delete ORDER BY id")
            .unwrap();
        assert_eq!(
            memdb_column_values(&conn, root_page, 1),
            vec![
                (1, SqliteValue::Text("alpha2".into())),
                (3, SqliteValue::Text("gamma".into())),
            ],
            "the later SELECT must not clobber an already-correct MemDatabase mirror"
        );
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Integer(1), SqliteValue::Text("alpha2".into()),],
                vec![SqliteValue::Integer(3), SqliteValue::Text("gamma".into()),],
            ],
            "insert after a delete-triggered read boundary must remain visible to later reads in the same explicit transaction"
        );
        assert_eq!(
            memdb_column_values(&conn, root_page, 1),
            vec![
                (1, SqliteValue::Text("alpha2".into())),
                (3, SqliteValue::Text("gamma".into())),
            ],
            "the refreshed MemDatabase mirror should include the post-delete insert"
        );

        conn.execute("ROLLBACK;").unwrap();
    }

    #[test]
    fn test_prepared_insert_precomputes_direct_simple_insert_plan() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_plan (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .unwrap();

        let stmt = conn
            .prepare("INSERT INTO prep_direct_plan VALUES (?1, ('user_' || ?1), (?1 * 0.137))")
            .unwrap();

        assert!(matches!(
            stmt.precompiled_dml(),
            Some(PreparedPrecompiledDml {
                kind: PreparedDmlKind::Insert,
                direct_simple_insert: Some(_),
                ..
            })
        ));

        let PreparedPrecompiledDml {
            direct_simple_insert: Some(direct),
            ..
        } = stmt
            .precompiled_dml()
            .expect("prepared dispatch should exist")
        else {
            unreachable!("assertion above guarantees precompiled direct insert");
        };
        assert!(
            direct.compiled_row_values.is_some(),
            "benchmark-style direct insert should compile its row expressions once at prepare time"
        );
        assert!(
            direct
                .compiled_row_values
                .as_ref()
                .is_some_and(|exprs| exprs.iter().any(|expr| match expr {
                    PreparedDirectSimpleInsertExpr::ConcatChain(parts) => parts.len() >= 2,
                    _ => false,
                })),
            "benchmark-style direct insert should flatten concat-heavy expressions into one-pass chains"
        );
    }

