    #[test]
    fn test_prepared_insert_with_function_call_prefers_reusable_table_program() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_fallback (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value INTEGER NOT NULL);",
        )
        .unwrap();

        let stmt = conn
            .prepare("INSERT INTO prep_direct_fallback VALUES (?1, lower(?2), abs(?3))")
            .unwrap();
        let direct = stmt
            .precompiled_dml()
            .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
            .expect("function-call INSERT should still precompute direct metadata for fallback classification");
        assert!(
            Connection::direct_simple_insert_prefers_reusable_table_program(direct),
            "function-call INSERT should stay on the reusable table-program lane until compiled direct support exists"
        );

        reset_hot_path_profile();
        let affected = conn
            .execute_prepared_with_params(
                &stmt,
                &[
                    SqliteValue::Integer(1),
                    SqliteValue::Text("MiXeD".into()),
                    SqliteValue::Integer(-9),
                ],
            )
            .unwrap();
        assert_eq!(affected, 1);

        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.prepared_direct_insert_executions, 0,
            "reusable-only shapes must not drift onto the direct prepared-insert lane: {profile:?}"
        );

        let row = conn
            .query_row("SELECT id, name, value FROM prep_direct_fallback WHERE id = 1")
            .unwrap();
        assert_eq!(row.values()[0], SqliteValue::Integer(1));
        assert_eq!(row.values()[1], SqliteValue::Text("mixed".into()));
        assert_eq!(row.values()[2], SqliteValue::Integer(9));
    }

    #[test]
    fn test_prepared_upsert_skips_direct_simple_insert_fast_path() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_upsert_direct_guard (id INTEGER PRIMARY KEY, name TEXT, count INTEGER DEFAULT 0);",
        )
        .unwrap();

        let stmt = conn
            .prepare(
                "INSERT INTO prep_upsert_direct_guard VALUES (?1, ?2, ?3) \
                 ON CONFLICT(id) DO UPDATE SET \
                 name = excluded.name, count = count + excluded.count;",
            )
            .unwrap();

        assert!(
            stmt.precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .is_none(),
            "UPSERT must not route through the direct_simple_insert fast path because that lane drops ON CONFLICT DO UPDATE semantics"
        );

        stmt.execute_with_params(&[
            SqliteValue::Integer(1),
            SqliteValue::Text("alpha".into()),
            SqliteValue::Integer(1),
        ])
        .unwrap();
        stmt.execute_with_params(&[
            SqliteValue::Integer(1),
            SqliteValue::Text("alpha_v2".into()),
            SqliteValue::Integer(3),
        ])
        .unwrap();

        let row = conn
            .query_row("SELECT id, name, count FROM prep_upsert_direct_guard WHERE id = 1;")
            .unwrap();
        assert_eq!(
            row.values(),
            &[
                SqliteValue::Integer(1),
                SqliteValue::Text("alpha_v2".into()),
                SqliteValue::Integer(4),
            ]
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_executes_inside_explicit_transaction() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_exec (id INTEGER PRIMARY KEY, score INTEGER NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_exec VALUES (?1, (?1 * 7))")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        for id in 1..=3 {
            let affected = conn
                .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(id)])
                .unwrap();
            assert_eq!(affected, 1, "prepared direct insert should insert one row");
        }
        let session_id = conn
            .concurrent_session_id
            .borrow()
            .expect("BEGIN should bind a concurrent session by default");
        let concurrent_write_pages = {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            registry
                .get(session_id)
                .expect("concurrent session handle missing after direct inserts")
                .write_set_pages()
        };
        assert!(
            !concurrent_write_pages.is_empty(),
            "prepared direct inserts inside BEGIN must populate the concurrent write surface"
        );
        let table_root_page = fsqlite_types::PageNumber::new(
            u32::try_from(test_table_root_page(&conn, "prep_direct_exec"))
                .expect("root page should fit in u32"),
        )
        .expect("root page should be valid");
        assert!(
            concurrent_write_pages.contains(&table_root_page),
            "prepared direct inserts inside BEGIN must track table root page {table_root_page:?}; pages={concurrent_write_pages:?}"
        );
        assert_eq!(
            conn.memory_concurrent_synced_write_roots
                .borrow()
                .as_slice(),
            &[(session_id, table_root_page)],
            "repeated prepared direct inserts should register the conservative :memory: conflict root once per transaction"
        );
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            "direct prepared inserts should keep the :memory: MemDatabase mirror lazy until COMMIT"
        );
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            ":memory: explicit prepared direct inserts should avoid queueing MemDatabase row deltas during write-only explicit transactions"
        );
        let append_hint = conn.prepared_direct_insert_append_hint.borrow().clone();
        assert!(
            append_hint.is_some(),
            "repeated prepared direct inserts should retain a rightmost-leaf append hint inside the explicit transaction"
        );
        assert_eq!(
            append_hint
                .as_ref()
                .map(|hint| (hint.root_page, hint.last_rowid)),
            Some((2, 3)),
            "append hint should track the latest explicit rowid for the table root page"
        );
        assert!(
            append_hint
                .as_ref()
                .and_then(|hint| hint.cached_leaf.as_ref())
                .is_some(),
            "parked explicit-txn append hints should retain right-edge leaf metadata until COMMIT"
        );
        conn.execute("COMMIT;").unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "COMMIT should not need queued MemDatabase row deltas once before finalizing the transaction"
        );
        assert!(
            conn.prepared_direct_insert_append_hint.borrow().is_none(),
            "COMMIT should clear the transaction-local append hint"
        );

        let rows = conn
            .query("SELECT id, score FROM prep_direct_exec ORDER BY id")
            .unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Integer(1), SqliteValue::Integer(7)],
                vec![SqliteValue::Integer(2), SqliteValue::Integer(14)],
                vec![SqliteValue::Integer(3), SqliteValue::Integer(21)],
            ],
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_resyncs_after_savepoint_rollback() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_savepoint_sync \
             (id INTEGER PRIMARY KEY, score INTEGER NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_savepoint_sync VALUES (?1, (?1 * 7))")
            .unwrap();

        let table_root_page = fsqlite_types::PageNumber::new(
            u32::try_from(test_table_root_page(&conn, "prep_direct_savepoint_sync"))
                .expect("root page should fit in u32"),
        )
        .expect("root page should be valid");

        conn.execute("BEGIN;").unwrap();
        conn.execute("SAVEPOINT direct_sync;").unwrap();
        stmt.execute_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        let session_id = conn
            .concurrent_session_id
            .borrow()
            .expect("BEGIN should bind a concurrent session by default");
        assert_eq!(
            conn.memory_concurrent_synced_write_roots
                .borrow()
                .as_slice(),
            &[(session_id, table_root_page)],
            "first post-savepoint direct write should memoize the registered conflict root"
        );
        conn.execute("ROLLBACK TO direct_sync;").unwrap();
        assert!(
            conn.memory_concurrent_synced_write_roots
                .borrow()
                .is_empty(),
            "ROLLBACK TO must clear the direct-memory conflict-sync memo because the concurrent write surface was restored to the savepoint"
        );

        stmt.execute_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        let concurrent_write_pages = {
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            registry
                .get(session_id)
                .expect("concurrent session handle missing after resynced direct insert")
                .write_set_pages()
        };
        assert!(
            concurrent_write_pages.contains(&table_root_page),
            "direct write after ROLLBACK TO must re-register table root page {table_root_page:?}; pages={concurrent_write_pages:?}"
        );
        conn.execute("COMMIT;").unwrap();

        let rows = conn
            .query("SELECT id, score FROM prep_direct_savepoint_sync ORDER BY id")
            .unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![vec![SqliteValue::Integer(2), SqliteValue::Integer(14)]],
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_transaction_api_clears_append_hint() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_txn_api_hint (id INTEGER PRIMARY KEY, name TEXT NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_txn_api_hint VALUES (NULL, ?1)")
            .unwrap();

        conn.begin_transaction().unwrap();
        stmt.execute_with_params(&[SqliteValue::Text("committed".into())])
            .unwrap();
        assert!(
            conn.prepared_direct_insert_append_hint.borrow().is_some(),
            "explicit prepared INSERT should retain the append hint while the transaction is open"
        );
        conn.commit_transaction().unwrap();
        assert!(
            conn.prepared_direct_insert_append_hint.borrow().is_none(),
            "commit_transaction() bypasses SQL dispatch, so execute_commit_with_cx must clear the append hint itself"
        );

        conn.begin_transaction().unwrap();
        stmt.execute_with_params(&[SqliteValue::Text("rolled_back".into())])
            .unwrap();
        assert!(
            conn.prepared_direct_insert_append_hint.borrow().is_some(),
            "second transaction should rebuild an append hint before rollback"
        );
        conn.rollback_transaction().unwrap();
        assert!(
            conn.prepared_direct_insert_append_hint.borrow().is_none(),
            "rollback_transaction() must not leave a hint whose retained leaf image references rolled-back rows"
        );

        let rows = conn
            .query("SELECT id, name FROM prep_direct_txn_api_hint ORDER BY id")
            .unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(1),
                SqliteValue::Text("committed".into()),
            ]],
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_statement_savepoint_rollback_clears_append_hint() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_stmt_sp_hint (id INTEGER PRIMARY KEY, name TEXT NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_stmt_sp_hint VALUES (NULL, ?1)")
            .unwrap();

        conn.begin_transaction().unwrap();
        let err = conn
            .with_internal_statement_savepoint("append_hint_clear", || -> Result<()> {
                stmt.execute_with_params(&[SqliteValue::Text("rolled_back".into())])?;
                assert!(
                    conn.prepared_direct_insert_append_hint.borrow().is_some(),
                    "direct prepared INSERT should populate the append hint before the statement savepoint rolls back"
                );
                Err(FrankenError::FunctionError(
                    "forced statement rollback".to_owned(),
                ))
            })
            .expect_err("forced statement error should roll back the internal savepoint");
        assert!(
            matches!(err, FrankenError::FunctionError(message) if message == "forced statement rollback")
        );
        assert!(
            conn.prepared_direct_insert_append_hint.borrow().is_none(),
            "statement-savepoint rollback must clear retained leaf images from the rolled-back B-tree state"
        );

        let rows = conn
            .query("SELECT id, name FROM prep_direct_stmt_sp_hint ORDER BY id")
            .unwrap();
        assert!(rows.is_empty());
        conn.rollback_transaction().unwrap();
    }

    #[test]
    fn test_prepared_direct_fk_statement_rollback_clears_deferred_memdb_upsert() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("prepared_direct_fk_statement_rollback.db");
        let db_str = db_path.to_string_lossy().into_owned();

        let conn = Connection::open(&db_str).unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").unwrap();
        conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
            .unwrap();
        conn.execute(
            "CREATE TABLE child (
                id INTEGER PRIMARY KEY,
                parent_id INTEGER NOT NULL REFERENCES parent(id)
            );",
        )
        .unwrap();
        conn.execute("INSERT INTO parent VALUES (1);").unwrap();

        let stmt = conn
            .prepare("INSERT INTO child (id, parent_id) VALUES (?1, ?2)")
            .unwrap();
        assert!(
            stmt.precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .is_some(),
            "plain FK INSERT should still use the prepared direct INSERT lane"
        );

        conn.execute("BEGIN;").unwrap();
        let err = stmt.execute_with_params(&[SqliteValue::Integer(10), SqliteValue::Integer(404)]);
        assert!(
            matches!(err, Err(FrankenError::ForeignKeyViolation)),
            "missing parent should reject the inserted child row: {err:?}"
        );
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "statement-savepoint rollback must discard deferred MemDatabase upserts from the failed statement"
        );

        let rows = conn
            .query("SELECT id, parent_id FROM child ORDER BY id")
            .unwrap();
        assert!(
            rows.is_empty(),
            "failed FK INSERT must not remain visible through the connection-local MemDatabase mirror"
        );

        stmt.execute_with_params(&[SqliteValue::Integer(11), SqliteValue::Integer(1)])
            .unwrap();
        conn.execute("COMMIT;").unwrap();
        drop(stmt);
        drop(conn);

        let sqlite = rusqlite::Connection::open(&db_path).unwrap();
        let rows = sqlite
            .prepare("SELECT id, parent_id FROM child ORDER BY id")
            .unwrap()
            .query_map([], |row| Ok((row.get::<_, i64>(0)?, row.get::<_, i64>(1)?)))
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(
            rows,
            vec![(11, 1)],
            "only the valid post-rollback child row should reach the database file"
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_autocommit_retains_memory_append_hint() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_autohint (id INTEGER PRIMARY KEY, name TEXT NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_autohint VALUES (?1, ('user_' || ?1))")
            .unwrap();
        let root_page = stmt
            .precompiled_dml()
            .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
            .map(|direct| direct.root_page)
            .expect("autocommit direct insert should precompute direct metadata");

        for id in 1..=2 {
            let affected = conn
                .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(id)])
                .unwrap();
            assert_eq!(affected, 1);
            assert!(
                conn.retained_autocommit_txn.borrow().is_some()
                    || conn.cached_write_txn.borrow().is_some(),
                "autocommit :memory: insert should park reusable writer state"
            );
            assert_eq!(
                conn.prepared_direct_insert_append_hint
                    .borrow()
                    .as_ref()
                    .map(|hint| (hint.root_page, hint.last_rowid)),
                Some((root_page, id)),
                "retained autocommit should keep the table-local append hint hot across statements"
            );
            assert!(
                conn.prepared_direct_insert_append_hint
                    .borrow()
                    .as_ref()
                    .and_then(|hint| hint.cached_leaf.as_ref())
                    .is_some(),
                "retained autocommit should keep table-local rightmost leaf state hot across statements"
            );
        }
        assert_eq!(
            conn.pending_memdb_direct_upserts.borrow().len(),
            0,
            "retained autocommit should avoid queueing owned MemDatabase row images on the hot write-only path"
        );
        assert!(
            !conn.memdb_rows_loaded.get()
                && !conn.memdb_storage_count_shortcuts_safe.get()
                && conn.memdb_requires_active_txn_reload.get(),
            "retained autocommit should keep the append hint hot while marking the MemDatabase mirror stale for the next read boundary"
        );

        let rows = conn
            .query("SELECT id, name FROM prep_direct_autohint ORDER BY id;")
            .unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "retained autocommit read boundary should not need any queued MemDatabase deltas"
        );
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
        assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
    }

