    #[test]
    fn test_prepared_direct_simple_insert_large_explicit_txn_reloads_memdb_once_at_commit_for_memory()
     {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_large_dirty (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare(
                "INSERT INTO prep_direct_large_dirty VALUES (?1, ('user_' || ?1), (?1 * 0.137))",
            )
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        for id in 1..=(PREPARED_DIRECT_INSERT_PENDING_MEMDB_UPSERT_LIMIT as i64 + 1) {
            let affected = conn
                .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(id)])
                .unwrap();
            assert_eq!(affected, 1);
        }
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            ":memory: explicit transactions should keep the MemDatabase mirror lazy even after large write-only loops"
        );
        assert!(
            !conn.memdb_rows_loaded.get(),
            "write-only :memory: explicit transactions should not keep a stale MemDatabase row image resident"
        );
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "large :memory: explicit transactions should not accumulate queued MemDatabase row deltas"
        );

        conn.execute("COMMIT;").unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "COMMIT should not need queued MemDatabase rows for :memory: direct inserts"
        );
        assert!(
            conn.memdb_rows_loaded.get() && conn.memdb_storage_count_shortcuts_safe.get(),
            "after COMMIT the in-memory MemDatabase mirror should be rebuilt once so COUNT(*) stays on the fast path"
        );
        let count = conn
            .query("SELECT COUNT(*) FROM prep_direct_large_dirty")
            .unwrap();
        assert_eq!(
            count[0].values()[0],
            SqliteValue::Integer(PREPARED_DIRECT_INSERT_PENDING_MEMDB_UPSERT_LIMIT as i64 + 1),
            "the next read should see every committed row without forcing a pager-backed reload"
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_begin_refreshes_dirty_mirror_before_lazy_insert() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_dirty_seed (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare(
                "INSERT INTO prep_direct_dirty_seed VALUES (?1, ('user_' || ?1), (?1 * 0.137))",
            )
            .unwrap();

        conn.memdb_rows_loaded.set(false);
        conn.memdb_storage_count_shortcuts_safe.set(false);
        conn.memdb_requires_active_txn_reload.set(true);

        conn.execute("BEGIN;").unwrap();
        assert!(
            !conn.memdb_requires_active_txn_reload.get(),
            "BEGIN should refresh the dirty MemDatabase mirror from the active transaction before lazy direct inserts start"
        );
        let affected = conn
            .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(affected, 1);
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "once BEGIN refreshes the dirty MemDatabase mirror, the next :memory: direct insert should keep it lazy instead of queueing row deltas"
        );
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            "the first explicit :memory: direct insert should mark the MemDatabase mirror stale for the next read boundary"
        );

        let rows = conn
            .query("SELECT id, name FROM prep_direct_dirty_seed ORDER BY id")
            .unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(1),
                SqliteValue::Text("user_1".into()),
            ]],
            "reads inside the transaction should still recover the inserted row via active-txn reload"
        );

        conn.execute("ROLLBACK;").unwrap();
    }

    #[test]
    fn test_snapshot_free_memory_begin_defers_row_hydration_before_direct_update() {
        let _profile_guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA fsqlite_capture_time_travel_snapshots=false;")
            .unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_begin_defer (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                value REAL NOT NULL
            );",
        )
        .unwrap();
        let insert = conn
            .prepare(
                "INSERT INTO prep_direct_begin_defer VALUES (?1, ('user_' || ?1), (?1 * 0.137))",
            )
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        for id in 0..128_i64 {
            insert
                .execute_with_params(&[SqliteValue::Integer(id)])
                .unwrap();
        }
        conn.execute("COMMIT;").unwrap();

        let update = conn
            .prepare("UPDATE prep_direct_begin_defer SET value = ?2 WHERE id = ?1")
            .unwrap();

        super::reset_hot_path_profile();
        conn.execute("BEGIN;").unwrap();
        assert!(
            conn.is_concurrent_transaction(),
            "snapshot-free :memory: BEGIN must keep the default concurrent transaction semantics"
        );
        let begin_profile = super::hot_path_profile_snapshot();
        assert_eq!(
            begin_profile.record_decode.parse_record_into_calls, 0,
            "snapshot-free :memory: BEGIN should bind schema/publication without decoding every table row: {begin_profile:?}"
        );
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            "deferred row hydration must arm the next read boundary"
        );

        assert_eq!(
            update
                .execute_with_params(&[SqliteValue::Integer(64), SqliteValue::Float(999.99)])
                .unwrap(),
            1
        );
        conn.execute("COMMIT;").unwrap();

        let row = conn
            .query_row("SELECT value FROM prep_direct_begin_defer WHERE id = 64")
            .unwrap();
        assert_eq!(row.values(), &[SqliteValue::Float(999.99)]);
    }

    #[test]
    fn test_prepared_direct_simple_insert_savepoint_after_lazy_writes_restores_snapshot() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_direct_savepoint (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_savepoint VALUES (?1, ('user_' || ?1), (?1 * 0.137))")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        conn.execute_prepared_with_params(&stmt, &[SqliteValue::Integer(1)])
            .unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            ":memory: direct inserts should keep the MemDatabase mirror lazy until SAVEPOINT forces a refresh"
        );
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            "the first write should leave the MemDatabase mirror stale until SAVEPOINT captures a fresh snapshot"
        );
        conn.execute("SAVEPOINT s1;").unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "SAVEPOINT should not rely on queued MemDatabase row materialization before capturing the snapshot"
        );
        assert!(
            !conn.memdb_requires_active_txn_reload.get(),
            "SAVEPOINT should refresh the MemDatabase mirror from the active txn before capturing the snapshot"
        );
        conn.execute_prepared_with_params(&stmt, &[SqliteValue::Integer(2)])
            .unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "rows inserted after the savepoint should keep the MemDatabase mirror lazy until the next boundary"
        );
        assert!(
            conn.memdb_requires_active_txn_reload.get(),
            "writes after the savepoint should dirty the MemDatabase mirror again"
        );
        conn.execute("ROLLBACK TO s1;").unwrap();
        assert!(
            conn.pending_memdb_direct_upserts.borrow().is_empty(),
            "ROLLBACK TO SAVEPOINT should restore the captured MemDatabase snapshot without leaving deferred row state behind"
        );

        let rows = conn
            .query("SELECT id, name FROM prep_direct_savepoint ORDER BY id")
            .unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![vec![
                SqliteValue::Integer(1),
                SqliteValue::Text("user_1".into()),
            ]],
        );

        conn.execute("ROLLBACK;").unwrap();
    }

