    #[test]
    fn test_prepared_direct_simple_insert_implicit_rowid_ignores_stale_memdb_hint_when_exactness_revoked()
     {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_direct_hint_dirty (id INTEGER PRIMARY KEY, name TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_direct_hint_dirty VALUES (1, 'first');")
            .unwrap();
        conn.execute("INSERT INTO prep_direct_hint_dirty VALUES (2, 'second');")
            .unwrap();

        let stmt = conn
            .prepare("INSERT INTO prep_direct_hint_dirty VALUES (NULL, ?1)")
            .unwrap();
        let root_page = stmt
            .precompiled_dml()
            .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
            .map(|direct| direct.root_page)
            .expect("implicit-rowid direct insert should stay on the direct lane");
        let hydrated_rows = conn
            .query("SELECT id FROM prep_direct_hint_dirty ORDER BY id")
            .unwrap();
        assert_eq!(hydrated_rows.len(), 2);

        {
            let mut db = conn.db.borrow_mut();
            let table = db
                .get_table_mut(root_page)
                .expect("MemDatabase table should exist before stale-row injection");
            table.insert_row(
                9,
                vec![
                    SqliteValue::Integer(9),
                    SqliteValue::Text("stale-memdb-only".into()),
                ],
            );
        }
        conn.memdb_storage_count_shortcuts_safe.set(false);
        assert!(conn.memdb_rows_loaded.get());
        assert!(!conn.memdb_requires_active_txn_reload.get());
        assert_eq!(
            conn.prepared_direct_insert_memdb_next_rowid_hint(root_page, true),
            None,
            "once MemDatabase exactness is revoked, implicit-rowid direct inserts must ignore the stale MemDatabase rowid hint and fall back to pager/txn state"
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_reuses_record_scratch_buffer_capacity() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_direct_scratch (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_scratch VALUES (?1, ('payload_' || ?2))")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        stmt.execute_with_params(&[
            SqliteValue::Integer(1),
            SqliteValue::Text("abcdefghijklmnopqrstuvwxyz".into()),
        ])
        .unwrap();
        let first_capacity = conn
            .prepared_direct_insert_record_scratch
            .borrow()
            .capacity();
        assert!(
            first_capacity > 0,
            "direct insert should populate reusable record scratch after first execution"
        );

        stmt.execute_with_params(&[SqliteValue::Integer(2), SqliteValue::Text("x".into())])
            .unwrap();
        let second_capacity = conn
            .prepared_direct_insert_record_scratch
            .borrow()
            .capacity();
        stmt.execute_with_params(&[SqliteValue::Integer(3), SqliteValue::Text("y".into())])
            .unwrap();
        let third_capacity = conn
            .prepared_direct_insert_record_scratch
            .borrow()
            .capacity();
        conn.execute("COMMIT;").unwrap();

        assert!(
            second_capacity >= first_capacity,
            "direct insert scratch may grow once when it learns a reusable record-header envelope, but it must not discard earlier capacity"
        );
        assert_eq!(
            third_capacity, second_capacity,
            "once the direct insert lane has learned its reusable record-header envelope, subsequent executions should keep the scratch capacity stable"
        );
    }

    #[test]
    fn test_prepare_direct_simple_insert_constant_record_reuses_statement_lookaside() {
        let _guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_direct_const (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();

        let _stmt = conn
            .prepare("INSERT INTO prep_direct_const VALUES (1, 'abcdefghijklmnopqrstuvwxyz')")
            .unwrap();
        let warmed_capacity = conn
            .prepared_direct_insert_record_scratch
            .borrow()
            .capacity();
        assert!(
            warmed_capacity > 0,
            "prepare-time constant-record assembly should warm the reusable record scratch",
        );
        let first_profile = super::hot_path_profile_snapshot();
        assert!(
            first_profile.arena_alloc_bytes > 0,
            "first constant-record prepare should report retained lookaside growth",
        );
        assert_eq!(
            first_profile.fallback_to_general_allocator_count, 1,
            "prepare-time constant-record assembly still performs one owned handoff for the cached prepared artifact",
        );

        super::reset_hot_path_profile();
        let _stmt = conn
            .prepare("INSERT INTO prep_direct_const VALUES (2, 'x')")
            .unwrap();
        let second_profile = super::hot_path_profile_snapshot();
        assert_eq!(
            conn.prepared_direct_insert_record_scratch
                .borrow()
                .capacity(),
            warmed_capacity,
            "smaller prepare-time constant-record shapes should reuse warmed statement lookaside capacity",
        );
        assert_eq!(
            second_profile.arena_alloc_bytes, 0,
            "second prepare should not need additional retained lookaside growth for a smaller constant row",
        );
        assert_eq!(
            second_profile.fallback_to_general_allocator_count, 1,
            "owned prepared-artifact handoff should remain visible even when the scratch itself is reused",
        );
    }

    #[test]
    fn test_reset_statement_lookaside_clears_prepared_direct_insert_scratch_without_dropping_capacity()
     {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_direct_reset (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        let stmt = conn
            .prepare("INSERT INTO prep_direct_reset VALUES (?1, ('payload_' || ?2))")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        stmt.execute_with_params(&[
            SqliteValue::Integer(1),
            SqliteValue::Text("abcdefghijklmnopqrstuvwxyz".into()),
        ])
        .unwrap();
        conn.execute("COMMIT;").unwrap();

        let record_capacity = conn
            .prepared_direct_insert_record_scratch
            .borrow()
            .capacity();
        let row_capacity = conn.prepared_direct_insert_row_scratch.borrow().capacity();
        let text_capacity = conn.prepared_direct_insert_text_scratch.borrow().capacity();

        conn.reset_statement_lookaside();

        assert_eq!(conn.prepared_direct_insert_record_scratch.borrow().len(), 0);
        assert_eq!(
            conn.prepared_direct_insert_record_scratch
                .borrow()
                .capacity(),
            record_capacity,
            "record scratch reset should clear logical contents without discarding capacity",
        );
        assert_eq!(conn.prepared_direct_insert_row_scratch.borrow().len(), 0);
        assert_eq!(
            conn.prepared_direct_insert_row_scratch.borrow().capacity(),
            row_capacity,
            "row scratch reset should preserve inline/heap capacity for the next execution",
        );
        assert_eq!(conn.prepared_direct_insert_text_scratch.borrow().len(), 0);
        assert_eq!(
            conn.prepared_direct_insert_text_scratch.borrow().capacity(),
            text_capacity,
            "text scratch reset should drop stale contents without discarding warmed capacity",
        );
    }

    #[test]
    fn test_prepared_direct_simple_insert_or_rollback_rolls_back_explicit_transaction() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_direct_rollback (id INTEGER PRIMARY KEY, name TEXT);")
            .unwrap();
        let stmt = conn
            .prepare("INSERT OR ROLLBACK INTO prep_direct_rollback VALUES (?1, ?2)")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        let first = conn
            .execute_prepared_with_params(
                &stmt,
                &[SqliteValue::Integer(1), SqliteValue::Text("first".into())],
            )
            .unwrap();
        assert_eq!(first, 1);

        let err = conn
            .execute_prepared_with_params(
                &stmt,
                &[
                    SqliteValue::Integer(1),
                    SqliteValue::Text("duplicate".into()),
                ],
            )
            .expect_err("OR ROLLBACK duplicate should abort the whole explicit transaction");
        assert!(matches!(err, FrankenError::PrimaryKeyViolation));
        assert!(
            !conn.in_transaction.get() && conn.active_txn.borrow().is_none(),
            "OR ROLLBACK should leave the connection outside the explicit transaction"
        );

        let rows = conn
            .query("SELECT id, name FROM prep_direct_rollback ORDER BY id")
            .unwrap();
        assert!(
            rows.is_empty(),
            "OR ROLLBACK should discard earlier writes from the explicit transaction"
        );
    }

