    #[test]
    fn test_prepare_insert_with_foreign_keys_uses_direct_dispatch_and_checks_fk() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").unwrap();
        conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
            .unwrap();
        conn.execute(
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id));",
        )
        .unwrap();

        let stmt = conn
            .prepare("INSERT INTO child (id, parent_id) VALUES (?1, ?2)")
            .unwrap();
        let dispatch = stmt
            .precompiled_dml()
            .expect("FK child INSERT should use precompiled dispatch");
        assert!(
            dispatch.direct_simple_insert.is_some(),
            "FK child INSERT should keep the direct simple-insert lane"
        );

        conn.execute("INSERT INTO parent VALUES (1);").unwrap();
        let affected = conn
            .execute_prepared_with_params(&stmt, &[SqliteValue::Null, SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(affected, 1);

        let err = conn
            .execute_prepared_with_params(&stmt, &[SqliteValue::Null, SqliteValue::Integer(99)])
            .expect_err("missing parent should still fail FK enforcement");
        assert!(matches!(err, FrankenError::ForeignKeyViolation));

        let ignore_stmt = conn
            .prepare("INSERT OR IGNORE INTO child (id, parent_id) VALUES (?1, ?2)")
            .unwrap();
        let affected = conn
            .execute_prepared_with_params(
                &ignore_stmt,
                &[SqliteValue::Integer(1), SqliteValue::Integer(99)],
            )
            .unwrap();
        assert_eq!(
            affected, 0,
            "ignored primary-key conflict should not be converted into an FK error"
        );

        let rows = conn
            .query("SELECT id, parent_id FROM child ORDER BY id;")
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(
            rows[0].values().to_vec(),
            vec![SqliteValue::Integer(1), SqliteValue::Integer(1)]
        );
    }

    #[test]
    fn test_execute_prepared_rejects_statement_from_different_connection() {
        let conn1 = Connection::open(":memory:").unwrap();
        let conn2 = Connection::open(":memory:").unwrap();
        conn1
            .execute("CREATE TABLE prep_cross (id INTEGER PRIMARY KEY);")
            .unwrap();
        conn2
            .execute("CREATE TABLE prep_cross (id INTEGER PRIMARY KEY);")
            .unwrap();

        let stmt = conn1
            .prepare("INSERT INTO prep_cross VALUES (?1);")
            .unwrap();
        let error = conn2
            .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(1)])
            .expect_err("prepared DML should not execute through a different connection");
        assert!(matches!(error, FrankenError::Internal(_)));
        assert!(
            error
                .to_string()
                .contains("prepared statement belongs to a different connection")
        );

        assert_eq!(
            conn1.query("SELECT id FROM prep_cross;").unwrap().len(),
            0,
            "owner connection should remain unchanged on rejected cross-connection execution"
        );
        assert_eq!(
            conn2.query("SELECT id FROM prep_cross;").unwrap().len(),
            0,
            "callee connection should remain unchanged on rejected cross-connection execution"
        );
    }

