    #[test]
    fn test_prepare_reuses_prepared_template_without_second_parse_or_compile() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_template_cache (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();

        let sql = "SELECT val FROM prep_template_cache WHERE id = ?1";
        let stmt1 = conn.prepare(sql).unwrap();
        let stmt2 = conn.prepare(sql).unwrap();
        let profile = hot_path_profile_snapshot();

        assert!(
            std::sync::Arc::ptr_eq(&stmt1.program, &stmt2.program),
            "prepared cache should reuse the same compiled program"
        );
        assert!(
            Rc::ptr_eq(&stmt1.sql, &stmt2.sql),
            "prepared cache hit should share the canonical SQL allocation"
        );
        assert_eq!(
            profile.parser.prepared_cache_misses, 1,
            "first prepare should populate the prepared cache: {profile:?}"
        );
        assert_eq!(
            profile.parser.prepared_cache_hits, 1,
            "second prepare should hit the prepared cache: {profile:?}"
        );
        assert_eq!(
            profile.parser.rewrite_calls, 1,
            "prepared cache hit should skip a second rewrite pass: {profile:?}"
        );
        assert_eq!(
            profile.parser.compiled_cache_misses, 1,
            "only the first prepare should compile the statement: {profile:?}"
        );
        assert_eq!(
            profile.parser.compiled_cache_hits, 0,
            "prepared cache hit should bypass the compiled-program cache entirely: {profile:?}"
        );
        assert!(
            profile.prepared_lookup_time_ns > 0,
            "prepare() should record prepared lookup time across the miss+hit pair: {profile:?}"
        );
    }

    #[test]
    fn test_prepared_cache_invalidated_by_ddl() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_cache_ddl (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_cache_ddl VALUES (1, 'alpha');")
            .unwrap();

        let stmt = conn
            .prepare("SELECT val FROM prep_cache_ddl WHERE id = ?1")
            .unwrap();
        assert!(
            stmt.db.is_some(),
            "table-backed SELECT should produce a cacheable prepared template"
        );
        assert!(
            !conn.prepared_cache.borrow().is_empty(),
            "prepare should populate the prepared cache"
        );

        conn.execute("ALTER TABLE prep_cache_ddl ADD COLUMN extra TEXT;")
            .unwrap();
        assert!(
            conn.prepared_cache.borrow().is_empty(),
            "DDL must clear the prepared cache"
        );

        reset_hot_path_profile();
        let row = conn
            .query_row_with_params(
                "SELECT val FROM prep_cache_ddl WHERE id = ?1",
                &[SqliteValue::Integer(1)],
            )
            .unwrap();
        assert_eq!(row.values()[0], SqliteValue::Text("alpha".into()));
        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.parser.prepared_cache_misses, 1,
            "first ad-hoc execution after DDL should reseed the prepared cache: {profile:?}"
        );
        assert!(
            !conn.prepared_cache.borrow().is_empty(),
            "ad-hoc execution after DDL should repopulate the prepared cache"
        );
    }

    #[test]
    fn test_prepared_cache_clears_on_write_commit_and_reads_new_row_image() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_cache_dml (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();

        let sql = "SELECT val FROM prep_cache_dml WHERE id >= ?1 ORDER BY val";
        let first = conn.prepare(sql).unwrap();
        assert!(
            first.db.is_some(),
            "test requires a table-backed prepared template"
        );
        let select_cache_key = conn.prepared_cache_key(sql);
        assert!(
            conn.prepared_cache_len() > 0,
            "initial prepare should populate the prepared cache"
        );

        conn.execute("BEGIN").unwrap();
        conn.execute_with_params(
            "INSERT INTO prep_cache_dml VALUES (?1, ?2)",
            &[SqliteValue::Integer(1), SqliteValue::Text("alpha".into())],
        )
        .unwrap();
        conn.execute("COMMIT").unwrap();
        assert!(
            conn.lookup_prepared_cache(select_cache_key, sql).is_none(),
            "DML commit must clear table-backed prepared templates bound to pre-commit pager visibility"
        );

        reset_hot_path_profile();
        let second = conn.prepare(sql).unwrap();
        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.parser.prepared_cache_hits, 0,
            "re-prepare after DML commit should not reuse the stale cached template: {profile:?}"
        );
        assert_eq!(
            profile.parser.prepared_cache_misses, 1,
            "DML commit should force a prepared-cache miss: {profile:?}"
        );

        let rows = second
            .query_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));
    }

