    #[test]
    fn test_prepared_memory_query_row_reuses_cached_read_snapshot() {
        // This test must exercise the cached-read-snapshot park/reuse path,
        // NOT the direct rowid-lookup fast path (which bypasses the snapshot
        // machinery). Use a non-fast-path SELECT shape (`LIMIT 1` without a
        // parameter) so the prepared statement carries no
        // `PreparedQueryFastPath` metadata; that forces execution through
        // `prepare_connection_for_prepared_read`, where the snapshot park /
        // reuse counters live.
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_cached_read (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_cached_read VALUES (1, 'alpha');")
            .unwrap();
        flush_retained_autocommit_for_cached_read_test(&conn);

        let stmt = conn
            .prepare("SELECT val FROM prep_cached_read ORDER BY id LIMIT 1")
            .unwrap();
        assert!(
            stmt.prepared_query_fast_path.is_none(),
            "test setup requires a SELECT shape that does not compile to a \
             PreparedQueryFastPath (otherwise the rowid-lookup fast path \
             bypasses the snapshot-park machinery this test is exercising); \
             fast_path = {:?}",
            stmt.prepared_query_fast_path,
        );

        reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.values()[0], SqliteValue::Text("alpha".into()));
        let first_profile = hot_path_profile_snapshot();
        assert_eq!(
            first_profile.cached_read_snapshot_reuses, 0,
            "first prepared read should begin a fresh cached snapshot: {first_profile:?}"
        );
        assert_eq!(
            first_profile.cached_read_snapshot_parks, 1,
            "first prepared read should park the autocommit read snapshot for reuse: {first_profile:?}"
        );

        let row = stmt.query_row().unwrap();
        assert_eq!(row.values()[0], SqliteValue::Text("alpha".into()));
        let second_profile = hot_path_profile_snapshot();
        assert_eq!(
            second_profile.cached_read_snapshot_reuses, 1,
            "second prepared read should reuse the parked autocommit read snapshot: {second_profile:?}"
        );
        assert_eq!(
            second_profile.cached_read_snapshot_parks, 2,
            "second prepared read should park the reused snapshot again for the next statement: {second_profile:?}"
        );
    }

    #[test]
    fn test_prepared_memory_query_row_rowid_lookup_uses_microbatch_schema_carry() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_rowid_carry (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_rowid_carry VALUES (1, 'alpha');")
            .unwrap();

        let stmt = conn
            .prepare("SELECT * FROM prep_rowid_carry WHERE id = ?1")
            .unwrap();
        assert!(matches!(
            stmt.prepared_query_fast_path.as_ref(),
            Some(PreparedQueryFastPath::SimpleRowidLookup { .. })
        ));

        reset_hot_path_profile();
        let row = stmt
            .query_row_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(1), SqliteValue::Text("alpha".into())]
        );
        flush_retained_autocommit_for_cached_read_test(&conn);
        let cx = conn.op_cx().unwrap();
        conn.reload_memdb_from_pager_with_mode(&cx, true).unwrap();
        assert!(
            stmt.clean_memory_prepared_memdb_fast_path_ready_without_refresh(),
            "after warming MemDB and flushing the retained snapshot, the no-refresh path should be ready"
        );

        let (hits_before, renewals_before) = conn.stmt_microbatch_counters();
        let row = stmt
            .query_row_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(1), SqliteValue::Text("alpha".into())]
        );
        let (hits_after_first, renewals_after_first) = conn.stmt_microbatch_counters();
        assert_eq!(
            hits_after_first, hits_before,
            "first rowid lookup should renew the schema-carry epoch"
        );
        assert_eq!(
            renewals_after_first,
            renewals_before + 1,
            "first rowid lookup should seed a schema-carry epoch"
        );

        let row = stmt
            .query_row_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(1), SqliteValue::Text("alpha".into())]
        );
        let (hits_after_second, renewals_after_second) = conn.stmt_microbatch_counters();
        assert_eq!(
            hits_after_second,
            hits_after_first + 1,
            "second consecutive rowid lookup should carry schema validation"
        );
        assert_eq!(
            renewals_after_second, renewals_after_first,
            "schema-carry hit should not renew the epoch"
        );

        let profile = hot_path_profile_snapshot();
        assert!(
            profile.direct_rowid_lookup_query_row_hits >= 3,
            "test must exercise the direct rowid query_row fast path at least three times: {profile:?}"
        );
    }

    #[test]
    fn test_prepared_memory_query_rejects_cached_read_snapshot_after_commit_epoch_moves() {
        // bd-#70: this test exercises the read-snapshot-park rejection path
        // (not the direct rowid-lookup fast path, which side-steps both the
        // cached snapshot machinery and the plan-cache epoch wedge — that
        // path is covered separately in
        // `test_direct_rowid_fast_path_consults_plan_cache_after_commit_epoch_moves`).
        // We deliberately use a `LIMIT 1` parameter-less SELECT so the
        // statement compiles without any `PreparedQueryFastPath`, forcing
        // execution through `prepare_connection_for_prepared_read`, which is
        // where the `cached_read_snapshot_commit_epoch` reuse guard lives.
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_cached_read_epoch (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_cached_read_epoch VALUES (1, 'alpha');")
            .unwrap();
        flush_retained_autocommit_for_cached_read_test(&conn);

        let stmt = conn
            .prepare("SELECT val FROM prep_cached_read_epoch ORDER BY id LIMIT 1")
            .unwrap();
        assert!(
            stmt.prepared_query_fast_path.is_none(),
            "test setup requires a SELECT shape that does not compile to a \
             PreparedQueryFastPath (otherwise the direct fast path bypasses \
             the snapshot-park guard this test is exercising); fast_path = {:?}",
            stmt.prepared_query_fast_path,
        );

        reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(row.values()[0], SqliteValue::Text("alpha".into()));
        let first_profile = hot_path_profile_snapshot();
        assert_eq!(
            first_profile.cached_read_snapshot_reuses, 0,
            "first read should park a fresh snapshot: {first_profile:?}"
        );
        assert_eq!(
            first_profile.cached_read_snapshot_parks, 1,
            "first read should leave a parked snapshot for reuse: {first_profile:?}"
        );
        let first_epoch = conn.cached_read_snapshot_commit_epoch.get();
        assert!(
            first_epoch > 0,
            "parked read snapshot should record the finalized commit epoch"
        );

        conn.stable_commit_seq.fetch_add(1, AtomicOrdering::AcqRel);

        let row = stmt.query_row().unwrap();
        assert_eq!(row.values()[0], SqliteValue::Text("alpha".into()));
        let second_profile = hot_path_profile_snapshot();
        assert_eq!(
            second_profile.cached_read_snapshot_reuses, 0,
            "stale parked read snapshot must not be reused after the commit epoch advances: {second_profile:?}"
        );
        assert_eq!(
            second_profile.cached_read_snapshot_parks, 2,
            "fresh read after epoch movement should park a replacement snapshot: {second_profile:?}"
        );
        assert!(
            conn.cached_read_snapshot_commit_epoch.get() > first_epoch,
            "replacement parked snapshot should capture the newer commit epoch"
        );
    }

    /// bd-#70 wedge coverage for the OTHER path: when execution takes the
    /// direct rowid-lookup query_row fast path (which bypasses the cached
    /// read snapshot park machinery entirely), a cross-connection write
    /// commit must still invalidate the prepared-cache plan template so the
    /// next prepare reseeds against the new commit epoch.
    ///
    /// This locks in that the `commit_epoch` wedge (commit 6939d77e) covers
    /// the rowid-lookup path even though
    /// `test_prepared_memory_query_rejects_cached_read_snapshot_after_commit_epoch_moves`
    /// deliberately uses a non-fast-path SELECT to exercise the read-snapshot
    /// park guard. Together the two tests prove the wedge defends both
    /// dispatch routes.
    #[test]
    fn test_direct_rowid_fast_path_consults_plan_cache_after_commit_epoch_moves() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("rowid-fast-path-epoch.db");
        let db_path = db_path.to_string_lossy().into_owned();

        let reader = Connection::open(&db_path).unwrap();
        let writer = Connection::open(&db_path).unwrap();
        reader
            .execute("CREATE TABLE rowid_fp_epoch (id INTEGER PRIMARY KEY, val TEXT)")
            .unwrap();
        reader
            .execute("INSERT INTO rowid_fp_epoch VALUES (1, 'alpha')")
            .unwrap();

        let sql = "SELECT val FROM rowid_fp_epoch WHERE id = ?1";

        // Reader prepares once. The template is keyed under the rowid-lookup
        // fast-path metadata AND carries the current commit_epoch at insert.
        let prepared = reader.prepare(sql).unwrap();
        assert!(
            matches!(
                prepared.prepared_query_fast_path.as_ref(),
                Some(
                    PreparedQueryFastPath::SimpleRowidLookup { .. }
                        | PreparedQueryFastPath::SimpleProjectedRowidLookup { .. }
                )
            ),
            "test requires the rowid-lookup fast path metadata is attached \
             to the prepared template; otherwise it does not exercise the \
             dispatch route the wedge must cover"
        );
        drop(prepared);

        let cache_key = reader.prepared_cache_key(sql);
        assert!(
            reader.lookup_prepared_cache(cache_key, sql).is_some(),
            "initial prepare on reader should seed the prepared cache"
        );

        // Cross-connection commit on the writer advances the shared
        // finalized commit epoch observed by reader.
        writer
            .execute("UPDATE rowid_fp_epoch SET val = 'beta' WHERE id = 1")
            .unwrap();

        // bd-#70 wedge: reader's next cache lookup must reject the rowid-fast-path
        // template whose commit_epoch is now stale.
        assert!(
            reader.lookup_prepared_cache(cache_key, sql).is_none(),
            "cross-connection commit must evict the rowid-fast-path template \
             at the next lookup (bd-#70 wedge applies to ALL non-direct-DML \
             templates, including those with rowid-lookup fast-path metadata)"
        );
    }

    #[test]
    fn test_prepared_memory_query_row_no_rows_fast_path_reuses_cached_read_snapshot() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_cached_read_no_rows (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_cached_read_no_rows VALUES (1, 'alpha');")
            .unwrap();
        flush_retained_autocommit_for_cached_read_test(&conn);

        let stmt = conn
            .prepare("SELECT val FROM prep_cached_read_no_rows WHERE id = ?1")
            .unwrap();

        reset_hot_path_profile();
        let err = stmt
            .query_row_with_params(&[SqliteValue::Integer(99)])
            .unwrap_err();
        assert!(matches!(err, FrankenError::QueryReturnedNoRows));
        let first_profile = hot_path_profile_snapshot();
        // `WHERE id = ?1` on an INTEGER PRIMARY KEY is a rowid point lookup, so
        // it is served by the direct rowid query_row fast path rather than the
        // generic cached-read-snapshot executor. A missing rowid yields
        // QueryReturnedNoRows directly off the in-memory image without parking a
        // reusable read snapshot. (The cached-read-snapshot park/reuse mechanism
        // for non-direct query_row shapes is covered by the `_row_cap_` and
        // `_for_each_callback_` sibling tests.)
        assert_eq!(
            first_profile.direct_rowid_lookup_query_row_hits, 1,
            "missing-rowid no-rows read should land on the direct rowid query_row fast path: {first_profile:?}"
        );
        assert_eq!(
            first_profile.cached_read_snapshot_parks, 0,
            "the direct rowid no-rows path resolves off the in-memory image and does not park a read snapshot: {first_profile:?}"
        );

        let err = stmt
            .query_row_with_params(&[SqliteValue::Integer(99)])
            .unwrap_err();
        assert!(matches!(err, FrankenError::QueryReturnedNoRows));
        let second_profile = hot_path_profile_snapshot();
        assert_eq!(
            second_profile.direct_rowid_lookup_query_row_hits, 2,
            "the repeated missing-rowid read stays on the direct rowid query_row fast path: {second_profile:?}"
        );
        assert_eq!(
            second_profile.cached_read_snapshot_reuses, 0,
            "the direct rowid no-rows path never parks, so there is no snapshot to reuse: {second_profile:?}"
        );
    }

    #[test]
    fn test_prepared_memory_query_row_no_rows_row_cap_reuses_cached_read_snapshot() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_cached_read_row_cap_no_rows (id INTEGER PRIMARY KEY, val TEXT);",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO prep_cached_read_row_cap_no_rows VALUES (1, 'alpha'), (2, 'beta');",
        )
        .unwrap();

        let stmt = conn
            .prepare("SELECT val FROM prep_cached_read_row_cap_no_rows WHERE val = ?1")
            .unwrap();
        assert!(
            stmt.prepared_query_fast_path.is_none(),
            "non-indexed text filter should stay off the dedicated prepared query_row fast paths",
        );
        assert!(
            stmt.can_use_query_row_result_row_cap(),
            "plain filtered lookup should use the row-cap query_row executor",
        );

        reset_hot_path_profile();
        let err = stmt
            .query_row_with_params(&[SqliteValue::Text("missing".into())])
            .unwrap_err();
        assert!(matches!(err, FrankenError::QueryReturnedNoRows));
        let first_profile = hot_path_profile_snapshot();
        assert_eq!(
            first_profile.cached_read_snapshot_reuses, 0,
            "first no-rows row-cap read should begin a fresh snapshot: {first_profile:?}"
        );
        assert_eq!(
            first_profile.cached_read_snapshot_parks, 1,
            "first no-rows row-cap read should still park the read snapshot: {first_profile:?}"
        );

        let err = stmt
            .query_row_with_params(&[SqliteValue::Text("missing".into())])
            .unwrap_err();
        assert!(matches!(err, FrankenError::QueryReturnedNoRows));
        let second_profile = hot_path_profile_snapshot();
        assert_eq!(
            second_profile.cached_read_snapshot_reuses, 1,
            "second no-rows row-cap read should reuse the parked snapshot: {second_profile:?}"
        );
        assert_eq!(
            second_profile.cached_read_snapshot_parks, 2,
            "second no-rows row-cap read should re-park the snapshot: {second_profile:?}"
        );
    }

    #[test]
    fn test_prepared_memory_query_for_each_callback_error_reuses_cached_read_snapshot() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_cached_read_for_each_callback (id INTEGER PRIMARY KEY, val TEXT);",
        )
        .unwrap();
        conn.execute("INSERT INTO prep_cached_read_for_each_callback VALUES (1, 'alpha');")
            .unwrap();
        flush_retained_autocommit_for_cached_read_test(&conn);

        let stmt = conn
            .prepare("SELECT val FROM prep_cached_read_for_each_callback WHERE id = ?1")
            .unwrap();

        reset_hot_path_profile();
        let err = stmt
            .query_with_params_for_each(&[SqliteValue::Integer(1)], |_row| {
                Err(FrankenError::Internal(
                    "stop after first streamed row".to_owned(),
                ))
            })
            .unwrap_err();
        match err {
            FrankenError::Internal(detail) => {
                assert_eq!(detail, "stop after first streamed row");
            }
            other => panic!("expected callback error to propagate unchanged, got {other:?}"),
        }
        let first_profile = hot_path_profile_snapshot();
        assert_eq!(
            first_profile.cached_read_snapshot_reuses, 0,
            "first callback-aborted streaming read should begin a fresh snapshot: {first_profile:?}"
        );
        assert_eq!(
            first_profile.cached_read_snapshot_parks, 1,
            "first callback-aborted streaming read should still park the read snapshot: {first_profile:?}"
        );

        let err = stmt
            .query_with_params_for_each(&[SqliteValue::Integer(1)], |_row| {
                Err(FrankenError::Internal(
                    "stop after first streamed row".to_owned(),
                ))
            })
            .unwrap_err();
        match err {
            FrankenError::Internal(detail) => {
                assert_eq!(detail, "stop after first streamed row");
            }
            other => panic!("expected callback error to propagate unchanged, got {other:?}"),
        }
        let second_profile = hot_path_profile_snapshot();
        assert_eq!(
            second_profile.cached_read_snapshot_reuses, 1,
            "second callback-aborted streaming read should reuse the parked snapshot: {second_profile:?}"
        );
        assert_eq!(
            second_profile.cached_read_snapshot_parks, 2,
            "second callback-aborted streaming read should re-park the snapshot: {second_profile:?}"
        );
    }

    #[test]
    fn test_prepared_file_backed_select_uses_lightweight_refresh_for_external_dml() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("prepared_lightweight_refresh_select.db");
        let db = db_path.to_string_lossy().into_owned();

        let conn1 = Connection::open(&db).unwrap();
        conn1.set_reject_mem_fallback(true);
        conn1.set_strict_mem_fallback_rejection(true);
        conn1
            .execute("CREATE TABLE prep_lightweight_sel (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn1
            .execute("INSERT INTO prep_lightweight_sel VALUES (1, 'alpha');")
            .unwrap();

        let conn2 = Connection::open(&db).unwrap();
        conn2.set_reject_mem_fallback(true);
        conn2.set_strict_mem_fallback_rejection(true);
        let stmt = conn2
            .prepare("SELECT val FROM prep_lightweight_sel WHERE id = ?1")
            .unwrap();
        let seed = stmt
            .query_row_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(seed.values()[0], SqliteValue::Text("alpha".into()));

        conn1
            .execute("INSERT INTO prep_lightweight_sel VALUES (2, 'beta');")
            .unwrap();

        reset_hot_path_profile();
        let row = stmt
            .query_row_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        assert_eq!(row.values()[0], SqliteValue::Text("beta".into()));

        let profile = hot_path_profile_snapshot();
        // `WHERE id = ?1` on an INTEGER PRIMARY KEY is a rowid point lookup, so
        // the external INSERT is picked up by the direct rowid query_row fast
        // path. That path refreshes the in-memory image lazily through a single
        // pager publication refresh / memdb refresh rather than the legacy
        // `refresh_prepared_schema_state` lane — so the legacy
        // `prepared_schema_*` counters stay 0 while the publication/memdb
        // refresh counters fire once.
        assert_eq!(
            profile.direct_rowid_lookup_query_row_hits, 1,
            "the post-DML read should be served by the direct rowid query_row fast path: {profile:?}"
        );
        assert_eq!(
            profile.pager_publication_refreshes, 1,
            "external DML on a file-backed prepared SELECT must trigger exactly one lightweight pager publication refresh: {profile:?}"
        );
        // The key invariant: a schema-stable external DML is absorbed without a
        // full sqlite_master reload or re-decode.
        assert_eq!(
            profile.prepared_schema_full_reloads, 0,
            "schema-stable external DML should avoid full sqlite_master reloads: {profile:?}"
        );
        assert_eq!(
            profile
                .record_decode
                .callsite_breakdown
                .core_connection
                .parse_record_calls,
            0,
            "lightweight refresh must not rescan sqlite_master rows: {profile:?}"
        );
    }

    #[test]
    fn test_prepared_file_backed_autoincrement_insert_refreshes_sequence_without_full_reload() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir
            .path()
            .join("prepared_lightweight_refresh_autoincrement.db");
        let db = db_path.to_string_lossy().into_owned();

        let conn1 = Connection::open(&db).unwrap();
        conn1.set_reject_mem_fallback(true);
        conn1.set_strict_mem_fallback_rejection(true);
        conn1
            .execute(
                "CREATE TABLE prep_lightweight_auto (id INTEGER PRIMARY KEY AUTOINCREMENT, val TEXT);",
            )
            .unwrap();
        let stmt = conn1
            .prepare("INSERT INTO prep_lightweight_auto (val) VALUES (?1)")
            .unwrap();

        let conn2 = Connection::open(&db).unwrap();
        conn2.set_reject_mem_fallback(true);
        conn2.set_strict_mem_fallback_rejection(true);
        conn2
            .execute("INSERT INTO prep_lightweight_auto (val) VALUES ('from_conn2');")
            .unwrap();

        reset_hot_path_profile();
        let affected = stmt
            .execute_with_params(&[SqliteValue::Text("from_conn1".into())])
            .unwrap();
        assert_eq!(affected, 1);

        let rows = conn1
            .query("SELECT id, val FROM prep_lightweight_auto ORDER BY id;")
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
        assert_eq!(rows[0].values()[1], SqliteValue::Text("from_conn2".into()));
        assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
        assert_eq!(rows[1].values()[1], SqliteValue::Text("from_conn1".into()));

        let profile = hot_path_profile_snapshot();
        assert_eq!(profile.prepared_schema_refreshes, 1);
        assert_eq!(
            profile.prepared_schema_lightweight_refreshes, 1,
            "AUTOINCREMENT prepared inserts should still use the lightweight refresh path when the schema is unchanged: {profile:?}"
        );
        assert_eq!(
            profile.prepared_schema_full_reloads, 0,
            "AUTOINCREMENT sequence upkeep should not force a full schema reload: {profile:?}"
        );
    }

    #[test]
    fn test_prepared_file_backed_insert_reuses_schema_bound_publication_for_autocommit_begin() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("prepared_insert_publication_reuse.db");
        let db = db_path.to_string_lossy().into_owned();

        let conn1 = Connection::open(&db).unwrap();
        conn1.set_reject_mem_fallback(true);
        conn1.set_strict_mem_fallback_rejection(true);
        conn1
            .execute("CREATE TABLE prep_pub_reuse (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        let stmt = conn1
            .prepare("INSERT INTO prep_pub_reuse (id, val) VALUES (?1, ?2)")
            .unwrap();

        let conn2 = Connection::open(&db).unwrap();
        conn2.set_reject_mem_fallback(true);
        conn2.set_strict_mem_fallback_rejection(true);
        conn2
            .execute("INSERT INTO prep_pub_reuse VALUES (1, 'from_conn2');")
            .unwrap();

        reset_hot_path_profile();
        let affected = stmt
            .execute_with_params(&[
                SqliteValue::Integer(2),
                SqliteValue::Text("from_conn1".into()),
            ])
            .unwrap();
        assert_eq!(affected, 1);

        let profile = hot_path_profile_snapshot();
        assert_eq!(profile.prepared_schema_refreshes, 1);
        assert!(
            profile.prepared_schema_refresh_time_ns > 0,
            "file-backed prepared refresh should accumulate schema-refresh time: {profile:?}"
        );
        assert_eq!(
            profile.prepared_schema_lightweight_refreshes, 1,
            "schema-stable external DML should still use the lightweight prepared refresh path: {profile:?}"
        );
        assert_eq!(
            profile.prepared_schema_full_reloads, 0,
            "schema-stable external DML should avoid a full MemDB reload before the prepared insert: {profile:?}"
        );
        assert_eq!(
            profile.pager_publication_refreshes, 1,
            "prepared insert should reuse the schema-bound publication instead of rebinding during autocommit begin: {profile:?}"
        );
        assert!(
            profile.begin_setup_time_ns > 0,
            "file-backed prepared insert should accumulate begin/autocommit setup time: {profile:?}"
        );
        assert!(
            profile.execute_body_time_ns > 0,
            "prepared insert fast path should accumulate direct execute-body time: {profile:?}"
        );
        assert!(
            profile.commit_txn_roundtrip_time_ns > 0,
            "commit path should expose outer txn.commit() roundtrip time: {profile:?}"
        );
        assert!(
            profile.commit_handle_finalize_time_ns > 0,
            "commit handle teardown should be visible after txn.commit(): {profile:?}"
        );
        assert!(
            profile.commit_post_write_maintenance_time_ns > 0,
            "post-write maintenance should be visible after pager commit completes: {profile:?}"
        );
        assert!(
            profile.finalize_post_publish_time_ns > 0,
            "autocommit commit cleanup/publish work should be visible after the write body: {profile:?}"
        );
        assert_eq!(
            profile.prepared_insert_fast_lane_hits, 1,
            "simple prepared insert should stay on the fast lane while reusing the schema-bound publication: {profile:?}"
        );

        let rows = conn1
            .query("SELECT id, val FROM prep_pub_reuse ORDER BY id;")
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
        assert_eq!(rows[0].values()[1], SqliteValue::Text("from_conn2".into()));
        assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
        assert_eq!(rows[1].values()[1], SqliteValue::Text("from_conn1".into()));
    }

