    #[test]
    fn test_prepared_count_sum_cache_survives_noop_direct_dml_in_retained_batch() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE mem_retained_count_sum_noop_dml \
             (id INTEGER PRIMARY KEY, score INTEGER NOT NULL);",
        )
        .unwrap();
        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| {
                table
                    .name
                    .eq_ignore_ascii_case("mem_retained_count_sum_noop_dml")
            })
            .map(|table| table.root_page)
            .expect("test table root page");
        conn.execute("INSERT INTO mem_retained_count_sum_noop_dml VALUES (1, 10), (2, 20);")
            .unwrap();

        let aggregate = conn
            .prepare("SELECT COUNT(*), SUM(score) FROM mem_retained_count_sum_noop_dml;")
            .unwrap();
        let insert = conn
            .prepare("INSERT INTO mem_retained_count_sum_noop_dml VALUES (?1, ?2);")
            .unwrap();
        let update = conn
            .prepare("UPDATE mem_retained_count_sum_noop_dml SET score = ?2 WHERE id = ?1;")
            .unwrap();
        let delete = conn
            .prepare("DELETE FROM mem_retained_count_sum_noop_dml WHERE id = ?1;")
            .unwrap();

        let row = aggregate.query_row().unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(2), SqliteValue::Integer(30)]
        );

        insert
            .execute_with_params(&[SqliteValue::Integer(3), SqliteValue::Integer(30)])
            .unwrap();
        assert!(conn.retained_autocommit_txn.borrow().is_some());
        assert_eq!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .as_ref()
                .map(Row::values),
            Some(&[SqliteValue::Integer(3), SqliteValue::Integer(60)][..])
        );

        assert_eq!(
            update
                .execute_with_params(&[SqliteValue::Integer(999), SqliteValue::Integer(999)])
                .unwrap(),
            0
        );
        assert_eq!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .as_ref()
                .map(Row::values),
            Some(&[SqliteValue::Integer(3), SqliteValue::Integer(60)][..]),
            "zero-row direct UPDATE must not invalidate the retained aggregate cache"
        );

        assert_eq!(
            delete
                .execute_with_params(&[SqliteValue::Integer(999)])
                .unwrap(),
            0
        );
        assert_eq!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .as_ref()
                .map(Row::values),
            Some(&[SqliteValue::Integer(3), SqliteValue::Integer(60)][..]),
            "zero-row direct DELETE must not invalidate the retained aggregate cache"
        );

        reset_hot_path_profile();
        let row = aggregate.query_row().unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(3), SqliteValue::Integer(60)]
        );
        let profile = hot_path_profile_snapshot();
        assert!(
            profile.retained_autocommit_overlay_hits >= 1,
            "aggregate after no-op DML should use the retained overlay cache: {profile:?}"
        );
        assert_eq!(
            profile.retained_autocommit_read_after_write_flushes, 0,
            "no-op DML should not force a retained read-after-write flush: {profile:?}"
        );
    }

    #[test]
    fn test_memory_retained_autocommit_count_sum_cache_survives_flush_boundary() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE mem_retained_count_sum_flush (id INTEGER PRIMARY KEY, score INTEGER NOT NULL);",
        )
        .unwrap();
        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| {
                table
                    .name
                    .eq_ignore_ascii_case("mem_retained_count_sum_flush")
            })
            .map(|table| table.root_page)
            .expect("test table root page");
        let stmt = conn
            .prepare("SELECT COUNT(*), SUM(score) FROM mem_retained_count_sum_flush;")
            .unwrap();
        let insert = conn
            .prepare("INSERT INTO mem_retained_count_sum_flush VALUES (?1, ?2);")
            .unwrap();

        insert
            .execute_with_params(&[SqliteValue::Integer(1), SqliteValue::Integer(10)])
            .unwrap();
        insert
            .execute_with_params(&[SqliteValue::Integer(2), SqliteValue::Integer(20)])
            .unwrap();
        assert!(conn.retained_autocommit_txn.borrow().is_some());

        let row = stmt.query_row().unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(2), SqliteValue::Integer(30)]
        );

        let cx = conn.op_cx().unwrap();
        conn.flush_retained_autocommit_txn(&cx).unwrap();
        assert!(conn.retained_autocommit_txn.borrow().is_none());
        assert_eq!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .as_ref()
                .map(Row::values),
            Some(&[SqliteValue::Integer(2), SqliteValue::Integer(30)][..])
        );

        insert
            .execute_with_params(&[SqliteValue::Integer(3), SqliteValue::Integer(30)])
            .unwrap();
        assert_eq!(
            conn.retained_autocommit_count_sum_cache_row(root_page, 1, Some(0))
                .as_ref()
                .map(Row::values),
            Some(&[SqliteValue::Integer(3), SqliteValue::Integer(60)][..])
        );

        reset_hot_path_profile();
        let row = stmt.query_row().unwrap();
        assert_eq!(
            row.values(),
            &[SqliteValue::Integer(3), SqliteValue::Integer(60)]
        );
        let profile = hot_path_profile_snapshot();
        assert!(
            profile.retained_autocommit_overlay_hits >= 1,
            "prepared count+sum query should use the preserved cache through the retained overlay: {profile:?}"
        );
        assert_eq!(
            profile.retained_autocommit_read_after_write_flushes, 0,
            "preserved cache should avoid a read-after-write flush: {profile:?}"
        );
    }

    #[test]
    fn test_memory_autocommit_write_txn_invalidated_by_ddl() {
        // bd-aw0b9: verify that DDL (schema change) invalidates the retained
        // writer state so the next write gets a fresh begin path.
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE ddl_inv (id INTEGER PRIMARY KEY);")
            .unwrap();

        reset_hot_path_profile();

        // First write: parks the write txn.
        conn.execute("INSERT INTO ddl_inv VALUES (1);").unwrap();
        let p1 = hot_path_profile_snapshot();
        assert_eq!(p1.retained_autocommit_parks, 1);

        // DDL should invalidate the retained write txn.
        conn.execute("CREATE TABLE ddl_inv2 (id INTEGER PRIMARY KEY);")
            .unwrap();
        assert!(
            conn.retained_autocommit_txn.borrow().is_none(),
            "DDL should flush/invalidate retained autocommit state"
        );

        reset_hot_path_profile();
        conn.execute("INSERT INTO ddl_inv VALUES (2);").unwrap();
        let p2 = hot_path_profile_snapshot();
        assert!(
            p2.memory_autocommit_fast_path_begins >= 1 || p2.cached_write_txn_reuses >= 1,
            "write after DDL should rebuild writer state instead of reusing the pre-DDL retained txn: {p2:?}"
        );
        assert_eq!(p2.retained_autocommit_reuses, 0);
    }

    #[test]
    fn test_memory_autocommit_write_txn_correctness_across_many_inserts() {
        // bd-aw0b9: stress test that many consecutive autocommit writes
        // produce correct results when the write txn is continuously reused.
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE stress (id INTEGER PRIMARY KEY, val INTEGER);")
            .unwrap();

        for i in 1..=100 {
            conn.execute_with_params(
                "INSERT INTO stress VALUES (?1, ?2);",
                &[SqliteValue::Integer(i), SqliteValue::Integer(i * 10)],
            )
            .unwrap();
        }

        let rows = conn
            .query("SELECT COUNT(*), SUM(val) FROM stress;")
            .unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(100));
        // SUM(10+20+...+1000) = 10 * SUM(1..100) = 10 * 5050 = 50500
        assert_eq!(rows[0].values()[1], SqliteValue::Integer(50500));
    }

    #[test]
    fn test_memory_autocommit_write_txn_keeps_commit_clock_synced() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE commit_sync (id INTEGER PRIMARY KEY);")
            .unwrap();

        let seq_after_ddl = conn.current_global_commit_seq();

        conn.execute("INSERT INTO commit_sync VALUES (1);").unwrap();

        let seq_after_autocommit = conn.current_global_commit_seq();
        assert!(
            seq_after_autocommit >= seq_after_ddl,
            "retained :memory: autocommit batching must not move the visible commit clock backwards"
        );

        let rows = conn.query("SELECT COUNT(*) FROM commit_sync;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
        let seq_after_flush = conn.current_global_commit_seq();
        assert!(
            seq_after_flush > seq_after_ddl,
            "flushing the retained :memory: batch must advance the visible commit clock"
        );
        assert_eq!(
            conn.last_local_commit_seq(),
            Some(seq_after_flush.get()),
            "the retained-batch flush should keep last_local_commit_seq aligned"
        );

        conn.execute("BEGIN;").unwrap();
        conn.execute("INSERT INTO commit_sync VALUES (2);").unwrap();
        conn.execute("COMMIT;").unwrap();

        let seq_after_explicit = conn.current_global_commit_seq();
        assert!(
            seq_after_explicit > seq_after_flush,
            "a later explicit COMMIT must remain strictly monotonic after fast-path autocommit writes"
        );
        assert_eq!(
            conn.last_local_commit_seq(),
            Some(seq_after_explicit.get()),
            "explicit COMMIT should continue to refresh last_local_commit_seq after autocommit reuse"
        );
    }

    #[test]
    fn test_prepared_table_query_row_reuses_table_engine_after_first_execution() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE prep_query_row_engine_reuse (id INTEGER PRIMARY KEY, val TEXT);",
        )
        .unwrap();
        conn.execute("INSERT INTO prep_query_row_engine_reuse VALUES (1, 'alpha'), (2, 'beta');")
            .unwrap();

        let stmt = conn
            .prepare("SELECT val FROM prep_query_row_engine_reuse WHERE id = ?1")
            .unwrap();

        reset_statement_reuse_measurement(&conn);
        let first = stmt
            .query_row_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        let second = stmt
            .query_row_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        assert_eq!(first.values()[0], SqliteValue::Text("alpha".into()));
        assert_eq!(second.values()[0], SqliteValue::Text("beta".into()));

        let profile = hot_path_profile_snapshot();
        // `SELECT val FROM t WHERE id = ?1` on an INTEGER PRIMARY KEY is a point
        // lookup on the rowid, so it is served by the dedicated direct rowid
        // query_row fast path (commits 23aabe82 / e9fc471b "prove B3 point
        // lookup scaling"). That path is strictly faster than the reusable
        // VDBE table-engine shell and never allocates one — so both engine
        // counters stay 0 while every execution lands on the direct lane.
        assert_eq!(
            profile.prepared_table_engine_fresh_allocs, 0,
            "rowid point-lookup query_row must stay on the direct rowid fast path, never the reusable table engine: {profile:?}"
        );
        assert_eq!(
            profile.prepared_table_engine_reuses, 0,
            "rowid point-lookup query_row must not reuse a table engine because it never allocates one: {profile:?}"
        );
        assert_eq!(
            profile.direct_rowid_lookup_query_row_hits, 2,
            "both rowid point lookups should land on the direct rowid query_row fast path: {profile:?}"
        );
        assert_eq!(
            profile.parser.fast_path_executions, 2,
            "both executions should be counted as fast-path executions: {profile:?}"
        );
    }

    #[test]
    fn test_prepared_insert_reuses_table_engine_after_first_execution() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_engine_reuse (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();

        let insert_stmt = conn
            .prepare("INSERT INTO prep_engine_reuse (id, val) VALUES (?1, ?2)")
            .unwrap();

        reset_statement_reuse_measurement(&conn);
        for id in 1_i64..=2 {
            let affected = insert_stmt
                .execute_with_params(&[
                    SqliteValue::Integer(id),
                    SqliteValue::Text(format!("v{id}").into()),
                ])
                .unwrap();
            assert_eq!(affected, 1);
        }

        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.prepared_table_engine_fresh_allocs, 0,
            "benchmark-shaped prepared INSERT should stay on the direct fast lane instead of allocating a table-engine shell: {profile:?}"
        );
        assert_eq!(
            profile.prepared_table_engine_reuses, 0,
            "benchmark-shaped prepared INSERT should avoid table-engine reuse accounting when the direct fast lane owns execution: {profile:?}"
        );
        assert_eq!(
            profile.prepared_insert_fast_lane_hits, 2,
            "ordinary prepared inserts should stay on the slim fast lane when tracing is off: {profile:?}"
        );
        assert_eq!(
            profile.prepared_insert_instrumented_lane_hits, 0,
            "ordinary prepared inserts should avoid the instrumented lane when tracing is off: {profile:?}"
        );
        assert_eq!(
            profile.prepared_direct_insert_executions, 2,
            "ordinary prepared inserts should execute through the dedicated direct-insert lane on every execution: {profile:?}"
        );
        assert_eq!(
            profile.prepared_table_dml_affected_only_runs, 0,
            "ordinary prepared inserts should bypass the generic affected-only VDBE handoff when the direct lane is available: {profile:?}"
        );
        assert_eq!(
            profile.autoincrement_sequence_fast_path_updates, 0,
            "ordinary prepared inserts should skip AUTOINCREMENT follow-up work: {profile:?}"
        );
        assert_eq!(
            profile.autoincrement_sequence_scan_refreshes, 0,
            "ordinary prepared inserts should skip sqlite_sequence scan refreshes: {profile:?}"
        );
    }

    #[test]
    fn test_prepared_update_uses_autocommit_direct_lane() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_update_engine_reuse (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_update_engine_reuse VALUES (1, 'a'), (2, 'b');")
            .unwrap();

        let stmt = conn
            .prepare("UPDATE prep_update_engine_reuse SET val = ?1 WHERE id = ?2")
            .unwrap();

        reset_statement_reuse_measurement(&conn);
        let first = stmt
            .execute_with_params(&[SqliteValue::Text("alpha".into()), SqliteValue::Integer(1)])
            .unwrap();
        let second = stmt
            .execute_with_params(&[SqliteValue::Text("beta".into()), SqliteValue::Integer(2)])
            .unwrap();
        assert_eq!(first, 1);
        assert_eq!(second, 1);

        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.prepared_table_engine_fresh_allocs, 0,
            "autocommit direct-simple prepared UPDATE should bypass the reusable table-engine shell: {profile:?}"
        );
        assert_eq!(
            profile.prepared_table_engine_reuses, 0,
            "autocommit direct-simple prepared UPDATE should not report table-engine reuse: {profile:?}"
        );
        assert_eq!(
            profile.prepared_update_delete_fast_lane_hits, 0,
            "autocommit direct-simple prepared UPDATE should return before the fused VDBE update/delete lane: {profile:?}"
        );
        assert_eq!(
            profile.prepared_update_delete_instrumented_lane_hits, 0,
            "simple prepared UPDATE should avoid the instrumented lane when tracing is off: {profile:?}"
        );
        assert_eq!(
            profile.prepared_table_dml_affected_only_runs, 0,
            "autocommit direct-simple prepared UPDATE should avoid the affected-only VDBE handoff: {profile:?}"
        );
        assert_eq!(
            profile.prepared_update_delete_dml_direct_handoff_runs, 0,
            "autocommit direct-simple prepared UPDATE should avoid the update/delete VDBE handoff: {profile:?}"
        );
        assert_eq!(
            profile.prepared_direct_update_executions, 2,
            "autocommit direct-simple prepared UPDATE should use the dedicated direct UPDATE lane on every execute: {profile:?}"
        );
        assert_eq!(
            profile.prepared_direct_delete_executions, 0,
            "prepared UPDATE should not increment the direct DELETE lane: {profile:?}"
        );

        let rows = conn
            .query("SELECT val FROM prep_update_engine_reuse ORDER BY id")
            .unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));
        assert_eq!(rows[1].values()[0], SqliteValue::Text("beta".into()));
    }

