    #[test]
    fn test_programless_prepared_update_delete_forced_fallback_use_deferred_path() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE prep_ud_forced_fallback (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO prep_ud_forced_fallback VALUES (1, 'a'), (2, 'b');")
            .unwrap();
        conn.execute("PRAGMA fsqlite.fused_entry_mode = forced_fallback;")
            .unwrap();

        let update_stmt = conn
            .prepare("UPDATE prep_ud_forced_fallback SET val = ?1 WHERE id = ?2")
            .unwrap();
        let delete_stmt = conn
            .prepare("DELETE FROM prep_ud_forced_fallback WHERE id = ?1")
            .unwrap();

        reset_hot_path_profile();
        let updated = update_stmt
            .execute_with_params(&[SqliteValue::Text("forced".into()), SqliteValue::Integer(1)])
            .unwrap();
        let deleted = delete_stmt
            .execute_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        assert_eq!(updated, 1);
        assert_eq!(deleted, 1);

        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.prepared_update_delete_fast_lane_hits, 0,
            "forced fallback should keep prepared UPDATE/DELETE off the fused fast lane: {profile:?}"
        );
        assert_eq!(
            profile.prepared_update_delete_instrumented_lane_hits, 0,
            "programless forced fallback should use deferred statement execution, not the reusable table-program lane: {profile:?}"
        );
        assert_eq!(
            profile.prepared_direct_update_executions, 0,
            "programless forced fallback should keep UPDATE off the direct lane: {profile:?}"
        );
        assert_eq!(
            profile.prepared_direct_delete_executions, 0,
            "programless forced fallback should keep DELETE off the direct lane: {profile:?}"
        );

        let rows = conn
            .query("SELECT id, val FROM prep_ud_forced_fallback ORDER BY id")
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
        assert_eq!(rows[0].values()[1], SqliteValue::Text("forced".into()));
    }

    /// Verify the direct-simple UPDATE/DELETE fast path actually runs for the
    /// `UPDATE t SET c = ?N WHERE id = ?M` / `DELETE FROM t WHERE id = ?N`
    /// shape inside an explicit transaction, and produces correct results.
    #[test]
    fn test_direct_simple_update_delete_fast_path_executes_and_is_correct() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE direct_ud (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .unwrap();
        conn.execute("BEGIN").unwrap();
        let ins = conn
            .prepare("INSERT INTO direct_ud VALUES (?1, ('user_' || ?1), (?1 * 0.5))")
            .unwrap();
        for i in 0..5i64 {
            ins.execute_with_params(&[SqliteValue::Integer(i)]).unwrap();
        }
        conn.execute("COMMIT").unwrap();

        reset_hot_path_profile();

        conn.execute("BEGIN").unwrap();
        let upd = conn
            .prepare("UPDATE direct_ud SET value = ?2 WHERE id = ?1")
            .unwrap();
        assert_eq!(
            upd.execute_with_params(&[SqliteValue::Integer(2), SqliteValue::Float(99.0)])
                .unwrap(),
            1,
        );
        // Non-existent id: still succeeds but affects 0 rows.
        assert_eq!(
            upd.execute_with_params(&[SqliteValue::Integer(999), SqliteValue::Float(1.0)])
                .unwrap(),
            0,
        );
        let del = conn.prepare("DELETE FROM direct_ud WHERE id = ?1").unwrap();
        assert_eq!(
            del.execute_with_params(&[SqliteValue::Integer(3)]).unwrap(),
            1,
        );
        assert_eq!(
            del.execute_with_params(&[SqliteValue::Integer(999)])
                .unwrap(),
            0,
        );
        conn.execute("COMMIT").unwrap();

        let profile = hot_path_profile_snapshot();
        assert!(
            profile.prepared_direct_update_executions >= 2,
            "direct-simple UPDATE fast path should have been invoked at least twice (hit + miss): {profile:?}"
        );
        assert!(
            profile.prepared_direct_delete_executions >= 2,
            "direct-simple DELETE fast path should have been invoked at least twice (hit + miss): {profile:?}"
        );

        // Verify final row image is correct.
        let rows = conn
            .query("SELECT id, name, value FROM direct_ud ORDER BY id")
            .unwrap();
        assert_eq!(rows.len(), 4, "row 3 should be deleted");
        let row = &rows[2];
        assert_eq!(row.values()[0], SqliteValue::Integer(2));
        // value was updated to 99.0
        assert_eq!(row.values()[2], SqliteValue::Float(99.0));
        // name was left untouched (SET only touched `value`)
        assert_eq!(row.values()[1], SqliteValue::Text("user_2".into()));
    }

    #[test]
    fn test_direct_simple_update_delete_rowid_lookup_rejects_prefix_coercion() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE direct_ud_rowid_lookup (id INTEGER PRIMARY KEY, name TEXT NOT NULL);",
        )
        .unwrap();
        conn.execute("INSERT INTO direct_ud_rowid_lookup VALUES (0, 'zero'), (5, 'five');")
            .unwrap();

        let upd = conn
            .prepare("UPDATE direct_ud_rowid_lookup SET name = ?2 WHERE id = ?1")
            .unwrap();
        assert!(
            upd.prepared_update_delete_fast_path()
                .is_some_and(PreparedUpdateDeleteFastPath::has_direct_simple_dispatch),
            "test must exercise the prepared direct UPDATE lane"
        );
        let del = conn
            .prepare("DELETE FROM direct_ud_rowid_lookup WHERE id = ?1")
            .unwrap();
        assert!(
            del.prepared_update_delete_fast_path()
                .is_some_and(PreparedUpdateDeleteFastPath::has_direct_simple_dispatch),
            "test must exercise the prepared direct DELETE lane"
        );

        reset_hot_path_profile();
        conn.execute("BEGIN;").unwrap();
        assert_eq!(
            upd.execute_with_params(&[
                SqliteValue::Text("0abc".into()),
                SqliteValue::Text("bad_prefix".into()),
            ])
            .unwrap(),
            0
        );
        assert_eq!(
            upd.execute_with_params(&[
                SqliteValue::Float(5.5),
                SqliteValue::Text("bad_float".into()),
            ])
            .unwrap(),
            0
        );
        assert_eq!(
            del.execute_with_params(&[SqliteValue::Text("abc".into())])
                .unwrap(),
            0
        );
        assert_eq!(
            del.execute_with_params(&[SqliteValue::Float(0.5)]).unwrap(),
            0
        );
        assert_eq!(
            upd.execute_with_params(&[
                SqliteValue::Text("5.0".into()),
                SqliteValue::Text("integral_text".into()),
            ])
            .unwrap(),
            1
        );
        conn.execute("COMMIT;").unwrap();

        let profile = hot_path_profile_snapshot();
        assert!(
            profile.prepared_direct_update_executions >= 3,
            "direct UPDATE lane should handle both misses and the exact integral hit: {profile:?}"
        );
        assert!(
            profile.prepared_direct_delete_executions >= 2,
            "direct DELETE lane should handle no-match rowid coercions: {profile:?}"
        );

        let rows = conn
            .query("SELECT id, name FROM direct_ud_rowid_lookup ORDER BY id;")
            .unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>(),
            vec![
                vec![SqliteValue::Integer(0), SqliteValue::Text("zero".into())],
                vec![
                    SqliteValue::Integer(5),
                    SqliteValue::Text("integral_text".into()),
                ],
            ],
        );
    }

