    #[test]
    fn test_prepared_delete_fk_parent_path_skips_direct_dispatch() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").unwrap();
        conn.execute("CREATE TABLE prep_delete_parent (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute(
            "CREATE TABLE prep_delete_child (
                id INTEGER PRIMARY KEY,
                parent_id INTEGER REFERENCES prep_delete_parent(id) ON DELETE CASCADE
            );",
        )
        .unwrap();
        conn.execute("INSERT INTO prep_delete_parent VALUES (1, 'a'), (2, 'b');")
            .unwrap();
        conn.execute("INSERT INTO prep_delete_child VALUES (10, 1), (11, 2);")
            .unwrap();

        let stmt = conn
            .prepare("DELETE FROM prep_delete_parent WHERE id = ?1")
            .unwrap();

        reset_hot_path_profile();
        let affected = stmt
            .execute_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(affected, 1);

        let profile = hot_path_profile_snapshot();
        assert_eq!(
            profile.prepared_update_delete_fallback_foreign_key, 1,
            "DELETE on an FK parent must attribute the generic statement fallback to foreign-key work before reusing any precompiled VDBE handoff: {profile:?}"
        );
        assert_eq!(
            profile.prepared_update_delete_instrumented_lane_hits, 0,
            "DELETE on an FK parent should not route through the tracing-only instrumented lane: {profile:?}"
        );

        let parent_rows = conn
            .query("SELECT id FROM prep_delete_parent ORDER BY id")
            .unwrap();
        assert_eq!(parent_rows.len(), 1);
        assert_eq!(parent_rows[0].values()[0], SqliteValue::Integer(2));
        let child_rows = conn
            .query("SELECT id FROM prep_delete_child ORDER BY id")
            .unwrap();
        assert_eq!(child_rows.len(), 1);
        assert_eq!(child_rows[0].values()[0], SqliteValue::Integer(11));
    }

    #[test]
    fn test_prepared_delete_fast_path_rechecks_foreign_key_pragma_dynamically() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA foreign_keys = OFF;").unwrap();
        conn.execute("CREATE TABLE prep_fk_toggle_parent (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute(
            "CREATE TABLE prep_fk_toggle_child (
                id INTEGER PRIMARY KEY,
                parent_id INTEGER REFERENCES prep_fk_toggle_parent(id) ON DELETE CASCADE
            );",
        )
        .unwrap();
        conn.execute("INSERT INTO prep_fk_toggle_parent VALUES (1, 'a'), (2, 'b');")
            .unwrap();
        conn.execute("INSERT INTO prep_fk_toggle_child VALUES (10, 1), (11, 2);")
            .unwrap();

        let stmt = conn
            .prepare("DELETE FROM prep_fk_toggle_parent WHERE id = ?1")
            .unwrap();
        assert!(stmt.prepared_update_delete_fast_path.is_some());

        reset_hot_path_profile();
        let affected = stmt
            .execute_with_params(&[SqliteValue::Integer(1)])
            .unwrap();
        assert_eq!(affected, 1);
        let fast_profile = hot_path_profile_snapshot();
        assert_eq!(
            fast_profile.prepared_update_delete_fast_lane_hits, 2,
            "foreign_keys=OFF should record both fast-lane selection and fused-entry execution for the cached DELETE path: {fast_profile:?}"
        );
        assert_eq!(
            fast_profile.prepared_update_delete_fallback_foreign_key, 0,
            "foreign_keys=OFF should not force the FK fallback: {fast_profile:?}"
        );

        conn.execute("PRAGMA foreign_keys = ON;").unwrap();
        reset_hot_path_profile();
        let affected = stmt
            .execute_with_params(&[SqliteValue::Integer(2)])
            .unwrap();
        assert_eq!(affected, 1);
        let fallback_profile = hot_path_profile_snapshot();
        assert_eq!(
            fallback_profile.prepared_update_delete_fallback_foreign_key, 1,
            "foreign_keys=ON should still trigger FK fallback even when the prepared statement has cached metadata: {fallback_profile:?}"
        );

        let child_rows = conn
            .query("SELECT id, parent_id FROM prep_fk_toggle_child ORDER BY id")
            .unwrap();
        assert_eq!(
            child_rows.len(),
            1,
            "the foreign_keys=ON execution should still route through generic cascade handling"
        );
        assert_eq!(child_rows[0].values()[0], SqliteValue::Integer(10));
        assert_eq!(child_rows[0].values()[1], SqliteValue::Integer(1));
    }

