    // ── Window function tests ──────────────────────────────────────

    fn setup_window_test() -> Connection {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE scores(id INTEGER PRIMARY KEY, name TEXT, subject TEXT, score INTEGER);",
        )
        .unwrap();
        conn.execute("INSERT INTO scores VALUES (1, 'Alice', 'math', 90), (2, 'Bob', 'math', 85), (3, 'Charlie', 'math', 90), (4, 'Alice', 'science', 80), (5, 'Bob', 'science', 95), (6, 'Charlie', 'science', 70);").unwrap();
        conn
    }

    #[test]
    fn test_window_row_number() {
        let conn = setup_window_test();
        let rows = conn
            .query("SELECT name, score, ROW_NUMBER() OVER (ORDER BY score DESC) as rn FROM scores WHERE subject = 'math'")
            .unwrap();
        assert_eq!(rows.len(), 3, "expected 3 rows");
        // ROW_NUMBER assigns sequential numbers ordered by score DESC.
        // Scores: Alice 90, Charlie 90, Bob 85 → rn = 1, 2, 3
        let rn_values: Vec<i64> = rows
            .iter()
            .map(|r| match &r.values()[2] {
                SqliteValue::Integer(v) => *v,
                other => panic!("expected Integer, got {other:?}"),
            })
            .collect();
        assert_eq!(rn_values, vec![1, 2, 3]);
    }

    #[test]
    fn test_window_select_schema_borrow_conflict_returns_error_not_panic() {
        let conn = setup_window_test();
        let select = parse_select_statement(
            "SELECT name, score, ROW_NUMBER() OVER (ORDER BY score DESC) as rn \
             FROM scores WHERE subject = 'math'",
        );

        let _schema_write = conn.schema.borrow_mut();
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            conn.execute_window_select(&select, None)
        }));

        let err = result
            .expect("window SELECT planning should not panic on schema borrow conflict")
            .expect_err("schema borrow conflict should be reported as a query error");
        assert!(
            err.to_string()
                .contains("schema metadata is already mutably borrowed"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn test_window_row_number_partition_collate_nocase_dedup_shape() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE agents(
                id INTEGER PRIMARY KEY,
                project_id INTEGER NOT NULL,
                name TEXT NOT NULL,
                last_active_ts INTEGER NOT NULL
            );",
        )
        .unwrap();
        conn.execute(
            "INSERT INTO agents VALUES
                (1, 7, 'BlueLake', 10),
                (2, 7, 'bluelake', 20),
                (3, 7, 'GreenField', 30);",
        )
        .unwrap();

        let rows = conn
            .query(
                "SELECT id, name
                 FROM (
                   SELECT id, name, last_active_ts,
                          ROW_NUMBER() OVER (
                            PARTITION BY name COLLATE NOCASE
                            ORDER BY last_active_ts DESC, id DESC
                          ) AS rn
                   FROM agents
                   WHERE project_id = 7
                 ) dedup
                 WHERE rn = 1
                 ORDER BY last_active_ts DESC, id DESC",
            )
            .unwrap();

        let ids = rows
            .iter()
            .map(|row| match &row.values()[0] {
                SqliteValue::Integer(id) => *id,
                other => panic!("expected Integer id, got {other:?}"),
            })
            .collect::<Vec<_>>();
        assert_eq!(ids, vec![3, 2]);
    }

    #[test]
    fn test_join_eval_collation_context_callback_allows_nested_guard() {
        let context = JoinEvalCollationContext {
            column_collations: vec![Some("NOCASE".to_owned())],
            column_affinities: vec![TypeAffinity::Text],
            registry: CollationRegistry::new(),
        };
        let _outer_guard = JoinEvalCollationContextGuard::push(context.clone());

        with_current_join_eval_collation_context(|outer| {
            assert!(outer.is_some(), "outer context should be visible");
            let _inner_guard = JoinEvalCollationContextGuard::push(context);
            with_current_join_eval_collation_context(|inner| {
                assert!(inner.is_some(), "inner context should be visible");
            });
        });
    }

