    #[test]
    fn autocommit_dml_skips_memdb_time_travel_snapshot_capture() {
        let _serial = super::fsqlite_core_test_serializer();
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();

        let snapshot_count_after_ddl = conn.time_travel_snapshots.borrow().len();
        assert_eq!(
            snapshot_count_after_ddl, 1,
            "autocommit DDL should still retain the schema snapshot for time-travel"
        );

        conn.execute("INSERT INTO t VALUES (1, 'hello');").unwrap();
        conn.execute("UPDATE t SET val = 'world' WHERE id = 1;")
            .unwrap();
        conn.execute("DELETE FROM t WHERE id = 1;").unwrap();

        let snapshots = conn.time_travel_snapshots.borrow();
        assert_eq!(
            snapshots.len(),
            snapshot_count_after_ddl,
            "ordinary autocommit DML should not clone MemDatabase history on every statement"
        );
        assert_eq!(
            snapshots[0].commit_seq, 1,
            "the retained snapshot should still be the post-DDL schema state"
        );
    }

    #[test]
    fn file_backed_connections_reopen_with_schema_only_memdb_rows() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("schema_only_memdb_reload.db");
        let path_str = path.to_str().unwrap();

        {
            let conn = Connection::open(path_str).unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, val TEXT);")
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'hello');").unwrap();
            conn.execute("INSERT INTO t VALUES (2, 'world');").unwrap();
        }

        let conn = Connection::open(path_str).unwrap();
        assert!(
            !conn.memdb_rows_loaded.get(),
            "file-backed parity-cert connections should not eagerly hydrate table rows"
        );

        let root_page = conn
            .schema
            .borrow()
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case("t"))
            .map(|table| table.root_page)
            .expect("table t should exist in schema");
        let memdb_row_count = conn
            .db
            .borrow()
            .get_table(root_page)
            .expect("table t should exist in MemDatabase")
            .iter_rows()
            .count();
        assert_eq!(
            memdb_row_count, 0,
            "schema-only file-backed reload should avoid copying user rows into MemDatabase"
        );

        let count_rows = conn.query("SELECT COUNT(*) FROM t;").unwrap();
        assert_eq!(
            count_rows[0].values()[0],
            SqliteValue::Integer(2),
            "COUNT(*) must read pager-backed storage even when the MemDatabase mirror is schema-only"
        );

        let rows = conn.query("SELECT val FROM t ORDER BY id;").unwrap();
        assert_eq!(
            rows.len(),
            2,
            "pager-backed reads should still see both rows"
        );
        assert_eq!(rows[0].values(), &[SqliteValue::Text("hello".into())]);
        assert_eq!(rows[1].values(), &[SqliteValue::Text("world".into())]);
    }

    #[test]
    fn schema_only_reload_skips_sqlite_master_rescan_when_only_row_mirror_is_dirty() {
        let _profile_guard = StatementReuseHotPathProfileGuard::new();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("schema_only_dirty_row_mirror.db");
        let path_str = path.to_str().unwrap();

        let conn = Connection::open(path_str).unwrap();
        conn.set_reject_mem_fallback(true);
        conn.set_strict_mem_fallback_rejection(true);
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, val TEXT);")
            .unwrap();
        conn.execute("INSERT INTO t VALUES (1, 'hello');").unwrap();

        let cx = conn.op_cx().unwrap();
        conn.reload_memdb_from_pager_with_mode(&cx, false).unwrap();
        let schema_cookie = conn.schema_cookie();

        conn.memdb_rows_loaded.set(false);
        conn.memdb_storage_count_shortcuts_safe.set(false);
        conn.memdb_requires_active_txn_reload.set(true);

        reset_hot_path_profile();
        conn.reload_memdb_from_pager_with_mode(&cx, false).unwrap();
        let profile = hot_path_profile_snapshot();

        assert_eq!(
            conn.schema_cookie(),
            schema_cookie,
            "test setup should keep the schema cookie unchanged"
        );
        assert!(
            !conn.memdb_requires_active_txn_reload.get(),
            "schema-only reload should consume a dirty row-mirror marker without forcing a sqlite_master rescan"
        );
        assert!(
            !conn.memdb_rows_loaded.get(),
            "schema-only fast path must not claim that rows were hydrated"
        );
        assert!(
            !conn.memdb_storage_count_shortcuts_safe.get(),
            "schema-only fast path must keep MemDatabase count shortcuts disabled"
        );
        assert_eq!(
            profile
                .record_decode
                .callsite_breakdown
                .core_connection
                .parse_record_calls,
            0,
            "schema-only dirty-row refresh should stay on the unchanged-schema fast path: {profile:?}"
        );
    }

