    #[test]
    fn test_attach_memory_database_inherits_parent_memory_vfs_config() {
        let config = MemoryVfsConfig {
            initial_reserve_bytes: 16 * 1024,
            growth_chunk_bytes: 32 * 1024,
            max_bytes: Some(256 * 1024),
        };
        let mut env = ConnectionEnv::default();
        env.set_memory_vfs_config(config);

        let conn = Connection::open_with_env(":memory:", env).unwrap();
        conn.execute("ATTACH DATABASE ':memory:' AS aux;").unwrap();

        let attached_stats = conn
            .with_attached_connection("aux", |attached| attached.memory_stats())
            .unwrap();
        let snapshot = attached_stats
            .memory_vfs
            .expect("attached :memory: database should expose MemoryVfs stats");
        assert_eq!(snapshot.initial_reserve_bytes, config.initial_reserve_bytes);
        assert_eq!(snapshot.growth_chunk_bytes, config.growth_chunk_bytes);
        assert_eq!(snapshot.max_bytes, config.max_bytes);
    }

    #[test]
    fn test_select_from_attached_schema_reads_attached_database() {
        let dir = tempfile::tempdir().unwrap();
        let aux_path = dir.path().join("aux.db");
        let aux_path_sql = aux_path.to_string_lossy().replace('\'', "''");
        let aux_path_str = aux_path.to_string_lossy().into_owned();

        let aux = Connection::open(&aux_path_str).unwrap();
        aux.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, value TEXT);")
            .unwrap();
        aux.execute("INSERT INTO t VALUES (1, 'alpha');").unwrap();
        aux.execute("INSERT INTO t VALUES (2, 'beta');").unwrap();
        drop(aux);

        let conn = Connection::open(":memory:").unwrap();
        conn.execute(&format!("ATTACH DATABASE '{aux_path_sql}' AS aux;"))
            .unwrap();

        let rows = conn.query("SELECT value FROM aux.t ORDER BY id;").unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values()[0].clone())
                .collect::<Vec<_>>(),
            vec![
                SqliteValue::Text("alpha".into()),
                SqliteValue::Text("beta".into()),
            ]
        );

        let stmt = conn
            .prepare("SELECT value FROM aux.t ORDER BY id;")
            .unwrap();
        let prepared_rows = stmt.query().unwrap();
        assert_eq!(
            prepared_rows
                .iter()
                .map(|row| row.values()[0].clone())
                .collect::<Vec<_>>(),
            vec![
                SqliteValue::Text("alpha".into()),
                SqliteValue::Text("beta".into()),
            ]
        );
    }

    #[test]
    fn test_prepare_select_from_attached_schema_uses_deferred_dispatch() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, value TEXT);")
            .unwrap();
        conn.execute("ATTACH DATABASE ':memory:' AS aux;").unwrap();
        conn.execute("CREATE TABLE aux.t (id INTEGER PRIMARY KEY, value TEXT);")
            .unwrap();
        conn.execute("INSERT INTO t VALUES (1, 'main-row');")
            .unwrap();
        conn.execute("INSERT INTO aux.t VALUES (1, 'aux-row');")
            .unwrap();

        let stmt = conn
            .prepare("SELECT value FROM aux.t ORDER BY id;")
            .unwrap();
        assert!(
            stmt.deferred_query_statement.is_some(),
            "attached-schema SELECT should defer execution so the schema prefix routes to the attached connection"
        );
        assert!(
            stmt.db.is_none(),
            "attached-schema SELECT should not prebind the main MemDatabase"
        );

        let rows = stmt.query().unwrap();
        assert_eq!(
            rows.iter()
                .map(|row| row.values()[0].clone())
                .collect::<Vec<_>>(),
            vec![SqliteValue::Text("aux-row".into())]
        );
    }

    #[test]
    fn test_create_index_on_attached_schema_delegates_to_attached_database() -> Result<()> {
        let conn = Connection::open(":memory:")?;
        conn.execute("ATTACH DATABASE ':memory:' AS aux;")?;
        conn.execute("CREATE TABLE aux.t (id INTEGER PRIMARY KEY, value TEXT);")?;
        conn.execute("INSERT INTO aux.t VALUES (1, 'beta'), (2, 'alpha');")?;

        conn.execute("CREATE INDEX aux.idx_t_value ON t(value);")?;

        let index_rows = conn.query(
            "SELECT name
             FROM aux.sqlite_master
             WHERE type = 'index' AND name = 'idx_t_value';",
        )?;
        if index_rows.len() != 1
            || index_rows[0].values()[0] != SqliteValue::Text("idx_t_value".into())
        {
            return Err(FrankenError::Internal(format!(
                "expected one aux.sqlite_master row for idx_t_value, got {index_rows:?}"
            )));
        }

        let rows =
            conn.query("SELECT id, value FROM aux.t WHERE value >= 'alpha' ORDER BY value;")?;
        let actual = rows
            .iter()
            .map(|row| row.values().to_vec())
            .collect::<Vec<_>>();
        let expected = vec![
            vec![SqliteValue::Integer(2), SqliteValue::Text("alpha".into())],
            vec![SqliteValue::Integer(1), SqliteValue::Text("beta".into())],
        ];
        if actual != expected {
            return Err(FrankenError::Internal(format!(
                "expected attached index query rows {expected:?}, got {actual:?}"
            )));
        }
        Ok(())
    }

    #[test]
    fn test_unique_create_index_on_attached_schema_validates_existing_rows() -> Result<()> {
        let conn = Connection::open(":memory:")?;
        conn.execute("ATTACH DATABASE ':memory:' AS aux;")?;
        conn.execute("CREATE TABLE aux.t (id INTEGER PRIMARY KEY, value TEXT);")?;
        conn.execute("INSERT INTO aux.t VALUES (1, 'dup'), (2, 'dup');")?;

        let Err(err) = conn.execute("CREATE UNIQUE INDEX aux.idx_t_value ON t(value);") else {
            return Err(FrankenError::Internal(
                "attached unique-index backfill accepted duplicate keys".into(),
            ));
        };
        let err_text = err.to_string();
        if !(matches!(&err, FrankenError::UniqueViolation { .. })
            || err_text.contains("UNIQUE constraint failed")
            || err_text.contains("secondary-index conflict"))
        {
            return Err(FrankenError::Internal(format!(
                "expected unique violation from attached CREATE UNIQUE INDEX, got {err}"
            )));
        }

        let rows = conn.query(
            "SELECT name
             FROM aux.sqlite_master
             WHERE type = 'index' AND name = 'idx_t_value';",
        )?;
        if !rows.is_empty() {
            return Err(FrankenError::Internal(format!(
                "failed attached CREATE UNIQUE INDEX persisted sqlite_master rows: {rows:?}"
            )));
        }
        Ok(())
    }

