    #[test]
    fn test_prepared_change_tracking_simple_point_read_skips_sync() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, v INTEGER);")
            .unwrap();
        conn.execute("INSERT INTO t(v) VALUES(10);").unwrap();

        let stmt = conn.prepare("SELECT v FROM t WHERE id = ?1;").unwrap();
        assert!(
            !stmt.may_observe_change_tracking,
            "simple point reads should not force change-tracking sync"
        );

        let sentinel = ChangeTrackingState {
            last_insert_rowid: -71,
            last_changes: -72,
            total_changes: -73,
        };
        set_change_tracking_state(sentinel);

        let rows = stmt
            .query_with_params(&[SqliteValue::Integer(1)])
            .expect("prepared point read should execute");
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(10));
        assert_eq!(
            get_change_tracking_state(),
            sentinel,
            "point reads without change-tracking functions must not mutate the TLS state"
        );
    }

