    #[test]
    fn test_failed_pending_direct_update_leaf_patch_run_flush_preserves_buffer() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute(
            "CREATE TABLE bench (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .unwrap();
        conn.execute("INSERT INTO bench VALUES (1, 'user_1', 1.5);")
            .unwrap();
        let update = conn
            .prepare("UPDATE bench SET value = ?2 WHERE id = ?1;")
            .unwrap();

        conn.execute("BEGIN;").unwrap();
        conn.execute_prepared_with_params(
            &update,
            &[SqliteValue::Integer(1), SqliteValue::Float(42.5)],
        )
        .expect("prepared update should execute");
        assert!(conn.pending_direct_update_leaf_patch_run.borrow().is_some());

        let cancelled = Cx::new();
        cancelled.transition_to_running();
        cancelled.cancel_with_reason(CancelReason::UserInterrupt);
        assert!(
            conn.flush_pending_direct_update_leaf_patch_run(&cancelled)
                .is_err(),
            "cancelled flush should report an error"
        );
        assert!(
            conn.pending_direct_update_leaf_patch_run.borrow().is_some(),
            "failed flush must preserve the buffered update"
        );

        conn.execute("COMMIT;").unwrap();
        let row = conn
            .query_row("SELECT value FROM bench WHERE id = 1;")
            .expect("committed patched row should be readable");
        assert_eq!(row.values()[0], SqliteValue::Float(42.5));
    }

