    /// Regression test for issue #31: multi-level FK CASCADE propagation.
    ///
    /// Deleting a grandparent row should cascade through parent to child via
    /// ON DELETE CASCADE at each level.
    #[test]
    fn test_issue31_multi_level_fk_cascade_propagation() {
        let conn = Connection::open(":memory:").unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").unwrap();

        conn.execute("CREATE TABLE grandparent (id INTEGER PRIMARY KEY, name TEXT);")
            .unwrap();
        conn.execute(
            "CREATE TABLE parent (
                id INTEGER PRIMARY KEY,
                gp_id INTEGER REFERENCES grandparent(id) ON DELETE CASCADE,
                name TEXT
            );",
        )
        .unwrap();
        conn.execute(
            "CREATE TABLE child (
                id INTEGER PRIMARY KEY,
                p_id INTEGER REFERENCES parent(id) ON DELETE CASCADE,
                name TEXT
            );",
        )
        .unwrap();

        conn.execute("INSERT INTO grandparent VALUES (1, 'GP1'), (2, 'GP2');")
            .unwrap();
        conn.execute("INSERT INTO parent VALUES (1, 1, 'P1'), (2, 1, 'P2'), (3, 2, 'P3');")
            .unwrap();
        conn.execute(
            "INSERT INTO child VALUES (1, 1, 'C1'), (2, 1, 'C2'), (3, 2, 'C3'), (4, 3, 'C4');",
        )
        .unwrap();

        // Delete GP1: should cascade to P1, P2, then to C1, C2, C3.
        conn.execute("DELETE FROM grandparent WHERE id = 1;")
            .unwrap();

        // Only GP2 survives.
        let rows = conn.query("SELECT COUNT(*) FROM grandparent;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));

        // Only P3 (referencing GP2) survives.
        let rows = conn.query("SELECT COUNT(*) FROM parent;").unwrap();
        assert_eq!(
            rows[0].values()[0],
            SqliteValue::Integer(1),
            "parent rows not cascaded correctly"
        );

        // Only C4 (referencing P3) survives.
        let rows = conn.query("SELECT COUNT(*) FROM child;").unwrap();
        assert_eq!(
            rows[0].values()[0],
            SqliteValue::Integer(1),
            "multi-level FK CASCADE did not propagate from grandparent to child"
        );

        // Verify the surviving rows are the correct ones.
        let rows = conn.query("SELECT id FROM grandparent;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(2));
        let rows = conn.query("SELECT id FROM parent;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(3));
        let rows = conn.query("SELECT id FROM child;").unwrap();
        assert_eq!(rows[0].values()[0], SqliteValue::Integer(4));
    }

    /// Regression test for issue #59: INSERT-time FK validation returns wrong
    /// results after prepared statement reuse in a write transaction.
    ///
    /// The root cause is that `check_fk_parent_exists()` runs
    /// `SELECT 1 FROM parent WHERE id = ?1` via `query_with_params()`,
    /// which takes the prepared-statement reuse path. When the FK check
    /// query is routed through the ad-hoc prepared reuse path and
    /// `prepare_connection_for_prepared_read` triggers a full memdb reload
    /// from the active transaction, the reload consumes the transaction
    /// handle temporarily. If the schema reload path fails to find rows
    /// because the memdb was not hydrated (file-backed DB with
    /// `reject_mem_fallback=true`), the subsequent VDBE execution must
    /// fall through to storage cursors backed by the pager — which should
    /// always see the current transaction state.
    ///
    /// This test exercises the exact `br dep add` flow:
    /// 1. Validate IDs via SELECT
    /// 2. BFS cycle check with prepared UNION statement reused N times
    /// 3. INSERT OR IGNORE into child table
    /// 4. UPDATE parent table
    /// 5. INSERT into another child table (FK to parent) — must NOT fail
    #[test]
    fn test_issue59_fk_check_after_prepared_stmt_reuse_in_write_txn() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("issue59.db");
        let db_str = db_path.to_string_lossy().to_string();

        // Phase 1: set up schema and seed data
        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();

            conn.execute(
                "CREATE TABLE issues (
                    id TEXT PRIMARY KEY,
                    title TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'open',
                    updated_at TEXT
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE dependencies (
                    issue_id TEXT NOT NULL,
                    depends_on_id TEXT NOT NULL,
                    type TEXT NOT NULL DEFAULT 'blocks',
                    created_by TEXT,
                    PRIMARY KEY (issue_id, depends_on_id),
                    FOREIGN KEY (issue_id) REFERENCES issues(id) ON DELETE CASCADE
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    issue_id TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    created_at TEXT,
                    FOREIGN KEY (issue_id) REFERENCES issues(id) ON DELETE CASCADE
                );",
            )
            .unwrap();

            // Seed multiple issues to create a dependency graph
            for i in 1..=10 {
                conn.execute(&format!(
                    "INSERT INTO issues (id, title) VALUES ('hr-gcvk.{i}', 'Issue {i}');"
                ))
                .unwrap();
            }
            // Create pre-existing dependencies to make BFS non-trivial
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.2', 'hr-gcvk.1', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.3', 'hr-gcvk.2', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.4', 'hr-gcvk.3', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.5', 'hr-gcvk.4', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.6', 'hr-gcvk.5', 'blocks');",
            )
            .unwrap();
            // Give node 7 some existing deps so BFS from 7 traverses the graph
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.7', 'hr-gcvk.6', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.8', 'hr-gcvk.7', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.9', 'hr-gcvk.8', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "INSERT INTO dependencies (issue_id, depends_on_id, type)
                 VALUES ('hr-gcvk.10', 'hr-gcvk.9', 'blocks');",
            )
            .unwrap();
        }

        // Phase 2: reproduce the bug — reopen and run the transaction pattern
        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();

            let issue_id = "hr-gcvk.7";
            let depends_on_id = "hr-gcvk.2";

            conn.execute("BEGIN IMMEDIATE;").unwrap();

            // Step 1: Validate issue_id exists
            let rows = conn
                .query_with_params(
                    "SELECT status FROM issues WHERE id = ?1",
                    &[SqliteValue::Text(issue_id.into())],
                )
                .unwrap();
            assert!(!rows.is_empty(), "issue_id should exist: {issue_id}");

            // Step 2: Validate depends_on_id exists
            let rows = conn
                .query_with_params(
                    "SELECT status FROM issues WHERE id = ?1",
                    &[SqliteValue::Text(depends_on_id.into())],
                )
                .unwrap();
            assert!(
                !rows.is_empty(),
                "depends_on_id should exist: {depends_on_id}"
            );

            // Step 3: BFS cycle check — prepare a UNION query and reuse it N times
            let bfs_stmt = conn
                .prepare(
                    "SELECT depends_on_id FROM dependencies WHERE issue_id = ?1 AND type IN ('blocks', 'parent-child')
                     UNION
                     SELECT issue_id FROM dependencies WHERE depends_on_id = ?1 AND type = 'parent-child'",
                )
                .unwrap();

            let mut visited = std::collections::HashSet::new();
            let mut queue = std::collections::VecDeque::new();
            queue.push_back(issue_id.to_string());
            visited.insert(issue_id.to_string());

            while let Some(current) = queue.pop_front() {
                let neighbors = bfs_stmt
                    .query_with_params(&[SqliteValue::Text(current.clone().into())])
                    .unwrap();
                for row in &neighbors {
                    if let SqliteValue::Text(neighbor) = &row.values()[0] {
                        if visited.insert(neighbor.to_string()) {
                            queue.push_back(neighbor.to_string());
                        }
                    }
                }
            }
            drop(bfs_stmt);

            // Step 4: Check existing dep
            let rows = conn
                .query_with_params(
                    "SELECT 1 FROM dependencies WHERE issue_id = ?1 AND depends_on_id = ?2",
                    &[
                        SqliteValue::Text(issue_id.into()),
                        SqliteValue::Text(depends_on_id.into()),
                    ],
                )
                .unwrap();
            assert!(rows.is_empty(), "dependency should not exist yet");

            // Step 5: INSERT OR IGNORE into dependencies
            conn.execute(&format!(
                "INSERT OR IGNORE INTO dependencies (issue_id, depends_on_id, type, created_by) VALUES ('{issue_id}', '{depends_on_id}', 'blocks', 'test');"
            ))
            .unwrap();

            // Step 6: UPDATE issues
            conn.execute(&format!(
                "UPDATE issues SET updated_at = '2026-04-03T00:00:00Z' WHERE id = '{issue_id}';"
            ))
            .unwrap();

            // Step 7: INSERT into events — FK check must find the parent row
            let result = conn.execute(&format!(
                "INSERT INTO events (issue_id, event_type, created_at) VALUES ('{issue_id}', 'dep_added', '2026-04-03T00:00:00Z');"
            ));
            assert!(
                result.is_ok(),
                "INSERT into events should succeed — FK check should find the parent row. Got error: {:?}",
                result.err()
            );

            conn.execute("COMMIT;").unwrap();
        }
    }

    /// Variant of issue #59 test: more BFS iterations to stress cursor/cache state.
    #[test]
    fn test_issue59_fk_check_after_many_prepared_stmt_iterations() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("issue59_many.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();

            conn.execute(
                "CREATE TABLE issues (
                    id TEXT PRIMARY KEY,
                    title TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'open',
                    updated_at TEXT
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE dependencies (
                    issue_id TEXT NOT NULL,
                    depends_on_id TEXT NOT NULL,
                    type TEXT NOT NULL DEFAULT 'blocks',
                    PRIMARY KEY (issue_id, depends_on_id),
                    FOREIGN KEY (issue_id) REFERENCES issues(id) ON DELETE CASCADE
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    issue_id TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    FOREIGN KEY (issue_id) REFERENCES issues(id) ON DELETE CASCADE
                );",
            )
            .unwrap();

            // Create a large graph to force many BFS iterations
            for i in 1..=50 {
                conn.execute(&format!(
                    "INSERT INTO issues (id, title) VALUES ('node-{i}', 'Node {i}');"
                ))
                .unwrap();
            }
            // Create a long chain: 1->2->3->...->40
            for i in 1..40 {
                conn.execute(&format!(
                    "INSERT INTO dependencies (issue_id, depends_on_id, type) VALUES ('node-{}', 'node-{i}', 'blocks');",
                    i + 1
                ))
                .unwrap();
            }
        }

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();
            conn.execute("BEGIN IMMEDIATE;").unwrap();

            // Prepare and reuse the BFS query many times
            let bfs_stmt = conn
                .prepare(
                    "SELECT depends_on_id FROM dependencies WHERE issue_id = ?1
                     UNION
                     SELECT issue_id FROM dependencies WHERE depends_on_id = ?1",
                )
                .unwrap();

            let mut visited = std::collections::HashSet::new();
            let mut queue = std::collections::VecDeque::new();
            queue.push_back("node-45".to_string());
            visited.insert("node-45".to_string());

            while let Some(current) = queue.pop_front() {
                let neighbors = bfs_stmt
                    .query_with_params(&[SqliteValue::Text(current.clone().into())])
                    .unwrap();
                for row in &neighbors {
                    if let SqliteValue::Text(neighbor) = &row.values()[0] {
                        if visited.insert(neighbor.to_string()) {
                            queue.push_back(neighbor.to_string());
                        }
                    }
                }
            }
            drop(bfs_stmt);

            // Now do DML and FK check
            conn.execute(
                "INSERT OR IGNORE INTO dependencies (issue_id, depends_on_id, type) VALUES ('node-45', 'node-1', 'blocks');",
            )
            .unwrap();
            conn.execute(
                "UPDATE issues SET updated_at = '2026-04-03T00:00:00Z' WHERE id = 'node-45';",
            )
            .unwrap();

            // This must succeed — FK check must find 'node-45' in issues
            let result = conn.execute(
                "INSERT INTO events (issue_id, event_type) VALUES ('node-45', 'dep_added');",
            );
            assert!(
                result.is_ok(),
                "INSERT into events should succeed after many BFS iterations. Got error: {:?}",
                result.err()
            );

            conn.execute("COMMIT;").unwrap();
        }
    }

    /// Issue #59 variant: FK check on insert into child table should always
    /// see parent rows that were present before the transaction began, even
    /// after in-transaction writes dirty the memdb and force reloads.
    /// Tests the critical `check_fk_parent_exists` -> `query_with_params`
    /// -> prepared-reuse path specifically.
    #[test]
    fn test_issue59_direct_fk_check_query_sees_parent_after_dml() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("issue59_direct.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();
            conn.execute("CREATE TABLE parent (id TEXT PRIMARY KEY, val TEXT);")
                .unwrap();
            conn.execute(
                "CREATE TABLE child (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    parent_id TEXT NOT NULL,
                    FOREIGN KEY (parent_id) REFERENCES parent(id)
                );",
            )
            .unwrap();
            conn.execute(
                "CREATE TABLE other (
                    id TEXT PRIMARY KEY,
                    ref_id TEXT,
                    FOREIGN KEY (ref_id) REFERENCES parent(id)
                );",
            )
            .unwrap();
            conn.execute("INSERT INTO parent VALUES ('p1', 'v1'), ('p2', 'v2'), ('p3', 'v3');")
                .unwrap();
        }

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();
            conn.execute("BEGIN IMMEDIATE;").unwrap();

            // Prepare a statement and execute it many times to populate
            // the prepared statement cache and VDBE engine state.
            let stmt = conn
                .prepare("SELECT id FROM parent WHERE id = ?1 UNION SELECT val FROM parent WHERE id = ?1")
                .unwrap();
            for _ in 0..20 {
                let _ = stmt
                    .query_with_params(&[SqliteValue::Text("p1".into())])
                    .unwrap();
                let _ = stmt
                    .query_with_params(&[SqliteValue::Text("p2".into())])
                    .unwrap();
                let _ = stmt
                    .query_with_params(&[SqliteValue::Text("p3".into())])
                    .unwrap();
            }
            drop(stmt);

            // Write operations that dirty the memdb
            conn.execute("INSERT OR IGNORE INTO other VALUES ('o1', 'p1');")
                .unwrap();
            conn.execute("UPDATE parent SET val = 'updated' WHERE id = 'p1';")
                .unwrap();

            // Now verify the FK check path explicitly: query_with_params
            // on the exact SQL that check_fk_parent_exists would generate.
            let rows = conn
                .query_with_params(
                    "SELECT 1 FROM \"parent\" WHERE \"id\" = ?1 LIMIT 1",
                    &[SqliteValue::Text("p1".into())],
                )
                .unwrap();
            assert!(
                !rows.is_empty(),
                "FK validation query must find parent row 'p1' after DML"
            );

            // And the actual INSERT that triggers check_fk_parent_exists
            let result = conn.execute("INSERT INTO child (parent_id) VALUES ('p1');");
            assert!(
                result.is_ok(),
                "INSERT into child should succeed. Got error: {:?}",
                result.err()
            );

            conn.execute("COMMIT;").unwrap();
        }
    }

    #[test]
    #[ignore = "manual perf probe for file-backed connection-open schema reload"]
    fn manual_perf_probe_connection_open_schema_reload_many_tables() {
        const TABLES: usize = 32;
        const DEFAULT_ITERATIONS: usize = 120;

        let iterations = std::env::var("FSQLITE_SCHEMA_REOPEN_ITERS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(DEFAULT_ITERATIONS);

        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("schema_reopen_many_tables.db");
        let db_str = db_path.to_string_lossy().to_string();

        {
            let conn = Connection::open(&db_str).unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").unwrap();
            for table_index in 0..TABLES {
                let table = format!("item_{table_index}");
                conn.execute(&format!(
                    "CREATE TABLE {table} (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        tenant_id TEXT NOT NULL,
                        parent_id INTEGER REFERENCES {table}(id) ON DELETE SET NULL,
                        name TEXT NOT NULL COLLATE NOCASE UNIQUE,
                        sort_key INTEGER NOT NULL DEFAULT 0 CHECK(sort_key >= 0),
                        body TEXT,
                        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        updated_at TEXT,
                        UNIQUE(tenant_id, sort_key),
                        CHECK(length(name) > 0)
                    ) STRICT;"
                ))
                .unwrap();
                conn.execute(&format!(
                    "CREATE INDEX {table}_tenant_sort_idx ON {table}(tenant_id, sort_key);"
                ))
                .unwrap();
            }
        }

        let mut samples_us = Vec::with_capacity(iterations);
        let total_start = std::time::Instant::now();
        for _ in 0..iterations {
            let start = std::time::Instant::now();
            let conn = Connection::open(&db_str).unwrap();
            let rows = conn.query("SELECT COUNT(*) FROM item_0;").unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(0));
            samples_us.push(start.elapsed().as_micros());
        }
        let total = total_start.elapsed();
        samples_us.sort_unstable();
        let p50 = samples_us[samples_us.len() / 2];
        let p95_index = (samples_us.len() * 95 / 100).min(samples_us.len() - 1);
        let p95 = samples_us[p95_index];
        println!(
            "manual_perf_probe.connection_open_schema_reload tables={TABLES} iterations={iterations} total_ms={} p50_us={p50} p95_us={p95}",
            total.as_millis()
        );
    }

